########################################################
# pglDatabase
########################################################
class pglDatabase:
    """Coordinate PostgreSQL-backed scientific checkpoints.

    Main entry points:
        loadSession(), saveSession(), saveRawSession().
        loadDataset(), saveDataset().
        Session/dataset reporting and lifecycle operations.

    Responsibilities:
        Resolve database configuration and registered payload locations.
        Publish and restore session and dataset checkpoints.
        Validate lineage, history boundaries, manifests, and catalog links.
        Coordinate soft deletion and source dependency protection.
        Initialize and migrate the scientific schema.

    Dependencies:
        pglPostgres owns SQL connections, SSH tunnels, and local server setup.
        pglStorage owns standalone matrix persistence, hashing, verified file
        copies, and general scientific-save validation.

    Transaction ownership:
        Public save/lifecycle methods own their connections and transactions.
        Advanced APIs generally use caller-owned connections; their docstrings
        specify publication and commit responsibility.

    Filesystem writes are not rolled back by PostgreSQL. Failed saves may
    leave unregistered files, but publication must not be reported before
    successful commit and connection cleanup.

    Checkpoint manifests and pglCheckpointFilesystem belong here because
    they implement the database checkpoint representation, even when an
    individual helper performs no SQL.

    Existing method docstrings describe return conventions and limitations.
    Structural and provenance checks do not establish scientific validity.
    """

    # -------------------------------------------------------------------------
    # Shared constants
    # -------------------------------------------------------------------------
    MIGRATION_LOCK = 734_291_806_115

    # =========================================================================
    # PUBLIC API
    # =========================================================================

    # -------------------------------------------------------------------------
    # Settings
    # -------------------------------------------------------------------------
    @classmethod
    def settings(cls):
        """
        Edit database settings using the standard settings dialog.
        """
        settingsList = cls.getSettings(returnSettingsList=True)

        original = pglDatabaseSettingsList(settingsList)

        modified = pglDialogs.traitsDialog(original)

        cls._saveModifiedSettings(modified, original)

    @classmethod
    def getSettingsDir(cls):
        """
        Return the directory containing local database-settings profiles.
        """
        pglDir = pglSettingsManager.getPGLSettingsDir()
        if pglDir is None:
            raise OSError("Could not resolve the PGL settings directory.")

        settingsDir = pglDir / "databaseSettings"
        settingsDir.mkdir(parents=True, exist_ok=True)
        return settingsDir

    @classmethod
    def getSettings(cls, settingsName=None, settings=None, returnSettingsList=False):
        """
        Load database settings.

        Explicit settings supersede settingsName.
        With neither, return the default settings.
        returnSettingsList=True ignores other arguments and returns all
        settings, with the default first.
        """
        if returnSettingsList:
            settings = None
            settingsName = None

        if settings is not None:
            if not isinstance(settings, pglDatabaseSettings):
                pglMessages.warning("Settings must be pglDatabaseSettings.")
                return None
            return settings

        settingsDir = cls.getSettingsDir()

        if settingsName is not None:
            filename = pglStorage.makeValidFilename(settingsName)
            settingsPath = settingsDir / f"{filename}.json"

            if not settingsPath.is_file():
                pglMessages.warning(f"Database settings file '{settingsPath}' not found.")
                return None

            return pglDatabaseSettings.load(filename=settingsPath)

        settingsList = []
        for filename in sorted(settingsDir.glob("*.json")):
            loaded = pglDatabaseSettings.load(filename=filename)
            if not isinstance(loaded, pglDatabaseSettings):
                raise ValueError(f"Invalid database settings file: {filename}")
            settingsList.append(loaded)

        if not settingsList:
            pglMessages.message("No saved database settings found, creating default settings.")
            settings = pglDatabaseSettings()
            settings.isDefault = True
            settings.save()
            settingsList = [settings]
        else:
            defaults = [s for s in settingsList if s.isDefault]

            if defaults:
                settings = defaults[0]

                if len(defaults) > 1:
                    pglMessages.warning(
                        f"Found {len(defaults)} default database settings, keeping only the first."
                    )
                    for other in defaults[1:]:
                        other.isDefault = False
                        other.save()
            else:
                settings = settingsList[0]
                settings.isDefault = True
                settings.save()
                pglMessages.message(
                    f"No default database settings found, using: {settings.name}."
                )

            # Move the default to the front.
            settingsList.remove(settings)
            settingsList.insert(0, settings)

        if returnSettingsList:
            return settingsList

        return settingsList[0]
    
    @classmethod
    def inspectPostgres(cls, *, settings=None, settingsName=None, user=None, sslRootCert=None):
        """Display and return other sessions in the configured PostgreSQL database.

        Uses pglPostgres for configuration, authentication, and direct/SSH access.
        Does not cancel queries, terminate sessions, or change database data.

        Returns:
            List of activity dictionaries, or None if configuration is
            unavailable or connection authentication is cancelled.

        Visibility into other roles' sessions depends on database permissions.
        """
        from pprint import pformat

        from .pglPostgres import pglPostgres

        postgres = pglPostgres.fromSettings(settings=settings, settingsName=settingsName)

        if postgres is None:
            return None

        activity = postgres.inspectDatabaseActivity(user=user, sslRootCert=sslRootCert)

        if activity is None:
            return None

        if not activity:
            pglMessages.message("No other sessions are currently connected to this database.")
            return activity

        for entry in activity:
            pglMessages.message(pformat(entry, sort_dicts=False), wrapText=False)

        return activity
    
    @classmethod
    def inspectPostgresLocks(cls, *, settings=None, settingsName=None, sslRootCert=None, verbose=False, returnRecords=False):
        """Display lock-related sessions and remember their connection identity.

        Default:
            One line per session, with PID, database owner, client identity,
            state/ages, advisory-lock count, and blocking PIDs.

        verbose=True:
            Also display the complete diagnostic dictionaries.

        returnRecords=True:
            Return the records for programmatic use. Otherwise return None
            to avoid duplicate notebook output.

        Displayed PID/backend-start pairs are remembered in this Python
        process, scoped to the configured database, for safe recovery using
        terminatePostgresLock(pid).

        Diagnostic information does not establish abandonment. A database-idle
        session may still be uploading or verifying payloads.

        Does not terminate sessions or modify database data.
        """
        from pprint import pformat

        from .pglPostgres import pglPostgres

        if type(verbose) is not bool or type(returnRecords) is not bool:
            raise ValueError("verbose and returnRecords must be booleans.")

        postgres = pglPostgres.fromSettings(settings=settings, settingsName=settingsName)

        if postgres is None:
            return None

        records = postgres.inspectLocks(sslRootCert=sslRootCert)

        if records is None:
            return None

        databaseKey = json.dumps(cls._checkpointDatabaseIdentity(postgres), sort_keys=True)
        snapshots = dict(getattr(cls, "_postgresLockSnapshots", {}))

        # Replace this database's snapshot, preserving other database entries.
        snapshots = {key: value for key, value in snapshots.items() if key[0] != databaseKey}

        for record in records:
            snapshots[(databaseKey, record["pid"])] = dict(record)

        cls._postgresLockSnapshots = snapshots

        #pglMessages.message(f"PostgreSQL locks: {postgres.databaseName}.{postgres.databaseSchema}", wrapText=False)

        if not records:
            pglMessages.message("No advisory-lock holders or blocked sessions found.")
        else:
            for record in records:
                pglMessages.message(cls._formatPostgresLock(record), wrapText=False)

                if verbose:
                    pglMessages.message(pformat(record, sort_dicts=False), wrapText=False)

            pglMessages.message("Idle does not mean abandoned. Confirm ownership before terminating; recovery uses terminatePostgresLock(PID).", wrapText=False)

        return records if returnRecords else None
    
    @classmethod
    def terminatePostgresLock(cls, pid, *, settings=None, settingsName=None, sslRootCert=None):
        """Administratively terminate a previously inspected abandoned owner.

        Requires only the displayed PID. The connection start time is retrieved
        from this process's latest inspection of the same configured database.

        Refuses targets that have not been inspected in this Python process.
        The underlying pglPostgres method rechecks connection identity, requires
        administrator authentication and confirmation, and refuses owners with
        queued followers.

        Does not remove payload files or retry saves.
        """
        from .pglPostgres import pglPostgres

        if type(pid) is not int or pid <= 0:
            raise ValueError("pid must be a positive integer.")

        postgres = pglPostgres.fromSettings(settings=settings, settingsName=settingsName)

        if postgres is None:
            return None

        databaseKey = json.dumps(cls._checkpointDatabaseIdentity(postgres), sort_keys=True)
        snapshotKey = (databaseKey, pid)
        snapshots = getattr(cls, "_postgresLockSnapshots", {})
        owner = snapshots.get(snapshotKey)

        if owner is None:
            pglMessages.warning(f"PID {pid} has not been inspected in this Python process for this database. Run pglDatabase.inspectPostgresLocks() with the same settings first, then retry.", level=1)
            return False

        if not owner.get("heldAdvisoryLocks"):
            pglMessages.warning(f"PID {pid} was not an advisory-lock holder in the last inspection. Inspect again; this operation is for confirmed abandoned lock owners.", level=1)
            return False

        pglMessages.message(f"Selected: {cls._formatPostgresLock(owner)}", wrapText=False)

        try:
            result = postgres.terminateLockOwner(pid, owner["backendStart"], sslRootCert=sslRootCert)

        except psycopg.errors.InsufficientPrivilege:
            pglMessages.warning("PostgreSQL refused termination. The configured administrator account lacks permission to terminate this backend. No automatic privilege changes were attempted.", level=2)
            return False

        except (psycopg.OperationalError, psycopg.InterfaceError, ConnectionError, TimeoutError):
            pglMessages.warning("The administrator connection failed. Termination may not have completed; restore connectivity and inspect PostgreSQL activity before retrying.", level=2)
            return None

        if result:
            snapshots.pop(snapshotKey, None)

        return result
    
    @staticmethod
    def _formatPostgresLock(record):
        """Format one diagnostic record without exposing full SQL by default."""

        def formatAge(value):
            if value is None:
                return "-"

            seconds = max(0, int(value.total_seconds()))

            if seconds < 60:
                return f"{seconds}s"

            if seconds < 3600:
                return f"{seconds // 60}m{seconds % 60:02d}s"

            return f"{seconds // 3600}h{seconds % 3600 // 60:02d}m"

        def singleLine(value):
            return " ".join(str(value).split())

        pid = record["pid"]
        owner = singleLine(record.get("databaseUser") or "unknown")
        client = singleLine(record.get("clientIdentity") or "client unidentified")
        state = singleLine(record.get("state") or "unknown")
        stateAge = formatAge(record.get("stateAge"))
        connectionAge = formatAge(record.get("connectionAge"))
        transactionAge = formatAge(record.get("transactionAge"))
        heldLocks = record.get("heldAdvisoryLocks", 0)
        blockingPIDs = record.get("blockingPIDs") or []
        blockers = ",".join(str(value) for value in blockingPIDs) or "none"
        waitType = record.get("waitType")
        waitEvent = record.get("waitEvent")
        waitLabel = f" | wait: {singleLine(waitType)}/{singleLine(waitEvent)}" if waitType else ""

        return f"PID {pid} | {owner} | {client} | {state} {stateAge} | connected {connectionAge} | transaction {transactionAge} | holds {heldLocks} advisory locks | blocked by: {blockers}{waitLabel}"
    
    @classmethod
    def _saveModifiedSettings(cls, modifiedSettingsList, originalSettingsList):
        """
        Save new or modified database settings and trash removed files.

        Renaming a profile changes only its local settings filename.
        It does not rename or move databasePath or cacheDir.
        """
        if modifiedSettingsList is None:
            return

        modifiedList = modifiedSettingsList.settingsList
        originalList = originalSettingsList.settingsList

        # Validate before writing anything. Names must map to unique files.
        filenames = set()
        uuids = set()

        for settings in modifiedList:
            filename = pglStorage.makeValidFilename(settings.name)

            if not filename:
                pglMessages.warning("Database settings must have a nonempty valid name.")
                return

            if filename in filenames:
                pglMessages.warning(
                    f"Database settings names must produce unique filenames: {settings.name}"
                )
                return

            if not settings.uuid or settings.uuid in uuids:
                pglMessages.warning("Database settings must have unique, nonempty UUIDs.")
                return

            filenames.add(filename)
            uuids.add(settings.uuid)

        # Ensure exactly one default when profiles remain.
        if modifiedList:
            defaults = [s for s in modifiedList if s.isDefault]
            selectedDefault = defaults[0] if defaults else modifiedList[0]

            for settings in modifiedList:
                settings.isDefault = settings is selectedDefault

        originalByUUID = {s.uuid: s for s in originalList}

        # Write all new/changed profiles before removing obsolete files.
        for settings in modifiedList:
            original = originalByUUID.get(settings.uuid)

            if original is None:
                pglMessages.message(f"Saving new database settings {settings.name}")
                settings.save()
            elif not original.equals(settings):
                settings.save()

        # Preserve any filename still used by the resulting settings list,
        # including when profiles exchange names.
        retainedPaths = {s.saveDir() for s in modifiedList}

        for original in originalList:
            oldPath = original.saveDir()

            if oldPath not in retainedPaths and oldPath.exists():
                pglSettingsManager.moveToTrash(oldPath)

    # -------------------------------------------------------------------------
    # Database setup
    # -------------------------------------------------------------------------
    # User entry point for local server setup and schema initialization.

    # ++++++++++++++++++++++++++++++ initDatabase +++++++++++++++++++++++++++++
    # User-facing database API. See the docstring for configuration, side effects, and return
    # conventions.
    @classmethod
    def initDatabase(cls, postgres=None, *, settings=None, settingsName=None):
        """Set up the locally managed database and initialize its schema.

        Uses default PGL settings unless settings or settingsName is supplied.
        An explicit postgres object may be supplied instead.

        Loads configuration from databasePath. If missing, creates a local
        configuration using that directory as installDirectory.

        Ensures PostgreSQL is installed, initializes missing server data,
        starts the server, creates the database/application access, and
        applies pending schema migrations.

        Never deletes existing data or resets an existing database.
        Local server setup currently supports macOS/Homebrew only.
        Returns False on cancellation or an operational connection failure.
        """
        from .pglPostgres import pglPostgres

        if postgres is not None and (settings is not None or settingsName is not None):
            raise ValueError("Supply either postgres or PGL settings, not both.")

        if postgres is None:
            resolvedSettings = cls.getSettings(settings=settings, settingsName=settingsName)

            if resolvedSettings is None:
                pglMessages.warning("Could not resolve PGL settings.", level=0)
                return False

            directory = resolvedSettings.databasePath.strip()

            if not directory:
                pglMessages.warning("Set databasePath in PGL settings before initializing the database.", level=0)
                return False

            configurationFile = posixpath.join(directory.rstrip("/") + "/", pglPostgres.CONFIGURATION_FILENAME)

            try:
                postgres = pglPostgres.load(configurationFile)
            except FileNotFoundError:
                # Only bootstrap a local installation. Never interpret a
                # missing remote configuration as a request for local setup.
                _, localDirectory, isLocal = pglPostgres._resolveConfigurationFile(directory)

                if not isLocal:
                    pglMessages.warning("Remote PostgreSQL configuration was not found. Initialize the server on its installation machine.", level=0)
                    return False

                postgres = pglPostgres(installDirectory=localDirectory)
                pglMessages.message(f"Creating local PostgreSQL configuration in {localDirectory}.")

        if not isinstance(postgres, pglPostgres):
            raise TypeError("postgres must be a pglPostgres instance.")

        postgres._validateValues()

        # The existing administration and migration implementation manages
        # a local server only. Do not accidentally administer a local server
        # when the loaded configuration describes a remote connection.
        if (
            getattr(postgres, "_configurationLoadedRemotely", False)
            or postgres.connectionTransport != "direct"
            or postgres.connectionHost != postgres.postgresHost
            or postgres.connectionPort != postgres.postgresPort
        ):
            pglMessages.warning("Database initialization currently requires the locally managed server configuration. Run it on the installation machine.", level=0)
            return False

        try:
            postgres.install()

            if postgres.init() is False:
                return False

            if postgres.start() is False:
                return False

            if not postgres.createDatabase():
                return False

            return cls._initDatabaseSchema(postgres=postgres)

        except psycopg.OperationalError as error:
            pglMessages.warning(f"Could not initialize PostgreSQL: {error}", level=0)
            return False


    # -------------------------------------------------------------------------
    # Sessions: loading and publication
    # -------------------------------------------------------------------------
    # User entry points for loading saved sessions and publishing raw or derived checkpoints.

    # ++++++++++++++++++++++++++++++ loadSession ++++++++++++++++++++++++++++++
    # User-facing database API. See the docstring for configuration, side effects, and return
    # conventions.
    # Direct callers in this module: _loadPipelineInput, getDatasetBehaviorData, getDatasetSession.
    # +++++++++++++++++++++++++++++ loadSession +++++++++++++++++++++++++++++
    @classmethod
    def loadSession(cls, sessionID, *, settings=None, settingsName=None, storageOptionsByBackend=None, sslRootCert=None, includeDeleted=False, cacheDirectory=None, directLocalPolicy="materialize"):
        """Load a completed checkpoint with retained caller-side payload access.

        Resolves configuration, selects the checkpoint-contract loader,
        restores annotations/publication metadata, and binds the saved
        history baseline.

        Supports legacy raw/derived contracts, derived v2 matrix products,
        derived v3 file attachments, and derived MRI v1/v2 checkpoints.

        Scientific fields remain deferred where supported. Derived files
        are restored as unopened references; their bytes are downloaded only
        when requested through getDerivedFile().

        Registered server-local roots resolve through the selected caller's
        local or SSH access context. Returned readers retain payload access,
        not the SQL connection or its tunnel.

        Returns None for invalid arguments, unavailable configuration,
        connection cancellation, an unknown/hidden checkpoint, or handled
        SQL errors. Integrity and contract errors propagate.

        On failure after reconstruction, closes attached matrices and the
        checkpoint filesystem without resolving deferred scientific fields.

        cacheDirectory overrides settings.cacheDir for MNE or v3 checkpoints.
        includeDeleted permits inspection without restoring lifecycle state.
        Requires current migration history and a persistent schema identity.
        Does not apply migrations, publish, or modify database records.

        The final printed overview resolves behavioral settings/data for
        labels and acquisition timestamps through session.info().
        """
        from .pglPostgres import pglPostgres

        if type(sessionID) is not int or not 0 <= sessionID <= 9223372036854775807:
            pglMessages.warning("sessionID must be a nonnegative PostgreSQL bigint.", level=1)
            return None

        if type(includeDeleted) is not bool:
            pglMessages.warning("includeDeleted must be a boolean.", level=1)
            return None

        if directLocalPolicy not in ("materialize", "immutable"):
            pglMessages.warning("directLocalPolicy must be 'materialize' or 'immutable'.", level=1)
            return None

        session = None
        checkpoint = None

        def closeFailedLoad():
            """Release privately loaded session/MRI resources without opening arrays."""
            if session is None: return

            # Both collections contain already-attached matrix wrappers. Accessing
            # these dictionaries does not resolve matrix.data or MRI scan payloads.
            collections = [session.dataMatrices]
            mri = getattr(session, "mri", None)
            if mri is not None: collections.append(mri.dataMatrices)

            # Shared wrappers should be closed once. One close failure must not
            # prevent the remaining matrices or checkpoint filesystem from closing.
            closedMatrices = set()
            for matrices in collections:
                for matrix in matrices.values():
                    if id(matrix) in closedMatrices: continue
                    closedMatrices.add(id(matrix))
                    try:
                        matrix.close()
                    except Exception:
                        pass

            # Derived-file backings borrow this filesystem too. Do not
            # materialize those files or resolve MNE fields during cleanup.
            filesystem = session.filesystem
            if isinstance(filesystem, pglCheckpointFilesystem):
                try:
                    filesystem.close()
                except Exception:
                    pass

        try:
            try:
                resolvedSettings = cls.getSettings(settings=settings, settingsName=settingsName)

                if resolvedSettings is None:
                    pglMessages.warning("Cannot load session: could not resolve PGL settings.", level=0)
                    return None

                pglMessages.message(f"Loading sessionID={sessionID} from {resolvedSettings.name} database: {resolvedSettings.databasePath}, username={resolvedSettings.username}")
                postgres = pglPostgres.fromSettings(settings=resolvedSettings)

            except (TypeError, ValueError) as error:
                pglMessages.warning(f"Cannot load session: invalid settings or configuration: {error}", level=1)
                return None

            if postgres is None: return None

            with postgres.connect(sslRootCert=sslRootCert) as connection:
                if connection is None: return None

                with connection.transaction():
                    connection.execute("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ, READ ONLY")
                    databaseID = cls._requireStableDatabaseIdentity(connection, postgres)

                    table = sql.Identifier(postgres.databaseSchema, "session")
                    statement = sql.SQL("SELECT origin, contract_version, description, checkpoint_name FROM {} WHERE session_id = %s AND (%s OR deleted_at IS NULL)").format(table)
                    checkpoint = connection.execute(statement, (sessionID, includeDeleted)).fetchone()

                    if checkpoint is not None:
                        origin, contractVersion, description, checkpointName = checkpoint
                        loadOptions = {
                            "storageOptionsByBackend": storageOptionsByBackend,
                            "includeDeleted": includeDeleted,
                        }

                        if (origin, contractVersion) == ("raw", "pgl.raw.behavior.v1"):
                            loader = cls.loadRawSession

                            # Legacy raw behavioral manifests declare no products.
                            cls._verifySessionProducts(connection, postgres, sessionID, [])

                        elif origin == "raw" and contractVersion in ("pgl.raw.session.v1", "pgl.raw.session.v2"):
                            loader = cls.loadRawSessionBundle
                            resolvedCache = cls._resolveCacheDirectory(cacheDirectory, settings=resolvedSettings)
                            loadOptions.update(cacheDirectory=resolvedCache, directLocalPolicy=directLocalPolicy)

                        elif origin == "derived" and contractVersion in (
                            "pgl.derived.behavior.v1",
                            "pgl.derived.behavior.v2",
                            "pgl.derived.behavior.v3",
                            "pgl.derived.session.v1",
                            "pgl.derived.session.v2",
                            "pgl.derived.session.v3",
                            "pgl.derived.mri.v1",
                            "pgl.derived.mri.v2",
                        ):
                            loader = cls.loadDerivedSession
                            hasMNE = contractVersion in (
                                "pgl.derived.session.v1",
                                "pgl.derived.session.v2",
                                "pgl.derived.session.v3",
                            )
                            hasFileContract = contractVersion in (
                                "pgl.derived.behavior.v3",
                                "pgl.derived.session.v3",
                                "pgl.derived.mri.v1",
                                "pgl.derived.mri.v2",
                            )

                            # V3 behavioral sessions need a cache independently
                            # of MNE. Resolve its location without creating it.
                            resolvedCache = (
                                cls._resolveCacheDirectory(cacheDirectory, settings=resolvedSettings)
                                if hasMNE or hasFileContract else cacheDirectory
                            )
                            loadOptions.update(cacheDirectory=resolvedCache, directLocalPolicy=directLocalPolicy)

                        else:
                            raise ValueError(f"Unsupported checkpoint origin/contract: {origin!r}, {contractVersion!r}")

                        # Read publication attribution in the same SQL snapshot.
                        # Validate it before constructing retained payload readers.
                        publicationInfo = cls._getCheckpointPublicationInfo(connection, postgres, sessionID)
                        session = loader(connection, postgres, sessionID, **loadOptions)
                        pendingBinding = cls._prepareCheckpointBinding(sessionID, postgres, databaseID=databaseID, databaseName=resolvedSettings.name)
                        pendingPostgres = postgres.withTimeouts()

            # SQL and its tunnel have closed. The returned session retains
            # independently owned contexts for deferred payload reads.
            if checkpoint is None:
                reason = "Unknown checkpoint" if includeDeleted else "Unknown or deleted checkpoint"
                pglMessages.warning(f"{reason}: {sessionID}", level=0)
                return None

            session.sessionID = sessionID
            session.description = checkpoint[2]
            session.checkpointName = checkpoint[3]

            for name, value in publicationInfo.items():
                setattr(session, name, value)

            cls._bindCheckpointBaseline(session, sessionID, postgres)
            session._checkpointBinding = pendingBinding
            session._checkpointPostgres = pendingPostgres

            # Keep overview failures inside the cleanup boundary too.
            session.print(headerOnly=True)

        except psycopg.Error as error:
            closeFailedLoad()
            pglMessages.warning(f"Could not load session {sessionID}: {error}", level=2)
            return None

        except BaseException:
            closeFailedLoad()
            raise

        return session

    # ++++++++++++++++++++++++++++++ saveSession ++++++++++++++++++++++++++++++
    # User-facing database API. See the docstring for configuration, side effects, and return
    # conventions.
    @classmethod
    def saveSession(cls, session, *, parentSessionID=None, settings=None, settingsName=None, backendID=None, checkpointName=None, description=None, ingestMethod="manual", storageOptions=None, sslRootCert=None, lockTimeoutSeconds=30.0, ioTimeoutSeconds=60, connectTimeoutSeconds=10):
        """Publish current contents using selective checkpoint payload reuse.

        Untouched checkpoint-backed behavioral contents, stimuli, MRI
        acquisitions, and restored attachments reuse registered content.

        Materialized mutable contents are serialized conservatively.
        MNE and working matrices retain their existing full-export paths.

        Acquires a session publication/lifecycle lock before database writes.
        Ordinary SELECT reports remain available; competing publication and
        dependency/lifecycle operations may wait.

        Updates working identity, annotations, and history baseline only
        after commit and connection cleanup.

        Expected operational failures warn and return None.
        Integrity/programming errors and KeyboardInterrupt propagate.
        Payload writes are not transactional.
        Requires current migrations; never applies migrations automatically.
        """
        from time import perf_counter

        from .pglPostgres import pglPostgres

        pglPostgres.validateTimeouts(lockTimeoutSeconds=lockTimeoutSeconds, ioTimeoutSeconds=ioTimeoutSeconds, connectTimeoutSeconds=connectTimeoutSeconds)

        if getattr(session, "mri", None) is not None:
            from .pglMRI import pglMRI

            if type(session.mri) is not pglMRI or not session.mri.scans:
                pglMessages.warning("Session was not saved: MRI requires a nonempty pglMRI collection.")
                return None
            if session.mne is not None:
                pglMessages.warning("Session was not saved: combined MRI/MNE checkpoints are unsupported.")
                return None

        # Preserve the existing friendly refusal for failed-action safety.
        try:
            pglStorage.requireSafeSave(session)
        except ValueError as error:
            pglMessages.warning(str(error))
            return None

        cls._getCheckpointHistoryBoundary(session)
        originalBaseline = deepcopy(session._checkpointBaseline)
        originalReference = cls._getBoundCheckpointReference(session)
        originalBinding = deepcopy(session._checkpointBinding)
        originalSessionID = session.sessionID
        resolvedParentID = originalSessionID if parentSessionID is None else parentSessionID

        if resolvedParentID is None:
            pglMessages.warning(
                "Cannot save session: no source checkpoint is selected. "
                "Use saveRawSession() to create a root, or supply parentSessionID.",
                level=2,
            )
            return None

        for label, value in (("parentSessionID", resolvedParentID), ("backendID", backendID)):
            if label == "backendID" and value is None: continue
            if type(value) is not int or not 0 <= value <= 9223372036854775807:
                raise ValueError(f"{label} must be a nonnegative PostgreSQL bigint.")

        if storageOptions is not None and not isinstance(storageOptions, dict):
            raise TypeError("storageOptions must be a dictionary or None.")

        def normalizeAnnotation(value, label):
            if value is None: return None
            if not isinstance(value, str) or "\x00" in value:
                raise ValueError(f"{label} must be a string without NUL, or None.")
            return value if value.strip() else None

        originalCheckpointName = session.checkpointName
        originalDescription = session.description
        resolvedCheckpointName = normalizeAnnotation(originalCheckpointName if checkpointName is None else checkpointName, "checkpointName")
        resolvedDescription = normalizeAnnotation(originalDescription if description is None else description, "description")

        if not isinstance(ingestMethod, str) or ingestMethod not in {"manual", "automated"}:
            raise ValueError("ingestMethod must be manual or automated.")

        sessionID = None
        commitAttempted = False
        commitConfirmed = False
        progress = None
        operation = "resolving database settings"
        saveStarted = perf_counter()

        try:
            with pglProgress("Saving session") as progress:
                progress(0, "Resolving database settings")
                resolvedSettings = cls.getSettings(settings=settings, settingsName=settingsName)

                if resolvedSettings is None:
                    pglMessages.warning("Cannot save session: could not resolve PGL settings.", level=0)
                    return None

                username = resolvedSettings.username
                if not isinstance(username, str) or not username.strip() or "\x00" in username:
                    pglMessages.warning("Cannot save session: set a valid username in PGL settings.", level=0)
                    return None

                progress(0.01, "Loading PostgreSQL configuration")
                postgres = pglPostgres.fromSettings(settings=resolvedSettings)
                if postgres is None: return None

                postgres = postgres.withTimeouts(lockTimeoutSeconds=lockTimeoutSeconds, ioTimeoutSeconds=ioTimeoutSeconds, connectTimeoutSeconds=connectTimeoutSeconds)

                if originalBaseline and originalBaseline["databaseIdentity"] != cls._checkpointDatabaseIdentity(postgres):
                    raise ValueError("The selected database differs from this session's checkpoint baseline.")

                if originalBinding and originalBinding["databaseIdentity"] != cls._checkpointDatabaseIdentity(postgres):
                    raise ValueError("The selected database differs from this session's saved-checkpoint endpoint.")

                if backendID is None and not postgres.storageLocations:
                    pglMessages.warning("Cannot save session: no storageLocations are configured.", level=0)
                    return None

                databasePath = resolvedSettings.databasePath.strip()
                progress(0.02, "Connecting to PostgreSQL")

                with postgres.connect(sslRootCert=sslRootCert) as connection:
                    if connection is None:
                        progress(None, "Connection cancelled")
                        return None

                    with connection.transaction():
                        connection.execute("SET TRANSACTION ISOLATION LEVEL READ COMMITTED")
                        databaseID = cls._requireStableDatabaseIdentity(connection, postgres)
                        if originalReference is not None and originalReference["databaseID"] != databaseID:
                            raise ValueError("The database UUID differs from this session's saved-checkpoint identity.")

                        # Acquire before backend registration, user creation,
                        # matrix publication, or checkpoint row locks.
                        progress(0.03, "Acquiring checkpoint publication/lifecycle lock")
                        cls._acquireCheckpointPublicationLock(connection, postgres, progress=progress)

                        if backendID is None:
                            progress(0.035, "Resolving checkpoint storage destination")
                            backendID = cls._getConfiguredStorageBackend(connection, postgres, storageOptions=storageOptions)

                        progress(0.04, "Resolving checkpoint owner")
                        createdBy = cls.getOrCreateUser(connection, postgres, username)

                        progress(0.05, "Preparing selective derived checkpoint")
                        sessionID = cls._saveDerivedSession(
                            connection,
                            postgres,
                            session,
                            createdBy,
                            backendID,
                            parentSessionID=resolvedParentID,
                            checkpointName=resolvedCheckpointName,
                            description=resolvedDescription,
                            ingestMethod=ingestMethod,
                            storageOptions=storageOptions,
                            progress=progress.section(0.05, 0.95),
                        )

                        progress(0.96, "Preparing committed checkpoint baseline")
                        pglStorage.requireSafeSave(session)
                        cls._getCheckpointHistoryBoundary(session)

                        if session.sessionID != originalSessionID or session._checkpointBaseline != originalBaseline:
                            raise ValueError("Working checkpoint identity changed while saving.")
                        if session.checkpointName != originalCheckpointName or session.description != originalDescription:
                            raise ValueError("Working checkpoint annotations changed while saving.")

                        if session._checkpointBinding != originalBinding:
                            raise ValueError("Working saved-checkpoint binding changed while saving.")

                        pendingBaseline = cls._prepareCheckpointBaseline(session, sessionID, postgres)
                        pendingBinding = cls._prepareCheckpointBinding(sessionID, postgres, databaseID=databaseID, databaseName=resolvedSettings.name)
                        pendingPostgres = postgres.withTimeouts()

                        progress(0.98, "Committing checkpoint transaction")
                        commitAttempted = True

                    commitConfirmed = True
                    progress(0.99, "Closing PostgreSQL connection and tunnel")

                # Preserve existing reader/backing ownership. Updating sessionID
                # does not retarget the working object's deferred source readers.
                session.sessionID = sessionID
                session.checkpointName = resolvedCheckpointName
                session.description = resolvedDescription
                session._checkpointBaseline = pendingBaseline
                session._checkpointBinding = pendingBinding
                session._checkpointPostgres = pendingPostgres

                progress.finish(f"Checkpoint {sessionID} saved")

        except Exception as error:
            operation = getattr(progress, "_description", operation)

            if not cls._handleCheckpointSaveFailure(
                error,
                checkpointKind="Session checkpoint",
                checkpointID=sessionID,
                operation=operation,
                commitAttempted=commitAttempted,
                commitConfirmed=commitConfirmed,
            ):
                raise

            return None

        pglMessages.message(
            f"Checkpoint {sessionID} is complete. Database configuration: "
            f"{databasePath} (database={postgres.databaseName}, "
            f"schema={postgres.databaseSchema}; "
            f"{perf_counter() - saveStarted:.1f} s total).",
            wrapText=False,
        )
        return sessionID

    # +++++++++++++++++++++++++++++ saveRawSession ++++++++++++++++++++++++++++
    # User-facing database API. See the docstring for configuration, side effects, and return
    # conventions.
    @classmethod
    def saveRawSession(cls, session, *, settings=None, settingsName=None, backendID=None, storageOptions=None, sslRootCert=None, allowMissingMetadata=False, lockTimeoutSeconds=30.0, ioTimeoutSeconds=60, connectTimeoutSeconds=10):
        """Save or reuse a parentless acquisition checkpoint with progress.

        Timeout overrides apply to a private runtime configuration copy:
            lockTimeoutSeconds: each advisory-lock contention wait.
            ioTimeoutSeconds: PGL-owned inferred SFTP channel I/O.
            connectTimeoutSeconds: PostgreSQL and PGL-owned SSH setup.

        These do not limit total save duration, change caller-owned source
        filesystems, configure explicit-URL storage backends, or control remote
        configuration-file discovery. SQL statement/general lock timeouts are
        not changed.

        Returns a checkpoint ID after commit and connection cleanup, or None
        for rejection, cancellation, unavailable configuration, or handled
        lock/connection/timeout failures.

        Unexpected errors, integrity failures, and KeyboardInterrupt propagate.
        Recognized dropped SSH connections warn; SSH security failures propagate.

        SQL changes are transactional; payload writes are not.
        Failure during commit can leave its outcome uncertain to this client.
        No automatic retry, connection termination, or payload deletion occurs.

        Requires current migrations; never applies them automatically.
        Binds sessionID and saved source identity after connection cleanup,
        without establishing or replacing a working-history baseline.
        """
        from time import perf_counter

        from paramiko import SSHException
        from paramiko.ssh_exception import AuthenticationException, BadHostKeyException

        from .pglPostgres import pglPostgres

        # Reject invalid timeout arguments before source reads or connections.
        pglPostgres.validateTimeouts(lockTimeoutSeconds=lockTimeoutSeconds, ioTimeoutSeconds=ioTimeoutSeconds, connectTimeoutSeconds=connectTimeoutSeconds)

        # Reject unsupported combinations before opening database connections.
        if getattr(session, "mri", None) is not None:
            from .pglMRI import pglMRI

            if type(session.mri) is not pglMRI or not session.mri.scans:
                pglMessages.warning(
                    "Raw session was not saved: MRI requires a nonempty pglMRI collection.",
                    level=0,
                )
                return None

            if session.mne is not None:
                pglMessages.warning(
                    "Raw session was not saved: combined MRI/MNE checkpoints are unsupported.",
                    level=0,
                )
                return None
        
        originalReference = cls._getBoundCheckpointReference(session)
        originalBinding = deepcopy(session._checkpointBinding)
        originalSessionID = session.sessionID
        originalBaseline = deepcopy(session._checkpointBaseline)

        sessionID = None
        commitAttempted = False
        commitConfirmed = False
        operation = "validating raw acquisition metadata"
        saveStarted = perf_counter()

        def isDroppedSSHConnection(error):
            """Recognize connection loss without hiding SSH security failures."""
            if isinstance(error, (AuthenticationException, BadHostKeyException)):
                return False

            if not isinstance(error, SSHException):
                return False

            message = str(error).strip().lower()

            return message.startswith("server connection dropped:") or message in {
                "socket is closed",
                "socket is closed.",
                "server connection dropped",
                "ssh session not active",
                "no existing session",
            }

        def warnSaveFailure(reason, *, inspectLocks=False):
            """Warn after cleanup and optionally display current lock owners."""
            if commitConfirmed:
                outcome = (
                    f"Raw checkpoint {sessionID}: the database transaction committed, "
                    "but subsequent cleanup failed. The checkpoint was not rolled back. "
                    "This call returns no checkpoint ID, so the working session's "
                    "checkpoint identity was not updated."
                )
            elif commitAttempted:
                outcome = (
                    f"Raw checkpoint {sessionID}: the failure occurred during commit. "
                    "The commit outcome is not confirmed by this client. "
                    "The checkpoint may already have been saved."
                )
            else:
                outcome = (
                    "The final checkpoint commit was not attempted. "
                    "Transaction and connection cleanup were attempted. "
                    "If PostgreSQL is unreachable, its transaction and locks may remain "
                    "until the server detects the disconnected client."
                )

            pglMessages.warning(
                f"Raw session save stopped while {operation}: {reason}.\n"
                f"{outcome}\n"
                "Partial or unregistered payload files may remain. "
                "No automatic retry or connection termination was performed.",
                level=2,
            )

            if inspectLocks:
                pglMessages.message("Checking current lock owners and blocked sessions...", wrapText=False)

                try:
                    cls.inspectPostgresLocks(settings=settings, settingsName=settingsName, sslRootCert=sslRootCert)
                except Exception as diagnosticError:
                    pglMessages.warning(f"Lock inspection was unavailable ({type(diagnosticError).__name__}). Restore connectivity and run pglDatabase.inspectPostgresLocks() with the same database settings.", level=1)

                pglMessages.message("For a confirmed abandoned owner, use pglDatabase.terminatePostgresLock(PID). Administrator authorization and confirmation are required. Current holders are not necessarily the original blocker.", wrapText=False)
            else:
                pglMessages.message("Check VPN/network and database/storage availability. After restoring connectivity, run pglDatabase.inspectPostgres() before retrying.", wrapText=False)

            if commitAttempted:
                pglMessages.message("Check pglDatabase.print() to establish whether the checkpoint was saved before retrying.", wrapText=False)

        try:
            if not cls._checkRawSessionLabels(session, allowMissingMetadata=allowMissingMetadata):
                return None

            if session.dataMatrices:
                productNames = list(session.dataMatrices)
                pglMessages.warning(f"saveRawSession() saves acquisition contents only. Attached data matrices {productNames!r} will not be included in this checkpoint. Working attachments are unchanged; use saveSession() to preserve them.", level=1)

            operation = "resolving database settings"
            resolvedSettings = cls.getSettings(settings=settings, settingsName=settingsName)

            if resolvedSettings is None:
                pglMessages.warning("Cannot save raw session: could not resolve PGL settings.", level=0)
                return None

            username = resolvedSettings.username

            if not isinstance(username, str) or not username.strip() or "\x00" in username:
                pglMessages.warning("Cannot save raw session: set a valid username in PGL settings.", level=0)
                return None

            databasePath = resolvedSettings.databasePath.strip()

            with pglProgress() as progress:
                operation = "loading PostgreSQL configuration"
                progress(0, "Loading PostgreSQL configuration")
                postgres = pglPostgres.fromSettings(settings=resolvedSettings)

                if postgres is None:
                    progress(None, "PostgreSQL configuration unavailable")
                    return None

                # Keep saved configuration and other operations unchanged.
                postgres = postgres.withTimeouts(lockTimeoutSeconds=lockTimeoutSeconds, ioTimeoutSeconds=ioTimeoutSeconds, connectTimeoutSeconds=connectTimeoutSeconds)

                baseline = session._checkpointBaseline

                if baseline and baseline["databaseIdentity"] != cls._checkpointDatabaseIdentity(postgres):
                    pglMessages.warning("Cannot save this session to a different database. Cross-database checkpoint transfer is not implemented; session IDs are local to their database.")
                    progress(None, "Database identity mismatch")
                    return None

                if originalBinding and originalBinding["databaseIdentity"] != cls._checkpointDatabaseIdentity(postgres):
                    raise ValueError("The selected database differs from this session's saved-checkpoint endpoint.")

                if backendID is None and not postgres.storageLocations:
                    pglMessages.warning("Cannot save raw session: no storageLocations are configured in the PostgreSQL configuration.", level=0)
                    progress(None, "No storage destination configured")
                    return None

                operation = "connecting to PostgreSQL"
                progress(0.01, "Connecting to PostgreSQL")

                with postgres.connect(sslRootCert=sslRootCert) as connection:
                    if connection is None:
                        progress(None, "Connection cancelled")
                        return None

                    with connection.transaction():
                        databaseID = cls._requireStableDatabaseIdentity(connection, postgres)
                        if originalReference is not None and originalReference["databaseID"] != databaseID:
                            raise ValueError("The database UUID differs from this session's saved-checkpoint identity.")

                        if backendID is None:
                            operation = "resolving storage destination and acquiring its registration lock"
                            progress(0.03, "Resolving storage destination / acquiring registration lock")
                            backendID = cls._getConfiguredStorageBackend(connection, postgres, storageOptions=storageOptions)

                        operation = "resolving checkpoint owner"
                        progress(0.04, "Resolving checkpoint owner")
                        createdBy = cls.getOrCreateUser(connection, postgres, username)

                        operation = "preparing, transferring, verifying, or registering checkpoint contents"
                        progress(0.05, "Preparing raw checkpoint")
                        sessionID = cls._saveRawSession(connection, postgres, session, createdBy, backendID, storageOptions=storageOptions, progress=progress)

                        # Prepare binding before commit; installation on the
                        # working object waits for connection cleanup below.
                        if session.sessionID != originalSessionID or session._checkpointBinding != originalBinding or session._checkpointBaseline != originalBaseline:
                            raise ValueError("Working checkpoint bookkeeping changed while saving raw acquisition contents.")
                        pendingBinding = cls._prepareCheckpointBinding(sessionID, postgres, databaseID=databaseID, databaseName=resolvedSettings.name)
                        pendingPostgres = postgres.withTimeouts()

                        operation = "committing the checkpoint transaction"
                        progress(0.98, "Committing transaction")
                        commitAttempted = True

                    commitConfirmed = True
                    operation = "closing the PostgreSQL connection and tunnel"
                    progress(0.99, "Closing PostgreSQL connection and tunnel")

                # Raw publication identifies an acquisition checkpoint,
                # not a new history boundary for the current working state.
                session.sessionID = sessionID
                session._checkpointBinding = pendingBinding
                session._checkpointPostgres = pendingPostgres

                progress.finish(f"Raw checkpoint {sessionID} saved")

        except psycopg.errors.LockNotAvailable:
            warnSaveFailure("PostgreSQL could not acquire a required lock", inspectLocks=True)
            return None

        except TimeoutError:
            reason = (
                "a lock wait, connection attempt, or I/O operation timed out "
                f"(configured limits: advisory lock {lockTimeoutSeconds:g} s, "
                f"SFTP I/O {ioTimeoutSeconds} s, connection setup {connectTimeoutSeconds} s)"
            )
            warnSaveFailure(reason, inspectLocks=True)
            return None

        except SSHException as error:
            if not isDroppedSSHConnection(error):
                raise

            warnSaveFailure("the SSH/SFTP connection was lost")
            return None

        except (psycopg.OperationalError, psycopg.InterfaceError):
            warnSaveFailure("a PostgreSQL connection or operational failure occurred")
            return None

        except ConnectionError:
            warnSaveFailure("a network connection failed")
            return None

        pglMessages.message(f"Raw checkpoint {sessionID} is complete. Database configuration: {databasePath} (database={postgres.databaseName}, schema={postgres.databaseSchema}; {perf_counter() - saveStarted:.1f} s total).", wrapText=False)
        return sessionID

    # -------------------------------------------------------------------------
    # Sessions: annotations and lifecycle
    # -------------------------------------------------------------------------
    # User entry points for annotation changes and coordinated soft deletion or restoration.

    # +++++++++++++++++++++++++ setSessionDescription +++++++++++++++++++++++++
    # User-facing database API. See the docstring for configuration, side effects, and return
    # conventions.
    @classmethod
    def setSessionDescription(cls, sessionID, description, *, settings=None, settingsName=None, sslRootCert=None):
        """Set or clear an active saved checkpoint's description.

        Accepts raw and derived checkpoints.
        None or blank text clears the description.

        Updates only database metadata, not payloads, manifest identity,
        lineage, or saved action history. Previous descriptions are not
        retained by this method.

        Returns True for a committed change, False for an unchanged,
        unknown, or deleted checkpoint, and None for invalid arguments,
        unavailable configuration/connection, or database failure.
        """
        from .pglPostgres import pglPostgres

        if type(sessionID) is not int or not 0 <= sessionID <= 9223372036854775807:
            pglMessages.warning("sessionID must be a nonnegative PostgreSQL bigint.", level=1)
            return None

        if description is not None and (not isinstance(description, str) or "\x00" in description):
            pglMessages.warning("description must be a string without NUL, or None.", level=1)
            return None

        if description is not None:
            description = description.strip() or None

        try:
            try:
                postgres = pglPostgres.fromSettings(settings=settings, settingsName=settingsName)
            except (TypeError, ValueError) as error:
                pglMessages.warning(f"Cannot update session description: invalid settings or configuration: {error}", level=1)
                return None

            if postgres is None:
                return None

            table = sql.Identifier(postgres.databaseSchema, "session")

            with postgres.connect(sslRootCert=sslRootCert) as connection:
                if connection is None:
                    return None

                with connection.transaction():
                    statement = sql.SQL("SELECT description, deleted_at FROM {} WHERE session_id = %s FOR UPDATE").format(table)
                    record = connection.execute(statement, (sessionID,)).fetchone()

                    if record is None:
                        outcome = "unknown"
                    elif record[1] is not None:
                        outcome = "deleted"
                    elif record[0] == description:
                        outcome = "unchanged"
                    else:
                        statement = sql.SQL("UPDATE {} SET description = %s WHERE session_id = %s RETURNING description").format(table)
                        updated = connection.execute(statement, (description, sessionID)).fetchone()

                        if updated != (description,):
                            raise RuntimeError("The database did not apply the requested description.")

                        outcome = "updated"

        except psycopg.Error as error:
            pglMessages.warning(f"Could not update description for session {sessionID}: {error}. If the connection failed during commit, check the saved description before retrying.", level=2)
            return None

        if outcome == "unknown":
            pglMessages.warning(f"Unknown session: {sessionID}", level=0)
            return False

        if outcome == "deleted":
            pglMessages.warning(f"Cannot change the description of deleted session {sessionID}. Undelete it first.", level=2)
            return False

        if outcome == "unchanged":
            pglMessages.message(f"Session {sessionID} already has that description; nothing changed.")
            return False

        if description is None:
            pglMessages.message(f"Description cleared for session {sessionID}.")
        else:
            pglMessages.message(f"Description updated for session {sessionID}: {cls._printValue(description)}", wrapText=False)

        return True

    # +++++++++++++++++++++++++++++ deleteSession +++++++++++++++++++++++++++++
    # User-facing database API. See the docstring for configuration, side effects, and return
    # conventions.
    @classmethod
    def deleteSession(cls, sessionID, *, deleteDownstreamSessions=False, settings=None, settingsName=None, sslRootCert=None):
        """Soft-delete a session, optionally including active descendants.

        Without deleteDownstreamSessions, active descendants block deletion.

        With deleteDownstreamSessions=True, print every session to be newly
        deleted and require an explicit 'yes'. Recheck the exact deletion
        set under locks after confirmation.

        Every new deletion records a group, even for a single session.
        Previously deleted descendants are not enrolled in the new group.

        Returns:
            True: a change committed.
            False: unchanged, unknown, blocked, or confirmation cancelled.
            None: invalid arguments, unavailable configuration/connection,
                  or database failure.

        Unknown sessions warn at level 0, invalid arguments at level 1,
        and blocked operations/database failures at level 2.

        Never removes or rereads payloads.
        """
        return cls._changeSessionDeletionState(sessionID, deleted=True, deleteDownstreamSessions=deleteDownstreamSessions, settings=settings, settingsName=settingsName, sslRootCert=sslRootCert)

    # ++++++++++++++++++++++++++++ undeleteSession ++++++++++++++++++++++++++++
    # User-facing database API. See the docstring for configuration, side effects, and return
    # conventions.
    @classmethod
    def undeleteSession(cls, sessionID, *, settings=None, settingsName=None, sslRootCert=None):
        """Restore an entire deletion group through its top-level session.

        Calls on other group members are refused. Required parents outside
        the group must already be active.

        Legacy deleted sessions without group records are restored alone,
        subject to the same parent requirement.

        Returns:
            True: restoration committed.
            False: unchanged, unknown, or blocked.
            None: invalid arguments, unavailable configuration/connection,
                  or database failure.

        Unknown sessions warn at level 0, invalid arguments at level 1,
        and blocked operations/database failures at level 2.

        Does not reread or rewrite payloads.
        """
        return cls._changeSessionDeletionState(sessionID, deleted=False, settings=settings, settingsName=settingsName, sslRootCert=sslRootCert)


    # -------------------------------------------------------------------------
    # Datasets: loading and publication
    # -------------------------------------------------------------------------
    # User entry points for immutable dataset checkpoint publication and restoration.

    # ++++++++++++++++++++++++++++++ loadDataset ++++++++++++++++++++++++++++++
    # User-facing database API. See the docstring for configuration, side effects, and return
    # conventions.
    @classmethod
    def loadDataset(cls, datasetID, *, settings=None, settingsName=None, sslRootCert=None, includeDeleted=False, storageOptionsByBackend=None, cacheDirectory=None, directLocalPolicy="materialize"):
        """Restore metadata, membership, and unopened product references.

        Does not construct sessions, open Zarr stores, or rebuild products.
        includeDeleted permits inspection without restoring protection.
        """
        from psycopg.rows import tuple_row
        from .pglData import pglDataMatrixReference
        from .pglDataset import pglDataset
        from .pglSerialize import pglSerialize

        if type(datasetID) is not int or not 0 <= datasetID <= 9223372036854775807:
            raise ValueError("datasetID must be a nonnegative PostgreSQL bigint.")

        if type(includeDeleted) is not bool:
            raise ValueError("includeDeleted must be a boolean.")

        if directLocalPolicy not in ("materialize", "immutable"):
            raise ValueError("directLocalPolicy must be 'materialize' or 'immutable'.")

        shell = pglDataset(settings=settings, settingsName=settingsName)
        resolvedSettings, postgres = cls._resolveDatasetStorage(shell)

        if postgres is None:
            return None

        datasetsTable = sql.Identifier(postgres.databaseSchema, "dataset")
        membersTable = sql.Identifier(postgres.databaseSchema, "dataset_members")
        productsTable = sql.Identifier(postgres.databaseSchema, "dataset_products")
        checkpoint = None
        memberRows = []
        productRows = []

        with postgres.connect(sslRootCert=sslRootCert) as connection:
            if connection is None:
                return None

            with connection.transaction():
                connection.execute("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ, READ ONLY")

                with connection.cursor(row_factory=tuple_row) as cursor:
                    statement = sql.SQL("""
                        SELECT family_uuid, name, checkpoint_name, description,
                               status, contract_version, metadata
                        FROM {}
                        WHERE dataset_id = %s
                          AND (%s OR deleted_at IS NULL)
                    """).format(datasetsTable)

                    cursor.execute(statement, (datasetID, includeDeleted))
                    checkpoint = cursor.fetchone()

                    if checkpoint is not None:
                        statement = sql.SQL("SELECT member_index, session_id, entry_name, labels FROM {} WHERE dataset_id = %s ORDER BY member_index").format(membersTable)
                        cursor.execute(statement, (datasetID,))
                        memberRows = cursor.fetchall()

                        statement = sql.SQL("SELECT product_name, matrix_revision_id FROM {} WHERE dataset_id = %s ORDER BY product_name").format(productsTable)
                        cursor.execute(statement, (datasetID,))
                        productRows = cursor.fetchall()

        if checkpoint is None:
            pglMessages.warning(f"Unknown or hidden dataset checkpoint: {datasetID}", level=0)
            return None

        familyUUID, name, checkpointName, description, status, contractVersion, document = checkpoint

        if status != "complete":
            raise ValueError("Only completed dataset checkpoints can be loaded.")

        if contractVersion != "pgl.dataset.v1":
            raise ValueError(f"Unsupported dataset contract: {contractVersion!r}")

        if not isinstance(document, dict):
            raise ValueError("Dataset metadata must contain a serialized JSON object.")

        dataset = pglSerialize.fromJSON(json.dumps(document, allow_nan=False), strict=True)

        if type(dataset) is not pglDataset:
            raise TypeError("Saved dataset metadata did not restore as pglDataset.")

        if dataset.name != name or dataset.uuid != str(familyUUID):
            raise ValueError("Dataset metadata disagrees with its database identity or name.")

        if dataset.data:
            raise ValueError("Dataset metadata unexpectedly embedded products.")

        if [row[0] for row in memberRows] != list(range(len(memberRows))):
            raise ValueError("Dataset membership order is invalid.")

        records = [{"sessionID": sessionID, "entryName": entryName, "labels": labels} for _, sessionID, entryName, labels in memberRows]
        dataset._members = dataset._validateMembers(records)
        dataset.datasetID = datasetID
        dataset.checkpointName = checkpointName
        dataset.description = description

        cls._bindDatasetStorage(dataset, resolvedSettings, postgres)
        identityJSON = cls._datasetDatabaseIdentityJSON(dataset._datasetDatabaseIdentity)

        dataset.data = {productName: pglDataMatrixReference(str(revisionID), identityJSON) for productName, revisionID in productRows}
        cls._validateDatasetProducts(dataset)

        dataset._datasetLoadOptions = {
            "sslRootCert": sslRootCert,
            "storageOptionsByBackend": storageOptionsByBackend,
            "cacheDirectory": cacheDirectory,
            "directLocalPolicy": directLocalPolicy,
        }

        dataset._datasetBaseline = {
            "version": 1,
            "datasetID": datasetID,
            "familyUUID": dataset.uuid,
            "databaseIdentity": deepcopy(dataset._datasetDatabaseIdentity),
            "historyHashes": cls._datasetHistoryHashes(dataset),
        }

        pglMessages.message(f"Loaded dataset checkpoint {datasetID} with {len(records)} members and {len(productRows)} unopened products; sessions have not been loaded.")
        return dataset

    # +++++++++++++++++++++++++++++ saveDataset +++++++++++++++++++++++++++++
    @classmethod
    def saveDataset(cls, dataset, *, settings=None, settingsName=None, backendID=None, storageOptions=None, sslRootCert=None, lockTimeoutSeconds=30.0, ioTimeoutSeconds=60, connectTimeoutSeconds=10):
        """Publish a dataset checkpoint with progress and runtime timeouts.

        Existing references reuse registered matrix revisions.
        Working matrices publish new standalone Zarr bundles.
        Cached working sessions are not saved.

        Preserves dependency-lock ordering and validates required sources.
        Payload access closes before the commit attempt.

        Updates dataset identity, binding, annotations, and baseline only
        after successful commit and connection cleanup.

        Progress is per product for Zarr publication, not byte-level.
        Expected operational failures warn and return None.
        Other errors and KeyboardInterrupt propagate.

        Payload writes are not transactional. Failed publication may leave
        unregistered matrix bundles. Concurrent mutation is unsupported.
        """
        from contextlib import ExitStack
        from time import perf_counter

        from psycopg.types.json import Jsonb

        from .pglData import pglDataMatrix, pglDataMatrixReference
        from .pglPostgres import pglPostgres

        pglPostgres.validateTimeouts(lockTimeoutSeconds=lockTimeoutSeconds, ioTimeoutSeconds=ioTimeoutSeconds, connectTimeoutSeconds=connectTimeoutSeconds)

        if backendID is not None and (type(backendID) is not int or not 0 <= backendID <= 9223372036854775807):
            raise ValueError("backendID must be a nonnegative PostgreSQL bigint.")

        if storageOptions is not None and not isinstance(storageOptions, dict):
            raise TypeError("storageOptions must be a dictionary or None.")

        datasetID = None
        commitAttempted = False
        commitConfirmed = False
        progress = None
        operation = "validating dataset contents"
        saveStarted = perf_counter()

        try:
            with pglProgress("Saving dataset") as progress:
                progress(0, "Validating dataset membership, history, and products")

                metadata = cls._prepareDatasetMetadata(dataset)
                members = dataset._validateMembers(dataset.members)
                products = cls._validateDatasetProducts(dataset)
                checkpointName = cls._datasetAnnotation(dataset.checkpointName, "checkpointName")
                description = cls._datasetAnnotation(dataset.description, "description")
                historyHashes = cls._datasetHistoryHashes(dataset)

                for product in products.values():
                    if isinstance(product, pglDataMatrix):
                        pglStorage.requireSafeSave(product)
                        pglStorage.validateDataMatrixEncoding(product.requireData())

                progress(0.01, "Resolving dataset database configuration")
                resolvedSettings, postgres = cls._resolveDatasetStorage(dataset, settings=settings, settingsName=settingsName)

                if postgres is None:
                    return None

                postgres = postgres.withTimeouts(lockTimeoutSeconds=lockTimeoutSeconds, ioTimeoutSeconds=ioTimeoutSeconds, connectTimeoutSeconds=connectTimeoutSeconds)
                username = resolvedSettings.username

                if not isinstance(username, str) or not username.strip() or "\x00" in username:
                    pglMessages.warning("Cannot save dataset: set a valid username in PGL settings.", level=0)
                    return None

                databaseIdentity = deepcopy(cls._checkpointDatabaseIdentity(postgres))
                identityJSON = cls._datasetDatabaseIdentityJSON(databaseIdentity)

                for name, product in products.items():
                    if isinstance(product, pglDataMatrixReference) and product.databaseIdentityJSON != identityJSON:
                        raise ValueError(f"Product {name!r} references a different configured database.")

                datasetsTable = sql.Identifier(postgres.databaseSchema, "dataset")
                membersTable = sql.Identifier(postgres.databaseSchema, "dataset_members")
                productsTable = sql.Identifier(postgres.databaseSchema, "dataset_products")
                revisionsTable = sql.Identifier(postgres.databaseSchema, "matrix_revisions")
                backendsTable = sql.Identifier(postgres.databaseSchema, "storage_backends")
                hasWorkingProducts = any(isinstance(product, pglDataMatrix) for product in products.values())

                progress(0.02, "Connecting to PostgreSQL")

                with postgres.connect(sslRootCert=sslRootCert) as connection:
                    if connection is None:
                        progress(None, "Connection cancelled")
                        return None

                    with connection.transaction():
                        connection.execute("SET TRANSACTION ISOLATION LEVEL READ COMMITTED")

                        progress(0.03, "Acquiring dataset session-dependency lock")
                        postgres.acquireTableShareLock(connection, "session", description="dataset session-dependency lock", progress=progress)

                        # Keep all owned payload resources inside the transaction,
                        # but close them before marking the commit attempt.
                        with ExitStack() as resources:
                            progress(0.04, "Resolving checkpoint owner")
                            createdBy = cls.getOrCreateUser(connection, postgres, username)
                            destinationFS = None
                            destinationRoot = None

                            if hasWorkingProducts:
                                if backendID is None:
                                    progress(0.05, "Resolving matrix storage destination")
                                    backendID = cls._getConfiguredStorageBackend(connection, postgres, storageOptions=storageOptions)

                                statement = sql.SQL("SELECT url_prefix, is_active FROM {} WHERE backend_id = %s FOR SHARE").format(backendsTable)
                                backend = connection.execute(statement, (backendID,)).fetchone()

                                if backend is None or not backend[1]:
                                    raise ValueError("Matrix destination backend is missing or inactive.")

                                progress(0.06, "Opening matrix destination storage")
                                access = resources.enter_context(pglDatabaseAccess(postgres, {backendID: storageOptions or {}}))
                                destinationFS, destinationRoot = access.resolve(backendID, backend[0])

                            progress(0.07, "Allocating dataset checkpoint")

                            statement = sql.SQL("""
                                INSERT INTO {} (
                                    family_uuid, name, checkpoint_name, description,
                                    metadata, created_by
                                )
                                VALUES (%s::uuid, %s, %s, %s, %s, %s)
                                RETURNING dataset_id
                            """).format(datasetsTable)

                            datasetID = connection.execute(statement, (dataset.uuid, dataset.name, checkpointName, description, Jsonb(metadata), createdBy)).fetchone()[0]

                            statement = sql.SQL("""
                                INSERT INTO {} (
                                    dataset_id, session_id, member_index, entry_name, labels
                                )
                                VALUES (%s, %s, %s, %s, %s)
                            """).format(membersTable)

                            for index, member in enumerate(members):
                                progress(0.07 + 0.02 * index / max(len(members), 1), f"Registering dataset member {index + 1}/{len(members)}")
                                connection.execute(statement, (datasetID, member["sessionID"], index, member["entryName"], Jsonb(member["labels"])))

                            progress(0.09, "Checking dataset members and required ancestors")
                            problems = cls._getDatasetSourceProblems(connection, postgres, datasetID)

                            if problems:
                                problem = problems[0]
                                raise ValueError(f"Cannot save dataset: member session {problem['memberSessionID']} requires active completed source checkpoint {problem['sourceSessionID']}.")

                            # Product-level estimates: working products dominate;
                            # reference-only catalog checks receive small weight.
                            productItems = list(products.items())
                            weights = [1 if isinstance(product, pglDataMatrixReference) else 100 for _, product in productItems]
                            totalWeight = sum(weights)
                            completedWeight = 0

                            for index, ((productName, product), weight) in enumerate(zip(productItems, weights)):
                                start = 0.10 + 0.84 * completedWeight / totalWeight
                                end = 0.10 + 0.84 * (completedWeight + weight) / totalWeight
                                productProgress = progress.section(start, end, label=f"Product {index + 1}/{len(productItems)} {productName}")

                                if isinstance(product, pglDataMatrixReference):
                                    productProgress(0, "Checking saved matrix reference")
                                    revisionID = product.matrixRevisionID

                                    statement = sql.SQL("SELECT contract_version FROM {} WHERE matrix_revision_id = %s::uuid").format(revisionsTable)
                                    registered = connection.execute(statement, (revisionID,)).fetchone()

                                    if registered != ("pgl.matrix.zarr.v1",):
                                        raise ValueError(f"Product {productName!r} references an unknown or unsupported matrix revision.")

                                else:
                                    productProgress(0, "Publishing matrix Zarr bundle")
                                    productRoot = posixpath.join(destinationRoot, "matrices")
                                    savedURL = pglStorage.saveDataMatrix(product, productRoot, filesystem=destinationFS)
                                    savedPath = destinationFS._strip_protocol(savedURL)

                                    productProgress(0.90, "Checking published matrix descriptor")

                                    with destinationFS.open(posixpath.join(savedPath, "matrix.json"), "rb") as source:
                                        descriptorBytes = source.read(16 * 1024 * 1024 + 1)

                                    if len(descriptorBytes) > 16 * 1024 * 1024:
                                        raise ValueError("Published matrix descriptor exceeds the size limit.")

                                    descriptor = json.loads(descriptorBytes)
                                    revisionID = descriptor["matrixRevisionID"]
                                    objectKey = f"matrices/matrix-{revisionID}"
                                    expectedPath = posixpath.join(destinationRoot, objectKey)

                                    if posixpath.normpath(savedPath) != posixpath.normpath(expectedPath):
                                        raise ValueError("Published matrix path differs from its expected backend-relative location.")

                                    productProgress(0.95, "Registering matrix revision")

                                    statement = sql.SQL("""
                                        INSERT INTO {} (
                                            matrix_revision_id, backend_id, object_key,
                                            contract_version, descriptor, created_by
                                        )
                                        VALUES (%s::uuid, %s, %s, %s, %s, %s)
                                    """).format(revisionsTable)

                                    connection.execute(statement, (revisionID, backendID, objectKey, "pgl.matrix.zarr.v1", Jsonb(descriptor), createdBy))

                                productProgress(None, "Attaching dataset product")
                                statement = sql.SQL("INSERT INTO {} (dataset_id, product_name, matrix_revision_id) VALUES (%s, %s, %s::uuid)").format(productsTable)
                                connection.execute(statement, (datasetID, productName, revisionID))
                                productProgress(1, "Product registered")
                                completedWeight += weight

                            progress(0.94, "Rechecking working dataset before publication")
                            cls._requireSafeDatasetCheckpoint(dataset)
                            cls._requireDatasetProductsUnchanged(dataset, products)

                            if dataset.members != members or cls._prepareDatasetMetadata(dataset) != metadata:
                                raise ValueError("Dataset changed while saving. No checkpoint was published.")

                            if cls._datasetAnnotation(dataset.checkpointName, "checkpointName") != checkpointName or cls._datasetAnnotation(dataset.description, "description") != description:
                                raise ValueError("Dataset annotations changed while saving. No checkpoint was published.")

                            progress(0.95, "Completing dataset checkpoint")
                            statement = sql.SQL("UPDATE {} SET status = 'complete', completed_at = statement_timestamp() WHERE dataset_id = %s RETURNING dataset_id").format(datasetsTable)

                            if connection.execute(statement, (datasetID,)).fetchone() != (datasetID,):
                                raise RuntimeError("Dataset checkpoint completion failed.")

                            pendingBaseline = {
                                "version": 1,
                                "datasetID": datasetID,
                                "familyUUID": dataset.uuid,
                                "databaseIdentity": databaseIdentity,
                                "historyHashes": historyHashes,
                            }

                            progress(0.97, "Closing dataset payload access")

                        progress(0.98, "Committing dataset transaction")
                        commitAttempted = True

                    commitConfirmed = True
                    progress(0.99, "Closing PostgreSQL connection and tunnel")

                dataset.datasetID = datasetID
                dataset.checkpointName = checkpointName
                dataset.description = description
                dataset._datasetDatabaseIdentity = databaseIdentity
                dataset._datasetSettings = resolvedSettings
                dataset._datasetSettingsName = None
                dataset._datasetBaseline = pendingBaseline

                progress.finish(f"Dataset checkpoint {datasetID} saved")

        except Exception as error:
            operation = getattr(progress, "_description", operation)

            if not cls._handleCheckpointSaveFailure(error, checkpointKind="Dataset checkpoint", checkpointID=datasetID, operation=operation, commitAttempted=commitAttempted, commitConfirmed=commitConfirmed):
                raise

            return None

        pglMessages.message(f"Dataset checkpoint {datasetID} saved with {len(members)} members and {len(products)} products in {postgres.databaseName}.{postgres.databaseSchema} ({perf_counter() - saveStarted:.1f} s total).")
        return datasetID

    # -------------------------------------------------------------------------
    # Datasets: members and scientific products
    # -------------------------------------------------------------------------
    # Resolve exact member checkpoints, inspect membership, or open and construct dataset products.

    # +++++++++++++++++++++++++++ getDatasetSession +++++++++++++++++++++++++++
    # User-facing database API. See the docstring for configuration, side effects, and return
    # conventions.
    @classmethod
    def getDatasetSession(cls, dataset, sessionID, *, settings=None, settingsName=None, storageOptionsByBackend=None, sslRootCert=None, cacheDirectory=None, directLocalPolicy=None):
        """Resolve an exact member checkpoint and cache its working object.

        Explicit database overrides are checked even for a cache hit.
        Cached session mutation does not alter the membership record.
        """
        dataset._findMember(sessionID=sessionID)
        resolvedSettings, postgres = cls._resolveDatasetStorage(dataset, settings=settings, settingsName=settingsName)

        if postgres is None:
            return None

        if sessionID in dataset._sessionCache:
            return dataset._sessionCache[sessionID]

        options = dict(dataset._datasetLoadOptions)

        if storageOptionsByBackend is not None:
            options["storageOptionsByBackend"] = storageOptionsByBackend

        if sslRootCert is not None:
            options["sslRootCert"] = sslRootCert

        if cacheDirectory is not None:
            options["cacheDirectory"] = cacheDirectory

        if directLocalPolicy is not None:
            options["directLocalPolicy"] = directLocalPolicy

        session = cls.loadSession(sessionID, settings=resolvedSettings, **options)

        if session is None:
            return None

        cls._bindDatasetStorage(dataset, resolvedSettings, postgres)
        dataset._sessionCache[sessionID] = session
        return session

    # +++++++++++++++++++++++++++++ getDatasetData ++++++++++++++++++++++++++++
    # User-facing database API. See the docstring for configuration, side effects, and return
    # conventions.
    # Direct callers in this module: getDatasetBehaviorData.
    # +++++++++++++++++++++++++++++ getDatasetData ++++++++++++++++++++++++++
    @classmethod
    def getDatasetData(cls, dataset, productName, *, settings=None, settingsName=None, storageOptionsByBackend=None, sslRootCert=None):
        """Resolve an attached dataset product and cache its working matrix.

        Called by pglDataset.getData() and getDatasetBehaviorData().

        Existing working matrix:
            Validate the dataset's configured database binding, then return
            the same attached object without reopening its payload.

        Saved matrix reference:
            Validate reference/database correspondence.
            Query the registered revision and backend in a read-only snapshot.
            Close SQL before opening the matrix through _openRegisteredMatrix().
            Resolve server-local roots using the caller's local/SSH context.
            Replace the reference only after successful loading and checks.

        Returns:
            The attached pglDataMatrix, or None for unavailable configuration
            or connection cancellation.

        Missing products raise KeyError. Invalid bindings, inactive backends,
        unsupported products, and catalog/payload errors propagate.

        Reads catalog and matrix/Zarr metadata. Scientific arrays remain lazy.
        Does not extract missing products, evaluate construction freshness,
        or publish records or files.

        An opened matrix owns its payload-access context through its xarray
        close callback. Call matrix.close() only after dependent readers are
        finished. A closed matrix remains attached until explicitly replaced
        or removed; this accessor does not automatically reopen it.

        Concurrent mutation during resolution is unsupported. Detectable
        replacement of the product prevents installing the loaded matrix.
        """
        from psycopg.rows import tuple_row

        from .pglData import pglDataMatrix, pglDataMatrixReference

        if not isinstance(productName, str) or not productName.strip():
            raise ValueError("productName must be a nonblank string.")

        if productName not in dataset.data:
            raise KeyError(f"No attached dataset product: {productName!r}")

        resolvedSettings, postgres = cls._resolveDatasetStorage(dataset, settings=settings, settingsName=settingsName)

        if postgres is None:
            return None

        product = dataset.data[productName]

        if isinstance(product, pglDataMatrix):
            return product

        if not isinstance(product, pglDataMatrixReference):
            raise TypeError(f"Unsupported dataset product: {productName!r}")

        identityJSON = cls._datasetDatabaseIdentityJSON(cls._checkpointDatabaseIdentity(postgres))

        if product.databaseIdentityJSON != identityJSON:
            raise ValueError("Matrix reference belongs to a different configured database.")

        options = dataset._datasetLoadOptions

        if sslRootCert is None:
            sslRootCert = options.get("sslRootCert")

        if storageOptionsByBackend is None:
            storageOptionsByBackend = options.get("storageOptionsByBackend")

        revisions = sql.Identifier(postgres.databaseSchema, "matrix_revisions")
        backends = sql.Identifier(postgres.databaseSchema, "storage_backends")

        with postgres.connect(sslRootCert=sslRootCert) as connection:
            if connection is None:
                return None

            with connection.transaction():
                connection.execute("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ, READ ONLY")

                with connection.cursor(row_factory=tuple_row) as cursor:
                    statement = sql.SQL("""
                        SELECT revision.backend_id,
                               revision.object_key,
                               revision.contract_version,
                               revision.descriptor,
                               backend.url_prefix,
                               backend.is_active
                        FROM {} AS revision
                        JOIN {} AS backend
                          ON backend.backend_id = revision.backend_id
                        WHERE revision.matrix_revision_id = %s::uuid
                    """).format(revisions, backends)

                    cursor.execute(statement, (product.matrixRevisionID,))
                    record = cursor.fetchone()

        if record is None:
            raise ValueError(f"Unknown registered matrix revision: {product.matrixRevisionID}")

        backendID, objectKey, contractVersion, descriptor, registeredRoot, isActive = record

        if not isActive:
            raise ValueError(f"Matrix backend {backendID} is inactive.")

        # SQL and its tunnel have closed. The matrix opener creates separate
        # payload access and retains it for subsequent lazy scientific reads.
        matrix = cls._openRegisteredMatrix(postgres, revisionID=product.matrixRevisionID, backendID=backendID, objectKey=objectKey, contractVersion=contractVersion, descriptor=descriptor, registeredRoot=registeredRoot, storageOptionsByBackend=storageOptionsByBackend)

        try:
            if dataset.data.get(productName) is not product:
                raise ValueError("Dataset product changed while it was being opened.")

            cls._bindDatasetStorage(dataset, resolvedSettings, postgres)
            dataset.data[productName] = matrix

        except BaseException:
            try:
                matrix.close()
            except Exception:
                pass

            raise

        return matrix

    # +++++++++++++++++++++++++ getDatasetBehaviorData ++++++++++++++++++++++
    @classmethod
    def getDatasetBehaviorData(cls, dataset, *, settings=None, settingsName=None, storageOptionsByBackend=None, sslRootCert=None, cacheDirectory=None, directLocalPolicy=None):
        """Return or construct the dataset-owned comprehensive behavior matrix.

        Called by pglDataset.getBehaviorData() and behavioral table access.

        Existing product:
            Resolve through getDatasetData(), validate its behavioral schema,
            and return it. Never silently replace an invalid product or
            automatically rebuild after membership/code changes.

        Missing product:
            Load exact active member checkpoints afresh in membership order.
            Bypass the editable session cache and saved matrix attachments.
            Extract behavioral sources and attach the combined matrix only
            after successful validation.

        Each privately loaded member's unused matrix attachments and checkpoint
        filesystem are closed after extraction. Cached/user-owned sessions are
        not touched. This relies on extractSession() returning scientific
        contents independent of the member's deferred filesystem.

        Reads behavioral payloads; general session loading may also inspect
        matrix/MNE metadata. Does not publish database records or payloads.

        Initial construction retains extracted matrices until assembly and is
        not bounded-memory streaming. Concurrent dataset mutation is unsupported;
        detectable membership, identity, or attachment changes prevent attachment.

        Returns a working pglDataMatrix, or None when configuration or existing
        product resolution returns no result. Other failures propagate.
        """
        from .pglBehavior import pglBehavior

        productName = "behavior"

        if productName in dataset.data:
            matrix = cls.getDatasetData(dataset, productName, settings=settings, settingsName=settingsName, storageOptionsByBackend=storageOptionsByBackend, sslRootCert=sslRootCert)

            if matrix is None:
                return None

            pglBehavior._requireBehaviorData(matrix)
            return matrix

        cls._requireSafeDatasetCheckpoint(dataset)
        members = dataset._validateMembers(dataset.members)

        if not members:
            raise ValueError("Cannot construct behavioral data from an empty dataset.")

        resolvedSettings, postgres = cls._resolveDatasetStorage(dataset, settings=settings, settingsName=settingsName)

        if postgres is None:
            return None

        databaseIdentity = deepcopy(cls._checkpointDatabaseIdentity(postgres))
        originalBinding = deepcopy(dataset._datasetDatabaseIdentity)
        originalDatasetID = dataset.datasetID
        options = dict(dataset._datasetLoadOptions)

        if storageOptionsByBackend is not None:
            options["storageOptionsByBackend"] = storageOptionsByBackend

        if sslRootCert is not None:
            options["sslRootCert"] = sslRootCert

        if cacheDirectory is not None:
            options["cacheDirectory"] = cacheDirectory

        if directLocalPolicy is not None:
            options["directLocalPolicy"] = directLocalPolicy

        # Historical dataset inspection does not authorize construction from
        # deleted source checkpoints.
        options["includeDeleted"] = False

        matrices = []
        combined = None

        try:
            for memberIndex, member in enumerate(members):
                sessionID = member["sessionID"]
                pglMessages.message(f"Constructing dataset behavior: member {memberIndex + 1}/{len(members)}, checkpoint {sessionID}...")

                # Load a private authoritative source, never an editable cached
                # working session.
                session = cls.loadSession(sessionID, settings=resolvedSettings, **options)

                if session is None:
                    raise RuntimeError(f"Cannot construct dataset behavior: member checkpoint {sessionID} could not be loaded.")

                try:
                    if session.sessionID != sessionID:
                        raise ValueError("Loaded session identity differs from the requested member.")

                    baseline = session._checkpointBaseline

                    if baseline.get("databaseIdentity") != databaseIdentity:
                        raise ValueError("Loaded member belongs to a different configured database.")

                    if not session.runs:
                        raise ValueError(f"Member checkpoint {sessionID} has no behavioral runs. Nonbehavioral members are not silently skipped.")

                    # Extract saved behavioral sources rather than reusing
                    # attachments that may describe another working state.
                    matrix = pglBehavior.extractSession(session, name=productName)
                    matrices.append(matrix)

                finally:
                    # These attachments belong to the private loaded session,
                    # not to the extracted matrices retained for assembly.
                    try:
                        for attachment in session.dataMatrices.values():
                            try:
                                attachment.close()
                            except Exception as error:
                                pglMessages.warning(f"Could not close an unused member matrix ({type(error).__name__}).", level=1)
                    finally:
                        # Do not resolve any MNE field merely to clean up.
                        # Behavioral extraction does not need MNE readers.
                        if isinstance(session.filesystem, pglCheckpointFilesystem):
                            try:
                                session.filesystem.close()
                            except Exception as error:
                                pglMessages.warning(f"Could not close a private member checkpoint filesystem ({type(error).__name__}).", level=1)

            combined = pglBehavior.combineSessionData(matrices, members=members, databaseIdentity=databaseIdentity, name=productName)

            # Supplement existing extraction/assembly provenance.
            combined.provenance = {
                **deepcopy(combined.provenance),
                "orchestration": "pglDatabase.getDatasetBehaviorData",
                "sourceState": "freshlyLoadedCheckpointBehavior",
                "datasetCheckpointIDAtConstruction": originalDatasetID,
                "sourceReadPolicy": "Exact member checkpoints loaded afresh; working session cache and saved session matrix attachments not reused",
                "membershipSnapshot": deepcopy(members),
            }

            cls._requireSafeDatasetCheckpoint(dataset)

            if dataset.members != members:
                raise ValueError("Dataset membership changed during behavioral construction; no product was attached.")

            if dataset.datasetID != originalDatasetID or dataset._datasetDatabaseIdentity != originalBinding:
                raise ValueError("Dataset identity/binding changed during behavioral construction; no product was attached.")

            if productName in dataset.data:
                raise ValueError("A behavior product was attached during construction; it was not replaced.")

            pglBehavior._requireBehaviorData(combined)
            pglStorage.validateDataMatrixEncoding(combined.requireData())

            cls._bindDatasetStorage(dataset, resolvedSettings, postgres)
            dataset.data = {**dataset.data, productName: combined}

            pglMessages.message(f"Constructed dataset behavior from {len(members)} member checkpoints. Attached as data['behavior']; not saved.")
            return combined

        except BaseException:
            if combined is not None:
                try:
                    combined.close()
                except Exception:
                    pass

            raise

        finally:
            # The assembler creates independent arrays, so its result does
            # not retain the temporary member matrices.
            for matrix in matrices:
                try:
                    matrix.close()
                except Exception as error:
                    pglMessages.warning(f"Could not close a temporary behavioral matrix ({type(error).__name__}).", level=1)

    # +++++++++++++++++++++++ getDatasetMemberSummaries ++++++++++++++++++++++
    @classmethod
    def getDatasetMemberSummaries(cls, dataset, *, sessionIDs=None, settings=None, settingsName=None, sslRootCert=None, includeBehaviorLabels=False):
        """Read member summaries without constructing sessions or matrices.

        Called by dataset membership validation and printDataset().

        Default:
            Read database metadata only. Acquisition time falls back to the
            root checkpoint. Labels use checkpoint metadata, then root metadata.

        includeBehaviorLabels=True:
            Read verified root experiment-settings files for acquisition
            sessionName values and fallback experiment/subject labels.
            Resolve payload access using the dataset's caller configuration
            and retained runtime backend options.

        SQL closes before payload reads. One short-lived access context reuses
        filesystem connections and closes on success or failure.

        Historical inspection includes deleted source rows and their recorded
        settings locations. Reading them does not restore lifecycle state.

        Returns:
            Mapping from session ID to summary.
            Empty mapping for an empty request.
            None for unavailable configuration or connection cancellation.

        Missing sessions are absent from the mapping. Other errors propagate.
        Does not publish, populate the session cache, or open scientific arrays.
        Successful resolution binds the dataset's runtime configuration.
        """
        from psycopg.rows import tuple_row

        if type(includeBehaviorLabels) is not bool:
            raise ValueError("includeBehaviorLabels must be a boolean.")

        requested = [record["sessionID"] for record in dataset.members] if sessionIDs is None else list(sessionIDs)

        for sessionID in requested:
            dataset._validateSessionID(sessionID)

        requested = sorted(set(requested))

        if not requested:
            return {}

        resolvedSettings, postgres = cls._resolveDatasetStorage(dataset, settings=settings, settingsName=settingsName)

        if postgres is None:
            return None

        if sslRootCert is None:
            sslRootCert = dataset._datasetLoadOptions.get("sslRootCert")

        sessions = sql.Identifier(postgres.databaseSchema, "session")
        links = sql.Identifier(postgres.databaseSchema, "session_files")
        files = sql.Identifier(postgres.databaseSchema, "files")
        locations = sql.Identifier(postgres.databaseSchema, "storage_locations")
        backends = sql.Identifier(postgres.databaseSchema, "storage_backends")

        settingsByRoot = {}
        identities = {}
        locationsByFile = {}

        with postgres.connect(sslRootCert=sslRootCert) as connection:
            if connection is None:
                return None

            with connection.transaction():
                connection.execute("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ, READ ONLY")

                with connection.cursor(row_factory=tuple_row) as cursor:
                    statement = sql.SQL("""
                        SELECT checkpoint.session_id,
                               checkpoint.status,
                               checkpoint.deleted_at,
                               checkpoint.checkpoint_name,
                               checkpoint.created_at,
                               COALESCE(checkpoint.acquired_at, root.acquired_at),
                               checkpoint.meta,
                               root.meta,
                               checkpoint.root_session_id
                        FROM {sessions} AS checkpoint
                        LEFT JOIN {sessions} AS root
                          ON root.session_id = checkpoint.root_session_id
                        WHERE checkpoint.session_id = ANY(%s::bigint[])
                        ORDER BY checkpoint.session_id
                    """).format(sessions=sessions)

                    cursor.execute(statement, (requested,))
                    rows = cursor.fetchall()
                    rootIDs = sorted({row[8] for row in rows if row[8] is not None})

                    if includeBehaviorLabels and rootIDs:
                        # Historical inspection includes deleted links/content.
                        statement = sql.SQL("""
                            SELECT link.session_id, link.name, content.file_id,
                                   content.sha256, content.size_bytes
                            FROM {} AS link
                            JOIN {} AS content ON content.file_id = link.file_id
                            WHERE link.session_id = ANY(%s::bigint[])
                              AND link.name ~ '^runs/[0-9]+/experimentSettings[.]json$'
                            ORDER BY link.session_id, link.name
                        """).format(links, files)

                        cursor.execute(statement, (rootIDs,))

                        for rootID, name, fileID, digest, size in cursor.fetchall():
                            settingsByRoot.setdefault(rootID, []).append((name, fileID))
                            identities[fileID] = {"sha256": digest, "size_bytes": size}

                    if identities:
                        statement = sql.SQL("""
                            SELECT location.file_id, backend.backend_id,
                                   backend.url_prefix, location.object_key
                            FROM {} AS location
                            JOIN {} AS backend ON backend.backend_id = location.backend_id
                            WHERE location.file_id = ANY(%s::bigint[])
                              AND location.status = 'present'
                              AND location.verified_at IS NOT NULL
                              AND backend.is_active
                            ORDER BY location.file_id, location.priority,
                                     backend.backend_id, location.object_key
                        """).format(locations, backends)

                        cursor.execute(statement, (sorted(identities),))

                        for fileID, backendID, root, key in cursor.fetchall():
                            locationsByFile.setdefault(fileID, []).append({
                                "backend_id": backendID,
                                "url_prefix": root,
                                "object_key": key,
                            })

        settingsByFile = {}

        # Default membership validation remains SQL-only. No access context
        # is needed unless verified behavioral settings are actually requested.
        if identities:
            storageOptionsByBackend = dataset._datasetLoadOptions.get("storageOptionsByBackend")

            with pglDatabaseAccess(postgres, storageOptionsByBackend) as access:
                for fileID, identity in identities.items():
                    candidates = locationsByFile.get(fileID, [])

                    if not candidates:
                        raise FileNotFoundError(f"Experiment-settings file {fileID} has no eligible registered location.")

                    settingsByFile[fileID] = cls._readPrintExperimentSettings(identity, candidates, accessContext=access)

        labelsByRoot = {}

        # ++++++++++++++++++++++++++++ addLabel +++++++++++++++++++++++++++++
        def addLabel(values, value, fieldName):
            """Collect distinct nonblank labels without changing saved text."""
            if value is None:
                return

            if not isinstance(value, str):
                raise ValueError(f"Saved {fieldName} must be a string or None.")

            if value.strip() and value not in values:
                values.append(value)

        for rootID, records in settingsByRoot.items():
            labels = {"experimentNames": [], "subjectIDs": [], "sessionNames": []}

            for name, fileID in sorted(records, key=lambda item: int(item[0].split("/")[1])):
                savedSettings = settingsByFile[fileID]
                addLabel(labels["experimentNames"], savedSettings.get("experimentName"), "experimentName")
                addLabel(labels["subjectIDs"], savedSettings.get("subjectID"), "subjectID")
                addLabel(labels["sessionNames"], savedSettings.get("sessionName"), "sessionName")

            labelsByRoot[rootID] = labels

        summaries = {}

        for sessionID, status, deletedAt, checkpointName, createdAt, acquiredAt, checkpointMeta, rootMeta, rootID in rows:
            labelMetadata = None

            for metadata in (checkpointMeta, rootMeta):
                if isinstance(metadata, dict) and "pgl_session_labels" in metadata:
                    labelMetadata = cls._validateSessionLabelMetadata(metadata["pgl_session_labels"])
                    break

            rootLabels = labelsByRoot.get(rootID, {"experimentNames": [], "subjectIDs": [], "sessionNames": []})

            if labelMetadata is not None:
                experimentNames = sorted({record["experimentName"] for record in labelMetadata["labels"] if record["experimentName"] is not None})
                subjectIDs = sorted({record["subjectID"] for record in labelMetadata["labels"] if record["subjectID"] is not None})
            else:
                experimentNames = list(rootLabels["experimentNames"])
                subjectIDs = sorted(rootLabels["subjectIDs"])

            summaries[sessionID] = {
                "sessionID": sessionID,
                "status": status,
                "deletedAt": deletedAt,
                "checkpointName": checkpointName,
                "createdAt": createdAt,
                "acquiredAt": acquiredAt,
                "experimentNames": experimentNames,
                "subjectIDs": subjectIDs,
                "sessionNames": list(rootLabels["sessionNames"]),
            }

        cls._bindDatasetStorage(dataset, resolvedSettings, postgres)
        return summaries


    # -------------------------------------------------------------------------
    # Datasets: lifecycle
    # -------------------------------------------------------------------------
    # User entry points for dataset soft deletion and restoration of source protection.

    # +++++++++++++++++++++++++++++ deleteDataset +++++++++++++++++++++++++++++
    # User-facing database API. See the docstring for configuration, side effects, and return
    # conventions.
    @classmethod
    def deleteDataset(cls, datasetID, *, settings=None, settingsName=None, sslRootCert=None):
        """Soft-delete one completed dataset checkpoint.

        Releases this checkpoint's session protection. Other active dataset
        versions continue protecting their own members and ancestors.

        Preserves membership, history, scientific products, and sessions.
        Does not inspect, delete, or rewrite payloads.

        Returns True for a committed change, False for an unchanged,
        unknown, or blocked operation, and None for invalid arguments,
        unavailable configuration/connection, or database failure.
        """
        return cls._changeDatasetDeletionState(datasetID, deleted=True, settings=settings, settingsName=settingsName, sslRootCert=sslRootCert)

    # ++++++++++++++++++++++++++++ undeleteDataset ++++++++++++++++++++++++++++
    # User-facing database API. See the docstring for configuration, side effects, and return
    # conventions.
    @classmethod
    def undeleteDataset(cls, datasetID, *, settings=None, settingsName=None, sslRootCert=None):
        """Restore one completed dataset checkpoint.

        Every member and required ancestor must be complete and active.
        Refusal warns and leaves the dataset deleted.

        Does not restore sessions automatically or inspect payloads.

        Returns True for a committed change, False for an unchanged,
        unknown, or blocked operation, and None for invalid arguments,
        unavailable configuration/connection, or database failure.
        """
        return cls._changeDatasetDeletionState(datasetID, deleted=False, settings=settings, settingsName=settingsName, sslRootCert=sslRootCert)


    # -------------------------------------------------------------------------
    # Database reporting
    # -------------------------------------------------------------------------
    # User-facing reports. Individual docstrings identify metadata-only reports and verified
    # settings reads.

    # +++++++++++++++++++++++++++++++++ print +++++++++++++++++++++++++++++++++
    # User-facing database API. See the docstring for configuration, side effects, and return
    # conventions.
    @staticmethod
    @_postgresReadAvailability
    def print(details=None, postgres=None, *, settings=None, settingsName=None, sessionID=None, summary=False, datasets=False, nRows=10, maxWidth=48, sslRootCert=None, includeDeleted=False, storageOptionsByBackend=None, experimentName=None, subjectID=None, dateRange=None, checkpointDateRange=None):
        """Select a session listing, dataset listing, or database report.

        Default:
            List visible sessions grouped by root experiment and subject,
            displaying actual parent-child relationships.

        Session listing filters:
            experimentName:
                Exact root experiment label.
            subjectID:
                Exact root subject label.
            dateRange:
                Inclusive UTC calendar-date range for root acquisition time.
            checkpointDateRange:
                Inclusive UTC calendar-date range for checkpoint creation time.

            Date ranges are (start, end), using ISO date strings or Python
            date objects. Either endpoint may be None.

            Supplied filters combine with AND. Experiment and subject must
            match the same root label pair. Visible ancestors of matching
            checkpoints are retained as explicitly marked context.

        datasets=True:
            List visible dataset checkpoints grouped by dataset name.
            Show checkpoint names, member counts, and scientific product names.
            Does not load datasets, sessions, or scientific payloads.

        summary=True:
            Show database table counts and session statuses.

        sessionID:
            Show one session checkpoint's metadata, subjects, and linked files.

        details:
            Show one table, an iterable of tables, or "all".

        datasets, summary, sessionID, and details are mutually exclusive.
        Session listing filters cannot be used with those selections.
        nRows limits table detail views only, not readable listings.

        includeDeleted includes soft-deleted checkpoints.
        storageOptionsByBackend applies to the session listing's verified
        acquisition-settings reads.

        Read-only; does not publish or modify records.
        """
        if type(summary) is not bool:
            raise ValueError("summary must be a boolean.")

        if type(datasets) is not bool:
            raise ValueError("datasets must be a boolean.")

        if type(includeDeleted) is not bool:
            raise ValueError("includeDeleted must be a boolean.")

        if type(nRows) is not int or nRows <= 0:
            raise ValueError("nRows must be a positive integer.")

        if type(maxWidth) is not int or maxWidth < 8:
            raise ValueError("maxWidth must be an integer of at least 8.")

        selectedModes = sum((details is not None, sessionID is not None, summary, datasets))

        if selectedModes > 1:
            raise ValueError("Supply only one of details, sessionID, summary=True, or datasets=True.")

        hasSessionFilters = any(value is not None for value in (experimentName, subjectID, dateRange, checkpointDateRange))

        if selectedModes and hasSessionFilters:
            raise ValueError("experimentName, subjectID, dateRange, and checkpointDateRange apply only to the session listing.")

        if datasets:
            return pglDatabase.printDatasets(postgres=postgres, settings=settings, settingsName=settingsName, sslRootCert=sslRootCert, includeDeleted=includeDeleted)

        if sessionID is not None:
            return pglDatabase.printSession(sessionID, postgres=postgres, settings=settings, settingsName=settingsName, sslRootCert=sslRootCert, includeDeleted=includeDeleted)

        if details is not None or summary:
            return pglDatabase.printTables(details=details, postgres=postgres, settings=settings, settingsName=settingsName, nRows=nRows, maxWidth=maxWidth, sslRootCert=sslRootCert, includeDeleted=includeDeleted)

        return pglDatabase.printSessions(postgres=postgres, settings=settings, settingsName=settingsName, sslRootCert=sslRootCert, includeDeleted=includeDeleted, storageOptionsByBackend=storageOptionsByBackend, experimentName=experimentName, subjectID=subjectID, dateRange=dateRange, checkpointDateRange=checkpointDateRange)

    # ++++++++++++++++++++++++++++++ printSession +++++++++++++++++++++++++++++
    # User-facing database API.
    # Direct callers in this module: print.
    @staticmethod
    @_postgresReadAvailability
    def printSession(sessionID, postgres=None, *, settings=None, settingsName=None, sslRootCert=None, includeDeleted=False):
        """Print one checkpoint's metadata, linked subjects, and linked files.

        Shows:
            All session-row metadata and creator labels.
            Distinct subject IDs recorded on visible file links.
            One preferred registered location per logical file.
            The number of other visible registered locations.

        Subjects are collected from file links, not reconstructed sessions.
        Registered locations are catalog paths, not caller-resolved SSH paths.
        Location eligibility describes recorded metadata only; it does not
        establish current accessibility or successful session reconstruction.

        Reads database metadata in one consistent, read-only snapshot.
        Does not reconstruct sessions, open payloads, verify bytes, or modify
        database records. Full file paths are printed without truncation.

        includeDeleted permits historical inspection without restoring records.

        Returns:
            True after printing the report.
            False for unavailable configuration, connection cancellation,
            or an absent/deletion-filtered session.
            Other errors propagate.

        Examples:
            # Inspect one checkpoint through the main print interface.
            pglDatabase.print(sessionID=77)

            # Call the single-checkpoint report directly.
            pglDatabase.printSession(77)

            # Include soft-deleted session/file/location records.
            pglDatabase.printSession(77, includeDeleted=True)

            # Use a caller-supplied PostgreSQL configuration.
            pglDatabase.printSession(77, postgres=postgres)

            # Use a named settings configuration.
            pglDatabase.printSession(77, settingsName="mySettings")
        """
        from psycopg.rows import tuple_row

        if type(sessionID) is not int or not 0 <= sessionID <= 9223372036854775807:
            raise ValueError("sessionID must be a nonnegative PostgreSQL bigint.")

        if type(includeDeleted) is not bool:
            raise ValueError("includeDeleted must be a boolean.")

        postgres = pglDatabase._printPostgres(postgres, settings=settings, settingsName=settingsName)

        if postgres is None:
            return False

        sessionsTable = sql.Identifier(postgres.databaseSchema, "session")
        usersTable = sql.Identifier(postgres.databaseSchema, "users")
        linksTable = sql.Identifier(postgres.databaseSchema, "session_files")
        filesTable = sql.Identifier(postgres.databaseSchema, "files")
        locationsTable = sql.Identifier(postgres.databaseSchema, "storage_locations")
        backendsTable = sql.Identifier(postgres.databaseSchema, "storage_backends")

        sessionRecord = None
        sessionFiles = {}
        locationsByFile = {}

        with postgres.connect(sslRootCert=sslRootCert) as connection:
            if connection is None:
                return False

            with connection.transaction():
                connection.execute("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ, READ ONLY")

                with connection.cursor(row_factory=tuple_row) as cursor:
                    cursor.execute("SELECT current_database(), transaction_timestamp()")
                    databaseName, snapshotTime = cursor.fetchone()

                    statement = sql.SQL("""
                        SELECT checkpoint.*,
                               creator.username AS creator_username,
                               creator.display_name AS creator_display_name
                        FROM {} AS checkpoint
                        LEFT JOIN {} AS creator
                          ON creator.user_id = checkpoint.created_by
                        WHERE checkpoint.session_id = %s
                          AND (%s OR checkpoint.deleted_at IS NULL)
                    """).format(sessionsTable, usersTable)
                    cursor.execute(statement, (sessionID, includeDeleted))
                    row = cursor.fetchone()

                    if row is not None:
                        sessionRecord = dict(zip((column.name for column in cursor.description), row))

                        statement = sql.SQL("""
                            SELECT link.name,
                                   link.role,
                                   link.subject_id,
                                   content.file_id,
                                   content.sha256,
                                   content.size_bytes,
                                   link.deleted_at,
                                   content.deleted_at
                            FROM {} AS link
                            JOIN {} AS content ON content.file_id = link.file_id
                            WHERE link.session_id = %s
                              AND (%s OR (link.deleted_at IS NULL AND content.deleted_at IS NULL))
                            ORDER BY link.name
                        """).format(linksTable, filesTable)
                        cursor.execute(statement, (sessionID, includeDeleted))

                        for name, role, subjectID, fileID, digest, size, linkDeleted, contentDeleted in cursor.fetchall():
                            sessionFiles[name] = {
                                "role": role,
                                "subject_id": subjectID,
                                "file_id": fileID,
                                "sha256": digest,
                                "size_bytes": size,
                                "link_deleted_at": linkDeleted,
                                "content_deleted_at": contentDeleted,
                            }

                        fileIDs = sorted({record["file_id"] for record in sessionFiles.values()})

                        if fileIDs:
                            statement = sql.SQL("""
                                SELECT location.file_id,
                                       location.object_key,
                                       backend.backend_id,
                                       backend.name,
                                       backend.url_prefix,
                                       backend.is_active,
                                       location.status,
                                       location.priority,
                                       location.verified_at,
                                       location.deleted_at
                                FROM {} AS location
                                JOIN {} AS backend
                                  ON backend.backend_id = location.backend_id
                                WHERE location.file_id = ANY(%s::bigint[])
                                  AND (%s OR location.deleted_at IS NULL)
                                ORDER BY location.file_id,
                                         location.priority,
                                         backend.backend_id,
                                         location.object_key
                            """).format(locationsTable, backendsTable)
                            cursor.execute(statement, (fileIDs, includeDeleted))

                            for fileID, key, backendID, backendName, root, active, status, priority, verifiedAt, deletedAt in cursor.fetchall():
                                locationsByFile.setdefault(fileID, []).append({
                                    "object_key": key,
                                    "backend_id": backendID,
                                    "backend_name": backendName,
                                    "root": root,
                                    "active": active,
                                    "status": status,
                                    "priority": priority,
                                    "verified_at": verifiedAt,
                                    "deleted_at": deletedAt,
                                })

        if sessionRecord is None:
            pglMessages.warning(f"No visible session {sessionID} found in {databaseName}.{postgres.databaseSchema}; it may be absent or excluded by the deletion filter.", level=0)
            return False

        # ++++++++++++++++++++++++++++++ expectedKey ++++++++++++++++++++++++++++++
        def expectedKey(name):
            """Prefer a checkpoint-local alias when one is registered.

            This is only a display preference. Shared content can legitimately
            have its preferred location in another run or session.
            """
            if sessionRecord["contract_version"] == "pgl.raw.behavior.v1":
                parts = name.split("/", 2)

                if len(parts) == 3 and parts[0] == "runs" and parts[1].isascii() and parts[1].isdigit():
                    return f"session{sessionID:06d}/run{int(parts[1]):05d}/{parts[2]}"

            return f"session{sessionID:06d}/{name}"

        # ++++++++++++++++++++++++++++++++ eligible +++++++++++++++++++++++++++++++
        def eligible(location):
            """Evaluate recorded location eligibility without accessing storage."""
            return location["active"] and location["status"] == "present" and location["verified_at"] is not None and (includeDeleted or location["deleted_at"] is None)

        deletionLabel = " [DELETED]" if sessionRecord["deleted_at"] is not None else ""
        pglMessages.printHeader(f"Session {sessionID}{deletionLabel}")
        pglMessages.message(f"Database: {databaseName}.{postgres.databaseSchema}", wrapText=False)
        pglMessages.message(f"Snapshot transaction started: {snapshotTime}", wrapText=False)
        pglMessages.print()
        pglMessages.printHeader("Session metadata", fillChar="-")
        labelWidth = max(len(name) for name in sessionRecord)

        for name, value in sessionRecord.items():
            pglMessages.print(f"  {name:<{labelWidth}} : {pglDatabase._printValue(value)}")

        subjects = sorted({record["subject_id"] for record in sessionFiles.values() if record["subject_id"] is not None})
        pglMessages.print()
        pglMessages.printHeader("Subjects from file links", fillChar="-")
        pglMessages.print("  " + (", ".join(pglDatabase._printValue(subject) for subject in subjects) if subjects else "(none linked)"))

        pglMessages.print()
        pglMessages.printHeader(f"Files and locations: {len(sessionFiles)} linked files", fillChar="-")
        pglMessages.print("  One recorded content location per file; shared files may resolve into another run or session.")
        pglMessages.print("  Status and eligibility are recorded metadata; payloads and caller access have not been checked.")
        pglMessages.print("  Locations are registered paths, not caller-resolved SSH paths.")
        pglMessages.print("  Registered aliases/copies are paths, not necessarily separate physical byte copies.")

        if includeDeleted:
            pglMessages.print("  Including deleted records. Location eligibility below assumes this inspection override.")

        if not sessionFiles:
            pglMessages.print("  (no linked files)")

        for name, record in sessionFiles.items():
            preferredKey = expectedKey(name)
            candidates = locationsByFile.get(record["file_id"], [])
            ordered = sorted(candidates, key=lambda location: (
                not eligible(location),
                location["object_key"] != preferredKey,
                location["priority"],
                location["backend_id"],
                location["object_key"],
            ))

            pglMessages.print()
            pglMessages.print(f"  {pglDatabase._printValue(name)}")
            pglMessages.print(f"    file_id: {record['file_id']} | bytes: {record['size_bytes']} | role: {pglDatabase._printValue(record['role'])}")

            if includeDeleted:
                linkState = "DELETED" if record["link_deleted_at"] is not None else "active"
                contentState = "DELETED" if record["content_deleted_at"] is not None else "active"
                pglMessages.print(f"    File link: {linkState} | shared content identity: {contentState}")

            if not ordered:
                pglMessages.print("    No visible registered storage location.")
                continue

            location = ordered[0]
            separator = "" if location["root"].endswith("/") else "/"
            fullLocation = location["root"] + separator + location["object_key"]

            pglMessages.print(f"    Location: {pglDatabase._printValue(fullLocation)}")
            pglMessages.print(f"    Backend: {location['backend_id']} | status: {pglDatabase._printValue(location['status'])} | active: {location['active']} | catalog-eligible location: {eligible(location)}")
            pglMessages.print(f"    Last verified: {pglDatabase._printValue(location['verified_at'])}")

            if includeDeleted:
                locationState = "DELETED" if location["deleted_at"] is not None else "active"
                pglMessages.print(f"    Location deletion state: {locationState}")

            if len(ordered) > 1:
                pglMessages.print(f"    Other visible registered aliases/copies: {len(ordered) - 1}")

        pglMessages.printHeader()
        return True

    # +++++++++++++++++++++++++++++ printSessions +++++++++++++++++++++++++++
    # +++++++++++++++++++++++++++++ printSessions +++++++++++++++++++++++++++
    @staticmethod
    @_postgresReadAvailability
    def printSessions(postgres=None, *, settings=None, settingsName=None, sslRootCert=None, includeDeleted=False, storageOptionsByBackend=None, experimentName=None, subjectID=None, dateRange=None, checkpointDateRange=None):
        """Print sessions grouped by root experiment and subject.

        Called directly or by print() with its default selection.

        Parentless roots display acquisition sessionName values in brackets.
        Descendants display database checkpoint names in parentheses.
        Descriptions are omitted; actual parent-child relationships are shown.

        Filters:
            experimentName / subjectID:
                Exact matches against the same root grouping-label pair.
                Only matching groups are displayed.

            dateRange:
                Inclusive UTC calendar dates for the root's acquired_at.
                Descendants inherit this original acquisition timestamp.

            checkpointDateRange:
                Inclusive UTC calendar dates for each checkpoint's created_at.

            Date ranges accept (start, end), with ISO date strings or Python
            date objects. None endpoints are open. Missing timestamps do not
            match a supplied date range, including (None, None).

            All supplied filters combine with AND. Visible ancestors of
            matching checkpoints are retained and marked [context].
            Nonmatching descendants are not included automatically.

        Timezone-naive database timestamps are interpreted as UTC.

        Reads catalog metadata in a consistent SQL snapshot. After SQL closes,
        reads verified root experiment-settings files through caller-resolved
        local/SSH access. One report-owned context reuses filesystem connections
        and closes before output is printed.

        Mirrored root labels supply grouping when present. Older behavioral
        roots fall back to archived settings. Descendants inherit root grouping.
        Acquisition settings are still read for sessionName, which is not
        included in mirrored label metadata.

        Does not reconstruct sessions, open MNE/scientific matrix payloads, or
        modify records. Returns False for unavailable configuration or
        connection cancellation; other errors propagate.
        """
        from datetime import date, datetime, timezone
        from psycopg.rows import tuple_row

        if type(includeDeleted) is not bool:
            raise ValueError("includeDeleted must be a boolean.")

        for fieldName, value in (("experimentName", experimentName), ("subjectID", subjectID)):
            if value is not None and (not isinstance(value, str) or not value.strip()):
                raise ValueError(f"{fieldName} must be a nonblank string or None.")

        dateRange = pglDatabase._printDateRange(dateRange, "dateRange")
        checkpointDateRange = pglDatabase._printDateRange(checkpointDateRange, "checkpointDateRange")
        hasFilters = any(value is not None for value in (experimentName, subjectID, dateRange, checkpointDateRange))

        # +++++++++++++++++++++++++++ matchesDate +++++++++++++++++++++++++++
        def matchesDate(timestamp, bounds):
            """Compare a database timestamp using its UTC calendar date."""
            if bounds is None:
                return True

            if timestamp is None:
                return False

            if isinstance(timestamp, datetime):
                if timestamp.tzinfo is None or timestamp.utcoffset() is None:
                    timestamp = timestamp.replace(tzinfo=timezone.utc)

                calendarDate = timestamp.astimezone(timezone.utc).date()
            elif isinstance(timestamp, date):
                calendarDate = timestamp
            else:
                raise ValueError("Database acquisition/creation timestamps must be datetime or date values.")

            startDate, endDate = bounds
            return (startDate is None or calendarDate >= startDate) and (endDate is None or calendarDate <= endDate)

        # +++++++++++++++++++++++++++ rangeLabel ++++++++++++++++++++++++++++
        def rangeLabel(bounds):
            """Format inclusive calendar-date boundaries for the report."""
            startDate, endDate = bounds
            startLabel = startDate.isoformat() if startDate is not None else "unbounded"
            endLabel = endDate.isoformat() if endDate is not None else "unbounded"
            return f"{startLabel} through {endLabel} (inclusive UTC dates)"

        postgres = pglDatabase._printPostgres(postgres, settings=settings, settingsName=settingsName)

        if postgres is None:
            return False

        sessionsTable = sql.Identifier(postgres.databaseSchema, "session")
        linksTable = sql.Identifier(postgres.databaseSchema, "session_files")
        filesTable = sql.Identifier(postgres.databaseSchema, "files")
        locationsTable = sql.Identifier(postgres.databaseSchema, "storage_locations")
        backendsTable = sql.Identifier(postgres.databaseSchema, "storage_backends")

        records = {}
        recordsByRoot = {}
        matchingIDsByRoot = {}
        groupsByRoot = {}
        settingsByRoot = {}
        identities = {}
        locationsByFile = {}

        with postgres.connect(sslRootCert=sslRootCert) as connection:
            if connection is None:
                return False

            with connection.transaction():
                connection.execute("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ, READ ONLY")

                with connection.cursor(row_factory=tuple_row) as cursor:
                    cursor.execute("SELECT current_database(), transaction_timestamp()")
                    databaseName, snapshotTime = cursor.fetchone()

                    # Original acquisition time comes from the root, not the
                    # descendant's creation time or any overridden timestamp.
                    # Reading a deleted root's date does not display that root.
                    statement = sql.SQL("""
                        SELECT checkpoint.session_id,
                               checkpoint.parent_session_id,
                               checkpoint.root_session_id,
                               checkpoint.origin,
                               checkpoint.status,
                               checkpoint.deleted_at,
                               checkpoint.meta,
                               checkpoint.checkpoint_name,
                               checkpoint.created_at,
                               root.acquired_at
                        FROM {sessions} AS checkpoint
                        LEFT JOIN {sessions} AS root
                          ON root.session_id = checkpoint.root_session_id
                        WHERE (%s OR checkpoint.deleted_at IS NULL)
                        ORDER BY checkpoint.session_id
                    """).format(sessions=sessionsTable)
                    cursor.execute(statement, (includeDeleted,))

                    for sessionID, parentID, rootID, origin, status, deletedAt, meta, checkpointName, createdAt, acquiredAt in cursor.fetchall():
                        record = {
                            "session_id": sessionID,
                            "parent_session_id": parentID,
                            "root_session_id": rootID,
                            "origin": origin,
                            "status": status,
                            "deleted_at": deletedAt,
                            "meta": meta,
                            "checkpoint_name": checkpointName,
                            "created_at": createdAt,
                            "acquired_at": acquiredAt,
                            "session_names": [],
                        }
                        records[sessionID] = record
                        recordsByRoot.setdefault(rootID, {})[sessionID] = record

                        if matchesDate(acquiredAt, dateRange) and matchesDate(createdAt, checkpointDateRange):
                            matchingIDsByRoot.setdefault(rootID, set()).add(sessionID)

                    # Only date-eligible families need grouping/settings reads.
                    rootIDs = sorted(matchingIDsByRoot)
                    visibleRootIDs = []

                    for rootID in rootIDs:
                        record = records.get(rootID)

                        if record is None:
                            groupsByRoot[rootID] = {("Unknown", "Unknown")}
                            continue

                        visibleRootIDs.append(rootID)
                        meta = record["meta"] or {}

                        if "pgl_session_labels" in meta:
                            metadata = pglDatabase._validateSessionLabelMetadata(meta["pgl_session_labels"])
                            groupsByRoot[rootID] = {
                                (
                                    label["experimentName"] if label["experimentName"] is not None else "Unknown",
                                    label["subjectID"] if label["subjectID"] is not None else "Unknown",
                                )
                                for label in metadata["labels"]
                            }

                    # Eligible visible behavioral roots need acquisition
                    # settings for sessionName, even with mirrored labels.
                    if visibleRootIDs:
                        statement = sql.SQL("""
                            SELECT link.session_id, link.name, content.file_id,
                                   content.sha256, content.size_bytes
                            FROM {} AS link
                            JOIN {} AS content ON content.file_id = link.file_id
                            WHERE link.session_id = ANY(%s::bigint[])
                              AND link.name ~ '^runs/[0-9]+/experimentSettings[.]json$'
                              AND (%s OR (link.deleted_at IS NULL AND content.deleted_at IS NULL))
                            ORDER BY link.session_id, link.name
                        """).format(linksTable, filesTable)
                        cursor.execute(statement, (visibleRootIDs, includeDeleted))

                        for rootID, name, fileID, digest, size in cursor.fetchall():
                            settingsByRoot.setdefault(rootID, []).append((name, fileID))
                            identities[fileID] = {"sha256": digest, "size_bytes": size}

                    if identities:
                        statement = sql.SQL("""
                            SELECT location.file_id, backend.backend_id,
                                   backend.url_prefix, location.object_key
                            FROM {} AS location
                            JOIN {} AS backend ON backend.backend_id = location.backend_id
                            WHERE location.file_id = ANY(%s::bigint[])
                              AND (%s OR location.deleted_at IS NULL)
                              AND location.status = 'present'
                              AND location.verified_at IS NOT NULL
                              AND backend.is_active
                            ORDER BY location.file_id, location.priority,
                                     backend.backend_id, location.object_key
                        """).format(locationsTable, backendsTable)
                        cursor.execute(statement, (sorted(identities), includeDeleted))

                        for fileID, backendID, root, key in cursor.fetchall():
                            locationsByFile.setdefault(fileID, []).append({
                                "backend_id": backendID,
                                "url_prefix": root,
                                "object_key": key,
                            })

        # SQL is closed. No deferred reader escapes this report, so its access
        # context can be closed after collecting the verified settings.
        settingsByFile = {}

        if identities:
            with pglDatabaseAccess(postgres, storageOptionsByBackend) as access:
                for fileID, identity in identities.items():
                    candidates = locationsByFile.get(fileID, [])

                    if not candidates:
                        raise FileNotFoundError(f"Experiment-settings file {fileID} has no eligible registered location.")

                    settingsByFile[fileID] = pglDatabase._readPrintExperimentSettings(identity, candidates, accessContext=access)

        for rootID in rootIDs:
            record = records.get(rootID)

            if record is None:
                continue

            sessionNames = []
            pairs = set()
            needsGrouping = rootID not in groupsByRoot
            runSettings = sorted(settingsByRoot.get(rootID, []), key=lambda item: int(item[0].split("/")[1]))

            for name, fileID in runSettings:
                savedSettings = settingsByFile[fileID]
                sessionName = savedSettings.get("sessionName")

                if sessionName is not None:
                    if not isinstance(sessionName, str):
                        raise ValueError(f"Saved sessionName must be a string or None: root {rootID}, {name}")

                    if sessionName.strip() and sessionName not in sessionNames:
                        sessionNames.append(sessionName)

                if needsGrouping:
                    experiment = pglDatabase._printGroupingValue(savedSettings.get("experimentName"), "experimentName")
                    subject = pglDatabase._printGroupingValue(savedSettings.get("subjectID"), "subjectID")
                    pairs.add((experiment, subject))

            record["session_names"] = sessionNames

            if needsGrouping:
                groupsByRoot[rootID] = pairs or {("Unknown", "Unknown")}

        grouped = {}
        displayedIDs = set()
        matchedIDs = set()

        for rootID in rootIDs:
            # Test experiment and subject together against each saved pair.
            # A root with (experimentA, subject1) and (experimentB, subject2)
            # must not match experimentA + subject2.
            matchingPairs = {
                (experiment, subject)
                for experiment, subject in groupsByRoot[rootID]
                if (experimentName is None or experiment == experimentName)
                and (subjectID is None or subject == subjectID)
            }

            if not matchingPairs:
                continue

            rootRecords = recordsByRoot[rootID]
            rootMatches = matchingIDsByRoot[rootID]
            includedIDs = set(rootMatches)

            # Preserve actual parent-child relationships. Stop at hidden or
            # missing parents instead of drawing artificial ancestor arrows.
            # The formatter performs the final lineage cycle validation.
            for sessionID in sorted(rootMatches):
                parentID = rootRecords[sessionID]["parent_session_id"]

                while parentID in rootRecords and parentID not in includedIDs:
                    includedIDs.add(parentID)
                    parentID = rootRecords[parentID]["parent_session_id"]

            selectedRecords = {}

            for sessionID in sorted(includedIDs):
                record = dict(rootRecords[sessionID])
                record["filter_context"] = sessionID not in rootMatches
                selectedRecords[sessionID] = record

            for experiment, subject in matchingPairs:
                grouped.setdefault(experiment, {}).setdefault(subject, {}).update(selectedRecords)

            displayedIDs.update(includedIDs)
            matchedIDs.update(rootMatches)

        # +++++++++++++++++++++++++++ groupOrder ++++++++++++++++++++++++++++
        def groupOrder(value):
            """Sort labels case-insensitively, with Unknown last."""
            return (value == "Unknown", value.casefold(), value)

        output = []

        for experiment in sorted(grouped, key=groupOrder):
            output.append(pglDatabase._printValue(experiment))

            for subject in sorted(grouped[experiment], key=groupOrder):
                output.append("  " + pglDatabase._printValue(subject))
                output.extend(pglDatabase._sessionLineageLines(grouped[experiment][subject]))

            output.append("")

        pglMessages.printHeader("Sessions")
        pglMessages.message(f"Database: {databaseName}.{postgres.databaseSchema}", wrapText=False)
        pglMessages.message(f"Metadata snapshot: {snapshotTime}", wrapText=False)
        pglMessages.print("  Including deleted sessions." if includeDeleted else "  Deleted sessions excluded.")

        if experimentName is not None:
            pglMessages.print(f"  Experiment filter: {pglDatabase._printValue(experimentName)}")

        if subjectID is not None:
            pglMessages.print(f"  Subject filter: {pglDatabase._printValue(subjectID)}")

        if dateRange is not None:
            pglMessages.print(f"  Original acquisition: {rangeLabel(dateRange)}")

        if checkpointDateRange is not None:
            pglMessages.print(f"  Checkpoint creation: {rangeLabel(checkpointDateRange)}")

        if hasFilters:
            contextCount = len(displayedIDs - matchedIDs)
            pglMessages.print(f"  Matching checkpoints: {len(matchedIDs)} | Context ancestors: {contextCount}")

            if contextCount:
                pglMessages.print("  [context] marks ancestors shown for lineage only; they do not match all filters.")

        pglMessages.print()

        if not grouped:
            pglMessages.print("  (no matching visible sessions)" if hasFilters else "  (no visible sessions)")
        else:
            for line in output:
                pglMessages.print(line)

        pglMessages.printHeader()
        return True
    # +++++++++++++++++++++++++++++ printDatasets +++++++++++++++++++++++++++++
    # User-facing database API. See the docstring for configuration, side effects, and return
    # conventions.
    # Direct callers in this module: print.
    def printDatasets(postgres=None, *, settings=None, settingsName=None, sslRootCert=None, includeDeleted=False):
        """Print saved dataset checkpoints grouped by name.

        Shows:
            Dataset ID.
            Optional checkpoint name.
            Deleted/incomplete state markers.
            Saved member count.
            Scientific product names.

        Distinct families sharing a name are labeled by family UUID.
        No parent-child lineage is inferred between dataset checkpoints.
        Descriptions are omitted; names are not truncated.

        Counts describe recorded membership, not current source availability.
        Product names do not establish construction freshness.

        Reads database metadata in one consistent snapshot.
        Does not reconstruct datasets/sessions, open matrix payloads,
        or modify database records.

        Returns False for unavailable configuration/connection.
        Other errors propagate.
        """
        from psycopg.rows import tuple_row

        if type(includeDeleted) is not bool:
            raise ValueError("includeDeleted must be a boolean.")

        postgres = pglDatabase._printPostgres(postgres, settings=settings, settingsName=settingsName)

        if postgres is None:
            return False

        datasetsTable = sql.Identifier(postgres.databaseSchema, "dataset")
        membersTable = sql.Identifier(postgres.databaseSchema, "dataset_members")
        productsTable = sql.Identifier(postgres.databaseSchema, "dataset_products")

        with postgres.connect(sslRootCert=sslRootCert) as connection:
            if connection is None:
                return False

            with connection.transaction():
                connection.execute("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ, READ ONLY")

                with connection.cursor(row_factory=tuple_row) as cursor:
                    cursor.execute("SELECT current_database(), transaction_timestamp()")
                    databaseName, snapshotTime = cursor.fetchone()

                    # Separate correlated queries avoid multiplying membership
                    # rows by product rows when calculating counts.
                    statement = sql.SQL("""
                        SELECT checkpoint.dataset_id,
                               checkpoint.family_uuid::text,
                               checkpoint.name,
                               checkpoint.checkpoint_name,
                               checkpoint.status,
                               checkpoint.deleted_at,
                               (
                                   SELECT count(*)
                                   FROM {members} AS membership
                                   WHERE membership.dataset_id = checkpoint.dataset_id
                               ) AS member_count,
                               ARRAY(
                                   SELECT product.product_name
                                   FROM {products} AS product
                                   WHERE product.dataset_id = checkpoint.dataset_id
                                   ORDER BY product.product_name
                               ) AS product_names
                        FROM {datasets} AS checkpoint
                        WHERE (%s OR checkpoint.deleted_at IS NULL)
                        ORDER BY checkpoint.dataset_id
                    """).format(datasets=datasetsTable, members=membersTable, products=productsTable)

                    cursor.execute(statement, (includeDeleted,))
                    rows = cursor.fetchall()

        grouped = {}

        for datasetID, familyUUID, name, checkpointName, status, deletedAt, memberCount, productNames in rows:
            record = {
                "datasetID": datasetID,
                "checkpointName": checkpointName,
                "status": status,
                "deletedAt": deletedAt,
                "memberCount": memberCount,
                "productNames": productNames,
            }
            grouped.setdefault(name, {}).setdefault(familyUUID, []).append(record)

        # +++++++++++++++++++++++++++++++ nameOrder +++++++++++++++++++++++++++++++
        # Local implementation within printDatasets.
        def nameOrder(value):
            return (value is None, "" if value is None else value.casefold(), "" if value is None else value)

        # +++++++++++++++++++++++++++++ checkpointLine ++++++++++++++++++++++++++++
        # Local implementation within printDatasets.
        def checkpointLine(record, prefix):
            label = f"{prefix}datasetID: {record['datasetID']}"

            if record["checkpointName"]:
                label += f" ({pglDatabase._printValue(record['checkpointName'])})"

            if record["deletedAt"] is not None:
                label += " [deleted]"

            if record["status"] != "complete":
                label += f" [{pglDatabase._printValue(record['status'])}]"

            products = ", ".join(pglDatabase._printValue(name) for name in record["productNames"]) or "(none)"
            return f"{label} | members: {record['memberCount']} | products: {products}"

        pglMessages.printHeader("Datasets")
        pglMessages.message(f"Database: {databaseName}.{postgres.databaseSchema}", wrapText=False)
        pglMessages.message(f"Metadata snapshot: {snapshotTime}", wrapText=False)
        pglMessages.print("  Including deleted datasets." if includeDeleted else "  Deleted datasets excluded.")
        pglMessages.print()

        if not rows:
            pglMessages.print("  (no visible datasets)")
        else:
            for name in sorted(grouped, key=nameOrder):
                pglMessages.print(pglDatabase._printValue(name))
                families = grouped[name]
                showFamilies = len(families) > 1

                # Order families by their first visible checkpoint ID.
                familyOrder = sorted(families, key=lambda family: min(record["datasetID"] for record in families[family]))

                for familyUUID in familyOrder:
                    if showFamilies:
                        pglMessages.print(f"  family: {familyUUID}")

                    prefix = "    " if showFamilies else "  "

                    for record in sorted(families[familyUUID], key=lambda record: record["datasetID"]):
                        pglMessages.print(checkpointLine(record, prefix))

                pglMessages.print()

        pglMessages.printHeader()
        return True

    # ++++++++++++++++++++++++++++++ printDataset +++++++++++++++++++++++++++++
    # User-facing database API. See the docstring for configuration, side effects, and return
    # conventions.
    @classmethod
    def printDataset(cls, dataset, *, verbose=False, settings=None, settingsName=None, sslRootCert=None):
        """Print membership labels and product references.

        Displays experiment, subject, and behavioral acquisition session names.
        Reads verified root experiment-settings files for session names.
        Does not construct member sessions or open scientific matrix arrays.

        Entry name is the dataset-local alias.
        Session name is the behavioral acquisition's sessionName.
        Checkpoint name is the saved checkpoint annotation.

        Multiple distinct labels are joined with ' + '; these are summaries,
        not an assertion that every experiment/subject/name combination exists.
        """
        from .pglData import pglDataMatrixReference

        members = dataset._validateMembers(dataset.members)
        products = cls._validateDatasetProducts(dataset)
        summaries = cls.getDatasetMemberSummaries(dataset, settings=settings, settingsName=settingsName, sslRootCert=sslRootCert, includeBehaviorLabels=True)

        if summaries is None:
            pglMessages.warning("Cannot print dataset members: database configuration or connection is unavailable.", level=0)
            return False

        pglMessages.printHeader(f"Dataset: {cls._printValue(dataset.name)}")
        pglMessages.print(f"  Source checkpoint: {dataset.datasetID if dataset.datasetID is not None else 'Unsaved'}")
        pglMessages.print(f"  Working members: {len(members)}")

        if dataset.checkpointName:
            pglMessages.print(f"  Checkpoint name: {cls._printValue(dataset.checkpointName)}")

        if dataset.description:
            pglMessages.print(f"  Description: {cls._printValue(dataset.description)}")

        pglMessages.print("  Acquisition dates below are not checkpoint creation dates.")
        pglMessages.print()

        rows = []

        for member in members:
            sessionID = member["sessionID"]
            summary = summaries.get(sessionID)

            if summary is None:
                experimentLabel = "Unknown"
                subjectLabel = "Unknown"
                sessionLabel = ""
                acquiredLabel = "Unknown"
                checkpointLabel = "Unavailable"
                state = "missing"
            else:
                experimentLabel = " + ".join(summary["experimentNames"]) or "Unknown"
                subjectLabel = " + ".join(summary["subjectIDs"]) or "Unknown"
                sessionLabel = " + ".join(summary["sessionNames"])
                acquiredAt = summary["acquiredAt"]
                acquiredLabel = acquiredAt.isoformat() if acquiredAt is not None else "Unknown"
                checkpointLabel = summary["checkpointName"] or ""
                state = "deleted" if summary["deletedAt"] is not None else summary["status"]

            rows.append((
                experimentLabel,
                subjectLabel,
                sessionLabel,
                member["entryName"] or "",
                acquiredLabel,
                sessionID,
                checkpointLabel,
                state,
            ))

        # Preserve the existing subject-first display order.
        # This does not change authoritative dataset membership order.
        rows.sort(key=lambda row: (row[1] == "Unknown", row[1], row[5]))
        cls._printTable(("Experiment", "Subject", "Session name", "Entry name", "Acquired", "Session ID", "Checkpoint name", "Source state"), rows, maxWidth=None)

        if products:
            pglMessages.print()
            pglMessages.printHeader("Scientific products", fillChar="-")
            productRows = []

            for name, product in sorted(products.items()):
                state = "Saved reference; unopened" if isinstance(product, pglDataMatrixReference) else "Working matrix"
                revisionID = product.matrixRevisionID or "Unpublished"
                productRows.append((name, state, revisionID))

            cls._printTable(("Product", "Attachment state", "Source revision"), productRows, maxWidth=None)
            pglMessages.print("  Attachment state does not yet report construction freshness.")

        if verbose:
            for member in members:
                if member["labels"]:
                    pglMessages.print(f"  Session {member['sessionID']} labels: {cls._printValue(member['labels'])}")

            parameterNames = sorted(str(key) for key in dataset.derivedParameters)
            pglMessages.print(f"  Derived parameter keys: {', '.join(parameterNames) or '(none)'}")
            pglMessages.print(f"  Recorded actions: {len(dataset.actionHistory)}")

        pglMessages.printHeader()
        return True

    # ++++++++++++++++++++++++++++++ printTables ++++++++++++++++++++++++++++++
    # User-facing database API. See the docstring for configuration, side effects, and return
    # conventions.
    # Direct callers in this module: print.
    @_postgresReadAvailability
    @staticmethod
    def printTables(details=None, postgres=None, *, settings=None, settingsName=None, nRows=10, maxWidth=48, sslRootCert=None, includeDeleted=False):
        """Print database table counts/statuses or selected table contents.

        details=None:
            Database summary.

        details="session", an iterable of names, or "all":
            First nRows rows of each requested table.

        Does not access payload storage.
        """
        from psycopg.rows import tuple_row

        if type(includeDeleted) is not bool:
            raise ValueError("includeDeleted must be a boolean.")

        if type(nRows) is not int or nRows <= 0:
            raise ValueError("nRows must be a positive integer.")

        if type(maxWidth) is not int or maxWidth < 8:
            raise ValueError("maxWidth must be an integer of at least 8.")

        tableOrder = pglDatabase._printTableOrder()

        if details is None:
            requested = []
        elif isinstance(details, str):
            requested = list(tableOrder) if details == "all" else [details]
        else:
            try:
                requested = list(details)
            except TypeError as error:
                raise ValueError("details must be a table name or an iterable of table names.") from error

        if any(not isinstance(name, str) or name not in tableOrder for name in requested):
            raise ValueError(f"Supported detail tables: {', '.join(tableOrder)}; or 'all'.")

        requested = list(dict.fromkeys(requested))
        postgres = pglDatabase._printPostgres(postgres, settings=settings, settingsName=settingsName)

        if postgres is None:
            return False

        # ++++++++++++++++++++++++++++++ reportTable ++++++++++++++++++++++++++++++
        # Local implementation within printTables.
        def reportTable(name):
            table = sql.Identifier(postgres.databaseSchema, name)

            if not includeDeleted and name in {"session", "session_files", "files", "storage_locations"}:
                return sql.SQL("(SELECT * FROM {} WHERE deleted_at IS NULL)").format(table)

            return table

        counts = []
        checkpointCounts = []
        detailResults = []

        with postgres.connect(sslRootCert=sslRootCert) as connection:
            if connection is None:
                return False

            with connection.transaction():
                connection.execute("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ, READ ONLY")

                with connection.cursor(row_factory=tuple_row) as cursor:
                    cursor.execute("SELECT current_database(), current_user, transaction_timestamp()")
                    databaseName, databaseUser, snapshotTime = cursor.fetchone()

                    if requested:
                        for name in requested:
                            order = sql.SQL(", ").join(sql.Identifier(column) for column in tableOrder[name])
                            statement = sql.SQL("SELECT * FROM {} AS record ORDER BY {} LIMIT %s").format(reportTable(name), order)
                            cursor.execute(statement, (nRows + 1,))
                            headers = [column.name for column in cursor.description]
                            rows = cursor.fetchall()
                            detailResults.append((name, headers, rows[:nRows], len(rows) > nRows))
                    else:
                        for name in tableOrder:
                            cursor.execute(sql.SQL("SELECT count(*) FROM {} AS record").format(reportTable(name)))
                            counts.append((name, cursor.fetchone()[0]))

                        if includeDeleted:
                            statement = sql.SQL("SELECT origin, status, deleted_at IS NOT NULL AS deleted, count(*) FROM {} AS record GROUP BY origin, status, deleted_at IS NOT NULL ORDER BY origin, status, deleted").format(reportTable("session"))
                        else:
                            statement = sql.SQL("SELECT origin, status, count(*) FROM {} AS record GROUP BY origin, status ORDER BY origin, status").format(reportTable("session"))

                        cursor.execute(statement)
                        checkpointCounts = cursor.fetchall()

        if requested:
            for name, headers, rows, hasMore in detailResults:
                pglMessages.print()
                pglMessages.printHeader(name, fillChar="-")

                if includeDeleted:
                    pglMessages.print("  Including deleted records; deleted_at is the deletion marker where applicable.")

                pglMessages.print(f"  First {len(rows)} rows, ordered by {', '.join(tableOrder[name])}")
                pglDatabase._printTable(headers, rows, maxWidth=maxWidth)

                if hasMore:
                    pglMessages.message(f"More rows available; increase nRows above {nRows} to display more.")

        else:
            pglMessages.printHeader("PGL database snapshot")
            pglMessages.print("  Including deleted records." if includeDeleted else "  Deleted records excluded.")
            pglMessages.message(f"Database: {databaseName}.{postgres.databaseSchema}", wrapText=False)
            pglMessages.message(f"User: {databaseUser} | Transport: {postgres.connectionTransport}", wrapText=False)
            pglMessages.message(f"Snapshot transaction started: {snapshotTime}", wrapText=False)
            pglMessages.print()
            pglMessages.printHeader("Table counts", fillChar="-")
            pglDatabase._printTable(("table", "rows"), counts, maxWidth=maxWidth)
            pglMessages.print()
            pglMessages.printHeader("Checkpoint status", fillChar="-")
            checkpointHeaders = ("origin", "status", "deleted", "checkpoints") if includeDeleted else ("origin", "status", "checkpoints")
            pglDatabase._printTable(checkpointHeaders, checkpointCounts, maxWidth=maxWidth)

        pglMessages.printHeader()
        return True

    # +++++++++++++++++++++++++++ _printDateRange +++++++++++++++++++++++++++
    @staticmethod
    def _printDateRange(value, fieldName):
        """Validate an inclusive calendar-date range used by session reports.

        Accepts None or a two-item tuple/list containing ISO date strings,
        Python date objects, or None for an open endpoint.

        Datetime endpoints are rejected: these filters intentionally operate
        on whole UTC calendar days, not timestamp intervals.
        """
        from datetime import date, datetime

        if value is None:
            return None

        if not isinstance(value, (tuple, list)) or len(value) != 2:
            raise ValueError(f"{fieldName} must be a (start, end) tuple or list.")

        endpoints = []

        for endpoint in value:
            if endpoint is None:
                endpoints.append(None)
                continue

            if isinstance(endpoint, datetime):
                raise ValueError(f"{fieldName} endpoints must be dates, not datetime values.")

            if isinstance(endpoint, date):
                endpoints.append(endpoint)
                continue

            if isinstance(endpoint, str):
                try:
                    parsed = date.fromisoformat(endpoint)
                except ValueError as error:
                    raise ValueError(f"{fieldName} endpoints must use YYYY-MM-DD dates.") from error

                if parsed.isoformat() != endpoint:
                    raise ValueError(f"{fieldName} endpoints must use YYYY-MM-DD dates.")

                endpoints.append(parsed)
                continue

            raise ValueError(f"{fieldName} endpoints must be YYYY-MM-DD strings, date objects, or None.")

        startDate, endDate = endpoints

        if startDate is not None and endDate is not None and startDate > endDate:
            raise ValueError(f"{fieldName} start date must not be after its end date.")

        return startDate, endDate
    # -------------------------------------------------------------------------
    # Pipeline extraction
    # -------------------------------------------------------------------------
    # Extract recorded analysis using verified checkpoint ancestry without executing the analysis.

    # +++++++++++++++++++++++++++ getSessionPipeline ++++++++++++++++++++++++++
    # User-facing database API. See the docstring for configuration, side effects, and return
    # conventions.
    @classmethod
    def getSessionPipeline(cls, session, name=None, *, settings=None, settingsName=None, storageOptionsByBackend=None, sslRootCert=None):
        """Extract recorded analysis from a session using checkpoint ancestry.

        For sessions with a checkpoint baseline, verify active ancestry and
        saved history metadata, then extract the suffix after the raw boundary.

        Without a baseline, preserve the existing history-only extraction path.
        That path may have a recorded pipeline input or no default input.

        Returns None for unavailable configuration or connection cancellation.
        Invalid ancestry and metadata errors propagate.

        Reads manifests/history only. Does not open scientific payloads,
        change session history, save a recipe, or execute actions.
        """
        from .pglPipeline import pglActionable, pglPipeline
        from .pglPostgres import pglPostgres

        if not isinstance(session, pglActionable):
            raise TypeError("Pipeline extraction requires a pglActionable object.")

        if name is not None:
            pglPipeline._validatePipelineName(name)

        boundary = cls._getCheckpointHistoryBoundary(session)

        if boundary is None:
            return pglPipeline.fromHistory(session, name=name)

        baseline = deepcopy(session._checkpointBaseline)

        if getattr(session, "sessionID", None) != baseline["sessionID"]:
            raise ValueError("Session ID differs from its checkpoint baseline. Reload the intended checkpoint before ancestry-based extraction.")

        postgres = pglPostgres.fromSettings(settings=settings, settingsName=settingsName)

        if postgres is None:
            return None

        if cls._checkpointDatabaseIdentity(postgres) != baseline["databaseIdentity"]:
            raise ValueError("Current PGL settings point to a different database than the session baseline.")

        sessionsTable = sql.Identifier(postgres.databaseSchema, "session")
        checkpoints = []
        seen = set()
        currentID = baseline["sessionID"]

        with postgres.connect(sslRootCert=sslRootCert) as connection:
            if connection is None:
                return None

            with connection.transaction():
                connection.execute("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ, READ ONLY")

                while currentID is not None:
                    if currentID in seen:
                        raise ValueError("Checkpoint ancestry contains a cycle.")

                    if len(seen) >= 10000:
                        raise ValueError("Checkpoint ancestry exceeds the replay inspection limit.")

                    seen.add(currentID)
                    statement = sql.SQL("SELECT session_id, parent_session_id, root_session_id, origin, status, contract_version, manifest_hash, deleted_at FROM {} WHERE session_id = %s").format(sessionsTable)
                    row = connection.execute(statement, (currentID,)).fetchone()

                    if row is None:
                        raise ValueError(f"Replay ancestor {currentID} does not exist.")

                    record = dict(zip(("sessionID", "parentSessionID", "rootSessionID", "origin", "status", "contractVersion", "manifestHash", "deletedAt"), row))

                    if record["status"] != "complete" or record["deletedAt"] is not None:
                        raise ValueError(f"Replay ancestor {currentID} is incomplete or deleted.")

                    checkpoints.append(record)
                    currentID = record["parentSessionID"]

                checkpoints.reverse()

                for checkpoint in checkpoints:
                    history = cls._readReplayCheckpointHistory(connection, postgres, checkpoint, storageOptionsByBackend=storageOptionsByBackend)
                    checkpoint["historyHashes"] = [hashlib.sha256(cls.encodeRawManifest(json.loads(entry.toJSON()))).hexdigest() for entry in history.actionHistory]

                inputRecord = cls._selectAncestralReplayInput(session, checkpoints, postgres)

        # Recheck the working prefix after metadata reads. Callers must not
        # concurrently modify the session while extraction is in progress.
        cls._getCheckpointHistoryBoundary(session)

        if session._checkpointBaseline != baseline:
            raise ValueError("The working checkpoint baseline changed during pipeline extraction.")

        prefixLength = inputRecord["historyCount"]
        view = pglActionable()
        view.actionHistory = list(session.actionHistory[prefixLength:])
        view._failedActionIDs = list(session._failedActionIDs)

        # Check only the analysis history selected for extraction, not the
        # acquisition history already excluded by the raw checkpoint boundary.
        from .pglPipeline import pglActionStatus

        for entry in view.actionHistory:
            if entry.actionStatus == pglActionStatus.SUCCESS and (not entry.actionCode.get("module") or not entry.actionCode.get("qualname")):
                pglMessages.warning(f"Cannot extract pipeline: {entry.actionName!r} has old history recorded before action class identities were added. Reloading or resaving will not recover that missing information. The session and its history have not been changed.", level=2)
                return None

        # The tested execution-tree extractor rejects a boundary that splits
        # a parent/child execution tree rather than silently flattening it.
        pipeline = pglPipeline._fromHistoryRecipe(view, name=name)
        if pipeline is None:
            return None

        # +++++++++++++++++++++++++ restoreHistoryIndices +++++++++++++++++++++++++
        # Local implementation within getSessionPipeline.
        def restoreHistoryIndices(recipe):
            for source in recipe.stepSources.values():
                source["historyIndex"] += prefixLength

            for action in recipe.actions:
                if isinstance(action, pglPipeline):
                    restoreHistoryIndices(action)

        restoreHistoryIndices(pipeline)
        pipeline.replayInput = inputRecord

        pglMessages.message(f"Pipeline extracted from recorded ancestry: input checkpoint {inputRecord['sessionID']}; excluded {prefixLength} history entries already included in that raw checkpoint.")
        return pipeline


    # =========================================================================
    # ADVANCED API
    # =========================================================================

    # -------------------------------------------------------------------------
    # Session loading with caller-owned connections
    # -------------------------------------------------------------------------
    # Lower-level loaders used by loadSession(). Callers own database connections and transactions.

    # +++++++++++++++++++++++++++++ loadRawSession ++++++++++++++++++++++++++
    @classmethod
    def loadRawSession(cls, connection, postgres, sessionID, storageOptionsByBackend=None, *, includeDeleted=False):
        """Restore a raw behavioral checkpoint with retained caller-side access.

        Called by loadSession(), or by advanced callers owning a SQL snapshot.

        Verifies the manifest immediately. Behavioral files remain deferred
        and are verified when opened through pglCheckpointFilesystem.

        Creates one runtime access context for manifest and payload reads.
        On success, ownership transfers to the returned session's filesystem.
        On failure, the context closes before the exception propagates.

        The caller may close SQL after this method returns. Deferred file
        access uses its retained filesystem context, not the SQL connection.

        This low-level loader does not assign checkpoint annotations or bind
        the working history baseline; loadSession() performs that bookkeeping.

        Once all deferred readers are finished, the filesystem owner can call
        session.filesystem.close() to release its SSH connections.

        Does not publish or modify database records.
        """
        from .pglSession import pglSession

        access = pglDatabaseAccess(postgres, storageOptionsByBackend)

        try:
            manifest = cls.loadRawManifest(connection, postgres, sessionID, includeDeleted=includeDeleted, accessContext=access)
            fileLocations = cls.getRawFileLocations(connection, postgres, sessionID, manifest, includeDeleted=includeDeleted)
            filesystem = pglCheckpointFilesystem(manifest, fileLocations, accessContext=access, ownsAccess=True)
            runPaths = [record["path"] for record in manifest["runs"]]
            session = pglSession(filesystem=filesystem, runList=runPaths)
            return session

        except BaseException:
            access.close()
            raise

    # ++++++++++++++++++++++++++ loadRawSessionBundle +++++++++++++++++++++++++
    # Advanced database/checkpoint API. Observe the connection and transaction requirements in the
    # docstring.
    # Direct callers in this module: _saveRawMNECheckpoint.
    @classmethod
    def loadRawSessionBundle(cls, connection, postgres, sessionID, storageOptionsByBackend=None, *, includeDeleted=False, maxManifestBytes=16 * 1024 * 1024, cacheDirectory=None, directLocalPolicy="materialize"):
        """Restore a raw session bundle using the caller's SQL transaction.

        Supports MNE-required raw v1 and explicitly declared raw v2 contents.

        Reads verified history and modality descriptors. MRI payloads remain
        deferred until scan.data is accessed; saved header metadata is available
        immediately.

        The returned checkpoint filesystem retains payload access independently
        of the SQL connection. Keep it open while deferred readers need it.

        This lower-level loader does not assign checkpoint annotations or bind
        the working history baseline; public loadSession() handles those steps.

        Does not publish or modify database records.
        """
        return cls._loadSessionBundle(connection, postgres, sessionID, storageOptionsByBackend=storageOptionsByBackend, includeDeleted=includeDeleted, maxManifestBytes=maxManifestBytes, cacheDirectory=cacheDirectory, directLocalPolicy=directLocalPolicy, origin="raw")
    
    # +++++++++++++++++++++++++++ loadDerivedSession ++++++++++++++++++++++++++
    # Advanced database/checkpoint API. Observe the connection and transaction requirements in the
    # docstring.
    @classmethod
    def loadDerivedSession(cls, connection, postgres, sessionID, storageOptionsByBackend=None, *, includeDeleted=False, maxManifestBytes=16 * 1024 * 1024, cacheDirectory=None, directLocalPolicy="materialize"):
        """Load a completed derived checkpoint using the caller's transaction."""
        return cls._loadSessionBundle(connection, postgres, sessionID, storageOptionsByBackend=storageOptionsByBackend, includeDeleted=includeDeleted, maxManifestBytes=maxManifestBytes, cacheDirectory=cacheDirectory, directLocalPolicy=directLocalPolicy, origin="derived")

    # +++++++++++++++++++++++ reconstructDerivedSession +++++++++++++++++++++++
    # Advanced database/checkpoint API. Observe the connection and transaction requirements in the
    # docstring.
    # +++++++++++++++++++++++ reconstructDerivedSession ++++++++++++++++++++++
    @classmethod
    def reconstructDerivedSession(cls, manifest, fileLocations, storageOptionsByBackend=None, *, cacheDirectory=None, directLocalPolicy="materialize", cacheContext=None, accessContext=None, ownsAccess=False):
        """Reconstruct a derived checkpoint from supplied inventory metadata.

        Advanced reconstruction entry point; does not query PostgreSQL.
        Does not restore separately registered matrix products.

        Remote database callers must supply a pglDatabaseAccess context.
        Configure backend options on that context rather than supplying a
        second nonempty storageOptionsByBackend mapping.

        ownsAccess=True transfers context ownership to the returned session's
        filesystem on success. On failure, the caller retains ownership.

        Without a context, retains local/explicit-URL compatibility behavior.
        Deferred readers require the returned filesystem to remain open.
        """
        return cls._reconstructSessionBundle(manifest, fileLocations, storageOptionsByBackend=storageOptionsByBackend, cacheDirectory=cacheDirectory, directLocalPolicy=directLocalPolicy, cacheContext=cacheContext, origin="derived", accessContext=accessContext, ownsAccess=ownsAccess)

    # -------------------------------------------------------------------------
    # Checkpoint creation, registration, and completion
    # -------------------------------------------------------------------------
    # Publication primitives used by save coordinators. They do not commit the caller's outer
    # transaction.

    # ++++++++++++++++++++++++++ createRawCheckpoint ++++++++++++++++++++++++++
    # Advanced database/checkpoint API. Observe the connection and transaction requirements in the
    # docstring.
    # Direct callers in this module: _saveRawSession, registerStagedRawCheckpoint.
    @staticmethod
    def createRawCheckpoint(connection, postgres, createdBy, description=None, ingestMethod="manual"):
        """Create an unpublished raw behavioral checkpoint.

        Uses the caller's connection and transaction; does not commit.
        File links and completion are handled separately.
        """
        if isinstance(createdBy, bool) or not isinstance(createdBy, int) or not 0 <= createdBy <= 9223372036854775807:
            raise ValueError("createdBy must be a nonnegative PostgreSQL bigint.")

        if description is not None and (not isinstance(description, str) or "\x00" in description):
            raise ValueError("description must be a string without NUL, or None.")

        if ingestMethod not in {"manual", "automated"}:
            raise ValueError("ingestMethod must be manual or automated.")

        table = sql.Identifier(postgres.databaseSchema, "session")
        statement = sql.SQL("""
            INSERT INTO {} (
                origin, kind, ingest_method, modalities, status,
                description, contract_version, created_by, started_at
            )
            VALUES (
                'raw', 'acquired', %s, ARRAY['behavior']::text[], 'in_progress',
                %s, 'pgl.raw.behavior.v1', %s, now()
            )
            RETURNING session_id
        """).format(table)

        return connection.execute(statement, (ingestMethod, description, createdBy)).fetchone()[0]

    ################################################################
    # Allocate an unpublished derived checkpoint
    ################################################################
    @staticmethod
    def createDerivedCheckpoint(connection, postgres, createdBy, parentSessionID, description=None, ingestMethod="manual", *, checkpointName=None, contractVersion="pgl.derived.behavior.v1", modalities=None):
        """Create an unpublished derived checkpoint in the caller's transaction.

        Supports:
            Behavioral/MNE v1/v2/v3 contracts.
            MRI v1 with optional behavior, products, and derived files.

        Database lineage rules require a completed, active parent.
        Matrix products and derived files do not add separate modalities.
        Combined MRI/MNE checkpoints remain unsupported.

        Does not write payloads, complete or commit the checkpoint, or modify
        the working session.
        """
        for label, value in (("createdBy", createdBy), ("parentSessionID", parentSessionID)):
            if type(value) is not int or not 0 <= value <= 9223372036854775807:
                raise ValueError(f"{label} must be a nonnegative PostgreSQL bigint.")

        for label, value in (("checkpointName", checkpointName), ("description", description)):
            if value is not None and (not isinstance(value, str) or "\x00" in value):
                raise ValueError(f"{label} must be a string without NUL, or None.")

        if ingestMethod not in ("manual", "automated"):
            raise ValueError("ingestMethod must be manual or automated.")

        behaviorContracts = {
            "pgl.derived.behavior.v1",
            "pgl.derived.behavior.v2",
            "pgl.derived.behavior.v3",
        }
        mneContracts = {
            "pgl.derived.session.v1",
            "pgl.derived.session.v2",
            "pgl.derived.session.v3",
        }
        mriContracts = {"pgl.derived.mri.v1", "pgl.derived.mri.v2"}

        if contractVersion not in behaviorContracts | mneContracts | mriContracts:
            raise ValueError("Unsupported derived checkpoint contract.")

        hasMNE = contractVersion in mneContracts
        hasMRI = contractVersion in mriContracts

        if modalities is None:
            modalities = ["mri"] if hasMRI else ["mne"] if hasMNE else ["behavior"]

        if not isinstance(modalities, (list, tuple)) or not modalities:
            raise ValueError("modalities must be a nonempty list or tuple.")
        if any(not isinstance(value, str) or value not in ("behavior", "mne", "mri") for value in modalities):
            raise ValueError("Supported content categories are behavior, mne, and mri.")
        if len(set(modalities)) != len(modalities):
            raise ValueError("Duplicate modalities are not allowed.")

        selected = set(modalities)

        # The contract determines which modality combinations are legal.
        # Do not permit an MRI collection to be omitted under a behavior/MNE
        # contract or allow unsupported MRI/MNE combinations.
        if hasMRI:
            if "mri" not in selected or not selected <= {"behavior", "mri"}:
                raise ValueError("Derived MRI checkpoints require MRI and optionally behavior.")
        elif hasMNE:
            if "mne" not in selected or not selected <= {"behavior", "mne"}:
                raise ValueError("Derived MNE checkpoints require MNE and optionally behavior.")
        elif selected != {"behavior"}:
            raise ValueError("Behavioral checkpoints require only the behavior category.")

        table = sql.Identifier(postgres.databaseSchema, "session")
        statement = sql.SQL("""
            INSERT INTO {} (
                origin, kind, parent_session_id, ingest_method,
                modalities, status, checkpoint_name, description,
                contract_version, created_by, started_at
            )
            VALUES (
                'derived', 'processed', %s, %s, %s::text[], 'in_progress',
                %s, %s, %s, %s, now()
            )
            RETURNING session_id
        """).format(table)

        return connection.execute(
            statement,
            (
                parentSessionID,
                ingestMethod,
                list(modalities),
                checkpointName,
                description,
                contractVersion,
                createdBy,
            ),
        ).fetchone()[0]
    
    
    # ++++++++++++++++++++++ registerStagedRawCheckpoint +++++++++++++++++++++
    @classmethod
    def registerStagedRawCheckpoint(cls, connection, postgres, createdBy, backendID, manifest, staged, storedManifest, storageOptions=None, *, sessionID=None, accessContext=None, progress=None):
        """Register a staged behavioral archive without completing or committing.

        Validates staged identities, reads verified acquisition labels,
        verifies/registers stored payloads, and attaches checkpoint file links.

        A supplied access context is borrowed. Otherwise this method owns and
        closes one temporary context.

        Optional progress weights registration verification by file size.
        Repeated identical payload/location registrations are verified once.
        All existing publication and integrity checks remain in place.
        """
        from contextlib import ExitStack

        if type(backendID) is not int or not 0 <= backendID <= 9223372036854775807:
            raise ValueError("backendID must be a nonnegative PostgreSQL bigint.")

        if storageOptions is not None and not isinstance(storageOptions, dict):
            raise TypeError("storageOptions must be a dictionary or None.")

        if accessContext is not None:
            if not isinstance(accessContext, pglDatabaseAccess):
                raise TypeError("accessContext must be a pglDatabaseAccess instance.")

            if storageOptions:
                raise ValueError("Configure storage options on accessContext, not on both arguments.")

            if cls._checkpointDatabaseIdentity(accessContext._postgres) != cls._checkpointDatabaseIdentity(postgres):
                raise ValueError("The supplied payload context belongs to a different configured database.")

        if progress is not None:
            progress(0, "Validating staged file inventory")

        cls.validateRawManifest(manifest)
        expectedByName = {record["name"]: record for record in manifest["files"]}
        stagedByName = {record["name"]: record for record in staged}

        if len(expectedByName) != len(manifest["files"]) or len(stagedByName) != len(staged):
            raise ValueError("Duplicate logical filenames are not allowed.")

        if set(expectedByName) != set(stagedByName):
            raise ValueError("Staged files do not match the manifest filenames.")

        if "manifest.json" in expectedByName:
            raise ValueError("manifest.json is reserved for the checkpoint manifest.")

        for name, expected in expectedByName.items():
            actual = stagedByName[name]

            if actual["sha256"] != expected["sha256"] or actual["size_bytes"] != expected["size_bytes"]:
                raise ValueError(f"Staged identity differs from manifest: {name}")

        manifestBytes = cls.encodeRawManifest(manifest)

        if storedManifest["sha256"] != hashlib.sha256(manifestBytes).hexdigest() or storedManifest["size_bytes"] != len(manifestBytes):
            raise ValueError("Stored manifest identity does not match the supplied manifest.")

        backendsTable = sql.Identifier(postgres.databaseSchema, "storage_backends")
        statement = sql.SQL("SELECT url_prefix, is_active FROM {} WHERE backend_id = %s").format(backendsTable)
        backend = connection.execute(statement, (backendID,)).fetchone()

        if backend is None or not backend[1]:
            raise ValueError(f"Storage backend is missing or inactive: {backendID}")

        registeredRoot = backend[0]

        with ExitStack() as resources:
            if accessContext is None:
                access = resources.enter_context(pglDatabaseAccess(postgres, {backendID: storageOptions or {}}))
            else:
                access = accessContext

            fileLocations = {
                name: {
                    "sha256": record["sha256"],
                    "size_bytes": record["size_bytes"],
                    "locations": [{
                        "backend_id": backendID,
                        "url_prefix": registeredRoot,
                        "object_key": record["object_key"],
                    }],
                }
                for name, record in stagedByName.items()
            }

            archive = pglCheckpointFilesystem(manifest, fileLocations, accessContext=access, ownsAccess=False)
            resources.callback(archive.close)

            if progress is not None:
                progress(0, "Verifying archived acquisition labels")

            metadata = cls._behaviorLabelMetadata(manifest, archive)
            subjectsByRun = {run["path"]: metadata["labels"][run["index"]]["subjectID"] for run in manifest["runs"]}
            subjectsByName = {}

            for name in expectedByName:
                matchingRuns = [path for path in subjectsByRun if name.startswith(path + "/")]

                if len(matchingRuns) != 1:
                    raise ValueError(f"File does not belong to exactly one run: {name}")

                subjectsByName[name] = subjectsByRun[matchingRuns[0]]

            if progress is not None:
                progress(None, "Validating unpublished checkpoint")

            if sessionID is None:
                checkpointID = cls.createRawCheckpoint(connection, postgres, createdBy)
            else:
                sessionsTable = sql.Identifier(postgres.databaseSchema, "session")
                linksTable = sql.Identifier(postgres.databaseSchema, "session_files")

                statement = sql.SQL("SELECT status, origin, contract_version, created_by, deleted_at FROM {} WHERE session_id = %s FOR UPDATE").format(sessionsTable)
                checkpoint = connection.execute(statement, (sessionID,)).fetchone()

                if checkpoint != ("in_progress", "raw", "pgl.raw.behavior.v1", createdBy, None):
                    raise ValueError("Checkpoint must be an active in-progress raw behavioral checkpoint owned by the supplied creator.")

                statement = sql.SQL("SELECT 1 FROM {} WHERE session_id = %s LIMIT 1").format(linksTable)

                if connection.execute(statement, (sessionID,)).fetchone() is not None:
                    raise ValueError("Checkpoint already has file links.")

                checkpointID = sessionID

            cls._recordSessionLabelMetadata(connection, postgres, checkpointID, metadata)
            registeredPayloads = {}

            def registerPayload(record, fileProgress=None):
                """Verify/register each distinct identity and location once."""
                identity = (record["sha256"], record["size_bytes"], record["object_key"])

                if identity not in registeredPayloads:
                    if fileProgress is not None:
                        fileProgress(0, "Resolving content identity")

                    fileID = cls.getOrCreateFile(connection, postgres, record["sha256"], record["size_bytes"])
                    cls.verifyAndRegisterStorageLocation(connection, postgres, fileID, backendID, record["object_key"], accessContext=access, progress=fileProgress)
                    registeredPayloads[identity] = fileID
                elif fileProgress is not None:
                    fileProgress(1, "Reusing verification from this registration")

                return registeredPayloads[identity]

            records = [stagedByName[name] for name in sorted(expectedByName)]
            records.append({**storedManifest, "name": "manifest.json"})
            fileRange = progress.section(0.05, 1) if progress is not None else None

            for record, fileProgress in pglProgress.fileSections(records, fileRange):
                name = record["name"]
                fileID = registerPayload(record, fileProgress)

                if fileProgress is not None:
                    fileProgress(None, "Attaching checkpoint file")

                if name == "manifest.json":
                    cls.attachCheckpointFile(connection, postgres, checkpointID, name, fileID, role="manifest")
                else:
                    cls.attachCheckpointFile(connection, postgres, checkpointID, name, fileID, role="acquisition", subjectID=subjectsByName[name])

            return checkpointID

    # ++++++++++++++++++++++ registerDerivedSessionFiles ++++++++++++++++++++
    @classmethod
    def registerDerivedSessionFiles(cls, connection, postgres, sessionID, backendID, manifest, *, objectPrefix, storageOptions=None, accessContext=None, progress=None):
        """Verify/register a staged derived bundle without committing.

        A supplied access context is borrowed.
        Optional progress reports verification and file registration.
        Does not copy payloads, register matrix links, or complete the checkpoint.
        """
        return cls._registerSessionBundleFiles(connection, postgres, sessionID, backendID, manifest, objectPrefix=objectPrefix, storageOptions=storageOptions, origin="derived", accessContext=accessContext, progress=progress)
    
    # +++++++++++++++++++++++++ completeRawCheckpoint +++++++++++++++++++++++++
    # Advanced database/checkpoint API. Observe the connection and transaction requirements in the
    # docstring.
    # Direct callers in this module: _saveRawSession.
    @classmethod
    def completeRawCheckpoint(cls, connection, postgres, sessionID, manifest):
        """Validate registered identities and complete a raw checkpoint.

        Must run inside the caller's transaction.
        Checks recorded verification status; does not reread payload bytes.
        """
        cls.validateRawManifest(manifest)
        sessionsTable = sql.Identifier(postgres.databaseSchema, "session")
        linksTable = sql.Identifier(postgres.databaseSchema, "session_files")
        filesTable = sql.Identifier(postgres.databaseSchema, "files")
        locationsTable = sql.Identifier(postgres.databaseSchema, "storage_locations")
        backendsTable = sql.Identifier(postgres.databaseSchema, "storage_backends")

        statement = sql.SQL("""
            SELECT status, origin, contract_version
            FROM {} WHERE session_id = %s FOR UPDATE
        """).format(sessionsTable)
        checkpoint = connection.execute(statement, (sessionID,)).fetchone()

        if checkpoint is None:
            raise ValueError(f"Unknown checkpoint: {sessionID}")

        if checkpoint != ("in_progress", "raw", "pgl.raw.behavior.v1"):
            raise ValueError("Checkpoint must be an in-progress raw behavioral checkpoint.")

        if manifest["contract_version"] != checkpoint[2]:
            raise ValueError("Manifest contract does not match the checkpoint.")

        expected = {}
        for record in manifest["files"]:
            name = record["name"]

            if name == "manifest.json" or name in expected:
                raise ValueError(f"Reserved or duplicate manifest filename: {name}")

            expected[name] = (record["sha256"], record["size_bytes"], "acquisition")

        manifestBytes = cls.encodeRawManifest(manifest)
        manifestHash = hashlib.sha256(manifestBytes).hexdigest()
        expected["manifest.json"] = (manifestHash, len(manifestBytes), "manifest")

        statement = sql.SQL("""
            SELECT link.name, content.sha256, content.size_bytes, link.role,
                   EXISTS (
                       SELECT 1
                       FROM {} AS location
                       JOIN {} AS backend ON backend.backend_id = location.backend_id
                       WHERE location.file_id = content.file_id
                         AND location.status = 'present'
                         AND location.verified_at IS NOT NULL
                         AND backend.is_active
                   ) AS has_verified_location
            FROM {} AS link
            JOIN {} AS content ON content.file_id = link.file_id
            WHERE link.session_id = %s
        """).format(locationsTable, backendsTable, linksTable, filesTable)

        rows = connection.execute(statement, (sessionID,)).fetchall()
        actual = {name: (sha256, size, role) for name, sha256, size, role, available in rows}

        if actual != expected:
            raise ValueError("Checkpoint file links do not exactly match the manifest.")

        unavailable = [name for name, sha256, size, role, available in rows if not available]
        if unavailable:
            raise ValueError(f"Files lack verified active storage locations: {', '.join(sorted(unavailable))}")

        statement = sql.SQL("""
            UPDATE {}
            SET status = 'complete', manifest_hash = %s, completed_at = now()
            WHERE session_id = %s
        """).format(sessionsTable)
        connection.execute(statement, (manifestHash, sessionID))

        return manifestHash

    # +++++++++++++++++++++++ completeDerivedCheckpoint +++++++++++++++++++++++
    # Advanced database/checkpoint API. Observe the connection and transaction requirements in the
    # docstring.
    # Direct callers in this module: _saveDerivedSession.
    @classmethod
    def completeDerivedCheckpoint(cls, connection, postgres, sessionID, manifest):
        """Complete a derived checkpoint using the shared validation implementation."""
        return cls._completeSessionBundleCheckpoint(connection, postgres, sessionID, manifest, origin="derived")


    # -------------------------------------------------------------------------
    # Catalog registration
    # -------------------------------------------------------------------------
    # Resolve catalog identities and attach verified locations or logical file links in the caller's
    # transaction.
    
    @classmethod
    def _resolveCheckpointFileReuse(cls, connection, postgres, references):
        """Resolve existing checkpoint content without opening payload bytes.

        references maps NEW logical filenames to records returned by
        pglCheckpointFilesystem.getPublicationReference().

        The caller must:
            Establish reuse eligibility from current object/backing state.
            Own a READ COMMITTED transaction.
            Acquire the session publication lock before publication writes.

        Checks the configured database, content identity, active completed
        ownership, and present verified locations on active backends.

        Returns logical filename -> {fileID, sha256, size_bytes}.

        Locks eligible content/location/backend rows until outer commit.
        Does not refresh verification timestamps, read payloads, commit,
        retry, or modify references.
        """
        from psycopg.pq import TransactionStatus
        from psycopg.rows import tuple_row

        if not isinstance(references, dict):
            raise TypeError("references must be a dictionary.")

        if not references:
            return {}

        if connection.info.transaction_status != TransactionStatus.INTRANS:
            raise ValueError("Checkpoint reuse requires an active transaction.")

        databaseIdentity = cls._checkpointDatabaseIdentity(postgres)
        prepared = {}
        sizesByHash = {}

        def validateName(name):
            if (
                not isinstance(name, str)
                or not name
                or name.startswith("/")
                or "\\" in name
                or "\x00" in name
                or any(part in ("", ".", "..") for part in name.split("/"))
            ):
                raise ValueError("Checkpoint filenames must be valid relative POSIX paths.")

        for name, reference in references.items():
            validateName(name)
            if name == "manifest.json":
                raise ValueError("The outer manifest cannot be a reuse candidate.")

            fields = {"databaseIdentity", "sourceName", "sha256", "size_bytes"}
            if not isinstance(reference, dict) or set(reference) != fields:
                raise ValueError(f"Invalid checkpoint reuse reference: {name!r}")

            if reference["databaseIdentity"] != databaseIdentity:
                raise ValueError("Cross-database checkpoint payload reuse is unsupported.")

            validateName(reference["sourceName"])
            digest, size = reference["sha256"], reference["size_bytes"]

            if not isinstance(digest, str) or re.fullmatch(r"[0-9a-f]{64}", digest) is None:
                raise ValueError("Invalid reused SHA-256.")
            if type(size) is not int or not 0 <= size <= 9223372036854775807:
                raise ValueError("Invalid reused byte count.")
            if digest in sizesByHash and sizesByHash[digest] != size:
                raise ValueError("Conflicting sizes for the same reused content hash.")

            sizesByHash[digest] = size
            prepared[name] = {"sha256": digest, "size_bytes": size}

        with connection.cursor(row_factory=tuple_row) as cursor:
            cursor.execute("SHOW transaction_isolation")
            if cursor.fetchone()[0] != "read committed":
                raise ValueError("Checkpoint reuse requires READ COMMITTED isolation.")

            # Check actual lock ownership rather than accepting a Python flag.
            cursor.execute("""
                SELECT EXISTS (
                    SELECT 1
                    FROM pg_catalog.pg_locks AS held
                    JOIN pg_catalog.pg_class AS relation
                      ON relation.oid = held.relation
                    JOIN pg_catalog.pg_namespace AS namespace
                      ON namespace.oid = relation.relnamespace
                    WHERE held.pid = pg_catalog.pg_backend_pid()
                      AND held.locktype = 'relation'
                      AND held.granted
                      AND namespace.nspname = %s
                      AND relation.relname = 'session'
                      AND held.mode IN (
                          'ShareRowExclusiveLock',
                          'ExclusiveLock',
                          'AccessExclusiveLock'
                      )
                )
            """, (postgres.databaseSchema,))

            if cursor.fetchone() != (True,):
                raise ValueError("Acquire the checkpoint publication lock before resolving reuse.")

        sessions = sql.Identifier(postgres.databaseSchema, "session")
        links = sql.Identifier(postgres.databaseSchema, "session_files")
        files = sql.Identifier(postgres.databaseSchema, "files")
        locations = sql.Identifier(postgres.databaseSchema, "storage_locations")
        backends = sql.Identifier(postgres.databaseSchema, "storage_backends")

        statement = sql.SQL("""
            SELECT content.file_id, content.sha256, content.size_bytes
            FROM {files} AS content
            JOIN {locations} AS location
              ON location.file_id = content.file_id
            JOIN {backends} AS backend
              ON backend.backend_id = location.backend_id
            WHERE content.sha256 = ANY(%s::text[])
              AND content.deleted_at IS NULL
              AND location.deleted_at IS NULL
              AND location.status = 'present'
              AND location.verified_at IS NOT NULL
              AND backend.is_active
              AND EXISTS (
                  SELECT 1
                  FROM {links} AS reference
                  JOIN {sessions} AS owner
                    ON owner.session_id = reference.session_id
                  WHERE reference.file_id = content.file_id
                    AND reference.deleted_at IS NULL
                    AND owner.deleted_at IS NULL
                    AND owner.status = 'complete'
              )
            ORDER BY content.file_id, backend.backend_id, location.object_key
            FOR SHARE OF content, location, backend
        """).format(
            files=files,
            locations=locations,
            backends=backends,
            links=links,
            sessions=sessions,
        )

        with connection.cursor(row_factory=tuple_row) as cursor:
            cursor.execute(statement, (sorted(sizesByHash),))
            rows = cursor.fetchall()

        catalog = {}

        for fileID, digest, size in rows:
            if size != sizesByHash[digest]:
                raise ValueError("Registered content size differs from its reuse reference.")

            record = {"fileID": fileID, "sha256": digest, "size_bytes": size}
            if digest in catalog and catalog[digest] != record:
                raise ValueError("Conflicting registered identities for reused content.")

            catalog[digest] = record

        missing = sorted(name for name, identity in prepared.items() if identity["sha256"] not in catalog)

        if missing:
            examples = ", ".join(repr(name) for name in missing[:5])
            extra = f" and {len(missing) - 5} more" if len(missing) > 5 else ""
            raise ValueError(
                f"Cannot reuse checkpoint payloads: {examples}{extra}. "
                "Each requires active content, an active completed owner, "
                "and a present verified location on an active backend."
            )

        return {
            name: dict(catalog[identity["sha256"]])
            for name, identity in sorted(prepared.items())
        }

    # ++++++++++++++++++++++++++++ getOrCreateUser ++++++++++++++++++++++++++++
    # Advanced database/checkpoint API. Observe the connection and transaction requirements in the
    # docstring.
    # Direct callers in this module: saveDataset, saveRawSession, saveSession.
    @staticmethod
    def getOrCreateUser(connection, postgres, username, displayName=None):
        """Return a creator's user_id without changing an existing profile.

        Uses the caller's connection and transaction; does not commit.
        """
        if not isinstance(username, str) or not username.strip() or "\x00" in username:
            raise ValueError("username must be a nonempty string without NUL.")

        if displayName is not None and (not isinstance(displayName, str) or "\x00" in displayName):
            raise ValueError("displayName must be a string without NUL, or None.")

        table = sql.Identifier(postgres.databaseSchema, "users")
        statement = sql.SQL("INSERT INTO {} (username, display_name) VALUES (%s, %s) ON CONFLICT (username) DO NOTHING RETURNING user_id").format(table)
        row = connection.execute(statement, (username, displayName)).fetchone()

        if row is not None:
            return row[0]

        statement = sql.SQL("SELECT user_id FROM {} WHERE username = %s").format(table)
        row = connection.execute(statement, (username,)).fetchone()

        if row is None:
            raise RuntimeError("User could not be resolved; retry the transaction.")

        return row[0]

    # +++++++++++++++++++++++++++ getOrCreateSubject ++++++++++++++++++++++++++
    # Advanced database/checkpoint API. Observe the connection and transaction requirements in the
    # docstring.
    # Direct callers in this module: _recordSessionLabelMetadata.
    @staticmethod
    def getOrCreateSubject(connection, postgres, subjectID):
        """Register or reuse a subject without changing an existing description.

        Uses the caller's connection and transaction; does not commit.
        """
        if not isinstance(subjectID, str) or not subjectID.strip() or "\x00" in subjectID:
            raise ValueError("subjectID must be a nonempty string without NUL.")

        table = sql.Identifier(postgres.databaseSchema, "subjects")
        statement = sql.SQL("INSERT INTO {} (subject_id) VALUES (%s) ON CONFLICT (subject_id) DO NOTHING RETURNING subject_id").format(table)
        row = connection.execute(statement, (subjectID,)).fetchone()

        if row is not None:
            return row[0]

        statement = sql.SQL("SELECT subject_id FROM {} WHERE subject_id = %s").format(table)
        row = connection.execute(statement, (subjectID,)).fetchone()

        if row is None:
            raise RuntimeError("Subject could not be resolved; retry the transaction.")

        return row[0]

    # +++++++++++++++++++++++ getOrCreateStorageBackend +++++++++++++++++++++++
    # Advanced database/checkpoint API. Observe the connection and transaction requirements in the
    # docstring.
    # Direct callers in this module: _getConfiguredStorageBackend.
    @staticmethod
    def getOrCreateStorageBackend(connection, postgres, name, kind, urlPrefix):
        """Return a backend_id, rejecting conflicting existing configuration.

        Uses the caller's connection and transaction; does not commit.
        Does not probe storage or store credentials.
        """
        if not isinstance(name, str) or not name.strip() or "\x00" in name:
            raise ValueError("Backend name must be a nonempty string without NUL.")

        if kind not in {"local", "nas", "cloud"}:
            raise ValueError("Backend kind must be local, nas, or cloud.")

        if not isinstance(urlPrefix, str) or not urlPrefix.strip() or any(character in urlPrefix for character in ("\x00", "\n", "\r")):
            raise ValueError("Backend root must be a nonempty path or URL without NUL or newline characters.")

        table = sql.Identifier(postgres.databaseSchema, "storage_backends")
        statement = sql.SQL("INSERT INTO {} (name, kind, url_prefix) VALUES (%s, %s, %s) ON CONFLICT (name) DO NOTHING RETURNING backend_id").format(table)
        row = connection.execute(statement, (name, kind, urlPrefix)).fetchone()

        if row is not None:
            return row[0]

        statement = sql.SQL("SELECT backend_id, kind, url_prefix, is_active FROM {} WHERE name = %s").format(table)
        row = connection.execute(statement, (name,)).fetchone()

        if row is None:
            raise RuntimeError("Storage backend could not be resolved; retry the transaction.")

        backendID, existingKind, existingRoot, isActive = row

        if existingKind != kind or existingRoot != urlPrefix:
            raise ValueError(f"Storage backend {name!r} already exists with different configuration.")

        if not isActive:
            raise ValueError(f"Storage backend {name!r} is inactive.")

        return backendID

    # ++++++++++++++++++++++++++++ getOrCreateFile ++++++++++++++++++++++++++++
    # Advanced database/checkpoint API. Observe the connection and transaction requirements in the
    # docstring.
    # Direct callers in this module: _registerSessionBundleFiles, registerStagedRawCheckpoint.
    @staticmethod
    def getOrCreateFile(connection, postgres, sha256, sizeBytes):
        """Return a file_id for a content identity.

        Uses the caller's connection and transaction; does not commit.
        Storage locations are registered separately.
        """
        if not isinstance(sha256, str) or re.fullmatch(r"[0-9a-f]{64}", sha256) is None:
            raise ValueError("SHA-256 must contain 64 lowercase hexadecimal characters.")

        if isinstance(sizeBytes, bool) or not isinstance(sizeBytes, int) or not 0 <= sizeBytes <= 9223372036854775807:
            raise ValueError("sizeBytes must be a nonnegative PostgreSQL bigint.")

        table = sql.Identifier(postgres.databaseSchema, "files")
        statement = sql.SQL("INSERT INTO {} (sha256, size_bytes, kind) VALUES (%s, %s, %s) ON CONFLICT (sha256) DO NOTHING RETURNING file_id").format(table)
        row = connection.execute(statement, (sha256, sizeBytes, "file")).fetchone()

        if row is not None:
            return row[0]

        statement = sql.SQL("SELECT file_id, size_bytes, kind FROM {} WHERE sha256 = %s").format(table)
        row = connection.execute(statement, (sha256,)).fetchone()

        if row is None:
            raise RuntimeError("File identity could not be resolved; retry the transaction.")

        fileID, existingSize, existingKind = row

        if existingSize != sizeBytes or existingKind != "file":
            raise ValueError("Existing SHA-256 has conflicting size or kind; file identity was not changed.")

        return fileID

    # ++++++++++++++++++++ verifyAndRegisterStorageLocation +++++++++++++++++
    @classmethod
    def verifyAndRegisterStorageLocation(cls, connection, postgres, fileID, backendID, objectKey, storageOptions=None, *, accessContext=None, progress=None):
        """Verify stored bytes and register their backend-relative location.

        Uses the caller's SQL transaction and does not commit.
        Registered roots and relative object keys remain unchanged.

        A supplied payload access context is borrowed. Otherwise this method
        creates and closes its own context.

        Optional progress reports byte-based verification and SQL registration.
        All existing integrity and location-identity checks are retained.
        """
        if progress is not None:
            progress(0, "Resolving registered file identity")

        for label, value in (("fileID", fileID), ("backendID", backendID)):
            if type(value) is not int or not 0 <= value <= 9223372036854775807:
                raise ValueError(f"{label} must be a nonnegative PostgreSQL bigint.")

        if not isinstance(objectKey, str) or objectKey.startswith("/") or "\\" in objectKey or "\x00" in objectKey or any(part in {"", ".", ".."} for part in objectKey.split("/")):
            raise ValueError("objectKey must be a valid relative POSIX path.")

        if storageOptions is not None and not isinstance(storageOptions, dict):
            raise TypeError("storageOptions must be a dictionary or None.")

        if accessContext is not None:
            if not isinstance(accessContext, pglDatabaseAccess):
                raise TypeError("accessContext must be a pglDatabaseAccess instance.")

            if storageOptions:
                raise ValueError("Configure storage options on accessContext, not on both arguments.")

            if cls._checkpointDatabaseIdentity(accessContext._postgres) != cls._checkpointDatabaseIdentity(postgres):
                raise ValueError("The supplied payload context belongs to a different configured database.")

        filesTable = sql.Identifier(postgres.databaseSchema, "files")
        backendsTable = sql.Identifier(postgres.databaseSchema, "storage_backends")
        locationsTable = sql.Identifier(postgres.databaseSchema, "storage_locations")

        statement = sql.SQL("SELECT sha256, size_bytes FROM {} WHERE file_id = %s").format(filesTable)
        identity = connection.execute(statement, (fileID,)).fetchone()

        if identity is None:
            raise ValueError(f"Unknown file_id: {fileID}")

        statement = sql.SQL("SELECT url_prefix, is_active FROM {} WHERE backend_id = %s").format(backendsTable)
        backend = connection.execute(statement, (backendID,)).fetchone()

        if backend is None or not backend[1]:
            raise ValueError(f"Storage backend is missing or inactive: {backendID}")

        statement = sql.SQL("SELECT file_id FROM {} WHERE backend_id = %s AND object_key = %s").format(locationsTable)
        existing = connection.execute(statement, (backendID, objectKey)).fetchone()

        if existing is not None and existing[0] != fileID:
            raise ValueError("Storage path is already registered to different content.")

        ownsAccess = accessContext is None
        access = pglDatabaseAccess(postgres, {backendID: storageOptions or {}}) if ownsAccess else accessContext

        try:
            if progress is not None:
                progress(None, "Opening stored file for verification")

            filesystem, root = access.resolve(backendID, backend[0])
            actual = pglStorage.hashFile(filesystem, posixpath.join(root, objectKey), progress=progress, expectedSize=identity[1], description="Verifying stored file for registration")

            if actual["sha256"] != identity[0] or actual["size_bytes"] != identity[1]:
                raise ValueError("Stored payload does not match the registered file identity.")

        finally:
            if ownsAccess:
                access.close()

        if progress is not None:
            progress(None, "Registering verified storage location")

        # Verification precedes catalog publication. Existing triggers retain
        # responsibility for deletion-marker coordination.
        statement = sql.SQL("""
            INSERT INTO {} AS location
                (file_id, backend_id, object_key, status, verified_at)
            VALUES (%s, %s, %s, 'present', now())
            ON CONFLICT (backend_id, object_key) DO UPDATE
            SET status = 'present', verified_at = EXCLUDED.verified_at
            WHERE location.file_id = EXCLUDED.file_id
            RETURNING object_key
        """).format(locationsTable)

        row = connection.execute(statement, (fileID, backendID, objectKey)).fetchone()

        if row is None:
            raise ValueError("Storage path was registered concurrently to different content.")

        return row[0]

    # ++++++++++++++++++++++++++ attachCheckpointFile +++++++++++++++++++++++++
    # Advanced database/checkpoint API. Observe the connection and transaction requirements in the
    # docstring.
    # Direct callers in this module: _registerSessionBundleFiles, registerStagedRawCheckpoint.
    @staticmethod
    def attachCheckpointFile(connection, postgres, sessionID, name, fileID, role=None, subjectID=None):
        """Attach a file to an in-progress checkpoint.

        Uses the caller's connection and transaction; does not commit.
        Duplicate logical names are rejected, not overwritten.
        Does not verify payload availability.
        """
        for label, value in (("sessionID", sessionID), ("fileID", fileID)):
            if isinstance(value, bool) or not isinstance(value, int) or not 0 <= value <= 9223372036854775807:
                raise ValueError(f"{label} must be a nonnegative PostgreSQL bigint.")

        if not isinstance(name, str) or name.startswith("/") or "\\" in name or "\x00" in name or any(part in {"", ".", ".."} for part in name.split("/")):
            raise ValueError("name must be a valid relative POSIX path.")

        for label, value in (("role", role), ("subjectID", subjectID)):
            if value is not None and (not isinstance(value, str) or not value.strip() or "\x00" in value):
                raise ValueError(f"{label} must be a nonempty string without NUL, or None.")

        table = sql.Identifier(postgres.databaseSchema, "session_files")
        statement = sql.SQL("INSERT INTO {} (session_id, name, file_id, role, subject_id) VALUES (%s, %s, %s, %s, %s)").format(table)
        connection.execute(statement, (sessionID, name, fileID, role, subjectID))


    # -------------------------------------------------------------------------
    # Lineage and lifecycle inspection
    # -------------------------------------------------------------------------
    # Read-only previews. These queries alone do not authorize concurrent lifecycle changes.

    # +++++++++++++++++++++++++ getDownstreamSessions +++++++++++++++++++++++++
    # Advanced database/checkpoint API. Observe the connection and transaction requirements in the
    # docstring.
    # Direct callers in this module: _getSessionDeletionRecords.
    @staticmethod
    def getDownstreamSessions(connection, postgres, sessionID):
        """Return all descendants, including deleted sessions, ordered by ID.

        Follows parent_session_id recursively. The requested session itself
        is excluded, even if a cycle leads back to it.

        Returns a list of metadata dictionaries. An existing session with
        no descendants returns an empty list; an unknown session raises
        ValueError.

        Read-only: does not change rows, access payloads, or commit.
        One SQL statement provides a consistent snapshot.

        This is an informational lookup, not a concurrency-safe deletion
        decision. Deletion must repeat it under the required locks.
        """
        from psycopg.rows import dict_row

        if isinstance(sessionID, bool) or not isinstance(sessionID, int) or not 0 <= sessionID <= 9223372036854775807:
            raise ValueError("sessionID must be a nonnegative PostgreSQL bigint.")

        sessions = sql.Identifier(postgres.databaseSchema, "session")

        # Recurse over IDs only. UNION removes previously visited IDs,
        # including those reached again through a cycle.
        statement = sql.SQL("""
            WITH RECURSIVE reachable(session_id) AS (
                SELECT session_id
                FROM {sessions}
                WHERE session_id = %s

                UNION

                SELECT child.session_id
                FROM {sessions} AS child
                JOIN reachable AS parent
                  ON child.parent_session_id = parent.session_id
            )
            SELECT checkpoint.session_id,
                   checkpoint.parent_session_id,
                   checkpoint.root_session_id,
                   checkpoint.origin,
                   checkpoint.kind,
                   checkpoint.status,
                   checkpoint.description,
                   checkpoint.created_at,
                   checkpoint.deleted_at
            FROM {sessions} AS checkpoint
            JOIN reachable
              ON reachable.session_id = checkpoint.session_id
            ORDER BY checkpoint.session_id
        """).format(sessions=sessions)

        with connection.cursor(row_factory=dict_row) as cursor:
            cursor.execute(statement, (sessionID,))
            records = cursor.fetchall()

        if not records:
            raise ValueError(f"Unknown session: {sessionID}")

        return [record for record in records if record["session_id"] != sessionID]

    # ++++++++++++++++++++++++ getSessionDeletionImpact +++++++++++++++++++++++
    # Advanced database/checkpoint API. Observe the connection and transaction requirements in the
    # docstring.
    @staticmethod
    def getSessionDeletionImpact(connection, postgres, sessionID):
        """Preview which linked content would become eligible for soft deletion.

        Includes deleted sessions. Does not change database rows or payloads.

        Files remain shared when another nondeleted session references them,
        regardless of that session's publication status.

        This is an informational preview, not a concurrency-safe deletion
        decision. The actual delete operation must coordinate concurrent
        changes and recompute eligibility inside its transaction.
        """
        if (
            isinstance(sessionID, bool)
            or not isinstance(sessionID, int)
            or not 0 <= sessionID <= 9223372036854775807
        ):
            raise ValueError("sessionID must be a nonnegative PostgreSQL bigint.")

        sessions = sql.Identifier(postgres.databaseSchema, "session")
        links = sql.Identifier(postgres.databaseSchema, "session_files")
        locations = sql.Identifier(postgres.databaseSchema, "storage_locations")

        # One statement provides a consistent snapshot for this preview.
        statement = sql.SQL("""
            SELECT checkpoint.deleted_at,
                   linked.file_id,
                   CASE WHEN linked.file_id IS NOT NULL THEN EXISTS (
                       SELECT 1
                       FROM {links} AS other_link
                       JOIN {sessions} AS other_session
                         ON other_session.session_id = other_link.session_id
                       WHERE other_link.file_id = linked.file_id
                         AND other_session.session_id <> checkpoint.session_id
                         AND other_session.deleted_at IS NULL
                   ) ELSE false END AS shared_with_active_session,
                   (
                       SELECT count(*)
                       FROM {locations} AS location
                       WHERE location.file_id = linked.file_id
                   ) AS location_count
            FROM {sessions} AS checkpoint
            LEFT JOIN (
                SELECT DISTINCT session_id, file_id
                FROM {links}
                WHERE session_id = %s
            ) AS linked
              ON linked.session_id = checkpoint.session_id
            WHERE checkpoint.session_id = %s
            ORDER BY linked.file_id
        """).format(sessions=sessions, links=links, locations=locations)

        rows = connection.execute(statement, (sessionID, sessionID)).fetchall()

        if not rows:
            raise ValueError(f"Unknown session: {sessionID}")

        exclusive = []
        shared = []
        exclusiveLocationCount = 0
        sharedLocationCount = 0

        for deletedAt, fileID, sharedWithActiveSession, locationCount in rows:
            if fileID is None:
                continue

            if sharedWithActiveSession:
                shared.append(fileID)
                sharedLocationCount += locationCount
            else:
                exclusive.append(fileID)
                exclusiveLocationCount += locationCount

        return {
            "session_id": sessionID,
            "deleted_at": rows[0][0],
            "exclusive_file_ids": exclusive,
            "shared_file_ids": shared,
            "exclusive_location_count": exclusiveLocationCount,
            "shared_location_count": sharedLocationCount,
        }


    # =========================================================================
    # IMPLEMENTATION SUPPORT
    # =========================================================================

    # -------------------------------------------------------------------------
    # Configuration, database identity, and checkpoint baselines
    # -------------------------------------------------------------------------
    # Shared database binding, destination selection, cache configuration, and saved-history
    # boundaries.

    # +++++++++++++++++++++++++ _resolveBackendAccess +++++++++++++++++++++++
    @staticmethod
    def _resolveBackendAccess(postgres, registeredRoot, *, storageOptions=None):
        """Resolve caller-side access without changing a registered root.

        Called by database payload readers and publication coordinators.
        Returns (filesystem, filesystemRoot).

        Server-local roots:
            Absolute POSIX paths and local file:// URLs identify paths on the
            installation machine, not automatically on the calling computer.

            Direct access is permitted only for a locally loaded/constructed
            configuration targeting a loopback PostgreSQL endpoint.

            SSH access requires PostgreSQL to be reached through the SSH
            endpoint's loopback interface. The configured SSH endpoint is
            therefore assumed to be the installation/storage machine.

        Explicit remote URLs:
            Use their own fsspec protocol independently of the SQL transport.
            Their existing authentication and host-verification behavior is
            governed by that backend, not by the inferred SSH adapter.

        Initial restrictions:
            Relative paths, server-side ~ expansion, filesystem chains, and
            remote authorities in file:// URLs are rejected.
            Inferred SSH access uses the caller's resolved SSH configuration.
            Nonempty storageOptions are rejected for inferred SSH access,
            rather than allowing an endpoint or security-policy override.

        Does not query SQL, write payloads, register locations, or modify the
        supplied PostgreSQL configuration.

        Resolution may open an SSH/backend connection.
        A returned inferred-SSH filesystem is caller-owned: retain it while
        lazy readers depend on it, then close it when no longer needed.

        Explicit remote URL support retains existing behavior; this function
        does not establish that every remote protocol has been tested.

        Raises for ambiguous locations or unsupported access configurations.
        Never falls back from failed SSH access to client-local access.
        """
        import ipaddress
        from urllib.parse import unquote, urlsplit

        from fsspec.core import url_to_fs
        from fsspec.implementations.local import LocalFileSystem

        if not isinstance(registeredRoot, str) or not registeredRoot.strip():
            raise ValueError("Registered storage root must be a nonempty string.")

        if any(character in registeredRoot for character in ("\x00", "\n", "\r")):
            raise ValueError("Registered storage root contains invalid control characters.")

        if storageOptions is not None and not isinstance(storageOptions, dict):
            raise TypeError("storageOptions must be a dictionary or None.")

        options = dict(storageOptions or {})

        # A URI can contain :: within an IPv6 authority. Examine filesystem
        # chaining outside that authority instead of rejecting IPv6 URLs.
        explicitURL = "://" in registeredRoot
        parsed = urlsplit(registeredRoot) if explicitURL else None

        if explicitURL:
            chainOutsideAuthority = "::" in registeredRoot.split("://", 1)[0] or "::" in parsed.path

            if chainOutsideAuthority:
                raise NotImplementedError("Filesystem chains are not supported for database backend roots.")

            protocol = parsed.scheme.lower()

            if protocol not in {"file", "local"}:
                return url_to_fs(registeredRoot, **options)

            if parsed.netloc not in ("", "localhost") or parsed.query or parsed.fragment:
                raise ValueError("A local storage URL must contain only a local authority and an absolute path.")

            serverRoot = unquote(parsed.path)
        else:
            if "::" in registeredRoot:
                raise NotImplementedError("Filesystem chains are not supported for database backend roots.")

            serverRoot = registeredRoot

        # Decode file:// paths before checking them. Never resolve these paths
        # with Path.resolve() on a client accessing a remote installation.
        if (
            not serverRoot.startswith("/")
            or serverRoot.startswith("//")
            or "\\" in serverRoot
            or any(character in serverRoot for character in ("\x00", "\n", "\r"))
            or any(part in {".", ".."} for part in serverRoot.split("/"))
        ):
            raise ValueError("Server-local storage roots must be absolute POSIX paths without dot segments, backslashes, or control characters.")

        if postgres is None:
            raise ValueError("A database access context is required to resolve a server-local storage root.")

        postgres._validateValues()

        # ++++++++++++++++++++++++++ isLoopback +++++++++++++++++++++++++++++
        def isLoopback(host):
            """Recognize explicit loopback endpoints without DNS inference."""
            if host.lower() == "localhost":
                return True

            candidate = host[1:-1] if host.startswith("[") and host.endswith("]") else host

            try:
                return ipaddress.ip_address(candidate).is_loopback
            except ValueError:
                return False

        if postgres.connectionTransport == "ssh":
            if not isLoopback(postgres.connectionHost):
                raise ValueError("Cannot infer payload access when SSH forwards PostgreSQL to another host. Server-local payload access currently requires a loopback database endpoint on the SSH installation machine.")

            if options:
                raise ValueError("storageOptions cannot override inferred SSH access. Configure the caller's SSH identity through pglPostgres and OpenSSH configuration.")

            from .pglSSH import pglSSHFilesystem

            access = postgres.getSSHAccessConfiguration()
            filesystem = pglSSHFilesystem(access, ioTimeoutSeconds=postgres.ioTimeoutSeconds)
            return filesystem, serverRoot

        if postgres.connectionTransport == "direct":
            if not isLoopback(postgres.connectionHost):
                raise ValueError("A direct remote PostgreSQL connection does not establish access to server-local payload paths. Use SSH to the installation machine or an explicit remote storage URL.")

            if getattr(postgres, "_configurationLoadedRemotely", False):
                raise ValueError("A remotely loaded direct-loopback configuration cannot authorize access to client-local payload paths.")

            # Local direct-loopback access is an explicit deployment
            # assumption, not proof that an externally managed tunnel or
            # container shares the caller's filesystem.
            filesystem = LocalFileSystem(**options)
            return filesystem, serverRoot

        raise ValueError("Unsupported database connection transport.")

    # ++++++++++++++++++++++ _checkpointDatabaseIdentity ++++++++++++++++++++++
    # Direct callers in this module: _bindDatasetStorage, _prepareCheckpointBaseline,
    # _resolveDatasetStorage, _selectAncestralReplayInput, getDatasetBehaviorData, getDatasetData,
    # getSessionPipeline, saveDataset.
    @staticmethod
    def _checkpointDatabaseIdentity(postgres):
        """Describe the configured database endpoint without credentials.

        This runtime identity distinguishes configured destinations.
        It is not a globally stable database identity across relocation,
        aliases, restores, or alternate connection transports.
        """
        identity = {
            "transport": postgres.connectionTransport,
            "host": postgres.connectionHost,
            "port": postgres.connectionPort,
            "database": postgres.databaseName,
            "schema": postgres.databaseSchema,
        }

        if postgres.connectionTransport == "ssh":
            identity["sshHost"] = postgres.sshHost
            identity["sshPort"] = postgres.sshPort
            identity["sshUser"] = postgres.sshUser

        return identity

    # ++++++++++++++++++++++ _getConfiguredStorageBackend ++++++++++++++++++++
    @classmethod
    def _getConfiguredStorageBackend(cls, connection, postgres, storageOptions=None):
        """Resolve/register the first configured payload destination.

        Called by session and dataset save coordinators when backendID is
        omitted. Uses the caller's SQL transaction; does not commit.

        Registers the original configured root, never a caller-derived SSH
        URL. Bare absolute paths and local file URLs remain kind='local',
        regardless of whether this caller will access them through SFTP.

        Existing active registrations are reused without changing their root
        or kind. Actual destination access is resolved by the save coordinator
        before writing payloads.

        Explicit remote protocols are classified without opening a connection.
        Unknown protocols require explicit backend registration.

        storageOptions is retained for interface compatibility. This metadata
        operation does not use or persist authentication options.

        Does not write payload files or test filesystem permissions.
        Errors propagate.
        """
        from urllib.parse import unquote, urlsplit

        if not postgres.storageLocations:
            raise ValueError("No payload destination is configured in postgres.storageLocations.")

        configuredRoot = postgres.storageLocations[0]

        if not isinstance(configuredRoot, str) or not configuredRoot.strip():
            raise ValueError("The configured payload destination must be a nonempty path or URL.")

        if any(character in configuredRoot for character in ("\x00", "\n", "\r")):
            raise ValueError("The configured payload destination contains invalid control characters.")

        if storageOptions is not None and not isinstance(storageOptions, dict):
            raise TypeError("storageOptions must be a dictionary or None.")

        explicitURL = "://" in configuredRoot
        parsed = urlsplit(configuredRoot) if explicitURL else None

        if explicitURL:
            if "::" in configuredRoot.split("://", 1)[0] or "::" in parsed.path:
                raise NotImplementedError("Filesystem chains are not supported for database backend roots.")

            protocol = parsed.scheme.lower()
        else:
            if "::" in configuredRoot:
                raise NotImplementedError("Filesystem chains are not supported for database backend roots.")

            protocol = "file"

        if protocol in {"file", "local"}:
            if explicitURL:
                if parsed.netloc not in ("", "localhost") or parsed.query or parsed.fragment:
                    raise ValueError("A local storage URL must contain only a local authority and an absolute path.")

                serverRoot = unquote(parsed.path)
            else:
                serverRoot = configuredRoot

            if (
                not serverRoot.startswith("/")
                or serverRoot.startswith("//")
                or "\\" in serverRoot
                or any(character in serverRoot for character in ("\x00", "\n", "\r"))
                or any(part in {".", ".."} for part in serverRoot.split("/"))
            ):
                raise ValueError("Server-local storage roots must be absolute POSIX paths without dot segments, backslashes, or control characters.")

            kind = "local"
        elif protocol in {"ssh", "sftp", "smb", "nfs"}:
            kind = "nas"
        elif protocol in {"s3", "gs", "gcs", "az", "abfs", "abfss", "adl"}:
            kind = "cloud"
        else:
            kind = None

        # Serialize registration for the exact configured root. Preserve its
        # spelling and identity rather than creating a personal access URL.
        lockName = f"pgl.storage_backend:{postgres.databaseSchema}:{configuredRoot}"
        postgres.acquireTransactionLock(connection, lockName, description="storage-backend registration", timeoutSeconds=postgres.lockTimeoutSeconds)

        table = sql.Identifier(postgres.databaseSchema, "storage_backends")
        statement = sql.SQL("""
            SELECT backend_id, is_active
            FROM {}
            WHERE url_prefix = %s
            ORDER BY is_active DESC, backend_id ASC
            LIMIT 1
        """).format(table)
        existing = connection.execute(statement, (configuredRoot,)).fetchone()

        if existing is not None:
            backendID, isActive = existing

            if not isActive:
                raise ValueError("The configured payload destination is registered as inactive.")

            return backendID

        if kind is None:
            raise ValueError("Cannot automatically classify the configured storage protocol. Register the backend explicitly and supply backendID.")

        rootHash = hashlib.sha256(configuredRoot.encode("utf-8")).hexdigest()
        backendName = f"configured_{rootHash}"

        return cls.getOrCreateStorageBackend(connection, postgres, backendName, kind, configuredRoot)

    # +++++++++++++++++++++++ _prepareCheckpointBaseline ++++++++++++++++++++++
    # Direct callers in this module: _bindCheckpointBaseline, saveSession.
    @classmethod
    def _prepareCheckpointBaseline(cls, session, sessionID, postgres):
        """Build runtime checkpoint metadata without modifying the session.

        Caller must establish that the supplied history corresponds to the
        checkpoint being loaded or published.

        Preparation can serialize history and fail, so saves must perform it
        before commit. Assignment to the working object happens afterward.

        Does not inspect scientific payloads or clear failure restrictions.
        """
        from .pglPipeline import pglActionable

        if not isinstance(session, pglActionable):
            raise TypeError("Checkpoint baseline tracking requires a pglActionable object.")

        if type(sessionID) is not int or not 0 <= sessionID <= 9223372036854775807:
            raise ValueError("sessionID must be a nonnegative PostgreSQL bigint.")

        historyHashes = []

        for entry in session.actionHistory:
            document = json.loads(entry.toJSON())
            content = cls.encodeRawManifest(document)
            historyHashes.append(hashlib.sha256(content).hexdigest())

        return {
            "version": 1,
            "sessionID": sessionID,
            "databaseIdentity": cls._checkpointDatabaseIdentity(postgres),
            "historyCount": len(historyHashes),
            "historyHashes": historyHashes,
        }

    # ++++++++++++++++++++++++ _bindCheckpointBaseline ++++++++++++++++++++++++
    # Direct callers in this module: loadSession.
    @classmethod
    def _bindCheckpointBaseline(cls, session, sessionID, postgres):
        """Bind a prepared checkpoint/history boundary to a working object.

        Used after verified loading. Saving prepares its baseline separately
        before commit and installs it only after successful publication.

        Never clears failed-action safety state.
        """
        baseline = cls._prepareCheckpointBaseline(session, sessionID, postgres)
        session._checkpointBaseline = baseline

    @staticmethod
    def _getCheckpointPublicationInfo(connection, postgres, sessionID):
        """Read publication metadata for a completed checkpoint.

        Uses the caller's connection and transaction. Does not modify records
        or access payloads. Deleted checkpoints may be inspected; the calling
        load/save operation owns visibility and lifecycle validation.

        Returns the completion timestamp in the recorded saving timezone.
        Without a recorded timezone, returns UTC and leaves the timezone
        field None so displays can identify that historical limitation.

        Missing completion timestamps remain None, not created_at fallbacks.
        Invalid stored timezone names or naive database timestamps raise.
        """
        from datetime import timezone
        from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

        if type(sessionID) is not int or not 0 <= sessionID <= 9223372036854775807:
            raise ValueError("sessionID must be a nonnegative PostgreSQL bigint.")

        sessions = sql.Identifier(postgres.databaseSchema, "session")
        users = sql.Identifier(postgres.databaseSchema, "users")

        statement = sql.SQL("""
            SELECT checkpoint.completed_at, checkpoint.saved_timezone,
                   creator.username
            FROM {} AS checkpoint
            JOIN {} AS creator ON creator.user_id = checkpoint.created_by
            WHERE checkpoint.session_id = %s
              AND checkpoint.status = 'complete'
        """).format(sessions, users)

        record = connection.execute(statement, (sessionID,)).fetchone()

        if record is None:
            raise ValueError(f"Completed checkpoint publication metadata is unavailable: {sessionID}")

        completedAt, savedTimezone, savedBy = record
        displayTimezone = timezone.utc

        if savedTimezone is not None:
            if not isinstance(savedTimezone, str) or not savedTimezone or savedTimezone != savedTimezone.strip():
                raise ValueError(f"Checkpoint {sessionID}: invalid saved timezone {savedTimezone!r}.")

            try:
                displayTimezone = ZoneInfo(savedTimezone)
            except (ValueError, ZoneInfoNotFoundError) as error:
                raise ValueError(f"Checkpoint {sessionID}: saved timezone {savedTimezone!r} is unavailable or invalid.") from error

        if completedAt is not None:
            if completedAt.utcoffset() is None:
                raise ValueError(f"Checkpoint {sessionID}: completed_at must include timezone information.")

            # Ignore the SQL connection's display timezone. Use the recorded
            # publisher timezone, or explicitly use UTC for historical rows.
            completedAt = completedAt.astimezone(displayTimezone)

        return {
            "checkpointSavedDateTime": completedAt.isoformat() if completedAt is not None else None,
            "checkpointSavedTimezone": savedTimezone,
            "checkpointSavedBy": savedBy,
        }

    # +++++++++++++++++++++ _getCheckpointHistoryBoundary +++++++++++++++++++++
    # Direct callers in this module: _loadPipelineInput, _selectAncestralReplayInput,
    # getSessionPipeline, saveSession.
    @classmethod
    def _getCheckpointHistoryBoundary(cls, session):
        """Return the verified working-history boundary, or None if unbound.

        Reject shortened or edited baseline history rather than guessing where
        replay should begin. Appending new history entries is permitted.

        This validates history metadata only, not scientific payload contents.
        """
        from .pglPipeline import pglActionable

        if not isinstance(session, pglActionable):
            raise TypeError("Checkpoint baseline tracking requires a pglActionable object.")

        baseline = session._checkpointBaseline

        if not baseline:
            return None

        expectedFields = {"version", "sessionID", "databaseIdentity", "historyCount", "historyHashes"}

        if set(baseline) != expectedFields or type(baseline["version"]) is not int or baseline["version"] != 1:
            raise ValueError("Invalid checkpoint baseline record.")

        count = baseline["historyCount"]
        hashes = baseline["historyHashes"]

        if type(count) is not int or count < 0 or not isinstance(hashes, list) or len(hashes) != count:
            raise ValueError("Invalid checkpoint baseline history inventory.")

        if any(not isinstance(value, str) or re.fullmatch(r"[0-9a-f]{64}", value) is None for value in hashes):
            raise ValueError("Invalid checkpoint baseline history fingerprint.")

        if len(session.actionHistory) < count:
            raise ValueError("Checkpoint history was shortened after loading. Cannot safely determine the replay boundary.")

        for index, expectedHash in enumerate(hashes):
            document = json.loads(session.actionHistory[index].toJSON())
            actualHash = hashlib.sha256(cls.encodeRawManifest(document)).hexdigest()

            if actualHash != expectedHash:
                raise ValueError(f"Checkpoint history entry {index} was changed after loading. Edit an extracted pipeline instead of historical records.")

        return count

    # +++++++++++++++++++++++++ _resolveCacheDirectory ++++++++++++++++++++++++
    # Direct callers in this module: loadSession.
    @staticmethod
    def _resolveCacheDirectory(cacheDirectory=None, *, settings):
        """Resolve an explicit cache path or settings.cacheDir without creating it.

        Accepts ordinary local filesystem paths, not URLs or fsspec chains.
        An invalid explicit override raises rather than falling back silently.
        """
        import os
        from pathlib import Path

        value = settings.cacheDir if cacheDirectory is None else cacheDirectory

        try: text = os.fspath(value)
        except TypeError as error: raise ValueError("Cache directory must be a local filesystem path.") from error

        if not isinstance(text, str) or not text.strip(): raise ValueError("Cache directory must be a nonempty local filesystem path.")
        if any(character in text for character in ("\x00", "\n", "\r")): raise ValueError("Cache directory must not contain NUL or newline characters.")
        if "://" in text or "::" in text: raise ValueError("Cache directory must be an ordinary local path, not a URL or fsspec chain.")

        return str(Path(text).expanduser().resolve())

    # ++++++++++++++++++++++++++++ _mneCacheContext +++++++++++++++++++++++++
    @classmethod
    def _mneCacheContext(cls, postgres, sessionID):
        """Build a caller-local MNE cache namespace for this database endpoint.

        Called by session bundle loading before installing deferred MNE
        backings. Includes SSH endpoint information so different installations
        sharing loopback PostgreSQL settings do not collide.

        Uses the existing runtime database identity policy. Different aliases,
        transports, or SSH users may produce separate cache namespaces even
        when they reach the same database.

        Does not connect, create directories, or inspect payloads.

        Older cache directories remain untouched; this namespace version may
        materialize a new cache instead of reusing an older one.
        """
        if type(sessionID) is not int or not 0 <= sessionID <= 9223372036854775807:
            raise ValueError("Invalid cache session ID.")

        document = {"cacheNamespaceVersion": 2, "databaseIdentity": cls._checkpointDatabaseIdentity(postgres)}
        digest = hashlib.sha256(pglStorage.encodeJSON(document)).hexdigest()[:16]
        label = re.sub(r"[^A-Za-z0-9_-]", "_", f"{postgres.databaseName}-{postgres.databaseSchema}")[:64]

        return {"namespace": f"{label}-{digest}", "sessionID": sessionID}

    # -------------------------------------------------------------------------
    # Session loading: bundle coordination
    # -------------------------------------------------------------------------
    # Resolve catalog inventories and products before reconstructing file-backed behavioral and MNE
    # contents.

    # +++++++++++++++++++++++++++ _loadSessionBundle ++++++++++++++++++++++++++
    # Direct callers in this module: loadDerivedSession, loadRawSessionBundle.
    # +++++++++++++++++++++++++++ _loadSessionBundle +++++++++++++++++++++++++
    @classmethod
    def _loadSessionBundle(cls, connection, postgres, sessionID, storageOptionsByBackend=None, *, includeDeleted=False, maxManifestBytes=16 * 1024 * 1024, cacheDirectory=None, directLocalPolicy="materialize", origin="derived"):
        """Load a completed bundle using caller-resolved payload access.

        Called by loadDerivedSession() and loadRawSessionBundle().
        Uses the caller's SQL transaction for catalog lookup.

        Supports raw session v1/v2, derived behavior/session v1/v2/v3,
        and derived MRI v1.
        Checks manifest integrity and encoding, exact file/product links,
        registered availability, and matrix descriptors.

        Owns one access context for manifest and checkpoint-file reads.
        Successful reconstruction transfers it to the session filesystem.
        Matrices retain their independently owned access contexts.

        Derived-file payloads are not downloaded here. Their references borrow
        the checkpoint filesystem and retain the supplied cacheDirectory.

        Returned objects retain no SQL connection. On failure, closes owned
        contexts and matrices. Does not publish records or modify payloads.
        """
        if origin not in ("raw", "derived"):
            raise ValueError("Bundle origin must be raw or derived.")

        if type(sessionID) is not int or not 0 <= sessionID <= 9223372036854775807:
            raise ValueError("sessionID must be a nonnegative PostgreSQL bigint.")

        if type(includeDeleted) is not bool:
            raise ValueError("includeDeleted must be a boolean.")

        if type(maxManifestBytes) is not int or maxManifestBytes <= 0:
            raise ValueError("maxManifestBytes must be a positive integer.")

        if directLocalPolicy not in ("materialize", "immutable"):
            raise ValueError("directLocalPolicy must be 'materialize' or 'immutable'.")

        sessions = sql.Identifier(postgres.databaseSchema, "session")
        links = sql.Identifier(postgres.databaseSchema, "session_files")
        files = sql.Identifier(postgres.databaseSchema, "files")
        locations = sql.Identifier(postgres.databaseSchema, "storage_locations")
        backends = sql.Identifier(postgres.databaseSchema, "storage_backends")

        statement = sql.SQL("SELECT origin, status, contract_version, manifest_hash FROM {} WHERE session_id = %s AND (%s OR deleted_at IS NULL)").format(sessions)
        checkpoint = connection.execute(statement, (sessionID, includeDeleted)).fetchone()

        if checkpoint is None: raise ValueError(f"Unknown or deleted checkpoint: {sessionID}")

        checkpointOrigin, status, contractVersion, manifestHash = checkpoint
        if status != "complete": raise ValueError("Only completed checkpoints can be loaded.")

        supportedContracts = {
            "raw": ("pgl.raw.session.v1", "pgl.raw.session.v2"),
            "derived": (
                "pgl.derived.behavior.v1",
                "pgl.derived.behavior.v2",
                "pgl.derived.behavior.v3",
                "pgl.derived.session.v1",
                "pgl.derived.session.v2",
                "pgl.derived.session.v3",
                "pgl.derived.mri.v1",
                "pgl.derived.mri.v2",
            ),
        }

        if checkpointOrigin != origin or contractVersion not in supportedContracts[origin]:
            raise ValueError("Unsupported checkpoint origin/contract.")

        hasMNE = contractVersion in (
            "pgl.raw.session.v1",
            "pgl.derived.session.v1",
            "pgl.derived.session.v2",
            "pgl.derived.session.v3",
        )
        payloadRole = "acquisition" if origin == "raw" else "derived"

        if hasMNE and (cacheDirectory is None or not str(cacheDirectory).strip()):
            raise ValueError("MNE restoration requires an explicit cacheDirectory.")

        # Advanced behavioral-only loaders can omit the cache and supply it
        # later to getDerivedFile(). The public loadSession resolves it for v3.
        statement = sql.SQL("""
            SELECT link.name, link.role, content.file_id, content.sha256,
                   content.size_bytes, link.deleted_at, content.deleted_at
            FROM {} AS link
            JOIN {} AS content ON content.file_id = link.file_id
            WHERE link.session_id = %s
            ORDER BY link.name
        """).format(links, files)

        rows = connection.execute(statement, (sessionID,)).fetchall()
        records = {}

        for name, role, fileID, digest, size, linkDeleted, contentDeleted in rows:
            if not includeDeleted and (linkDeleted is not None or contentDeleted is not None):
                raise ValueError(f"Checkpoint contains a deleted file link or content: {name}")
            if name in records: raise ValueError(f"Duplicate checkpoint file link: {name}")
            records[name] = {"role": role, "file_id": fileID, "sha256": digest, "size_bytes": size}

        manifestRecord = records.get("manifest.json")
        if manifestRecord is None or manifestRecord["role"] != "manifest" or manifestRecord["sha256"] != manifestHash:
            raise ValueError("Checkpoint manifest link is missing or inconsistent.")

        manifestSize = manifestRecord["size_bytes"]
        if type(manifestSize) is not int or not 0 <= manifestSize <= maxManifestBytes:
            raise ValueError("Manifest size is invalid or exceeds the configured limit.")

        fileIDs = sorted({record["file_id"] for record in records.values()})

        statement = sql.SQL("""
            SELECT location.file_id, backend.backend_id, backend.url_prefix,
                   location.object_key
            FROM {} AS location
            JOIN {} AS backend ON backend.backend_id = location.backend_id
            WHERE location.file_id = ANY(%s::bigint[])
              AND (%s OR location.deleted_at IS NULL)
              AND location.status = 'present'
              AND location.verified_at IS NOT NULL
              AND backend.is_active
            ORDER BY location.file_id, location.priority,
                     backend.backend_id, location.object_key
        """).format(locations, backends)

        locationRows = connection.execute(statement, (fileIDs, includeDeleted)).fetchall()
        locationsByFile = {}

        for fileID, backendID, root, key in locationRows:
            if not isinstance(key, str) or key.startswith("/") or "\\" in key or "\x00" in key or any(part in {"", ".", ".."} for part in key.split("/")):
                raise ValueError("Database contains an invalid payload object key.")

            locationsByFile.setdefault(fileID, []).append({
                "backend_id": backendID,
                "url_prefix": root,
                "object_key": key,
            })

        manifestLocations = locationsByFile.get(manifestRecord["file_id"], [])
        if not manifestLocations: raise FileNotFoundError("Manifest has no eligible verified storage location.")

        access = pglDatabaseAccess(postgres, storageOptionsByBackend)
        matrices = {}
        session = None

        try:
            failures = []
            manifestContent = None

            for location in manifestLocations:
                backendID = location["backend_id"]

                try:
                    filesystem, root = access.resolve(backendID, location["url_prefix"])
                    path = posixpath.join(root, location["object_key"])

                    with filesystem.open(path, "rb") as source:
                        content = source.read(manifestSize + 1)

                    if len(content) != manifestSize: raise ValueError("Manifest size mismatch.")
                    if hashlib.sha256(content).hexdigest() != manifestHash:
                        raise ValueError("Manifest hash mismatch.")

                except (OSError, ValueError) as error:
                    failures.append(f"backend {backendID}: {type(error).__name__}")
                    continue

                manifestContent = content
                break

            if manifestContent is None:
                raise OSError("No manifest copy could be verified: " + "; ".join(failures))

            manifest = json.loads(manifestContent.decode("utf-8"))
            cls._validateSessionBundleManifest(manifest, origin=origin)

            if manifest["contract_version"] != contractVersion:
                raise ValueError("Manifest contract differs from the database checkpoint contract.")

            # V2 declares its modality explicitly. The contract name alone
            # no longer tells us whether this checkpoint contains MNE.
            hasMNE = "mne" in manifest
            hasMRI = "mri" in manifest

            if (hasMNE or hasMRI) and (cacheDirectory is None or not str(cacheDirectory).strip()):
                raise ValueError("MNE/MRI restoration requires an explicit cacheDirectory.")

            if cls.encodeRawManifest(manifest) != manifestContent:
                raise ValueError("Stored manifest is not canonically encoded.")

            expected = {
                record["name"]: (
                    record["sha256"],
                    record["size_bytes"],
                    "history" if record["name"] == "history.json" else payloadRole,
                )
                for record in manifest["files"]
            }
            expected["manifest.json"] = (manifestHash, len(manifestContent), "manifest")
            actual = {name: (record["sha256"], record["size_bytes"], record["role"]) for name, record in records.items()}

            if actual != expected:
                raise ValueError("Checkpoint file links do not exactly match the manifest identities and roles.")

            fileLocations = {}

            for record in manifest["files"]:
                name = record["name"]
                candidates = locationsByFile.get(records[name]["file_id"], [])
                if not candidates: raise FileNotFoundError(f"File has no eligible verified storage location: {name}")

                fileLocations[name] = {
                    "sha256": record["sha256"],
                    "size_bytes": record["size_bytes"],
                    "locations": candidates,
                }

            # Empty v1 expectations still reject unexpected product links.
            # Each returned matrix owns a separate deferred-access context.
            matrices = cls._loadSessionProducts(
                connection, postgres, sessionID,
                manifest.get("products", []),
                storageOptionsByBackend=storageOptionsByBackend,
            )

            # MNE retains its existing cache namespace. Generic derived files
            # use their own content-addressed cache under cacheDirectory.
            cacheContext = cls._mneCacheContext(postgres, sessionID) if hasMNE else None
            session = cls._reconstructSessionBundle(
                manifest,
                fileLocations,
                cacheDirectory=cacheDirectory,
                directLocalPolicy=directLocalPolicy,
                cacheContext=cacheContext,
                origin=origin,
                accessContext=access,
                ownsAccess=True,
            )
            cls._installSessionMatrices(session, matrices, manifest)
            return session

        except BaseException:
            for matrix in matrices.values():
                try:
                    matrix.close()
                except Exception:
                    pass

            if session is not None:
                try:
                    session.filesystem.close()
                except Exception:
                    pass

            # Idempotent if the reconstructed filesystem already closed it.
            access.close()
            raise

    ################################################################
    # Reconstruct history, modality contents, and correspondence
    ################################################################
    @classmethod
    def _reconstructSessionBundle(cls, manifest, fileLocations, storageOptionsByBackend=None, *, cacheDirectory=None, directLocalPolicy="materialize", cacheContext=None, origin="derived", accessContext=None, ownsAccess=False):
        """Restore a session from a verified checkpoint inventory.

        Supports existing behavioral/MNE contracts, raw MRI bundles, and
        pgl.derived.mri.v1.

        Matrix attachments are restored separately by the database loader.
        Derived files retain deferred checkpoint references.
        MRI acquisition payloads remain deferred.

        Correspondence is restored explicitly, without replaying actions.
        Its matched endpoints are validated after restoring the collections.
        This may read behavioral data.json files, but not tasks or MRI voxels.

        Ownership of accessContext transfers only after reconstruction succeeds.
        On failure, the caller retains ownership of its access context.

        Does not query SQL, publish files, or run scientific processing.
        """
        from copy import deepcopy

        from .pglMRI import pglMRI, pglMRIBundle
        from .pglSession import pglSession, pglMNE

        if directLocalPolicy not in ("materialize", "immutable"):
            raise ValueError("directLocalPolicy must be 'materialize' or 'immutable'.")
        if type(ownsAccess) is not bool:
            raise ValueError("ownsAccess must be Boolean.")
        if ownsAccess and accessContext is None:
            raise ValueError("ownsAccess requires an access context.")

        cls._validateSessionBundleManifest(manifest, origin=origin)
        hasMNE = "mne" in manifest
        hasMRI = "mri" in manifest

        if (hasMNE or hasMRI) and (cacheDirectory is None or not str(cacheDirectory).strip()):
            raise ValueError("MNE/MRI restoration requires an explicit cacheDirectory.")

        # Borrow access until every reconstruction step has succeeded.
        filesystem = pglCheckpointFilesystem(
            manifest,
            fileLocations,
            storageOptionsByBackend=storageOptionsByBackend,
            accessContext=accessContext,
            ownsAccess=False,
        )

        try:
            filesystem.mneCacheContext = deepcopy(cacheContext)
            history, metadata = cls._readSessionHistory(filesystem, len(manifest["runs"]))
            correspondence = getattr(history, "_checkpointScanRunCorrespondence", None)

            # Raw acquisition exports must not carry derived correspondence.
            if origin == "raw" and correspondence is not None:
                raise ValueError("Raw acquisition history must not contain derived scan/run correspondence.")

            # Verify inner descriptors against the hashed outer inventory.
            if hasMNE: cls._verifyMNEInventory(manifest, filesystem)
            if hasMRI: cls._verifyMRIInventory(manifest, filesystem)

            session = pglSession(
                filesystem=filesystem,
                runList=[record["path"] for record in manifest["runs"]],
            )
            session.uuid = history.uuid
            session.actionHistory = list(history.actionHistory)

            if not session.runs and metadata is not None:
                session.experimentName = metadata["labels"][0]["experimentName"]
                session.subjectID = metadata["labels"][0]["subjectID"]

            if hasMNE:
                session.mne = pglMNE.loadBundle(
                    manifest["mne"]["path"],
                    filesystem=filesystem,
                    cacheDirectory=cacheDirectory,
                    directLocalPolicy=directLocalPolicy,
                )

            if hasMRI:
                if origin == "derived":
                    mri = pglMRIBundle.loadDerived(
                        manifest["mri"]["path"],
                        filesystem=filesystem,
                        cacheDirectory=cacheDirectory,
                    )
                else:
                    mri = pglMRI.loadAcquisitionBundle(
                        manifest["mri"]["path"],
                        filesystem=filesystem,
                        cacheDirectory=cacheDirectory,
                    )

                if mri is None:
                    raise ValueError("MRI bundle restoration was refused.")
                session.mri = mri

            # Restore product payload references without materializing files.
            # Product records themselves remain in the restored action history.
            if origin == "derived":
                cls._restoreSessionDerivedFiles(
                    session,
                    manifest,
                    filesystem,
                    cacheDirectory=cacheDirectory,
                )

            if correspondence is not None:
                record = session._validateScanRunCorrespondence(correspondence)
                resolved = session._resolveScanRunCorrespondence(record)

                # Install only after all matched identities have resolved.
                session.scanRunCorrespondence = record
                #pglMessages.message(f"Restored {len(resolved)} scan/run matches by acquisition identity; no matching action was replayed.")

            # Older checkpoints leave correspondence unset.
            filesystem._ownsAccess = ownsAccess
            return session

        except BaseException:
            # Still borrowing access: do not close the caller's access context.
            filesystem.close()
            raise

    # -------------------------------------------------------------------------
    # Session loading: legacy raw behavioral archives
    # -------------------------------------------------------------------------
    # Locate and verify raw behavioral manifests and resolve their registered acquisition files.

    # ++++++++++++++++++++++++++++ loadRawManifest +++++++++++++++++++++++++++
    @classmethod
    def loadRawManifest(cls, connection, postgres, sessionID, storageOptionsByBackend=None, maxBytes=16 * 1024 * 1024, *, includeDeleted=False, accessContext=None):
        """Read and verify a completed raw behavioral checkpoint manifest.

        Called by raw session loading and raw-checkpoint duplicate detection.

        Uses the caller's SQL connection for catalog lookup.
        Payload roots resolve through caller-side database access.

        If accessContext is supplied, its caller owns it and its backend
        options. Otherwise this method creates and closes a temporary context.

        Returns the structurally validated manifest after checking byte count,
        SHA-256, contract, and canonical encoding.

        Does not modify records, reconstruct runs, or retain a SQL connection.
        includeDeleted permits inspection without changing lifecycle state.
        """
        if type(maxBytes) is not int or maxBytes <= 0:
            raise ValueError("maxBytes must be a positive integer.")

        if accessContext is not None and not isinstance(accessContext, pglDatabaseAccess):
            raise TypeError("accessContext must be a pglDatabaseAccess instance.")

        if accessContext is not None and storageOptionsByBackend:
            raise ValueError("Configure storage options on accessContext, not on both arguments.")

        located = cls.getRawManifestLocations(connection, postgres, sessionID, includeDeleted=includeDeleted)

        if located["size_bytes"] > maxBytes:
            raise ValueError("Manifest exceeds the configured size limit.")

        ownsAccess = accessContext is None
        access = pglDatabaseAccess(postgres, storageOptionsByBackend) if ownsAccess else accessContext
        failures = []

        try:
            for location in located["locations"]:
                backendID = location["backend_id"]
                key = location["object_key"]

                if not isinstance(key, str) or key.startswith("/") or "\\" in key or "\x00" in key or any(part in {"", ".", ".."} for part in key.split("/")):
                    raise ValueError("Database contains an invalid manifest object key.")

                try:
                    filesystem, root = access.resolve(backendID, location["url_prefix"])

                    with filesystem.open(posixpath.join(root, key), "rb") as source:
                        content = source.read(located["size_bytes"] + 1)

                    if len(content) != located["size_bytes"]:
                        raise ValueError("Manifest size mismatch.")

                    if hashlib.sha256(content).hexdigest() != located["sha256"]:
                        raise ValueError("Manifest hash mismatch.")

                except (OSError, ValueError) as error:
                    failures.append(f"backend {backendID}: {type(error).__name__}")
                    continue

                # Verified bytes identify the content. A decoding failure is
                # a malformed manifest, not a reason to try an identical copy.
                manifest = json.loads(content.decode("utf-8"))

                if not isinstance(manifest, dict):
                    raise ValueError("Manifest must contain a JSON object.")

                if manifest.get("contract_version") != "pgl.raw.behavior.v1":
                    raise ValueError("Unsupported manifest contract.")

                if cls.encodeRawManifest(manifest) != content:
                    raise ValueError("Stored manifest is not in the expected canonical encoding.")

                return cls.validateRawManifest(manifest)

            raise OSError(f"No manifest copy could be verified: {'; '.join(failures)}")

        finally:
            if ownsAccess:
                access.close()

    # ++++++++++++++++++++++++ getRawManifestLocations ++++++++++++++++++++++++
    # Direct callers in this module: getRawFileLocations, loadRawManifest.
    @staticmethod
    def getRawManifestLocations(connection, postgres, sessionID, *, includeDeleted=False):
        """
        Return the manifest identity and candidate locations for a completed checkpoint.
        Deleted sessions are hidden unless includeDeleted=True.
        The override permits inspection; it does not undelete the session.
        """
        if type(includeDeleted) is not bool:
            raise ValueError("includeDeleted must be a boolean.")
        
        sessionsTable = sql.Identifier(postgres.databaseSchema, "session")
        linksTable = sql.Identifier(postgres.databaseSchema, "session_files")
        filesTable = sql.Identifier(postgres.databaseSchema, "files")
        locationsTable = sql.Identifier(postgres.databaseSchema, "storage_locations")
        backendsTable = sql.Identifier(postgres.databaseSchema, "storage_backends")

        statement = sql.SQL("SELECT status, origin, contract_version, manifest_hash FROM {} WHERE session_id = %s AND (%s OR deleted_at IS NULL)").format(sessionsTable)
        checkpoint = connection.execute(statement, (sessionID, includeDeleted)).fetchone()

        if checkpoint is None:
            raise ValueError(f"Unknown or deleted checkpoint: {sessionID}")
        status, origin, contractVersion, manifestHash = checkpoint

        if status != "complete":
            raise ValueError("Only completed checkpoints can be loaded.")

        if origin != "raw" or contractVersion != "pgl.raw.behavior.v1":
            raise ValueError("Unsupported checkpoint contract.")

        statement = sql.SQL("""
            SELECT content.file_id, content.sha256, content.size_bytes, link.role
            FROM {} AS link
            JOIN {} AS content ON content.file_id = link.file_id
            WHERE link.session_id = %s AND link.name = 'manifest.json'
        """).format(linksTable, filesTable)
        manifest = connection.execute(statement, (sessionID,)).fetchone()

        if manifest is None or manifest[3] != "manifest" or manifest[1] != manifestHash:
            raise ValueError("Checkpoint manifest link is missing or inconsistent.")

        fileID, sha256, sizeBytes, role = manifest

        statement = sql.SQL("""
            SELECT backend.backend_id, backend.url_prefix, location.object_key
            FROM {} AS location
            JOIN {} AS backend ON backend.backend_id = location.backend_id
            WHERE location.file_id = %s
              AND location.status = 'present'
              AND location.verified_at IS NOT NULL
              AND backend.is_active
            ORDER BY location.priority ASC, backend.backend_id ASC
        """).format(locationsTable, backendsTable)
        rows = connection.execute(statement, (fileID,)).fetchall()

        if not rows:
            raise FileNotFoundError("Manifest has no verified location on an active backend.")

        return {
            "sha256": sha256,
            "size_bytes": sizeBytes,
            "locations": [
                {"backend_id": backendID, "url_prefix": root, "object_key": key}
                for backendID, root, key in rows
            ],
        }

    # ++++++++++++++++++++++++++ getRawFileLocations ++++++++++++++++++++++++++
    # Direct callers in this module: _saveRawSession, loadRawSession.
    @classmethod
    def getRawFileLocations(cls, connection, postgres, sessionID, manifest, *, includeDeleted=False):
        """
        Return acquisition-file identities and candidate storage locations.
        Deleted sessions are hidden unless includeDeleted=True.
        The override permits inspection; it does not undelete the session.
        """
        cls.validateRawManifest(manifest)

        manifestIdentity = cls.getRawManifestLocations(connection, postgres, sessionID, includeDeleted=includeDeleted)
        manifestBytes = cls.encodeRawManifest(manifest)

        if hashlib.sha256(manifestBytes).hexdigest() != manifestIdentity["sha256"] or len(manifestBytes) != manifestIdentity["size_bytes"]:
            raise ValueError("Supplied manifest does not match the checkpoint.")

        linksTable = sql.Identifier(postgres.databaseSchema, "session_files")
        filesTable = sql.Identifier(postgres.databaseSchema, "files")
        locationsTable = sql.Identifier(postgres.databaseSchema, "storage_locations")
        backendsTable = sql.Identifier(postgres.databaseSchema, "storage_backends")

        statement = sql.SQL("""
            SELECT link.name, content.sha256, content.size_bytes, link.role
            FROM {} AS link
            JOIN {} AS content ON content.file_id = link.file_id
            WHERE link.session_id = %s
        """).format(linksTable, filesTable)

        rows = connection.execute(statement, (sessionID,)).fetchall()
        actual = {name: (digest, size, role) for name, digest, size, role in rows}

        expected = {
            record["name"]: (record["sha256"], record["size_bytes"], "acquisition")
            for record in manifest["files"]
        }
        expected["manifest.json"] = (manifestIdentity["sha256"], manifestIdentity["size_bytes"], "manifest")

        if actual != expected:
            raise ValueError("Checkpoint file links do not exactly match the manifest.")

        result = {
            record["name"]: {
                "sha256": record["sha256"],
                "size_bytes": record["size_bytes"],
                "locations": [],
            }
            for record in manifest["files"]
        }

        statement = sql.SQL("""
            SELECT link.name, backend.backend_id, backend.url_prefix,
                   location.object_key
            FROM {} AS link
            JOIN {} AS location ON location.file_id = link.file_id
            JOIN {} AS backend ON backend.backend_id = location.backend_id
            WHERE link.session_id = %s
              AND link.role = 'acquisition'
              AND location.status = 'present'
              AND location.verified_at IS NOT NULL
              AND backend.is_active
            ORDER BY link.name, location.priority ASC, backend.backend_id ASC
        """).format(linksTable, locationsTable, backendsTable)

        for name, backendID, root, key in connection.execute(statement, (sessionID,)).fetchall():
            result[name]["locations"].append({
                "backend_id": backendID,
                "url_prefix": root,
                "object_key": key,
            })

        unavailable = [name for name, record in result.items() if not record["locations"]]

        if unavailable:
            raise FileNotFoundError(f"Files lack verified active locations: {', '.join(sorted(unavailable))}")

        return result

    # ++++++++++++++++++++++++++++ readRawSubjects ++++++++++++++++++++++++++++
    # Checkpoint implementation support. Existing external callers may use this method; see its
    # docstring and this section's purpose.
    @classmethod
    def readRawSubjects(cls, manifest, checkpointFilesystem):
        """Read each run's recorded subject ID through a verified checkpoint filesystem.

        Returns a mapping from logical run paths to subject IDs.
        Does not access session caches or write to the database.
        """
        cls.validateRawManifest(manifest)
        subjectsByRun = {}

        for record in manifest["runs"]:
            runPath = record["path"]
            settingsPath = posixpath.join(runPath, "experimentSettings.json")

            with checkpointFilesystem.open(settingsPath, "rt", encoding="utf-8") as file:
                settings = json.load(file)

            if not isinstance(settings, dict):
                raise ValueError(f"Experiment settings must contain a JSON object: {settingsPath}")

            subjectID = settings.get("subjectID")

            if not isinstance(subjectID, str) or not subjectID.strip() or "\x00" in subjectID:
                raise ValueError(f"Missing or invalid recorded subject ID: {settingsPath}")

            subjectsByRun[runPath] = subjectID

        return subjectsByRun


    # -------------------------------------------------------------------------
    # Raw session publication
    # -------------------------------------------------------------------------
    # saveRawSession() coordination, acquisition preflight, source inventory, staging, and raw
    # bundle export.

    # ++++++++++++++++++++++++++++ _saveRawSession ++++++++++++++++++++++++++
    @classmethod
    def _saveRawSession(cls, connection, postgres, session, createdBy, backendID, storageOptions=None, *, progress=None):
        """Publish or reuse a parentless raw checkpoint.

        The caller owns the outer SQL transaction and final commit.
        Payload writes are not transactional.

        Behavioral acquisition files are inventoried, staged, verified, and
        registered through one operation-owned payload access context.
        MNE-containing sessions delegate to _saveRawMNECheckpoint().

        progress is an optional save-level pglProgress instance.
        Existing integrity, duplicate-reuse, and deletion behavior is retained.
        """
        for label, value in (("createdBy", createdBy), ("backendID", backendID)):
            if type(value) is not int or not 0 <= value <= 9223372036854775807:
                raise ValueError(f"{label} must be a nonnegative PostgreSQL bigint.")

        if storageOptions is not None and not isinstance(storageOptions, dict):
            raise TypeError("storageOptions must be a dictionary or None.")

        # MRI publication streams original sources directly to destination
        # storage. Existing MNE and behavioral save paths remain unchanged.
        if getattr(session, "mri", None) is not None:
            return cls._saveRawMRICheckpoint(connection, postgres, session, createdBy, backendID, storageOptions=storageOptions, progress=progress)

        if session.mne is not None:
            return cls._saveRawMNECheckpoint(connection, postgres, session, createdBy, backendID, storageOptions=storageOptions, progress=progress)
        
        if progress is not None:
            progress(0.05, "Inventorying and hashing acquisition sources")

        manifest = cls.buildRawManifest(session, progress=progress.section(0.05, 0.09) if progress is not None else None)
        cls.validateRawManifest(manifest)
        manifestHash = cls.hashRawManifest(manifest)

        if progress is not None:
            progress(0.09, "Checking for an existing raw checkpoint")

        sessionsTable = sql.Identifier(postgres.databaseSchema, "session")
        backendsTable = sql.Identifier(postgres.databaseSchema, "storage_backends")
        usersTable = sql.Identifier(postgres.databaseSchema, "users")

        with connection.transaction(), pglDatabaseAccess(postgres, {backendID: storageOptions or {}}) as access:
            statement = sql.SQL("SELECT 1 FROM {} WHERE user_id = %s FOR SHARE").format(usersTable)

            if connection.execute(statement, (createdBy,)).fetchone() is None:
                raise ValueError(f"Unknown creator: {createdBy}")

            statement = sql.SQL("SELECT url_prefix, is_active FROM {} WHERE backend_id = %s FOR SHARE").format(backendsTable)
            backend = connection.execute(statement, (backendID,)).fetchone()

            if backend is None or not backend[1]:
                raise ValueError(f"Storage backend is missing or inactive: {backendID}")

            if progress is not None:
                progress(None, "Acquiring raw-checkpoint identity lock")

            postgres.acquireTransactionLock(connection, manifestHash, description="raw-checkpoint identity", timeoutSeconds=postgres.lockTimeoutSeconds)

            if progress is not None:
                progress(None, "Comparing checkpoint catalog")

            statement = sql.SQL("""
                SELECT session_id, status, contract_version
                FROM {}
                WHERE manifest_hash = %s
                  AND origin = 'raw'
                  AND deleted_at IS NULL
                FOR SHARE
            """).format(sessionsTable)
            existing = connection.execute(statement, (manifestHash,)).fetchone()

            if existing is not None:
                existingID, status, contractVersion = existing

                if (status, contractVersion) != ("complete", "pgl.raw.behavior.v1"):
                    raise ValueError("Matching manifest belongs to an incomplete or unsupported checkpoint.")

                if progress is not None:
                    progress(None, f"Verifying existing checkpoint {existingID}")

                archivedManifest = cls.loadRawManifest(connection, postgres, existingID, accessContext=access)

                if archivedManifest != manifest:
                    raise ValueError("Existing checkpoint manifest differs from source manifest.")

                # Preserve existing reuse semantics: this checks catalog
                # correspondence, not a new byte scan of every archived file.
                cls.getRawFileLocations(connection, postgres, existingID, archivedManifest)

                pglMessages.warning(f"This raw session is already saved as active checkpoint {existingID}. No new checkpoint was created; returning the existing ID. To save another raw copy, delete checkpoint {existingID} and call saveRawSession() again. To save further work as a derived checkpoint, use saveSession().", level=2)

                if progress is not None:
                    progress(0.97, f"Reusing existing checkpoint {existingID}")

                return existingID

            statement = sql.SQL("""
                SELECT session_id
                FROM {}
                WHERE manifest_hash = %s
                  AND origin = 'raw'
                  AND deleted_at IS NOT NULL
                ORDER BY session_id
                FOR SHARE
            """).format(sessionsTable)
            deletedMatches = connection.execute(statement, (manifestHash,)).fetchall()

            if deletedMatches:
                deletedIDs = ", ".join(str(row[0]) for row in deletedMatches)
                pglMessages.message(f"Found matching deleted raw checkpoint(s) {deletedIDs}; leaving them unchanged and saving a new checkpoint.")

            if progress is not None:
                progress(0.10, "Opening destination storage")

            filesystem, root = access.resolve(backendID, backend[0])
            sessionID = cls.createRawCheckpoint(connection, postgres, createdBy)

            staged = cls.stageRawSession(session, manifest, filesystem, root, sessionID=sessionID, connection=connection, postgres=postgres, backendID=backendID, progress=progress.section(0.10, 0.70) if progress is not None else None)

            if progress is not None:
                progress(0.70, "Writing and verifying checkpoint manifest")

            storedManifest = cls.stageRawManifest(manifest, filesystem, root, sessionID=sessionID)

            cls.registerStagedRawCheckpoint(connection, postgres, createdBy, backendID, manifest, staged, storedManifest, sessionID=sessionID, accessContext=access, progress=progress.section(0.71, 0.95) if progress is not None else None)

            if progress is not None:
                progress(0.96, "Validating checkpoint completion")

            cls.completeRawCheckpoint(connection, postgres, sessionID, manifest)

            if progress is not None:
                progress(0.97, "Closing payload access")

            return sessionID

    # +++++++++++++++++++++++++ _saveRawMNECheckpoint +++++++++++++++++++++++
    @classmethod
    def _saveRawMNECheckpoint(cls, connection, postgres, session, createdBy, backendID, storageOptions=None, *, progress=None):
        """Publish or reuse a parentless raw checkpoint containing MNE.

        Called by _saveRawSession() using the caller's connection and outer
        transaction.

        Exports current MNE and unchanged behavioral acquisition contents to
        temporary local staging, then copies, verifies, and registers files
        through one operation-owned payload access context.

        Identical active completed checkpoints may be reused.
        Matching deleted checkpoints remain deleted.

        Runtime timeout overrides are carried by postgres:
            lockTimeoutSeconds controls checkpoint-identity lock waiting.
            connectTimeoutSeconds and ioTimeoutSeconds are preserved by
            pglDatabaseAccess for PGL-owned inferred SSH payload access.

        Owns temporary staging and destination payload access.
        Working-session source readers remain caller-owned.

        Returns the new or reused checkpoint ID without changing the working
        session's identity, annotations, or history.

        Uses a nested transaction/savepoint. The outer transaction must commit.
        Payload writes are not transactional and failures may leave files.

        progress is an optional save-level pglProgress instance.
        Successful commit and 100% reporting belong to saveRawSession().
        """
        from tempfile import TemporaryDirectory

        from fsspec.implementations.local import LocalFileSystem

        from .pglSession import pglMNE

        for label, value in (("createdBy", createdBy), ("backendID", backendID)):
            if type(value) is not int or not 0 <= value <= 9223372036854775807:
                raise ValueError(f"{label} must be a nonnegative PostgreSQL bigint.")

        if storageOptions is not None and not isinstance(storageOptions, dict):
            raise TypeError("storageOptions must be a dictionary or None.")

        if type(session.mne) is not pglMNE:
            raise TypeError("MNE raw checkpoints require a pglMNE instance.")

        sessions = sql.Identifier(postgres.databaseSchema, "session")
        users = sql.Identifier(postgres.databaseSchema, "users")
        backends = sql.Identifier(postgres.databaseSchema, "storage_backends")

        def isLocal(filesystem):
            """Determine locality from the resolved filesystem."""
            protocols = filesystem.protocol
            protocols = {protocols} if isinstance(protocols, str) else set(protocols)
            return bool(protocols.intersection({"file", "local"}))

        with connection.transaction(), pglDatabaseAccess(postgres, {backendID: storageOptions or {}}) as access:
            statement = sql.SQL("SELECT 1 FROM {} WHERE user_id = %s FOR SHARE").format(users)

            if connection.execute(statement, (createdBy,)).fetchone() is None:
                raise ValueError(f"Unknown creator: {createdBy}")

            statement = sql.SQL("SELECT url_prefix, is_active FROM {} WHERE backend_id = %s FOR SHARE").format(backends)
            backend = connection.execute(statement, (backendID,)).fetchone()

            if backend is None or not backend[1]:
                raise ValueError("Storage backend is missing or inactive.")

            if progress is not None:
                progress(0.05, "Opening destination storage")

            destinationFS, destinationRoot = access.resolve(backendID, backend[0])
            stagingFS = LocalFileSystem(skip_instance_cache=True)

            with TemporaryDirectory(prefix="pgl-raw-session-") as temporary:
                if progress is not None:
                    progress(0.06, "Exporting current MNE and behavioral contents to temporary staging")

                stagingRoot, manifest = cls.saveRawSessionFiles(session, Path(temporary) / "bundle", filesystem=stagingFS, progress=progress.section(0.06, 0.09) if progress is not None else None)
                manifestBytes = cls.encodeRawManifest(manifest)
                manifestHash = hashlib.sha256(manifestBytes).hexdigest()

                if progress is not None:
                    progress(0.09, "Acquiring raw-checkpoint identity lock")

                postgres.acquireTransactionLock(connection, manifestHash, description="raw-checkpoint identity", timeoutSeconds=postgres.lockTimeoutSeconds)

                if progress is not None:
                    progress(None, "Checking for an existing raw checkpoint")

                statement = sql.SQL("""
                    SELECT session_id, status, contract_version
                    FROM {}
                    WHERE origin = 'raw'
                      AND manifest_hash = %s
                      AND deleted_at IS NULL
                    FOR SHARE
                """).format(sessions)
                existing = connection.execute(statement, (manifestHash,)).fetchone()

                if existing is not None:
                    existingID, status, contract = existing

                    if (status, contract) != ("complete", "pgl.raw.session.v1"):
                        raise ValueError("Matching raw manifest belongs to an unsupported or incomplete checkpoint.")

                    # This private inspection creates its own payload contexts.
                    # Close them before returning; no loaded session escapes.
                    inspected = None

                    try:
                        if progress is not None:
                            progress(None, f"Verifying existing checkpoint {existingID}")

                        inspected = cls.loadRawSessionBundle(connection, postgres, existingID, storageOptionsByBackend={backendID: storageOptions or {}}, cacheDirectory=Path(temporary) / "unused-cache")

                    finally:
                        if inspected is not None:
                            try:
                                for matrix in inspected.dataMatrices.values():
                                    try:
                                        matrix.close()
                                    except Exception as error:
                                        pglMessages.warning(f"Could not close a duplicate-inspection matrix ({type(error).__name__}).", level=1)
                            finally:
                                inspected.filesystem.close()

                    pglMessages.warning(f"This raw session is already saved as active checkpoint {existingID}. No new checkpoint was created; returning the existing ID. To save another raw copy, delete checkpoint {existingID} and call saveRawSession() again. To save further work as a derived checkpoint, use saveSession().", level=2)

                    if progress is not None:
                        progress(0.97, f"Reusing existing checkpoint {existingID}")

                    return existingID

                statement = sql.SQL("""
                    SELECT session_id
                    FROM {}
                    WHERE origin = 'raw'
                      AND manifest_hash = %s
                      AND deleted_at IS NOT NULL
                    ORDER BY session_id
                    FOR SHARE
                """).format(sessions)
                deletedMatches = connection.execute(statement, (manifestHash,)).fetchall()

                if deletedMatches:
                    deletedIDs = ", ".join(str(row[0]) for row in deletedMatches)
                    pglMessages.message(f"Found matching deleted raw checkpoint(s) {deletedIDs}; leaving them unchanged and saving a new checkpoint.")

                modalities = (["behavior"] if manifest["runs"] else []) + ["mne"]

                if progress is not None:
                    progress(None, "Allocating raw MNE checkpoint")

                statement = sql.SQL("""
                    INSERT INTO {} (
                        origin, kind, ingest_method, modalities, status,
                        contract_version, created_by, started_at
                    )
                    VALUES (
                        'raw', 'acquired', 'manual', %s::text[], 'in_progress',
                        'pgl.raw.session.v1', %s, now()
                    )
                    RETURNING session_id
                """).format(sessions)
                sessionID = connection.execute(statement, (modalities, createdBy)).fetchone()[0]

                objectPrefix = f"session{sessionID:06d}"
                destination = posixpath.join(destinationRoot, objectPrefix)

                # Preserve source/destination overlap checks. An SSH-backed
                # server path must not be resolved on the client computer.
                for run in session.runs or []:
                    if run.filesystem is None:
                        raise ValueError("Source run has no filesystem.")

                    if isLocal(destinationFS) and isLocal(run.filesystem):
                        target = Path(destination).expanduser().resolve()
                        source = Path(run.fullDataPath).expanduser().resolve()

                        if target == source or source in target.parents:
                            raise ValueError("Checkpoint destination must be outside source run directories.")

                    elif destinationFS == run.filesystem:
                        target = posixpath.normpath(destination)
                        source = posixpath.normpath(run.fullDataPath)

                        if target == source or target.startswith(source.rstrip("/") + "/"):
                            raise ValueError("Checkpoint destination must be outside source run directories.")

                if progress is not None:
                    progress(0.10, "Creating checkpoint directories")

                if destinationFS.exists(destination):
                    raise FileExistsError(destination)

                destinationFS.makedirs(destination, exist_ok=False)

                for directory in manifest["directories"]:
                    if progress is not None:
                        progress(None, f"Creating checkpoint directory {directory}")

                    destinationFS.makedirs(posixpath.join(destination, directory), exist_ok=True)

                records = [
                    *manifest["files"],
                    {"name": "manifest.json", "sha256": manifestHash, "size_bytes": len(manifestBytes)},
                ]
                payloadProgress = progress.section(0.10, 0.70) if progress is not None else None

                for record, fileProgress in pglProgress.fileSections(records, payloadProgress):
                    pglStorage.copyVerifiedFile(stagingFS, posixpath.join(stagingRoot, record["name"]), destinationFS, destinationRoot, record, objectKey=posixpath.join(objectPrefix, record["name"]), progress=fileProgress)

                cls._registerSessionBundleFiles(connection, postgres, sessionID, backendID, manifest, objectPrefix=objectPrefix, origin="raw", accessContext=access, progress=progress.section(0.70, 0.95) if progress is not None else None)

                if progress is not None:
                    progress(0.96, "Validating checkpoint completion")

                cls._completeSessionBundleCheckpoint(connection, postgres, sessionID, manifest, origin="raw")

                if progress is not None:
                    progress(0.97, "Cleaning up temporary staging and payload access")

                return sessionID
    
    # +++++++++++++++++++++++++ _checkRawSessionLabels ++++++++++++++++++++++++
    # Direct callers in this module: saveRawSession.
    @classmethod
    def _checkRawSessionLabels(cls, session, *, allowMissingMetadata=False):
        """Check working-session safety and required raw acquisition labels.

        Called by the public raw saver before configuration, SQL, or export.
        allowMissingMetadata bypasses missing labels only, never failed-action
        safety or malformed/unreadable acquisition settings.
        """
        if type(allowMissingMetadata) is not bool:
            raise ValueError("allowMissingMetadata must be a boolean.")

        pglStorage.requireSafeSave(session)

        labels = session.getSessionLabels(acquisition=True)
        missing = []

        for record in labels:
            fields = [name for name in ("experimentName", "subjectID") if record[name] is None]

            if fields:
                owner = "session" if record["runIndex"] is None else f"run {record['runIndex']}"
                missing.append(f"{owner}: {', '.join(fields)}")

        if not missing:
            return True

        if session.runs:
            instructions = "Set experimentName and subjectID in the affected runs' saved acquisition experimentSettings.json. In-memory edits alone are not archived by saveRawSession()."
        else:
            instructions = "Set session.experimentName and session.subjectID before saving."

        if allowMissingMetadata:
            pglMessages.warning("Saving raw session with missing metadata because allowMissingMetadata=True: " + "; ".join(missing) + ". Unset values will display as Unknown.", level=0)
            return True

        pglMessages.warning("Raw session was not saved. Missing metadata: " + "; ".join(missing) + ". " + instructions + " To intentionally save without these labels, use saveRawSession(allowMissingMetadata=True).", level=0)
        return False

    # ++++++++++++++++++++++++++++ buildRawManifest +++++++++++++++++++++++++++
    # Direct callers in this module: _saveRawSession, saveRawSessionFiles, stageRawSession.
    @classmethod
    def buildRawManifest(cls, session, *, progress=None):
        """Inventory and hash unchanged behavioral acquisition files.

        Optional progress reports run/file names and bytes read.
        Does not copy payloads or publish database records.

        Source hashing does not issue extra stat requests solely to estimate
        progress. The returned manifest contains actual hashed byte counts.
        """
        if not session.runs:
            raise ValueError("A raw checkpoint must contain at least one run.")

        if session.mne is not None:
            raise NotImplementedError("This pilot archives behavioral run directories only; attached MNE data is not yet supported.")

        runs = []
        directories = []
        files = []
        runCount = len(session.runs)

        for index, run in enumerate(session.runs):
            runName = f"runs/{index:06d}"

            if progress is not None:
                progress(index / runCount, f"Inspecting acquisition run {index + 1}/{runCount}")

            inventory = cls.validateRawRun(run)
            runs.append({"index": index, "path": runName})
            directories.append(runName)
            directories.extend(posixpath.join(runName, directory) for directory in inventory["directories"])

            fileCount = len(inventory["files"])

            for fileIndex, relativePath in enumerate(inventory["files"]):
                sourcePath = posixpath.join(run.fullDataPath, relativePath)
                name = posixpath.join(runName, relativePath)
                fileProgress = None

                if progress is not None:
                    start = (index + fileIndex / max(fileCount, 1)) / runCount
                    end = (index + (fileIndex + 1) / max(fileCount, 1)) / runCount
                    fileProgress = progress.section(start, end, label=name)

                identity = pglStorage.hashFile(run.filesystem, sourcePath, progress=fileProgress, description="Hashing acquisition source")
                files.append({"name": name, **identity})

        if progress is not None:
            progress(1, "Acquisition inventory ready")

        return {
            "contract_version": "pgl.raw.behavior.v1",
            "runs": runs,
            "directories": sorted(["runs", *directories]),
            "files": sorted(files, key=lambda record: record["name"]),
        }

    # +++++++++++++++++++++++++++++ validateRawRun ++++++++++++++++++++++++++++
    # Direct callers in this module: buildRawManifest.
    @classmethod
    def validateRawRun(cls, run):
        """Validate required acquisition files and return the run inventory."""
        from .pglExperiment import pglTaskBase

        inventory = cls.inventoryRawRun(run)
        files = set(inventory["files"])
        directories = set(inventory["directories"])

        requiredFiles = {"experimentSettings.json", "settings.json", "state.json", "data.json", "pgl.json"}
        missing = requiredFiles - files

        if missing:
            raise ValueError(f"Run is missing required files: {', '.join(sorted(missing))}")

        settingsPath = posixpath.join(run.fullDataPath, "experimentSettings.json")
        with run.filesystem.open(settingsPath, "rt", encoding="utf-8") as file:
            settings = json.load(file)

        if not isinstance(settings, dict):
            raise ValueError("experimentSettings.json must contain a JSON object.")

        taskNames = settings.get("tasks")
        if not isinstance(taskNames, list) or any(not isinstance(name, str) or not name.strip() for name in taskNames):
            raise ValueError("experimentSettings.json must contain a list of nonempty task names.")

        for index, name in enumerate(taskNames):
            if "/" in name or "\\" in name or "\x00" in name:
                raise ValueError(f"Task name must not contain path separators or NUL: {name!r}")

            taskDirectory = pglTaskBase.getTaskDirectoryName(taskID=index, taskName=name)
            requiredTaskFiles = {posixpath.join(taskDirectory, filename) for filename in ("settings.json", "state.json", "data.json")}
            missing = requiredTaskFiles - files

            if missing:
                raise ValueError(f"Run is missing required task files: {', '.join(sorted(missing))}")

            parametersDirectory = posixpath.join(taskDirectory, "parameters")
            if parametersDirectory not in directories:
                raise ValueError(f"Run is missing parameters directory: {parametersDirectory}")

        return inventory

    # ++++++++++++++++++++++++++++ inventoryRawRun ++++++++++++++++++++++++++++
    # Direct callers in this module: validateRawRun.
    @staticmethod
    def inventoryRawRun(run):
        """List source files and directories without loading or changing their contents.

        Paths in the returned inventory are relative to the run directory.
        This is a structural inventory, not yet a verified checkpoint.
        """
        filesystem = run.filesystem
        root = run.fullDataPath

        if filesystem is None:
            raise ValueError("Run has no resolved filesystem.")

        if not filesystem.isdir(root):
            raise NotADirectoryError(f"Run directory does not exist: {root}")

        directories = set()
        files = set()

        # ++++++++++++++++++++++++++++++ relativePath +++++++++++++++++++++++++++++
        # Local implementation within inventoryRawRun.
        def relativePath(path):
            relative = posixpath.relpath(path, root)
            parts = relative.split("/")

            if relative.startswith("/") or "\\" in relative or any(part in {"", ".", ".."} for part in parts):
                raise ValueError(f"Invalid relative path in run inventory: {relative!r}")

            return relative

        for directory, directoryNames, fileNames in filesystem.walk(root, detail=False, on_error="raise"):
            for name in directoryNames:
                directories.add(relativePath(posixpath.join(directory, name)))

            for name in fileNames:
                files.add(relativePath(posixpath.join(directory, name)))

        return {"directories": sorted(directories), "files": sorted(files)}

    # ++++++++++++++++++++++++++++ stageRawSession ++++++++++++++++++++++++++++
    # Direct callers in this module: _saveRawSession.
    @classmethod
    def stageRawSession(cls, session, manifest, destinationFilesystem, destinationRoot, *, sessionID, connection, postgres, backendID, progress=None):
        """Store each distinct behavioral payload once on the backend.

        Reuse registered copies only after verifying their bytes.
        Repeated content within this save reuses the same verified payload.

        Local destinations retain readable hard-link aliases where supported.
        Other destinations retain canonical payload locations.

        Optional progress covers source revalidation, locks, comparisons,
        copying, read-back verification, and local alias creation.

        Requires the caller's transaction. Never deliberately overwrites
        payloads. Failed saves may leave unregistered files.
        """
        import errno
        import os
        import stat

        if isinstance(sessionID, bool) or not isinstance(sessionID, int) or sessionID < 0:
            raise ValueError("sessionID must be a nonnegative integer.")

        cls.validateRawManifest(manifest)

        if progress is not None:
            progress(0, "Rechecking acquisition sources")

        if cls.buildRawManifest(session, progress=progress.section(0, 0.10) if progress is not None else None) != manifest:
            raise ValueError("Source session no longer matches the supplied manifest.")

        def isLocal(filesystem):
            protocols = filesystem.protocol
            protocols = {protocols} if isinstance(protocols, str) else set(protocols)
            return bool(protocols.intersection({"file", "local"}))

        localDestination = isLocal(destinationFilesystem)
        sessionKey = f"session{sessionID:06d}"
        sessionRoot = posixpath.join(destinationRoot, sessionKey)

        # Reject overlap before creating destination paths.
        for run in session.runs:
            if localDestination and isLocal(run.filesystem):
                destination = Path(sessionRoot).expanduser().resolve()
                source = Path(run.fullDataPath).expanduser().resolve()

                if destination == source or source in destination.parents:
                    raise ValueError("Checkpoint destination must be outside source run directories.")

            elif destinationFilesystem == run.filesystem:
                destination = posixpath.normpath(sessionRoot)
                source = posixpath.normpath(run.fullDataPath)

                if destination == source or destination.startswith(source.rstrip("/") + "/"):
                    raise ValueError("Checkpoint destination must be outside source run directories.")

        # Preserve stable ordering and lock identity. These transaction locks
        # remain held until the outer transaction ends.
        for digest in sorted({record["sha256"] for record in manifest["files"]}):
            lockName = f"pgl.payload:{postgres.databaseSchema}:{backendID}:{digest}"

            if progress is not None:
                progress(None, f"Acquiring payload lock {digest[:12]}")

            postgres.acquireTransactionLock(connection, lockName, description=f"payload {digest[:12]}", timeoutSeconds=postgres.lockTimeoutSeconds)

        if progress is not None:
            progress(0.10, "Creating checkpoint directories")

        if destinationFilesystem.exists(sessionRoot):
            raise FileExistsError(f"Checkpoint destination already exists; it will not be overwritten: {sessionRoot}")

        destinationFilesystem.makedirs(destinationRoot, exist_ok=True)
        destinationFilesystem.makedirs(sessionRoot, exist_ok=False)
        runsByPath = {record["path"]: record for record in manifest["runs"]}

        def physicalKey(logicalName):
            parts = logicalName.split("/", 2)
            runRecord = runsByPath["/".join(parts[:2])]
            runKey = posixpath.join(sessionKey, f"run{runRecord['index']:05d}")
            return posixpath.join(runKey, parts[2]) if len(parts) == 3 else runKey

        # Empty physical directories are a local browsing convenience.
        # The manifest preserves logical directories on every backend.
        if localDestination:
            for directory in manifest["directories"]:
                if directory != "runs":
                    destinationFilesystem.makedirs(posixpath.join(destinationRoot, physicalKey(directory)), exist_ok=True)

        filesTable = sql.Identifier(postgres.databaseSchema, "files")
        locationsTable = sql.Identifier(postgres.databaseSchema, "storage_locations")
        verifiedByHash = {}
        staged = []

        unsupportedLinkErrors = {
            errno.EXDEV,
            errno.EPERM,
            errno.EACCES,
            errno.EMLINK,
            errno.ENOSYS,
            getattr(errno, "ENOTSUP", errno.EINVAL),
            getattr(errno, "EOPNOTSUPP", errno.EINVAL),
        }

        def readableLocation(canonical, targetKey):
            """Create a verified local hard-link alias when supported."""
            if not localDestination or canonical["object_key"] == targetKey:
                return canonical

            sourcePath = posixpath.join(destinationRoot, canonical["object_key"])
            targetPath = posixpath.join(destinationRoot, targetKey)
            destinationFilesystem.makedirs(posixpath.dirname(targetPath), exist_ok=True)
            sourceStat = os.lstat(sourcePath)

            if not stat.S_ISREG(sourceStat.st_mode):
                pglMessages.oneTimeWarning("A canonical payload is not a regular local file. Reusing its registered location without creating a hard link.", level=0)
                return canonical

            try:
                os.link(sourcePath, targetPath, follow_symlinks=False)
            except FileExistsError:
                raise
            except OSError as error:
                if error.errno not in unsupportedLinkErrors:
                    raise

                pglMessages.oneTimeWarning("Hard links are unavailable for this storage location. Reusing verified payload locations without creating duplicate copies.", level=0)
                return canonical

            targetStat = os.lstat(targetPath)

            if not stat.S_ISREG(targetStat.st_mode) or targetStat.st_dev != sourceStat.st_dev or targetStat.st_ino != sourceStat.st_ino:
                raise OSError(f"Hard-link identity check failed: {targetKey}")

            return {
                "object_key": targetKey,
                "sha256": canonical["sha256"],
                "size_bytes": canonical["size_bytes"],
            }

        payloadProgress = progress.section(0.10, 1) if progress is not None else None

        for record, fileProgress in pglProgress.fileSections(manifest["files"], payloadProgress):
            digest = record["sha256"]
            canonical = verifiedByHash.get(digest)

            if canonical is not None and canonical["size_bytes"] != record["size_bytes"]:
                raise ValueError("Manifest contains conflicting sizes for the same SHA-256.")

            if canonical is None:
                if fileProgress is not None:
                    fileProgress(0, "Looking for a reusable stored copy")

                statement = sql.SQL("""
                    SELECT location.object_key, content.size_bytes
                    FROM {} AS content
                    JOIN {} AS location ON location.file_id = content.file_id
                    WHERE content.sha256 = %s
                      AND location.backend_id = %s
                      AND location.status = 'present'
                      AND location.verified_at IS NOT NULL
                    ORDER BY location.priority, location.object_key
                """).format(filesTable, locationsTable)

                candidates = connection.execute(statement, (digest, backendID)).fetchall()
                failures = []

                for candidateIndex, (key, registeredSize) in enumerate(candidates):
                    if registeredSize != record["size_bytes"]:
                        raise ValueError("Registered content size conflicts with the manifest.")

                    if not isinstance(key, str) or key.startswith("/") or "\\" in key or "\x00" in key or any(part in {"", ".", ".."} for part in key.split("/")):
                        raise ValueError("Database contains an invalid payload object key.")

                    try:
                        description = f"Comparing registered copy {candidateIndex + 1}/{len(candidates)}"
                        actual = pglStorage.hashFile(destinationFilesystem, posixpath.join(destinationRoot, key), progress=fileProgress, expectedSize=record["size_bytes"], description=description)

                        if actual != {"sha256": digest, "size_bytes": record["size_bytes"]}:
                            raise ValueError("Registered payload integrity check failed.")

                    except (OSError, ValueError) as error:
                        failures.append(type(error).__name__)
                        continue

                    canonical = {"object_key": key, **actual}
                    break

                if candidates and canonical is None:
                    raise OSError(f"No registered copy could be verified for SHA-256 {digest}: {', '.join(failures)}")

                if canonical is None:
                    parts = record["name"].split("/", 2)
                    runRecord = runsByPath["/".join(parts[:2])]
                    run = session.runs[runRecord["index"]]
                    sourcePath = posixpath.join(run.fullDataPath, parts[2])
                    canonical = pglStorage.copyVerifiedFile(run.filesystem, sourcePath, destinationFilesystem, destinationRoot, record, objectKey=physicalKey(record["name"]), progress=fileProgress)

                verifiedByHash[digest] = canonical

            elif fileProgress is not None:
                fileProgress(1, "Reusing verified content from this save")

            if fileProgress is not None:
                fileProgress(None, "Finalizing verified payload location")

            stored = readableLocation(canonical, physicalKey(record["name"]))
            staged.append({"name": record["name"], **stored})

        return staged
    # ++++++++++++++++++++++++++++ stageRawManifest +++++++++++++++++++++++++++
    # Direct callers in this module: _saveRawSession.
    @classmethod
    def stageRawManifest(cls, manifest, destinationFilesystem, destinationRoot, *, sessionID):
        """Write and verify sessionNNNNNN/manifest.json without overwriting."""
        if isinstance(sessionID, bool) or not isinstance(sessionID, int) or sessionID < 0:
            raise ValueError("sessionID must be a nonnegative integer.")

        cls.validateRawManifest(manifest)
        manifestBytes = cls.encodeRawManifest(manifest)
        expectedHash = hashlib.sha256(manifestBytes).hexdigest()
        expectedSize = len(manifestBytes)

        objectKey = f"session{sessionID:06d}/manifest.json"
        destinationPath = posixpath.join(destinationRoot, objectKey)

        with destinationFilesystem.open(destinationPath, "xb") as file:
            file.write(manifestBytes)

        stored = pglStorage.hashFile(destinationFilesystem, destinationPath)

        if stored["sha256"] != expectedHash or stored["size_bytes"] != expectedSize:
            raise ValueError(f"Stored manifest verification failed: {objectKey}")

        return {"object_key": objectKey, **stored}

    # ++++++++++++++++++++++++++ saveRawSessionFiles ++++++++++++++++++++++++++
    # Direct callers in this module: _saveRawMNECheckpoint.
    @classmethod
    def saveRawSessionFiles(cls, session, dataPath, filesystem=None, *, progress=None):
        """Export MNE and optional unchanged behavioral acquisition files.

        Includes acquisition labels in hashed history.json.
        Does not register or publish a database checkpoint.

        Optional progress reports export phases and individual files.
        MNE serialization reports a phase rather than fabricated byte progress.

        Partial files may remain on failure. The raw database coordinator uses
        temporary local staging and owns its cleanup.
        """
        from .pglSession import pglSession, pglMNE

        if type(session.mne) is not pglMNE:
            raise TypeError("Raw session bundle export requires a pglMNE instance.")

        if dataPath is None or not str(dataPath).strip():
            raise ValueError("A destination is required.")

        if filesystem is None:
            filesystem, destination = url_to_fs(str(dataPath))
        else:
            destination = str(dataPath)

        if filesystem.exists(destination):
            raise FileExistsError(destination)

        def reportExport(description):
            if progress is not None:
                progress(None, description)

        # Expose byte counts during temporary work without letting each file
        # consume the entire export progress allocation.
        def exportFileProgress(name):
            if progress is None:
                return None

            def reportFile(fraction, description):
                progress(None, f"{name}: {description}")

            return reportFile

        behavior = pglSession()
        behavior.runs = list(session.runs or [])
        behavior.mne = None

        reportExport("Preparing behavioral acquisition inventory")
        behaviorManifest = cls.buildRawManifest(behavior, progress=progress.section(0, 0.15) if progress is not None else None) if behavior.runs else None

        reportExport("Encoding raw session history")
        historyBytes = cls._sessionHistoryBytes(session, acquisition=True)

        filesystem.makedirs(destination, exist_ok=False)
        directories = set()
        files = []
        runs = []

        if behaviorManifest is not None:
            directories.update(behaviorManifest["directories"])
            runs = deepcopy(behaviorManifest["runs"])

            reportExport("Creating temporary behavioral directories")

            for directory in sorted(directories):
                filesystem.makedirs(posixpath.join(destination, directory), exist_ok=True)

            behaviorProgress = progress.section(0.15, 0.35) if progress is not None else None

            for record, fileProgress in pglProgress.fileSections(behaviorManifest["files"], behaviorProgress):
                parts = record["name"].split("/", 2)
                run = behavior.runs[int(parts[1])]
                sourcePath = posixpath.join(run.fullDataPath, parts[2])
                pglStorage.copyVerifiedFile(run.filesystem, sourcePath, filesystem, destination, record, objectKey=record["name"], progress=fileProgress)
                files.append(dict(record))

            reportExport("Rechecking behavioral acquisition sources")

            if cls.buildRawManifest(behavior, progress=progress.section(0.35, 0.45) if progress is not None else None) != behaviorManifest:
                raise ValueError("Behavioral acquisition changed during raw export.")

        mneRoot = posixpath.join(destination, "mne")

        if progress is not None:
            progress(0.45, "Serializing current MNE contents")

        session.mne.saveBundle(mneRoot, filesystem=filesystem)
        directories.add("mne")

        if progress is not None:
            progress(0.65, "Inventorying and hashing staged MNE files")

        for current, directoryNames, fileNames in filesystem.walk(mneRoot, detail=False, on_error="raise"):
            relative = posixpath.relpath(current, destination)

            for name in directoryNames:
                directories.add(posixpath.join(relative, name))

            for name in fileNames:
                path = posixpath.join(current, name)
                logicalName = posixpath.join(relative, name)
                identity = pglStorage.hashFile(filesystem, path, progress=exportFileProgress(logicalName), description="Hashing staged MNE file")
                files.append({"name": logicalName, **identity})

        if progress is not None:
            progress(0.80, "Writing and verifying raw history")

        historyPath = posixpath.join(destination, "history.json")

        with filesystem.open(historyPath, "xb") as target:
            if target.write(historyBytes) != len(historyBytes):
                raise OSError("Incomplete raw session history write.")

        historyIdentity = {"sha256": hashlib.sha256(historyBytes).hexdigest(), "size_bytes": len(historyBytes)}
        storedHistory = pglStorage.hashFile(filesystem, historyPath, progress=exportFileProgress("history.json"), expectedSize=len(historyBytes), description="Verifying staged history")

        if storedHistory != historyIdentity:
            raise ValueError("Raw session history verification failed.")

        files.append({"name": "history.json", **historyIdentity})
        manifest = {
            "contract_version": "pgl.raw.session.v1",
            "runs": runs,
            "mne": {"path": "mne"},
            "directories": sorted(directories),
            "files": sorted(files, key=lambda record: record["name"]),
        }
        cls.validateRawSessionManifest(manifest)

        class DestinationView:
            def open(self, path, mode="rb", **kwargs): return filesystem.open(posixpath.join(destination, path), mode=mode, **kwargs)

        view = DestinationView()

        if progress is not None:
            progress(0.90, "Validating exported MNE inventory and acquisition labels")

        cls._verifyMNEInventory(manifest, view)
        _, metadata = cls._readSessionHistory(view, len(runs))

        if runs and metadata != cls._behaviorLabelMetadata(manifest, view):
            raise ValueError("Raw history labels differ from the archived behavioral settings.")

        if progress is not None:
            progress(0.95, "Writing and verifying staged manifest")

        content = cls.encodeRawManifest(manifest)
        manifestPath = posixpath.join(destination, "manifest.json")

        with filesystem.open(manifestPath, "xb") as target:
            if target.write(content) != len(content):
                raise OSError("Incomplete raw session manifest write.")

        expected = {"sha256": hashlib.sha256(content).hexdigest(), "size_bytes": len(content)}
        actual = pglStorage.hashFile(filesystem, manifestPath, progress=exportFileProgress("manifest.json"), expectedSize=len(content), description="Verifying staged manifest")

        if actual != expected:
            raise ValueError("Raw session manifest verification failed.")

        if progress is not None:
            progress(1, "Temporary raw bundle ready")

        return destination, manifest


    # -------------------------------------------------------------------------
    # Derived session publication
    # -------------------------------------------------------------------------
    # saveSession() coordination and checkpoint-specific temporary bundle export.

    # ++++++++++++++++++++++++++ _saveDerivedSession ++++++++++++++++++++++++
    @classmethod
    def _saveDerivedSession(cls, connection, postgres, session, createdBy, backendID, *, parentSessionID, checkpointName=None, description=None, ingestMethod="manual", storageOptions=None, progress=None):
        """Publish a derived checkpoint using staged bytes and existing content.

        Requires the caller's explicit READ COMMITTED transaction and early
        checkpoint publication lock. Public saveSession() owns that protocol.

        Stages:
            Current metadata/history.
            Materialized mutable contents requiring serialization.
            New/local scientific files.

        Reuses:
            Eligible untouched checkpoint-backed payloads.
            Existing file IDs and storage locations, without payload reads.

        Keeps complete manifest/file links for the new checkpoint.
        Does not update working identity, annotations, or history baseline.

        MNE and working matrices retain their existing full-export behavior.
        Matching parent reuse remains available when no matrices are attached.

        Payload writes are not transactional. Failed saves may leave
        unregistered files or matrix bundles.
        """
        from tempfile import TemporaryDirectory

        from fsspec.implementations.local import LocalFileSystem
        from psycopg.pq import TransactionStatus

        for label, value in (("createdBy", createdBy), ("backendID", backendID), ("parentSessionID", parentSessionID)):
            if type(value) is not int or not 0 <= value <= 9223372036854775807:
                raise ValueError(f"{label} must be a nonnegative PostgreSQL bigint.")

        for label, value in (("checkpointName", checkpointName), ("description", description)):
            if value is not None and (not isinstance(value, str) or "\x00" in value):
                raise ValueError(f"{label} must be a string without NUL, or None.")

        if not isinstance(ingestMethod, str) or ingestMethod not in {"manual", "automated"}:
            raise ValueError("ingestMethod must be manual or automated.")
        if storageOptions is not None and not isinstance(storageOptions, dict):
            raise TypeError("storageOptions must be a dictionary or None.")
        if connection.info.transaction_status != TransactionStatus.INTRANS:
            raise ValueError("Derived publication requires an active outer transaction.")

        # Reentrant for the public coordinator, which acquired this before
        # writes. Advanced callers must follow that same early-lock protocol.
        cls._acquireCheckpointPublicationLock(connection, postgres, progress=progress)

        pglStorage.requireSafeSave(session)
        products = cls._snapshotSessionMatrices(session)
        runs = list(session.runs or [])
        mneData = session.mne
        mriData = session.mri
        derivedSnapshot = deepcopy(session.derivedFiles)
        correspondenceSnapshot = deepcopy(session.scanRunCorrespondence)
        historySnapshot = cls._sessionHistoryBytes(session, acquisition=False)

        scans = list(mriData.scans) if mriData is not None else []
        scanSnapshots = [
            {
                "uuid": scan.uuid,
                "name": scan.name,
                "sourceMetadata": scan._copyMetadata(scan.sourceMetadata),
                "metadata": scan._copyMetadata(scan.metadata),
                "backing": scan._backing,
                "backingFilesystem": None if scan._backing is None else scan._backing.fs,
                "backingPath": None if scan._backing is None else scan._backing.path,
                "expectedIdentity": None if scan._backing is None else scan._backing.expectedIdentity,
                "localPath": scan.localPath,
            }
            for scan in scans
        ]

        def report(fraction, description):
            if progress is not None: progress(fraction, description)

        def requireUnchanged():
            """Preserve the existing publication-time structural checks."""
            pglStorage.requireSafeSave(session)
            cls._requireSessionMatricesUnchanged(session, products)

            currentRuns = list(session.runs or [])
            if len(currentRuns) != len(runs) or any(left is not right for left, right in zip(currentRuns, runs)):
                raise ValueError("Behavioral run collection changed while saving.")
            if session.mne is not mneData or session.mri is not mriData:
                raise ValueError("Session modality collections changed while saving.")
            if session.derivedFiles != derivedSnapshot:
                raise ValueError("Derived attachments changed while saving.")
            if session.scanRunCorrespondence != correspondenceSnapshot:
                raise ValueError("Scan/run correspondence changed while saving.")

            if mriData is not None:
                currentScans = list(mriData.scans)
                if len(currentScans) != len(scans) or any(left is not right for left, right in zip(currentScans, scans)):
                    raise ValueError("MRI scan collection changed while saving.")

                for scan, snapshot in zip(scans, scanSnapshots):
                    if (
                        scan.uuid != snapshot["uuid"]
                        or scan.name != snapshot["name"]
                        or scan.sourceMetadata != snapshot["sourceMetadata"]
                        or scan.metadata != snapshot["metadata"]
                        or scan._backing is not snapshot["backing"]
                        or scan.localPath != snapshot["localPath"]
                    ):
                        raise ValueError("MRI metadata or source binding changed while saving.")

                    backing = scan._backing
                    if backing is not None and (
                        backing.fs is not snapshot["backingFilesystem"]
                        or backing.path != snapshot["backingPath"]
                        or backing.expectedIdentity != snapshot["expectedIdentity"]
                    ):
                        raise ValueError("MRI acquisition backing changed while saving.")

            if cls._sessionHistoryBytes(session, acquisition=False) != historySnapshot:
                raise ValueError("Session history or labels changed while saving.")

        def isLocal(filesystem):
            protocols = filesystem.protocol
            protocols = {protocols} if isinstance(protocols, str) else set(protocols)
            return bool(protocols.intersection({"file", "local"}))

        sessions = sql.Identifier(postgres.databaseSchema, "session")
        users = sql.Identifier(postgres.databaseSchema, "users")
        backends = sql.Identifier(postgres.databaseSchema, "storage_backends")
        links = sql.Identifier(postgres.databaseSchema, "session_files")
        files = sql.Identifier(postgres.databaseSchema, "files")
        locations = sql.Identifier(postgres.databaseSchema, "storage_locations")

        with connection.transaction(), pglDatabaseAccess(postgres, {backendID: storageOptions or {}}) as access:
            report(0, "Validating checkpoint owner, destination, and parent")

            statement = sql.SQL("SELECT 1 FROM {} WHERE user_id = %s FOR SHARE").format(users)
            if connection.execute(statement, (createdBy,)).fetchone() is None:
                raise ValueError("Unknown checkpoint creator.")

            statement = sql.SQL("SELECT url_prefix, is_active FROM {} WHERE backend_id = %s FOR SHARE").format(backends)
            backend = connection.execute(statement, (backendID,)).fetchone()
            if backend is None or not backend[1]:
                raise ValueError("Destination backend is missing or inactive.")

            statement = sql.SQL("""
                SELECT origin, status, contract_version, manifest_hash,
                       description, ingest_method, created_by, modalities,
                       deleted_at, checkpoint_name
                FROM {}
                WHERE session_id = %s
                FOR SHARE
            """).format(sessions)
            parent = connection.execute(statement, (parentSessionID,)).fetchone()

            if parent is None or parent[1] != "complete" or parent[8] is not None:
                raise ValueError("Parent must be a completed active checkpoint.")

            report(0.02, "Opening destination storage")
            destinationFS, destinationRoot = access.resolve(backendID, backend[0])
            stagingFS = LocalFileSystem(skip_instance_cache=True)

            # Matrix publication retains its existing separate Zarr path.
            matrixEnd = 0.25 if products else 0.04
            productRecords = cls._publishSessionMatrices(
                connection,
                postgres,
                session,
                products,
                createdBy=createdBy,
                backendID=backendID,
                filesystem=destinationFS,
                destinationRoot=destinationRoot,
                progress=progress.section(0.03, matrixEnd) if progress is not None else None,
            )

            with TemporaryDirectory(prefix="pgl-derived-session-") as temporary:
                report(matrixEnd, "Staging current contents and reusable references")

                staged = cls._stageDerivedSessionCheckpoint(
                    session,
                    stagingFS,
                    str(Path(temporary) / "bundle"),
                    productRecords=productRecords,
                    progress=progress.section(matrixEnd, 0.55) if progress is not None else None,
                )

                stagingRoot = staged["destination"]
                manifest = staged["manifest"]
                references = staged["reusedFiles"]
                requireUnchanged()

                if manifest["products"] != productRecords:
                    raise ValueError("Staged matrix references differ from published revisions.")

                if [record["name"] for record in manifest.get("derivedFiles", [])] != sorted(derivedSnapshot):
                    raise ValueError("Staged attachment names differ from the working collection.")

                fileIdentities = {record["name"]: record for record in manifest["files"]}

                for record in manifest.get("derivedFiles", []):
                    attachment = derivedSnapshot[record["name"]]
                    for field in ("runIndex", "filename", "mediaType"):
                        if record[field] != attachment[field]:
                            raise ValueError("Staged attachment metadata differs from its working record.")

                    identity = fileIdentities[record["path"]]
                    if any(identity[field] != attachment[field] for field in ("sha256", "size_bytes")):
                        raise ValueError("Staged attachment identity differs from its working record.")

                report(0.55, "Resolving reused file identities in the database")
                reusedFiles = cls._resolveCheckpointFileReuse(connection, postgres, references)

                manifestBytes = cls.encodeRawManifest(manifest)
                manifestHash = hashlib.sha256(manifestBytes).hexdigest()
                contractVersion = manifest["contract_version"]
                modalities = (["behavior"] if manifest["runs"] else []) + (["mne"] if "mne" in manifest else []) + (["mri"] if "mri" in manifest else [])

                ################################################################
                # Preserve existing identical-parent reuse
                ################################################################
                sameParent = parent[0] == "derived" and parent[2] == contractVersion and parent[3] == manifestHash
                sameMetadata = (
                    parent[4] == description
                    and parent[5] == ingestMethod
                    and parent[6] == createdBy
                    and sorted(parent[7]) == sorted(modalities)
                    and parent[9] == checkpointName
                )

                if not products and sameParent and sameMetadata:
                    cls._verifySessionProducts(connection, postgres, parentSessionID, [])

                    expected = {
                        record["name"]: (
                            record["sha256"],
                            record["size_bytes"],
                            "history" if record["name"] == "history.json" else "derived",
                        )
                        for record in manifest["files"]
                    }
                    expected["manifest.json"] = (manifestHash, len(manifestBytes), "manifest")

                    statement = sql.SQL("""
                        SELECT link.name, content.sha256, content.size_bytes,
                               link.role,
                               (
                                   link.deleted_at IS NULL
                                   AND content.deleted_at IS NULL
                                   AND EXISTS (
                                       SELECT 1
                                       FROM {locations} AS location
                                       JOIN {backends} AS backend
                                         ON backend.backend_id = location.backend_id
                                       WHERE location.file_id = content.file_id
                                         AND location.deleted_at IS NULL
                                         AND location.status = 'present'
                                         AND location.verified_at IS NOT NULL
                                         AND backend.is_active
                                   )
                               ) AS available
                        FROM {links} AS link
                        JOIN {files} AS content ON content.file_id = link.file_id
                        WHERE link.session_id = %s
                        ORDER BY link.name
                    """).format(locations=locations, backends=backends, links=links, files=files)

                    rows = connection.execute(statement, (parentSessionID,)).fetchall()
                    actual = {name: (digest, size, role) for name, digest, size, role, available in rows}

                    if actual != expected:
                        raise ValueError("Matching parent has inconsistent file links.")

                    if all(available for _, _, _, _, available in rows):
                        requireUnchanged()
                        pglMessages.warning(
                            f"Session contents and metadata match checkpoint {parentSessionID}. "
                            "No new checkpoint was created; returning the existing ID.",
                            level=2,
                        )
                        report(1, f"Reusing checkpoint {parentSessionID}; cleaning up staging")
                        return parentSessionID

                ################################################################
                # Allocate and upload only physical staging files
                ################################################################
                report(0.58, "Allocating derived checkpoint")
                sessionID = cls.createDerivedCheckpoint(
                    connection,
                    postgres,
                    createdBy,
                    parentSessionID,
                    checkpointName=checkpointName,
                    description=description,
                    ingestMethod=ingestMethod,
                    contractVersion=contractVersion,
                    modalities=modalities,
                )

                objectPrefix = f"session{sessionID:06d}"
                destination = posixpath.join(destinationRoot, objectPrefix)

                # Retain source/destination overlap protection.
                for run in runs:
                    if run.filesystem is None:
                        raise ValueError("Source run has no filesystem.")

                    if isLocal(destinationFS) and isLocal(run.filesystem):
                        target = Path(destination).expanduser().resolve()
                        source = Path(run.fullDataPath).expanduser().resolve()
                        if target == source or source in target.parents:
                            raise ValueError("Checkpoint destination must be outside source run directories.")

                    elif destinationFS == run.filesystem:
                        target = posixpath.normpath(destination)
                        source = posixpath.normpath(run.fullDataPath)
                        if target == source or target.startswith(source.rstrip("/") + "/"):
                            raise ValueError("Checkpoint destination must be outside source run directories.")

                if destinationFS.exists(destination):
                    raise FileExistsError(destination)

                destinationFS.makedirs(destination, exist_ok=False)

                # Preserve the directory layout, including empty directories.
                # Reused scientific files themselves need no new physical path.
                for directory in manifest["directories"]:
                    destinationFS.makedirs(posixpath.join(destination, directory), exist_ok=True)

                physicalRecords = [
                    record for record in manifest["files"]
                    if record["name"] not in reusedFiles
                ]
                physicalRecords.append({
                    "name": "manifest.json",
                    "sha256": manifestHash,
                    "size_bytes": len(manifestBytes),
                })

                report(
                    0.60,
                    f"Uploading {len(physicalRecords)} files; "
                    f"reusing {len(reusedFiles)} existing payload references",
                )
                transferProgress = progress.section(0.60, 0.82) if progress is not None else None

                for record, fileProgress in pglProgress.fileSections(physicalRecords, transferProgress):
                    pglStorage.copyVerifiedFile(
                        stagingFS,
                        posixpath.join(stagingRoot, record["name"]),
                        destinationFS,
                        destinationRoot,
                        record,
                        objectKey=posixpath.join(objectPrefix, record["name"]),
                        progress=fileProgress,
                    )

                ################################################################
                # Register complete logical contents and finish publication
                ################################################################
                cls._registerMixedDerivedSessionFiles(
                    connection,
                    postgres,
                    sessionID,
                    backendID,
                    manifest,
                    objectPrefix=objectPrefix,
                    reusedFiles=reusedFiles,
                    accessContext=access,
                    progress=progress.section(0.82, 0.95) if progress is not None else None,
                )

                report(0.96, "Registering checkpoint matrix links")
                cls._registerSessionProducts(connection, postgres, sessionID, productRecords)

                requireUnchanged()
                for matrix in products.values(): pglStorage.requireSafeSave(matrix)

                report(0.98, "Validating complete checkpoint inventory")
                cls.completeDerivedCheckpoint(connection, postgres, sessionID, manifest)

                report(1, "Closing temporary staging and publication payload access")
                return sessionID

    ################################################################
    # Restore unopened derived-file references
    ################################################################
    @classmethod
    def _restoreSessionDerivedFiles(cls, session, manifest, filesystem, *,
                                    root="", cacheDirectory=None):
        """Restore attachment metadata without reading payload bytes.

        root is empty for a checkpoint filesystem exposing logical paths.
        Ordinary filesystems supply the exported checkpoint directory.

        Filesystem handles live in runtime-only backing records, separate
        from attachment metadata. The caller owns filesystem lifetime.
        """
        import posixpath
        from copy import deepcopy

        cls.validateDerivedManifest(manifest)
        if session.derivedFiles:
            raise ValueError("Refusing to replace existing derived-file attachments.")

        identities = {record["name"]: record for record in manifest["files"]}
        attachments = {}
        backings = {}

        for record in manifest.get("derivedFiles", []):
            runIndex = record["runIndex"]
            if runIndex is not None and runIndex >= len(session.runs or []):
                raise ValueError("Derived-file run association does not match the session.")

            identity = identities[record["path"]]
            attachment = {
                "version": 1,
                "runIndex": runIndex,
                "filename": record["filename"],
                "mediaType": record["mediaType"],
                "sha256": identity["sha256"],
                "size_bytes": identity["size_bytes"],
            }
            name = record["name"]
            attachments[name] = attachment
            backings[name] = {
                "attachment": deepcopy(attachment),
                "filesystem": filesystem,
                "path": posixpath.join(root, record["path"]) if root else record["path"],
                "cacheDirectory": cacheDirectory,
            }

        # Install only after all records have been validated.
        # Runtime backings are ordinary attributes, not serialized traits.
        session.derivedFiles = attachments
        session._derivedFileBackings = backings

    ################################################################
    # Retrieve a verified local copy of a derived file
    ################################################################
    @classmethod
    def getSessionDerivedFile(cls, session, name, *, cacheDirectory=None):
        """Return a verified local Path, or None for an unknown attachment.

        Local action outputs are verified in place.
        Restored checkpoint attachments are materialized on demand.

        No SQL query or generation occurs. Successful cache files remain
        available for external viewers. Missing/corrupt files raise.

        The cache must be trusted and caller-owned. Concurrent modification
        of attachments or payload files is unsupported.
        """
        import hashlib
        import json
        import os
        import re
        import shutil
        import tempfile
        from pathlib import Path

        if not isinstance(name, str): raise TypeError("Derived file name must be a string.")
        if name not in session.derivedFiles: return None

        attachment = session.derivedFiles[name]
        if not isinstance(attachment, dict) or attachment.get("version") != 1:
            raise ValueError(f"Invalid derived-file attachment: {name!r}")

        expected = {key: attachment[key] for key in ("sha256", "size_bytes")}
        if not isinstance(expected["sha256"], str) or re.fullmatch(r"[0-9a-f]{64}", expected["sha256"]) is None:
            raise ValueError("Invalid derived-file SHA-256.")
        if type(expected["size_bytes"]) is not int or not 0 <= expected["size_bytes"] <= 9223372036854775807:
            raise ValueError("Invalid derived-file size.")

        def verify(path):
            if session._derivedFileIdentity(path) != expected:
                raise ValueError(f"Derived file integrity mismatch: {name!r}")
            return path

        # Locally generated attachments retain their original source path.
        # They do not need a database backing or another cached copy.
        if "localPath" in attachment:
            localPath = attachment["localPath"]
            if not isinstance(localPath, str) or not localPath:
                raise ValueError("Invalid derived-file local path.")
            return verify(Path(localPath))

        backing = getattr(session, "_derivedFileBackings", {}).get(name)
        if backing is None or backing["attachment"] != attachment:
            raise ValueError(f"Derived file {name!r} has no matching checkpoint backing.")

        filename = attachment["filename"]
        if (
            not isinstance(filename, str)
            or not filename.strip()
            or filename in (".", "..")
            or any(character in filename for character in ("/", "\\", "\x00", "\n", "\r"))
        ):
            raise ValueError("Invalid derived filename.")

        cacheValue = backing["cacheDirectory"] if cacheDirectory is None else cacheDirectory
        if cacheValue is None:
            raise ValueError("A local cacheDirectory is required to retrieve this derived file.")

        cacheText = os.fspath(cacheValue)
        if (
            not isinstance(cacheText, str)
            or not cacheText.strip()
            or "://" in cacheText
            or "::" in cacheText
            or any(character in cacheText for character in ("\x00", "\n", "\r"))
        ):
            raise ValueError("cacheDirectory must be an ordinary local filesystem path.")

        cacheRoot = Path(cacheText).expanduser().resolve() / "derivedFiles"

        # Identity-addressed cache directories allow safe reuse across sessions.
        # Include filename so media players retain the expected extension.
        identityBytes = json.dumps(
            {**expected, "filename": filename},
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
        cacheKey = hashlib.sha256(identityBytes).hexdigest()
        destination = cacheRoot / cacheKey
        localFile = destination / filename

        def verifyDestination():
            if destination.is_symlink() or not destination.is_dir():
                raise ValueError(f"Invalid derived-file cache directory: {destination}")
            return verify(localFile)

        if os.path.lexists(destination): return verifyDestination()

        cacheRoot.mkdir(parents=True, exist_ok=True)
        staging = Path(tempfile.mkdtemp(prefix=".building-", dir=str(cacheRoot)))

        try:
            stagedFile = staging / filename
            digest = hashlib.sha256()
            size = 0

            # Stream from retained checkpoint access, not an open SQL connection.
            with backing["filesystem"].open(backing["path"], "rb") as source, stagedFile.open("xb") as target:
                while True:
                    block = source.read(1024 * 1024)
                    if not block: break
                    size += len(block)
                    if size > expected["size_bytes"]:
                        raise ValueError(f"Derived payload exceeds its recorded size: {name!r}")
                    digest.update(block)
                    if target.write(block) != len(block):
                        raise OSError("Incomplete derived-file cache write.")

                target.flush()
                os.fsync(target.fileno())

            if {"sha256": digest.hexdigest(), "size_bytes": size} != expected:
                raise ValueError(f"Derived file integrity mismatch: {name!r}")
            verify(stagedFile)

            # Publish only complete, verified files. A cooperating concurrent
            # retrieval may already have published the same nonempty directory.
            try:
                staging.rename(destination)
            except OSError:
                if not os.path.lexists(destination): raise
                verifyDestination()

            return verifyDestination()

        finally:
            if staging.exists(): shutil.rmtree(staging)

    ################################################################
    # Export session-owned derived files into checkpoint staging
    ################################################################
    @classmethod
    def _saveSessionDerivedFiles(cls, session, filesystem, destination, *, progress=None):
        """Export registered local attachments and return manifest components.

        destination must be an existing staging directory.
        Its derived/ directory must not already exist.

        Uses session.getDerivedFile() to verify each source, then streams and
        verifies its exported bytes. Local paths are not written to metadata.

        This first implementation supports the existing local attachments.
        Deferred checkpoint references will be supported by the retrieval
        layer in a subsequent step.

        Does not publish database records, write manifest.json, or modify
        session attachments. Failed exports may leave partial staging files;
        the enclosing save operation owns staging cleanup.

        The caller owns the progress display and reports final completion.
        """
        import posixpath
        from copy import deepcopy

        from .pglProgress import pglProgress
        from .pglStorage import pglStorage

        if not isinstance(session.derivedFiles, dict):
            raise TypeError("session.derivedFiles must be a dictionary.")
        if not filesystem.isdir(destination):
            raise ValueError("Derived-file export requires an existing staging directory.")

        # Existing local attachment records contain metadata only.
        # Snapshot them before validation or filesystem writes.
        attachments = deepcopy(session.derivedFiles)

        if not attachments:
            if progress is not None: progress(1, "No derived files")
            return {"derivedFiles": [], "directories": [], "files": []}

        root = posixpath.join(destination, "derived")
        if filesystem.exists(root): raise FileExistsError(root)

        if progress is not None: progress(0, "Validating derived files")

        records = []
        directories = ["derived"]
        sources = {}

        # Validate every source before creating the attachment directory.
        for name in attachments:
            if not isinstance(name, str) or not name.strip():
                raise ValueError("Derived-file names must be nonblank strings.")
            if any(character in name for character in ("\x00", "\n", "\r")):
                raise ValueError("Invalid derived-file name.")

        for index, name in enumerate(sorted(attachments)):
            attachment = attachments[name]
            if not isinstance(attachment, dict) or attachment.get("version") != 1:
                raise ValueError(f"Invalid derived-file attachment: {name!r}")

            filename = attachment.get("filename")
            mediaType = attachment.get("mediaType")
            runIndex = attachment.get("runIndex")

            if (
                not isinstance(filename, str)
                or not filename.strip()
                or filename in (".", "..")
                or any(character in filename for character in ("/", "\\", "\x00", "\n", "\r"))
            ):
                raise ValueError("Derived filename must be a single safe filename.")

            if not isinstance(mediaType, str) or not mediaType.strip():
                raise ValueError("Derived mediaType must be a nonblank string.")
            if any(character in mediaType for character in ("\x00", "\n", "\r")):
                raise ValueError("Invalid derived mediaType.")

            if runIndex is not None:
                if type(runIndex) is not int or not 0 <= runIndex < len(session.runs or []):
                    raise ValueError("Invalid derived-file runIndex.")

            # Existing session accessor checks source bytes against the
            # identity recorded when the action registered the attachment.
            source = session.getDerivedFile(name)
            if source is None: raise ValueError(f"Derived attachment disappeared: {name!r}")
            sources[name] = source

            relativeRoot = f"derived/f{index:06d}"
            relativePath = f"{relativeRoot}/{filename}"
            directories.append(relativeRoot)
            records.append({
                "name": name,
                "runIndex": runIndex,
                "filename": filename,
                "mediaType": mediaType,
                "path": relativePath,
            })

        if session.derivedFiles != attachments:
            raise ValueError("Derived-file attachments changed during validation.")

        filesystem.makedirs(root, exist_ok=False)

        # Weight export progress by file size rather than attachment count.
        workRecords = [
            {
                "name": record["name"],
                "size_bytes": attachments[record["name"]]["size_bytes"],
                "descriptor": record,
            }
            for record in records
        ]
        exportProgress = None if progress is None else progress.section(0.1, 1)
        files = []

        for work, fileProgress in pglProgress.fileSections(workRecords, exportProgress):
            record = work["descriptor"]
            name = record["name"]
            attachment = attachments[name]
            expected = {key: attachment[key] for key in ("sha256", "size_bytes")}
            targetPath = posixpath.join(destination, record["path"])
            filesystem.makedirs(posixpath.dirname(targetPath), exist_ok=False)

            # Stream the file; do not load an entire MP4 into RAM.
            copied = 0
            with sources[name].open("rb") as source, filesystem.open(targetPath, "xb") as target:
                while True:
                    block = source.read(1024 * 1024)
                    if not block: break
                    copied += len(block)
                    if copied > expected["size_bytes"]:
                        raise ValueError(f"Derived source grew during export: {name!r}")
                    if target.write(block) != len(block):
                        raise OSError(f"Incomplete derived-file export: {name!r}")
                    if fileProgress is not None:
                        fileProgress(0.5 * copied / max(1, expected["size_bytes"]), "Copying derived file")

            if copied != expected["size_bytes"]:
                raise ValueError(f"Derived source size changed during export: {name!r}")

            verifyProgress = None if fileProgress is None else fileProgress.section(0.5, 1)
            actual = pglStorage.hashFile(
                filesystem,
                targetPath,
                progress=verifyProgress,
                expectedSize=expected["size_bytes"],
                description="Verifying derived file",
            )
            if actual != expected:
                raise ValueError(f"Exported derived-file integrity mismatch: {name!r}")

            files.append({"name": record["path"], **expected})

        # Concurrent edits are unsupported. Detect metadata replacements
        # rather than silently publishing a mixed attachment snapshot.
        if session.derivedFiles != attachments:
            raise ValueError("Derived-file attachments changed during export.")

        return {
            "derivedFiles": records,
            "directories": sorted(directories),
            "files": sorted(files, key=lambda record: record["name"]),
        }

    ################################################################
    # Export current session contents into a derived checkpoint directory
    ################################################################
    @classmethod
    def saveDerivedSessionFiles(cls, session, dataPath, filesystem=None, filesystemPrefix=None, *, productRecords=None):
        """Export current contents, history, correspondence, and attachments.

        Supports:
            Existing behavioral/MNE derived contracts.
            pgl.derived.mri.v1 for MRI with optional behavior.

        MRI payloads remain original acquisition sources. Current annotations
        are preserved separately. Processed images are derived attachments,
        linked to acquisition UUIDs through their registered products.

        productRecords:
            None is permitted only without attached matrices.
            Otherwise supply exact named matrix revision references from the
            publication coordinator. Matrix arrays are published separately.

        Does not register SQL rows or modify working scientific contents.
        Writes manifest.json last. Failed exports may leave partial output.
        Concurrent mutation is unsupported; detectable changes are rejected.
        """
        import json
        import posixpath
        import hashlib
        from copy import deepcopy

        from .pglMRI import pglMRI, pglMRIBundle
        from .pglSession import pglMNE
        from .pglStorage import pglStorage

        pglStorage.requireSafeSave(session)

        runs = list(session.runs or [])
        mneData = session.mne
        mriData = session.mri
        hasMRI = mriData is not None
        products = cls._snapshotSessionMatrices(session)
        derivedSnapshot = deepcopy(session.derivedFiles)
        correspondenceSnapshot = deepcopy(session.scanRunCorrespondence)

        if mneData is not None and hasMRI:
            raise ValueError("Combined MRI/MNE derived checkpoints are not supported.")
        if mneData is not None and type(mneData) is not pglMNE:
            raise TypeError("MNE export currently supports pglMNE, not subclasses.")
        if hasMRI and (type(mriData) is not pglMRI or not mriData.scans):
            raise ValueError("MRI export requires a nonempty pglMRI collection.")
        if not runs and mneData is None and not hasMRI:
            raise ValueError("A checkpoint must contain behavioral, MRI, or MNE contents.")

        if productRecords is None:
            if products:
                raise ValueError("The save coordinator must publish attached matrices and supply productRecords.")
            validatedProducts = None
        else:
            validatedProducts = cls._validateMatrixRecordsForSession(session, productRecords)
            if {record["name"] for record in validatedProducts} != set(products):
                raise ValueError("Manifest products must exactly match session and MRI matrix attachments.")

        if not isinstance(derivedSnapshot, dict):
            raise TypeError("session.derivedFiles must be a dictionary.")

        # Capture MRI collection and portable annotations for end-of-export
        # checks. Original-header discovery occurs on exported copies only.
        scans = list(mriData.scans) if hasMRI else []
        scanSnapshots = [
            {
                "uuid": scan.uuid,
                "name": scan.name,
                "sourceMetadata": scan._copyMetadata(scan.sourceMetadata),
                "metadata": scan._copyMetadata(scan.metadata),
            }
            for scan in scans
        ]

        def requireUnchanged():
            currentRuns = list(session.runs or [])
            if len(currentRuns) != len(runs) or any(left is not right for left, right in zip(currentRuns, runs)):
                raise ValueError("Behavioral run collection changed during export.")
            if session.mne is not mneData or session.mri is not mriData:
                raise ValueError("Session modality contents changed during export.")
            if session.derivedFiles != derivedSnapshot:
                raise ValueError("Derived-file attachments changed during export.")
            if session.scanRunCorrespondence != correspondenceSnapshot:
                raise ValueError("Scan/run correspondence changed during export.")

            cls._requireSessionMatricesUnchanged(session, products)

            if hasMRI:
                currentScans = list(mriData.scans)
                if len(currentScans) != len(scans) or any(left is not right for left, right in zip(currentScans, scans)):
                    raise ValueError("MRI scan collection changed during export.")

                for scan, snapshot in zip(scans, scanSnapshots):
                    if (
                        scan.uuid != snapshot["uuid"]
                        or scan.name != snapshot["name"]
                        or scan.sourceMetadata != snapshot["sourceMetadata"]
                        or scan.metadata != snapshot["metadata"]
                    ):
                        raise ValueError("MRI scan metadata changed during export.")

        # History encoding validates correspondence against current identities
        # and saved behavioral UUIDs before any output directory is created.
        historyBytes = cls._sessionHistoryBytes(session, acquisition=False)

        if dataPath is None or not str(dataPath).strip():
            raise ValueError("A destination path is required.")

        filesystem, destination, _ = pglStorage.validateFilesystem(
            filesystem=filesystem,
            dataPath=dataPath,
            filesystemPrefix=filesystemPrefix,
            requireExists=False,
        )
        if filesystem is None: raise ValueError("Could not resolve destination filesystem.")
        if filesystem.exists(destination): raise FileExistsError(f"Destination already exists: {destination}")

        requireUnchanged()
        filesystem.makedirs(destination, exist_ok=False)
        directories, files, runRecords = set(), [], []

        def inventoryDirectory(relativeRoot):
            """Hash exported files without loading scientific arrays."""
            fullRoot = posixpath.join(destination, relativeRoot)
            directories.add(relativeRoot)

            for currentPath, directoryNames, fileNames in filesystem.walk(fullRoot, detail=False, on_error="raise"):
                logicalPath = posixpath.relpath(currentPath, destination)
                for name in directoryNames: directories.add(posixpath.join(logicalPath, name))

                for name in fileNames:
                    savedPath = posixpath.join(currentPath, name)
                    files.append({
                        "name": posixpath.join(logicalPath, name),
                        **pglStorage.hashFile(filesystem, savedPath),
                    })

        ################################################################
        # Export current behavioral contents
        ################################################################
        if runs:
            filesystem.makedirs(posixpath.join(destination, "runs"), exist_ok=False)
            directories.add("runs")

        for index, run in enumerate(runs):
            runName = f"runs/{index:06d}"
            pglMessages.message(f"Exporting current behavioral run {index + 1}/{len(runs)}.")
            run.saveDerivedRun(dataPath=posixpath.join(destination, runName), filesystem=filesystem)
            runRecords.append({"index": index, "path": runName})
            inventoryDirectory(runName)

        ################################################################
        # Export modality contents
        ################################################################
        if mneData is not None:
            mneData.saveBundle(posixpath.join(destination, "mne"), filesystem=filesystem)
            inventoryDirectory("mne")

        if hasMRI:
            pglMRIBundle.saveDerived(mriData, posixpath.join(destination, "mri"), filesystem=filesystem)
            inventoryDirectory("mri")

        ################################################################
        # Export attached artifacts, including corrected MRI images
        ################################################################
        requireUnchanged()
        derivedParts = cls._saveSessionDerivedFiles(session, filesystem, destination)
        directories.update(derivedParts["directories"])
        files.extend(derivedParts["files"])

        historyPath = posixpath.join(destination, "history.json")
        with filesystem.open(historyPath, "xb") as target:
            if target.write(historyBytes) != len(historyBytes):
                raise OSError("Incomplete session history write.")

        expectedHistory = {
            "sha256": hashlib.sha256(historyBytes).hexdigest(),
            "size_bytes": len(historyBytes),
        }
        if pglStorage.hashFile(filesystem, historyPath) != expectedHistory:
            raise ValueError("Saved session history verification failed.")
        files.append({"name": "history.json", **expectedHistory})

        ################################################################
        # Select the checkpoint contract without changing legacy layouts
        ################################################################
        if hasMRI:
            contractVersion = "pgl.derived.mri.v2"
            if validatedProducts is None: validatedProducts = []
        else:
            contractVersion = "pgl.derived.session.v1" if mneData is not None else "pgl.derived.behavior.v1"

            if validatedProducts is not None:
                contractVersion = "pgl.derived.session.v2" if mneData is not None else "pgl.derived.behavior.v2"

            if derivedParts["derivedFiles"]:
                contractVersion = "pgl.derived.session.v3" if mneData is not None else "pgl.derived.behavior.v3"
                if validatedProducts is None: validatedProducts = []

        manifest = {
            "contract_version": contractVersion,
            "runs": runRecords,
            "directories": sorted(directories),
            "files": sorted(files, key=lambda record: record["name"]),
        }
        if mneData is not None: manifest["mne"] = {"path": "mne"}
        if hasMRI: manifest["mri"] = {"path": "mri"}
        if validatedProducts is not None: manifest["products"] = validatedProducts
        if hasMRI or derivedParts["derivedFiles"]:
            manifest["derivedFiles"] = derivedParts["derivedFiles"]

        cls.validateDerivedManifest(manifest)

        class DestinationView:
            """Expose exported files by logical checkpoint path."""
            def open(self, path, mode="rb", **kwargs):
                return filesystem.open(posixpath.join(destination, path), mode=mode, **kwargs)

        view = DestinationView()
        restoredHistory, labels = cls._readSessionHistory(view, len(runs))

        if runs and labels != cls._behaviorLabelMetadata(manifest, view):
            raise ValueError("History labels differ from exported behavioral settings.")
        if mneData is not None: cls._verifyMNEInventory(manifest, view)
        mriDescriptor = cls._verifyMRIInventory(manifest, view) if hasMRI else None

        ################################################################
        # Verify correspondence against exported identities, not just memory
        ################################################################
        savedCorrespondence = getattr(restoredHistory, "_checkpointScanRunCorrespondence", None)
        if savedCorrespondence != correspondenceSnapshot:
            raise ValueError("Exported correspondence differs from the working record.")

        if savedCorrespondence is not None and savedCorrespondence["pairs"]:
            if mriDescriptor is None:
                raise ValueError("Nonempty scan/run correspondence requires exported MRI scans.")

            scanIDs = [record["uuid"] for record in mriDescriptor["scans"]]
            behaviorIDs = []

            for record in runRecords:
                with view.open(posixpath.join(record["path"], "data.json"), "rt", encoding="utf-8") as source:
                    document = json.load(source)
                if not isinstance(document, dict):
                    raise ValueError("Exported behavioral data must contain a JSON object.")
                behaviorIDs.append(document.get("uuid"))

            for pair in savedCorrespondence["pairs"]:
                if scanIDs.count(pair["scanUUID"]) != 1:
                    raise ValueError("Matched MRI identity is absent or ambiguous in exported contents.")
                if behaviorIDs.count(pair["behaviorDataUUID"]) != 1:
                    raise ValueError("Matched behavioral identity is absent or ambiguous in exported contents.")

        requireUnchanged()
        if cls._sessionHistoryBytes(session, acquisition=False) != historyBytes:
            raise ValueError("Session history or metadata changed during export.")

        # The manifest is the final completion marker for local staging.
        cls.stageDerivedManifest(manifest, filesystem, destination)
        return destination, manifest

    @classmethod
    def _stageDerivedMRICheckpoint(cls, mri, filesystem, destination, *, progress=None):
        """Stage MRI metadata and only acquisitions requiring physical export.

        destination:
            Existing checkpoint staging directory. Its mri/ child must not
            already exist.

        Checkpoint-backed acquisitions:
            Read their verified MRI descriptor, not their NIfTI payload.
            Check backing, descriptor, and checkpoint content identities.
            Preserve original acquisition references independently of _data.
            Write current annotations into the new MRI descriptor.

        Other acquisition sources:
            Export original bytes using scan.exportSource().
            Verify the exported header against preserved source provenance.

        Returns:
            directories: Complete logical MRI directory inventory.
            files: Complete logical MRI file identities.
            reusedFiles: Mapping of logical destination filename to existing
                checkpoint publication reference.

        Files listed in reusedFiles are deliberately absent from staging.
        This is NOT a standalone bundle export. The database coordinator must
        resolve reuse references, publish new bytes, and attach every file.

        Does not query SQL, publish a checkpoint, change working scans, or
        serialize cached working images. Processed images remain separate
        derived-file attachments.

        Concurrent mutation is unsupported; detectable collection, metadata,
        and backing changes are rejected. Failed staging may leave files;
        the enclosing temporary-directory owner handles cleanup.
        """
        from copy import deepcopy

        from .pglMRI import pglMRI, pglMRIFileBacking, pglMRIBundle, pglMRINiftiMetadata

        if type(mri) is not pglMRI:
            raise TypeError("MRI checkpoint staging requires a pglMRI instance.")

        scans = list(mri.scans)
        if not scans:
            raise ValueError("MRI checkpoint staging requires at least one scan.")

        if not filesystem.isdir(destination):
            raise ValueError("MRI checkpoint staging requires an existing directory.")

        mriRoot = posixpath.join(destination, "mri")
        if filesystem.exists(mriRoot):
            raise FileExistsError(mriRoot)

        prepared = []

        # Resolve lazy UUID defaults before taking snapshots. Never access data.
        for index, scan in enumerate(scans):
            backing = scan._backing
            if backing is not None and not isinstance(backing, pglMRIFileBacking):
                raise TypeError(f"Scan {index}: unsupported acquisition backing.")

            sourcePath = backing.path if backing is not None else scan.localPath
            if not isinstance(sourcePath, str) or not sourcePath.lower().endswith((".nii", ".nii.gz")):
                raise ValueError(f"Scan {index}: an original NIfTI source is required.")

            identifier = scan.uuid
            try:
                canonicalUUID = str(uuid.UUID(identifier))
            except (ValueError, TypeError, AttributeError):
                raise ValueError(f"Scan {index}: invalid acquisition UUID.") from None

            if identifier != canonicalUUID:
                raise ValueError(f"Scan {index}: acquisition UUID must use canonical formatting.")
            if not isinstance(scan.name, str) or not scan.name.strip():
                raise ValueError(f"Scan {index}: name must be nonblank.")

            sourceMetadata = scan._copyMetadata(scan.sourceMetadata)
            metadata = scan._copyMetadata(scan.metadata)
            if "nifti" in metadata and type(metadata["nifti"]) is not dict:
                raise ValueError(f"Scan {index}: metadata['nifti'] must be a dictionary.")

            suffix = ".nii.gz" if sourcePath.lower().endswith(".nii.gz") else ".nii"
            prepared.append({
                "scan": scan,
                "uuid": identifier,
                "name": scan.name,
                "sourceMetadata": sourceMetadata,
                "metadata": metadata,
                "backing": backing,
                "backingFilesystem": None if backing is None else backing.fs,
                "sourcePath": sourcePath,
                "expectedIdentity": None if backing is None else backing.expectedIdentity,
                "localPath": scan.localPath,
                "path": f"scans/{index:06d}/source{suffix}",
            })

        def requireUnchanged():
            """Inspect runtime bindings and metadata without resolving data."""
            current = list(mri.scans)
            if len(current) != len(scans) or any(left is not right for left, right in zip(current, scans)):
                raise ValueError("MRI collection changed during checkpoint staging.")

            for item in prepared:
                scan = item["scan"]
                if (
                    scan.uuid != item["uuid"]
                    or scan.name != item["name"]
                    or scan.sourceMetadata != item["sourceMetadata"]
                    or scan.metadata != item["metadata"]
                    or scan._backing is not item["backing"]
                    or scan.localPath != item["localPath"]
                ):
                    raise ValueError("MRI metadata or source binding changed during checkpoint staging.")

                backing = item["backing"]
                if backing is not None and (
                    backing.fs is not item["backingFilesystem"]
                    or backing.path != item["sourcePath"]
                    or backing.expectedIdentity != item["expectedIdentity"]
                ):
                    raise ValueError("MRI acquisition backing changed during checkpoint staging.")

        def uniqueKeys(pairs):
            result = {}
            for key, value in pairs:
                if key in result: raise ValueError(f"Duplicate MRI descriptor key: {key!r}")
                result[key] = value
            return result

        def rejectConstant(value):
            raise ValueError(f"Nonfinite MRI descriptor JSON constant: {value}")

        descriptors = {}

        def checkpointAcquisition(item):
            """Resolve original header provenance using verified metadata only."""
            backing = item["backing"]
            if backing is None or not isinstance(backing.fs, pglCheckpointFilesystem):
                return None

            sourceFS = backing.fs
            sourceName = sourceFS._logicalPath(item["sourcePath"])
            parts = sourceName.split("/")

            # Existing MRI contracts use <bundle>/scans/NNNNNN/source.nii[.gz].
            # Reject unexpected bindings instead of inferring a descriptor.
            if (
                len(parts) < 4
                or parts[-3] != "scans"
                or re.fullmatch(r"[0-9]{6}", parts[-2]) is None
                or parts[-1] not in ("source.nii", "source.nii.gz")
            ):
                raise ValueError("Checkpoint MRI backing has an unsupported acquisition path.")

            bundleRoot = "/".join(parts[:-3])
            relativePath = "/".join(parts[-3:])
            descriptorPath = posixpath.join(bundleRoot, "mri.json")
            descriptorKey = (id(sourceFS), descriptorPath)

            reference = sourceFS.getPublicationReference(sourceName)
            identity = {key: reference[key] for key in ("sha256", "size_bytes")}

            if item["expectedIdentity"] != identity:
                raise ValueError("MRI backing identity differs from its checkpoint inventory.")

            if descriptorKey not in descriptors:
                # Check the bound before open(): checkpoint opens verify/spool
                # their complete file before returning a stream.
                maxBytes = 64 * 1024 * 1024
                entry = sourceFS.info(descriptorPath)
                if entry["type"] != "file" or not 0 <= entry["size"] <= maxBytes:
                    raise ValueError("MRI source descriptor exceeds the supported size limit.")

                with sourceFS.open(descriptorPath, "rb") as source:
                    content = source.read(entry["size"] + 1)

                if len(content) != entry["size"]:
                    raise ValueError("MRI source descriptor has an unexpected size.")

                descriptor = json.loads(content, object_pairs_hook=uniqueKeys, parse_constant=rejectConstant)
                if not isinstance(descriptor, dict):
                    raise ValueError("MRI source descriptor must contain an object.")

                contract = descriptor.get("contract")
                if contract == pglMRIBundle.contract:
                    pglMRIBundle.validateDescriptor(descriptor)
                elif contract == "pgl.mri.derived.v1":
                    pglMRIBundle.validateDerivedDescriptor(descriptor)
                else:
                    raise ValueError("Unsupported checkpoint MRI source descriptor.")

                descriptors[descriptorKey] = {
                    record["path"]: record for record in descriptor["scans"]
                }

            record = descriptors[descriptorKey].get(relativePath)
            if record is None:
                raise ValueError("MRI acquisition is absent from its source descriptor.")

            if record["uuid"] != item["uuid"]:
                raise ValueError("MRI acquisition UUID differs from its source descriptor.")

            if {key: record[key] for key in identity} != identity:
                raise ValueError("MRI source descriptor disagrees with its checkpoint payload identity.")

            return reference, deepcopy(record["sourceMetadata"]["nifti"])

        # Establish reuse and original-header associations before writing output.
        # Each source MRI descriptor is read only once for this operation.
        for index, item in enumerate(prepared):
            if progress is not None:
                progress(0.1 * index / len(prepared), f"Checking MRI acquisition reference {index + 1}/{len(prepared)}")

            item["reuse"] = checkpointAcquisition(item)
            if item["reuse"] is not None:
                _, originalHeader = item["reuse"]
                preservedHeader = item["sourceMetadata"].get("nifti")
                if "nifti" in item["sourceMetadata"] and preservedHeader != originalHeader:
                    raise ValueError("MRI original-header metadata differs from its verified source descriptor.")

        requireUnchanged()
        filesystem.makedirs(mriRoot, exist_ok=False)

        directories = {"mri", "mri/scans"}
        files = []
        reusedFiles = {}
        records = []

        for index, item in enumerate(prepared):
            requireUnchanged()
            logicalName = posixpath.join("mri", item["path"])
            directories.add(posixpath.dirname(logicalName))

            if progress is not None:
                action = "Reusing" if item["reuse"] is not None else "Exporting"
                progress(0.1 + 0.8 * index / len(prepared), f"{action} MRI acquisition {index + 1}/{len(prepared)}: {item['name']}")

            if item["reuse"] is not None:
                reference, originalHeader = item["reuse"]
                identity = {key: reference[key] for key in ("sha256", "size_bytes")}
                reusedFiles[logicalName] = deepcopy(reference)

                # No payload open, cache materialization, or destination copy.
                # Logical directories are recorded even without physical files.
            else:
                target = posixpath.join(destination, logicalName)
                identity = item["scan"].exportSource(target, filesystem=filesystem)
                if identity is None:
                    raise RuntimeError("MRI acquisition export was refused.")

                exported = pglMRIFileBacking(filesystem, target, expectedIdentity=identity)
                originalHeader = pglMRINiftiMetadata.readBacking(exported)

            sourceMetadata = deepcopy(item["sourceMetadata"])
            if "nifti" in sourceMetadata and sourceMetadata["nifti"] != originalHeader:
                raise ValueError("MRI acquisition header conflicts with preserved source provenance.")

            sourceMetadata["nifti"] = deepcopy(originalHeader)
            records.append({
                "index": index,
                "uuid": item["uuid"],
                "name": item["name"],
                "path": item["path"],
                **identity,
                "sourceMetadata": sourceMetadata,
                "metadata": deepcopy(item["metadata"]),
            })
            files.append({"name": logicalName, **identity})

        descriptor = {"contract": "pgl.mri.derived.v1", "scans": records}
        pglMRIBundle.validateDerivedDescriptor(descriptor)
        requireUnchanged()

        if progress is not None:
            progress(0.95, "Writing current MRI annotations and acquisition references")

        content = json.dumps(descriptor, sort_keys=True, indent=2, allow_nan=False).encode("utf-8")
        if len(content) > 64 * 1024 * 1024:
            raise ValueError("Derived MRI descriptor exceeds the supported size limit.")

        descriptorPath = posixpath.join(mriRoot, "mri.json")
        with filesystem.open(descriptorPath, "xb") as target:
            if target.write(content) != len(content):
                raise OSError("Incomplete derived MRI descriptor write.")

        expected = {"sha256": hashlib.sha256(content).hexdigest(), "size_bytes": len(content)}
        if pglStorage.hashFile(filesystem, descriptorPath) != expected:
            raise ValueError("Derived MRI descriptor verification failed.")

        files.append({"name": "mri/mri.json", **expected})
        requireUnchanged()

        if progress is not None:
            progress(1, f"MRI staging ready: {len(reusedFiles)} reused acquisitions, {len(records) - len(reusedFiles)} exported")

        return {
            "directories": sorted(directories),
            "files": sorted(files, key=lambda record: record["name"]),
            "reusedFiles": reusedFiles,
        }
        
    @classmethod
    def _stageDerivedStimuliCheckpoint(cls, database, filesystem, destination, *, taskPath, progress=None):
        """Stage current stimulus metadata and collect reusable PNG references.

        destination:
            Existing checkpoint staging directory.

        taskPath:
            Relative task directory within the new checkpoint, for example
            runs/000000/task01_nSD-mini.

        Unopened checkpoint-backed PNGs:
            Read their verified stimulus manifest, not their image bytes.
            Match source path, stimulus identity, and checkpoint SHA-256.
            Reuse existing content while preserving current trial metadata.

        Materialized images and other sources:
            Encode current pixels using the existing PNG export policy.
            Materialized images are conservatively treated as potentially
            edited; an existing backing does not prove they are unchanged.

        Returns:
            directories: Complete logical stimulus directory inventory.
            files: Complete logical stimulus file identities.
            reusedFiles: Existing checkpoint references indexed by NEW logical
                filename. Those payloads are absent from physical staging.

        Does not query SQL or publish a checkpoint.
        Does not change stimulus IDs or replace source bindings.
        Non-checkpoint image access may populate its ordinary image cache.

        Supports the exact existing image database/image classes. Other
        exporters require their own explicit staging implementation.
        Concurrent mutation is unsupported.
        """
        from copy import deepcopy
        from io import BytesIO

        from .pglImage import pglImageDatabase, pglImageFile, pglImageFileH5, pglImageFileNSDMini

        if type(database) is not pglImageDatabase:
            raise TypeError("Mixed stimulus staging requires an exact pglImageDatabase.")

        if (
            not isinstance(taskPath, str)
            or not taskPath
            or taskPath.startswith("/")
            or "\\" in taskPath
            or "\x00" in taskPath
            or any(part in ("", ".", "..") for part in taskPath.split("/"))
        ):
            raise ValueError("taskPath must be a valid relative POSIX path.")

        if not filesystem.isdir(destination):
            raise ValueError("Stimulus staging requires an existing checkpoint directory.")

        bundleName = posixpath.join(taskPath, "stimuli")
        imageDirectory = posixpath.join(bundleName, "images")
        bundlePath = posixpath.join(destination, bundleName)

        if filesystem.exists(bundlePath):
            raise FileExistsError(bundlePath)

        stimuli = list(database.stimuli)
        trials = list(database.trials)
        runStarted = database._runStarted
        referenced = {}
        trialRecords = []
        trialSnapshots = []

        # Validate references without evaluating trial.img or stimulus.img.
        for index, trial in enumerate(trials):
            if type(trial.trialNum) is not int or trial.trialNum != index:
                raise ValueError("Trial numbers must match their sequence positions.")
            if type(trial.trialId) is not int or trial.trialId < 0:
                raise ValueError("Trial IDs must be nonnegative integers.")
            if type(trial.stimulusNum) is not int:
                raise ValueError("Trial stimulus numbers must be integers.")
            if trial.status not in ("pending", "completed"):
                raise ValueError("Unsupported stimulus trial status.")

            stimulusNum = trial.stimulusNum
            if stimulusNum == -1:
                if trial.stimulus is not None:
                    raise ValueError("A blank trial cannot reference an image.")
            else:
                if not 0 <= stimulusNum < len(stimuli):
                    raise ValueError("Trial references an invalid stimulus number.")
                if trial.stimulus is not stimuli[stimulusNum]:
                    raise ValueError("Stimulus inventory and trial references disagree.")
                referenced[stimulusNum] = trial.stimulus

            record = {
                "trialNum": trial.trialNum,
                "trialId": trial.trialId,
                "stimulusNum": stimulusNum,
                "status": trial.status,
                "completedAt": trial.completedAt,
                "metadata": deepcopy(trial.metadata),
            }
            trialRecords.append(record)
            trialSnapshots.append((trial, trial.stimulus))

        if len({record["trialId"] for record in trialRecords}) != len(trialRecords):
            raise ValueError("Trial IDs must be unique.")

        def encode(document):
            return (
                json.dumps(
                    document,
                    indent=2,
                    default=pglImageDatabase._manifestJsonDefault,
                    allow_nan=False,
                ) + "\n"
            ).encode("utf-8")

        prepared = []
        for stimulusNum, stimulus in sorted(referenced.items()):
            if type(stimulus) not in (pglImageFile, pglImageFileH5, pglImageFileNSDMini):
                raise TypeError("Unsupported stimulus image class for checkpoint staging.")

            sourceInfo = deepcopy(stimulus.sourceInfo)
            if not sourceInfo:
                sourceInfo = {
                    "filename": stimulus.filename,
                    "filesystemPrefix": stimulus.filesystemPrefix,
                    "originalStimulusNum": stimulusNum,
                }
                if isinstance(stimulus, pglImageFileH5):
                    sourceInfo.update({
                        "datasetPath": stimulus.datasetPath,
                        "imageIndex": stimulus.imageIndex,
                        "imageAxis": stimulus.imageAxis,
                    })

            record = {
                "stimulusNum": stimulusNum,
                "stimulusId": stimulus.stimulusId or uuid.uuid4().hex,
                "name": stimulus.name,
                "metadata": deepcopy(stimulus.metadata),
                "caption": stimulus.caption,
                "condition": stimulus.condition,
                "conditionNum": stimulus.conditionNum,
                "sourceInfo": sourceInfo,
            }

            # Snapshot portable fields separately from runtime image objects.
            snapshot = {
                "stimulusId": stimulus.stimulusId,
                "name": stimulus.name,
                "metadata": deepcopy(stimulus.metadata),
                "caption": stimulus.caption,
                "condition": stimulus.condition,
                "conditionNum": stimulus.conditionNum,
                "sourceInfo": deepcopy(stimulus.sourceInfo),
                "filename": stimulus.filename,
                "filesystemPrefix": stimulus.filesystemPrefix,
            }
            prepared.append({
                "stimulus": stimulus,
                "filesystem": stimulus.filesystem,
                "snapshot": encode(snapshot),
                "record": record,
                "initialImage": stimulus._img,
            })

        identifiers = [item["record"]["stimulusId"] for item in prepared]
        if len(set(identifiers)) != len(identifiers):
            raise ValueError("Referenced stimulus IDs must be unique.")

        manifest = {
            "formatName": "pglImageDatabaseRun",
            "formatVersion": 2,
            "runStarted": runStarted,
            "stimuli": [item["record"] for item in prepared],
            "trials": trialRecords,
        }
        encode(manifest)  # Validate metadata before payload reads or writes.

        sourceManifests = {}

        def uniqueKeys(pairs):
            result = {}
            for key, value in pairs:
                if key in result: raise ValueError(f"Duplicate stimulus manifest key: {key!r}")
                result[key] = value
            return result

        def reusableImage(item):
            """Return identity/geometry from verified source metadata only."""
            stimulus = item["stimulus"]
            sourceFS = item["filesystem"]

            # Exact class avoids applying ordinary PNG semantics to HDF5
            # selections or subclasses with custom image transformations.
            if type(stimulus) is not pglImageFile or stimulus._img is not None:
                return None
            if not isinstance(sourceFS, pglCheckpointFilesystem):
                return None

            sourceName = sourceFS._logicalPath(stimulus.filename)
            parts = sourceName.split("/")
            if len(parts) < 3 or parts[-2] != "images" or not parts[-1].lower().endswith(".png"):
                raise ValueError("Checkpoint image has an unsupported stimulus payload path.")

            sourceRoot = "/".join(parts[:-2])
            relativeName = "/".join(parts[-2:])
            manifestPath = posixpath.join(sourceRoot, "manifest.json")
            key = (id(sourceFS), manifestPath)

            reference = sourceFS.getPublicationReference(sourceName)

            if key not in sourceManifests:
                # Bound the descriptor before checkpoint open verifies/spools it.
                entry = sourceFS.info(manifestPath)
                if entry["type"] != "file" or not 0 <= entry["size"] <= 16 * 1024 * 1024:
                    raise ValueError("Stimulus manifest exceeds the supported metadata limit.")

                with sourceFS.open(manifestPath, "rb") as source:
                    content = source.read(entry["size"] + 1)
                if len(content) != entry["size"]:
                    raise ValueError("Stimulus manifest size mismatch.")

                document = json.loads(content, object_pairs_hook=uniqueKeys)
                if (
                    not isinstance(document, dict)
                    or document.get("formatName") != "pglImageDatabaseRun"
                    or type(document.get("formatVersion")) is not int
                    or document["formatVersion"] not in (1, 2)
                    or not isinstance(document.get("stimuli"), list)
                ):
                    raise ValueError("Unsupported source stimulus manifest.")

                sourceManifests[key] = document["stimuli"]

            matches = [
                record for record in sourceManifests[key]
                if isinstance(record, dict)
                and record.get("filename") == relativeName
                and record.get("stimulusId") == stimulus.stimulusId
            ]
            if len(matches) != 1:
                raise ValueError("Image backing lacks a unique matching saved stimulus record.")

            record = matches[0]
            if record.get("sha256") != reference["sha256"]:
                raise ValueError("Stimulus manifest hash differs from checkpoint image identity.")

            size = record.get("size")
            mode = record.get("mode")
            if (
                not isinstance(size, list)
                or len(size) != 2
                or any(type(value) is not int or value <= 0 for value in size)
                or mode not in ("L", "RGB", "RGBA")
            ):
                raise ValueError("Saved stimulus image geometry is invalid or unsupported.")

            return reference, list(size), mode

        # Collect reuse decisions before creating output. No image pixels are
        # loaded by this pass, and each source stimulus manifest is read once.
        for item in prepared:
            item["reuse"] = reusableImage(item)

        filesystem.makedirs(posixpath.join(destination, imageDirectory), exist_ok=False)
        files = []
        reusedFiles = {}
        allocatedNames = {}

        def writeBytes(logicalName, content):
            """Write new staging bytes and verify their complete identity."""
            path = posixpath.join(destination, logicalName)
            identity = {"sha256": hashlib.sha256(content).hexdigest(), "size_bytes": len(content)}

            with filesystem.open(path, "xb") as target:
                if target.write(content) != len(content):
                    raise OSError("Incomplete stimulus staging write.")

            if pglStorage.hashFile(filesystem, path) != identity:
                raise ValueError("Stimulus staging verification failed.")

            return identity

        for index, item in enumerate(prepared):
            stimulus = item["stimulus"]
            record = item["record"]
            reuse = item["reuse"]

            if progress is not None:
                action = "Reusing" if reuse is not None else "Encoding"
                progress(index / max(len(prepared), 1), f"{action} stimulus {index + 1}/{len(prepared)}")

            imageBytes = None
            if reuse is not None:
                reference, size, mode = reuse
                identity = {key: reference[key] for key in ("sha256", "size_bytes")}
            else:
                # Already materialized pixels may have been edited in place.
                # Other source types use their established image loader.
                img = stimulus.img
                if img.mode not in ("L", "RGB", "RGBA"):
                    raise ValueError(f"Cannot export image mode {img.mode!r} losslessly.")

                with BytesIO() as buffer:
                    img.save(buffer, format="PNG")
                    imageBytes = buffer.getvalue()

                size, mode = list(img.size), img.mode
                identity = {"sha256": hashlib.sha256(imageBytes).hexdigest(), "size_bytes": len(imageBytes)}

            preferredName = pglImageDatabase._getRunImageFilename(stimulus, record["stimulusNum"])
            stem = posixpath.splitext(preferredName)[0]
            candidate = preferredName
            suffix = 2

            # Keep portable case-insensitive names. Identical images with the
            # same preferred name may share one logical payload.
            while candidate.casefold() in allocatedNames:
                existingName, existingIdentity = allocatedNames[candidate.casefold()]
                if existingIdentity == identity:
                    candidate = existingName
                    break
                candidate = f"{stem}_{suffix}.png"
                suffix += 1

            logicalName = posixpath.join(imageDirectory, candidate)

            if candidate.casefold() not in allocatedNames:
                allocatedNames[candidate.casefold()] = (candidate, dict(identity))

                if reuse is not None:
                    reusedFiles[logicalName] = deepcopy(reference)
                elif writeBytes(logicalName, imageBytes) != identity:
                    raise ValueError("Encoded stimulus identity changed during staging.")

                files.append({"name": logicalName, **identity})

            record.update({
                "filename": f"images/{candidate}",
                "sha256": identity["sha256"],
                "size": size,
                "mode": mode,
            })

        # Do not allow detected collection/metadata changes to publish a mixed
        # snapshot. Pixel mutation during serialization remains unsupported.
        currentStimuli = list(database.stimuli)
        currentTrials = list(database.trials)
        if (
            len(currentStimuli) != len(stimuli)
            or any(left is not right for left, right in zip(currentStimuli, stimuli))
            or len(currentTrials) != len(trials)
            or any(left is not right for left, right in zip(currentTrials, trials))
            or database._runStarted != runStarted
        ):
            raise ValueError("Stimulus database changed during checkpoint staging.")

        for record, (trial, originalStimulus) in zip(trialRecords, trialSnapshots):
            current = {
                "trialNum": trial.trialNum,
                "trialId": trial.trialId,
                "stimulusNum": trial.stimulusNum,
                "status": trial.status,
                "completedAt": trial.completedAt,
                "metadata": trial.metadata,
            }
            if trial.stimulus is not originalStimulus or encode(current) != encode(record):
                raise ValueError("Stimulus trial changed during checkpoint staging.")

        for item in prepared:
            stimulus = item["stimulus"]
            current = {
                "stimulusId": stimulus.stimulusId,
                "name": stimulus.name,
                "metadata": stimulus.metadata,
                "caption": stimulus.caption,
                "condition": stimulus.condition,
                "conditionNum": stimulus.conditionNum,
                "sourceInfo": stimulus.sourceInfo,
                "filename": stimulus.filename,
                "filesystemPrefix": stimulus.filesystemPrefix,
            }
            if stimulus.filesystem is not item["filesystem"] or encode(current) != item["snapshot"]:
                raise ValueError("Stimulus metadata or source binding changed during staging.")

            if item["reuse"] is not None and stimulus._img is not None:
                raise ValueError("A reused stimulus was materialized during checkpoint staging.")
            if item["initialImage"] is not None and stimulus._img is not item["initialImage"]:
                raise ValueError("A materialized stimulus was replaced during staging.")

        content = encode(manifest)
        if len(content) > 16 * 1024 * 1024:
            raise ValueError("Stimulus manifest exceeds the supported metadata limit.")

        manifestName = posixpath.join(bundleName, "manifest.json")
        files.append({"name": manifestName, **writeBytes(manifestName, content)})

        if progress is not None:
            progress(1, f"Stimuli staged: {len(reusedFiles)} reused PNG files")

        return {
            "directories": sorted([bundleName, imageDirectory]),
            "files": sorted(files, key=lambda record: record["name"]),
            "reusedFiles": reusedFiles,
        }
    
    @classmethod
    def _stageDerivedRunCheckpoint(cls, run, filesystem, destination, *, runPath, progress=None):
        """Stage current behavioral contents without resolving reusable payloads.

        destination:
            Existing checkpoint staging directory.

        runPath:
            New logical run directory, for example runs/000000.

        Pending checkpoint-backed scalar fields reuse their saved bytes.
        Resolved fields serialize their current values.

        Pending tasks:
            Preserve individually loaded objects from _taskCache.
            Reuse uncached checkpoint-backed task directories.
            Resolve non-checkpoint tasks through their ordinary loader.

        Loaded tasks:
            Save current settings, state, data, and parameter bundles.
            Stage stimulus metadata/images separately, avoiding saveRun()'s
            unconditional image materialization.

        Returns complete logical directories/files plus reusedFiles.
        Reused payloads are intentionally absent from physical staging.

        This is database publication staging, not a standalone export.
        Does not query SQL, commit, or change the working run's source binding.

        Concurrent mutation is unsupported. Detectable collection and pending
        backing replacements are rejected. Existing component serializers may
        initialize their ordinary metadata defaults.
        """
        from .pglExperiment import pglTaskBase
        from .pglLazyLoad import pglFsspecBacking
        from .pglSerialize import pglSerialize
        from .pglSession import pglRun

        if type(run) is not pglRun:
            raise TypeError("Behavioral checkpoint staging requires an exact pglRun.")

        if not isinstance(runPath, str) or re.fullmatch(r"runs/[0-9]{6}", runPath) is None:
            raise ValueError("runPath must have the form runs/000000.")

        if not filesystem.isdir(destination):
            raise ValueError("Behavioral staging requires an existing checkpoint directory.")

        runDestination = posixpath.join(destination, runPath)
        if filesystem.exists(runDestination):
            raise FileExistsError(runDestination)

        directories = {"runs", runPath}
        filesByName = {}
        reusedFiles = {}
        pendingChecks = []

        def report(fraction, description):
            if progress is not None: progress(fraction, description)

        def validateRelativePath(path):
            if (
                not isinstance(path, str)
                or not path
                or path.startswith("/")
                or "\\" in path
                or "\x00" in path
                or any(part in ("", ".", "..") for part in path.split("/"))
            ):
                raise ValueError(f"Invalid behavioral checkpoint path: {path!r}")

        def addParents(name):
            parent = posixpath.dirname(name)
            while parent:
                directories.add(parent)
                parent = posixpath.dirname(parent)

        def addFile(record, reference=None):
            """Keep the logical inventory exact, including reused files."""
            name = record["name"]
            validateRelativePath(name)

            if name in filesByName or name in directories:
                raise ValueError(f"Duplicate or conflicting checkpoint file: {name!r}")

            filesByName[name] = dict(record)
            addParents(name)

            if reference is not None:
                expected = {key: record[key] for key in ("sha256", "size_bytes")}
                if any(reference[key] != value for key, value in expected.items()):
                    raise ValueError("Reuse reference differs from its logical file identity.")
                reusedFiles[name] = deepcopy(reference)

        def addReference(sourceFS, sourcePath, logicalName):
            reference = sourceFS.getPublicationReference(sourcePath)
            addFile({
                "name": logicalName,
                "sha256": reference["sha256"],
                "size_bytes": reference["size_bytes"],
            }, reference)

        def inventoryWrittenDirectory(logicalRoot):
            """Hash physical staging files only; reused files are added separately."""
            fullRoot = posixpath.join(destination, logicalRoot)
            directories.add(logicalRoot)

            for current, directoryNames, fileNames in filesystem.walk(fullRoot, detail=False, on_error="raise"):
                relativeRoot = posixpath.relpath(current, destination)
                validateRelativePath(relativeRoot)

                for name in directoryNames:
                    logicalName = posixpath.join(relativeRoot, name)
                    validateRelativePath(logicalName)
                    directories.add(logicalName)

                for name in fileNames:
                    logicalName = posixpath.join(relativeRoot, name)
                    addFile({
                        "name": logicalName,
                        **pglStorage.hashFile(filesystem, posixpath.join(current, name)),
                    })

        def reuseTaskDirectory(sourceFS, sourcePath, logicalRoot):
            """Carry an unopened task inventory forward without payload reads."""
            sourceRoot = sourceFS._logicalPath(sourcePath)
            if sourceFS.info(sourceRoot)["type"] != "directory":
                raise ValueError("Pending task backing is not a directory.")

            # Match the required task layout before accepting subtree reuse.
            for name in ("settings.json", "state.json", "data.json"):
                if sourceFS.info(posixpath.join(sourceRoot, name))["type"] != "file":
                    raise ValueError(f"Pending task is missing {name}.")

            if sourceFS.info(posixpath.join(sourceRoot, "parameters"))["type"] != "directory":
                raise ValueError("Pending task is missing its parameters directory.")

            directories.add(logicalRoot)

            # Checkpoint walk/info are inventory operations, not payload reads.
            # Preserve ancillary files belonging to this unchanged task too.
            for current, directoryNames, fileNames in sourceFS.walk(sourceRoot, detail=False, on_error="raise"):
                relativeRoot = posixpath.relpath(current, sourceRoot)
                targetRoot = logicalRoot if relativeRoot == "." else posixpath.join(logicalRoot, relativeRoot)
                validateRelativePath(targetRoot)
                directories.add(targetRoot)

                for name in directoryNames:
                    logicalName = posixpath.join(targetRoot, name)
                    validateRelativePath(logicalName)
                    directories.add(logicalName)

                for name in fileNames:
                    addReference(
                        sourceFS,
                        posixpath.join(current, name),
                        posixpath.join(targetRoot, name),
                    )

        report(0, "Preparing current behavioral metadata")

        # Task names define the current bundle layout. Resolving this small
        # metadata object does not load task contents or stimulus pixels.
        experimentSettings = run.experimentSettings
        if experimentSettings is None:
            raise ValueError("Cannot save run without experiment settings.")

        taskNames = list(experimentSettings.tasks)
        taskDirectories = [
            pglTaskBase.getTaskDirectoryName(taskID=index, taskName=name)
            for index, name in enumerate(taskNames)
        ]

        for name in taskDirectories:
            validateRelativePath(name)
            if "/" in name:
                raise ValueError("Task directory names must be single path components.")

        if len(set(taskDirectories)) != len(taskDirectories):
            raise ValueError("Task directory names must be unique.")

        components = {"experimentSettings": experimentSettings}
        componentReferences = {}

        for name in ("settings", "data"):
            if run.lazyIsPending(name):
                backing = run._lazyRuntime().pending[name]

                if isinstance(backing, pglFsspecBacking) and isinstance(backing.fs, pglCheckpointFilesystem):
                    componentReferences[name] = (backing.fs, backing.path)
                    pendingChecks.append((name, backing))
                    continue

            # Assignment cancels pending backing. A resolved/assigned value,
            # including an explicit None, must not be replaced by old bytes.
            component = getattr(run, name)
            if component is None:
                raise ValueError(f"Cannot save run: missing {name}.")
            components[name] = component

        # Match existing saveDerivedRun() semantics: state is not lazy-bound.
        # None means use the saved source state, without installing it on run.
        state = run.state
        stateSourceFS = run.filesystem
        stateSourceRoot = run.fullDataPath

        if state is not None:
            components["state"] = state
        else:
            if stateSourceFS is None or not stateSourceRoot:
                raise ValueError("Cannot save run: state is missing and there is no source.")

            statePath = posixpath.join(stateSourceRoot, "state.json")
            if isinstance(stateSourceFS, pglCheckpointFilesystem):
                componentReferences["state"] = (stateSourceFS, statePath)
            else:
                with stateSourceFS.open(statePath, "rb") as source:
                    restoredState = pglSerialize.fromJSON(source.read(), filename=statePath)

                if restoredState is None:
                    raise ValueError("Cannot restore source experiment state for export.")
                components["state"] = restoredState

        for name, component in components.items():
            if not callable(getattr(component, "saveStrict", None)):
                raise TypeError(f"Run component {name!r} has no saveStrict() method.")

        tasksPending = run.lazyIsPending("tasks")
        taskBacking = run._lazyRuntime().pending["tasks"] if tasksPending else None
        taskPlans = []

        if tasksPending:
            if not isinstance(taskBacking, pglFsspecBacking):
                raise TypeError("Pending behavioral tasks require pglFsspecBacking.")

            pendingChecks.append(("tasks", taskBacking))

            # getTaskAt() maps current task names to the backing directory.
            # Verify that mapping before treating uncached tasks as unchanged.
            settingsPath = posixpath.join(taskBacking.path, "experimentSettings.json")

            if isinstance(taskBacking.fs, pglCheckpointFilesystem):
                entry = taskBacking.fs.info(settingsPath)
                if entry["type"] != "file" or not 0 <= entry["size"] <= 16 * 1024 * 1024:
                    raise ValueError("Source experiment settings exceed the metadata limit.")

            with taskBacking.fs.open(settingsPath, "rb") as source:
                content = source.read(16 * 1024 * 1024 + 1)

            if len(content) > 16 * 1024 * 1024:
                raise ValueError("Source experiment settings exceed the metadata limit.")

            savedSettings = json.loads(content)
            if not isinstance(savedSettings, dict) or savedSettings.get("tasks") != taskNames:
                raise ValueError(
                    "Task names changed while the task collection remains pending. "
                    "Resolve the original task collection before changing its layout."
                )

            cachedTasks = dict(run._taskCache)
            if any(type(index) is not int or not 0 <= index < len(taskNames) for index in cachedTasks):
                raise ValueError("Individual task cache contains an invalid index.")

            for index, taskDirectory in enumerate(taskDirectories):
                if index in cachedTasks:
                    taskPlans.append(("working", cachedTasks[index]))
                elif isinstance(taskBacking.fs, pglCheckpointFilesystem):
                    sourcePath = posixpath.join(taskBacking.path, taskDirectory)
                    taskPlans.append(("reuse", sourcePath))
                else:
                    # Ordinary source files lack registered immutable identities.
                    # Preserve existing loading/export behavior for those tasks.
                    taskPlans.append(("working", run.getTaskAt(index)))

            # Include tasks loaded above when checking for subsequent replacement.
            cachedTasks = dict(run._taskCache)
            resolvedTasks = None
        else:
            values = run._trait_values.get("tasks")
            if values is None:
                raise ValueError("Cannot save run: tasks are missing.")

            resolvedTasks = list(values)
            cachedTasks = None
            if len(resolvedTasks) != len(taskNames):
                raise ValueError("Task count differs from current experiment settings.")

            taskPlans = [("working", task) for task in resolvedTasks]

        # Validate working task layout before creating output.
        for index, (kind, value) in enumerate(taskPlans):
            if kind == "reuse": continue

            task = value
            if task is None:
                raise ValueError(f"Task {index} is missing.")

            if task._getTaskDirectoryName() != taskDirectories[index]:
                raise ValueError(f"Task {index} directory differs from current experiment settings.")

            for name in ("settings", "state", "data"):
                component = getattr(task, name, None)
                if component is None or not callable(getattr(component, "saveStrict", None)):
                    raise ValueError(f"Task {index} lacks a persistable {name} component.")

            for parameter in task.parameters:
                if not callable(getattr(parameter, "saveBundleStrict", None)):
                    raise TypeError(f"Task {index} contains an unsupported parameter bundle.")

        filesystem.makedirs(runDestination, exist_ok=False)

        report(0.05, "Staging run settings, state, and behavioral data")

        for name in ("experimentSettings", "settings", "state", "data"):
            logicalName = posixpath.join(runPath, f"{name}.json")

            if name in componentReferences:
                sourceFS, sourcePath = componentReferences[name]
                addReference(sourceFS, sourcePath, logicalName)
            else:
                path = posixpath.join(destination, logicalName)
                components[name].saveStrict(filename=path, filesystem=filesystem)
                addFile({"name": logicalName, **pglStorage.hashFile(filesystem, path)})

        for index, (kind, value) in enumerate(taskPlans):
            logicalTask = posixpath.join(runPath, taskDirectories[index])
            start = 0.1 + 0.85 * index / max(len(taskPlans), 1)
            end = 0.1 + 0.85 * (index + 1) / max(len(taskPlans), 1)
            taskProgress = progress.section(start, end) if progress is not None else None

            if kind == "reuse":
                if taskProgress is not None:
                    taskProgress(0, f"Reusing unopened task {index + 1}/{len(taskPlans)}")

                reuseTaskDirectory(taskBacking.fs, value, logicalTask)

                if taskProgress is not None:
                    taskProgress(1, "Task inventory reused without payload reads")
                continue

            task = value
            taskDestination = posixpath.join(destination, logicalTask)
            filesystem.makedirs(taskDestination, exist_ok=False)

            if taskProgress is not None:
                taskProgress(0, f"Saving current task metadata {index + 1}/{len(taskPlans)}")

            # Do not call saveBundleStrict(): its stimulus export resolves img.
            for name in ("settings", "state", "data"):
                getattr(task, name).saveStrict(
                    filename=posixpath.join(taskDestination, f"{name}.json"),
                    filesystem=filesystem,
                )

            parameterPath = posixpath.join(taskDestination, "parameters")
            filesystem.makedirs(parameterPath, exist_ok=False)

            for parameter in list(task.parameters):
                parameter.saveBundleStrict(dataPath=parameterPath, filesystem=filesystem)

            # Inventory metadata/parameters before the stimulus helper adds its
            # own mixed physical/reference inventory.
            inventoryWrittenDirectory(logicalTask)

            stimulusDatabase = task.stimulusDatabase
            if stimulusDatabase is not None:
                stimulusProgress = taskProgress.section(0.2, 1) if taskProgress is not None else None
                parts = cls._stageDerivedStimuliCheckpoint(
                    stimulusDatabase,
                    filesystem,
                    destination,
                    taskPath=logicalTask,
                    progress=stimulusProgress,
                )

                directories.update(parts["directories"])
                for record in parts["files"]:
                    addFile(record, parts["reusedFiles"].get(record["name"]))

            elif taskProgress is not None:
                # Explicitly cleared stimuli stay absent. Do not restore them
                # from the source task merely because saved files exist there.
                taskProgress(1, "Task metadata staged; no stimulus database attached")

        report(0.97, "Checking behavioral staging consistency")

        if run.experimentSettings is not experimentSettings or list(experimentSettings.tasks) != taskNames:
            raise ValueError("Experiment settings or task layout changed during staging.")

        for name, backing in pendingChecks:
            if not run.lazyIsPending(name) or run._lazyRuntime().pending[name] is not backing:
                raise ValueError(f"Pending run field {name!r} changed during staging.")

        for name in ("settings", "data"):
            if name in components and getattr(run, name) is not components[name]:
                raise ValueError(f"Run component {name!r} was replaced during staging.")

        if run.state is not state:
            raise ValueError("Run state was replaced during staging.")

        if state is None and (run.filesystem is not stateSourceFS or run.fullDataPath != stateSourceRoot):
            raise ValueError("Run state source binding changed during staging.")

        if tasksPending:
            currentCache = dict(run._taskCache)
            if set(currentCache) != set(cachedTasks) or any(currentCache[index] is not task for index, task in cachedTasks.items()):
                raise ValueError("Individual task cache changed during staging.")
        else:
            current = run._trait_values.get("tasks")
            if current is None or len(current) != len(resolvedTasks) or any(left is not right for left, right in zip(current, resolvedTasks)):
                raise ValueError("Task collection changed during staging.")

        if set(filesByName).intersection(directories):
            raise ValueError("Behavioral staging contains conflicting file and directory paths.")

        report(1, f"Behavioral run staged: {len(reusedFiles)} existing file references")

        return {
            "directories": sorted(directories),
            "files": [filesByName[name] for name in sorted(filesByName)],
            "reusedFiles": reusedFiles,
        }
        
    @classmethod
    def _stageDerivedFilesCheckpoint(cls, session, filesystem, destination, *, progress=None):
        """Stage new attachments and reference existing checkpoint payloads.

        Restored checkpoint attachments:
            Require matching attachment/backing metadata.
            Check identity against the checkpoint inventory.
            Reuse registered bytes without calling getDerivedFile().

        Local or other supported attachments:
            Resolve and verify using getDerivedFile().
            Copy into staging with complete byte verification.

        Returns:
            derivedFiles: Portable attachment descriptors.
            directories: Complete logical attachment directories.
            files: Complete logical file identities.
            reusedFiles: Existing checkpoint references indexed by NEW path.

        Reused files are deliberately absent from physical staging.
        This is not a standalone export. The publication coordinator must
        resolve references and attach every declared file.

        Does not query SQL, publish a checkpoint, or change attachments.
        Local paths and runtime filesystem handles never enter the manifest.
        Concurrent mutation is unsupported; detectable metadata/backing
        replacements are rejected.
        """
        from copy import deepcopy

        from fsspec.implementations.local import LocalFileSystem

        if not isinstance(session.derivedFiles, dict):
            raise TypeError("session.derivedFiles must be a dictionary.")

        if not filesystem.isdir(destination):
            raise ValueError("Attachment staging requires an existing checkpoint directory.")

        attachments = deepcopy(session.derivedFiles)

        if not attachments:
            if progress is not None: progress(1, "No derived attachments")
            return {"derivedFiles": [], "directories": [], "files": [], "reusedFiles": {}}

        derivedRoot = posixpath.join(destination, "derived")
        if filesystem.exists(derivedRoot):
            raise FileExistsError(derivedRoot)

        for name in attachments:
            if (
                not isinstance(name, str)
                or not name.strip()
                or any(character in name for character in ("\x00", "\n", "\r"))
            ):
                raise ValueError("Derived-file names must be nonblank strings without NUL or newlines.")

        prepared = []
        descriptors = []
        directories = {"derived"}
        runCount = len(session.runs or [])

        if progress is not None: progress(0, "Validating derived attachment references")

        for index, name in enumerate(sorted(attachments)):
            attachment = attachments[name]
            required = {"version", "runIndex", "filename", "mediaType", "sha256", "size_bytes"}

            if (
                not isinstance(attachment, dict)
                or not required.issubset(attachment)
                or set(attachment) - required - {"localPath"}
                or type(attachment["version"]) is not int
                or attachment["version"] != 1
            ):
                raise ValueError(f"Invalid derived-file attachment: {name!r}")

            runIndex = attachment["runIndex"]
            if runIndex is not None and (type(runIndex) is not int or not 0 <= runIndex < runCount):
                raise ValueError(f"Invalid behavioral run association for {name!r}.")

            filename = attachment["filename"]
            if (
                not isinstance(filename, str)
                or not filename.strip()
                or filename in (".", "..")
                or any(character in filename for character in ("/", "\\", "\x00", "\n", "\r"))
            ):
                raise ValueError("Derived filename must be a single safe filename.")

            mediaType = attachment["mediaType"]
            if (
                not isinstance(mediaType, str)
                or not mediaType.strip()
                or any(character in mediaType for character in ("\x00", "\n", "\r"))
            ):
                raise ValueError("Derived mediaType must be a nonblank string without NUL or newlines.")

            digest = attachment["sha256"]
            size = attachment["size_bytes"]
            if not isinstance(digest, str) or re.fullmatch(r"[0-9a-f]{64}", digest) is None:
                raise ValueError(f"Invalid derived-file SHA-256 for {name!r}.")
            if type(size) is not int or not 0 <= size <= 9223372036854775807:
                raise ValueError(f"Invalid derived-file size for {name!r}.")

            relativeRoot = f"derived/f{index:06d}"
            logicalName = posixpath.join(relativeRoot, filename)
            directories.add(relativeRoot)

            descriptors.append({
                "name": name,
                "runIndex": runIndex,
                "filename": filename,
                "mediaType": mediaType,
                "path": logicalName,
            })

            item = {
                "name": name,
                "path": logicalName,
                "identity": {"sha256": digest, "size_bytes": size},
                "reference": None,
                "backing": None,
                "source": None,
            }

            if "localPath" in attachment:
                localPath = attachment["localPath"]
                if not isinstance(localPath, str) or not localPath:
                    raise ValueError(f"Invalid local attachment path for {name!r}.")
            else:
                backing = getattr(session, "_derivedFileBackings", {}).get(name)
                if not isinstance(backing, dict) or backing.get("attachment") != attachment:
                    raise ValueError(f"Attachment {name!r} has no matching saved backing.")

                sourceFS = backing.get("filesystem")
                sourcePath = backing.get("path")
                if not isinstance(sourcePath, str) or not sourcePath:
                    raise ValueError(f"Attachment {name!r} has an invalid backing path.")

                item.update({
                    "backing": backing,
                    "backingFilesystem": sourceFS,
                    "backingPath": sourcePath,
                })

                if isinstance(sourceFS, pglCheckpointFilesystem):
                    reference = sourceFS.getPublicationReference(sourcePath)
                    if any(reference[key] != value for key, value in item["identity"].items()):
                        raise ValueError(f"Attachment {name!r} differs from its checkpoint payload identity.")

                    item["reference"] = reference

            prepared.append(item)

        def requireUnchanged():
            """Validate attachment metadata and captured backing bindings."""
            if session.derivedFiles != attachments:
                raise ValueError("Derived attachments changed during checkpoint staging.")

            if len(session.runs or []) != runCount:
                raise ValueError("Behavioral run collection size changed during attachment staging.")

            currentBackings = getattr(session, "_derivedFileBackings", {})

            for item in prepared:
                backing = item["backing"]
                if backing is None: continue

                if (
                    currentBackings.get(item["name"]) is not backing
                    or backing.get("attachment") != attachments[item["name"]]
                    or backing.get("filesystem") is not item["backingFilesystem"]
                    or backing.get("path") != item["backingPath"]
                ):
                    raise ValueError("Derived attachment backing changed during checkpoint staging.")

        requireUnchanged()

        # Verify non-reusable sources before creating the attachment directory.
        # Checkpoint-backed attachments never enter this retrieval path.
        for item in prepared:
            if item["reference"] is not None: continue

            if progress is not None:
                progress(None, f"Verifying attachment source: {item['name']}")

            source = session.getDerivedFile(item["name"])
            if source is None:
                raise ValueError(f"Derived attachment disappeared: {item['name']!r}")

            item["source"] = Path(source)

        requireUnchanged()
        filesystem.makedirs(derivedRoot, exist_ok=False)

        files = []
        reusedFiles = {}
        localFS = LocalFileSystem(skip_instance_cache=True)

        # Reused payloads require only metadata work. Weight actual transfers
        # by bytes without letting large reused files dominate the estimate.
        workRecords = [
            {
                "name": item["name"],
                "size_bytes": 1 if item["reference"] is not None else max(1, item["identity"]["size_bytes"]),
                "item": item,
            }
            for item in prepared
        ]
        fileRange = progress.section(0.1, 1) if progress is not None else None

        for work, fileProgress in pglProgress.fileSections(workRecords, fileRange):
            requireUnchanged()
            item = work["item"]
            logicalName = item["path"]
            identity = item["identity"]

            if item["reference"] is not None:
                # Preserve the logical directory without creating or copying
                # a physical payload. Registration will attach existing content.
                reusedFiles[logicalName] = deepcopy(item["reference"])
                if fileProgress is not None:
                    fileProgress(1, "Reusing saved attachment without payload access")
            else:
                filesystem.makedirs(
                    posixpath.dirname(posixpath.join(destination, logicalName)),
                    exist_ok=False,
                )

                stored = pglStorage.copyVerifiedFile(
                    localFS,
                    str(item["source"]),
                    filesystem,
                    destination,
                    {"name": logicalName, **identity},
                    objectKey=logicalName,
                    progress=fileProgress,
                )

                if any(stored[key] != value for key, value in identity.items()):
                    raise ValueError("Staged attachment identity differs from its registered working identity.")

            files.append({"name": logicalName, **identity})

        requireUnchanged()

        if progress is not None:
            progress(1, f"Attachments staged: {len(reusedFiles)} reused, {len(files) - len(reusedFiles)} copied")

        return {
            "derivedFiles": descriptors,
            "directories": sorted(directories),
            "files": sorted(files, key=lambda record: record["name"]),
            "reusedFiles": reusedFiles,
        }
        
    @classmethod
    def _stageDerivedSessionCheckpoint(cls, session, filesystem, destination, *, productRecords, progress=None):
        """Stage a complete logical checkpoint with selective physical export.

        destination:
            Fresh checkpoint staging directory; must not already exist.

        productRecords:
            Named matrix revisions already prepared by the publication
            coordinator. Must exactly match current matrix attachment names.

        Returns:
            destination: Physical staging directory.
            manifest: Complete logical checkpoint manifest.
            reusedFiles: Existing checkpoint references indexed by logical path.

        Every manifest file is represented exactly once:
            A physical staged file, or an existing checkpoint reference.

        Reused payloads are not copied into staging.
        The outer manifest and history are always written for this publication.

        Behavioral contents, stimuli, MRI acquisitions, and derived attachments
        use selective staging. MNE retains the existing full bundle exporter.
        Matrix arrays are published separately by the caller.

        Does not query SQL, register file links, commit, or update session
        checkpoint bookkeeping. This is not a standalone bundle export.

        Concurrent mutation is unsupported. Detectable collection, annotation,
        attachment, and history changes are rejected. The caller additionally
        owns publication-time validation and transaction cleanup.
        """
        from copy import deepcopy

        from .pglMRI import pglMRI
        from .pglSession import pglMNE
        from .pglStorage import pglStorage

        pglStorage.requireSafeSave(session)

        if not isinstance(destination, str) or not destination.strip():
            raise ValueError("A nonempty checkpoint staging path is required.")
        if filesystem.exists(destination):
            raise FileExistsError(destination)

        runs = list(session.runs or [])
        mneData = session.mne
        mriData = session.mri
        hasMNE = mneData is not None
        hasMRI = mriData is not None

        if hasMNE and hasMRI:
            raise ValueError("Combined MRI/MNE checkpoints remain unsupported.")
        if hasMNE and type(mneData) is not pglMNE:
            raise TypeError("MNE checkpoint staging requires an exact pglMNE.")
        if hasMRI and (type(mriData) is not pglMRI or not mriData.scans):
            raise ValueError("MRI checkpoint staging requires a nonempty pglMRI.")
        if not runs and not hasMNE and not hasMRI:
            raise ValueError("A checkpoint must contain behavioral, MRI, or MNE contents.")

        products = cls._snapshotSessionMatrices(session)
        validatedProducts = cls._validateMatrixRecordsForSession(session, productRecords)

        if {record["name"] for record in validatedProducts} != set(products):
            raise ValueError("Matrix revision references must exactly match current attachments.")

        if not isinstance(session.derivedFiles, dict):
            raise TypeError("session.derivedFiles must be a dictionary.")

        derivedSnapshot = deepcopy(session.derivedFiles)
        correspondenceSnapshot = deepcopy(session.scanRunCorrespondence)

        # Capture history before any staging. Correspondence validation may read
        # behavioral data.json, but does not open stimulus or MRI payloads.
        historyBytes = cls._sessionHistoryBytes(session, acquisition=False)

        scans = list(mriData.scans) if hasMRI else []
        scanSnapshots = [
            {
                "uuid": scan.uuid,
                "name": scan.name,
                "sourceMetadata": scan._copyMetadata(scan.sourceMetadata),
                "metadata": scan._copyMetadata(scan.metadata),
                "backing": scan._backing,
                "backingFilesystem": None if scan._backing is None else scan._backing.fs,
                "backingPath": None if scan._backing is None else scan._backing.path,
                "expectedIdentity": None if scan._backing is None else scan._backing.expectedIdentity,
                "localPath": scan.localPath,
            }
            for scan in scans
        ]

        def report(fraction, description):
            if progress is not None: progress(fraction, description)

        def requireUnchanged():
            """Check working structure without resolving scientific payloads."""
            pglStorage.requireSafeSave(session)
            cls._requireSessionMatricesUnchanged(session, products)

            currentRuns = list(session.runs or [])
            if len(currentRuns) != len(runs) or any(left is not right for left, right in zip(currentRuns, runs)):
                raise ValueError("Behavioral run collection changed during checkpoint staging.")

            if session.mne is not mneData or session.mri is not mriData:
                raise ValueError("Session modality collection changed during checkpoint staging.")
            if session.derivedFiles != derivedSnapshot:
                raise ValueError("Derived attachments changed during checkpoint staging.")
            if session.scanRunCorrespondence != correspondenceSnapshot:
                raise ValueError("Scan/run correspondence changed during checkpoint staging.")

            if hasMRI:
                currentScans = list(mriData.scans)
                if len(currentScans) != len(scans) or any(left is not right for left, right in zip(currentScans, scans)):
                    raise ValueError("MRI scan collection changed during checkpoint staging.")

                for scan, snapshot in zip(scans, scanSnapshots):
                    if (
                        scan.uuid != snapshot["uuid"]
                        or scan.name != snapshot["name"]
                        or scan.sourceMetadata != snapshot["sourceMetadata"]
                        or scan.metadata != snapshot["metadata"]
                        or scan._backing is not snapshot["backing"]
                        or scan.localPath != snapshot["localPath"]
                    ):
                        raise ValueError("MRI metadata or source binding changed during checkpoint staging.")

                    backing = scan._backing
                    if backing is not None and (
                        backing.fs is not snapshot["backingFilesystem"]
                        or backing.path != snapshot["backingPath"]
                        or backing.expectedIdentity != snapshot["expectedIdentity"]
                    ):
                        raise ValueError("MRI acquisition backing changed during checkpoint staging.")

        directories = set()
        filesByName = {}
        reusedFiles = {}
        runRecords = []

        def addParts(parts):
            """Merge disjoint component inventories without hiding duplicates."""
            incomingFiles = parts["files"]
            incomingReferences = parts.get("reusedFiles", {})
            incomingNames = [record["name"] for record in incomingFiles]

            if len(set(incomingNames)) != len(incomingNames):
                raise ValueError("A staging component returned duplicate filenames.")
            if set(incomingReferences) - set(incomingNames):
                raise ValueError("A reuse reference has no matching logical file.")

            directories.update(parts["directories"])

            for record in incomingFiles:
                name = record["name"]
                if name in filesByName:
                    raise ValueError(f"Duplicate staged checkpoint filename: {name!r}")

                filesByName[name] = dict(record)

                if name in incomingReferences:
                    reference = incomingReferences[name]
                    if any(reference[key] != record[key] for key in ("sha256", "size_bytes")):
                        raise ValueError("Reused content differs from its manifest identity.")
                    reusedFiles[name] = deepcopy(reference)

        def inventoryPhysicalDirectory(relativeRoot):
            """Inventory an ordinary exported bundle, currently used for MNE."""
            componentDirectories = {relativeRoot}
            componentFiles = []
            fullRoot = posixpath.join(destination, relativeRoot)

            for current, directoryNames, fileNames in filesystem.walk(fullRoot, detail=False, on_error="raise"):
                logicalRoot = posixpath.relpath(current, destination)

                for name in directoryNames:
                    componentDirectories.add(posixpath.join(logicalRoot, name))

                for name in fileNames:
                    componentFiles.append({
                        "name": posixpath.join(logicalRoot, name),
                        **pglStorage.hashFile(filesystem, posixpath.join(current, name)),
                    })

            return {
                "directories": sorted(componentDirectories),
                "files": componentFiles,
                "reusedFiles": {},
            }

        requireUnchanged()
        filesystem.makedirs(destination, exist_ok=False)

        ################################################################
        # Stage behavioral metadata and selective task/stimulus contents
        ################################################################
        for index, run in enumerate(runs):
            start = 0.55 * index / len(runs)
            end = 0.55 * (index + 1) / len(runs)
            runProgress = progress.section(start, end) if progress is not None else None
            runPath = f"runs/{index:06d}"

            report(start, f"Staging behavioral run {index + 1}/{len(runs)}")
            parts = cls._stageDerivedRunCheckpoint(
                run,
                filesystem,
                destination,
                runPath=runPath,
                progress=runProgress,
            )
            addParts(parts)
            runRecords.append({"index": index, "path": runPath})

        ################################################################
        # Stage modality metadata and acquisition contents
        ################################################################
        if hasMRI:
            report(0.55, "Staging MRI annotations and acquisition references")
            addParts(cls._stageDerivedMRICheckpoint(
                mriData,
                filesystem,
                destination,
                progress=progress.section(0.55, 0.80) if progress is not None else None,
            ))

        elif hasMNE:
            # Explicit compatibility path. This still resolves/exports MNE
            # fields; do not claim that MNE payload reuse is implemented here.
            report(0.55, "Exporting MNE bundle using the existing full-export path")
            mneData.saveBundle(posixpath.join(destination, "mne"), filesystem=filesystem)
            addParts(inventoryPhysicalDirectory("mne"))

        ################################################################
        # Stage new attachments and reuse saved attachment references
        ################################################################
        requireUnchanged()
        derivedParts = cls._stageDerivedFilesCheckpoint(
            session,
            filesystem,
            destination,
            progress=progress.section(0.80, 0.92) if progress is not None else None,
        )
        addParts(derivedParts)

        ################################################################
        # Write current history independently of reused scientific payloads
        ################################################################
        report(0.92, "Writing current checkpoint history")
        historyPath = posixpath.join(destination, "history.json")

        with filesystem.open(historyPath, "xb") as target:
            if target.write(historyBytes) != len(historyBytes):
                raise OSError("Incomplete checkpoint history write.")

        historyIdentity = {
            "sha256": hashlib.sha256(historyBytes).hexdigest(),
            "size_bytes": len(historyBytes),
        }
        if pglStorage.hashFile(filesystem, historyPath) != historyIdentity:
            raise ValueError("Staged checkpoint history verification failed.")

        addParts({
            "directories": [],
            "files": [{"name": "history.json", **historyIdentity}],
            "reusedFiles": {},
        })

        ################################################################
        # Preserve existing manifest contracts and logical layouts
        ################################################################
        if hasMRI:
            contractVersion = "pgl.derived.mri.v2"
        elif derivedParts["derivedFiles"]:
            contractVersion = "pgl.derived.session.v3" if hasMNE else "pgl.derived.behavior.v3"
        else:
            contractVersion = "pgl.derived.session.v2" if hasMNE else "pgl.derived.behavior.v2"

        manifest = {
            "contract_version": contractVersion,
            "runs": runRecords,
            "directories": sorted(directories),
            "files": [filesByName[name] for name in sorted(filesByName)],
            "products": validatedProducts,
        }

        if hasMNE: manifest["mne"] = {"path": "mne"}
        if hasMRI: manifest["mri"] = {"path": "mri"}
        if hasMRI or derivedParts["derivedFiles"]:
            manifest["derivedFiles"] = derivedParts["derivedFiles"]

        cls.validateDerivedManifest(manifest)

        ################################################################
        # Verify generated descriptors and behavioral labels
        ################################################################
        class StagingView:
            """Expose only physically staged files by logical name."""

            def open(self, path, mode="rb", **kwargs):
                if path in reusedFiles:
                    raise ValueError(f"Staging validation unexpectedly requested reused payload bytes: {path!r}")
                return filesystem.open(posixpath.join(destination, path), mode=mode, **kwargs)

        view = StagingView()
        restoredHistory, labels = cls._readSessionHistory(view, len(runs))

        # Run staging always writes current experimentSettings.json.
        if runs and labels != cls._behaviorLabelMetadata(manifest, view):
            raise ValueError("History labels differ from staged behavioral settings.")

        if hasMNE: cls._verifyMNEInventory(manifest, view)
        mriDescriptor = cls._verifyMRIInventory(manifest, view) if hasMRI else None

        savedCorrespondence = getattr(restoredHistory, "_checkpointScanRunCorrespondence", None)
        if savedCorrespondence != correspondenceSnapshot:
            raise ValueError("Staged correspondence differs from the working record.")

        if savedCorrespondence is not None and savedCorrespondence["pairs"]:
            if mriDescriptor is None:
                raise ValueError("Nonempty scan/run correspondence requires MRI acquisitions.")

            scanIDs = [record["uuid"] for record in mriDescriptor["scans"]]
            behaviorIDs = []

            # History preparation resolves run.data when validating nonempty
            # correspondence. Therefore these current data files were written
            # by run staging, not silently carried forward as pending bytes.
            for record in runRecords:
                path = posixpath.join(record["path"], "data.json")
                with view.open(path, "rt", encoding="utf-8") as source:
                    document = json.load(source)

                if not isinstance(document, dict):
                    raise ValueError("Staged behavioral data must contain an object.")
                behaviorIDs.append(document.get("uuid"))

            for pair in savedCorrespondence["pairs"]:
                if scanIDs.count(pair["scanUUID"]) != 1:
                    raise ValueError("Matched MRI acquisition is absent or ambiguous in staged metadata.")
                if behaviorIDs.count(pair["behaviorDataUUID"]) != 1:
                    raise ValueError("Matched behavioral acquisition is absent or ambiguous in staged metadata.")

        ################################################################
        # Ensure every file is either staged or reused, never both/neither
        ################################################################
        report(0.97, "Checking complete physical/reference inventory")
        physicalNames = set()

        for current, _, fileNames in filesystem.walk(destination, detail=False, on_error="raise"):
            for name in fileNames:
                physicalNames.add(posixpath.relpath(posixpath.join(current, name), destination))

        expectedPhysical = set(filesByName) - set(reusedFiles)
        if physicalNames != expectedPhysical:
            raise ValueError("Physical staging files do not exactly match the non-reused manifest inventory.")

        requireUnchanged()
        if cls._sessionHistoryBytes(session, acquisition=False) != historyBytes:
            raise ValueError("Session history or labels changed during checkpoint staging.")

        # Write the outer manifest last. It describes the complete logical
        # checkpoint, not a self-contained copy of the temporary directory.
        cls.stageDerivedManifest(manifest, filesystem, destination)

        report(1, f"Checkpoint staged: {len(expectedPhysical)} physical files, {len(reusedFiles)} reused references")

        return {
            "destination": destination,
            "manifest": manifest,
            "reusedFiles": reusedFiles,
        }
    
    # ++++++++++++++++++++++++++ stageDerivedManifest +++++++++++++++++++++++++
    # Direct callers in this module: saveDerivedSessionFiles.
    @classmethod
    def stageDerivedManifest(cls, manifest, destinationFilesystem, destinationRoot):
        """Write and verify a derived manifest without overwriting.

        The destination directory must already exist.
        The manifest does not include its own file identity.
        Returns the stored manifest's object key, SHA-256, and byte count.
        """
        cls.validateDerivedManifest(manifest)

        # Use the same canonical JSON encoding as raw manifests.
        manifestBytes = cls.encodeRawManifest(manifest)
        expected = {
            "sha256": hashlib.sha256(manifestBytes).hexdigest(),
            "size_bytes": len(manifestBytes),
        }

        destinationPath = posixpath.join(destinationRoot, "manifest.json")

        with destinationFilesystem.open(destinationPath, "xb") as file:
            file.write(manifestBytes)

        stored = pglStorage.hashFile(destinationFilesystem, destinationPath)

        if stored != expected:
            raise ValueError("Stored derived manifest verification failed.")

        return {"object_key": "manifest.json", **stored}

    @classmethod
    def _installSessionMatrices(cls, session, matrices, manifest):
        """Install loaded matrices according to the validated manifest version.

        MRI-v2:
            Explicit ownership selects session.dataMatrices or
            session.mri.dataMatrices.

        Legacy:
            All matrices remain session-owned, regardless of their names.

        Requires a newly reconstructed session with empty matrix collections.
        Does not open or compute arrays. The enclosing loader owns resource
        cleanup if validation or installation fails.
        """
        from .pglData import pglDataMatrix

        cls.validateDerivedManifest(manifest) if manifest.get("contract_version", "").startswith("pgl.derived.") else cls.validateRawSessionManifest(manifest)

        records = manifest.get("products", [])
        if manifest["contract_version"] == "pgl.derived.mri.v2":
            cls._installOwnedSessionMatrices(session, matrices, records)
            return

        records = cls._validateSessionProductRecords(records)

        if type(matrices) is not dict:
            raise TypeError("Restored matrices must be a dictionary.")
        if set(matrices) != {record["name"] for record in records}:
            raise ValueError("Loaded matrix keys differ from the legacy manifest.")
        if not isinstance(session.dataMatrices, dict) or session.dataMatrices:
            raise ValueError("Matrix restoration requires an empty session.dataMatrices.")

        if session.mri is not None:
            if not isinstance(session.mri.dataMatrices, dict) or session.mri.dataMatrices:
                raise ValueError("Legacy restoration requires an empty MRI matrix collection.")

        installed = {}

        for record in records:
            matrix = matrices[record["name"]]
            if not isinstance(matrix, pglDataMatrix):
                raise TypeError(f"Restored matrix {record['name']!r} is not a pglDataMatrix.")
            if matrix.matrixRevisionID != record["matrixRevisionID"]:
                raise ValueError(f"Restored matrix {record['name']!r} has the wrong revision.")

            installed[record["name"]] = matrix

        session.dataMatrices = installed


    # -------------------------------------------------------------------------
    # Shared session bundle registration and completion
    # -------------------------------------------------------------------------
    # Register exported checkpoint files and validate catalog correspondence before publication.

    # ++++++++++++++++++++++ _registerSessionBundleFiles +++++++++++++++++++++
    @classmethod
    def _registerSessionBundleFiles(cls, connection, postgres, sessionID, backendID, manifest, *, objectPrefix, storageOptions=None, origin="derived", accessContext=None, progress=None):
        """Register a staged raw/derived bundle and its verified labels.

        Verifies the manifest, modality descriptors, history, acquisition
        labels, and every registered file before attaching catalog links.

        Supports existing behavioral/MNE bundles and raw v2 MRI bundles.
        Matrix products remain separate from checkpoint file registration.

        Modality files inherit explicit session subject metadata when there
        are no behavioral runs. With runs, no modality-to-run association is
        inferred. Derived attachments use their declared run association.

        Uses a nested transaction/savepoint; the caller must commit.
        Does not copy payloads or complete the checkpoint.

        A supplied access context is borrowed. Otherwise this method creates
        and closes an operation-owned context.

        Optional progress reports descriptor checks, byte-based stored-file
        verification, and catalog registration.
        """
        from contextlib import ExitStack

        for label, value in (("sessionID", sessionID), ("backendID", backendID)):
            if type(value) is not int or not 0 <= value <= 9223372036854775807:
                raise ValueError(f"{label} must be a nonnegative PostgreSQL bigint.")

        if (
            not isinstance(objectPrefix, str)
            or objectPrefix.startswith("/")
            or "\\" in objectPrefix
            or "\x00" in objectPrefix
            or any(part in {"", ".", ".."} for part in objectPrefix.split("/"))
        ):
            raise ValueError("objectPrefix must be a valid relative POSIX path.")

        if storageOptions is not None and not isinstance(storageOptions, dict):
            raise TypeError("storageOptions must be a dictionary or None.")

        if accessContext is not None:
            if not isinstance(accessContext, pglDatabaseAccess):
                raise TypeError("accessContext must be a pglDatabaseAccess instance.")
            if storageOptions:
                raise ValueError("Configure storage options on accessContext, not on both arguments.")
            if cls._checkpointDatabaseIdentity(accessContext._postgres) != cls._checkpointDatabaseIdentity(postgres):
                raise ValueError("The supplied payload context belongs to a different configured database.")

        if progress is not None: progress(0, "Validating unpublished bundle checkpoint")

        cls._validateSessionBundleManifest(manifest, origin=origin)
        payloadRole = "acquisition" if origin == "raw" else "derived"
        manifestBytes = cls.encodeRawManifest(manifest)
        manifestIdentity = {
            "sha256": hashlib.sha256(manifestBytes).hexdigest(),
            "size_bytes": len(manifestBytes),
        }
        hasMNE = "mne" in manifest
        hasMRI = "mri" in manifest

        # Validated declarations identify attachments and their explicit
        # behavioral run associations; filenames alone do not establish them.
        derivedByPath = {
            record["path"]: record
            for record in manifest.get("derivedFiles", [])
        }

        sessionsTable = sql.Identifier(postgres.databaseSchema, "session")
        linksTable = sql.Identifier(postgres.databaseSchema, "session_files")
        backendsTable = sql.Identifier(postgres.databaseSchema, "storage_backends")

        with connection.transaction():
            statement = sql.SQL("SELECT origin, status, contract_version, deleted_at FROM {} WHERE session_id = %s FOR UPDATE").format(sessionsTable)
            checkpoint = connection.execute(statement, (sessionID,)).fetchone()

            if checkpoint != (origin, "in_progress", manifest["contract_version"], None):
                raise ValueError("Checkpoint must be active, in progress, and match the manifest origin and contract.")

            statement = sql.SQL("SELECT 1 FROM {} WHERE session_id = %s LIMIT 1").format(linksTable)
            if connection.execute(statement, (sessionID,)).fetchone() is not None:
                raise ValueError("Checkpoint already has file links.")

            statement = sql.SQL("SELECT url_prefix, is_active FROM {} WHERE backend_id = %s FOR SHARE").format(backendsTable)
            backend = connection.execute(statement, (backendID,)).fetchone()
            if backend is None or not backend[1]:
                raise ValueError("Storage backend is missing or inactive.")

            registeredRoot = backend[0]

            with ExitStack() as resources:
                if accessContext is None:
                    access = resources.enter_context(pglDatabaseAccess(postgres, {backendID: storageOptions or {}}))
                else:
                    access = accessContext

                filesystem, root = access.resolve(backendID, registeredRoot)
                manifestKey = posixpath.join(objectPrefix, "manifest.json")

                if progress is not None: progress(0, "Verifying stored manifest")
                manifestProgress = progress.section(0, 0.01, label="manifest.json") if progress is not None else None

                actualManifest = pglStorage.hashFile(
                    filesystem,
                    posixpath.join(root, manifestKey),
                    progress=manifestProgress,
                    expectedSize=manifestIdentity["size_bytes"],
                    description="Verifying stored manifest",
                )
                if actualManifest != manifestIdentity:
                    raise ValueError("Saved manifest does not match the supplied manifest.")

                fileLocations = {
                    record["name"]: {
                        "sha256": record["sha256"],
                        "size_bytes": record["size_bytes"],
                        "locations": [{
                            "backend_id": backendID,
                            "url_prefix": registeredRoot,
                            "object_key": posixpath.join(objectPrefix, record["name"]),
                        }],
                    }
                    for record in manifest["files"]
                }

                # This view verifies descriptor/history bytes on opening.
                # It borrows the save coordinator's storage access.
                archive = pglCheckpointFilesystem(
                    manifest,
                    fileLocations,
                    accessContext=access,
                    ownsAccess=False,
                )
                resources.callback(archive.close)

                if hasMNE:
                    if progress is not None: progress(0.01, "Verifying archived MNE descriptor")
                    cls._verifyMNEInventory(manifest, archive)

                if hasMRI:
                    if progress is not None: progress(0.01, "Verifying archived MRI descriptor")
                    cls._verifyMRIInventory(manifest, archive)

                if progress is not None: progress(0.02, "Verifying archived checkpoint history")
                _, historyMetadata = cls._readSessionHistory(archive, len(manifest["runs"]))

                if manifest["runs"]:
                    if progress is not None: progress(0.03, "Verifying archived acquisition labels")
                    metadata = cls._behaviorLabelMetadata(manifest, archive)

                    if historyMetadata is not None and historyMetadata != metadata:
                        raise ValueError("History labels differ from archived behavioral experiment settings.")
                else:
                    metadata = historyMetadata or {
                        "version": 1,
                        "labels": [{
                            "runIndex": None,
                            "experimentName": None,
                            "subjectID": None,
                        }],
                    }

                if progress is not None: progress(0.04, "Registering verified checkpoint labels")
                cls._recordSessionLabelMetadata(connection, postgres, sessionID, metadata)

                subjectsByRun = {
                    run["path"]: metadata["labels"][run["index"]]["subjectID"]
                    for run in manifest["runs"]
                }

                # Explicit session labels apply to modality-only sessions.
                # Do not guess modality-to-run associations for mixed sessions.
                modalitySubject = metadata["labels"][0]["subjectID"] if not manifest["runs"] else None

                def registerPayload(name, identity, role, subjectID=None, fileProgress=None):
                    """Verify stored bytes, register their location, and attach."""
                    if fileProgress is not None: fileProgress(0, "Resolving content identity")

                    fileID = cls.getOrCreateFile(connection, postgres, identity["sha256"], identity["size_bytes"])
                    cls.verifyAndRegisterStorageLocation(
                        connection, postgres, fileID, backendID,
                        posixpath.join(objectPrefix, name),
                        accessContext=access,
                        progress=fileProgress,
                    )

                    if fileProgress is not None: fileProgress(None, "Attaching checkpoint file")
                    cls.attachCheckpointFile(connection, postgres, sessionID, name, fileID, role=role, subjectID=subjectID)

                records = [*manifest["files"], {"name": "manifest.json", **manifestIdentity}]
                fileRange = progress.section(0.05, 1) if progress is not None else None

                for record, fileProgress in pglProgress.fileSections(records, fileRange):
                    name = record["name"]

                    if name == "manifest.json":
                        registerPayload(name, record, role="manifest", fileProgress=fileProgress)

                    elif name == "history.json":
                        registerPayload(name, record, role="history", fileProgress=fileProgress)

                    elif name in derivedByPath:
                        runIndex = derivedByPath[name]["runIndex"]
                        subjectID = None if runIndex is None else subjectsByRun[manifest["runs"][runIndex]["path"]]
                        registerPayload(name, record, role="derived", subjectID=subjectID, fileProgress=fileProgress)

                    elif (hasMNE and name.startswith("mne/")) or (hasMRI and name.startswith("mri/")):
                        registerPayload(name, record, role=payloadRole, subjectID=modalitySubject, fileProgress=fileProgress)

                    else:
                        runPath = "/".join(name.split("/")[:2])
                        if runPath not in subjectsByRun:
                            raise ValueError(f"Checkpoint file has no declared owner: {name!r}")

                        registerPayload(name, record, role=payloadRole, subjectID=subjectsByRun[runPath], fileProgress=fileProgress)

        return sessionID
    
    @classmethod
    def _registerMixedDerivedSessionFiles(cls, connection, postgres, sessionID, backendID, manifest, *, objectPrefix, reusedFiles, accessContext, progress=None):
        """Register a derived checkpoint containing new and reused payloads.

        reusedFiles:
            Mapping of logical filenames to records returned by
            _resolveCheckpointFileReuse():
                fileID, sha256, size_bytes

            The caller must resolve these records in this same outer
            transaction, before publication writes or checkpoint row locks.
            Its dependency/content/location locks must remain held.

        New files:
            Must already exist under backendID/objectPrefix.
            Verify their bytes before registering locations and file links.

        Reused files:
            Recheck catalog identity and eligibility.
            Attach existing file IDs without reading payload bytes or
            refreshing storage verification timestamps.

        Descriptor/history validation uses a mixed checkpoint filesystem.
        Those small metadata files may be read; reused scientific payloads
        are not opened merely to register their links.

        Borrows accessContext. Does not close it, copy payloads, register
        matrix products, complete the checkpoint, or commit the outer
        transaction.

        Uses a savepoint so partial registration rolls back on failure.
        """
        from psycopg.pq import TransactionStatus
        from psycopg.rows import tuple_row

        for label, value in (("sessionID", sessionID), ("backendID", backendID)):
            if type(value) is not int or not 0 <= value <= 9223372036854775807:
                raise ValueError(f"{label} must be a nonnegative PostgreSQL bigint.")

        if (
            not isinstance(objectPrefix, str)
            or not objectPrefix
            or objectPrefix.startswith("/")
            or "\\" in objectPrefix
            or "\x00" in objectPrefix
            or any(part in ("", ".", "..") for part in objectPrefix.split("/"))
        ):
            raise ValueError("objectPrefix must be a valid relative POSIX path.")

        if not isinstance(accessContext, pglDatabaseAccess):
            raise TypeError("accessContext must be a pglDatabaseAccess instance.")
        if cls._checkpointDatabaseIdentity(accessContext._postgres) != cls._checkpointDatabaseIdentity(postgres):
            raise ValueError("Payload access belongs to a different configured database.")

        if connection.info.transaction_status != TransactionStatus.INTRANS:
            raise ValueError("Mixed registration requires an active caller-owned transaction.")

        cls.validateDerivedManifest(manifest)

        if not isinstance(reusedFiles, dict):
            raise TypeError("reusedFiles must be a dictionary.")

        inventory = {record["name"]: record for record in manifest["files"]}
        if set(reusedFiles) - set(inventory):
            raise ValueError("Reused files must belong to the manifest inventory.")

        # Copy metadata rather than retaining caller-owned registration records.
        reusedFiles = deepcopy(reusedFiles)
        reuseByID = {}

        for name, record in reusedFiles.items():
            if not isinstance(record, dict) or set(record) != {"fileID", "sha256", "size_bytes"}:
                raise ValueError(f"Invalid resolved reuse record for {name!r}.")

            fileID = record["fileID"]
            if type(fileID) is not int or not 0 <= fileID <= 9223372036854775807:
                raise ValueError("Reused fileID must be a nonnegative PostgreSQL bigint.")

            expected = {key: inventory[name][key] for key in ("sha256", "size_bytes")}
            identity = {key: record[key] for key in expected}

            if identity != expected:
                raise ValueError(f"Reused identity differs from the manifest: {name!r}")

            if fileID in reuseByID and reuseByID[fileID] != identity:
                raise ValueError("One reused file ID has conflicting content identities.")

            reuseByID[fileID] = identity

        # These generated metadata files must be newly staged/uploaded.
        # This keeps their validation independent of scientific-payload reuse.
        generatedNames = {"history.json"}
        generatedNames.update(
            posixpath.join(run["path"], "experimentSettings.json")
            for run in manifest["runs"]
        )
        if "mri" in manifest: generatedNames.add("mri/mri.json")
        if "mne" in manifest: generatedNames.add("mne/mne.json")

        if generatedNames.intersection(reusedFiles):
            raise ValueError("Mixed registration requires newly staged history, labels, and modality descriptors.")

        manifestBytes = cls.encodeRawManifest(manifest)
        manifestIdentity = {
            "sha256": hashlib.sha256(manifestBytes).hexdigest(),
            "size_bytes": len(manifestBytes),
        }

        sessions = sql.Identifier(postgres.databaseSchema, "session")
        links = sql.Identifier(postgres.databaseSchema, "session_files")
        files = sql.Identifier(postgres.databaseSchema, "files")
        locations = sql.Identifier(postgres.databaseSchema, "storage_locations")
        backends = sql.Identifier(postgres.databaseSchema, "storage_backends")

        def report(fraction, description):
            if progress is not None: progress(fraction, description)

        with connection.transaction():
            with connection.cursor(row_factory=tuple_row) as cursor:
                report(0, "Checking unpublished checkpoint and reuse catalog")

                statement = sql.SQL("""
                    SELECT origin, status, contract_version, deleted_at
                    FROM {}
                    WHERE session_id = %s
                    FOR UPDATE
                """).format(sessions)
                cursor.execute(statement, (sessionID,))

                if cursor.fetchone() != ("derived", "in_progress", manifest["contract_version"], None):
                    raise ValueError("Checkpoint must be active, in progress, and match the derived manifest.")

                cursor.execute(
                    sql.SQL("SELECT 1 FROM {} WHERE session_id = %s LIMIT 1").format(links),
                    (sessionID,),
                )
                if cursor.fetchone() is not None:
                    raise ValueError("Checkpoint already has file links.")

                cursor.execute(
                    sql.SQL("SELECT url_prefix, is_active FROM {} WHERE backend_id = %s FOR SHARE").format(backends),
                    (backendID,),
                )
                backend = cursor.fetchone()

                if backend is None or not backend[1]:
                    raise ValueError("Destination backend is missing or inactive.")

                registeredRoot = backend[0]
                locationsByID = {}

                if reuseByID:
                    # Earlier reuse resolution holds the protecting locks.
                    # Recheck rather than trusting arbitrary supplied file IDs.
                    statement = sql.SQL("""
                        SELECT content.file_id,
                               content.sha256,
                               content.size_bytes,
                               backend.backend_id,
                               backend.url_prefix,
                               location.object_key
                        FROM {files} AS content
                        JOIN {locations} AS location
                          ON location.file_id = content.file_id
                        JOIN {backends} AS backend
                          ON backend.backend_id = location.backend_id
                        WHERE content.file_id = ANY(%s::bigint[])
                          AND content.deleted_at IS NULL
                          AND location.deleted_at IS NULL
                          AND location.status = 'present'
                          AND location.verified_at IS NOT NULL
                          AND backend.is_active
                          AND EXISTS (
                              SELECT 1
                              FROM {links} AS reference
                              JOIN {sessions} AS owner
                                ON owner.session_id = reference.session_id
                              WHERE reference.file_id = content.file_id
                                AND reference.deleted_at IS NULL
                                AND owner.deleted_at IS NULL
                                AND owner.status = 'complete'
                          )
                        ORDER BY content.file_id, location.priority,
                                 backend.backend_id, location.object_key
                    """).format(
                        files=files,
                        locations=locations,
                        backends=backends,
                        links=links,
                        sessions=sessions,
                    )
                    cursor.execute(statement, (sorted(reuseByID),))

                    for fileID, digest, size, sourceBackendID, root, key in cursor.fetchall():
                        if reuseByID[fileID] != {"sha256": digest, "size_bytes": size}:
                            raise ValueError("Reused content identity differs from the current catalog.")

                        locationsByID.setdefault(fileID, []).append({
                            "backend_id": sourceBackendID,
                            "url_prefix": root,
                            "object_key": key,
                        })

                    if set(locationsByID) != set(reuseByID):
                        raise ValueError("Some reused payloads no longer have eligible active catalog references.")

            ################################################################
            # Validate generated metadata through the complete logical inventory
            ################################################################
            report(0.02, "Verifying uploaded checkpoint manifest")
            destinationFS, destinationRoot = accessContext.resolve(backendID, registeredRoot)
            manifestKey = posixpath.join(objectPrefix, "manifest.json")

            actual = pglStorage.hashFile(
                destinationFS,
                posixpath.join(destinationRoot, manifestKey),
                expectedSize=manifestIdentity["size_bytes"],
                description="Verifying uploaded checkpoint manifest",
            )
            if actual != manifestIdentity:
                raise ValueError("Uploaded checkpoint manifest differs from the supplied manifest.")

            fileLocations = {}

            for name, record in inventory.items():
                if name in reusedFiles:
                    candidates = locationsByID[reusedFiles[name]["fileID"]]
                else:
                    candidates = [{
                        "backend_id": backendID,
                        "url_prefix": registeredRoot,
                        "object_key": posixpath.join(objectPrefix, name),
                    }]

                fileLocations[name] = {
                    "sha256": record["sha256"],
                    "size_bytes": record["size_bytes"],
                    "locations": deepcopy(candidates),
                }

            # Construct a complete view, but open only generated metadata.
            # Closing this view must not close the coordinator's access context.
            archive = pglCheckpointFilesystem(
                manifest,
                fileLocations,
                accessContext=accessContext,
                ownsAccess=False,
            )

            try:
                report(0.03, "Validating modality descriptors and current history")

                if "mri" in manifest: cls._verifyMRIInventory(manifest, archive)
                if "mne" in manifest: cls._verifyMNEInventory(manifest, archive)

                _, historyMetadata = cls._readSessionHistory(archive, len(manifest["runs"]))

                if manifest["runs"]:
                    metadata = cls._behaviorLabelMetadata(manifest, archive)
                    if historyMetadata != metadata:
                        raise ValueError("Current history labels differ from uploaded behavioral settings.")
                else:
                    if historyMetadata is None:
                        raise ValueError("New modality-only checkpoints require explicit session-label metadata.")
                    metadata = historyMetadata

            finally:
                archive.close()

            cls._recordSessionLabelMetadata(connection, postgres, sessionID, metadata)

            subjectsByRun = {
                run["path"]: metadata["labels"][run["index"]]["subjectID"]
                for run in manifest["runs"]
            }
            modalitySubject = metadata["labels"][0]["subjectID"] if not manifest["runs"] else None
            derivedByPath = {record["path"]: record for record in manifest.get("derivedFiles", [])}

            def fileOwner(name):
                """Assign roles and subjects from current logical ownership."""
                if name == "manifest.json": return "manifest", None
                if name == "history.json": return "history", None

                if name in derivedByPath:
                    runIndex = derivedByPath[name]["runIndex"]
                    subjectID = None if runIndex is None else subjectsByRun[manifest["runs"][runIndex]["path"]]
                    return "derived", subjectID

                if ("mri" in manifest and name.startswith("mri/")) or ("mne" in manifest and name.startswith("mne/")):
                    return "derived", modalitySubject

                runRoot = "/".join(name.split("/")[:2])
                if runRoot not in subjectsByRun:
                    raise ValueError(f"Checkpoint file has no declared owner: {name!r}")

                return "derived", subjectsByRun[runRoot]

            ################################################################
            # Attach reused identities; verify/register newly uploaded bytes
            ################################################################
            records = [
                *manifest["files"],
                {"name": "manifest.json", **manifestIdentity},
            ]

            # Metadata-only reuse receives small weight rather than pretending
            # its full payload size will be transferred or verified.
            work = [
                {
                    "name": record["name"],
                    "size_bytes": 1 if record["name"] in reusedFiles else max(1, record["size_bytes"]),
                    "record": record,
                }
                for record in records
            ]
            fileRange = progress.section(0.05, 1) if progress is not None else None

            for item, fileProgress in pglProgress.fileSections(work, fileRange):
                record = item["record"]
                name = record["name"]
                role, subjectID = fileOwner(name)

                if name in reusedFiles:
                    fileID = reusedFiles[name]["fileID"]
                    if fileProgress is not None:
                        fileProgress(0, "Attaching existing registered content")
                else:
                    if fileProgress is not None:
                        fileProgress(0, "Resolving newly uploaded content")

                    fileID = cls.getOrCreateFile(
                        connection,
                        postgres,
                        record["sha256"],
                        record["size_bytes"],
                    )
                    cls.verifyAndRegisterStorageLocation(
                        connection,
                        postgres,
                        fileID,
                        backendID,
                        posixpath.join(objectPrefix, name),
                        accessContext=accessContext,
                        progress=fileProgress,
                    )

                cls.attachCheckpointFile(
                    connection,
                    postgres,
                    sessionID,
                    name,
                    fileID,
                    role=role,
                    subjectID=subjectID,
                )

                if fileProgress is not None:
                    fileProgress(1, "Checkpoint file link registered")

        return sessionID

    # ++++++++++++++++++++ _completeSessionBundleCheckpoint +++++++++++++++++++
    # Direct callers in this module: _saveRawMNECheckpoint, completeDerivedCheckpoint.
    @classmethod
    def _completeSessionBundleCheckpoint(cls, connection, postgres, sessionID, manifest, *, origin="derived"):
        """Validate registered contents and complete a raw/derived checkpoint.

        Checks:
            Checkpoint origin, contract, status, and lineage.
            Exact registered file identities and roles.
            Eligible verified file locations on active backends.
            Exact named matrix revisions and active matrix backends.

        V1 manifests imply no attached products.
        Derived v2 manifests explicitly declare products, including an empty
        collection.

        Uses recorded verification metadata, not a fresh payload-byte scan.

        Opens a transaction/savepoint. The caller's outer transaction must
        commit for publication to persist. Does not mutate working objects.
        """
        if type(sessionID) is not int or not 0 <= sessionID <= 9223372036854775807:
            raise ValueError("sessionID must be a nonnegative PostgreSQL bigint.")

        cls._validateSessionBundleManifest(manifest, origin=origin)

        productRecords = manifest.get("products", [])
        payloadRole = "acquisition" if origin == "raw" else "derived"
        manifestBytes = cls.encodeRawManifest(manifest)
        manifestHash = hashlib.sha256(manifestBytes).hexdigest()

        expected = {
            record["name"]: (
                record["sha256"],
                record["size_bytes"],
                "history" if record["name"] == "history.json" else payloadRole,
            )
            for record in manifest["files"]
        }
        expected["manifest.json"] = (manifestHash, len(manifestBytes), "manifest")

        sessions = sql.Identifier(postgres.databaseSchema, "session")
        links = sql.Identifier(postgres.databaseSchema, "session_files")
        files = sql.Identifier(postgres.databaseSchema, "files")
        locations = sql.Identifier(postgres.databaseSchema, "storage_locations")
        backends = sql.Identifier(postgres.databaseSchema, "storage_backends")

        with connection.transaction():
            # Product-link changes also lock this owner row. Holding this
            # lock makes link verification and completion one serialized step.
            statement = sql.SQL("""
                SELECT origin, status, contract_version, deleted_at,
                       parent_session_id, root_session_id
                FROM {}
                WHERE session_id = %s
                FOR UPDATE
            """).format(sessions)

            checkpoint = connection.execute(statement, (sessionID,)).fetchone()

            if checkpoint is None or checkpoint[:4] != (origin, "in_progress", manifest["contract_version"], None):
                raise ValueError("Checkpoint must be active, in progress, and match the manifest origin and contract.")

            parentID, rootID = checkpoint[4:]

            if origin == "raw":
                if parentID is not None or rootID != sessionID:
                    raise ValueError("A raw checkpoint must be parentless and its own root.")
            else:
                statement = sql.SQL("SELECT status, deleted_at, root_session_id FROM {} WHERE session_id = %s FOR SHARE").format(sessions)
                parent = connection.execute(statement, (parentID,)).fetchone()

                if parent != ("complete", None, rootID):
                    raise ValueError("Parent must be complete, active, and have the same root.")

            statement = sql.SQL("""
                SELECT link.name,
                       content.sha256,
                       content.size_bytes,
                       link.role,
                       (
                           link.deleted_at IS NULL
                           AND content.deleted_at IS NULL
                           AND EXISTS (
                               SELECT 1
                               FROM {} AS location
                               JOIN {} AS backend
                                 ON backend.backend_id = location.backend_id
                               WHERE location.file_id = content.file_id
                                 AND location.deleted_at IS NULL
                                 AND location.status = 'present'
                                 AND location.verified_at IS NOT NULL
                                 AND backend.is_active
                           )
                       ) AS available
                FROM {} AS link
                JOIN {} AS content ON content.file_id = link.file_id
                WHERE link.session_id = %s
                ORDER BY link.name
            """).format(locations, backends, links, files)

            rows = connection.execute(statement, (sessionID,)).fetchall()
            actual = {name: (digest, size, role) for name, digest, size, role, available in rows}

            if actual != expected:
                raise ValueError("Checkpoint file links do not exactly match the manifest identities and roles.")

            unavailable = [name for name, digest, size, role, available in rows if not available]

            if unavailable:
                raise ValueError("Files lack active links, content identities, or verified active storage locations: " + ", ".join(unavailable))

            # Always verify, including an empty collection. Otherwise an old
            # manifest could conceal additional database product links.
            cls._verifySessionProducts(connection, postgres, sessionID, productRecords)

            statement = sql.SQL("""
                UPDATE {}
                SET status = 'complete',
                    manifest_hash = %s,
                    completed_at = now()
                WHERE session_id = %s
            """).format(sessions)

            connection.execute(statement, (manifestHash, sessionID))

        return manifestHash

    @classmethod
    def _publishedMatrixRecords(cls, session, records):
        """Add explicit ownership to freshly published MRI matrix references.

        records:
            Catalog-key/revision pairs produced by _publishSessionMatrices().

        MRI sessions:
            Return owner-aware records for the MRI-v2 manifest.

        Other sessions:
            Preserve the existing two-field record format.

        Validates exact attachment coverage. Does not modify matrix identities,
        working attachments, supplied records, or SQL rows.
        """
        catalogRecords = cls._validateSessionProductRecords(records)
        bindings = cls._sessionMatrixBindings(session)

        if {record["name"] for record in catalogRecords} != set(bindings):
            raise ValueError("Published matrix references do not match current attachments.")

        if session.mri is None:
            return catalogRecords

        ownedRecords = []

        for record in catalogRecords:
            ownerName, localName, _ = bindings[record["name"]]
            ownedRecords.append({
                "name": record["name"],
                "owner": ownerName,
                "localName": localName,
                "matrixRevisionID": record["matrixRevisionID"],
            })

        return cls._validateOwnedMatrixRecords(ownedRecords)

    @classmethod
    def _validateMatrixRecordsForSession(cls, session, records):
        """Validate publication records against their working attachment owners.

        The session's modality determines the output contract:
            MRI present: owner-aware MRI-v2 records.
            Otherwise: existing legacy records.

        Never infer working ownership from an arbitrary product-name prefix.
        Requires exact coverage of current attachments.

        Does not verify payload bytes or query whether revisions are registered.
        """
        hasMRI = session.mri is not None
        validated = (
            cls._validateOwnedMatrixRecords(records)
            if hasMRI else
            cls._validateSessionProductRecords(records)
        )
        bindings = cls._sessionMatrixBindings(session)

        if {record["name"] for record in validated} != set(bindings):
            raise ValueError("Matrix revision references do not exactly match current attachments.")

        if hasMRI:
            for record in validated:
                ownerName, localName, _ = bindings[record["name"]]
                if record["owner"] != ownerName or record["localName"] != localName:
                    raise ValueError("Published matrix ownership differs from the working attachment.")

        return validated

    # -------------------------------------------------------------------------
    # Session matrix products
    # -------------------------------------------------------------------------
    # Snapshot attachments, publish revisions, register links, and restore exact manifest-declared
    # products.

    # ++++++++++++++++++++++++ _snapshotSessionMatrices +++++++++++++++++++++++
    # Direct callers in this module: _saveDerivedSession, saveDerivedSessionFiles.
    @classmethod
    def _sessionMatrixBindings(cls, session):
        """Describe matrix ownership without reading scientific array values.

        Without MRI:
            Preserve legacy literal session attachment names as catalog keys.

        With MRI:
            Use canonical owner/localName keys for BOTH owners, matching the
            MRI-v2 manifest contract.

        Returns:
            catalogKey -> (ownerName, localName, matrix)

        Matrix objects are not copied. Does not attach, publish, or compute.
        """
        from .pglData import pglDataMatrix

        hasMRI = session.mri is not None
        owners = [("session", session.dataMatrices)]
        if hasMRI: owners.append(("mri", session.mri.dataMatrices))

        bindings = {}

        for ownerName, matrices in owners:
            if not isinstance(matrices, dict):
                raise TypeError(f"{ownerName}.dataMatrices must be a dictionary.")

            for localName, matrix in matrices.items():
                # Reuse name validation even when retaining legacy catalog keys.
                ownedKey = cls._matrixAttachmentKey(ownerName, localName)

                if not isinstance(matrix, pglDataMatrix):
                    raise TypeError(f"{ownerName} matrix {localName!r} must be a pglDataMatrix.")

                catalogKey = ownedKey if hasMRI else localName
                if catalogKey in bindings:
                    raise ValueError(f"Duplicate matrix catalog key: {catalogKey!r}.")

                bindings[catalogKey] = (ownerName, localName, matrix)

        return {key: bindings[key] for key in sorted(bindings)}

    @classmethod
    def _snapshotSessionMatrices(cls, session):
        """Snapshot all retained session and MRI matrix attachments.

        Returns a deterministic catalog-key -> matrix dictionary.
        Matrix objects are not copied or computed.

        MRI checkpoints use owner-aware catalog keys for both collections.
        Non-MRI checkpoints preserve their existing literal attachment names.

        Array encoding and safe-save checks remain the publisher's responsibility.
        """
        bindings = cls._sessionMatrixBindings(session)
        return {key: binding[2] for key, binding in bindings.items()}

    @classmethod
    def _requireSessionMatricesUnchanged(cls, session, products):
        """Reject attachment-name, ownership-key, or object-identity changes.

        Does not compare numerical contents or detect arbitrary in-place
        mutation of exposed arrays. Concurrent mutation remains unsupported.

        The enclosing checkpoint coordinator also checks modality collection
        identity and other working-session metadata.
        """
        current = cls._snapshotSessionMatrices(session)

        if set(current) != set(products):
            raise ValueError("Session/MRI matrix attachments changed while saving.")

        for catalogKey, matrix in products.items():
            if current[catalogKey] is not matrix:
                raise ValueError(f"Matrix attachment {catalogKey!r} was replaced while saving.")
    
    # ++++++++++++++++++++++++ _publishSessionMatrices ++++++++++++++++++++++++
    # Direct callers in this module: _saveDerivedSession.
    @classmethod
    def _publishSessionMatrices(cls, connection, postgres, session, products, *, createdBy, backendID, filesystem, destinationRoot, progress=None):
        """Publish working matrices and register revisions in caller transaction.

        products must be a snapshot from _snapshotSessionMatrices().
        Optional progress reports product-level publication and registration.

        Zarr writes do not currently expose byte-level progress here.
        Does not mutate working matrix revision IDs or session attachments.
        Failed publication may leave unregistered matrix bundles.
        """
        from psycopg.types.json import Jsonb

        for label, value in (("createdBy", createdBy), ("backendID", backendID)):
            if type(value) is not int or not 0 <= value <= 9223372036854775807:
                raise ValueError(f"{label} must be a nonnegative PostgreSQL bigint.")

        cls._requireSessionMatricesUnchanged(session, products)

        for productName, matrix in products.items():
            pglStorage.requireSafeSave(matrix)
            pglStorage.validateDataMatrixEncoding(matrix.requireData())

        if not products:
            if progress is not None:
                progress(1, "No attached matrices to publish")

            return []

        backends = sql.Identifier(postgres.databaseSchema, "storage_backends")
        revisions = sql.Identifier(postgres.databaseSchema, "matrix_revisions")
        statement = sql.SQL("SELECT is_active FROM {} WHERE backend_id = %s FOR SHARE").format(backends)

        if connection.execute(statement, (backendID,)).fetchone() != (True,):
            raise ValueError("Matrix destination backend is missing or inactive.")

        productRoot = posixpath.join(destinationRoot, "matrices")
        records = []
        productCount = len(products)

        for index, (productName, matrix) in enumerate(products.items()):
            cls._requireSessionMatricesUnchanged(session, products)

            if progress is not None:
                progress(index / productCount, f"Publishing matrix {index + 1}/{productCount}: {productName}")

            savedURL = pglStorage.saveDataMatrix(matrix, productRoot, filesystem=filesystem)
            savedPath = filesystem._strip_protocol(savedURL)
            descriptorPath = posixpath.join(savedPath, "matrix.json")

            if progress is not None:
                progress(None, f"Checking published matrix descriptor: {productName}")

            with filesystem.open(descriptorPath, "rb") as source:
                descriptorBytes = source.read(16 * 1024 * 1024 + 1)

            if len(descriptorBytes) > 16 * 1024 * 1024:
                raise ValueError("Published matrix descriptor exceeds the metadata size limit.")

            descriptor = json.loads(descriptorBytes)
            revisionID = descriptor["matrixRevisionID"]

            if descriptor["contractVersion"] != "pgl.matrix.zarr.v1":
                raise ValueError("Published matrix has an unsupported persistence contract.")

            objectKey = f"matrices/matrix-{revisionID}"
            expectedPath = posixpath.join(destinationRoot, objectKey)

            if posixpath.normpath(savedPath) != posixpath.normpath(expectedPath):
                raise ValueError("Published matrix path differs from its expected backend-relative location.")

            if progress is not None:
                progress(None, f"Registering matrix revision: {productName}")

            statement = sql.SQL("""
                INSERT INTO {} (
                    matrix_revision_id, backend_id, object_key,
                    contract_version, descriptor, created_by
                )
                VALUES (%s::uuid, %s, %s, %s, %s, %s)
            """).format(revisions)

            connection.execute(statement, (revisionID, backendID, objectKey, "pgl.matrix.zarr.v1", Jsonb(descriptor), createdBy))
            records.append({"name": productName, "matrixRevisionID": revisionID})

            if progress is not None:
                progress((index + 1) / productCount, f"Matrix registered: {productName}")

        cls._requireSessionMatricesUnchanged(session, products)

        for matrix in products.values():
            pglStorage.requireSafeSave(matrix)

        return cls._publishedMatrixRecords(session, records)
    
    @classmethod
    def _validatedMatrixLinks(cls, records):
        """Validate either complete record format and return SQL link records.

        This helper is for low-level catalog registration, verification, and
        loading. It does not select a checkpoint contract or install owners.

        Accepts:
            A homogeneous list of legacy two-field records.
            A homogeneous list of explicit owner-aware records.
            An empty list.

        Mixed, partial, and unknown record formats are rejected.

        Manifest validation must separately enforce the format allowed by its
        version. Legacy names remain literal even if they resemble encoded keys.
        """
        if type(records) is not list:
            raise ValueError("Matrix records must be a list.")
        if not records: return []

        if any(type(record) is not dict for record in records):
            raise ValueError("Each matrix record must be a dictionary.")

        legacyFields = {"name", "matrixRevisionID"}
        ownedFields = {"name", "owner", "localName", "matrixRevisionID"}

        if all(set(record) == legacyFields for record in records):
            return cls._matrixCatalogRecords(records, owned=False)

        if all(set(record) == ownedFields for record in records):
            return cls._matrixCatalogRecords(records, owned=True)

        raise ValueError("Matrix records contain mixed, partial, or unsupported record formats.")

    # ++++++++++++++++++++++++ _registerSessionProducts +++++++++++++++++++++++
    # Direct callers in this module: _saveDerivedSession.
    @classmethod
    def _registerSessionProducts(cls, connection, postgres, sessionID, records):
        """Attach already-registered matrix revisions to an unpublished session.

        Writes database links only. Does not publish payloads or complete the
        checkpoint. Requires an initially empty product-link collection.

        Uses a savepoint so partial link insertion rolls back on failure.
        The enclosing session-save transaction must commit for links to persist.
        """
        if type(sessionID) is not int or not 0 <= sessionID <= 9223372036854775807:
            raise ValueError("sessionID must be a nonnegative PostgreSQL bigint.")

        records = cls._validatedMatrixLinks(records)
        sessions = sql.Identifier(postgres.databaseSchema, "session")
        products = sql.Identifier(postgres.databaseSchema, "session_products")

        with connection.transaction():
            # Serialize attachment registration against checkpoint completion.
            statement = sql.SQL("SELECT status, deleted_at FROM {} WHERE session_id = %s FOR UPDATE").format(sessions)
            owner = connection.execute(statement, (sessionID,)).fetchone()

            if owner != ("in_progress", None):
                raise ValueError("Session products require an active in_progress checkpoint.")

            statement = sql.SQL("SELECT 1 FROM {} WHERE session_id = %s LIMIT 1").format(products)

            if connection.execute(statement, (sessionID,)).fetchone() is not None:
                raise ValueError("Session products have already been registered.")

            statement = sql.SQL("""
                INSERT INTO {} (session_id, product_name, matrix_revision_id)
                VALUES (%s, %s, %s::uuid)
            """).format(products)

            for record in records:
                connection.execute(statement, (sessionID, record["name"], record["matrixRevisionID"]))

            cls._verifySessionProducts(connection, postgres, sessionID, records)

    # +++++++++++++++++++++++++ _verifySessionProducts ++++++++++++++++++++++++
    # Direct callers in this module: _completeSessionBundleCheckpoint, _loadSessionProducts,
    # _registerSessionProducts, _saveDerivedSession, loadSession.
    @classmethod
    def _verifySessionProducts(cls, connection, postgres, sessionID, records):
        """Verify exact session product links and registered matrix availability.

        Uses the caller's transaction. Checks catalog metadata and backend
        status, not payload bytes or scientific values.

        An empty expected list still checks for unexpected database links.
        This is important when loading old manifests or removing attachments.
        """
        if type(sessionID) is not int or not 0 <= sessionID <= 9223372036854775807:
            raise ValueError("sessionID must be a nonnegative PostgreSQL bigint.")

        records = cls._validatedMatrixLinks(records)
        products = sql.Identifier(postgres.databaseSchema, "session_products")
        revisions = sql.Identifier(postgres.databaseSchema, "matrix_revisions")
        backends = sql.Identifier(postgres.databaseSchema, "storage_backends")

        statement = sql.SQL("""
            SELECT product.product_name,
                   product.matrix_revision_id::text,
                   revision.contract_version,
                   backend.is_active
            FROM {} AS product
            JOIN {} AS revision
              ON revision.matrix_revision_id = product.matrix_revision_id
            JOIN {} AS backend
              ON backend.backend_id = revision.backend_id
            WHERE product.session_id = %s
        """).format(products, revisions, backends)

        rows = connection.execute(statement, (sessionID,)).fetchall()
        expected = {record["name"]: record["matrixRevisionID"] for record in records}
        actual = {name: revisionID for name, revisionID, contractVersion, isActive in rows}

        if actual != expected:
            raise ValueError("Session product links do not exactly match the manifest's named matrix revisions.")

        for name, revisionID, contractVersion, isActive in rows:
            if contractVersion != "pgl.matrix.zarr.v1":
                raise ValueError(f"Session product {name!r} has an unsupported matrix contract.")

            if not isActive:
                raise ValueError(f"Session product {name!r} has an inactive storage backend.")

    # +++++++++++++++++++++++++ _openRegisteredMatrix ++++++++++++++++++++++++
    @classmethod
    def _openRegisteredMatrix(cls, postgres, *, revisionID, backendID, objectKey, contractVersion, descriptor, registeredRoot, storageOptionsByBackend=None):
        """Open a catalog-resolved matrix and retain its payload access.

        Called by database product loaders after querying the revision and
        checking that its backend is active.

        Owns a separate access context for this matrix. Reads matrix.json,
        checks it against the catalog descriptor, then delegates standalone
        Zarr restoration to pglStorage.

        Returns:
            A pglDataMatrix whose scientific variables remain lazy.
            Its xarray close callback releases both the underlying reader
            and this matrix's owned access context.

        No SQL connection is opened or retained. The caller supplies catalog
        metadata from its own database lookup.

        Reads descriptor/Zarr metadata, not a complete scientific-value scan.
        Does not publish records, change registered paths, or mutate a dataset
        or session attachment collection.

        On failure, closes all resources created here.
        Call matrix.close() after its deferred readers are no longer needed.
        Derived xarray views must not outlive their source matrix's resources.
        """
        from uuid import UUID

        if not isinstance(revisionID, str):
            raise ValueError("Matrix revision ID must be a canonical UUID string.")

        try:
            canonicalID = str(UUID(revisionID))
        except (ValueError, AttributeError) as error:
            raise ValueError("Invalid matrix revision UUID.") from error

        if revisionID != canonicalID:
            raise ValueError("Matrix revision ID must use canonical UUID formatting.")

        if type(backendID) is not int or not 0 <= backendID <= 9223372036854775807:
            raise ValueError("backendID must be a nonnegative PostgreSQL bigint.")

        if contractVersion != "pgl.matrix.zarr.v1":
            raise ValueError("Unsupported registered matrix contract.")

        if not isinstance(descriptor, dict):
            raise ValueError("Registered matrix descriptor must be a JSON object.")

        if not isinstance(objectKey, str) or objectKey.startswith("/") or "\\" in objectKey or "\x00" in objectKey or any(part in {"", ".", ".."} for part in objectKey.split("/")):
            raise ValueError("Registered matrix has an invalid relative object key.")

        access = pglDatabaseAccess(postgres, storageOptionsByBackend)
        matrix = None

        try:
            filesystem, root = access.resolve(backendID, registeredRoot)
            bundlePath = posixpath.join(root, objectKey)
            maxBytes = 16 * 1024 * 1024

            with filesystem.open(posixpath.join(bundlePath, "matrix.json"), "rb") as source:
                descriptorBytes = source.read(maxBytes + 1)

            if len(descriptorBytes) > maxBytes:
                raise ValueError("Matrix descriptor exceeds the metadata size limit.")

            storedDescriptor = json.loads(descriptorBytes)

            if cls.encodeRawManifest(storedDescriptor) != cls.encodeRawManifest(descriptor):
                raise ValueError("Published matrix descriptor differs from its registered metadata.")

            matrix = pglStorage.loadDataMatrix(bundlePath, filesystem=filesystem)

            if matrix.matrixRevisionID != revisionID:
                raise ValueError("Loaded matrix revision differs from its registered identity.")

            data = matrix.requireData()

            # xarray exposes set_close(), but not a public callback getter.
            # Capture its existing callback before replacing it. Capturing
            # data.close instead would recurse after set_close() is called.
            if not hasattr(data, "_close"):
                raise RuntimeError("This xarray version does not expose the close callback needed to retain database payload access.")

            originalClose = data._close

            if originalClose is not None and not callable(originalClose):
                raise RuntimeError("The restored xarray close callback is invalid.")

            closed = False

            # +++++++++++++++++++++++ closePayload ++++++++++++++++++++++++++
            def closePayload():
                """Release the Zarr reader before its owned access context."""
                nonlocal closed

                if closed:
                    return

                closed = True

                try:
                    if originalClose is not None:
                        originalClose()
                finally:
                    access.close()

            data.set_close(closePayload)
            return matrix

        except BaseException:
            try:
                if matrix is not None:
                    try:
                        matrix.close()
                    except Exception:
                        # Preserve the original loading/validation error.
                        pass
            finally:
                access.close()

            raise

    # ++++++++++++++++++++++++++ _loadSessionProducts ++++++++++++++++++++++++
    @classmethod
    def _loadSessionProducts(cls, connection, postgres, sessionID, records, *, storageOptionsByBackend=None):
        """Restore exact manifest-declared session matrix attachments.

        Called by _loadSessionBundle() after manifest validation.
        Uses the caller's SQL transaction for catalog lookup and product-link
        verification.

        Each product is opened through _openRegisteredMatrix(), which resolves
        server-local roots using the caller's local/SSH access context and
        retains its own resources for deferred array reads.

        Returns:
            A dictionary mapping product names to working pglDataMatrix objects.

        Reads catalog rows, publication descriptors, and Zarr metadata.
        Does not extract behavior, compute scientific arrays, or publish data.
        Returned matrices retain payload readers, not the SQL connection.

        On failure, closes every matrix opened by this call.
        On success, the caller owns the returned matrices and must close them
        once their deferred readers are no longer needed.
        """
        records = cls._validatedMatrixLinks(records)
        cls._verifySessionProducts(connection, postgres, sessionID, records)

        if not records:
            return {}

        productsTable = sql.Identifier(postgres.databaseSchema, "session_products")
        revisionsTable = sql.Identifier(postgres.databaseSchema, "matrix_revisions")
        backendsTable = sql.Identifier(postgres.databaseSchema, "storage_backends")

        statement = sql.SQL("""
            SELECT product.product_name,
                   revision.matrix_revision_id::text,
                   revision.backend_id,
                   revision.object_key,
                   revision.contract_version,
                   revision.descriptor,
                   backend.url_prefix,
                   backend.is_active
            FROM {} AS product
            JOIN {} AS revision
              ON revision.matrix_revision_id = product.matrix_revision_id
            JOIN {} AS backend
              ON backend.backend_id = revision.backend_id
            WHERE product.session_id = %s
        """).format(productsTable, revisionsTable, backendsTable)

        rows = connection.execute(statement, (sessionID,)).fetchall()
        catalog = {row[0]: row[1:] for row in rows}
        restored = {}

        try:
            for record in records:
                productName = record["name"]
                revisionID, backendID, objectKey, contractVersion, descriptor, registeredRoot, isActive = catalog[productName]

                if revisionID != record["matrixRevisionID"]:
                    raise ValueError(f"Session product {productName!r} differs from its manifest revision.")

                if not isActive:
                    raise ValueError(f"Session product {productName!r} has an inactive backend.")

                matrix = cls._openRegisteredMatrix(postgres, revisionID=revisionID, backendID=backendID, objectKey=objectKey, contractVersion=contractVersion, descriptor=descriptor, registeredRoot=registeredRoot, storageOptionsByBackend=storageOptionsByBackend)
                restored[productName] = matrix

            return restored

        except BaseException:
            for matrix in restored.values():
                try:
                    matrix.close()
                except Exception:
                    pass

            raise

    # +++++++++++++++++++++ _validateSessionProductRecords ++++++++++++++++++++
    # Direct callers in this module: _loadSessionProducts, _registerSessionProducts,
    # _verifySessionProducts, saveDerivedSessionFiles, validateDerivedManifest.
    @staticmethod
    def _validateSessionProductRecords(records):
        """Validate named matrix references intended for a session manifest.

        Records must be sorted by case-sensitive product name.
        Revision IDs must be canonical UUID strings.

        Returns an independent list of normalized dictionaries.
        Does not read arrays, access storage, or mutate the input.
        """
        from uuid import UUID

        if not isinstance(records, list):
            raise ValueError("Session product records must be a list.")

        validated = []

        for index, record in enumerate(records):
            if not isinstance(record, dict) or set(record) != {"name", "matrixRevisionID"}:
                raise ValueError(f"Session product {index}: invalid record fields.")

            name = record["name"]

            if not isinstance(name, str) or not name.strip():
                raise ValueError(f"Session product {index}: name must be a nonblank string.")

            if any(character in name for character in ("\x00", "\n", "\r")):
                raise ValueError(f"Session product {index}: invalid name characters.")

            revisionID = record["matrixRevisionID"]

            if not isinstance(revisionID, str):
                raise ValueError(f"Session product {name!r}: revision ID must be a string.")

            try:
                canonicalID = str(UUID(revisionID))
            except (ValueError, AttributeError) as error:
                raise ValueError(f"Session product {name!r}: invalid revision UUID.") from error

            if revisionID != canonicalID:
                raise ValueError(f"Session product {name!r}: revision UUID must use canonical formatting.")

            validated.append({"name": name, "matrixRevisionID": revisionID})

        names = [record["name"] for record in validated]

        if names != sorted(set(names)):
            raise ValueError("Session product names must be unique and sorted.")

        return validated
    
    @staticmethod
    def _matrixAttachmentKey(owner, localName):
        """Return a canonical catalog key for an explicitly owned matrix.

        Ownership is supplied separately, never inferred from a user name.

        JSON tuple encoding avoids separator collisions while allowing the
        same local name under session and MRI owners. This key is not a path.

        Legacy matrix names must never be decoded using this convention.
        Only owner-aware manifest records use these keys.
        """
        import json

        if owner not in ("session", "mri"):
            raise ValueError("Matrix owner must be 'session' or 'mri'.")

        if not isinstance(localName, str) or not localName.strip():
            raise ValueError("Matrix localName must be a nonblank string.")
        if any(character in localName for character in ("\x00", "\n", "\r")):
            raise ValueError("Matrix localName must not contain NUL or newline characters.")

        return json.dumps([owner, localName], ensure_ascii=False, separators=(",", ":"))

    @classmethod
    def _validateOwnedMatrixRecords(cls, records):
        """Validate MRI-v2 matrix ownership records without reading arrays.

        Each record contains:
            name: Canonical catalog key, derived from owner and localName.
            owner: "session" or "mri".
            localName: Dictionary key under that owner.
            matrixRevisionID: Published matrix revision UUID.

        Records must be sorted by canonical catalog key. Owner/local-name
        pairs must be unique; different owners may use the same local name.

        Does not accept or reinterpret legacy records. The enclosing manifest
        version determines which validator applies.

        Returns independent records. Does not mutate the input, access SQL,
        open Zarr metadata, or assign matrices to working objects.
        """
        if type(records) is not list:
            raise ValueError("Owned matrix records must be a list.")

        validated = []
        catalogRecords = []
        expectedFields = {"name", "owner", "localName", "matrixRevisionID"}

        for index, record in enumerate(records):
            if type(record) is not dict or set(record) != expectedFields:
                raise ValueError(f"Owned matrix {index}: invalid record fields.")

            owner = record["owner"]
            localName = record["localName"]
            expectedKey = cls._matrixAttachmentKey(owner, localName)

            if record["name"] != expectedKey:
                raise ValueError(
                    f"Owned matrix {index}: catalog key disagrees with "
                    "its explicit owner and localName."
                )

            # Reuse existing UUID, ordering, and catalog-name validation.
            catalogRecords.append({
                "name": expectedKey,
                "matrixRevisionID": record["matrixRevisionID"],
            })
            validated.append({
                "name": expectedKey,
                "owner": owner,
                "localName": localName,
                "matrixRevisionID": record["matrixRevisionID"],
            })

        cls._validateSessionProductRecords(catalogRecords)
        return validated
    
    @classmethod
    def _installOwnedSessionMatrices(cls, session, matrices, records):
        """Install already-open matrices under their explicit manifest owners.

        matrices maps canonical catalog keys to opened pglDataMatrix objects.
        records must be owner-aware records from a validated MRI-v2 manifest.

        Validate every destination before assigning either dictionary.
        Requires empty destination collections; never merges or overwrites.

        Does not open, compute, copy, close, or delete matrix payloads.
        The enclosing loader owns cleanup if installation fails.

        Trait observers may raise during assignment. This helper does not
        claim transactional rollback of arbitrary observer side effects;
        installation belongs on a newly reconstructed, unpublished session.
        """
        from .pglData import pglDataMatrix

        records = cls._validateOwnedMatrixRecords(records)

        if type(matrices) is not dict:
            raise TypeError("Restored matrices must be a dictionary.")

        expectedKeys = {record["name"] for record in records}
        if set(matrices) != expectedKeys:
            raise ValueError("Restored matrix keys differ from the ownership manifest.")

        if not isinstance(session.dataMatrices, dict) or session.dataMatrices:
            raise ValueError("Matrix restoration requires an empty session.dataMatrices.")

        mri = session.mri
        if mri is None:
            raise ValueError("MRI-v2 matrix restoration requires an MRI collection.")
        if not isinstance(mri.dataMatrices, dict) or mri.dataMatrices:
            raise ValueError("Matrix restoration requires an empty MRI dataMatrices collection.")

        sessionMatrices = {}
        mriMatrices = {}

        for record in records:
            matrix = matrices[record["name"]]
            if not isinstance(matrix, pglDataMatrix):
                raise TypeError(f"Restored matrix {record['name']!r} is not a pglDataMatrix.")
            if matrix.matrixRevisionID != record["matrixRevisionID"]:
                raise ValueError(f"Restored matrix {record['name']!r} has the wrong revision.")

            destination = sessionMatrices if record["owner"] == "session" else mriMatrices
            destination[record["localName"]] = matrix

        # Matrix identity and display name remain unchanged. The manifest's
        # localName is the attachment key, not a request to rename the matrix.
        session.dataMatrices = sessionMatrices
        mri.dataMatrices = mriMatrices


    # -------------------------------------------------------------------------
    # Checkpoint history and acquisition labels
    # -------------------------------------------------------------------------
    # Encode and restore checkpoint history wrappers, validate labels, and mirror verified labels
    # into SQL.

    # ++++++++++++++++++++++++++ _sessionHistoryBytes +++++++++++++++++++++++++
    # Direct callers in this module: saveDerivedSessionFiles, saveRawSessionFiles.
    ################################################################
    # Encode checkpoint history, labels, and derived correspondence
    ################################################################
    @classmethod
    def _sessionHistoryBytes(cls, session, *, acquisition=False):
        """Encode history and explicit session metadata after safety checks.

        Derived exports include configured scan/run correspondence.
        Raw exports omit it because it is derived analysis metadata.

        Runtime failure state is not serialized.
        Correspondence is validated against current acquisition identities.
        Does not modify scientific data or publish files.
        """
        from .pglPipeline import pglActionable

        if type(acquisition) is not bool:
            raise TypeError("acquisition must be Boolean.")

        pglStorage.requireSafeSave(session)

        labels = {
            "version": 1,
            "labels": session.getSessionLabels(acquisition=acquisition),
        }
        cls._validateSessionLabelMetadata(labels, runCount=len(session.runs or []))

        correspondence = None
        if not acquisition and session.scanRunCorrespondence is not None:
            correspondence = session._validateScanRunCorrespondence(session.scanRunCorrespondence)
            session._resolveScanRunCorrespondence(correspondence)

        # Retain the existing history representation and its action products.
        history = pglActionable()
        history.uuid = session.uuid
        history.actionHistory = list(session.actionHistory)
        document = json.loads(history.toJSON())

        reserved = {"pgl_session_labels", "pgl_scan_run_correspondence"}
        if reserved.intersection(document):
            raise ValueError("History wrapper contains a reserved session metadata field.")

        document["pgl_session_labels"] = labels

        # Absence means unset; an explicit empty pair list remains configured.
        if correspondence is not None:
            document["pgl_scan_run_correspondence"] = correspondence

        return json.dumps(document, sort_keys=True, indent=4).encode("utf-8")

    ################################################################
    # Restore checkpoint history and explicit session metadata
    ################################################################
    @classmethod
    def _readSessionHistory(cls, filesystem, runCount):
        """Restore history and labels without resolving scientific payloads.

        Supports older files without labels or scan/run correspondence.

        Returns the existing (history, labels) tuple.
        Validated correspondence is carried temporarily on
        history._checkpointScanRunCorrespondence for session reconstruction.

        Only correspondence structure is checked here. The session loader
        must resolve its endpoints after restoring runs and MRI scans.
        """
        from .pglPipeline import pglActionable
        from .pglSession import pglSession

        def uniqueKeys(pairs):
            result = {}
            for key, value in pairs:
                if key in result: raise ValueError(f"Duplicate checkpoint-history key: {key!r}")
                result[key] = value
            return result

        with filesystem.open("history.json", "rt", encoding="utf-8") as source:
            document = json.load(source, object_pairs_hook=uniqueKeys)

        if not isinstance(document, dict):
            raise ValueError("Checkpoint history must contain a JSON object.")

        hasLabels = "pgl_session_labels" in document
        labels = document.pop("pgl_session_labels", None)
        if hasLabels:
            cls._validateSessionLabelMetadata(labels, runCount=runCount)

        hasCorrespondence = "pgl_scan_run_correspondence" in document
        correspondence = document.pop("pgl_scan_run_correspondence", None)
        if hasCorrespondence:
            # Explicit null is not a correspondence record. Unset is encoded
            # by omitting the field, preserving compatibility with old files.
            correspondence = pglSession._validateScanRunCorrespondence(correspondence)

        history = pglActionable.fromJSON(json.dumps(document), filename="history.json")
        if type(history) is not pglActionable:
            raise ValueError("Checkpoint history must contain a pglActionable wrapper.")

        if json.loads(history.toJSON()) != document:
            raise ValueError("Checkpoint history could not be reconstructed without changes.")

        # Install runtime transport metadata only after the serialization
        # round-trip check. This is not an action or a replay instruction.
        history._checkpointScanRunCorrespondence = correspondence
        return history, labels

    # +++++++++++++++++++++++++ _behaviorLabelMetadata ++++++++++++++++++++++++
    # Direct callers in this module: _registerSessionBundleFiles, registerStagedRawCheckpoint,
    # saveDerivedSessionFiles, saveRawSessionFiles.
    @classmethod
    def _behaviorLabelMetadata(cls, manifest, filesystem):
        """Read label pairs from verified archived behavioral experiment settings."""
        from .pglSession import pglSession

        labels = []

        for runRecord in manifest["runs"]:
            path = posixpath.join(runRecord["path"], "experimentSettings.json")

            with filesystem.open(path, "rt", encoding="utf-8") as source:
                settings = json.load(source)

            if not isinstance(settings, dict):
                raise ValueError(f"Experiment settings must contain a JSON object: {path}")

            labels.append({
                "runIndex": runRecord["index"],
                "experimentName": pglSession._normalizeSessionLabel(settings.get("experimentName"), f"{path}: experimentName"),
                "subjectID": pglSession._normalizeSessionLabel(settings.get("subjectID"), f"{path}: subjectID"),
            })

        if not labels:
            raise ValueError("Behavioral label extraction requires at least one run.")

        metadata = {"version": 1, "labels": labels}
        return cls._validateSessionLabelMetadata(metadata, runCount=len(manifest["runs"]))

    # +++++++++++++++++++++ _validateSessionLabelMetadata +++++++++++++++++++++
    # Direct callers in this module: _behaviorLabelMetadata, _readSessionHistory,
    # _recordSessionLabelMetadata, _sessionHistoryBytes, getDatasetMemberSummaries, printSessions.
    @staticmethod
    def _validateSessionLabelMetadata(metadata, runCount=None):
        """Validate the versioned experiment/subject metadata record."""
        from .pglSession import pglSession

        if not isinstance(metadata, dict) or set(metadata) != {"version", "labels"}:
            raise ValueError("Invalid session-label metadata fields.")

        if type(metadata["version"]) is not int or metadata["version"] != 1:
            raise ValueError("Unsupported session-label metadata version.")

        labels = metadata["labels"]

        if not isinstance(labels, list) or not labels:
            raise ValueError("Session-label metadata must contain a nonempty labels list.")

        indices = []

        for record in labels:
            if not isinstance(record, dict) or set(record) != {"runIndex", "experimentName", "subjectID"}:
                raise ValueError("Invalid session-label record.")

            index = record["runIndex"]

            if index is not None and (type(index) is not int or index < 0):
                raise ValueError("Invalid session-label run index.")

            indices.append(index)

            for name in ("experimentName", "subjectID"):
                normalized = pglSession._normalizeSessionLabel(record[name], name)

                if normalized != record[name]:
                    raise ValueError(f"Session-label {name} must use None for an unset value.")

        if indices != [None] and indices != list(range(len(labels))):
            raise ValueError("Session-label run indices must be consecutive, or a single None for a session without runs.")

        if runCount is not None:
            expected = list(range(runCount)) if runCount else [None]

            if indices != expected:
                raise ValueError("Session-label metadata does not match the behavioral run inventory.")

        return metadata

    # ++++++++++++++++++++++ _recordSessionLabelMetadata ++++++++++++++++++++++
    # Direct callers in this module: _registerSessionBundleFiles, registerStagedRawCheckpoint.
    @classmethod
    def _recordSessionLabelMetadata(cls, connection, postgres, sessionID, metadata):
        """Mirror verified payload labels into an active in-progress checkpoint."""
        from psycopg.types.json import Jsonb

        cls._validateSessionLabelMetadata(metadata)
        subjects = sorted({record["subjectID"] for record in metadata["labels"] if record["subjectID"] is not None})

        for subjectID in subjects:
            cls.getOrCreateSubject(connection, postgres, subjectID)

        table = sql.Identifier(postgres.databaseSchema, "session")
        statement = sql.SQL("UPDATE {} SET meta = COALESCE(meta, '{{}}'::jsonb) || %s::jsonb WHERE session_id = %s AND status = 'in_progress' AND deleted_at IS NULL RETURNING session_id").format(table)
        row = connection.execute(statement, (Jsonb({"pgl_session_labels": metadata}), sessionID)).fetchone()

        if row is None:
            raise ValueError("Session labels can only be recorded on an active in-progress checkpoint.")


    # -------------------------------------------------------------------------
    # Checkpoint manifest contracts and inventory verification
    # -------------------------------------------------------------------------
    # Shared checkpoint-format rules used during export, registration, loading, and logical
    # filesystem construction.

    # +++++++++++++++++++++++++++ encodeRawManifest +++++++++++++++++++++++++++
    # Direct callers in this module: _completeSessionBundleCheckpoint,
    # _getCheckpointHistoryBoundary, _loadSessionBundle, _loadSessionProducts,
    # _prepareCheckpointBaseline, _readReplayCheckpointHistory, _registerSessionBundleFiles,
    # _saveDerivedSession, _saveRawMNECheckpoint, completeRawCheckpoint, getDatasetData,
    # getRawFileLocations, getSessionPipeline, hashRawManifest, loadRawManifest,
    # registerStagedRawCheckpoint, saveRawSessionFiles, stageDerivedManifest, stageRawManifest.
    @classmethod
    def encodeRawManifest(cls, manifest):
        """Encode a checkpoint manifest deterministically as UTF-8 JSON.

        Shared by checkpoint hashing, publication, loading, and metadata
        comparisons. Does not validate the manifest or access storage.

        Delegates generic JSON encoding to pglStorage. The compact,
        sorted-key UTF-8 representation is unchanged from existing manifests.
        """
        return pglStorage.encodeJSON(manifest)

    # ++++++++++++++++++++++++++++ hashRawManifest ++++++++++++++++++++++++++++
    # Direct callers in this module: _saveRawSession.
    @classmethod
    def hashRawManifest(cls, manifest):
        """Return the SHA-256 of the exact encoded manifest bytes."""
        return hashlib.sha256(cls.encodeRawManifest(manifest)).hexdigest()

    # ++++++++++++++++++++++++++ validateRawManifest ++++++++++++++++++++++++++
    # Direct callers in this module: _saveRawSession, completeRawCheckpoint, getRawFileLocations,
    # loadRawManifest, pglCheckpointFilesystem, readRawSubjects, registerStagedRawCheckpoint,
    # stageRawManifest, stageRawSession.
    @classmethod
    def validateRawManifest(cls, manifest):
        """Validate the raw behavioral manifest contract."""
        return cls._validateBehaviorManifest(manifest, "pgl.raw.behavior.v1")

    # +++++++++++++++++++++++ validateRawSessionManifest ++++++++++++++++++++++
    # Direct callers in this module: _validateSessionBundleManifest, pglCheckpointFilesystem,
    # saveRawSessionFiles.
    @classmethod
    def validateRawSessionManifest(cls, manifest):
        """Validate raw session contracts without changing their identity.

        V1 retains its MNE-required inventory.
        V2 explicitly supports the five agreed acquisition combinations.
        """
        if not isinstance(manifest, dict):
            raise ValueError("Manifest must be a dictionary.")

        contract = manifest.get("contract_version")
        if contract == "pgl.raw.session.v2":
            return cls.validateRawSessionV2Manifest(manifest)

        if contract != "pgl.raw.session.v1":
            raise ValueError("Unsupported raw session contract.")

        # Preserve the original v1 validation exactly.
        validationView = dict(manifest)
        validationView["contract_version"] = "pgl.derived.session.v1"
        cls.validateDerivedSessionManifest(validationView)
        return manifest
    
    @classmethod
    def validateRawSessionV2Manifest(cls, manifest):
        """Validate a raw v2 inventory without reading payloads.

        Supports behavior alone, MNE alone, MRI alone, and either modality
        with behavior. Empty sessions and combined MNE/MRI are unsupported.

        Existing v1 contracts remain unchanged.
        Inner modality descriptors are verified separately.
        """
        import posixpath
        import re

        required = {"contract_version", "runs", "directories", "files"}
        if not isinstance(manifest, dict):
            raise ValueError("Raw v2 manifest must be a dictionary.")

        if not required.issubset(manifest) or set(manifest) - required - {"mne", "mri"}:
            raise ValueError("Raw v2 manifest has missing or unexpected fields.")

        if manifest["contract_version"] != "pgl.raw.session.v2":
            raise ValueError("Unsupported raw v2 contract.")

        for field in ("runs", "directories", "files"):
            if not isinstance(manifest[field], list):
                raise ValueError(f"Manifest {field} must be a list.")

        modalities = [name for name in ("mne", "mri") if name in manifest]
        if len(modalities) > 1:
            raise ValueError("Combined MNE/MRI raw checkpoints are not supported.")
        if not modalities and not manifest["runs"]:
            raise ValueError("A raw checkpoint must contain acquisition contents.")

        for name in modalities:
            if manifest[name] != {"path": name}:
                raise ValueError(f"{name.upper()} bundle path must be {name!r}.")

        runPaths = set()
        for index, record in enumerate(manifest["runs"]):
            if not isinstance(record, dict) or set(record) != {"index", "path"}:
                raise ValueError("Invalid behavioral run record.")

            expectedPath = f"runs/{index:06d}"
            if type(record["index"]) is not int or record["index"] != index:
                raise ValueError("Run indices must be consecutive and ordered.")
            if record["path"] != expectedPath:
                raise ValueError(f"Run path must be {expectedPath!r}.")

            runPaths.add(expectedPath)

        def validatePath(path):
            if (
                not isinstance(path, str)
                or not path
                or path.startswith("/")
                or "\\" in path
                or "\x00" in path
                or any(part in ("", ".", "..") for part in path.split("/"))
            ):
                raise ValueError(f"Invalid manifest path: {path!r}")

        directories = manifest["directories"]
        for path in directories: validatePath(path)
        if directories != sorted(set(directories)):
            raise ValueError("Manifest directories must be unique and sorted.")

        fileNames = []
        for record in manifest["files"]:
            if not isinstance(record, dict) or set(record) != {"name", "sha256", "size_bytes"}:
                raise ValueError("Invalid manifest file record.")

            validatePath(record["name"])
            if not isinstance(record["sha256"], str) or re.fullmatch(r"[0-9a-f]{64}", record["sha256"]) is None:
                raise ValueError("Invalid manifest SHA-256.")
            if type(record["size_bytes"]) is not int or not 0 <= record["size_bytes"] <= 9223372036854775807:
                raise ValueError("Invalid manifest file size.")

            fileNames.append(record["name"])

        if fileNames != sorted(set(fileNames)):
            raise ValueError("Manifest filenames must be unique and sorted.")

        directorySet = set(directories)
        fileSet = set(fileNames)
        if directorySet.intersection(fileSet):
            raise ValueError("A manifest path cannot be both a file and directory.")

        requiredDirectories = set(modalities)
        if runPaths: requiredDirectories.update({"runs", *runPaths})
        if not requiredDirectories.issubset(directorySet):
            raise ValueError("Missing required acquisition directories.")

        requiredFiles = {"history.json"}
        requiredFiles.update(f"{name}/{name}.json" for name in modalities)
        if not requiredFiles.issubset(fileSet):
            raise ValueError("Missing history or modality descriptor.")

        for path in directories + fileNames:
            parent = posixpath.dirname(path)
            if parent and parent not in directorySet:
                raise ValueError(f"Missing parent directory for {path!r}.")

            if path == "history.json" and path in fileSet: continue
            if path in modalities and path in directorySet: continue
            if path == "runs" and runPaths and path in directorySet: continue
            if any(path.startswith(name + "/") for name in modalities): continue

            owningRun = "/".join(path.split("/")[:2])
            if owningRun not in runPaths:
                raise ValueError(f"Path lies outside declared acquisition contents: {path!r}")

        for runPath in runPaths:
            if not any(name.startswith(runPath + "/") for name in fileNames):
                raise ValueError(f"Behavioral run contains no files: {runPath}")

        return manifest

    # ++++++++++++++++++++++++ validateDerivedManifest ++++++++++++++++++++++++
    # Direct callers in this module: _validateSessionBundleManifest, pglCheckpointFilesystem,
    # saveDerivedSessionFiles, stageDerivedManifest.
    ################################################################
    # Validate derived checkpoint manifests
    ################################################################
    @classmethod
    def validateDerivedManifest(cls, manifest):
        """Validate derived behavioral/MNE and MRI checkpoint inventories.

        Existing contracts:
            V1: Behavioral/MNE inventory.
            V2: Adds explicit matrix-product references.
            V3: Adds explicit derived-file attachments.

        MRI contract:
            pgl.derived.mri.v1 includes MRI, optional behavior, matrix
            references, and derived-file attachments.
            pgl.derived.mri.v2 adds explicit matrix owner/localName fields.

        Does not read payloads, mutate the manifest, or establish scientific
        validity. Inner modality descriptors are verified separately.
        """
        import posixpath
        import re

        if not isinstance(manifest, dict):
            raise ValueError("Manifest must be a dictionary.")

        contract = manifest.get("contract_version")
        if contract == "pgl.derived.mri.v2":
            return cls._validateDerivedMRIV2Manifest(manifest)
        if contract == "pgl.derived.mri.v1":
            return cls._validateDerivedMRIManifest(manifest)
        
        v2Contracts = {
            "pgl.derived.behavior.v2": "pgl.derived.behavior.v1",
            "pgl.derived.session.v2": "pgl.derived.session.v1",
        }
        v3Contracts = {
            "pgl.derived.behavior.v3": "pgl.derived.behavior.v1",
            "pgl.derived.session.v3": "pgl.derived.session.v1",
        }

        if contract in v3Contracts:
            expectedFields = {
                "contract_version", "runs", "directories", "files",
                "products", "derivedFiles",
            }
            if contract == "pgl.derived.session.v3": expectedFields.add("mne")
            if set(manifest) != expectedFields:
                raise ValueError("Derived v3 manifest has missing or unexpected fields.")

            for field in ("runs", "directories", "files", "derivedFiles"):
                if not isinstance(manifest[field], list):
                    raise ValueError(f"Manifest {field} must be a list.")

            cls._validateSessionProductRecords(manifest["products"])

            # Validate the entire inventory before separating attachments.
            # Otherwise removing attachment entries could conceal duplicates,
            # malformed identities, or invalid ordering.
            directories = manifest["directories"]
            fileRecords = manifest["files"]

            def validatePath(path):
                if (
                    not isinstance(path, str) or not path
                    or path.startswith("/") or "\\" in path or "\x00" in path
                    or any(part in ("", ".", "..") for part in path.split("/"))
                ):
                    raise ValueError(f"Invalid manifest path: {path!r}")

            for path in directories: validatePath(path)
            if directories != sorted(set(directories)):
                raise ValueError("Directories must be unique and sorted.")

            fileNames = []

            for record in fileRecords:
                if not isinstance(record, dict) or set(record) != {"name", "sha256", "size_bytes"}:
                    raise ValueError("File record has missing or unexpected fields.")

                validatePath(record["name"])
                if not isinstance(record["sha256"], str) or re.fullmatch(r"[0-9a-f]{64}", record["sha256"]) is None:
                    raise ValueError("Invalid file SHA-256.")
                if type(record["size_bytes"]) is not int or not 0 <= record["size_bytes"] <= 9223372036854775807:
                    raise ValueError("Invalid file size.")

                fileNames.append(record["name"])

            if fileNames != sorted(set(fileNames)):
                raise ValueError("File names must be unique and sorted.")

            directorySet, fileSet = set(directories), set(fileNames)
            if directorySet.intersection(fileSet):
                raise ValueError("A path cannot be both a file and a directory.")

            for path in directories + fileNames:
                parent = posixpath.dirname(path)
                if parent and parent not in directorySet:
                    raise ValueError(f"Missing parent directory for {path!r}.")

            attachments = manifest["derivedFiles"]
            attachmentNames = []
            expectedPayloads = set()
            expectedDirectories = {"derived"} if attachments else set()

            for index, attachment in enumerate(attachments):
                expectedAttachmentFields = {
                    "name", "runIndex", "filename", "mediaType", "path",
                }
                if not isinstance(attachment, dict) or set(attachment) != expectedAttachmentFields:
                    raise ValueError("Derived-file record has missing or unexpected fields.")

                name = attachment["name"]
                if not isinstance(name, str) or not name.strip():
                    raise ValueError("Derived-file name must be a nonblank string.")
                if any(character in name for character in ("\x00", "\n", "\r")):
                    raise ValueError("Invalid derived-file name.")
                attachmentNames.append(name)

                runIndex = attachment["runIndex"]
                if runIndex is not None:
                    if type(runIndex) is not int or not 0 <= runIndex < len(manifest["runs"]):
                        raise ValueError("Invalid derived-file runIndex.")

                filename = attachment["filename"]
                if (
                    not isinstance(filename, str) or not filename.strip()
                    or filename in (".", "..")
                    or any(character in filename for character in ("/", "\\", "\x00", "\n", "\r"))
                ):
                    raise ValueError("Derived filename must be a single safe filename.")

                mediaType = attachment["mediaType"]
                if not isinstance(mediaType, str) or not mediaType.strip():
                    raise ValueError("Derived mediaType must be a nonblank string.")
                if any(character in mediaType for character in ("\x00", "\n", "\r")):
                    raise ValueError("Invalid derived mediaType.")

                # Deterministic directories follow sorted logical names.
                # Separate directories permit identical filenames on different
                # attachments without collision.
                root = f"derived/f{index:06d}"
                expectedPath = f"{root}/{filename}"
                if attachment["path"] != expectedPath:
                    raise ValueError(f"Derived-file path must be {expectedPath!r}.")

                expectedDirectories.add(root)
                expectedPayloads.add(expectedPath)

            if attachmentNames != sorted(set(attachmentNames)):
                raise ValueError("Derived-file names must be unique and sorted.")

            actualPayloads = {
                path for path in fileSet
                if path == "derived" or path.startswith("derived/")
            }
            actualDirectories = {
                path for path in directorySet
                if path == "derived" or path.startswith("derived/")
            }

            if actualPayloads != expectedPayloads:
                raise ValueError("Derived-file declarations do not exactly match attachment payloads.")
            if actualDirectories != expectedDirectories:
                raise ValueError("Derived-file declarations do not exactly match attachment directories.")

            # Validate remaining content using the unchanged v1 inventory
            # rules. Only new containers are constructed; source data stays
            # unchanged.
            inventoryManifest = {
                key: value for key, value in manifest.items()
                if key not in ("products", "derivedFiles")
            }
            inventoryManifest["contract_version"] = v3Contracts[contract]
            inventoryManifest["directories"] = [
                path for path in directories if path not in expectedDirectories
            ]
            inventoryManifest["files"] = [
                record for record in fileRecords if record["name"] not in expectedPayloads
            ]

        elif contract in v2Contracts:
            if "products" not in manifest:
                raise ValueError("Derived v2 manifest requires a products list.")

            cls._validateSessionProductRecords(manifest["products"])

            # Preserve the existing v2-to-v1 structural validation.
            inventoryManifest = dict(manifest)
            inventoryManifest.pop("products")
            inventoryManifest["contract_version"] = v2Contracts[contract]

        elif contract in ("pgl.derived.behavior.v1", "pgl.derived.session.v1"):
            inventoryManifest = manifest

        else:
            raise ValueError(f"Unsupported derived manifest contract: {contract!r}")

        if inventoryManifest["contract_version"] == "pgl.derived.session.v1":
            cls.validateDerivedSessionManifest(inventoryManifest)
        else:
            cls._validateBehaviorManifest(inventoryManifest, "pgl.derived.behavior.v1")
            if "history.json" not in {record["name"] for record in inventoryManifest["files"]}:
                raise ValueError("Derived manifest is missing history.json.")

        return manifest

    # +++++++++++++++++++++ validateDerivedSessionManifest ++++++++++++++++++++
    # Direct callers in this module: validateDerivedManifest, validateRawSessionManifest.
    @staticmethod
    def validateDerivedSessionManifest(manifest):
        """Validate a derived session inventory containing an MNE bundle."""

        # +++++++++++++++++++++++++++++ requireFields +++++++++++++++++++++++++++++
        # Local implementation within validateDerivedSessionManifest.
        def requireFields(value, names, label):
            if not isinstance(value, dict) or set(value) != set(names):
                raise ValueError(f"{label} has missing or unexpected fields")

        # ++++++++++++++++++++++++++++++ validatePath +++++++++++++++++++++++++++++
        # Local implementation within validateDerivedSessionManifest.
        def validatePath(path):
            if (
                not isinstance(path, str)
                or not path
                or path.startswith("/")
                or "\\" in path
                or "\x00" in path
                or any(part in ("", ".", "..") for part in path.split("/"))
            ):
                raise ValueError(f"Invalid manifest path: {path!r}")

        requireFields(
            manifest,
            {"contract_version", "runs", "mne", "directories", "files"},
            "Manifest",
        )
        if manifest["contract_version"] != "pgl.derived.session.v1":
            raise ValueError("Unsupported derived session contract")

        for name in ("runs", "directories", "files"):
            if not isinstance(manifest[name], list):
                raise ValueError(f"Manifest {name} must be a list")

        requireFields(manifest["mne"], {"path"}, "MNE record")
        if manifest["mne"]["path"] != "mne":
            raise ValueError("MNE bundle path must be 'mne'")

        runPaths = set()
        for index, record in enumerate(manifest["runs"]):
            requireFields(record, {"index", "path"}, "Run record")
            if type(record["index"]) is not int or record["index"] != index:
                raise ValueError("Run indices must be consecutive and ordered")

            expectedPath = f"runs/{index:06d}"
            if record["path"] != expectedPath:
                raise ValueError(f"Run path must be {expectedPath!r}")
            runPaths.add(expectedPath)

        directories = manifest["directories"]
        for path in directories: validatePath(path)
        if directories != sorted(set(directories)):
            raise ValueError("Directories must be unique and sorted")

        directorySet = set(directories)
        requiredDirectories = {"mne"}
        if runPaths: requiredDirectories.update({"runs", *runPaths})
        if not requiredDirectories.issubset(directorySet):
            raise ValueError("Missing required bundle directories")

        fileNames = []
        for record in manifest["files"]:
            requireFields(record, {"name", "sha256", "size_bytes"}, "File record")
            validatePath(record["name"])

            digest = record["sha256"]
            size = record["size_bytes"]
            if not isinstance(digest, str) or re.fullmatch(r"[0-9a-f]{64}", digest) is None:
                raise ValueError("File SHA256 must be 64 lowercase hexadecimal characters")
            if type(size) is not int or not 0 <= size <= 9223372036854775807:
                raise ValueError("File size must be a nonnegative PostgreSQL bigint")

            fileNames.append(record["name"])

        if fileNames != sorted(set(fileNames)):
            raise ValueError("File names must be unique and sorted")
        if directorySet.intersection(fileNames):
            raise ValueError("A path cannot be both a file and a directory")
        if not {"history.json", "mne/mne.json"}.issubset(fileNames):
            raise ValueError("Missing history.json or mne/mne.json")

        for path in directories + fileNames:
            if path in ("runs", "mne"):
                if path not in directorySet:
                    raise ValueError(f"Expected a directory: {path}")
                continue

            if path == "history.json":
                if path not in fileNames:
                    raise ValueError("history.json must be a file")
                continue

            if posixpath.dirname(path) not in directorySet:
                raise ValueError(f"Missing parent directory for {path!r}")

            if path.startswith("mne/"): continue

            owningRun = "/".join(path.split("/")[:2])
            if owningRun not in runPaths:
                raise ValueError(f"Path lies outside declared bundles: {path!r}")

        for runPath in runPaths:
            if not any(name.startswith(runPath + "/") for name in fileNames):
                raise ValueError(f"Run contains no files: {runPath}")

        return manifest

    # +++++++++++++++++++++ _validateSessionBundleManifest ++++++++++++++++++++
    # Direct callers in this module: _completeSessionBundleCheckpoint, _loadSessionBundle,
    # _readReplayCheckpointHistory, _reconstructSessionBundle, _registerSessionBundleFiles.
    @classmethod
    def _validateSessionBundleManifest(cls, manifest, *, origin):
        if origin == "raw":
            return cls.validateRawSessionManifest(manifest)
        if origin == "derived":
            return cls.validateDerivedManifest(manifest)
        raise ValueError(f"Unsupported bundle origin: {origin!r}")

    # +++++++++++++++++++++++ _validateBehaviorManifest +++++++++++++++++++++++
    # Direct callers in this module: validateDerivedManifest, validateRawManifest.
    @staticmethod
    def _validateBehaviorManifest(manifest, contractVersion):
        """Validate the v1 manifest structure without accessing payloads."""

        # +++++++++++++++++++++++++++++ requireFields +++++++++++++++++++++++++++++
        # Local implementation within _validateBehaviorManifest.
        def requireFields(value, fields, label):
            if not isinstance(value, dict) or set(value) != set(fields):
                raise ValueError(f"{label} has missing or unexpected fields.")

        # ++++++++++++++++++++++++++++++ validatePath +++++++++++++++++++++++++++++
        # Local implementation within _validateBehaviorManifest.
        def validatePath(path):
            if (
                not isinstance(path, str)
                or path.startswith("/")
                or "\\" in path
                or "\x00" in path
            ):
                raise ValueError(f"Invalid manifest path: {path!r}")

            if any(part in {"", ".", ".."} for part in path.split("/")):
                raise ValueError(f"Invalid manifest path: {path!r}")

        requireFields(
            manifest,
            {"contract_version", "runs", "directories", "files"},
            "Manifest",
        )

        if manifest["contract_version"] != contractVersion:
            raise ValueError("Unsupported manifest contract.")

        for field in ("runs", "directories", "files"):
            if not isinstance(manifest[field], list):
                raise ValueError(f"Manifest {field} must be a list.")

        if not manifest["runs"]:
            raise ValueError("Manifest must contain at least one run.")

        runPaths = set()

        for index, record in enumerate(manifest["runs"]):
            requireFields(record, {"index", "path"}, "Run record")

            if type(record["index"]) is not int or record["index"] != index:
                raise ValueError(
                    "Run indices must be consecutive and ordered from zero."
                )

            expectedPath = f"runs/{index:06d}"

            if record["path"] != expectedPath:
                raise ValueError(f"Run path must be {expectedPath!r}.")

            runPaths.add(expectedPath)

        directories = manifest["directories"]

        for path in directories:
            validatePath(path)

        if directories != sorted(set(directories)):
            raise ValueError("Directories must be unique and sorted.")

        directorySet = set(directories)

        if not {"runs", *runPaths}.issubset(directorySet):
            raise ValueError("Manifest is missing required run directories.")

        fileNames = []

        for record in manifest["files"]:
            requireFields(
                record,
                {"name", "sha256", "size_bytes"},
                "File record",
            )
            validatePath(record["name"])

            digest = record["sha256"]
            size = record["size_bytes"]

            if (
                not isinstance(digest, str)
                or re.fullmatch(r"[0-9a-f]{64}", digest) is None
            ):
                raise ValueError(
                    "File SHA-256 must contain 64 lowercase hexadecimal characters."
                )

            if type(size) is not int or not 0 <= size <= 9223372036854775807:
                raise ValueError(
                    "File size must be a nonnegative PostgreSQL bigint."
                )

            fileNames.append(record["name"])

        if fileNames != sorted(set(fileNames)):
            raise ValueError("File names must be unique and sorted.")

        if directorySet.intersection(fileNames):
            raise ValueError(
                "A manifest path cannot be both a file and a directory."
            )

        for path in directories + fileNames:
            if path == "runs":
                continue

            # Only derived checkpoints permit this session-level file.
            if (
                contractVersion == "pgl.derived.behavior.v1"
                and path == "history.json"
                and path in fileNames
            ):
                continue

            if posixpath.dirname(path) not in directorySet:
                raise ValueError(f"Missing parent directory for {path!r}.")

            owningRun = "/".join(path.split("/")[:2])

            if owningRun not in runPaths:
                raise ValueError(
                    f"Path lies outside the declared runs: {path!r}"
                )

        for runPath in runPaths:
            if not any(name.startswith(runPath + "/") for name in fileNames):
                raise ValueError(f"Run contains no files: {runPath}")

        return manifest

    # ++++++++++++++++++++++++++ _verifyMNEInventory ++++++++++++++++++++++++++
    # Direct callers in this module: _reconstructSessionBundle, _registerSessionBundleFiles,
    # saveDerivedSessionFiles, saveRawSessionFiles.
    @classmethod
    def _verifyMNEInventory(cls, manifest, filesystem):
        """Verify MNE descriptor references against the outer file inventory."""
        from .pglSession import pglMNEBundle

        mneRoot = manifest["mne"]["path"]
        descriptorPath = posixpath.join(mneRoot, "mne.json")
        inventory = {record["name"]: record for record in manifest["files"]}
        descriptorRecord = inventory[descriptorPath]

        maxBytes = 16 * 1024 * 1024
        if descriptorRecord["size_bytes"] > maxBytes:
            raise ValueError("MNE descriptor exceeds size limit")

        with filesystem.open(descriptorPath, "rb") as source:
            content = source.read(descriptorRecord["size_bytes"] + 1)

        if (
            len(content) != descriptorRecord["size_bytes"]
            or hashlib.sha256(content).hexdigest() != descriptorRecord["sha256"]
        ):
            raise ValueError("MNE descriptor identity mismatch")

        descriptor = json.loads(content)
        pglMNEBundle._validateDescriptor(descriptor)

        expected = {}
        for resource in descriptor["resources"].values():
            for record in resource["files"]:
                name = posixpath.join(mneRoot, resource["root"], record["name"])
                if name in expected: raise ValueError(f"Duplicate MNE payload reference: {name}")
                expected[name] = (record["sha256"], record["size_bytes"])

        actual = {
            name: (record["sha256"], record["size_bytes"])
            for name, record in inventory.items()
            if name.startswith(mneRoot + "/") and name != descriptorPath
        }

        if actual != expected:
            raise ValueError("MNE descriptor payloads do not exactly match checkpoint inventory")

        return descriptor

    # ++++++++++++++++++++++++++ _verifyMRIInventory ++++++++++++++++++++++++++
    ################################################################
    # Verify MRI descriptor and original-source payload references
    ################################################################
    @classmethod
    def _verifyMRIInventory(cls, manifest, filesystem, *, maxDescriptorBytes=64 * 1024 * 1024):
        """Verify MRI metadata against the outer checkpoint inventory.

        Raw MRI checkpoints require pgl.mri.acquisition.v1.
        Derived MRI checkpoints require pgl.mri.derived.v1.

        Both describe original acquisition payloads. Processed image products
        live in the session's separate derived-file attachment inventory.

        Reads the MRI descriptor only, not NIfTI payloads.
        The caller must validate the outer manifest first.

        Checks descriptor bytes, inner structure, and exact acquisition
        payload correspondence. Does not reconstruct scans or modify metadata.
        """
        import hashlib
        import json
        import posixpath

        from .pglMRI import pglMRIBundle

        if type(maxDescriptorBytes) is not int or maxDescriptorBytes <= 0:
            raise ValueError("maxDescriptorBytes must be a positive integer.")

        if manifest.get("mri") != {"path": "mri"}:
            raise ValueError("Missing or invalid MRI bundle declaration.")

        outerContract = manifest.get("contract_version")
        if outerContract == "pgl.raw.session.v2":
            expectedInnerContract = pglMRIBundle.contract
            validator = pglMRIBundle.validateDescriptor
        elif outerContract in ("pgl.derived.mri.v1", "pgl.derived.mri.v2"):
            expectedInnerContract = "pgl.mri.derived.v1"
            validator = pglMRIBundle.validateDerivedDescriptor
        else:
            raise ValueError(f"Unsupported MRI checkpoint contract: {outerContract!r}")

        inventory = {record["name"]: record for record in manifest["files"]}
        descriptorPath = "mri/mri.json"
        identity = inventory.get(descriptorPath)
        if identity is None:
            raise ValueError("MRI descriptor is absent from the checkpoint inventory.")

        size = identity["size_bytes"]
        if type(size) is not int or not 0 <= size <= maxDescriptorBytes:
            raise ValueError("MRI descriptor size is invalid or exceeds the limit.")

        with filesystem.open(descriptorPath, "rb") as source:
            content = source.read(size + 1)

        if len(content) != size or hashlib.sha256(content).hexdigest() != identity["sha256"]:
            raise ValueError("MRI descriptor identity mismatch.")

        def uniqueKeys(pairs):
            result = {}
            for key, value in pairs:
                if key in result: raise ValueError(f"Duplicate MRI descriptor key: {key!r}")
                result[key] = value
            return result

        def rejectConstant(value):
            raise ValueError(f"Nonfinite MRI descriptor JSON constant: {value}")

        descriptor = json.loads(
            content,
            object_pairs_hook=uniqueKeys,
            parse_constant=rejectConstant,
        )
        if type(descriptor) is not dict or descriptor.get("contract") != expectedInnerContract:
            raise ValueError("MRI descriptor contract disagrees with its enclosing checkpoint.")

        validator(descriptor)

        expected = {}

        for scan in descriptor["scans"]:
            name = posixpath.join("mri", scan["path"])
            if name in expected: raise ValueError("Duplicate MRI acquisition payload reference.")
            expected[name] = (scan["sha256"], scan["size_bytes"])

        actual = {
            name: (record["sha256"], record["size_bytes"])
            for name, record in inventory.items()
            if name.startswith("mri/") and name != descriptorPath
        }

        if actual != expected:
            raise ValueError("MRI descriptor acquisition payloads do not exactly match the checkpoint inventory.")

        return descriptor
    # -------------------------------------------------------------------------
    # Dataset configuration, history, and publication validation
    # -------------------------------------------------------------------------
    # Resolve dataset binding and prepare lightweight metadata without embedding scientific
    # products.

    # +++++++++++++++++++++++++ _resolveDatasetStorage ++++++++++++++++++++++++
    # Direct callers in this module: getDatasetBehaviorData, getDatasetData,
    # getDatasetMemberSummaries, getDatasetSession, loadDataset, saveDataset.
    @classmethod
    def _resolveDatasetStorage(cls, dataset, *, settings=None, settingsName=None):
        """Resolve configuration and reject a different bound database.

        The binding is a runtime endpoint descriptor, not a globally portable
        database UUID. Credentials and settings are never serialized.
        """
        from .pglDataset import pglDataset
        from .pglPostgres import pglPostgres

        if not isinstance(dataset, pglDataset):
            raise TypeError("Expected a pglDataset.")

        if settings is not None and settingsName is not None:
            raise ValueError("Supply settings or settingsName, not both.")

        if settings is None and settingsName is None:
            settings = dataset._datasetSettings
            settingsName = dataset._datasetSettingsName if settings is None else None

        resolvedSettings = cls.getSettings(settings=settings, settingsName=settingsName)

        if resolvedSettings is None:
            return None, None

        postgres = pglPostgres.fromSettings(settings=resolvedSettings)

        if postgres is None:
            return None, None

        identity = cls._checkpointDatabaseIdentity(postgres)

        if dataset._datasetDatabaseIdentity and dataset._datasetDatabaseIdentity != identity:
            raise ValueError("The selected database differs from this dataset's bound database. Dataset membership cannot be resolved against another database.")

        return resolvedSettings, postgres

    # ++++++++++++++++++++++++++ _bindDatasetStorage ++++++++++++++++++++++++++
    # Direct callers in this module: getDatasetBehaviorData, getDatasetData,
    # getDatasetMemberSummaries, getDatasetSession, loadDataset.
    @classmethod
    def _bindDatasetStorage(cls, dataset, resolvedSettings, postgres):
        """Install runtime configuration after successful metadata access."""
        dataset._datasetDatabaseIdentity = deepcopy(cls._checkpointDatabaseIdentity(postgres))
        dataset._datasetSettings = resolvedSettings
        dataset._datasetSettingsName = None

    # ++++++++++++++++++++++ _datasetDatabaseIdentityJSON +++++++++++++++++++++
    # Direct callers in this module: getDatasetData, loadDataset, saveDataset.
    @staticmethod
    def _datasetDatabaseIdentityJSON(identity):
        """Canonical runtime database identity for reference comparisons."""
        return json.dumps(identity, sort_keys=True, separators=(",", ":"), allow_nan=False)

    # +++++++++++++++++++++ _requireSafeDatasetCheckpoint +++++++++++++++++++++
    # Direct callers in this module: _prepareDatasetMetadata, getDatasetBehaviorData, saveDataset.
    @classmethod
    def _requireSafeDatasetCheckpoint(cls, dataset):
        """Validate failure bookkeeping, history prefix, and family identity."""
        from .pglDataset import pglDataset

        if not isinstance(dataset, pglDataset):
            raise TypeError("Expected a pglDataset.")

        pglStorage.requireSafeSave(dataset)

        baseline = dataset._datasetBaseline

        if not baseline:
            return

        expectedFields = {"version", "datasetID", "familyUUID", "databaseIdentity", "historyHashes"}

        if set(baseline) != expectedFields or type(baseline["version"]) is not int or baseline["version"] != 1:
            raise ValueError("Invalid dataset checkpoint baseline.")

        if dataset.datasetID != baseline["datasetID"]:
            raise ValueError("Dataset ID differs from its saved baseline.")

        if dataset.uuid != baseline["familyUUID"]:
            raise ValueError("Dataset family UUID differs from its saved baseline.")

        if dataset._datasetDatabaseIdentity != baseline["databaseIdentity"]:
            raise ValueError("Dataset database binding differs from its saved baseline.")

        expectedHashes = baseline["historyHashes"]

        if not isinstance(expectedHashes, list):
            raise ValueError("Invalid dataset history baseline.")

        actualHashes = cls._datasetHistoryHashes(dataset)

        if len(actualHashes) < len(expectedHashes) or actualHashes[:len(expectedHashes)] != expectedHashes:
            raise ValueError("Saved dataset history was shortened or edited. Historical entries must remain unchanged; append new analyses instead.")

    # +++++++++++++++++++++++++ _datasetHistoryHashes +++++++++++++++++++++++++
    # Direct callers in this module: _requireSafeDatasetCheckpoint, loadDataset, saveDataset.
    @staticmethod
    def _datasetHistoryHashes(dataset):
        """Fingerprint history metadata without touching scientific products."""
        return [hashlib.sha256(entry.toJSON(strict=True).encode("utf-8")).hexdigest() for entry in dataset.actionHistory]

    # ++++++++++++++++++++++++ _prepareDatasetMetadata ++++++++++++++++++++++++
    # Direct callers in this module: saveDataset.
    @classmethod
    def _prepareDatasetMetadata(cls, dataset):
        """Strictly encode lightweight metadata without embedding products.

        Membership lives in dataset_members.
        Product links live in dataset_products.
        Editable annotations live in dataset columns.
        """
        from uuid import UUID
        from .pglDataset import pglDataset
        from .pglSerialize import pglSerialize

        cls._requireSafeDatasetCheckpoint(dataset)
        dataset._validateName(dataset.name)
        dataset._validateMembers(dataset.members)
        cls._validateDatasetProducts(dataset)

        familyUUID = dataset.uuid
        _ = dataset.pglVersion
        _ = dataset.github

        try:
            parsedUUID = UUID(familyUUID)
        except (TypeError, ValueError, AttributeError) as error:
            raise ValueError("Dataset uuid must be a valid UUID string.") from error

        if str(parsedUUID) != familyUUID:
            raise ValueError("Dataset uuid must use canonical lowercase UUID formatting.")

        text = dataset.toJSON(strict=True)
        restored = pglSerialize.fromJSON(text, strict=True)

        if type(restored) is not pglDataset:
            raise TypeError("Dataset metadata must restore as an exact pglDataset.")

        if restored.data:
            raise ValueError("Dataset metadata must not embed scientific products.")

        if restored.toJSON(strict=True) != text:
            raise ValueError("Dataset metadata did not round-trip exactly.")

        return json.loads(text)

    # +++++++++++++++++++++++++++ _datasetAnnotation ++++++++++++++++++++++++++
    # Direct callers in this module: saveDataset.
    @staticmethod
    def _datasetAnnotation(value, fieldName):
        """Normalize blank annotations without imposing a character limit."""
        if value is None:
            return None

        if not isinstance(value, str) or "\x00" in value:
            raise ValueError(f"{fieldName} must be a string without NUL, or None.")

        return value if value.strip() else None

    # ++++++++++++++++++++++++ _validateDatasetProducts +++++++++++++++++++++++
    # Direct callers in this module: _prepareDatasetMetadata, loadDataset, printDataset,
    # saveDataset.
    @staticmethod
    def _validateDatasetProducts(dataset):
        """Validate product names/types without opening references or arrays."""
        from .pglData import pglDataMatrix, pglDataMatrixReference

        products = dict(dataset.data)

        for name, product in products.items():
            if not isinstance(name, str) or not name.strip() or "\x00" in name:
                raise ValueError("Dataset product names must be nonblank strings without NUL.")

            if not isinstance(product, (pglDataMatrix, pglDataMatrixReference)):
                raise TypeError(f"Product {name!r} must be a pglDataMatrix or pglDataMatrixReference.")

        return products

    # ++++++++++++++++++++ _requireDatasetProductsUnchanged +++++++++++++++++++
    # Direct callers in this module: saveDataset.
    @classmethod
    def _requireDatasetProductsUnchanged(cls, dataset, products):
        """Check product attachment identity without comparing array contents.

        This does not detect all mutations through exposed xarray objects.
        Concurrent mutation during saving is unsupported.
        """
        if set(dataset.data) != set(products):
            raise ValueError("Dataset product names changed during saving.")

        for name, product in products.items():
            if dataset.data[name] is not product:
                raise ValueError(f"Dataset product {name!r} was replaced during saving.")


    # -------------------------------------------------------------------------
    # Session lifecycle coordination
    # -------------------------------------------------------------------------
    # Preview, confirm, lock, and apply coordinated session deletion groups or whole-group
    # restoration.

    # ++++++++++++++++++++++ _changeSessionDeletionState ++++++++++++++++++++++
    # Direct callers in this module: deleteSession, undeleteSession.
    @classmethod
    def _changeSessionDeletionState(cls, sessionID, *, deleted, deleteDownstreamSessions=False, settings=None, settingsName=None, sslRootCert=None):
        """Settings-based lifecycle wrapper with confirmation and commit handling."""
        from .pglPostgres import pglPostgres

        if isinstance(sessionID, bool) or not isinstance(sessionID, int) or not 0 <= sessionID <= 9223372036854775807:
            pglMessages.warning("sessionID must be a nonnegative PostgreSQL bigint.", level=1)
            return None

        if type(deleted) is not bool:
            pglMessages.warning("deleted must be a boolean.", level=1)
            return None

        if type(deleteDownstreamSessions) is not bool:
            pglMessages.warning("deleteDownstreamSessions must be a boolean.", level=1)
            return None

        if deleteDownstreamSessions and not deleted:
            pglMessages.warning("deleteDownstreamSessions applies only to deletion.", level=1)
            return None

        action = "delete" if deleted else "undelete"
        approvedSessionIDs = None

        try:
            try:
                postgres = pglPostgres.fromSettings(settings=settings, settingsName=settingsName)
            except (TypeError, ValueError) as error:
                pglMessages.warning(f"Cannot {action} session: invalid settings or configuration: {error}", level=1)
                return None

            if postgres is None:
                return None

            if deleted and deleteDownstreamSessions:
                # Finish the preview transaction AND close its connection
                # before asking the user for confirmation.
                with postgres.connect(sslRootCert=sslRootCert) as connection:
                    if connection is None:
                        return None

                    with connection.transaction():
                        connection.execute("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ, READ ONLY")
                        records = cls._getSessionDeletionRecords(connection, postgres, sessionID)
                        candidates = [record for record in records if record["deleted_at"] is None]

                        target = next(record for record in records if record["session_id"] == sessionID)

                        if target["deleted_at"] is not None and candidates:
                            raise cls._SessionLifecycleBlocked(f"Session {sessionID} is already deleted but has active descendants. No new deletion group was created; resolve the existing lifecycle inconsistency first.")

                if not candidates:
                    return False

                databaseLabel = f"{postgres.databaseName}.{postgres.databaseSchema}"
                confirmed = cls._confirmSessionDeletion(sessionID, candidates, databaseLabel=databaseLabel)

                if confirmed is not True:
                    return False

                approvedSessionIDs = [record["session_id"] for record in candidates]

            # A fresh transaction performs the authoritative checks.
            with postgres.connect(sslRootCert=sslRootCert) as connection:
                if connection is None:
                    return None

                with connection.transaction():
                    connection.execute("SET TRANSACTION ISOLATION LEVEL READ COMMITTED")
                    changed = cls._setSessionDeleted(connection, postgres, sessionID, deleted=deleted, approvedSessionIDs=approvedSessionIDs)

        except cls._UnknownLifecycleSession as error:
            pglMessages.warning(str(error), level=0)
            return False

        except cls._SessionLifecycleBlocked as error:
            pglMessages.warning(str(error), level=2)
            return False

        except psycopg.Error as error:
            pglMessages.warning(f"Could not {action} session {sessionID}: {error}. If the connection failed during commit, the outcome may be uncertain; check the session state before retrying.", level=2)
            return None

        # Report success only after transaction and connection cleanup.
        if changed:
            if deleted:
                pglMessages.message(f"Soft deletion committed for session {sessionID} and its deletion group in {postgres.databaseName}.{postgres.databaseSchema}.")
            else:
                pglMessages.message(f"Restoration committed for session {sessionID} and its deletion group, if any, in {postgres.databaseName}.{postgres.databaseSchema}.")

        return changed

    # +++++++++++++++++++++++ _getSessionDeletionRecords ++++++++++++++++++++++
    # Direct callers in this module: _changeSessionDeletionState, _setSessionDeleted.
    @classmethod
    def _getSessionDeletionRecords(cls, connection, postgres, sessionID):
        """Return target/descendants and reject dataset-protected deletion.

        Includes deleted records in the returned inventory, but checks
        protection only for sessions that would be newly deleted.

        Used in a consistent preview snapshot and again under lifecycle
        locks before authoritative deletion. A preview alone does not
        authorize any database changes.

        Does not write, commit, reconstruct sessions, or read payloads.
        """
        from psycopg.rows import dict_row

        if type(sessionID) is not int or not 0 <= sessionID <= 9223372036854775807:
            raise ValueError("sessionID must be a nonnegative PostgreSQL bigint.")

        sessions = sql.Identifier(postgres.databaseSchema, "session")
        statement = sql.SQL("""
            SELECT session_id, parent_session_id, root_session_id,
                   origin, kind, status, description, created_at, deleted_at
            FROM {}
            WHERE session_id = %s
        """).format(sessions)

        with connection.cursor(row_factory=dict_row) as cursor:
            cursor.execute(statement, (sessionID,))
            target = cursor.fetchone()

        if target is None:
            raise cls._UnknownLifecycleSession(f"Unknown session: {sessionID}")

        descendants = cls.getDownstreamSessions(connection, postgres, sessionID)
        records = sorted([target, *descendants], key=lambda record: record["session_id"])
        proposedIDs = [record["session_id"] for record in records if record["deleted_at"] is None]

        cls._requireNoDatasetSessionBlockers(connection, postgres, proposedIDs)
        return records

    # ++++++++++++++++++++++++ _confirmSessionDeletion ++++++++++++++++++++++++
    # Direct callers in this module: _changeSessionDeletionState.
    @staticmethod
    def _confirmSessionDeletion(sessionID, sessions, *, databaseLabel):
        """Print every proposed member and require an explicit 'yes'.

        No database access or payload I/O. Call without database locks.
        Cancellation or unavailable input never authorizes deletion.
        """
        records = sorted(sessions, key=lambda record: record["session_id"])

        if not records:
            return False

        # ++++++++++++++++++++++++++++++++ display ++++++++++++++++++++++++++++++++
        # Local implementation within _confirmSessionDeletion.
        def display(value):
            return "NULL" if value is None else repr(value)

        pglMessages.print()
        pglMessages.printHeader("sessions to be deleted")
        pglMessages.print(f"Database: {display(databaseLabel)}")
        pglMessages.print(f"Deletion-group top-level session: {sessionID}")
        pglMessages.print(f"Sessions to be newly soft-deleted: {len(records)}")
        pglMessages.print("Previously deleted sessions are not added to this group.")
        pglMessages.print()

        for record in records:
            label = "top-level session" if record["session_id"] == sessionID else "downstream session"
            pglMessages.print(f"  Session {record['session_id']} ({label})")
            pglMessages.print(f"    Parent: {display(record.get('parent_session_id'))}")
            pglMessages.print(f"    Origin: {display(record.get('origin'))} | Status: {display(record.get('status'))}")
            pglMessages.print(f"    Created: {display(record.get('created_at'))}")
            pglMessages.print(f"    Description: {display(record.get('description'))}")
            pglMessages.print()

        pglMessages.print("This is soft deletion only. No payload files will be removed.")
        pglMessages.print(f"Restore this entire deletion group with undeleteSession({sessionID}).")
        pglMessages.print("Individual group members cannot be restored separately.")
        pglMessages.print("Restoration requires any parent outside the group to be active.")
        pglMessages.print("All listed sessions must be included; partial selection is not supported.")

        try:
            response = input("Type yes to soft-delete ALL listed sessions; anything else cancels: ")
        except (EOFError, OSError, KeyboardInterrupt, NotImplementedError):
            pglMessages.print("\nDeletion cancelled: confirmation was interrupted or input was unavailable.")
            return False

        if response.strip().lower() != "yes":
            pglMessages.print("Deletion cancelled.")
            return False

        pglMessages.print("Confirmation received. The deletion set will be rechecked before any changes.")
        return True

    # +++++++++++++++++++++++++++ _setSessionDeleted ++++++++++++++++++++++++++
    # Direct callers in this module: _changeSessionDeletionState.
    @classmethod
    def _setSessionDeleted(cls, connection, postgres, sessionID, *, deleted, approvedSessionIDs=None):
        """Atomically delete a group or restore an existing deletion group.

        Internal lifecycle operation; no confirmation prompt or payload I/O.

        approvedSessionIDs:
            None permits deletion only when no active descendants exist.
            Otherwise, must exactly match all sessions to be newly deleted.
            The public wrapper supplies this only after user confirmation.
            Not permitted for restoration.

        Returns True for a change, False for an unchanged state.
        Unknown sessions and blocked operations raise dedicated ValueError
        subclasses; the public wrapper translates them into warnings.

        Opens a transaction/savepoint. An outer transaction must commit for
        persistence. Requires READ COMMITTED isolation.

        Conservative EXCLUSIVE locks last until the outer transaction ends.
        Ordinary SELECT queries remain allowed; competing writes are blocked.
        """
        if isinstance(sessionID, bool) or not isinstance(sessionID, int) or not 0 <= sessionID <= 9223372036854775807:
            raise ValueError("sessionID must be a nonnegative PostgreSQL bigint.")

        if type(deleted) is not bool:
            raise ValueError("deleted must be a boolean.")

        if approvedSessionIDs is not None:
            if not deleted:
                raise ValueError("approvedSessionIDs applies only to deletion.")

            if not isinstance(approvedSessionIDs, (list, tuple)):
                raise ValueError("approvedSessionIDs must be a list or tuple.")

            for value in approvedSessionIDs:
                if isinstance(value, bool) or not isinstance(value, int) or not 0 <= value <= 9223372036854775807:
                    raise ValueError("approvedSessionIDs must contain nonnegative PostgreSQL bigints.")

            if len(set(approvedSessionIDs)) != len(approvedSessionIDs):
                raise ValueError("approvedSessionIDs must not contain duplicates.")

            approvedSessionIDs = sorted(approvedSessionIDs)

        sessions = sql.Identifier(postgres.databaseSchema, "session")
        links = sql.Identifier(postgres.databaseSchema, "session_files")
        files = sql.Identifier(postgres.databaseSchema, "files")
        locations = sql.Identifier(postgres.databaseSchema, "storage_locations")
        groups = sql.Identifier(postgres.databaseSchema, "session_deletion_groups")
        members = sql.Identifier(postgres.databaseSchema, "session_deletion_group_members")

        from psycopg.rows import tuple_row

        with connection.transaction():
            with connection.cursor(row_factory=tuple_row) as cursor:
                cursor.execute("SHOW transaction_isolation")

                if cursor.fetchone()[0] != "read committed":
                    raise ValueError("Session delete/undelete requires READ COMMITTED isolation.")

                # Parent relationships live on session, so locking session
                # also protects the authoritative descendant/parent checks.
                statement = sql.SQL("LOCK TABLE {}, {}, {}, {}, {}, {} IN EXCLUSIVE MODE").format(sessions, links, files, locations, groups, members)
                cursor.execute(statement)

                cursor.execute(sql.SQL("SELECT deleted_at FROM {} WHERE session_id = %s").format(sessions), (sessionID,))
                target = cursor.fetchone()

                if target is None:
                    raise cls._UnknownLifecycleSession(f"Unknown session: {sessionID}")

                if deleted:
                    records = cls._getSessionDeletionRecords(connection, postgres, sessionID)
                    candidates = [record for record in records if record["deleted_at"] is None]
                    affectedIDs = sorted(record["session_id"] for record in candidates)

                    # Never silently expand OR shrink the approved set.
                    if approvedSessionIDs is not None and affectedIDs != approvedSessionIDs:
                        raise cls._SessionLifecycleBlocked("The sessions to be deleted changed after confirmation. Nothing was changed; rerun deleteSession() to review the current list.")

                    if target[0] is not None:
                        if affectedIDs:
                            raise cls._SessionLifecycleBlocked(f"Session {sessionID} is already deleted but has active descendants. No new deletion group was created; resolve the existing lifecycle inconsistency first.")
                        return False

                    downstreamIDs = [value for value in affectedIDs if value != sessionID]

                    if downstreamIDs and approvedSessionIDs is None:
                        listed = ", ".join(str(value) for value in downstreamIDs)
                        raise cls._SessionLifecycleBlocked(f"Cannot delete session {sessionID}: active downstream sessions exist: {listed}. Use deleteDownstreamSessions=True to preview and explicitly confirm deletion of the complete group.")

                    # Prevent a group from spanning a previously deleted
                    # intermediate parent. Such a group could otherwise
                    # become impossible to restore under the parent rule.
                    recordsByID = {record["session_id"]: record for record in records}

                    for record in candidates:
                        if record["session_id"] == sessionID:
                            continue

                        parent = recordsByID.get(record["parent_session_id"])

                        if parent is not None and parent["deleted_at"] is not None:
                            raise cls._SessionLifecycleBlocked(f"Cannot create deletion group: active session {record['session_id']} has deleted parent {record['parent_session_id']} inside the downstream tree. Resolve this existing lifecycle inconsistency first; nothing was changed.")

                    # Active sessions must not already have outstanding
                    # group membership or lead an outstanding group.
                    statement = sql.SQL("""
                        SELECT session_id
                        FROM {}
                        WHERE session_id = ANY(%s::bigint[])
                          AND restored_at IS NULL
                        ORDER BY session_id
                    """).format(members)
                    cursor.execute(statement, (affectedIDs,))
                    conflicts = [row[0] for row in cursor.fetchall()]

                    if conflicts:
                        raise cls._SessionLifecycleBlocked(f"Active sessions already have outstanding deletion-group membership: {conflicts}. Nothing was changed; review lifecycle consistency.")

                    statement = sql.SQL("""
                        SELECT top_session_id
                        FROM {}
                        WHERE top_session_id = ANY(%s::bigint[])
                          AND restored_at IS NULL
                        ORDER BY top_session_id
                    """).format(groups)
                    cursor.execute(statement, (affectedIDs,))
                    conflicts = [row[0] for row in cursor.fetchall()]

                    if conflicts:
                        raise cls._SessionLifecycleBlocked(f"Active sessions already lead outstanding deletion groups: {conflicts}. Nothing was changed; review lifecycle consistency.")

                    statement = sql.SQL("""
                        INSERT INTO {} (top_session_id)
                        VALUES (%s)
                        RETURNING deletion_group_id, created_at
                    """).format(groups)
                    cursor.execute(statement, (sessionID,))
                    groupID, marker = cursor.fetchone()

                    statement = sql.SQL("""
                        INSERT INTO {} (deletion_group_id, session_id)
                        SELECT %s, member_id
                        FROM unnest(%s::bigint[]) AS member_ids(member_id)
                    """).format(members)
                    cursor.execute(statement, (groupID, affectedIDs))

                    cls._applySessionDeletionMarkers(connection, postgres, affectedIDs, marker)
                    return True

                # Restoration: resolve outstanding membership first.
                statement = sql.SQL("""
                    SELECT membership.deletion_group_id,
                           deletion_group.top_session_id,
                           deletion_group.restored_at
                    FROM {} AS membership
                    JOIN {} AS deletion_group
                      ON deletion_group.deletion_group_id = membership.deletion_group_id
                    WHERE membership.session_id = %s
                      AND membership.restored_at IS NULL
                """).format(members, groups)
                cursor.execute(statement, (sessionID,))
                membership = cursor.fetchone()

                statement = sql.SQL("""
                    SELECT deletion_group_id
                    FROM {}
                    WHERE top_session_id = %s
                      AND restored_at IS NULL
                """).format(groups)
                cursor.execute(statement, (sessionID,))
                ledGroup = cursor.fetchone()

                if membership is None:
                    if ledGroup is not None:
                        raise cls._SessionLifecycleBlocked(f"Session {sessionID} leads an outstanding group but lacks its membership record. Nothing was changed; review lifecycle consistency.")

                    if target[0] is None:
                        return False

                    # Legacy deletion: do not invent historical membership.
                    groupID = None
                    affectedIDs = [sessionID]

                else:
                    groupID, topID, groupRestoredAt = membership

                    if groupRestoredAt is not None:
                        raise cls._SessionLifecycleBlocked(f"Session {sessionID} has outstanding membership in an already-restored group. Nothing was changed; review lifecycle consistency.")

                    if topID != sessionID:
                        raise cls._SessionLifecycleBlocked(f"Session {sessionID} belongs to the deletion group led by session {topID}. Restore the entire group with undeleteSession({topID}); individual members cannot be restored separately.")

                    if ledGroup != (groupID,):
                        raise cls._SessionLifecycleBlocked(f"Session {sessionID} has inconsistent deletion-group ownership. Nothing was changed.")

                    statement = sql.SQL("""
                        SELECT membership.session_id,
                               membership.restored_at,
                               checkpoint.deleted_at
                        FROM {} AS membership
                        JOIN {} AS checkpoint
                          ON checkpoint.session_id = membership.session_id
                        WHERE membership.deletion_group_id = %s
                        ORDER BY membership.session_id
                    """).format(members, sessions)
                    cursor.execute(statement, (groupID,))
                    memberRows = cursor.fetchall()
                    affectedIDs = [row[0] for row in memberRows]

                    if sessionID not in affectedIDs or any(restoredAt is not None or deletedAt is None for _, restoredAt, deletedAt in memberRows):
                        raise cls._SessionLifecycleBlocked(f"Deletion group {groupID} has inconsistent member states. Nothing was changed; review lifecycle consistency.")

                # Every required parent must either be restored in this
                # operation or already be active outside the group.
                statement = sql.SQL("""
                    SELECT child.session_id, child.parent_session_id
                    FROM {sessions} AS child
                    LEFT JOIN {sessions} AS parent
                      ON parent.session_id = child.parent_session_id
                    WHERE child.session_id = ANY(%s::bigint[])
                      AND child.parent_session_id IS NOT NULL
                      AND NOT (child.parent_session_id = ANY(%s::bigint[]))
                      AND (parent.session_id IS NULL OR parent.deleted_at IS NOT NULL)
                    ORDER BY child.session_id
                """).format(sessions=sessions)
                cursor.execute(statement, (affectedIDs, affectedIDs))
                blockedParents = cursor.fetchall()

                if blockedParents:
                    details = ", ".join(f"session {childID} requires parent {parentID}" for childID, parentID in blockedParents)
                    raise cls._SessionLifecycleBlocked(f"Cannot restore session {sessionID}: {details}. Restore the required parent or its top-level deletion group first. Nothing was changed.")

                cls._applySessionDeletionMarkers(connection, postgres, affectedIDs, None)

                if groupID is not None:
                    cursor.execute("SELECT statement_timestamp()")
                    restoredAt = cursor.fetchone()[0]

                    cursor.execute(sql.SQL("UPDATE {} SET restored_at = %s WHERE deletion_group_id = %s").format(groups), (restoredAt, groupID))
                    cursor.execute(sql.SQL("UPDATE {} SET restored_at = %s WHERE deletion_group_id = %s").format(members), (restoredAt, groupID))

                return True

    # ++++++++++++++++++++++ _applySessionDeletionMarkers +++++++++++++++++++++
    # Direct callers in this module: _setSessionDeleted.
    @staticmethod
    def _applySessionDeletionMarkers(connection, postgres, sessionIDs, marker):
        """Apply coordinated markers to an already-validated session set.

        Internal write primitive. Caller must hold all lifecycle locks,
        own the transaction, and perform group/lineage validation first.

        marker is a timestamp for deletion or None for restoration.
        Does not commit, inspect payloads, or manage group records.
        """
        sessions = sql.Identifier(postgres.databaseSchema, "session")
        links = sql.Identifier(postgres.databaseSchema, "session_files")
        files = sql.Identifier(postgres.databaseSchema, "files")
        locations = sql.Identifier(postgres.databaseSchema, "storage_locations")

        # Update every owner before changing links, so the existing
        # link guards see the correct session deletion marker.
        statement = sql.SQL("""
            UPDATE {}
            SET deleted_at = %s
            WHERE session_id = ANY(%s::bigint[])
              AND deleted_at IS DISTINCT FROM %s::timestamptz
        """).format(sessions)
        connection.execute(statement, (marker, sessionIDs, marker))

        statement = sql.SQL("""
            UPDATE {}
            SET deleted_at = %s
            WHERE session_id = ANY(%s::bigint[])
              AND deleted_at IS DISTINCT FROM %s::timestamptz
        """).format(links)
        connection.execute(statement, (marker, sessionIDs, marker))

        # All owners have their final markers before shared-content
        # eligibility is recomputed.
        statement = sql.SQL("""
            WITH desired AS (
                SELECT content.file_id,
                       CASE WHEN EXISTS (
                           SELECT 1
                           FROM {links} AS reference
                           JOIN {sessions} AS owner
                             ON owner.session_id = reference.session_id
                           WHERE reference.file_id = content.file_id
                             AND owner.deleted_at IS NULL
                       )
                       THEN NULL::timestamptz
                       ELSE COALESCE(content.deleted_at, %s::timestamptz)
                       END AS deleted_at
                FROM {files} AS content
                WHERE EXISTS (
                    SELECT 1
                    FROM {links} AS affected
                    WHERE affected.session_id = ANY(%s::bigint[])
                      AND affected.file_id = content.file_id
                )
            )
            UPDATE {files} AS content
            SET deleted_at = desired.deleted_at
            FROM desired
            WHERE content.file_id = desired.file_id
              AND content.deleted_at IS DISTINCT FROM desired.deleted_at
        """).format(sessions=sessions, links=links, files=files)
        connection.execute(statement, (marker, sessionIDs))

        statement = sql.SQL("""
            UPDATE {locations} AS location
            SET deleted_at = content.deleted_at
            FROM {files} AS content
            WHERE location.file_id = content.file_id
              AND EXISTS (
                  SELECT 1
                  FROM {links} AS affected
                  WHERE affected.session_id = ANY(%s::bigint[])
                    AND affected.file_id = content.file_id
              )
              AND location.deleted_at IS DISTINCT FROM content.deleted_at
        """).format(locations=locations, files=files, links=links)
        connection.execute(statement, (sessionIDs,))


    # -------------------------------------------------------------------------
    # Dataset dependency protection
    # -------------------------------------------------------------------------
    # Shared source checks used by dataset publication/restoration and session deletion.

    # +++++++++++++++++++++++ _getDatasetSessionBlockers ++++++++++++++++++++++
    # Direct callers in this module: _requireNoDatasetSessionBlockers.
    @staticmethod
    def _getDatasetSessionBlockers(connection, postgres, sessionIDs):
        """Find active datasets protecting any proposed session deletion.

        A dataset protects its exact members and every upstream ancestor.
        Historical matrix/action provenance does not create protection.

        Read-only metadata query. For an authoritative decision, the caller
        must hold the session lifecycle lock through transaction completion.
        """
        proposedIDs = list(sessionIDs)

        if any(type(value) is not int or not 0 <= value <= 9223372036854775807 for value in proposedIDs):
            raise ValueError("sessionIDs must contain nonnegative PostgreSQL bigints.")

        proposedIDs = sorted(set(proposedIDs))

        if not proposedIDs:
            return []

        sessions = sql.Identifier(postgres.databaseSchema, "session")
        datasets = sql.Identifier(postgres.databaseSchema, "dataset")
        members = sql.Identifier(postgres.databaseSchema, "dataset_members")

        # Carry the proposed deletion ID through its descendants so each
        # result identifies both the protected ancestor and exact member.
        # UNION terminates traversal even if malformed lineage contains a cycle.
        statement = sql.SQL("""
            WITH RECURSIVE descendants(target_id, session_id) AS (
                SELECT checkpoint.session_id, checkpoint.session_id
                FROM {sessions} AS checkpoint
                WHERE checkpoint.session_id = ANY(%s::bigint[])

                UNION

                SELECT descendants.target_id, child.session_id
                FROM descendants
                JOIN {sessions} AS child
                  ON child.parent_session_id = descendants.session_id
            )
            SELECT descendants.target_id,
                   owner.dataset_id,
                   owner.name,
                   owner.checkpoint_name,
                   membership.session_id,
                   membership.entry_name
            FROM descendants
            JOIN {members} AS membership
              ON membership.session_id = descendants.session_id
            JOIN {datasets} AS owner
              ON owner.dataset_id = membership.dataset_id
            WHERE owner.status = 'complete'
              AND owner.deleted_at IS NULL
            ORDER BY owner.dataset_id,
                     membership.session_id,
                     descendants.target_id
        """).format(sessions=sessions, datasets=datasets, members=members)

        from psycopg.rows import tuple_row

        with connection.cursor(row_factory=tuple_row) as cursor:
            cursor.execute(statement, (proposedIDs,))
            rows = cursor.fetchall()

        names = ("protectedSessionID", "datasetID", "datasetName", "checkpointName", "memberSessionID", "entryName")
        return [dict(zip(names, row)) for row in rows]

    # ++++++++++++++++++++ _requireNoDatasetSessionBlockers +++++++++++++++++++
    # Direct callers in this module: _getSessionDeletionRecords.
    @classmethod
    def _requireNoDatasetSessionBlockers(cls, connection, postgres, sessionIDs):
        """Refuse a complete proposed deletion set if any member is protected.

        Raises the existing lifecycle exception, which the public session
        deletion wrapper translates into pglMessages.warning.

        Does not modify database records or open scientific payloads.
        """
        blockers = cls._getDatasetSessionBlockers(connection, postgres, sessionIDs)

        if not blockers:
            return

        # One concrete blocker is sufficient to explain refusal. Report how
        # many additional protection relationships were found without printing
        # an unbounded list for large datasets.
        blocker = blockers[0]
        datasetName = cls._printValue(blocker["datasetName"])
        checkpointName = blocker["checkpointName"]
        entryName = blocker["entryName"]

        datasetLabel = f"dataset {blocker['datasetID']} ({datasetName!r})"

        if checkpointName:
            datasetLabel += f", checkpoint {cls._printValue(checkpointName)!r}"

        memberLabel = f"member session {blocker['memberSessionID']}"

        if entryName is not None:
            memberLabel += f", entryName={cls._printValue(entryName)!r}"

        extra = f" There are {len(blockers) - 1} additional blocking relationships." if len(blockers) > 1 else ""

        raise cls._SessionLifecycleBlocked(f"Cannot delete session {blocker['protectedSessionID']}: active {datasetLabel} protects {memberLabel} and its ancestors.{extra} Nothing was changed. deleteDownstreamSessions=True cannot bypass dataset protection. Removing a member in a newer dataset version does not release protection held by older active versions.")

    # +++++++++++++++++++++++ _getDatasetSourceProblems +++++++++++++++++++++++
    # Direct callers in this module: _changeDatasetDeletionState, saveDataset.
    @staticmethod
    def _getDatasetSourceProblems(connection, postgres, datasetID):
        """List members/ancestors that prevent dataset restoration.

        Returns metadata only. The caller must validate the dataset's
        existence and hold the session dependency lock when using this
        result to authorize restoration.
        """
        if type(datasetID) is not int or not 0 <= datasetID <= 9223372036854775807:
            raise ValueError("datasetID must be a nonnegative PostgreSQL bigint.")

        sessions = sql.Identifier(postgres.databaseSchema, "session")
        members = sql.Identifier(postgres.databaseSchema, "dataset_members")

        statement = sql.SQL("""
            WITH RECURSIVE ancestry(member_id, source_id) AS (
                SELECT membership.session_id, membership.session_id
                FROM {members} AS membership
                WHERE membership.dataset_id = %s

                UNION

                SELECT ancestry.member_id, checkpoint.parent_session_id
                FROM ancestry
                JOIN {sessions} AS checkpoint
                  ON checkpoint.session_id = ancestry.source_id
                WHERE checkpoint.parent_session_id IS NOT NULL
            )
            SELECT ancestry.member_id,
                   membership.entry_name,
                   ancestry.source_id,
                   checkpoint.status,
                   checkpoint.deleted_at
            FROM ancestry
            JOIN {members} AS membership
              ON membership.dataset_id = %s
             AND membership.session_id = ancestry.member_id
            LEFT JOIN {sessions} AS checkpoint
              ON checkpoint.session_id = ancestry.source_id
            WHERE checkpoint.session_id IS NULL
               OR checkpoint.status <> 'complete'
               OR checkpoint.deleted_at IS NOT NULL
            ORDER BY ancestry.member_id, ancestry.source_id
        """).format(sessions=sessions, members=members)

        from psycopg.rows import tuple_row

        with connection.cursor(row_factory=tuple_row) as cursor:
            cursor.execute(statement, (datasetID, datasetID))
            rows = cursor.fetchall()

        names = ("memberSessionID", "entryName", "sourceSessionID", "status", "deletedAt")
        return [dict(zip(names, row)) for row in rows]


    # -------------------------------------------------------------------------
    # Dataset lifecycle coordination
    # -------------------------------------------------------------------------
    # Serialize dataset deletion/restoration with session lifecycle writes and revalidate required
    # sources.

    # ++++++++++++++++++++++ _changeDatasetDeletionState ++++++++++++++++++++++
    # Direct callers in this module: deleteDataset, undeleteDataset.
    @classmethod
    def _changeDatasetDeletionState(cls, datasetID, *, deleted, settings=None, settingsName=None, sslRootCert=None):
        """Coordinate a dataset lifecycle change with session lifecycle writes.

        Acquire the session dependency lock before locking the dataset row.
        This matches the protocol required for future dataset publication.

        Session deletion takes an EXCLUSIVE session-table lock, conflicting
        with this SHARE lock. Member/ancestor validation therefore remains
        valid until commit.

        Scientific payloads and membership records are never modified here.
        """
        from .pglPostgres import pglPostgres
        from psycopg.rows import tuple_row

        if type(datasetID) is not int or not 0 <= datasetID <= 9223372036854775807:
            pglMessages.warning("datasetID must be a nonnegative PostgreSQL bigint.", level=1)
            return None

        if type(deleted) is not bool:
            pglMessages.warning("deleted must be a boolean.", level=1)
            return None

        operation = "delete" if deleted else "undelete"
        outcome = None
        warning = None

        try:
            try:
                postgres = pglPostgres.fromSettings(settings=settings, settingsName=settingsName)
            except (TypeError, ValueError) as error:
                pglMessages.warning(f"Cannot {operation} dataset: invalid settings or configuration: {error}", level=1)
                return None

            if postgres is None:
                return None

            sessions = sql.Identifier(postgres.databaseSchema, "session")
            datasets = sql.Identifier(postgres.databaseSchema, "dataset")

            with postgres.connect(sslRootCert=sslRootCert) as connection:
                if connection is None:
                    return None

                with connection.transaction():
                    connection.execute("SET TRANSACTION ISOLATION LEVEL READ COMMITTED")

                    # Take this before dataset row locks and before any writes.
                    connection.execute(sql.SQL("LOCK TABLE {} IN SHARE MODE").format(sessions))

                    with connection.cursor(row_factory=tuple_row) as cursor:
                        statement = sql.SQL("SELECT status, deleted_at FROM {} WHERE dataset_id = %s FOR UPDATE").format(datasets)
                        cursor.execute(statement, (datasetID,))
                        record = cursor.fetchone()

                        if record is None:
                            outcome = "unknown"

                        elif record[0] != "complete":
                            outcome = "blocked"
                            warning = f"Cannot {operation} dataset {datasetID}: only completed dataset checkpoints support this lifecycle operation."

                        elif (record[1] is not None) == deleted:
                            outcome = "unchanged"

                        else:
                            problems = cls._getDatasetSourceProblems(connection, postgres, datasetID) if not deleted else []

                            if problems:
                                problem = problems[0]
                                sourceID = problem["sourceSessionID"]
                                memberID = problem["memberSessionID"]
                                entryName = problem["entryName"]
                                memberLabel = f"member session {memberID}"

                                if entryName is not None:
                                    memberLabel += f" (entryName={cls._printValue(entryName)!r})"

                                if problem["status"] is None:
                                    reason = "missing"
                                elif problem["deletedAt"] is not None:
                                    reason = "deleted"
                                else:
                                    reason = f"not complete (status={cls._printValue(problem['status'])!r})"

                                extra = f" There are {len(problems) - 1} additional unavailable source relationships." if len(problems) > 1 else ""
                                warning = f"Cannot undelete dataset {datasetID}: {memberLabel} requires session {sourceID}, which is {reason}.{extra} Restore the required sessions or their deletion groups first. Nothing was changed."
                                outcome = "blocked"

                            else:
                                marker = sql.SQL("statement_timestamp()") if deleted else sql.SQL("NULL")
                                statement = sql.SQL("UPDATE {} SET deleted_at = {} WHERE dataset_id = %s RETURNING dataset_id").format(datasets, marker)
                                cursor.execute(statement, (datasetID,))

                                if cursor.fetchone() != (datasetID,):
                                    raise RuntimeError("Dataset lifecycle update did not return the requested checkpoint.")

                                outcome = "changed"

        except psycopg.Error as error:
            pglMessages.warning(f"Could not {operation} dataset {datasetID}: {error}. If the connection failed during commit, check the dataset state before retrying.", level=2)
            return None

        # Report only after transaction and connection cleanup.
        if outcome == "unknown":
            pglMessages.warning(f"Unknown dataset checkpoint: {datasetID}", level=0)
            return False

        if outcome == "blocked":
            pglMessages.warning(warning, level=2)
            return False

        if outcome == "unchanged":
            return False

        if outcome != "changed":
            raise RuntimeError("Dataset lifecycle operation finished without a recognized outcome.")

        if deleted:
            pglMessages.message(f"Dataset {datasetID} soft-deleted in {postgres.databaseName}.{postgres.databaseSchema}. Its session protection is released; sessions and saved outputs are unchanged.")
        else:
            pglMessages.message(f"Dataset {datasetID} restored in {postgres.databaseName}.{postgres.databaseSchema}. Its members and ancestors are protected again.")

        return True


    # -------------------------------------------------------------------------
    # Reporting configuration and formatting
    # -------------------------------------------------------------------------
    # Shared report configuration, table formatting, and session-lineage presentation.

    # +++++++++++++++++++++++++++++ _printPostgres ++++++++++++++++++++++++++++
    # Direct callers in this module: printDatasets, printSession, printSessions, printTables.
    @staticmethod
    def _printPostgres(postgres=None, *, settings=None, settingsName=None):
        """Resolve reporting configuration without opening a connection."""
        from .pglPostgres import pglPostgres

        if postgres is not None and (settings is not None or settingsName is not None):
            raise ValueError("Supply either postgres or PGL settings, not both.")

        if postgres is None:
            postgres = pglPostgres.fromSettings(settings=settings, settingsName=settingsName)

        if postgres is not None and not isinstance(postgres, pglPostgres):
            raise TypeError("postgres must be a pglPostgres instance.")

        return postgres

    # ++++++++++++++++++++++++++++++ _printValue ++++++++++++++++++++++++++++++
    # Direct callers in this module: _changeDatasetDeletionState, _printTable,
    # _requireNoDatasetSessionBlockers, _sessionLineageLines, printDataset, printDatasets,
    # printSession, printSessions, setSessionDescription.
    @staticmethod
    def _printValue(value, maxWidth=None):
        """Produce single-line display text, optionally truncated."""
        text = "NULL" if value is None else str(value)
        text = text.replace("\r", "\\r").replace("\n", "\\n").replace("\t", "\\t")

        if maxWidth is not None and len(text) > maxWidth:
            return text[:maxWidth - 3] + "..."

        return text

    # ++++++++++++++++++++++++++++++ _printTable ++++++++++++++++++++++++++++++
    # Direct callers in this module: printDataset, printTables.
    @staticmethod
    def _printTable(headers, rows, maxWidth=48):
        """Print a compact table without accessing storage."""
        displayed = [[pglDatabase._printValue(value, maxWidth) for value in headers]]
        displayed.extend([pglDatabase._printValue(value, maxWidth) for value in row] for row in rows)
        widths = [max(len(row[index]) for row in displayed) for index in range(len(headers))]

        # ++++++++++++++++++++++++++++++++ printRow +++++++++++++++++++++++++++++++
        # Local implementation within _printTable.
        def printRow(row):
            pglMessages.print("  " + " | ".join(value.ljust(width) for value, width in zip(row, widths)))

        printRow(displayed[0])
        pglMessages.print("  " + "-+-".join("-" * width for width in widths))

        for row in displayed[1:]:
            printRow(row)

        if not rows:
            pglMessages.print("  (no rows)")

    # ++++++++++++++++++++++++++++ _printTableOrder +++++++++++++++++++++++++++
    # Direct callers in this module: printTables.
    @staticmethod
    def _printTableOrder():
        """Supported database-report tables and their stable ordering."""
        return {
            "session": ("session_id",),
            "dataset": ("dataset_id",),
            "dataset_members": ("dataset_id", "member_index"),
            "dataset_products": ("dataset_id", "product_name"),
            "matrix_revisions": ("matrix_revision_id",),
            "subjects": ("subject_id",),
            "files": ("file_id",),
            "storage_backends": ("backend_id",),
            "storage_locations": ("file_id", "backend_id", "object_key"),
            "users": ("user_id",),
            "session_files": ("session_id", "name"),
        }

    # ++++++++++++++++++++++++++ _sessionLineageLines +++++++++++++++++++++++++
    # Direct callers in this module: printSessions.
    # ++++++++++++++++++++++++++ _sessionLineageLines +++++++++++++++++++++++++
    # Direct callers in this module: printSessions.
    @staticmethod
    def _sessionLineageLines(records):
        """Format visible session lineage without descriptions.

        Parentless roots use behavioral acquisition session names:
            sessionID: 92 [day1]

        Descendants use database checkpoint names:
            95 (checkpointName)

        Ancestors retained only to explain filtered lineage use [context].

        Hidden/missing parents are not bypassed by artificial arrows.
        Iterative traversal avoids Python recursion limits.
        """
        children = {sessionID: [] for sessionID in records}

        for sessionID, record in records.items():
            parentID = record["parent_session_id"]

            if parentID in records:
                children[parentID].append(sessionID)

        for values in children.values():
            values.sort()

        roots = sorted(sessionID for sessionID, record in records.items() if record["parent_session_id"] not in records)
        visited = set()
        lines = []

        # +++++++++++++++++++++++++++++++ nodeLabel +++++++++++++++++++++++++++++++
        # Local implementation within _sessionLineageLines.
        def nodeLabel(sessionID):
            record = records[sessionID]

            if record["parent_session_id"] is None:
                label = f"sessionID: {sessionID}"
                sessionNames = record["session_names"]

                if sessionNames:
                    label += " [" + ", ".join(pglDatabase._printValue(name) for name in sessionNames) + "]"
            else:
                label = str(sessionID)
                checkpointName = record["checkpoint_name"]

                if checkpointName:
                    label += f" ({pglDatabase._printValue(checkpointName)})"

            if record["deleted_at"] is not None:
                label += " [deleted]"

            if record["status"] != "complete":
                label += f" [{pglDatabase._printValue(record['status'])}]"

            if record.get("filter_context", False):
                label += " [context]"

            return label

        # +++++++++++++++++++++++++++++++ appendTree ++++++++++++++++++++++++++++++
        # Local implementation within _sessionLineageLines.
        def appendTree(startID, prefix):
            pending = [(startID, prefix)]

            while pending:
                currentID, currentPrefix = pending.pop()
                line = currentPrefix

                while True:
                    if currentID in visited:
                        raise ValueError("Session lineage contains a cycle or repeated node.")

                    visited.add(currentID)
                    line += nodeLabel(currentID)
                    descendants = children[currentID]

                    if not descendants:
                        lines.append(line)
                        break

                    branchPrefix = " " * (len(line) + 1) + "-> "

                    for childID in reversed(descendants[1:]):
                        pending.append((childID, branchPrefix))

                    currentID = descendants[0]
                    line += " -> "

        for sessionID in roots:
            parentID = records[sessionID]["parent_session_id"]

            if parentID is not None:
                lines.append(f"    [parent session {parentID} is not visible in this listing]")

            appendTree(sessionID, "    ")

        if len(visited) != len(records):
            raise ValueError("Session lineage contains a cycle with no visible root.")

        return lines

    # ++++++++++++++++++++++++++ _printGroupingValue ++++++++++++++++++++++++++
    # Direct callers in this module: printSessions.
    @staticmethod
    def _printGroupingValue(value, fieldName):
        """Use Unknown for unset labels, while rejecting malformed metadata."""
        if value is None:
            return "Unknown"

        if not isinstance(value, str):
            raise ValueError(f"Saved {fieldName} must be a string or None.")

        if not value.strip():
            return "Unknown"

        return value

    # ++++++++++++++++++++++ _readPrintExperimentSettings +++++++++++++++++++
    @staticmethod
    def _readPrintExperimentSettings(identity, locations, *, accessContext):
        """Read one verified experiment-settings document for a report.

        Called by printSessions() and getDatasetMemberSummaries().
        Borrows their access context so repeated file reads reuse connections.

        Tries supplied registered replicas in order. Checks bounded size and
        SHA-256 before decoding JSON. Once verified bytes are found, malformed
        JSON is a document error rather than a replica-selection failure.

        Returns a settings dictionary.
        Does not reconstruct runs, read MNE fields, query SQL, or publish data.
        Does not close the caller-owned context.
        """
        if not isinstance(accessContext, pglDatabaseAccess):
            raise TypeError("accessContext must be a pglDatabaseAccess instance.")

        maxBytes = 16 * 1024 * 1024
        expectedSize = identity["size_bytes"]
        expectedHash = identity["sha256"]

        if type(expectedSize) is not int or not 0 <= expectedSize <= maxBytes:
            raise ValueError("Experiment settings exceed the reporting size limit or have an invalid size.")

        failures = []

        for location in locations:
            backendID = location["backend_id"]
            key = location["object_key"]

            if not isinstance(key, str) or key.startswith("/") or "\\" in key or "\x00" in key or any(part in {"", ".", ".."} for part in key.split("/")):
                raise ValueError("Database contains an invalid experiment-settings object key.")

            try:
                filesystem, root = accessContext.resolve(backendID, location["url_prefix"])

                with filesystem.open(posixpath.join(root, key), "rb") as source:
                    content = source.read(expectedSize + 1)

                if len(content) != expectedSize or hashlib.sha256(content).hexdigest() != expectedHash:
                    raise ValueError("Experiment-settings integrity mismatch.")

            except (OSError, ValueError) as error:
                failures.append(f"backend {backendID}: {type(error).__name__}")
                continue

            settings = json.loads(content.decode("utf-8"))

            if not isinstance(settings, dict):
                raise ValueError("Saved experiment settings must contain a JSON object.")

            return settings

        reason = "; ".join(failures) or "no eligible storage locations"
        raise OSError("No experiment-settings copy could be verified: " + reason)


    # -------------------------------------------------------------------------
    # Pipeline inputs, ancestry, and replay metadata
    # -------------------------------------------------------------------------
    # Resolve replay inputs and verify saved ancestry history without executing scientific actions.

    # +++++++++++++++++++++++++++ _loadPipelineInput ++++++++++++++++++++++++++
    # Checkpoint implementation support. Existing external callers may use this method; see its
    # docstring and this section's purpose.
    @classmethod
    def _loadPipelineInput(cls, sessionID, *, settings=None, settingsName=None, storageOptionsByBackend=None, sslRootCert=None, cacheDirectory=None, directLocalPolicy="materialize"):
        """Load an active checkpoint and describe it as a pipeline input.

        Reuses the public session loader, including its validation, deferred
        loading, and connection cleanup. No SQL connection is returned.

        The database identity is the current runtime endpoint descriptor,
        not a permanent globally unique store identifier.
        """
        if type(sessionID) is not int or not 0 <= sessionID <= 9223372036854775807:
            raise ValueError("sessionID must be a nonnegative PostgreSQL bigint.")

        session = cls.loadSession(sessionID, settings=settings, settingsName=settingsName, storageOptionsByBackend=storageOptionsByBackend, sslRootCert=sslRootCert, includeDeleted=False, cacheDirectory=cacheDirectory, directLocalPolicy=directLocalPolicy)

        if session is None:
            return None, None

        boundary = cls._getCheckpointHistoryBoundary(session)
        baseline = session._checkpointBaseline

        if boundary is None or baseline["sessionID"] != sessionID or boundary != len(session.actionHistory):
            raise ValueError("Loaded pipeline input lacks a matching checkpoint history baseline.")

        inputRecord = {
            "version": 1,
            "kind": "checkpoint",
            "sessionID": sessionID,
            "databaseIdentity": deepcopy(baseline["databaseIdentity"]),
            "historyCount": boundary,
            "historyHashes": list(baseline["historyHashes"]),
        }

        return session, inputRecord

    # ++++++++++++++++++++++ _validatePipelineReplayInput +++++++++++++++++++++
    # Direct callers in this module: _selectAncestralReplayInput.
    @staticmethod
    def _validatePipelineReplayInput(record, expected=None):
        """Validate replay input metadata and optionally compare it to a plan.

        Uses metadata only; does not connect, read payloads, or mutate records.

        Endpoint identity prevents accidental use of a different configured
        database. It is not a permanent store UUID across relocation/restores.
        """
        expectedFields = {"version", "kind", "sessionID", "databaseIdentity", "historyCount", "historyHashes"}

        # ++++++++++++++++++++++++++++++++ validate +++++++++++++++++++++++++++++++
        # Local implementation within _validatePipelineReplayInput.
        def validate(value):
            if not isinstance(value, dict) or set(value) != expectedFields:
                raise ValueError("Invalid pipeline checkpoint input record.")

            if type(value["version"]) is not int or value["version"] != 1 or value["kind"] != "checkpoint":
                raise ValueError("Unsupported pipeline checkpoint input version or kind.")

            if type(value["sessionID"]) is not int or not 0 <= value["sessionID"] <= 9223372036854775807:
                raise ValueError("Invalid replay checkpoint ID.")

            identity = value["databaseIdentity"]

            if not isinstance(identity, dict):
                raise ValueError("Invalid replay database identity.")

            transport = identity.get("transport")
            identityFields = {"transport", "host", "port", "database", "schema"}

            if transport == "ssh":
                identityFields.update({"sshHost", "sshPort", "sshUser"})
            elif transport != "direct":
                raise ValueError("Unsupported replay database transport.")

            if set(identity) != identityFields:
                raise ValueError("Invalid replay database identity fields.")

            for key in ("host", "database", "schema"):
                if not isinstance(identity[key], str) or not identity[key]:
                    raise ValueError(f"Invalid replay database identity: {key}.")

            if type(identity["port"]) is not int or not 1 <= identity["port"] <= 65535:
                raise ValueError("Invalid replay database port.")

            if transport == "ssh":
                if not isinstance(identity["sshHost"], str) or not identity["sshHost"] or not isinstance(identity["sshUser"], str):
                    raise ValueError("Invalid replay SSH identity.")

                if type(identity["sshPort"]) is not int or not 1 <= identity["sshPort"] <= 65535:
                    raise ValueError("Invalid replay SSH port.")

            count = value["historyCount"]
            hashes = value["historyHashes"]

            if type(count) is not int or count < 0 or not isinstance(hashes, list) or len(hashes) != count:
                raise ValueError("Invalid replay history boundary.")

            if any(not isinstance(digest, str) or re.fullmatch(r"[0-9a-f]{64}", digest) is None for digest in hashes):
                raise ValueError("Invalid replay history fingerprint.")

        validate(record)

        if expected is not None:
            validate(expected)

            if record["databaseIdentity"] != expected["databaseIdentity"]:
                raise ValueError("The configured database differs from the pipeline's recorded replay database. Select the original settings, or explicitly supply sessionID to choose a different input.")

            if record["sessionID"] != expected["sessionID"]:
                raise ValueError("Loaded checkpoint differs from the pipeline's recorded replay checkpoint.")

            if record["historyCount"] != expected["historyCount"] or record["historyHashes"] != expected["historyHashes"]:
                raise ValueError("Loaded checkpoint history differs from the recorded replay input. Execution was not started.")

        return record

    # ++++++++++++++++++++++ _readReplayCheckpointHistory +++++++++++++++++++++
    # Direct callers in this module: getSessionPipeline.
    @classmethod
    def _readReplayCheckpointHistory(cls, connection, postgres, checkpoint, *, storageOptionsByBackend=None):
        """Read history metadata without constructing runs or MNE objects.

        checkpoint is a validated ancestry record from getSessionPipeline().
        Reject contracts without a recorded session-history boundary.

        Derived v1/v2/v3 share the history-reading contract. Matrix products
        and derived-file payloads are not opened or replayed here.
        """
        from io import BytesIO, TextIOWrapper

        sessionID = checkpoint["sessionID"]
        origin = checkpoint["origin"]
        contract = checkpoint["contractVersion"]

        if (origin, contract) == ("raw", "pgl.raw.behavior.v1"):
            raise ValueError(
                f"Raw checkpoint {sessionID} uses pgl.raw.behavior.v1 and has no session-level "
                "history boundary. Automatic ancestry replay cannot safely distinguish "
                "acquisition loading from later processing for this contract."
            )

        supported = {
            ("raw", "pgl.raw.session.v1"),
            ("raw", "pgl.raw.session.v2"),
            ("derived", "pgl.derived.behavior.v1"),
            ("derived", "pgl.derived.behavior.v2"),
            ("derived", "pgl.derived.behavior.v3"),
            ("derived", "pgl.derived.session.v1"),
            ("derived", "pgl.derived.session.v2"),
            ("derived", "pgl.derived.session.v3"),
            ("derived", "pgl.derived.mri.v1"),
            ("derived", "pgl.derived.mri.v2"),
        }

        if (origin, contract) not in supported:
            raise ValueError(f"Checkpoint {sessionID} has an unsupported replay contract: {origin}, {contract}.")

        manifestBytes, manifestIdentity = cls._readReplayMetadataFile(
            connection, postgres, sessionID, "manifest.json",
            storageOptionsByBackend=storageOptionsByBackend,
            maxBytes=16 * 1024 * 1024,
        )

        if manifestIdentity["sha256"] != checkpoint["manifestHash"]:
            raise ValueError(f"Checkpoint {sessionID}: manifest link differs from its checkpoint identity.")

        manifest = json.loads(manifestBytes.decode("utf-8"))
        cls._validateSessionBundleManifest(manifest, origin=origin)

        if manifest["contract_version"] != contract or cls.encodeRawManifest(manifest) != manifestBytes:
            raise ValueError(f"Checkpoint {sessionID}: manifest contract or canonical encoding differs.")

        historyRecords = [record for record in manifest["files"] if record["name"] == "history.json"]
        if len(historyRecords) != 1:
            raise ValueError(f"Checkpoint {sessionID}: manifest must contain exactly one history.json.")

        historyBytes, historyIdentity = cls._readReplayMetadataFile(
            connection, postgres, sessionID, "history.json",
            storageOptionsByBackend=storageOptionsByBackend,
        )
        expectedHistory = historyRecords[0]

        if historyIdentity != {"sha256": expectedHistory["sha256"], "size_bytes": expectedHistory["size_bytes"]}:
            raise ValueError(f"Checkpoint {sessionID}: registered history differs from the manifest.")

        class HistoryView:
            """Expose only the already-verified history bytes to the reader."""

            def open(self, path, mode="rb", **kwargs):
                if path != "history.json":
                    raise ValueError("Replay history reader requested an unexpected file.")

                if mode == "rb": return BytesIO(historyBytes)
                if mode in ("r", "rt"):
                    return TextIOWrapper(BytesIO(historyBytes), encoding=kwargs.get("encoding", "utf-8"))

                raise ValueError("Replay history is read-only.")

        # Preserve existing history/label compatibility checks.
        history, metadata = cls._readSessionHistory(HistoryView(), len(manifest["runs"]))
        return history

    # ++++++++++++++++++++++++ _readReplayMetadataFile +++++++++++++++++++++++
    @classmethod
    def _readReplayMetadataFile(cls, connection, postgres, sessionID, name, *, storageOptionsByBackend=None, maxBytes=64 * 1024 * 1024):
        """Read a verified checkpoint metadata file for replay inspection.

        Called by _readReplayCheckpointHistory().
        Only manifest.json and history.json are permitted.

        The caller owns the SQL snapshot and validates checkpoint eligibility.
        This method verifies the active file link, expected role, registered
        content identity, and bytes read from an eligible replica.

        Server-local roots resolve through the caller's local/SSH context.
        Explicit remote URLs retain their own filesystem protocol.
        Does not fall back from SSH to client-local file access.

        Returns:
            (verifiedBytes, {"sha256": digest, "size_bytes": size})

        Owns a short-lived payload access context and closes it on both success
        and failure. Returned bytes do not depend on an open filesystem.

        Does not reconstruct scientific objects, execute actions, publish
        records, or modify payloads. Does not decode the returned JSON.

        Read/integrity failures may advance to another registered replica.
        Other connection and security errors propagate.
        """
        if name not in ("manifest.json", "history.json"):
            raise ValueError("Replay inspection may read only manifest.json or history.json.")

        if type(maxBytes) is not int or maxBytes <= 0:
            raise ValueError("maxBytes must be a positive integer.")

        links = sql.Identifier(postgres.databaseSchema, "session_files")
        files = sql.Identifier(postgres.databaseSchema, "files")
        locations = sql.Identifier(postgres.databaseSchema, "storage_locations")
        backends = sql.Identifier(postgres.databaseSchema, "storage_backends")

        statement = sql.SQL("""
            SELECT content.file_id,
                   content.sha256,
                   content.size_bytes,
                   link.role
            FROM {} AS link
            JOIN {} AS content ON content.file_id = link.file_id
            WHERE link.session_id = %s
              AND link.name = %s
              AND link.deleted_at IS NULL
              AND content.deleted_at IS NULL
        """).format(links, files)

        record = connection.execute(statement, (sessionID, name)).fetchone()

        if record is None:
            raise ValueError(f"Checkpoint {sessionID} has no active registered {name}.")

        fileID, digest, size, role = record
        expectedRole = "manifest" if name == "manifest.json" else "history"

        if role != expectedRole:
            raise ValueError(f"Checkpoint {sessionID}: {name} has an unexpected role.")

        if type(size) is not int or not 0 <= size <= maxBytes:
            raise ValueError(f"Checkpoint {sessionID}: {name} exceeds the replay metadata size limit or has an invalid size.")

        statement = sql.SQL("""
            SELECT backend.backend_id,
                   backend.url_prefix,
                   location.object_key
            FROM {} AS location
            JOIN {} AS backend ON backend.backend_id = location.backend_id
            WHERE location.file_id = %s
              AND location.deleted_at IS NULL
              AND location.status = 'present'
              AND location.verified_at IS NOT NULL
              AND backend.is_active
            ORDER BY location.priority, backend.backend_id, location.object_key
        """).format(locations, backends)

        candidates = connection.execute(statement, (fileID,)).fetchall()
        failures = []

        # No deferred reader escapes this method. Close owned SSH connections
        # before returning verified in-memory bytes.
        with pglDatabaseAccess(postgres, storageOptionsByBackend) as access:
            for backendID, registeredRoot, objectKey in candidates:
                if not isinstance(objectKey, str) or objectKey.startswith("/") or "\\" in objectKey or "\x00" in objectKey or any(part in {"", ".", ".."} for part in objectKey.split("/")):
                    raise ValueError("Database contains an invalid replay metadata object key.")

                try:
                    filesystem, root = access.resolve(backendID, registeredRoot)

                    with filesystem.open(posixpath.join(root, objectKey), "rb") as source:
                        content = source.read(size + 1)

                    if len(content) != size or hashlib.sha256(content).hexdigest() != digest:
                        raise ValueError("Metadata content identity mismatch.")

                except (OSError, ValueError) as error:
                    failures.append(f"backend {backendID}: {type(error).__name__}")
                    continue

                return content, {"sha256": digest, "size_bytes": size}

        reason = "; ".join(failures) or "no eligible storage locations"
        raise OSError(f"Cannot verify checkpoint {sessionID} {name}: {reason}")
    
    # ++++++++++++++++++++++ _selectAncestralReplayInput ++++++++++++++++++++++
    # Direct callers in this module: getSessionPipeline.
    @classmethod
    def _selectAncestralReplayInput(cls, session, checkpoints, postgres):
        """Validate root-to-current ancestry histories and choose the raw input.

        checkpoints contains records in root-to-current order, each with
        verified historyHashes.

        This checks recorded provenance consistency, not scientific equivalence
        or the absence of unrecorded in-memory mutations.
        """
        boundary = cls._getCheckpointHistoryBoundary(session)

        if boundary is None:
            raise ValueError("This working session has no verified checkpoint baseline. Reload its saved checkpoint before requesting ancestry-based extraction.")

        baseline = session._checkpointBaseline
        identity = cls._checkpointDatabaseIdentity(postgres)

        if baseline["databaseIdentity"] != identity:
            raise ValueError("Current PGL settings point to a different database than this session's checkpoint baseline.")

        if not checkpoints:
            raise ValueError("No checkpoint ancestry was supplied.")

        current = checkpoints[-1]

        if current["sessionID"] != baseline["sessionID"] or session.sessionID != baseline["sessionID"]:
            raise ValueError("Working session ID, baseline, and checkpoint ancestry do not agree.")

        if current["historyHashes"] != baseline["historyHashes"]:
            raise ValueError("Saved checkpoint history differs from the working session's baseline.")

        root = checkpoints[0]

        if root["origin"] != "raw" or root["parentSessionID"] is not None or root["rootSessionID"] != root["sessionID"]:
            raise ValueError("Replay ancestry does not begin with a parentless raw root.")

        # Both raw session contracts preserve an explicit history boundary.
        # Legacy raw behavior v1 does not, so it remains unsupported here.
        if root["contractVersion"] not in ("pgl.raw.session.v1", "pgl.raw.session.v2"):
            raise ValueError("Automatic ancestry replay requires a raw contract with recorded session history.")
        
        seen = set()
        previous = None

        for checkpoint in checkpoints:
            sessionID = checkpoint["sessionID"]

            if sessionID in seen:
                raise ValueError("Checkpoint ancestry contains a cycle or repeated checkpoint.")

            seen.add(sessionID)

            if checkpoint["status"] != "complete" or checkpoint["deletedAt"] is not None:
                raise ValueError(f"Replay ancestor {sessionID} is incomplete or deleted.")

            if checkpoint["rootSessionID"] != root["sessionID"]:
                raise ValueError("Checkpoint ancestry has inconsistent root IDs.")

            if previous is not None:
                if checkpoint["origin"] != "derived" or checkpoint["parentSessionID"] != previous["sessionID"]:
                    raise ValueError("Checkpoint ancestry contains a broken parent relationship.")

                prefix = previous["historyHashes"]
                childHistory = checkpoint["historyHashes"]

                if len(childHistory) < len(prefix) or childHistory[:len(prefix)] != prefix:
                    raise ValueError(f"Checkpoint {sessionID} does not preserve its parent's recorded history prefix. Refusing to infer a replay sequence.")

            previous = checkpoint

        inputRecord = {
            "version": 1,
            "kind": "checkpoint",
            "sessionID": root["sessionID"],
            "databaseIdentity": deepcopy(identity),
            "historyCount": len(root["historyHashes"]),
            "historyHashes": list(root["historyHashes"]),
        }

        cls._validatePipelineReplayInput(inputRecord)
        return inputRecord


    # -------------------------------------------------------------------------
    # Schema initialization, migrations, and application grants
    # -------------------------------------------------------------------------
    # Local administrator-only schema setup. Existing migration names and checksums remain
    # unchanged.

    # ++++++++++++++++++++++++++ _initDatabaseSchema ++++++++++++++++++++++++++
    # Direct callers in this module: initDatabase.
    @classmethod
    def _initDatabaseSchema(cls, postgres=None, *, settings=None, settingsName=None):
        """Apply schema migrations using saved administrator credentials.

        Returns False on missing configuration, cancellation, or an
        operational connection failure. Schema/ownership errors raise.
        """
        from .pglPostgres import pglPostgres

        if postgres is not None and (settings is not None or settingsName is not None):
            raise ValueError("Supply either postgres or PGL settings, not both.")

        if postgres is None:
            postgres = pglPostgres.fromSettings(settings=settings, settingsName=settingsName)

            if postgres is None:
                return False

        if not isinstance(postgres, pglPostgres):
            raise TypeError("postgres must be a pglPostgres instance.")

        postgres._validateValues()
        migrations = cls._readMigrations()

        try:
            with postgres._localConnect(database=postgres.databaseName) as connection:
                if connection is None:
                    return False

                with connection.transaction():
                    connection.execute("SELECT pg_advisory_xact_lock(%s)", (cls.MIGRATION_LOCK,))
                    cls._prepareSchema(connection, postgres)
                    applied = cls._applyMigrations(connection, postgres, migrations)
                    cls._grantApplicationAccess(connection, postgres)

        except psycopg.OperationalError as error:
            pglMessages.warning(f"Could not complete schema initialization for {postgres.databaseName!r}. If the connection was lost during commit, rerun initialization to check migration state.\n{error}", level=0)
            return False

        if applied:
            pglMessages.message(f"Applied migrations: {', '.join(applied)}")
        else:
            pglMessages.message("Database schema is already current.")

        pglMessages.message(f"Scientific schema ready: {postgres.databaseName}.{postgres.databaseSchema}")
        return True

    @staticmethod
    def _compareMigrationHistory(migrations, history):
        """Compare repository migrations with applied history without I/O.

        Returns a report containing every detected compatibility problem.
        An exact complete match is required for compatibility.

        Local migration metadata must itself be valid and consecutive.
        Database history problems are reported rather than repaired.

        Neither input is modified. SQL text is excluded from the report.
        """
        if not isinstance(migrations, (list, tuple)) or not migrations:
            raise ValueError("A nonempty repository migration inventory is required.")
        if not isinstance(history, (list, tuple)):
            raise TypeError("Migration history must be a list or tuple.")

        available = []

        for position, migration in enumerate(migrations, start=1):
            if not isinstance(migration, dict):
                raise ValueError("Repository migration records must be dictionaries.")

            version = migration.get("version")
            name = migration.get("name")
            checksum = migration.get("checksum")

            if type(version) is not int or version != position:
                raise ValueError("Repository migrations must be consecutive from version 1.")
            if not isinstance(name, str) or re.fullmatch(rf"{version:04d}_[a-z0-9_]+", name) is None:
                raise ValueError("Repository migration name disagrees with its version.")
            if not isinstance(checksum, str) or re.fullmatch(r"[0-9a-f]{64}", checksum) is None:
                raise ValueError("Repository migration checksum is invalid.")

            available.append({"version": version, "name": name, "checksum": checksum})

        applied = []
        issues = []

        def addIssue(code, message):
            issues.append({"code": code, "message": message})

        for row in history:
            if not isinstance(row, (list, tuple)) or len(row) != 3:
                addIssue("invalidHistory", "Migration history contains a malformed row.")
                continue

            version, name, checksum = row

            if (
                type(version) is not int or version < 1
                or not isinstance(name, str) or not name
                or not isinstance(checksum, str)
                or re.fullmatch(r"[0-9a-f]{64}", checksum) is None
            ):
                addIssue("invalidHistory", "Migration history contains invalid version/name/checksum values.")
                continue

            applied.append({"version": version, "name": name, "checksum": checksum})

        versions = [record["version"] for record in applied]
        consecutive = versions == list(range(1, len(applied) + 1))

        if not consecutive:
            addIssue(
                "nonconsecutiveHistory",
                "Database migration history is not consecutive from version 1. "
                "Review and repair migration history administratively; do not infer missing applications.",
            )

        availableByVersion = {record["version"]: record for record in available}

        for record in applied:
            expected = availableByVersion.get(record["version"])

            if expected is None:
                addIssue(
                    "databaseNewer",
                    f"Database migration {record['version']} is unknown to this checkout. "
                    "Update the client checkout to the database's migration set before proceeding.",
                )
                continue

            if record["name"] != expected["name"] or record["checksum"] != expected["checksum"]:
                addIssue(
                    "migrationMismatch",
                    f"Applied migration {record['version']} has a different name or checksum. "
                    "Restore the original applied migration file and introduce changes in a new migration. "
                    "Do not rewrite applied checksums to conceal the mismatch.",
                )

        # Call migrations 'pending' only when the applied inventory is a
        # verified prefix. Corrupt or newer history is not merely pending.
        pending = []
        if not issues and len(applied) < len(available):
            pending = [dict(record) for record in available[len(applied):]]
            addIssue(
                "pendingMigrations",
                "Required migrations are pending: "
                + ", ".join(record["name"] for record in pending)
                + ". Update PGL on the installation machine and run initialization there "
                "using that machine's local server settings. Do not blindly administer "
                "a remote destination from the exporting client.",
            )

        return {
            "compatible": not issues,
            "available": available,
            "applied": applied,
            "pending": pending,
            "issues": issues,
        }

    @staticmethod
    def _requireMigrationInspectionTransaction(connection):
        """Require a caller-owned transaction without changing its settings.

        Read-only inspection callers should use REPEATABLE READ, READ ONLY.
        Publication callers may revalidate inside their write transaction.

        This check performs no SQL and does not start or finish a transaction.
        """
        from psycopg.pq import TransactionStatus

        if connection.info.transaction_status != TransactionStatus.INTRANS:
            raise ValueError("Migration/identity inspection requires an active caller-owned transaction.")

    @classmethod
    def _inspectMigrationCompatibility(cls, connection, postgres, *, migrations=None):
        """Inspect configured schema and migration history using reads only.

        The caller owns the connection, snapshot, and transaction.
        No initialization, migration application, grants, or settings writes.

        Returns a compatibility report for accessible metadata.
        Missing schema/history and denied schema usage are explicit blockers.

        SQL permission, connection, and malformed-table errors propagate with
        their original categories. They must not be translated into 'pending
        migrations'. A SQL failure may abort the caller's transaction.

        A report is a snapshot, not authorization for later publication.
        Revalidate after approval under the eventual publication protocol.
        """
        from psycopg.rows import tuple_row

        cls._requireMigrationInspectionTransaction(connection)
        migrations = cls._readMigrations() if migrations is None else migrations

        # Validate the local inventory even when the configured schema is absent.
        report = cls._compareMigrationHistory(migrations, [])
        report.update({
            "schema": postgres.databaseSchema,
            "schemaExists": False,
            "historyExists": False,
        })

        def blocked(code, message):
            # No applied history was read; do not label it an empty database
            # with pending migrations.
            report.update({
                "compatible": False,
                "applied": None,
                "pending": [],
                "issues": [{"code": code, "message": message}],
            })
            return report

        with connection.cursor(row_factory=tuple_row) as cursor:
            cursor.execute("""
                SELECT namespace.oid,
                       pg_catalog.has_schema_privilege(namespace.oid, 'USAGE')
                FROM pg_catalog.pg_namespace AS namespace
                WHERE namespace.nspname = %s
            """, (postgres.databaseSchema,))
            schemaRecord = cursor.fetchone()

            if schemaRecord is None:
                return blocked(
                    "missingSchema",
                    "The configured scientific schema does not exist. Check database/schema "
                    "selection and installation state; no schema was created.",
                )

            report["schemaExists"] = True
            schemaOID, canUseSchema = schemaRecord

            if canUseSchema is not True:
                return blocked(
                    "schemaAccessDenied",
                    "The connected role lacks USAGE on the configured schema. "
                    "Fix access permissions; this is not a pending-migration diagnosis.",
                )

            cursor.execute("""
                SELECT relation.relkind
                FROM pg_catalog.pg_class AS relation
                WHERE relation.relnamespace = %s
                  AND relation.relname = 'schema_migrations'
            """, (schemaOID,))
            historyRecord = cursor.fetchone()

            if historyRecord is None:
                return blocked(
                    "missingHistory",
                    "The configured schema has no migration history table. "
                    "Review configuration and installation state administratively; "
                    "compatibility cannot be inferred from existing scientific tables.",
                )

            report["historyExists"] = True

            if historyRecord != ("r",):
                return blocked(
                    "invalidHistoryRelation",
                    "schema_migrations is not an ordinary table matching the migration runner's contract.",
                )

            # Do not suppress SELECT permission failures or infer empty history
            # from inaccessible metadata.
            table = sql.Identifier(postgres.databaseSchema, "schema_migrations")
            cursor.execute(sql.SQL("SELECT version, name, checksum FROM {} ORDER BY version").format(table))
            history = cursor.fetchall()

        compared = cls._compareMigrationHistory(migrations, history)
        report.update(compared)
        return report

    @classmethod
    def _readStableDatabaseID(cls, connection, postgres):
        """Read the persistent scientific-schema UUID without generating one.

        The caller must first establish migration compatibility and own the
        transaction. This helper reads identity only; it does not certify
        migration compatibility by itself.

        Returns a canonical UUID string.
        Missing/inaccessible tables propagate their original SQL errors.
        Missing or malformed identity rows raise ValueError.

        Restored continuations retain identity. Independently writable clones
        are not distinguishable merely because they copied this UUID.
        """
        from psycopg.rows import tuple_row

        cls._requireMigrationInspectionTransaction(connection)
        table = sql.Identifier(postgres.databaseSchema, "schema_identity")

        with connection.cursor(row_factory=tuple_row) as cursor:
            cursor.execute(sql.SQL("SELECT singleton, database_id::text FROM {}").format(table))
            rows = cursor.fetchall()

        if len(rows) != 1 or rows[0][0] is not True:
            raise ValueError("Scientific schema must contain exactly one valid identity row.")

        databaseID = rows[0][1]
        if not isinstance(databaseID, str):
            raise ValueError("Scientific schema identity must be a canonical UUID string.")

        try:
            canonicalID = str(uuid.UUID(databaseID))
        except (ValueError, AttributeError):
            raise ValueError("Scientific schema identity contains an invalid UUID.") from None

        if canonicalID != databaseID or uuid.UUID(databaseID).int == 0:
            raise ValueError("Scientific schema identity must be a canonical nonzero UUID.")

        return databaseID
    
    

    # ++++++++++++++++++++++++++++ _readMigrations ++++++++++++++++++++++++++++
    # Direct callers in this module: _initDatabaseSchema.
    @classmethod
    def _readMigrations(cls):
        """Read and checksum the SQL migration files shipped with pglStorage."""
        directory = Path(pglInfo.getPGLDir()) / "database" / "migrations"

        if not directory.is_dir():
            raise FileNotFoundError(f"Migration directory not found: {directory}")

        migrations = []

        for path in sorted(directory.glob("*.sql")):
            match = re.fullmatch(r"(\d{4})_([a-z0-9_]+)\.sql", path.name)

            if match is None:
                raise ValueError(f"Invalid migration filename: {path.name}")

            content = path.read_bytes()

            migrations.append({
                "version": int(match.group(1)),
                "name": path.stem,
                "checksum": hashlib.sha256(content).hexdigest(),
                "sql": content.decode("utf-8"),
            })

        if not migrations:
            raise ValueError(f"No SQL migrations found in {directory}")

        versions = [migration["version"] for migration in migrations]

        if versions != list(range(1, len(migrations) + 1)):
            raise ValueError("Migration numbers must be unique and consecutive, starting at 0001.")

        return migrations

    # +++++++++++++++++++++++++++++ _prepareSchema ++++++++++++++++++++++++++++
    # Direct callers in this module: _initDatabaseSchema.
    @classmethod
    def _prepareSchema(cls, connection, postgres):
        """Ensure an administrator-owned schema and migration history table."""
        actualAdmin = connection.execute("SELECT current_user").fetchone()[0]

        if actualAdmin != postgres.adminUser:
            raise RuntimeError(f"Connected as {actualAdmin!r}, not configured administrator {postgres.adminUser!r}.")

        role = connection.execute("SELECT rolsuper, rolcreatedb, rolcreaterole, rolreplication, rolbypassrls, rolcanlogin FROM pg_roles WHERE rolname = %s", (postgres.databaseUser,)).fetchone()

        if role is None:
            raise RuntimeError("Application role is missing. Run postgres.createDatabase() first.")

        if any(role[:5]) or not role[5]:
            raise RuntimeError("Application role has unexpected privileges or cannot log in.")

        memberships = connection.execute("SELECT 1 FROM pg_auth_members WHERE member = (SELECT oid FROM pg_roles WHERE rolname = %s) LIMIT 1", (postgres.databaseUser,)).fetchone()

        if memberships is not None:
            raise RuntimeError("Application role has role memberships requiring review.")

        schema = sql.Identifier(postgres.databaseSchema)
        admin = sql.Identifier(postgres.adminUser)
        application = sql.Identifier(postgres.databaseUser)

        schemaOwner = connection.execute("SELECT pg_get_userbyid(nspowner) FROM pg_namespace WHERE nspname = %s", (postgres.databaseSchema,)).fetchone()

        if schemaOwner is None:
            connection.execute(sql.SQL("CREATE SCHEMA {} AUTHORIZATION {}").format(schema, admin))
        elif schemaOwner[0] != postgres.adminUser:
            raise RuntimeError(f"Schema {postgres.databaseSchema!r} is owned by {schemaOwner[0]!r}, not {postgres.adminUser!r}. Ownership will not be changed automatically.")

        connection.execute(sql.SQL("REVOKE CREATE ON SCHEMA {} FROM PUBLIC").format(schema))
        connection.execute(sql.SQL("REVOKE CREATE ON SCHEMA {} FROM {}").format(schema, application))

        # All unqualified objects in migration SQL belong to this schema.
        connection.execute(sql.SQL("SET LOCAL search_path TO {}, pg_catalog").format(schema))

        migrationTable = sql.Identifier(postgres.databaseSchema, "schema_migrations")

        connection.execute(sql.SQL("""
            CREATE TABLE IF NOT EXISTS {} (
                version integer PRIMARY KEY CHECK (version > 0),
                name text NOT NULL UNIQUE,
                checksum char(64) NOT NULL CHECK (checksum ~ '^[0-9a-f]{{64}}$'),
                applied_at timestamptz NOT NULL DEFAULT now(),
                applied_by text NOT NULL DEFAULT current_user
            )
        """).format(migrationTable))

    @classmethod
    def status(cls, postgres=None, *, settings=None, settingsName=None):
        """Print application connectivity and migration status; return None.

        Uses default PGL settings unless settings or settingsName is supplied.
        An explicit postgres object may be supplied instead.

        Opens the configured application connection, including SSH transport,
        and reads migration history. Does not install, initialize, start,
        create, migrate, or change database permissions.

        Reads the saved application password, or prompts if none is available.
        Never saves or deletes PostgreSQL credentials. A rejected password is
        attempted once; rerun the check after correcting the credentials.

        Successful connection confirms PostgreSQL is reachable and accepting
        application connections. Failure does not prove the server is stopped.

        Migration status reflects recorded history and shipped migration files;
        it does not audit every schema object or application permission.
        """
        from .pglPostgres import pglPostgres

        if postgres is not None and (settings is not None or settingsName is not None):
            raise ValueError("Supply either postgres or PGL settings, not both.")

        if postgres is None:
            postgres = pglPostgres.fromSettings(settings=settings, settingsName=settingsName)

            if postgres is None:
                pglMessages.warning("PostgreSQL configuration unavailable. Connectivity and migrations were not checked.")
                return

        if not isinstance(postgres, pglPostgres):
            raise TypeError("postgres must be a pglPostgres instance.")

        postgres._validateValues()
        pglMessages.message("✅ PostgreSQL configuration loaded and valid.")
        pglMessages.message(f"Database: {postgres.databaseName}.{postgres.databaseSchema}")
        pglMessages.message(f"Endpoint: {postgres.connectionHost}:{postgres.connectionPort} ({postgres.connectionTransport})")

        # Read credentials ourselves so connect() cannot delete a rejected
        # saved password or save a newly entered one during a status check.
        password = None

        try:
            service, databaseUser = postgres._passwordStoreIdentity(user=postgres.databaseUser)

            try:
                store = postgres._passwordStore()
                password = store.get_password(service, databaseUser)
            except Exception as error:
                pglMessages.warning(f"Could not read the saved PostgreSQL password ({type(error).__name__}). Please enter it instead.", level=1)

            if not password:
                password = postgres._askPassword(f"PostgreSQL password for {databaseUser}: ")

            if not password:
                pglMessages.message("Database check cancelled. Connectivity and migrations were not checked.")
                return

            # Explicit credentials get one attempt, without credential-store
            # writes, deletion, or PostgreSQL authentication retries.
            with postgres.connect(password=password, rememberPassword=False, useSavedPassword=False) as connection:
                password = None

                if connection is None:
                    pglMessages.message("Database check cancelled. Connectivity and migrations were not checked.")
                    return

                pglMessages.message("✅ PostgreSQL is reachable and accepting connections.")
                pglMessages.message("✅ Application database and configured schema are accessible.")

                try:
                    migrations = cls._readMigrations()
                except (OSError, ValueError) as error:
                    pglMessages.warning(f"Could not read the available migrations. Migration status is unknown.\n{error}")
                    return

                migrationTable = sql.Identifier(postgres.databaseSchema, "schema_migrations")

                # Read only: never prepare a missing schema/history table.
                try:
                    history = connection.execute(sql.SQL("SELECT version, name, checksum FROM {} ORDER BY version").format(migrationTable)).fetchall()
                except psycopg.errors.UndefinedTable:
                    pglMessages.warning("Migration history table is missing. Schema migration status cannot be verified.")
                    return
                except psycopg.Error as error:
                    pglMessages.warning(f"Could not read migration history. Migration status is unknown.\n{error}")
                    return

                availableVersions = [migration["version"] for migration in migrations]
                appliedVersions = [row[0] for row in history]

                # Match the migration runner's prefix check: reject gaps,
                # unknown versions, and history ahead of this installation.
                if appliedVersions != availableVersions[:len(appliedVersions)]:
                    pglMessages.warning("Database migration history does not match the available migration files. Check that the correct pgl version is installed.")
                    return

                appliedByVersion = {version: (name, checksum) for version, name, checksum in history}

                for migration in migrations:
                    version = migration["version"]

                    if version in appliedByVersion:
                        expected = (migration["name"], migration["checksum"])

                        if appliedByVersion[version] != expected:
                            pglMessages.warning(f"Previously applied migration has changed: {migration['name']}. Restore the original file and put changes in a new migration.")
                            return

                pendingMigrations = [migration["name"] for migration in migrations if migration["version"] not in appliedByVersion]

                if pendingMigrations:
                    pendingText = "\n".join(f"    {migrationName}" for migrationName in pendingMigrations)
                    pglMessages.warning(
                        f"Schema is not up to date: {len(pendingMigrations)} pending migration(s).\n"
                        f"{pendingText}\n"
                        "Run pglDatabase.applyMigrations(...) on the installation machine with the matching local configuration."
                    )
                else:
                    pglMessages.message(f"✅ Schema is up to date: {len(history)} migration(s) verified.")

        except psycopg.OperationalError as error:
            pglMessages.warning(f"Could not complete the database connection check. Migration status is unknown; this does not necessarily mean PostgreSQL is stopped.\n{error}")
        except RuntimeError as error:
            # connect() validates database identity and schema access before
            # yielding. Such a failure does not establish that the server is down.
            pglMessages.warning(f"Database connection validation failed. Migration status is unknown.\n{error}")
        finally:
            # Drop this local reference; Python does not guarantee secure erasure.
            password = None

    @classmethod
    def applyMigrations(cls, postgres=None, *, settings=None, settingsName=None):
        """Apply schema migrations using saved administrator credentials.

        Uses default PGL settings unless settings or settingsName is supplied.
        An explicit postgres object may be supplied instead.

        Runs the existing schema preparation, migration, and application-access
        steps. Does not call the server installation, initialization, startup,
        or database-creation methods.

        Returns True on success, including when no migrations are pending.
        Returns False on missing configuration, cancellation, or an operational
        connection failure. Schema/ownership errors raise.

        Uses the existing local administrator connection path; this does not
        add support for remote migration administration.
        """
        return cls._initDatabaseSchema(postgres=postgres, settings=settings, settingsName=settingsName)

    # ++++++++++++++++++++++++++++ _applyMigrations +++++++++++++++++++++++++++
    # Direct callers in this module: _initDatabaseSchema.
    @classmethod
    def _applyMigrations(cls, connection, postgres, migrations):
        """Validate history and apply pending migrations in the caller's transaction."""
        migrationTable = sql.Identifier(postgres.databaseSchema, "schema_migrations")
        history = connection.execute(sql.SQL("SELECT version, name, checksum FROM {} ORDER BY version").format(migrationTable)).fetchall()

        availableVersions = [migration["version"] for migration in migrations]
        appliedVersions = [row[0] for row in history]

        if appliedVersions != availableVersions[:len(appliedVersions)]:
            raise RuntimeError("Database migration history does not match the available migration files. Check that the correct pgl version is installed.")

        appliedByVersion = {version: (name, checksum) for version, name, checksum in history}

        # Verify all applied migrations before running any new ones.
        for migration in migrations:
            version = migration["version"]

            if version in appliedByVersion:
                expected = (migration["name"], migration["checksum"])

                if appliedByVersion[version] != expected:
                    raise RuntimeError(f"Previously applied migration has changed: {migration['name']}. Restore the original file and put changes in a new migration.")

        newlyApplied = []

        for migration in migrations:
            if migration["version"] in appliedByVersion:
                continue

            # Migration files are trusted repository code, not user input.
            connection.execute(migration["sql"], prepare=False)
            connection.execute(sql.SQL("INSERT INTO {} (version, name, checksum) VALUES (%s, %s, %s)").format(migrationTable), (migration["version"], migration["name"], migration["checksum"]))
            newlyApplied.append(migration["name"])

        return newlyApplied

    # ++++++++++++++++++++++++ _grantApplicationAccess ++++++++++++++++++++++++
    # Direct callers in this module: _initDatabaseSchema.
    # Refactor correction: explicitly grant application access to session_products.
    @classmethod
    def _grantApplicationAccess(cls, connection, postgres):
        """Grant application access after pending migrations are applied.

        Dataset products and membership are protected by publication guards.
        Matrix revision records permit registration and reads, not mutation.
        Reporting views, migration history, and schema identity are read-only.

        Stable identity changes require an explicit administrative procedure;
        ordinary application publication cannot replace the schema UUID.
        """
        schema = sql.Identifier(postgres.databaseSchema)
        application = sql.Identifier(postgres.databaseUser)

        connection.execute(sql.SQL("GRANT USAGE ON SCHEMA {} TO {}").format(schema, application))

        applicationTables = [
            "users",
            "subjects",
            "storage_backends",
            "files",
            "storage_locations",
            "session",
            "session_files",
            "session_products",
            "session_deletion_groups",
            "session_deletion_group_members",
            "dataset",
            "dataset_members",
            "dataset_products",
        ]

        for name in applicationTables:
            table = sql.Identifier(postgres.databaseSchema, name)
            connection.execute(sql.SQL("GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE {} TO {}").format(table, application))

        # Published matrix records and export mappings are append-only.
        # Triggers additionally reject row mutation by broader-permission callers.
        for name in ("matrix_revisions", "session_export_mappings"):
            table = sql.Identifier(postgres.databaseSchema, name)
            connection.execute(sql.SQL("REVOKE ALL PRIVILEGES ON TABLE {} FROM {}").format(table, application))
            connection.execute(sql.SQL("GRANT SELECT, INSERT ON TABLE {} TO {}").format(table, application))

        readOnlyTables = [
            "schema_migrations",
            "schema_identity",
            "session_subjects",
            "raw_sessions",
            "session_subjects_including_deleted",
            "raw_sessions_including_deleted",
        ]

        for name in readOnlyTables:
            table = sql.Identifier(postgres.databaseSchema, name)
            connection.execute(sql.SQL("REVOKE ALL PRIVILEGES ON TABLE {} FROM {}").format(table, application))
            connection.execute(sql.SQL("GRANT SELECT ON TABLE {} TO {}").format(table, application))

        connection.execute(sql.SQL("GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA {} TO {}").format(schema, application))

    @classmethod
    def _inspectCheckpointReference(cls, connection, postgres, reference, *, includeDeleted=False):
        """Inspect a qualified checkpoint reference in the caller's database.

        Caller responsibilities:
            Establish migration compatibility first.
            Own a consistent transaction.
            Apply verification policy before authorizing foreign reuse/load.

        Local references resolve directly by stable schema UUID.
        Foreign references resolve only through session_export_mappings.
        A missing foreign mapping never falls back to a same-numbered local ID.

        Returns metadata and explicit destination state. Foreign verification
        evidence is returned unchanged for a separate validator; its presence
        alone does not establish payload equivalence or trusted provenance.

        includeDeleted controls inspection visibility, not restoration.
        Incomplete checkpoints are always reported as blocked.

        Does not load scientific objects, open payloads, change records,
        start/commit transactions, or resolve database profiles.
        SQL access errors propagate rather than being reported as no match.
        """
        from psycopg.rows import tuple_row
        from uuid import UUID

        if type(includeDeleted) is not bool:
            raise ValueError("includeDeleted must be Boolean.")

        if type(reference) is not dict or set(reference) != {"databaseID", "sessionID", "databaseName"}:
            raise ValueError("Expected a database-qualified checkpoint reference.")

        databaseID = reference["databaseID"]
        if not isinstance(databaseID, str):
            raise ValueError("databaseID must be a canonical UUID string.")

        try:
            parsedID = UUID(databaseID)
        except (ValueError, AttributeError):
            raise ValueError("Invalid databaseID.") from None

        if str(parsedID) != databaseID or parsedID.int == 0:
            raise ValueError("databaseID must be canonical and nonzero.")

        sourceSessionID = reference["sessionID"]
        if type(sourceSessionID) is not int or not 0 <= sourceSessionID <= 9223372036854775807:
            raise ValueError("sessionID must be a nonnegative PostgreSQL bigint.")

        databaseName = reference["databaseName"]
        if (
            not isinstance(databaseName, str) or not databaseName.strip()
            or any(character in databaseName for character in ("\x00", "\n", "\r"))
        ):
            raise ValueError("databaseName must be a nonblank profile label without NUL or newlines.")

        # This checks transaction ownership and reads actual schema identity.
        # Profile labels and connection endpoints never determine localness.
        destinationDatabaseID = cls._readStableDatabaseID(connection, postgres)
        local = databaseID == destinationDatabaseID
        result = {
            "reference": deepcopy(reference),
            "destinationDatabaseID": destinationDatabaseID,
            "resolutionKind": "local" if local else "exportMapping",
            "destinationSessionID": None,
            "state": None,
            "checkpoint": None,
            "mapping": None,
            "requiresVerification": not local,
        }

        sessions = sql.Identifier(postgres.databaseSchema, "session")
        mappings = sql.Identifier(postgres.databaseSchema, "session_export_mappings")

        with connection.cursor(row_factory=tuple_row) as cursor:
            if local:
                destinationSessionID = sourceSessionID
            else:
                statement = sql.SQL("""
                    SELECT destination_session_id, source_database_name,
                           source_manifest_hash, destination_manifest_hash,
                           source_contract_version, destination_contract_version,
                           verification, registered_by, registered_at
                    FROM {}
                    WHERE source_database_id = %s::uuid
                      AND source_session_id = %s
                """).format(mappings)
                cursor.execute(statement, (databaseID, sourceSessionID))
                mappingRow = cursor.fetchone()

                if mappingRow is None:
                    result["state"] = "unmapped"
                    return result

                mappingNames = (
                    "destinationSessionID", "sourceDatabaseName",
                    "sourceManifestHash", "destinationManifestHash",
                    "sourceContractVersion", "destinationContractVersion",
                    "verification", "registeredBy", "registeredAt",
                )
                result["mapping"] = deepcopy(dict(zip(mappingNames, mappingRow)))
                destinationSessionID = mappingRow[0]

            result["destinationSessionID"] = destinationSessionID
            statement = sql.SQL("""
                SELECT status, deleted_at, manifest_hash, contract_version,
                       checkpoint_name, description, completed_at,
                       parent_session_id, root_session_id
                FROM {}
                WHERE session_id = %s
            """).format(sessions)
            cursor.execute(statement, (destinationSessionID,))
            checkpointRow = cursor.fetchone()

        if checkpointRow is None:
            result["state"] = "missingDestination"
            return result

        checkpointNames = (
            "status", "deletedAt", "manifestHash", "contractVersion",
            "checkpointName", "description", "completedAt",
            "parentSessionID", "rootSessionID",
        )
        checkpoint = dict(zip(checkpointNames, checkpointRow))
        result["checkpoint"] = checkpoint

        # Validate catalog correspondence even for a hidden/deleted row.
        mapping = result["mapping"]
        if mapping is not None and (
            mapping["destinationManifestHash"] != checkpoint["manifestHash"]
            or mapping["destinationContractVersion"] != checkpoint["contractVersion"]
        ):
            result["state"] = "inconsistentMapping"
        elif checkpoint["status"] != "complete":
            result["state"] = "incompleteDestination"
        elif checkpoint["manifestHash"] is None or checkpoint["completedAt"] is None:
            result["state"] = "invalidCompletion"
        elif checkpoint["deletedAt"] is not None and not includeDeleted:
            result["state"] = "deletedDestination"
        else:
            # 'candidate' means catalog-eligible only. In particular, foreign
            # mappings still require evidence validation before resolution.
            result["state"] = "candidate"

        return result

    @classmethod
    def _readExportAncestry(cls, connection, postgres, sessionID, *, maxCheckpoints=10000):
        """Read active completed ancestry in raw-root-to-selected order.

        Requires a caller-owned REPEATABLE READ or SERIALIZABLE, READ ONLY
        transaction. Does not start, commit, or change transaction settings.

        Follows parent links only. Siblings and dataset memberships are not
        included. Historical action-input dependencies are inspected separately.

        Validates:
            Session IDs and noncyclic ancestry.
            Active completed status.
            Raw-root and derived-parent relationships.
            Consistent root IDs, manifest hashes, and publication timestamps.

        Returns independent catalog metadata dictionaries. Contract support,
        manifest bytes, file/product inventories, and source dependencies
        require subsequent inspection; this helper does not establish them.

        No payload access, SQL writes, or explicit publication locks.
        SQL errors propagate. Missing/deleted/incomplete ancestors block export.
        """
        from psycopg.rows import tuple_row

        if type(sessionID) is not int or not 0 <= sessionID <= 9223372036854775807:
            raise ValueError("sessionID must be a nonnegative PostgreSQL bigint.")
        if type(maxCheckpoints) is not int or maxCheckpoints <= 0:
            raise ValueError("maxCheckpoints must be a positive integer.")

        cls._requireMigrationInspectionTransaction(connection)
        table = sql.Identifier(postgres.databaseSchema, "session")
        names = (
            "sessionID", "parentSessionID", "rootSessionID",
            "origin", "kind", "status", "deletedAt",
            "contractVersion", "manifestHash", "checkpointName",
            "description", "completedAt", "createdBy",
        )
        statement = sql.SQL("""
            SELECT session_id, parent_session_id, root_session_id,
                   origin, kind, status, deleted_at,
                   contract_version, manifest_hash, checkpoint_name,
                   description, completed_at, created_by
            FROM {}
            WHERE session_id = %s
        """).format(table)

        records = []
        visited = set()
        currentID = sessionID

        with connection.cursor(row_factory=tuple_row) as cursor:
            cursor.execute("SHOW transaction_isolation")
            isolation = cursor.fetchone()[0]
            cursor.execute("SHOW transaction_read_only")
            readOnly = cursor.fetchone()[0]

            if isolation not in ("repeatable read", "serializable") or readOnly != "on":
                raise ValueError("Export ancestry inspection requires a consistent read-only transaction.")

            while currentID is not None:
                if currentID in visited:
                    raise ValueError("Export ancestry contains a cycle.")
                if len(records) >= maxCheckpoints:
                    raise ValueError("Export ancestry exceeds maxCheckpoints; review its depth before increasing the limit.")

                visited.add(currentID)
                cursor.execute(statement, (currentID,))
                row = cursor.fetchone()
                if row is None:
                    raise ValueError(f"Required export checkpoint {currentID} does not exist.")

                record = dict(zip(names, row))
                if type(record["sessionID"]) is not int or record["sessionID"] != currentID:
                    raise ValueError("Export ancestry lookup returned an inconsistent checkpoint ID.")

                for field in ("rootSessionID", "createdBy"):
                    value = record[field]
                    if type(value) is not int or not 0 <= value <= 9223372036854775807:
                        raise ValueError(f"Checkpoint {currentID}: invalid {field}.")

                parentID = record["parentSessionID"]
                if parentID is not None and (type(parentID) is not int or not 0 <= parentID <= 9223372036854775807):
                    raise ValueError(f"Checkpoint {currentID}: invalid parent ID.")

                if record["deletedAt"] is not None:
                    raise ValueError(f"Required export checkpoint {currentID} is deleted.")
                if record["status"] != "complete":
                    raise ValueError(f"Required export checkpoint {currentID} is incomplete.")

                digest = record["manifestHash"]
                if not isinstance(digest, str) or re.fullmatch(r"[0-9a-f]{64}", digest) is None:
                    raise ValueError(f"Checkpoint {currentID}: invalid manifest hash.")

                completedAt = record["completedAt"]
                if completedAt is None or not callable(getattr(completedAt, "utcoffset", None)) or completedAt.utcoffset() is None:
                    raise ValueError(f"Checkpoint {currentID}: missing or invalid completion timestamp.")

                contract = record["contractVersion"]
                if not isinstance(contract, str) or not contract.strip():
                    raise ValueError(f"Checkpoint {currentID}: missing contract version.")

                if record["origin"] == "raw":
                    if record["kind"] != "acquired" or parentID is not None or record["rootSessionID"] != currentID:
                        raise ValueError(f"Checkpoint {currentID}: invalid raw-root lineage.")
                elif record["origin"] == "derived":
                    if record["kind"] != "processed" or parentID is None or parentID == currentID or record["rootSessionID"] == currentID:
                        raise ValueError(f"Checkpoint {currentID}: invalid derived lineage.")
                else:
                    raise ValueError(f"Checkpoint {currentID}: unsupported origin.")

                records.append(record)
                currentID = parentID

        records.reverse()
        root = records[0]
        if root["origin"] != "raw":
            raise ValueError("Export ancestry does not begin with a raw root.")

        for position, record in enumerate(records):
            if record["rootSessionID"] != root["sessionID"]:
                raise ValueError("Export ancestry has inconsistent root IDs.")
            if position and record["parentSessionID"] != records[position - 1]["sessionID"]:
                raise ValueError("Export ancestry has a broken parent chain.")

        return records

    @classmethod
    def _readExportCheckpointManifest(cls, connection, postgres, checkpoint, *, storageOptionsByBackend=None):
        """Read a saved export manifest and verify its exact catalog inventory.

        checkpoint:
            One record returned by _readExportAncestry() in the same snapshot.

        Requires a consistent read-only transaction. Migration compatibility
        must already have been established by the enclosing export coordinator.

        Uses the existing verified metadata reader, canonical encoding,
        manifest validators, and matrix-link verifier.

        Checks every file link, including manifest.json, against its expected
        identity and role. Deleted links/content and unexpected links block
        export rather than disappearing through query filtering.

        Returns the verified manifest without constructing scientific objects.
        Reads manifest bytes only, not history or scientific payload arrays.
        Does not establish current availability of every payload or verify
        complete matrix-bundle bytes. Those are subsequent inventory steps.

        Does not write SQL, copy files, or retain a SQL/payload connection.
        """
        from psycopg.rows import tuple_row

        cls._requireMigrationInspectionTransaction(connection)

        if type(checkpoint) is not dict:
            raise TypeError("checkpoint must be an ancestry record.")

        sessionID = checkpoint.get("sessionID")
        if type(sessionID) is not int or not 0 <= sessionID <= 9223372036854775807:
            raise ValueError("Checkpoint sessionID must be a nonnegative PostgreSQL bigint.")

        expectedHash = checkpoint.get("manifestHash")
        if not isinstance(expectedHash, str) or re.fullmatch(r"[0-9a-f]{64}", expectedHash) is None:
            raise ValueError("Checkpoint ancestry record has an invalid manifest hash.")

        origin = checkpoint.get("origin")
        contract = checkpoint.get("contractVersion")
        if origin not in ("raw", "derived"):
            raise ValueError("Unsupported export checkpoint origin.")
        if not isinstance(contract, str) or not contract:
            raise ValueError("Missing export checkpoint contract.")

        sessions = sql.Identifier(postgres.databaseSchema, "session")
        links = sql.Identifier(postgres.databaseSchema, "session_files")
        files = sql.Identifier(postgres.databaseSchema, "files")

        with connection.cursor(row_factory=tuple_row) as cursor:
            cursor.execute("SHOW transaction_isolation")
            isolation = cursor.fetchone()[0]
            cursor.execute("SHOW transaction_read_only")
            readOnly = cursor.fetchone()[0]
            if isolation not in ("repeatable read", "serializable") or readOnly != "on":
                raise ValueError("Export manifest inspection requires a consistent read-only transaction.")

            # Do not trust a caller-supplied ancestry record without checking
            # that it describes this checkpoint in the current SQL snapshot.
            cursor.execute(sql.SQL("""
                SELECT origin, contract_version, manifest_hash, status, deleted_at
                FROM {} WHERE session_id = %s
            """).format(sessions), (sessionID,))
            if cursor.fetchone() != (origin, contract, expectedHash, "complete", None):
                raise ValueError("Export ancestry record differs from the active completed checkpoint.")

        content, identity = cls._readReplayMetadataFile(
            connection,
            postgres,
            sessionID,
            "manifest.json",
            storageOptionsByBackend=storageOptionsByBackend,
            maxBytes=16 * 1024 * 1024,
        )
        if identity != {"sha256": expectedHash, "size_bytes": len(content)}:
            raise ValueError("Export manifest identity differs from checkpoint ancestry.")
        if hashlib.sha256(content).hexdigest() != expectedHash:
            raise ValueError("Export manifest bytes differ from checkpoint ancestry.")

        manifest = json.loads(content)
        if not isinstance(manifest, dict):
            raise ValueError("Export manifest must contain a JSON object.")
        if cls.encodeRawManifest(manifest) != content:
            raise ValueError("Export manifest is not canonically encoded.")
        if manifest.get("contract_version") != contract:
            raise ValueError("Export manifest contract differs from its catalog record.")

        if (origin, contract) == ("raw", "pgl.raw.behavior.v1"):
            cls.validateRawManifest(manifest)
        else:
            cls._validateSessionBundleManifest(manifest, origin=origin)

        payloadRole = "acquisition" if origin == "raw" else "derived"
        expectedFiles = {
            record["name"]: (
                record["sha256"],
                record["size_bytes"],
                "history" if record["name"] == "history.json" else payloadRole,
            )
            for record in manifest["files"]
        }
        expectedFiles["manifest.json"] = (expectedHash, len(content), "manifest")

        with connection.cursor(row_factory=tuple_row) as cursor:
            # LEFT JOIN makes a missing content row an explicit integrity
            # failure, even if an externally altered schema lost its FK.
            cursor.execute(sql.SQL("""
                SELECT link.name, content.file_id, content.sha256,
                       content.size_bytes, link.role,
                       link.deleted_at, content.deleted_at
                FROM {} AS link
                LEFT JOIN {} AS content ON content.file_id = link.file_id
                WHERE link.session_id = %s
                ORDER BY link.name
            """).format(links, files), (sessionID,))
            rows = cursor.fetchall()

        actualFiles = {}
        for name, fileID, digest, size, role, linkDeletedAt, contentDeletedAt in rows:
            if name in actualFiles:
                raise ValueError("Export checkpoint contains duplicate logical file links.")
            if fileID is None:
                raise ValueError(f"Export checkpoint file {name!r} has no content identity.")
            if linkDeletedAt is not None or contentDeletedAt is not None:
                raise ValueError(f"Export checkpoint file {name!r} has a deleted link or content identity.")
            actualFiles[name] = (digest, size, role)

        if actualFiles != expectedFiles:
            raise ValueError("Export checkpoint file links do not exactly match its manifest.")

        # An empty declaration must still reject hidden extra product links.
        # Existing validation supports legacy and MRI owner-aware records.
        cls._verifySessionProducts(connection, postgres, sessionID, manifest.get("products", []))
        return manifest
    
    @classmethod
    def _readExportFileInventory(cls, connection, postgres, checkpoint, *, storageOptionsByBackend=None):
        """Inventory checkpoint files and eligible registered source locations.

        Reuses _readExportCheckpointManifest() for snapshot, contract, manifest,
        exact file-link, and matrix-link validation.

        Includes manifest.json itself and preserves logical roles/subjects.
        Locations are catalog-eligible candidates, not newly verified bytes.
        Missing candidates block export; failed access must not silently
        substitute unrelated paths or a same-numbered backend elsewhere.

        Returns:
            manifest: Verified saved manifest.
            files: Sorted logical file records with content IDs and locations.
            logicalBytes: Sum over logical links, including repeated content.
            uniqueContentBytes: Sum over distinct file IDs in this checkpoint.
            matrixInventoryComplete: False; separate bundle inventory required.

        Byte counts are file-only and are not total export-size estimates.
        Matrix bundles are not included in session_files.

        Reads manifest bytes and SQL metadata only. Does not open scientific
        payloads, connect to candidate locations, write records, or copy files.
        Caller owns the consistent read-only transaction and migration checks.
        """
        from psycopg.rows import tuple_row

        manifest = cls._readExportCheckpointManifest(
            connection,
            postgres,
            checkpoint,
            storageOptionsByBackend=storageOptionsByBackend,
        )
        sessionID = checkpoint["sessionID"]
        links = sql.Identifier(postgres.databaseSchema, "session_files")
        files = sql.Identifier(postgres.databaseSchema, "files")
        locations = sql.Identifier(postgres.databaseSchema, "storage_locations")
        backends = sql.Identifier(postgres.databaseSchema, "storage_backends")

        with connection.cursor(row_factory=tuple_row) as cursor:
            cursor.execute(sql.SQL("""
                SELECT link.name, content.file_id, content.sha256,
                       content.size_bytes, link.role, link.subject_id
                FROM {} AS link
                JOIN {} AS content ON content.file_id = link.file_id
                WHERE link.session_id = %s
                ORDER BY link.name
            """).format(links, files), (sessionID,))
            fileRows = cursor.fetchall()
            fileIDs = sorted({row[1] for row in fileRows})

            # Prior validation established an exact nonempty inventory,
            # including the manifest. Do not turn missing links into an
            # apparently successful empty transfer.
            if not fileIDs:
                raise ValueError("Export checkpoint has no registered file inventory.")

            cursor.execute(sql.SQL("""
                SELECT location.file_id, backend.backend_id,
                       backend.name, backend.kind, backend.url_prefix,
                       location.object_key, location.priority,
                       location.verified_at
                FROM {} AS location
                JOIN {} AS backend ON backend.backend_id = location.backend_id
                WHERE location.file_id = ANY(%s::bigint[])
                  AND location.deleted_at IS NULL
                  AND location.status = 'present'
                  AND location.verified_at IS NOT NULL
                  AND backend.is_active
                ORDER BY location.file_id, location.priority,
                         backend.backend_id, location.object_key
            """).format(locations, backends), (fileIDs,))
            locationRows = cursor.fetchall()

        locationsByFile = {}
        for fileID, backendID, backendName, kind, root, key, priority, verifiedAt in locationRows:
            if (
                not isinstance(key, str) or not key
                or key.startswith("/") or "\\" in key or "\x00" in key
                or any(part in ("", ".", "..") for part in key.split("/"))
            ):
                raise ValueError("Export source contains an invalid storage object key.")
            if (
                not isinstance(root, str) or not root.strip()
                or any(character in root for character in ("\x00", "\n", "\r"))
            ):
                raise ValueError("Export source contains an invalid registered storage root.")

            locationsByFile.setdefault(fileID, []).append({
                "backendID": backendID,
                "backendName": backendName,
                "backendKind": kind,
                "registeredRoot": root,
                "objectKey": key,
                "priority": priority,
                "verifiedAt": verifiedAt,
            })

        inventory = []
        identities = {}
        missingNames = []

        for name, fileID, digest, size, role, subjectID in fileRows:
            identity = (digest, size)
            if fileID in identities and identities[fileID] != identity:
                raise ValueError("Export inventory has conflicting identities for one content ID.")
            identities[fileID] = identity

            candidates = locationsByFile.get(fileID, [])
            if not candidates:
                missingNames.append(name)

            inventory.append({
                "name": name,
                "fileID": fileID,
                "sha256": digest,
                "size_bytes": size,
                "role": role,
                "subjectID": subjectID,
                "locations": deepcopy(candidates),
            })

        if missingNames:
            examples = ", ".join(repr(name) for name in missingNames[:5])
            extra = f"; plus {len(missingNames) - 5} more" if len(missingNames) > 5 else ""
            raise ValueError(
                f"Export checkpoint {sessionID} has files without eligible "
                f"registered locations: {examples}{extra}."
            )

        return {
            "manifest": manifest,
            "files": inventory,
            "logicalBytes": sum(record["size_bytes"] for record in inventory),
            "uniqueContentBytes": sum(size for _, size in identities.values()),
            "matrixInventoryComplete": False,
        }
        
    @classmethod
    def _readExportMatrixInventory(cls, connection, postgres, checkpoint, *, storageOptionsByBackend=None):
        """Inventory registered matrix products without opening their bundles.

        Reuses verified checkpoint-manifest and exact product-link checks.
        Caller owns the consistent read-only transaction and migration checks.

        Ownership:
            MRI-v2 records explicitly identify session or MRI ownership.
            Legacy records remain session-owned, regardless of their names.

        Returns independent attachment records and distinct revision records.
        Shared revisions are inventoried once without losing attachment names.

        Catalog descriptor validation is not payload verification. No Zarr
        metadata/chunks are opened, no arrays computed, and no bundle sizes
        guessed. Complete stored-bundle enumeration and byte verification
        remain required before transfer/publication.

        Reads checkpoint manifest bytes and SQL metadata only.
        Does not write SQL, resolve matrix storage access, or copy payloads.
        """
        from psycopg.rows import tuple_row

        manifest = cls._readExportCheckpointManifest(
            connection,
            postgres,
            checkpoint,
            storageOptionsByBackend=storageOptionsByBackend,
        )
        owned = manifest["contract_version"] == "pgl.derived.mri.v2"
        declared = manifest.get("products", [])
        validated = (
            cls._validateOwnedMatrixRecords(declared)
            if owned else cls._validateSessionProductRecords(declared)
        )

        attachments = [
            {
                "catalogName": record["name"],
                "owner": record["owner"] if owned else "session",
                "localName": record["localName"] if owned else record["name"],
                "matrixRevisionID": record["matrixRevisionID"],
            }
            for record in validated
        ]

        products = sql.Identifier(postgres.databaseSchema, "session_products")
        revisions = sql.Identifier(postgres.databaseSchema, "matrix_revisions")
        backends = sql.Identifier(postgres.databaseSchema, "storage_backends")

        # LEFT JOIN makes absent catalog dependencies explicit. Never silently
        # omit a link because its revision/backend cannot be resolved.
        statement = sql.SQL("""
            SELECT product.product_name,
                   product.matrix_revision_id::text,
                   revision.contract_version,
                   revision.descriptor,
                   revision.backend_id,
                   revision.object_key,
                   backend.name,
                   backend.kind,
                   backend.url_prefix,
                   backend.is_active
            FROM {} AS product
            LEFT JOIN {} AS revision
              ON revision.matrix_revision_id = product.matrix_revision_id
            LEFT JOIN {} AS backend
              ON backend.backend_id = revision.backend_id
            WHERE product.session_id = %s
            ORDER BY product.product_name
        """).format(products, revisions, backends)

        with connection.cursor(row_factory=tuple_row) as cursor:
            cursor.execute(statement, (checkpoint["sessionID"],))
            rows = cursor.fetchall()

        expected = {record["catalogName"]: record["matrixRevisionID"] for record in attachments}
        actual = {}
        revisionsByID = {}

        for name, revisionID, contract, descriptor, backendID, key, backendName, kind, root, active in rows:
            if name in actual:
                raise ValueError("Export matrix inventory contains duplicate product links.")
            actual[name] = revisionID

            if expected.get(name) != revisionID:
                raise ValueError("Export matrix link differs from its manifest declaration.")
            if contract != pglStorage.MATRIX_CONTRACT:
                raise ValueError("Export matrix revision is missing or has an unsupported contract.")
            if type(backendID) is not int or not 0 <= backendID <= 9223372036854775807:
                raise ValueError("Export matrix has an invalid backend ID.")
            if active is not True:
                raise ValueError("Export matrix backend is missing or inactive.")
            if (
                not isinstance(key, str) or not key
                or key.startswith("/") or "\\" in key or "\x00" in key
                or any(part in ("", ".", "..") for part in key.split("/"))
            ):
                raise ValueError("Export matrix has an invalid backend-relative bundle path.")
            if (
                not isinstance(root, str) or not root.strip()
                or any(character in root for character in ("\x00", "\n", "\r"))
            ):
                raise ValueError("Export matrix has an invalid registered storage root.")

            # Reuse the standalone descriptor contract. Encoding additionally
            # rejects values that cannot be preserved as canonical metadata.
            pglStorage._validateMatrixDescriptor(descriptor)
            cls.encodeRawManifest(descriptor)
            if descriptor["matrixRevisionID"] != revisionID:
                raise ValueError("Export matrix descriptor identifies another revision.")
            if descriptor["contractVersion"] != contract:
                raise ValueError("Export matrix descriptor disagrees with its registered contract.")

            revision = {
                "matrixRevisionID": revisionID,
                "contractVersion": contract,
                "descriptor": deepcopy(descriptor),
                "backendID": backendID,
                "backendName": backendName,
                "backendKind": kind,
                "registeredRoot": root,
                "objectKey": key,
            }

            previous = revisionsByID.get(revisionID)
            if previous is not None and cls.encodeRawManifest(previous) != cls.encodeRawManifest(revision):
                raise ValueError("Export matrix catalog contains conflicting records for one revision.")
            revisionsByID[revisionID] = revision

        if actual != expected:
            raise ValueError("Export matrix links do not exactly match the manifest.")

        return {
            "attachments": attachments,
            "revisions": [revisionsByID[key] for key in sorted(revisionsByID)],
            "bundleInventoryComplete": not revisionsByID,
            "bundleBytes": 0 if not revisionsByID else None,
        }
        
    @classmethod
    def _readExportMatrixBundleInventory(
        cls, connection, postgres, checkpoint, *, requireAllChunks,
        storageOptionsByBackend=None,
        progress=None,
    ):
        """Inventory registered matrix bundles through database-qualified access.

        Reuses _readExportMatrixInventory() for manifest/catalog validation and
        pglDatabaseAccess for caller-specific resolution of registered roots.

        Caller owns the consistent read-only SQL transaction and migration
        checks. The filesystem is not part of that SQL snapshot; concurrent
        payload mutation remains unsupported.

        requireAllChunks:
            Required explicit Boolean forwarded to layout validation.
            True requires every grid chunk.
            False reports missing grid chunks without interpreting their values.

        Returns the catalog inventory with:
            revisions:
                Existing distinct revision records, each extended with
                bundleInventory: descriptor, files, bundleBytes, and layout.
            bundleBytes:
                Sum over distinct revision records, not attachment links.
                This is not physical-storage deduplication across revisions.

        Preserves the catalog reader's bundleInventoryComplete value:
            Empty inventories remain vacuously complete.
            Nonempty inventories are NOT promoted to complete here.

        Hashes establish current observed bytes, not publication-time integrity.
        No codec decoding, scientific-value verification, transfer, publication,
        or destination mapping verification is performed.

        Owns a bounded payload-access context. Closes it on success or failure.
        Does not load scientific matrices, resolve ordinary settings profiles,
        write SQL, copy payloads, delete files, or modify catalog records.
        Errors propagate; failed access never substitutes another location.
        Optional progress is a pglProgress-compatible call/section reporter.
        Ranges allocate work, not elapsed-time estimates. Helpers never
        finish the enclosing operation. The public caller supplies a
        display-failure-isolated adapter; direct callback errors propagate.

        """
        from copy import deepcopy
        import posixpath

        if type(requireAllChunks) is not bool:
            raise TypeError("requireAllChunks must be an explicit Boolean.")

        catalog = cls._readExportMatrixInventory(
            connection,
            postgres,
            checkpoint,
            storageOptionsByBackend=storageOptionsByBackend,
        )
        result = deepcopy(catalog)

        # An empty catalog requires no matrix payload access.
        if not result["revisions"]:
            if progress is not None: progress(1, "No registered matrix bundles")
            return result

        with pglDatabaseAccess(postgres, storageOptionsByBackend) as access:
            for index, revision in enumerate(result["revisions"]):
                count = len(result["revisions"])
                bundleProgress = (
                    progress.section(index / count, (index + 1) / count,
                                     label=f"Matrix {index + 1}/{count}")
                    if progress is not None else None
                )
                filesystem, root = access.resolve(
                    revision["backendID"],
                    revision["registeredRoot"],
                )
                bundlePath = posixpath.join(root, revision["objectKey"])

                revision["bundleInventory"] = (
                    pglStorage.inventoryDataMatrixBundleLayout(
                        bundlePath,
                        filesystem=filesystem,
                        expectedDescriptor=revision["descriptor"],
                        requireAllChunks=requireAllChunks,
                        progress=bundleProgress,
                    )
                )

        result["bundleBytes"] = sum(
            revision["bundleInventory"]["bundleBytes"]
            for revision in result["revisions"]
        )
        if progress is not None: progress(1, "Registered matrix inventory verified")
        return result
    
    @classmethod
    def _copyExportCheckpointFiles(
        cls, inventory, destinationPath, *, sourceAccess,
        destinationFilesystem=None, destinationStorageOptions=None, progress=None,
    ):
        """Copy saved checkpoint files without reconstructing scientific objects.

        inventory:
            Result of _readExportFileInventory() from a migration-checked,
            consistent source snapshot. Structural checks here do not establish
            that arbitrary caller-supplied records came from that inspection.

        sourceAccess:
            Borrowed pglDatabaseAccess for the source database. Its database
            association must match the inventory's origin, as established by
            the enclosing coordinator. Never closed by this method.

        Source selection:
            Use the first listed eligible location for each logical file.
            Preserve the inventory's priority ordering. Resolution, reading,
            or verification failures propagate; no fallback is attempted.

        destinationPath:
            Exact new checkpoint-file directory. Parent must already exist.
            Existing destinations are rejected. Matrix bundles are separate.

        Returns:
            destinationPath: Filesystem-qualified destination.
            manifest: Independent copy of the unchanged saved manifest.
            files: Sorted logical names and verified SHA-256/size identities.
            fileBytes: Sum over logical files, including manifest.json.
            sourceLocations: Selected source location for each logical name.

        Copies manifest.json last, then enumerates and hashes the destination.
        Final verification requires the exact declared directory/file sets.
        A late failure may leave manifest.json present: successful return,
        not marker presence alone, is required before catalog registration.

        Does not load scientific objects, regenerate history, query/write SQL,
        register mappings, transfer matrices, close filesystems, or delete files.

        Local paths receive explicit symlink checks. Generic backend safety
        depends on authoritative listings and exclusive-create semantics.
        Concurrent mutation/writers are unsupported; verification is not an
        atomic snapshot. No publication-time matrix integrity is implied.
        Optional progress:
            A pglProgress-compatible reporter supporting call() and section().
            Reports this helper's work only; never finishes the parent display.
            Caller callback errors propagate like the existing hash/copy helpers.

        """
        from copy import deepcopy
        from pathlib import Path
        import hashlib
        import posixpath
        import re

        from fsspec.implementations.local import LocalFileSystem

        if not isinstance(sourceAccess, pglDatabaseAccess):
            raise TypeError("sourceAccess must be a pglDatabaseAccess instance.")
        if type(inventory) is not dict:
            raise TypeError("inventory must be a dictionary.")

        inventory = deepcopy(inventory)
        manifest = inventory.get("manifest")
        if type(manifest) is not dict:
            raise ValueError("Export inventory lacks a manifest.")

        contract = manifest.get("contract_version")
        if contract == "pgl.raw.behavior.v1":
            cls.validateRawManifest(manifest)
            origin = "raw"
        elif contract in ("pgl.raw.session.v1", "pgl.raw.session.v2"):
            cls.validateRawSessionManifest(manifest)
            origin = "raw"
        else:
            cls.validateDerivedManifest(manifest)
            origin = "derived"

        def validatePath(value, label):
            if (
                not isinstance(value, str) or not value
                or value.startswith("/") or "\\" in value
                or any(character in value for character in ("\x00", "\n", "\r"))
                or any(part in ("", ".", "..") for part in value.split("/"))
            ):
                raise ValueError(f"Invalid {label}: {value!r}")

        def requireLocalSafe(filesystem, path):
            """Do not resolve symlinks away before checking their ancestors."""
            if isinstance(filesystem, LocalFileSystem):
                localPath = Path(path).absolute()
                for candidate in (localPath, *localPath.parents):
                    if candidate.is_symlink():
                        raise ValueError(f"Symlinked export path: {candidate}")

        directories = set(manifest["directories"])
        for name in directories: validatePath(name, "manifest directory")

        manifestBytes = cls.encodeRawManifest(manifest)
        manifestIdentity = {
            "sha256": hashlib.sha256(manifestBytes).hexdigest(),
            "size_bytes": len(manifestBytes),
        }
        expectedFiles = {
            record["name"]: {
                "sha256": record["sha256"],
                "size_bytes": record["size_bytes"],
            }
            for record in manifest["files"]
        }
        if "manifest.json" in expectedFiles:
            raise ValueError("manifest.json is reserved for the saved manifest.")
        expectedFiles["manifest.json"] = manifestIdentity

        for name in expectedFiles: validatePath(name, "logical filename")

        # Explicitly require a complete, non-conflicting directory tree.
        if directories.intersection(expectedFiles):
            raise ValueError("A destination path cannot be both file and directory.")
        for name in directories | set(expectedFiles):
            parent = posixpath.dirname(name)
            if parent and parent not in directories:
                raise ValueError(f"Missing declared parent directory: {name}")

        fileRecords = inventory.get("files")
        if type(fileRecords) is not list:
            raise ValueError("Export inventory files must be a list.")

        recordsByName = {}
        selectedLocations = {}
        payloadRole = "acquisition" if origin == "raw" else "derived"

        for record in fileRecords:
            if type(record) is not dict:
                raise ValueError("Invalid export file record.")
            name = record.get("name")
            validatePath(name, "inventory filename")
            if name in recordsByName:
                raise ValueError("Duplicate export inventory filename.")

            identity = {
                "sha256": record.get("sha256"),
                "size_bytes": record.get("size_bytes"),
            }
            if (
                not isinstance(identity["sha256"], str)
                or re.fullmatch(r"[0-9a-f]{64}", identity["sha256"]) is None
                or type(identity["size_bytes"]) is not int
                or not 0 <= identity["size_bytes"] <= 9223372036854775807
                or identity != expectedFiles.get(name)
            ):
                raise ValueError(f"Export file identity differs from manifest: {name}")

            role = (
                "manifest" if name == "manifest.json"
                else "history" if name == "history.json"
                else payloadRole
            )
            if record.get("role") != role:
                raise ValueError(f"Export file role differs from manifest: {name}")

            locations = record.get("locations")
            if type(locations) is not list or not locations:
                raise ValueError(f"Export file has no source locations: {name}")

            # Do not sort, try alternatives, or interpret labels as identity.
            location = locations[0]
            if type(location) is not dict:
                raise ValueError(f"Invalid selected source location: {name}")

            backendID = location.get("backendID")
            root = location.get("registeredRoot")
            if type(backendID) is not int or not 0 <= backendID <= 9223372036854775807:
                raise ValueError("Invalid selected source backend ID.")
            if (
                not isinstance(root, str) or not root.strip()
                or any(character in root for character in ("\x00", "\n", "\r"))
            ):
                raise ValueError("Invalid selected registered root.")
            validatePath(location.get("objectKey"), "source object key")

            recordsByName[name] = record
            selectedLocations[name] = deepcopy(location)

        if set(recordsByName) != set(expectedFiles):
            raise ValueError("Export file set differs from the saved manifest.")

        destinationFilesystem, destinationRoot = pglStorage._resolveStoragePath(
            destinationPath,
            filesystem=destinationFilesystem,
            storageOptions=destinationStorageOptions,
            label="checkpoint export destination",
        )
        destinationRoot = destinationRoot.rstrip("/")
        if not destinationRoot:
            raise ValueError("Checkpoint destination cannot be the filesystem root.")

        requireLocalSafe(destinationFilesystem, destinationRoot)
        if destinationFilesystem.exists(destinationRoot):
            raise FileExistsError(destinationRoot)

        parent = posixpath.dirname(destinationRoot) or "."
        if not destinationFilesystem.isdir(parent):
            raise NotADirectoryError(parent)

        # Resolve every selected location before creating output. The access
        # context caches backend/root pairs. No payload bytes are read here.
        sources = {}
        for name in sorted(expectedFiles):
            location = selectedLocations[name]
            filesystem, root = sourceAccess.resolve(
                location["backendID"], location["registeredRoot"],
            )
            sourcePath = posixpath.join(root, location["objectKey"])
            requireLocalSafe(filesystem, sourcePath)

            sameNamespace = filesystem is destinationFilesystem
            if (
                isinstance(filesystem, LocalFileSystem)
                and isinstance(destinationFilesystem, LocalFileSystem)
            ):
                sameNamespace = True
                comparedSource = str(Path(sourcePath).absolute())
                comparedDestination = str(Path(destinationRoot).absolute())
            else:
                comparedSource = sourcePath
                comparedDestination = destinationRoot

            if sameNamespace:
                comparedSource = posixpath.normpath(comparedSource)
                comparedDestination = posixpath.normpath(comparedDestination)
                if (
                    comparedSource == comparedDestination
                    or comparedSource.startswith(comparedDestination.rstrip("/") + "/")
                    or comparedDestination.startswith(comparedSource.rstrip("/") + "/")
                ):
                    raise ValueError("Destination overlaps a selected source file.")

            sources[name] = (filesystem, sourcePath)

        requireLocalSafe(destinationFilesystem, destinationRoot)
        if destinationFilesystem.exists(destinationRoot):
            raise FileExistsError(destinationRoot)
        destinationFilesystem.makedirs(destinationRoot, exist_ok=False)

        # Preserve declared empty directories as well as file parents.
        for name in sorted(directories, key=lambda value: (value.count("/"), value)):
            path = posixpath.join(destinationRoot, name)
            requireLocalSafe(destinationFilesystem, path)
            destinationFilesystem.makedirs(path, exist_ok=False)

        copyOrder = sorted(set(expectedFiles) - {"manifest.json"}) + ["manifest.json"]
        copyWork = [{"name": name, **expectedFiles[name]} for name in copyOrder]
        copyProgress = progress.section(0, 0.75) if progress is not None else None
        for item, fileProgress in pglProgress.fileSections(copyWork, copyProgress):
            name = item["name"]
            filesystem, sourcePath = sources[name]
            requireLocalSafe(filesystem, sourcePath)
            requireLocalSafe(
                destinationFilesystem, posixpath.join(destinationRoot, name),
            )
            pglStorage.copyVerifiedFile(
                filesystem, sourcePath,
                destinationFilesystem, destinationRoot,
                expectedFiles[name],
                objectKey=name,
                progress=fileProgress,
            )

        def listDestination():
            """Require authoritative immediate-child listings and exact contents."""
            pending = [destinationRoot]
            observedDirectories = set()
            observedFiles = {}

            while pending:
                current = pending.pop()
                requireLocalSafe(destinationFilesystem, current)
                for entry in destinationFilesystem.ls(current, detail=True):
                    path = destinationFilesystem._strip_protocol(entry["name"])
                    if posixpath.dirname(path.rstrip("/")) != current:
                        raise ValueError("Destination listing returned a non-child entry.")

                    name = posixpath.relpath(path, destinationRoot)
                    validatePath(name, "destination entry")
                    requireLocalSafe(destinationFilesystem, path)
                    kind = entry.get("type")
                    if entry.get("islink") or kind in ("link", "symlink"):
                        raise ValueError(f"Symlinked destination entry: {name}")

                    if kind == "directory":
                        if name not in directories or name in observedDirectories:
                            raise ValueError(f"Unexpected or duplicate destination directory: {name}")
                        observedDirectories.add(name)
                        pending.append(path)
                    elif kind == "file":
                        if name not in expectedFiles or name in observedFiles:
                            raise ValueError(f"Unexpected or duplicate destination file: {name}")
                        size = entry.get("size")
                        if type(size) is not int or size < 0:
                            raise ValueError("Invalid destination file size.")
                        observedFiles[name] = size
                    else:
                        raise ValueError(f"Unsupported destination entry: {name}")

            if observedDirectories != directories or set(observedFiles) != set(expectedFiles):
                raise ValueError("Destination contents differ from the declared inventory.")
            return observedFiles

        if progress is not None: progress(0.75, "Checking complete checkpoint file inventory")
        before = listDestination()
        verifiedFiles = []
        verifyWork = [
            {"name": name, **expectedFiles[name]}
            for name in sorted(expectedFiles)
        ]
        verifyProgress = progress.section(0.75, 0.99) if progress is not None else None
        for item, fileProgress in pglProgress.fileSections(verifyWork, verifyProgress):
            name = item["name"]
            path = posixpath.join(destinationRoot, name)
            requireLocalSafe(destinationFilesystem, path)
            identity = pglStorage.hashFile(
                destinationFilesystem, path,
                progress=fileProgress, expectedSize=item["size_bytes"],
                description="Verifying complete checkpoint copy",
            )
            if identity != expectedFiles[name] or identity["size_bytes"] != before[name]:
                raise ValueError(f"Final destination identity mismatch: {name}")
            verifiedFiles.append({"name": name, **identity})

        if listDestination() != before:
            raise ValueError("Destination listing changed during final verification.")
        if progress is not None: progress(1, "Checkpoint file copy verified")

        return {
            "destinationPath": destinationFilesystem.unstrip_protocol(destinationRoot),
            "manifest": manifest,
            "files": verifiedFiles,
            "fileBytes": sum(record["size_bytes"] for record in verifiedFiles),
            "sourceLocations": [
                {"name": name, "location": selectedLocations[name]}
                for name in sorted(selectedLocations)
            ],
        }
        
    @classmethod
    def _compareExportManifestIdentity(cls, sourceManifest, destinationManifest):
        """Require identical validated manifests for byte-preserving export.

        Accepts parsed source and destination manifest dictionaries.

        Supports the explicitly listed existing raw and derived contracts.
        Uses existing contract validators and canonical manifest encoding.
        Does not normalize contracts, rewrite references, or mutate inputs.

        Returns:
            contractVersion: Unchanged checkpoint contract.
            sha256: SHA-256 of the identical canonical manifest bytes.
            size_bytes: Length of those canonical bytes.

        Caller responsibilities:
            Bind each supplied document to its actual stored manifest bytes
            and checkpoint catalog identity.
            Independently verify files, matrix bundles, attachment ownership,
            destination lineage, and database-qualified checkpoint mappings.

        Document identity alone does NOT establish stored-byte equality,
        scientific validity, source authenticity, or checkpoint equivalence.
        The return value is not mapping verification evidence or authorization
        to resolve a foreign checkpoint.

        Does not query SQL, read/write payloads, deserialize scientific objects,
        register mappings, or change bundleInventoryComplete.
        """
        from copy import deepcopy
        import hashlib

        rawContracts = {
            "pgl.raw.behavior.v1",
            "pgl.raw.session.v1",
            "pgl.raw.session.v2",
        }
        derivedContracts = {
            "pgl.derived.behavior.v1",
            "pgl.derived.behavior.v2",
            "pgl.derived.behavior.v3",
            "pgl.derived.session.v1",
            "pgl.derived.session.v2",
            "pgl.derived.session.v3",
            "pgl.derived.mri.v1",
            "pgl.derived.mri.v2",
        }

        def validatedBytes(manifest, label):
            """Validate an independent document without constructing payloads."""
            if type(manifest) is not dict:
                raise TypeError(f"{label} manifest must be a dictionary.")

            manifest = deepcopy(manifest)
            contract = manifest.get("contract_version")
            if (
                not isinstance(contract, str)
                or contract not in rawContracts | derivedContracts
            ):
                raise ValueError(f"Unsupported {label} export manifest contract.")

            if contract == "pgl.raw.behavior.v1":
                cls.validateRawManifest(manifest)
            elif contract in rawContracts:
                cls.validateRawSessionManifest(manifest)
            else:
                cls.validateDerivedManifest(manifest)

            return contract, cls.encodeRawManifest(manifest)

        sourceContract, sourceBytes = validatedBytes(sourceManifest, "source")
        destinationContract, destinationBytes = validatedBytes(
            destinationManifest, "destination",
        )

        if sourceContract != destinationContract:
            raise ValueError("Source and destination manifest contracts differ.")
        if sourceBytes != destinationBytes:
            raise ValueError(
                "Source and destination manifests differ under byte-preserving export."
            )

        return {
            "contractVersion": sourceContract,
            "sha256": hashlib.sha256(sourceBytes).hexdigest(),
            "size_bytes": len(sourceBytes),
        }
        
    @classmethod
    def _compareExportFileInventory(cls, sourceInventory, destinationInventory):
        """Compare checkpoint file catalogs for byte-preserving export.

        Inputs:
            Inventory dictionaries with manifest/files fields using the
            _readExportFileInventory() representation.

        Requires:
            Identical validated canonical manifests.
            Exact logical filenames, hashes, sizes, roles, and subject IDs.
            Valid database-local file IDs, without conflicting content
            identities for one ID within either catalog.

        Permits:
            Different database-local file IDs, storage locations, backend
            IDs, verification timestamps, and location priority order.
            Different input file-record ordering.

        Returns:
            manifestIdentity: Result of _compareExportManifestIdentity().
            files: Sorted common logical identities, roles, and subject IDs.
            logicalBytes: Sum over logical links, including manifest.json.

        File IDs are checked within each database, never matched across them.
        Subject IDs are compared exactly as catalog strings; no subject
        renaming or identity-equivalence inference is performed.

        Locations and cached aggregate totals are deliberately not compared.
        Their eligibility, accessibility, and actual bytes require separate
        verification. This method does not establish current payload integrity.

        Does not compare matrix attachments or SQL lineage, construct mapping
        verification evidence, authorize foreign resolution, query SQL, read
        payloads, mutate inputs, or change bundleInventoryComplete.
        """
        from copy import deepcopy

        if type(sourceInventory) is not dict or type(destinationInventory) is not dict:
            raise TypeError("Source and destination inventories must be dictionaries.")

        sourceInventory = deepcopy(sourceInventory)
        destinationInventory = deepcopy(destinationInventory)

        manifestIdentity = cls._compareExportManifestIdentity(
            sourceInventory.get("manifest"),
            destinationInventory.get("manifest"),
        )
        manifest = sourceInventory["manifest"]
        contract = manifestIdentity["contractVersion"]
        payloadRole = "acquisition" if contract.startswith("pgl.raw.") else "derived"

        expectedFiles = {
            record["name"]: {
                "sha256": record["sha256"],
                "size_bytes": record["size_bytes"],
                "role": "history" if record["name"] == "history.json" else payloadRole,
            }
            for record in manifest["files"]
        }
        if "manifest.json" in expectedFiles:
            raise ValueError("manifest.json is reserved for the checkpoint manifest.")

        expectedFiles["manifest.json"] = {
            "sha256": manifestIdentity["sha256"],
            "size_bytes": manifestIdentity["size_bytes"],
            "role": "manifest",
        }

        def projectFiles(inventory, label):
            """Validate local identity bookkeeping and project portable fields."""
            records = inventory.get("files")
            if type(records) is not list:
                raise ValueError(f"{label} inventory files must be a list.")

            projected = {}
            identitiesByID = {}
            requiredFields = {
                "name", "fileID", "sha256", "size_bytes", "role", "subjectID",
            }

            for record in records:
                if type(record) is not dict or not requiredFields.issubset(record):
                    raise ValueError(f"Invalid {label} file record.")

                name = record["name"]
                if not isinstance(name, str) or name not in expectedFiles:
                    raise ValueError(f"Unexpected {label} logical filename: {name!r}")
                if name in projected:
                    raise ValueError(f"Duplicate {label} logical filename: {name!r}")

                fileID = record["fileID"]
                if type(fileID) is not int or not 0 <= fileID <= 9223372036854775807:
                    raise ValueError(f"Invalid {label} database-local file ID.")

                digest = record["sha256"]
                size = record["size_bytes"]
                role = record["role"]
                if (
                    not isinstance(digest, str)
                    or type(size) is not int
                    or not 0 <= size <= 9223372036854775807
                    or not isinstance(role, str)
                    or {
                        "sha256": digest,
                        "size_bytes": size,
                        "role": role,
                    } != expectedFiles[name]
                ):
                    raise ValueError(
                        f"{label} file identity or role differs from manifest: {name}"
                    )

                identity = (digest, size)
                if fileID in identitiesByID and identitiesByID[fileID] != identity:
                    raise ValueError(
                        f"{label} file ID has conflicting content identities: {fileID}"
                    )
                identitiesByID[fileID] = identity

                subjectID = record["subjectID"]
                if subjectID is not None and (
                    not isinstance(subjectID, str)
                    or not subjectID.strip()
                    or "\x00" in subjectID
                ):
                    raise ValueError(f"Invalid {label} subject ID: {name}")

                projected[name] = {
                    "name": name,
                    "sha256": digest,
                    "size_bytes": size,
                    "role": role,
                    "subjectID": subjectID,
                }

            if set(projected) != set(expectedFiles):
                raise ValueError(f"{label} file set differs from the manifest.")

            return [projected[name] for name in sorted(projected)]

        sourceFiles = projectFiles(sourceInventory, "Source")
        destinationFiles = projectFiles(destinationInventory, "Destination")

        if sourceFiles != destinationFiles:
            raise ValueError("Source and destination file subject associations differ.")

        return {
            "manifestIdentity": manifestIdentity,
            "files": sourceFiles,
            "logicalBytes": sum(record["size_bytes"] for record in sourceFiles),
        }
        
    @classmethod
    def _compareExportMatrixInventory(
        cls, sourceInventory, destinationInventory, *,
        sourceManifest, destinationManifest,
    ):
        """Compare matrix attachments, descriptors, and captured byte identities.

        Inputs:
            Matrix inventories in the _readExportMatrixBundleInventory()
            representation, plus their corresponding saved manifests.

        Requires:
            Identical validated manifests.
            Exact manifest-declared attachment names, ownership, local names,
            and revision UUIDs.
            Exactly the referenced distinct revisions, without duplicates.
            Valid matching catalog and bundle descriptors.
            Identical sorted stored-file SHA-256/size records.
            Correct per-bundle and aggregate byte totals.

        Permits:
            Different destination backend IDs, roots, object keys, and backend
            labels. Attachment/revision list order does not affect comparison.

        Returns:
            manifestIdentity: Common canonical manifest identity.
            attachments: Sorted portable attachment records.
            revisions: Sorted revision identities, descriptors, and byte records.
            bundleBytes: Sum over distinct revisions, not attachment links.

        This compares captured evidence, not current filesystems. Caller must
        obtain inventories using the actual byte/layout inventory helpers and
        enforce the chosen chunk-coverage policy independently.

        Supplied layout reports and bundleInventoryComplete flags are not
        evidence of fresh verification and are deliberately not promoted or
        returned. Matching invented inventories can still describe nonexistent
        or invalid payloads.

        Does not query SQL, read payloads, decode chunks, validate mapped
        checkpoint lineage, register mappings, authorize foreign resolution,
        mutate inputs, or establish publication-time integrity.
        """
        from copy import deepcopy
        import re

        if type(sourceInventory) is not dict or type(destinationInventory) is not dict:
            raise TypeError("Source and destination matrix inventories must be dictionaries.")

        sourceInventory = deepcopy(sourceInventory)
        destinationInventory = deepcopy(destinationInventory)

        manifestIdentity = cls._compareExportManifestIdentity(
            sourceManifest, destinationManifest,
        )
        manifest = deepcopy(sourceManifest)
        owned = manifest["contract_version"] == "pgl.derived.mri.v2"
        declared = manifest.get("products", [])
        validated = (
            cls._validateOwnedMatrixRecords(declared)
            if owned else cls._validateSessionProductRecords(declared)
        )
        expectedAttachments = {
            record["name"]: {
                "catalogName": record["name"],
                "owner": record["owner"] if owned else "session",
                "localName": record["localName"] if owned else record["name"],
                "matrixRevisionID": record["matrixRevisionID"],
            }
            for record in validated
        }
        expectedRevisionIDs = {
            record["matrixRevisionID"] for record in expectedAttachments.values()
        }

        def validateName(name):
            """Require the same portable relative filename form as byte inventory."""
            if (
                not isinstance(name, str) or not name
                or name.startswith("/") or "\\" in name
                or any(character in name for character in ("\x00", "\n", "\r"))
                or any(part in ("", ".", "..") for part in name.split("/"))
            ):
                raise ValueError(f"Invalid matrix inventory filename: {name!r}")

        def projectInventory(inventory, label):
            """Validate correspondence without consulting a filesystem."""
            attachments = inventory.get("attachments")
            revisions = inventory.get("revisions")
            if type(attachments) is not list or type(revisions) is not list:
                raise ValueError(f"{label} matrix attachments/revisions must be lists.")

            actualAttachments = {}
            attachmentFields = {"catalogName", "owner", "localName", "matrixRevisionID"}
            for record in attachments:
                if type(record) is not dict or set(record) != attachmentFields:
                    raise ValueError(f"Invalid {label} matrix attachment record.")

                name = record["catalogName"]
                if not isinstance(name, str) or name not in expectedAttachments:
                    raise ValueError(f"Unexpected {label} matrix attachment.")
                if name in actualAttachments:
                    raise ValueError(f"Duplicate {label} matrix attachment.")
                if record != expectedAttachments[name]:
                    raise ValueError(f"{label} matrix attachment differs from manifest.")
                actualAttachments[name] = dict(record)

            if set(actualAttachments) != set(expectedAttachments):
                raise ValueError(f"{label} matrix attachments do not cover the manifest.")

            projectedRevisions = {}
            for revision in revisions:
                if type(revision) is not dict:
                    raise ValueError(f"Invalid {label} matrix revision record.")

                revisionID = revision.get("matrixRevisionID")
                if not isinstance(revisionID, str) or revisionID not in expectedRevisionIDs:
                    raise ValueError(f"Unexpected {label} matrix revision.")
                if revisionID in projectedRevisions:
                    raise ValueError(f"Duplicate {label} matrix revision.")
                if revision.get("contractVersion") != pglStorage.MATRIX_CONTRACT:
                    raise ValueError(f"Unsupported {label} matrix contract.")

                descriptor = revision.get("descriptor")
                pglStorage._validateMatrixDescriptor(descriptor)
                descriptorBytes = pglStorage.encodeJSON(descriptor)
                if descriptor["matrixRevisionID"] != revisionID:
                    raise ValueError(f"{label} descriptor identifies another revision.")

                bundle = revision.get("bundleInventory")
                if type(bundle) is not dict:
                    raise ValueError(f"{label} revision lacks a captured bundle inventory.")

                bundleDescriptor = bundle.get("descriptor")
                pglStorage._validateMatrixDescriptor(bundleDescriptor)
                if pglStorage.encodeJSON(bundleDescriptor) != descriptorBytes:
                    raise ValueError(f"{label} catalog and bundle descriptors differ.")

                files = bundle.get("files")
                if type(files) is not list:
                    raise ValueError(f"{label} matrix files must be a list.")

                names = []
                projectedFiles = []
                for record in files:
                    if type(record) is not dict or set(record) != {
                        "name", "sha256", "size_bytes",
                    }:
                        raise ValueError(f"Invalid {label} matrix file record.")

                    name = record["name"]
                    validateName(name)
                    if name != "matrix.json" and not name.startswith("data.zarr/"):
                        raise ValueError(f"Unexpected {label} matrix bundle filename.")

                    digest = record["sha256"]
                    size = record["size_bytes"]
                    if (
                        not isinstance(digest, str)
                        or re.fullmatch(r"[0-9a-f]{64}", digest) is None
                        or type(size) is not int or size < 0
                    ):
                        raise ValueError(f"Invalid {label} matrix byte identity.")

                    names.append(name)
                    projectedFiles.append(dict(record))

                if names != sorted(set(names)):
                    raise ValueError(f"{label} matrix filenames must be unique and sorted.")

                requiredNames = {
                    "matrix.json",
                    "data.zarr/.zgroup",
                    "data.zarr/.zattrs",
                    "data.zarr/.zmetadata",
                }
                if not requiredNames.issubset(names):
                    raise ValueError(f"{label} matrix inventory lacks required metadata files.")

                bundleBytes = sum(record["size_bytes"] for record in projectedFiles)
                if (
                    type(bundle.get("bundleBytes")) is not int
                    or bundle["bundleBytes"] != bundleBytes
                ):
                    raise ValueError(f"{label} matrix bundle byte total is inconsistent.")

                projectedRevisions[revisionID] = {
                    "matrixRevisionID": revisionID,
                    "contractVersion": revision["contractVersion"],
                    "descriptor": deepcopy(descriptor),
                    "files": projectedFiles,
                    "bundleBytes": bundleBytes,
                }

            if set(projectedRevisions) != expectedRevisionIDs:
                raise ValueError(f"{label} matrix revisions do not cover the manifest.")

            bundleBytes = sum(
                revision["bundleBytes"] for revision in projectedRevisions.values()
            )
            if (
                type(inventory.get("bundleBytes")) is not int
                or inventory["bundleBytes"] != bundleBytes
            ):
                raise ValueError(f"{label} aggregate matrix byte total is inconsistent.")

            return {
                "attachments": [
                    actualAttachments[name] for name in sorted(actualAttachments)
                ],
                "revisions": [
                    projectedRevisions[key] for key in sorted(projectedRevisions)
                ],
                "bundleBytes": bundleBytes,
            }

        source = projectInventory(sourceInventory, "Source")
        destination = projectInventory(destinationInventory, "Destination")

        if pglStorage.encodeJSON(source) != pglStorage.encodeJSON(destination):
            raise ValueError("Source and destination captured matrix inventories differ.")

        return {"manifestIdentity": manifestIdentity, **source}
    
    @classmethod
    def _compareExportCheckpointLineage(
        cls, sourceAncestry, destinationAncestry, *,
        sourceDatabaseID, destinationDatabaseID, sessionIDMapping,
    ):
        """Compare complete checkpoint chains under an explicit export mapping.

        Ancestries:
            Root-to-selected record lists using _readExportAncestry() fields.
            Both must describe active, completed, noncyclic chains.

        sessionIDMapping:
            Dictionary of source-local integer IDs to destination-local integer
            IDs. Must cover exactly both chains, with one-to-one correspondence.
            No numeric-ID fallback, partial mapping, or ancestry collapse.

        Requires:
            Distinct canonical nonzero database UUIDs.
            Consistent raw-root/derived-parent structure on both sides.
            Mapped parent/root relationships.
            Matching manifest hashes, contracts, origin, and kind.

        Returns:
            sourceDatabaseID / destinationDatabaseID.
            checkpoints: Root-to-selected portable correspondence records.

        Publication timestamps must be timezone-aware but need not match.
        Creator IDs, annotations, and other catalog fields are not compared.
        This does not define their eventual export preservation policy.

        Caller must bind database UUIDs and ancestry records to actual checked
        database snapshots. Matching supplied records alone cannot establish
        their authenticity or current visibility.

        Does not inspect manifests/payloads, check historical action-input
        dependencies, compare all session metadata, register mappings, produce
        authorization evidence, or resolve foreign references.

        Does not query SQL, mutate inputs, or change transaction settings.
        """
        from copy import deepcopy
        from datetime import datetime
        from uuid import UUID
        import re

        def validateDatabaseID(value, label):
            if not isinstance(value, str):
                raise ValueError(f"{label} must be a canonical nonzero UUID.")
            try:
                parsed = UUID(value)
            except (ValueError, AttributeError) as error:
                raise ValueError(f"Invalid {label}.") from error
            if str(parsed) != value or parsed.int == 0:
                raise ValueError(f"{label} must be a canonical nonzero UUID.")

        def validateSessionID(value, label):
            if type(value) is not int or not 0 <= value <= 9223372036854775807:
                raise ValueError(f"{label} must be a nonnegative PostgreSQL bigint.")

        validateDatabaseID(sourceDatabaseID, "sourceDatabaseID")
        validateDatabaseID(destinationDatabaseID, "destinationDatabaseID")
        if sourceDatabaseID == destinationDatabaseID:
            raise ValueError("Cross-database lineage comparison requires distinct database UUIDs.")

        if type(sessionIDMapping) is not dict:
            raise TypeError("sessionIDMapping must be a dictionary.")
        sessionIDMapping = deepcopy(sessionIDMapping)

        for sourceID, destinationID in sessionIDMapping.items():
            validateSessionID(sourceID, "Mapping source session ID")
            validateSessionID(destinationID, "Mapping destination session ID")
        if len(set(sessionIDMapping.values())) != len(sessionIDMapping):
            raise ValueError("Lineage mapping must be one-to-one.")

        def validateAncestry(records, label):
            """Validate the chain itself before comparing its mapped identity."""
            if type(records) is not list or not records:
                raise ValueError(f"{label} ancestry must be a nonempty list.")

            records = deepcopy(records)
            requiredFields = {
                "sessionID", "parentSessionID", "rootSessionID",
                "origin", "kind", "status", "deletedAt",
                "manifestHash", "contractVersion", "completedAt",
            }
            seen = set()
            rootID = None
            previousID = None

            for index, record in enumerate(records):
                if type(record) is not dict or not requiredFields.issubset(record):
                    raise ValueError(f"Invalid {label} ancestry record.")

                sessionID = record["sessionID"]
                parentID = record["parentSessionID"]
                validateSessionID(sessionID, f"{label} session ID")
                validateSessionID(record["rootSessionID"], f"{label} root ID")
                if parentID is not None:
                    validateSessionID(parentID, f"{label} parent ID")
                if sessionID in seen:
                    raise ValueError(f"{label} ancestry contains duplicate session IDs.")
                seen.add(sessionID)

                if record["status"] != "complete" or record["deletedAt"] is not None:
                    raise ValueError(f"{label} ancestry must be active and complete.")

                completedAt = record["completedAt"]
                if (
                    not isinstance(completedAt, datetime)
                    or completedAt.tzinfo is None
                    or completedAt.utcoffset() is None
                ):
                    raise ValueError(f"{label} completion timestamp must be timezone-aware.")

                digest = record["manifestHash"]
                if not isinstance(digest, str) or re.fullmatch(r"[0-9a-f]{64}", digest) is None:
                    raise ValueError(f"Invalid {label} manifest hash.")
                contract = record["contractVersion"]
                if (
                    not isinstance(contract, str) or not contract.strip()
                    or any(character in contract for character in ("\x00", "\n", "\r"))
                ):
                    raise ValueError(f"Invalid {label} contract version.")

                if index == 0:
                    rootID = sessionID
                    if (
                        record["origin"] != "raw"
                        or record["kind"] != "acquired"
                        or parentID is not None
                        or record["rootSessionID"] != sessionID
                    ):
                        raise ValueError(f"{label} ancestry has an invalid raw root.")
                elif (
                    record["origin"] != "derived"
                    or record["kind"] != "processed"
                    or parentID != previousID
                    or record["rootSessionID"] != rootID
                ):
                    raise ValueError(f"{label} ancestry has an invalid derived parent/root chain.")

                previousID = sessionID

            return records

        source = validateAncestry(sourceAncestry, "Source")
        destination = validateAncestry(destinationAncestry, "Destination")

        sourceIDs = {record["sessionID"] for record in source}
        destinationIDs = {record["sessionID"] for record in destination}
        if (
            set(sessionIDMapping) != sourceIDs
            or set(sessionIDMapping.values()) != destinationIDs
        ):
            raise ValueError("Lineage mapping must cover exactly both ancestry chains.")

        mappedOrder = [sessionIDMapping[record["sessionID"]] for record in source]
        if mappedOrder != [record["sessionID"] for record in destination]:
            raise ValueError("Mapped ancestry order differs from destination ancestry.")

        checkpoints = []
        for sourceRecord, destinationRecord in zip(source, destination):
            sourceParent = sourceRecord["parentSessionID"]
            expectedParent = (
                None if sourceParent is None else sessionIDMapping[sourceParent]
            )
            expectedRoot = sessionIDMapping[sourceRecord["rootSessionID"]]
            if (
                destinationRecord["parentSessionID"] != expectedParent
                or destinationRecord["rootSessionID"] != expectedRoot
            ):
                raise ValueError("Mapped parent/root relationships differ.")

            for field in ("origin", "kind", "contractVersion", "manifestHash"):
                if sourceRecord[field] != destinationRecord[field]:
                    raise ValueError(f"Mapped checkpoint {field} differs.")

            checkpoints.append({
                "sourceSessionID": sourceRecord["sessionID"],
                "destinationSessionID": destinationRecord["sessionID"],
                "sourceParentSessionID": sourceParent,
                "destinationParentSessionID": expectedParent,
                "sourceRootSessionID": sourceRecord["rootSessionID"],
                "destinationRootSessionID": expectedRoot,
                "origin": sourceRecord["origin"],
                "kind": sourceRecord["kind"],
                "contractVersion": sourceRecord["contractVersion"],
                "manifestHash": sourceRecord["manifestHash"],
            })

        return {
            "sourceDatabaseID": sourceDatabaseID,
            "destinationDatabaseID": destinationDatabaseID,
            "checkpoints": checkpoints,
        }
        
    @classmethod
    def _inspectExportHistoryReferences(
        cls, history, *, sourceDatabaseID, sourceSessionIDs,
    ):
        """Check structured action-input references for the initial export scope.

        history:
            Metadata restored through _readSessionHistory(). Do not pass raw
            JSON in place of restored history: argument paths may contain
            typed mapping keys encoded by the PGL serializer.

        sourceDatabaseID / sourceSessionIDs:
            Explicit source UUID and selected ancestry IDs established by the
            caller's database inspection. This method does not verify SQL.

        Initial supported scope:
            Version-2 actionInputs records.
            Empty replay metadata or an explicit workingObject replay marker.
            Qualified checkpoint inputs entirely within the selected source
            ancestry. Null references are reported as unbound working inputs.
            No recorded product consumption.

        Rejects:
            Missing/legacy/unspecified action inputs.
            Endpoint-based checkpoint replay records.
            External or out-of-scope qualified references.
            Nonempty actionProductInputs, whose product availability requires
            a separate verification implementation.

        Empty action history is supported. An absent history file is a
        separate manifest-contract case, not an empty history inferred here.

        Returns structured checkpoint-reference coverage and unbound-input
        positions. This is NOT universal dependency completeness, replay
        portability, mapping evidence, or foreign-resolution authorization.

        Preserves historical references and labels without rewriting them.
        Does not query SQL, resolve products, read scientific payloads, mutate
        history, or infer saved product membership from owner references.
        """
        from copy import deepcopy
        from uuid import UUID

        from .pglPipeline import pglActionable, pglActionHistory

        if not isinstance(history, pglActionable):
            raise TypeError("history must be restored pglActionable metadata.")

        if not isinstance(sourceDatabaseID, str):
            raise ValueError("sourceDatabaseID must be a canonical nonzero UUID.")
        try:
            parsedID = UUID(sourceDatabaseID)
        except (ValueError, AttributeError) as error:
            raise ValueError("Invalid sourceDatabaseID.") from error
        if str(parsedID) != sourceDatabaseID or parsedID.int == 0:
            raise ValueError("sourceDatabaseID must be a canonical nonzero UUID.")

        if type(sourceSessionIDs) is not list or not sourceSessionIDs:
            raise ValueError("sourceSessionIDs must be a nonempty list.")
        if any(
            type(value) is not int or not 0 <= value <= 9223372036854775807
            for value in sourceSessionIDs
        ):
            raise ValueError("Source session IDs must be nonnegative PostgreSQL bigints.")
        if len(set(sourceSessionIDs)) != len(sourceSessionIDs):
            raise ValueError("Source session IDs must be unique.")
        selectedIDs = set(sourceSessionIDs)

        entries = history.actionHistory
        references = []
        unboundInputs = []

        for actionIndex, entry in enumerate(entries):
            if not isinstance(entry, pglActionHistory):
                raise TypeError("History contains an unsupported action-history object.")

            productInputs = entry.actionProductInputs
            if type(productInputs) is not list:
                raise ValueError("Recorded product inputs must be a list.")
            if productInputs:
                raise ValueError(
                    f"Action {actionIndex}: product-consumption verification "
                    "is not implemented for this export scope."
                )

            # Work on copies: validation and reporting must not edit history.
            record = deepcopy(entry.actionInput)
            if (
                type(record) is not dict
                or record.get("kind") != "actionInputs"
            ):
                raise ValueError(
                    f"Action {actionIndex}: legacy or unspecified action inputs "
                    "are unsupported by this export scope."
                )
            pglActionHistory.validateActionInputs(record)

            replay = record["replayInput"]
            if replay and replay != {"version": 1, "kind": "workingObject"}:
                raise ValueError(
                    f"Action {actionIndex}: checkpoint replay metadata requires "
                    "separate endpoint-portability verification."
                )

            for inputIndex, item in enumerate(record["inputs"]):
                position = {
                    "actionIndex": actionIndex,
                    "inputIndex": inputIndex,
                }
                reference = item["checkpoint"]
                if reference is None:
                    unboundInputs.append(position)
                    continue

                if (
                    reference["databaseID"] != sourceDatabaseID
                    or reference["sessionID"] not in selectedIDs
                ):
                    raise ValueError(
                        f"Action {actionIndex}, input {inputIndex}: checkpoint "
                        "reference is outside the selected source ancestry."
                    )

                references.append({
                    **position,
                    "checkpoint": deepcopy(reference),
                })

        return {
            "sourceDatabaseID": sourceDatabaseID,
            "sourceSessionIDs": list(sourceSessionIDs),
            "actionCount": len(entries),
            "checkpointReferences": references,
            "unboundWorkingInputs": unboundInputs,
            "structuredCheckpointReferencesCovered": True,
            "dependencyCompletenessEstablished": False,
        }
        
    @classmethod
    def _prepareExportSessionMetadata(
        cls, sourceRecord, sourceCreator, sourceManifest, *,
        sourceDatabaseID, verifiedLabels,
    ):
        """Project source metadata for the initial byte-preserving export path.

        sourceRecord:
            Full JSON-compatible session row, using SQL column names.
            Timestamp fields must use timezone-aware ISO-8601 strings, as
            returned by PostgreSQL to_jsonb(session). This is not an ancestry
            record or a native tuple containing Python datetime objects.

        sourceCreator:
            Exact fields: sourceUserID, username, displayName.
            Identifies the source creator only. Does not authorize creation,
            matching, or impersonation of a destination user.

        verifiedLabels:
            Labels independently read/verified from archived checkpoint
            metadata. Must agree with sourceRecord.meta.pgl_session_labels.
            This method checks correspondence, not how labels were obtained.

        Returns:
            preservedFields:
                Source acquisition/descriptive fields and complete meta object.
            sourceProvenance:
                Source-qualified full catalog snapshot and creator description.
            destinationManagedFields:
                Column names the publication coordinator must allocate/set.

        Original publication timestamps and saved_timezone are retained in
        sourceProvenance, not copied into destination publication fields.
        Historical payload bytes are neither regenerated nor rewritten.

        Initial scope requires explicit catalog labels. Unknown columns,
        missing columns, or unsupported representations block projection.
        Source/destination lineage and other comparison helpers remain separate.

        This is a proposed publication projection, not a mapping verification
        document, schema migration, or proof of source authenticity. Persisting
        sourceProvenance requires the later versioned evidence protocol.

        Does not query/write SQL, create users, read payloads, mutate inputs,
        select a destination actor/timezone, or authorize foreign resolution.
        """
        from copy import deepcopy
        from datetime import datetime
        from uuid import UUID

        expectedFields = {
            "session_id", "root_session_id", "parent_session_id",
            "origin", "kind", "instrument", "ingest_method", "acquired_at",
            "manifest_hash", "modalities", "status", "description", "meta",
            "contract_version", "created_by", "created_at", "started_at",
            "completed_at", "deleted_at", "checkpoint_name", "saved_timezone",
        }
        if type(sourceRecord) is not dict or set(sourceRecord) != expectedFields:
            raise ValueError("Source session metadata has missing or unsupported columns.")
        if type(sourceCreator) is not dict or set(sourceCreator) != {
            "sourceUserID", "username", "displayName",
        }:
            raise ValueError("Invalid source creator metadata.")

        sourceRecord = deepcopy(sourceRecord)
        sourceCreator = deepcopy(sourceCreator)
        sourceManifest = deepcopy(sourceManifest)
        verifiedLabels = deepcopy(verifiedLabels)

        if not isinstance(sourceDatabaseID, str):
            raise ValueError("sourceDatabaseID must be a canonical nonzero UUID.")
        try:
            parsedID = UUID(sourceDatabaseID)
        except (ValueError, AttributeError) as error:
            raise ValueError("Invalid sourceDatabaseID.") from error
        if str(parsedID) != sourceDatabaseID or parsedID.int == 0:
            raise ValueError("sourceDatabaseID must be a canonical nonzero UUID.")

        def validateID(value, label):
            if type(value) is not int or not 0 <= value <= 9223372036854775807:
                raise ValueError(f"{label} must be a nonnegative PostgreSQL bigint.")

        def validateText(value, label, *, nullable=True, nonblank=False):
            if value is None and nullable: return
            if (
                not isinstance(value, str) or "\x00" in value
                or (nonblank and not value.strip())
            ):
                raise ValueError(f"Invalid {label}.")

        def parseTimestamp(value, label, *, nullable):
            """Validate JSON timestamp representation without rewriting it."""
            if value is None and nullable: return None
            if not isinstance(value, str):
                raise ValueError(f"{label} must be a timezone-aware ISO timestamp.")
            try:
                parsed = datetime.fromisoformat(value)
            except ValueError as error:
                raise ValueError(f"Invalid {label} timestamp.") from error
            if parsed.tzinfo is None or parsed.utcoffset() is None:
                raise ValueError(f"{label} must be a timezone-aware ISO timestamp.")
            return parsed

        for field in ("session_id", "root_session_id", "created_by"):
            validateID(sourceRecord[field], field)
        parentID = sourceRecord["parent_session_id"]
        if parentID is not None: validateID(parentID, "parent_session_id")
        validateID(sourceCreator["sourceUserID"], "sourceUserID")
        if sourceCreator["sourceUserID"] != sourceRecord["created_by"]:
            raise ValueError("Source creator does not match the session creator ID.")

        validateText(sourceCreator["username"], "source username", nullable=False, nonblank=True)
        validateText(sourceCreator["displayName"], "source display name")
        for field in ("instrument", "description", "checkpoint_name"):
            validateText(sourceRecord[field], field)
        if sourceRecord["ingest_method"] not in (None, "manual", "automated"):
            raise ValueError("Unsupported source ingest method.")
        savedTimezone = sourceRecord["saved_timezone"]
        validateText(savedTimezone, "saved_timezone", nonblank=True)
        if savedTimezone is not None and savedTimezone != savedTimezone.strip():
            raise ValueError("saved_timezone must not contain surrounding whitespace.")

        if sourceRecord["status"] != "complete" or sourceRecord["deleted_at"] is not None:
            raise ValueError("Source checkpoint must be active and complete.")

        parseTimestamp(sourceRecord["created_at"], "created_at", nullable=False)
        startedAt = parseTimestamp(sourceRecord["started_at"], "started_at", nullable=True)
        completedAt = parseTimestamp(sourceRecord["completed_at"], "completed_at", nullable=False)
        parseTimestamp(sourceRecord["acquired_at"], "acquired_at", nullable=True)
        if startedAt is not None and completedAt < startedAt:
            raise ValueError("Source completion precedes its publication start.")

        manifestIdentity = cls._compareExportManifestIdentity(sourceManifest, sourceManifest)
        contract = manifestIdentity["contractVersion"]
        if (
            sourceRecord["contract_version"] != contract
            or sourceRecord["manifest_hash"] != manifestIdentity["sha256"]
        ):
            raise ValueError("Source catalog manifest identity differs from the supplied manifest.")

        raw = contract.startswith("pgl.raw.")
        expectedOrigin, expectedKind = ("raw", "acquired") if raw else ("derived", "processed")
        if (sourceRecord["origin"], sourceRecord["kind"]) != (expectedOrigin, expectedKind):
            raise ValueError("Source origin/kind disagrees with its manifest contract.")

        sessionID = sourceRecord["session_id"]
        rootID = sourceRecord["root_session_id"]
        if raw:
            if parentID is not None or rootID != sessionID:
                raise ValueError("Invalid raw source lineage.")
        elif parentID is None or parentID == sessionID or rootID == sessionID:
            raise ValueError("Invalid derived source lineage.")

        modalities = sourceRecord["modalities"]
        expectedModalities = set()
        if sourceManifest["runs"]: expectedModalities.add("behavior")
        if "mne" in sourceManifest: expectedModalities.add("mne")
        if "mri" in sourceManifest: expectedModalities.add("mri")
        if (
            type(modalities) is not list
            or any(not isinstance(value, str) for value in modalities)
            or len(modalities) != len(set(modalities))
            or set(modalities) != expectedModalities
        ):
            raise ValueError("Source modalities disagree with manifest contents.")

        metadata = sourceRecord["meta"]
        if type(metadata) is not dict or "pgl_session_labels" not in metadata:
            raise ValueError("Initial export requires explicit source catalog labels.")

        cls._validateSessionLabelMetadata(
            verifiedLabels, runCount=len(sourceManifest["runs"]),
        )
        cls._validateSessionLabelMetadata(
            metadata["pgl_session_labels"], runCount=len(sourceManifest["runs"]),
        )
        if pglStorage.encodeJSON(metadata["pgl_session_labels"]) != pglStorage.encodeJSON(verifiedLabels):
            raise ValueError("Source catalog labels differ from verified archived labels.")

        # Reject unsupported JSON values while preserving every original meta
        # field. Arbitrary metadata is retained, not interpreted as dependencies.
        pglStorage.encodeJSON(sourceRecord)
        pglStorage.encodeJSON(sourceCreator)

        preservedNames = (
            "instrument", "ingest_method", "acquired_at", "modalities",
            "description", "checkpoint_name", "meta",
        )
        managedNames = (
            "session_id", "root_session_id", "parent_session_id",
            "origin", "kind", "contract_version", "manifest_hash",
            "status", "deleted_at", "created_by", "created_at",
            "started_at", "completed_at", "saved_timezone",
        )

        return {
            "preservedFields": {
                name: deepcopy(sourceRecord[name]) for name in preservedNames
            },
            "sourceProvenance": {
                "sourceDatabaseID": sourceDatabaseID,
                "sourceSessionID": sessionID,
                "sessionMetadata": sourceRecord,
                "creator": sourceCreator,
            },
            "destinationManagedFields": list(managedNames),
        }
        
    @classmethod
    def _buildExportMappingEvidence(
        cls, *,
        sourceDatabaseID, destinationDatabaseID,
        sourceRecord, sourceCreator, destinationRecord, destinationCreator,
        sourceManifest, destinationManifest,
        sourceFiles, destinationFiles,
        sourceMatrices, destinationMatrices,
        sourceAncestry, destinationAncestry, sessionIDMapping,
        verifiedLabels, history,
    ):
        """Build internally checked byte-preserving export evidence.

        Initial scope:
            pgl.raw.behavior.v1 and pgl.derived.behavior.v3.
            Unchanged manifests, checkpoint files, matrix revisions/descriptors.
            Explicit one-to-one root-to-selected lineage mapping.
            The existing bounded history-reference policy.

        Inputs must be caller observations from the checked source snapshot
        and destination publication transaction. File/matrix inventories must
        come from the corresponding catalog and payload verification steps.

        history:
            None only when the validated raw manifest has no history file.
            Otherwise metadata restored from the verified saved history bytes.
            This method does not independently bind an arbitrary history
            object to those bytes; the coordinator must establish that binding.

        Re-runs existing comparison/projection helpers. Requires the selected
        source and destination catalog records to agree with their ancestry
        records, and preserved destination metadata to match source metadata.

        Returns an independent JSON-compatible document for the future
        session_export_mappings.verification protocol.

        This is an application-attestation builder, not proof that supplied
        observations were collected, storage was hashed, or SQL rows exist.
        Strict grid coverage is a REQUIRED publication policy, not a check
        performed by this pure builder. Supplied layout flags are not trusted.

        No verification timestamps are fabricated. Destination publication
        timestamps retain their original meaning. Editable annotations are
        captured as publication snapshots, not permanent reuse constraints.

        Does not query SQL, hash/read payloads, decode chunks, register mappings,
        authorize foreign resolution, mutate inputs, or establish authenticity.
        Structural validation and actual destination-binding checks remain
        separate required implementation steps.
        """
        from copy import deepcopy
        from datetime import datetime

        sourceRecord = deepcopy(sourceRecord)
        destinationRecord = deepcopy(destinationRecord)
        sourceManifest = deepcopy(sourceManifest)
        destinationManifest = deepcopy(destinationManifest)

        manifestIdentity = cls._compareExportManifestIdentity(
            sourceManifest, destinationManifest,
        )
        if manifestIdentity["contractVersion"] not in {
            "pgl.raw.behavior.v1", "pgl.derived.behavior.v3",
        }:
            raise ValueError("Mapping evidence v1 supports only the initial behavioral contracts.")

        # Inventories must describe these exact manifests, not a different
        # internally consistent pair passed alongside them.
        for label, inventory, manifest in (
            ("Source", sourceFiles, sourceManifest),
            ("Destination", destinationFiles, destinationManifest),
        ):
            if type(inventory) is not dict:
                raise TypeError(f"{label} file inventory must be a dictionary.")
            cls._compareExportManifestIdentity(manifest, inventory.get("manifest"))

        fileComparison = cls._compareExportFileInventory(
            sourceFiles, destinationFiles,
        )
        matrixComparison = cls._compareExportMatrixInventory(
            sourceMatrices, destinationMatrices,
            sourceManifest=sourceManifest,
            destinationManifest=destinationManifest,
        )
        lineage = cls._compareExportCheckpointLineage(
            sourceAncestry, destinationAncestry,
            sourceDatabaseID=sourceDatabaseID,
            destinationDatabaseID=destinationDatabaseID,
            sessionIDMapping=sessionIDMapping,
        )

        sourceProjection = cls._prepareExportSessionMetadata(
            sourceRecord, sourceCreator, sourceManifest,
            sourceDatabaseID=sourceDatabaseID,
            verifiedLabels=verifiedLabels,
        )
        destinationProjection = cls._prepareExportSessionMetadata(
            destinationRecord, destinationCreator, destinationManifest,
            sourceDatabaseID=destinationDatabaseID,
            verifiedLabels=verifiedLabels,
        )
        if (
            pglStorage.encodeJSON(sourceProjection["preservedFields"])
            != pglStorage.encodeJSON(destinationProjection["preservedFields"])
        ):
            raise ValueError("Destination preserved metadata differs from source.")

        sourceID = sourceRecord["session_id"]
        destinationID = destinationRecord["session_id"]
        if sessionIDMapping.get(sourceID) != destinationID:
            raise ValueError("Selected catalog records disagree with the explicit mapping.")

        # The full-chain comparator validates chain shape. Here bind the
        # selected records to that chain instead of trusting unrelated reports.
        fieldPairs = (
            ("session_id", "sessionID"),
            ("parent_session_id", "parentSessionID"),
            ("root_session_id", "rootSessionID"),
            ("origin", "origin"),
            ("kind", "kind"),
            ("status", "status"),
            ("deleted_at", "deletedAt"),
            ("manifest_hash", "manifestHash"),
            ("contract_version", "contractVersion"),
        )
        for label, record, ancestry in (
            ("Source", sourceRecord, sourceAncestry),
            ("Destination", destinationRecord, destinationAncestry),
        ):
            matches = [
                item for item in ancestry
                if item["sessionID"] == record["session_id"]
            ]
            if len(matches) != 1:
                raise ValueError(f"{label} selected record is absent from its ancestry.")
            checkpoint = matches[0]
            if any(record[column] != checkpoint[field] for column, field in fieldPairs):
                raise ValueError(f"{label} selected metadata differs from its ancestry.")
            if datetime.fromisoformat(record["completed_at"]) != checkpoint["completedAt"]:
                raise ValueError(f"{label} completion time differs from its ancestry.")

        historyFiles = [
            record for record in fileComparison["files"]
            if record["name"] == "history.json"
        ]
        if not historyFiles:
            if manifestIdentity["contractVersion"] != "pgl.raw.behavior.v1" or history is not None:
                raise ValueError("History absence does not match the supported raw contract.")
            historyEvidence = {
                "state": "absentUnderContract",
                "identity": None,
                "referenceInspection": None,
            }
        else:
            if len(historyFiles) != 1 or history is None:
                raise ValueError("Verified restored history is required for this manifest.")
            inspection = cls._inspectExportHistoryReferences(
                history,
                sourceDatabaseID=sourceDatabaseID,
                sourceSessionIDs=[item["sessionID"] for item in sourceAncestry],
            )
            historyEvidence = {
                "state": "present",
                "identity": {
                    field: historyFiles[0][field]
                    for field in ("sha256", "size_bytes")
                },
                "referenceInspection": inspection,
            }

        destinationPublication = {
            "creator": deepcopy(destinationCreator),
            **{
                name: destinationRecord[name]
                for name in (
                    "created_at", "started_at", "completed_at", "saved_timezone",
                )
            },
        }
        evidence = {
            "contractVersion": "pgl.session.export.bytePreserving.v1",
            "source": {
                "databaseID": sourceDatabaseID,
                "sessionID": sourceID,
                "manifestHash": manifestIdentity["sha256"],
                "contractVersion": manifestIdentity["contractVersion"],
            },
            "destination": {
                "databaseID": destinationDatabaseID,
                "sessionID": destinationID,
                "manifestHash": manifestIdentity["sha256"],
                "contractVersion": manifestIdentity["contractVersion"],
            },
            "manifest": sourceManifest,
            "lineage": lineage,
            "sourceProvenance": sourceProjection["sourceProvenance"],
            "preservedMetadataAtPublication": sourceProjection["preservedFields"],
            "destinationPublication": destinationPublication,
            "files": {
                "records": fileComparison["files"],
                "logicalBytes": fileComparison["logicalBytes"],
            },
            "matrices": {
                field: matrixComparison[field]
                for field in ("attachments", "revisions", "bundleBytes")
            },
            "history": historyEvidence,
            "verificationPolicy": {
                "transferMode": "bytePreserving",
                "requiredMatrixCoverage": "allGridChunks",
                "historyReferencePolicy": "selectedAncestryActionInputsV2NoProductConsumption",
                "evidenceMeaning": "callerAttestationWithInternalCorrespondenceChecks",
                "dependencyCompletenessEstablished": False,
                "scientificValuesVerified": False,
                "publicationTimeMatrixIntegrityEstablished": False,
                "sourceAuthenticityEstablishedByDocument": False,
                "atomicFilesystemSQLPublication": False,
                "foreignResolutionAuthorizedByDocument": False,
            },
        }

        # Require canonical JSON encodability without changing native historical
        # values or inventing string representations for unsupported objects.
        pglStorage.encodeJSON(evidence)
        return deepcopy(evidence)
    
    @classmethod
    def _validateExportMappingEvidence(cls, evidence):
        """Validate the persisted initial byte-preserving evidence document.

        Supports pgl.session.export.bytePreserving.v1 for behavioral chains:
            Raw root: pgl.raw.behavior.v1.
            Derived checkpoints: pgl.derived.behavior.v3.

        Checks exact document fields, JSON types, qualified identities,
        manifest correspondence, explicit lineage, source metadata projection,
        file/matrix identities and totals, bounded history-reference reports,
        destination publication metadata, and fixed verification limitations.

        Validates stored facts directly. Does not fabricate catalog records,
        restored histories, timestamps, or verification observations.

        Returns an independent copy of the validated document.
        Errors propagate; unsupported forms are rejected.

        IMPORTANT:
            Structurally consistent evidence can still be invented.
            Successful validation does not establish source authenticity,
            actual SQL/payload existence, current visibility, scientific
            validity, performed byte verification, or foreign authorization.

        Caller must separately bind this document to its mapping-table row,
        the actual destination database/checkpoint/lineage, and the required
        destination catalog/payload checks.

        No SQL, filesystem access, scientific restoration, mapping insertion,
        input mutation, or bundleInventoryComplete promotion.
        """
        from copy import deepcopy
        from datetime import datetime
        from uuid import UUID
        import math
        import re

        def requireFields(value, fields, label):
            if type(value) is not dict or set(value) != set(fields):
                raise ValueError(f"{label}: missing or unexpected fields.")

        def requireJSON(value, active):
            """Reject non-JSON Python values rather than silently coercing them."""
            if value is None or type(value) in (str, bool, int): return
            if type(value) is float:
                if not math.isfinite(value): raise ValueError("Evidence contains nonfinite JSON.")
                return
            if type(value) not in (dict, list):
                raise ValueError("Evidence must contain only plain JSON types.")
            if id(value) in active: raise ValueError("Evidence contains a cycle.")
            active.add(id(value))
            try:
                children = value.values() if type(value) is dict else value
                if type(value) is dict and any(type(key) is not str for key in value):
                    raise ValueError("Evidence JSON keys must be strings.")
                for child in children: requireJSON(child, active)
            finally:
                active.remove(id(value))

        def requireEqual(left, right, label):
            # Canonical comparison distinguishes JSON true from integer 1.
            if pglStorage.encodeJSON(left) != pglStorage.encodeJSON(right):
                raise ValueError(f"{label}: values disagree.")

        def validateID(value, label):
            if type(value) is not int or not 0 <= value <= 9223372036854775807:
                raise ValueError(f"{label}: invalid PostgreSQL bigint.")

        def validateCount(value, label):
            if type(value) is not int or value < 0:
                raise ValueError(f"{label}: invalid count/size.")

        def validateUUID(value, label):
            if type(value) is not str:
                raise ValueError(f"{label}: invalid UUID.")
            try:
                parsed = UUID(value)
            except ValueError as error:
                raise ValueError(f"{label}: invalid UUID.") from error
            if str(parsed) != value or not parsed.int:
                raise ValueError(f"{label}: UUID must be canonical and nonzero.")

        def validateText(value, label, *, nullable=False):
            if value is None and nullable: return
            if (
                type(value) is not str or not value.strip()
                or any(character in value for character in ("\x00", "\n", "\r"))
            ):
                raise ValueError(f"{label}: invalid text.")

        def validateHash(value, label):
            if type(value) is not str or re.fullmatch(r"[0-9a-f]{64}", value) is None:
                raise ValueError(f"{label}: invalid SHA-256.")

        def validatePath(value):
            if (
                type(value) is not str or not value or value.startswith("/")
                or "\\" in value
                or any(character in value for character in ("\x00", "\n", "\r"))
                or any(part in ("", ".", "..") for part in value.split("/"))
            ):
                raise ValueError("Invalid evidence-relative file path.")

        def parseTimestamp(value, label, *, nullable=False):
            if value is None and nullable: return None
            if type(value) is not str:
                raise ValueError(f"{label}: expected ISO timestamp.")
            try:
                parsed = datetime.fromisoformat(value)
            except ValueError as error:
                raise ValueError(f"{label}: invalid timestamp.") from error
            if parsed.tzinfo is None or parsed.utcoffset() is None:
                raise ValueError(f"{label}: timestamp must be timezone-aware.")
            return parsed

        requireJSON(evidence, set())
        requireFields(evidence, {
            "contractVersion", "source", "destination", "manifest", "lineage",
            "sourceProvenance", "preservedMetadataAtPublication",
            "destinationPublication", "files", "matrices", "history",
            "verificationPolicy",
        }, "Evidence")
        if evidence["contractVersion"] != "pgl.session.export.bytePreserving.v1":
            raise ValueError("Unsupported mapping evidence contract.")
        evidence = deepcopy(evidence)

        expectedPolicy = {
            "transferMode": "bytePreserving",
            "requiredMatrixCoverage": "allGridChunks",
            "historyReferencePolicy": "selectedAncestryActionInputsV2NoProductConsumption",
            "evidenceMeaning": "callerAttestationWithInternalCorrespondenceChecks",
            "dependencyCompletenessEstablished": False,
            "scientificValuesVerified": False,
            "publicationTimeMatrixIntegrityEstablished": False,
            "sourceAuthenticityEstablishedByDocument": False,
            "atomicFilesystemSQLPublication": False,
            "foreignResolutionAuthorizedByDocument": False,
        }
        requireEqual(evidence["verificationPolicy"], expectedPolicy, "Verification policy")

        manifest = evidence["manifest"]
        manifestIdentity = cls._compareExportManifestIdentity(manifest, manifest)
        if manifestIdentity["contractVersion"] not in {
            "pgl.raw.behavior.v1", "pgl.derived.behavior.v3",
        }:
            raise ValueError("Unsupported evidence manifest contract.")

        for label in ("source", "destination"):
            endpoint = evidence[label]
            requireFields(endpoint, {
                "databaseID", "sessionID", "manifestHash", "contractVersion",
            }, label)
            validateUUID(endpoint["databaseID"], f"{label} database")
            validateID(endpoint["sessionID"], f"{label} session")
            validateHash(endpoint["manifestHash"], f"{label} manifest")
            requireEqual(
                [endpoint["manifestHash"], endpoint["contractVersion"]],
                [manifestIdentity["sha256"], manifestIdentity["contractVersion"]],
                f"{label} manifest binding",
            )

        source = evidence["source"]
        destination = evidence["destination"]
        if source["databaseID"] == destination["databaseID"]:
            raise ValueError("Evidence requires distinct source/destination databases.")

        lineage = evidence["lineage"]
        requireFields(lineage, {
            "sourceDatabaseID", "destinationDatabaseID", "checkpoints",
        }, "Lineage")
        requireEqual(
            [lineage["sourceDatabaseID"], lineage["destinationDatabaseID"]],
            [source["databaseID"], destination["databaseID"]],
            "Lineage database binding",
        )
        chain = lineage["checkpoints"]
        if type(chain) is not list or not chain:
            raise ValueError("Evidence lineage must be a nonempty list.")

        sourceIDs, destinationIDs = [], []
        for index, record in enumerate(chain):
            requireFields(record, {
                "sourceSessionID", "destinationSessionID",
                "sourceParentSessionID", "destinationParentSessionID",
                "sourceRootSessionID", "destinationRootSessionID",
                "origin", "kind", "contractVersion", "manifestHash",
            }, "Lineage checkpoint")
            for field in (
                "sourceSessionID", "destinationSessionID",
                "sourceRootSessionID", "destinationRootSessionID",
            ):
                validateID(record[field], field)
            for field in ("sourceParentSessionID", "destinationParentSessionID"):
                if record[field] is not None: validateID(record[field], field)
            validateHash(record["manifestHash"], "Lineage manifest")

            if (
                record["sourceSessionID"] in sourceIDs
                or record["destinationSessionID"] in destinationIDs
            ):
                raise ValueError("Lineage mapping must be one-to-one without duplicate IDs.")
            sourceIDs.append(record["sourceSessionID"])
            destinationIDs.append(record["destinationSessionID"])

            if index == 0:
                requireEqual(
                    [record["origin"], record["kind"], record["contractVersion"]],
                    ["raw", "acquired", "pgl.raw.behavior.v1"],
                    "Raw lineage contract",
                )
                expectedParents = [None, None]
            else:
                requireEqual(
                    [record["origin"], record["kind"], record["contractVersion"]],
                    ["derived", "processed", "pgl.derived.behavior.v3"],
                    "Derived lineage contract",
                )
                expectedParents = [sourceIDs[index - 1], destinationIDs[index - 1]]

            requireEqual(
                [record["sourceParentSessionID"], record["destinationParentSessionID"]],
                expectedParents, "Lineage parent relationships",
            )
            requireEqual(
                [record["sourceRootSessionID"], record["destinationRootSessionID"]],
                [sourceIDs[0], destinationIDs[0]], "Lineage root relationships",
            )

        if source["sessionID"] not in sourceIDs:
            raise ValueError("Selected source checkpoint is absent from lineage.")
        selected = chain[sourceIDs.index(source["sessionID"])]
        requireEqual(
            [selected["destinationSessionID"], selected["manifestHash"], selected["contractVersion"]],
            [destination["sessionID"], source["manifestHash"], source["contractVersion"]],
            "Selected lineage binding",
        )

        provenance = evidence["sourceProvenance"]
        requireFields(provenance, {
            "sourceDatabaseID", "sourceSessionID", "sessionMetadata", "creator",
        }, "Source provenance")
        requireEqual(
            [provenance["sourceDatabaseID"], provenance["sourceSessionID"]],
            [source["databaseID"], source["sessionID"]],
            "Source provenance binding",
        )
        sourceMetadata = provenance["sessionMetadata"]
        if (
            type(sourceMetadata) is not dict
            or type(sourceMetadata.get("meta")) is not dict
            or "pgl_session_labels" not in sourceMetadata["meta"]
        ):
            raise ValueError("Source evidence lacks explicit catalog labels.")

        # Reuse metadata representation checks. These embedded labels are NOT
        # independently verified here; only stored internal consistency is tested.
        projection = cls._prepareExportSessionMetadata(
            sourceMetadata, provenance["creator"], manifest,
            sourceDatabaseID=source["databaseID"],
            verifiedLabels=sourceMetadata["meta"]["pgl_session_labels"],
        )
        requireEqual(projection["sourceProvenance"], provenance, "Source metadata projection")
        requireEqual(
            projection["preservedFields"], evidence["preservedMetadataAtPublication"],
            "Preserved metadata snapshot",
        )
        for column, field in (
            ("session_id", "sourceSessionID"),
            ("parent_session_id", "sourceParentSessionID"),
            ("root_session_id", "sourceRootSessionID"),
            ("origin", "origin"), ("kind", "kind"),
            ("manifest_hash", "manifestHash"), ("contract_version", "contractVersion"),
        ):
            requireEqual(sourceMetadata[column], selected[field], "Source metadata/lineage binding")

        publication = evidence["destinationPublication"]
        requireFields(publication, {
            "creator", "created_at", "started_at", "completed_at", "saved_timezone",
        }, "Destination publication")
        creator = publication["creator"]
        requireFields(creator, {"sourceUserID", "username", "displayName"}, "Destination creator")
        # Retain the builder's existing creator representation. Here sourceUserID
        # is the observed destination creator ID, not a source-database user ID.
        validateID(creator["sourceUserID"], "Destination creator ID")
        if (
            type(creator["username"]) is not str or not creator["username"].strip()
            or "\x00" in creator["username"]
        ):
            raise ValueError("Invalid destination creator username.")
        if creator["displayName"] is not None and (
            type(creator["displayName"]) is not str or "\x00" in creator["displayName"]
        ):
            raise ValueError("Invalid destination creator display name.")
        parseTimestamp(publication["created_at"], "Destination creation")
        started = parseTimestamp(publication["started_at"], "Destination start", nullable=True)
        completed = parseTimestamp(publication["completed_at"], "Destination completion")
        if started is not None and completed < started:
            raise ValueError("Destination completion precedes start.")
        timezoneName = publication["saved_timezone"]
        if timezoneName is not None:
            validateText(timezoneName, "Destination timezone")
            if timezoneName != timezoneName.strip():
                raise ValueError("Destination timezone has surrounding whitespace.")

        files = evidence["files"]
        requireFields(files, {"records", "logicalBytes"}, "Files")
        if type(files["records"]) is not list:
            raise ValueError("Evidence file records must be a list.")
        payloadRole = "acquisition" if selected["origin"] == "raw" else "derived"
        expectedFiles = {
            item["name"]: {
                "sha256": item["sha256"], "size_bytes": item["size_bytes"],
                "role": "history" if item["name"] == "history.json" else payloadRole,
            }
            for item in manifest["files"]
        }
        if "manifest.json" in expectedFiles:
            raise ValueError("Reserved manifest filename in payload inventory.")
        expectedFiles["manifest.json"] = {
            "sha256": manifestIdentity["sha256"],
            "size_bytes": manifestIdentity["size_bytes"],
            "role": "manifest",
        }
        names = []
        for record in files["records"]:
            requireFields(record, {
                "name", "sha256", "size_bytes", "role", "subjectID",
            }, "File record")
            validatePath(record["name"])
            validateHash(record["sha256"], "File identity")
            validateID(record["size_bytes"], "File size")
            if record["name"] not in expectedFiles:
                raise ValueError("Unexpected evidence file.")
            requireEqual(
                {key: record[key] for key in ("sha256", "size_bytes", "role")},
                expectedFiles[record["name"]], "File/manifest correspondence",
            )
            subject = record["subjectID"]
            if subject is not None and (
                type(subject) is not str or not subject.strip() or "\x00" in subject
            ):
                raise ValueError("Invalid evidence subject ID.")
            names.append(record["name"])
        if names != sorted(expectedFiles):
            raise ValueError("Evidence files must exactly cover the manifest in sorted order.")
        validateCount(files["logicalBytes"], "Logical bytes")
        if files["logicalBytes"] != sum(item["size_bytes"] for item in files["records"]):
            raise ValueError("Evidence logical byte total differs.")

        matrices = evidence["matrices"]
        requireFields(matrices, {"attachments", "revisions", "bundleBytes"}, "Matrices")
        if type(matrices["attachments"]) is not list or type(matrices["revisions"]) is not list:
            raise ValueError("Evidence matrix collections must be lists.")
        products = cls._validateSessionProductRecords(manifest.get("products", []))
        expectedAttachments = sorted([
            {
                "catalogName": item["name"], "owner": "session",
                "localName": item["name"], "matrixRevisionID": item["matrixRevisionID"],
            }
            for item in products
        ], key=lambda item: item["catalogName"])
        requireEqual(matrices["attachments"], expectedAttachments, "Matrix attachment correspondence")
        expectedRevisionIDs = sorted({item["matrixRevisionID"] for item in products})
        revisionIDs = []

        for revision in matrices["revisions"]:
            requireFields(revision, {
                "matrixRevisionID", "contractVersion", "descriptor", "files", "bundleBytes",
            }, "Matrix revision")
            validateUUID(revision["matrixRevisionID"], "Matrix revision")
            if revision["contractVersion"] != pglStorage.MATRIX_CONTRACT:
                raise ValueError("Unsupported matrix evidence contract.")
            pglStorage._validateMatrixDescriptor(revision["descriptor"])
            if revision["descriptor"]["matrixRevisionID"] != revision["matrixRevisionID"]:
                raise ValueError("Matrix descriptor identifies another revision.")
            if type(revision["files"]) is not list:
                raise ValueError("Matrix byte records must be a list.")

            matrixNames = []
            for record in revision["files"]:
                requireFields(record, {"name", "sha256", "size_bytes"}, "Matrix file")
                validatePath(record["name"])
                if record["name"] != "matrix.json" and not record["name"].startswith("data.zarr/"):
                    raise ValueError("Unexpected matrix bundle filename.")
                validateHash(record["sha256"], "Matrix file hash")
                validateCount(record["size_bytes"], "Matrix file size")
                matrixNames.append(record["name"])
            if matrixNames != sorted(set(matrixNames)):
                raise ValueError("Matrix filenames must be unique and sorted.")
            if not {
                "matrix.json", "data.zarr/.zgroup", "data.zarr/.zattrs", "data.zarr/.zmetadata",
            }.issubset(matrixNames):
                raise ValueError("Matrix evidence lacks required metadata files.")
            validateCount(revision["bundleBytes"], "Matrix bundle bytes")
            if revision["bundleBytes"] != sum(item["size_bytes"] for item in revision["files"]):
                raise ValueError("Matrix bundle byte total differs.")
            revisionIDs.append(revision["matrixRevisionID"])

        if revisionIDs != expectedRevisionIDs:
            raise ValueError("Matrix revisions must exactly cover declared products in sorted order.")
        validateCount(matrices["bundleBytes"], "Aggregate matrix bytes")
        if matrices["bundleBytes"] != sum(item["bundleBytes"] for item in matrices["revisions"]):
            raise ValueError("Aggregate matrix byte total differs.")

        history = evidence["history"]
        requireFields(history, {"state", "identity", "referenceInspection"}, "History")
        historyIdentity = expectedFiles.get("history.json")
        if historyIdentity is None:
            requireEqual(history, {
                "state": "absentUnderContract",
                "identity": None,
                "referenceInspection": None,
            }, "Absent history")
            if source["contractVersion"] != "pgl.raw.behavior.v1":
                raise ValueError("Unsupported history absence.")
        else:
            if history["state"] != "present":
                raise ValueError("Manifest requires present history evidence.")
            requireEqual(
                history["identity"],
                {key: historyIdentity[key] for key in ("sha256", "size_bytes")},
                "History file binding",
            )
            report = history["referenceInspection"]
            requireFields(report, {
                "sourceDatabaseID", "sourceSessionIDs", "actionCount",
                "checkpointReferences", "unboundWorkingInputs",
                "structuredCheckpointReferencesCovered", "dependencyCompletenessEstablished",
            }, "History reference inspection")
            requireEqual(
                [report["sourceDatabaseID"], report["sourceSessionIDs"]],
                [source["databaseID"], sourceIDs], "History scope",
            )
            requireEqual(
                [report["structuredCheckpointReferencesCovered"], report["dependencyCompletenessEstablished"]],
                [True, False], "History verification limits",
            )
            validateCount(report["actionCount"], "History action count")
            positions = set()

            for field in ("checkpointReferences", "unboundWorkingInputs"):
                records = report[field]
                if type(records) is not list:
                    raise ValueError("History input reports must be lists.")
                orderedPositions = []
                for record in records:
                    fields = {"actionIndex", "inputIndex"}
                    if field == "checkpointReferences": fields.add("checkpoint")
                    requireFields(record, fields, "History input position")
                    validateCount(record["actionIndex"], "Action index")
                    validateCount(record["inputIndex"], "Input index")
                    if record["actionIndex"] >= report["actionCount"]:
                        raise ValueError("History action index is outside action count.")
                    position = (record["actionIndex"], record["inputIndex"])
                    if position in positions:
                        raise ValueError("Duplicate or overlapping history input positions.")
                    positions.add(position)
                    orderedPositions.append(position)

                    if field == "checkpointReferences":
                        reference = record["checkpoint"]
                        requireFields(reference, {
                            "databaseID", "sessionID", "databaseName",
                        }, "History checkpoint")
                        validateUUID(reference["databaseID"], "History database")
                        validateID(reference["sessionID"], "History session")
                        validateText(reference["databaseName"], "History database label")
                        if (
                            reference["databaseID"] != source["databaseID"]
                            or reference["sessionID"] not in sourceIDs
                        ):
                            raise ValueError("History reference is outside declared lineage.")
                if orderedPositions != sorted(orderedPositions):
                    raise ValueError("History input positions must be ordered.")

        pglStorage.encodeJSON(evidence)
        return evidence
    
    @classmethod
    def _verifyExportDestinationCatalog(cls, connection, postgres, evidence):
        """Bind validated export evidence to actual destination catalog records.

        Transaction modes:
            REPEATABLE READ / SERIALIZABLE, READ ONLY for inspection.
            READ COMMITTED with an already-held session publication lock for
            publication. Does not acquire that lock or change transactions.

        Checks migration compatibility and actual stable database UUID, the
        complete recorded destination chain, selected checkpoint metadata and
        publication fields, exact file links, and matrix attachments/descriptors.

        Later checkpoint_name/description edits are permitted. Source metadata
        and original annotation snapshots in evidence remain unchanged.

        File locations must be catalog-eligible; matrix backends must be active.
        Catalog eligibility is NOT a fresh payload-byte verification.

        Returns a bounded catalog-binding result explicitly requiring payload
        verification. Does not insert/read an export mapping row or authorize
        foreign resolution. Mapping-row correspondence remains separate.

        Source authenticity and the historical verification claims cannot be
        established from destination catalogs alone.

        No payload access, scientific loading, writes, commits, lock acquisition,
        automatic cleanup, or mutation of the supplied evidence.
        """
        from datetime import datetime

        from psycopg.rows import tuple_row

        checked = cls._validateExportMappingEvidence(evidence)
        cls._requireMigrationInspectionTransaction(connection)

        sessions = sql.Identifier(postgres.databaseSchema, "session")
        links = sql.Identifier(postgres.databaseSchema, "session_files")
        files = sql.Identifier(postgres.databaseSchema, "files")
        locations = sql.Identifier(postgres.databaseSchema, "storage_locations")
        backends = sql.Identifier(postgres.databaseSchema, "storage_backends")
        products = sql.Identifier(postgres.databaseSchema, "session_products")
        revisions = sql.Identifier(postgres.databaseSchema, "matrix_revisions")

        with connection.cursor(row_factory=tuple_row) as cursor:
            cursor.execute("SHOW transaction_isolation")
            isolation = cursor.fetchone()[0]
            cursor.execute("SHOW transaction_read_only")
            readOnly = cursor.fetchone()[0]

            if isolation in ("repeatable read", "serializable") and readOnly == "on":
                pass
            elif isolation == "read committed" and readOnly == "off":
                # Verify ownership of the already-acquired relation lock.
                # A normal RowExclusiveLock from INSERT is not sufficient.
                cursor.execute(sql.SQL("""
                    /* exportDestinationPublicationLock */
                    SELECT EXISTS (
                        SELECT 1
                        FROM pg_catalog.pg_locks AS held
                        WHERE held.pid = pg_catalog.pg_backend_pid()
                          AND held.locktype = 'relation'
                          AND held.relation = %s::regclass
                          AND held.granted
                          AND held.mode IN (
                              'ShareRowExclusiveLock',
                              'ExclusiveLock',
                              'AccessExclusiveLock'
                          )
                    )
                """), (sessions.as_string(connection),))
                if cursor.fetchone() != (True,):
                    raise ValueError("Destination catalog verification requires the publication lock.")
            else:
                raise ValueError("Unsupported transaction mode for destination catalog verification.")

        actualDatabaseID = cls._requireStableDatabaseIdentity(connection, postgres)
        if actualDatabaseID != checked["destination"]["databaseID"]:
            raise ValueError("Actual destination database UUID differs from evidence.")

        expectedChain = checked["lineage"]["checkpoints"]
        destinationIDs = [record["destinationSessionID"] for record in expectedChain]
        destinationID = checked["destination"]["sessionID"]

        with connection.cursor(row_factory=tuple_row) as cursor:
            cursor.execute(sql.SQL("""
                /* exportDestinationSessionRows */
                SELECT checkpoint.session_id, to_jsonb(checkpoint)
                FROM {} AS checkpoint
                WHERE checkpoint.session_id = ANY(%s::bigint[])
                ORDER BY checkpoint.session_id
            """).format(sessions), (destinationIDs,))
            sessionRows = cursor.fetchall()

        actualSessions = {}
        for sessionID, record in sessionRows:
            if (
                type(sessionID) is not int or sessionID in actualSessions
                or type(record) is not dict or record.get("session_id") != sessionID
            ):
                raise ValueError("Invalid or duplicate destination session catalog record.")
            actualSessions[sessionID] = record

        if set(actualSessions) != set(destinationIDs):
            raise ValueError("Destination catalog does not contain the exact evidence chain.")

        def requireEqual(actual, expected, label):
            if pglStorage.encodeJSON(actual) != pglStorage.encodeJSON(expected):
                raise ValueError(f"Destination {label} differs from evidence.")

        def parseTimestamp(value, label):
            if type(value) is not str:
                raise ValueError(f"Invalid destination {label} timestamp.")
            try:
                result = datetime.fromisoformat(value)
            except ValueError as error:
                raise ValueError(f"Invalid destination {label} timestamp.") from error
            if result.tzinfo is None or result.utcoffset() is None:
                raise ValueError(f"Destination {label} timestamp must be timezone-aware.")
            return result

        for expected in expectedChain:
            actual = actualSessions[expected["destinationSessionID"]]
            if actual.get("status") != "complete" or actual.get("deleted_at") is not None:
                raise ValueError("Destination lineage contains an inactive or incomplete checkpoint.")

            for column, field in (
                ("parent_session_id", "destinationParentSessionID"),
                ("root_session_id", "destinationRootSessionID"),
                ("origin", "origin"),
                ("kind", "kind"),
                ("contract_version", "contractVersion"),
                ("manifest_hash", "manifestHash"),
            ):
                if column not in actual:
                    raise ValueError(f"Destination lineage lacks {column}.")
                requireEqual(actual[column], expected[field], f"lineage {column}")
            parseTimestamp(actual.get("completed_at"), "completion")

        actual = actualSessions[destinationID]
        sourceMetadata = checked["sourceProvenance"]["sessionMetadata"]
        if set(actual) != set(sourceMetadata):
            raise ValueError("Destination session schema differs from the supported metadata columns.")

        for field, value in checked["preservedMetadataAtPublication"].items():
            # These annotations are explicitly editable after completion.
            if field in ("checkpoint_name", "description"): continue
            requireEqual(actual[field], value, f"preserved {field}")

        publication = checked["destinationPublication"]
        requireEqual(
            actual["created_by"], publication["creator"]["sourceUserID"],
            "publication creator ID",
        )
        requireEqual(actual["saved_timezone"], publication["saved_timezone"], "saved timezone")
        for field in ("created_at", "started_at", "completed_at"):
            actualValue, expectedValue = actual[field], publication[field]
            if actualValue is None or expectedValue is None:
                requireEqual(actualValue, expectedValue, field)
            elif parseTimestamp(actualValue, field) != parseTimestamp(expectedValue, field):
                raise ValueError(f"Destination publication {field} differs from evidence.")

        # Creator labels are snapshots, not cross-database identity authority.
        # The actual immutable destination creator ID is bound above; label
        # edits in users do not invalidate an otherwise matching checkpoint.

        with connection.cursor(row_factory=tuple_row) as cursor:
            cursor.execute(sql.SQL("""
                /* exportDestinationFileRows */
                SELECT link.name, content.file_id, content.sha256,
                       content.size_bytes, link.role, link.subject_id,
                       link.deleted_at, content.deleted_at,
                       EXISTS (
                           SELECT 1
                           FROM {} AS location
                           JOIN {} AS backend ON backend.backend_id = location.backend_id
                           WHERE location.file_id = content.file_id
                             AND location.deleted_at IS NULL
                             AND location.status = 'present'
                             AND location.verified_at IS NOT NULL
                             AND backend.is_active
                       )
                FROM {} AS link
                LEFT JOIN {} AS content ON content.file_id = link.file_id
                WHERE link.session_id = %s
                ORDER BY link.name
            """).format(locations, backends, links, files), (destinationID,))
            fileRows = cursor.fetchall()

        actualFiles = []
        seenNames = set()
        identitiesByID = {}
        for name, fileID, digest, size, role, subjectID, linkDeleted, contentDeleted, eligible in fileRows:
            if (
                not isinstance(name, str) or name in seenNames
                or type(fileID) is not int or fileID < 0
                or type(size) is not int or size < 0
            ):
                raise ValueError("Invalid destination file catalog record.")
            if linkDeleted is not None or contentDeleted is not None or eligible is not True:
                raise ValueError("Destination file lacks active catalog links/content/locations.")
            identity = (digest, size)
            if fileID in identitiesByID and identitiesByID[fileID] != identity:
                raise ValueError("Destination file ID has conflicting identities.")
            identitiesByID[fileID] = identity
            seenNames.add(name)
            actualFiles.append({
                "name": name, "sha256": digest, "size_bytes": size,
                "role": role, "subjectID": subjectID,
            })

        requireEqual(actualFiles, checked["files"]["records"], "file catalog")

        with connection.cursor(row_factory=tuple_row) as cursor:
            cursor.execute(sql.SQL("""
                /* exportDestinationMatrixRows */
                SELECT product.product_name, product.matrix_revision_id::text,
                       revision.contract_version, revision.descriptor,
                       revision.backend_id, revision.object_key,
                       backend.url_prefix, backend.is_active
                FROM {} AS product
                LEFT JOIN {} AS revision
                  ON revision.matrix_revision_id = product.matrix_revision_id
                LEFT JOIN {} AS backend ON backend.backend_id = revision.backend_id
                WHERE product.session_id = %s
                ORDER BY product.product_name
            """).format(products, revisions, backends), (destinationID,))
            matrixRows = cursor.fetchall()

        expectedRevisions = {
            record["matrixRevisionID"]: record
            for record in checked["matrices"]["revisions"]
        }
        actualAttachments = []
        seenProducts = set()
        observedRevisions = {}

        for name, revisionID, contract, descriptor, backendID, key, root, active in matrixRows:
            if not isinstance(name, str) or name in seenProducts:
                raise ValueError("Invalid or duplicate destination matrix attachment.")
            if revisionID not in expectedRevisions:
                raise ValueError("Unexpected destination matrix revision.")
            if type(backendID) is not int or backendID < 0 or active is not True:
                raise ValueError("Destination matrix backend is missing, invalid, or inactive.")
            if (
                not isinstance(key, str) or not key or key.startswith("/")
                or "\\" in key
                or any(character in key for character in ("\x00", "\n", "\r"))
                or any(part in ("", ".", "..") for part in key.split("/"))
                or not isinstance(root, str) or not root.strip()
                or any(character in root for character in ("\x00", "\n", "\r"))
            ):
                raise ValueError("Invalid destination matrix storage location.")

            expected = expectedRevisions[revisionID]
            requireEqual(contract, expected["contractVersion"], "matrix contract")
            requireEqual(descriptor, expected["descriptor"], "matrix descriptor")
            location = {
                "backendID": backendID, "objectKey": key, "registeredRoot": root,
            }
            if revisionID in observedRevisions:
                requireEqual(location, observedRevisions[revisionID], "shared matrix location")
            observedRevisions[revisionID] = location
            seenProducts.add(name)
            actualAttachments.append({
                "catalogName": name, "owner": "session", "localName": name,
                "matrixRevisionID": revisionID,
            })

        requireEqual(
            actualAttachments, checked["matrices"]["attachments"],
            "matrix attachments",
        )
        if set(observedRevisions) != set(expectedRevisions):
            raise ValueError("Destination matrix revisions do not exactly cover evidence.")

        return {
            "destinationDatabaseID": actualDatabaseID,
            "destinationSessionID": destinationID,
            "catalogBindingChecked": True,
            "lineageCheckpointCount": len(destinationIDs),
            "fileCount": len(actualFiles),
            "matrixRevisionCount": len(observedRevisions),
            "payloadBytesVerified": False,
            "requiresPayloadVerification": True,
            "mappingRowBindingChecked": False,
            "foreignResolutionAuthorized": False,
        }
        
    @classmethod
    def _verifyExportDestinationPayloads(
        cls, connection, postgres, evidence, *, storageOptionsByBackend=None,
        progress=None,
    ):
        """Verify current destination bytes against validated mapping evidence.

        Requires the transaction/locking conditions enforced by
        _verifyExportDestinationCatalog(). Rechecks that binding after I/O.

        Checkpoint files:
            Select the first eligible catalog location in priority/backend/key
            order. Hash every logical file against evidence. No fallback.

        Matrices:
            Resolve each distinct registered revision and verify its descriptor,
            exact stored-file inventory, and strict grid-chunk coverage.

        Returns selected locations and actual verified byte totals. Does not
        persist verification results or refresh catalog verification timestamps.

        Owns a bounded pglDatabaseAccess context. Closes it on success/failure.
        Local selected paths receive ancestor-symlink checks.

        Catalog checks and hashing are not an atomic snapshot. Concurrent
        payload mutation is unsupported. Generic backend safety depends on
        accurate listings and metadata.

        Does not establish source authenticity, integrity since original matrix
        publication, scientific decoding/value validity, or universal dependency
        completeness. Does not bind a mapping-table row or authorize foreign
        resolution, even when all destination bytes match.

        No SQL writes, copying, cleanup, scientific loading, or commits.
        Optional progress is a pglProgress-compatible call/section reporter.
        Ranges allocate work, not elapsed-time estimates. Helpers never
        finish the enclosing operation. The public caller supplies a
        display-failure-isolated adapter; direct callback errors propagate.

        """
        from pathlib import Path
        import posixpath

        from fsspec.implementations.local import LocalFileSystem
        from psycopg.rows import tuple_row

        if progress is not None: progress(0, "Checking destination catalog and payload locations")
        checked = cls._validateExportMappingEvidence(evidence)
        catalogBefore = cls._verifyExportDestinationCatalog(connection, postgres, checked)
        sessionID = checked["destination"]["sessionID"]

        links = sql.Identifier(postgres.databaseSchema, "session_files")
        files = sql.Identifier(postgres.databaseSchema, "files")
        locations = sql.Identifier(postgres.databaseSchema, "storage_locations")
        backends = sql.Identifier(postgres.databaseSchema, "storage_backends")
        revisions = sql.Identifier(postgres.databaseSchema, "matrix_revisions")
        products = sql.Identifier(postgres.databaseSchema, "session_products")

        with connection.cursor(row_factory=tuple_row) as cursor:
            cursor.execute(sql.SQL("""
                /* exportDestinationPayloadFileLocations */
                SELECT link.name, content.sha256, content.size_bytes,
                       backend.backend_id, backend.url_prefix, location.object_key
                FROM {} AS link
                JOIN {} AS content ON content.file_id = link.file_id
                JOIN {} AS location ON location.file_id = content.file_id
                JOIN {} AS backend ON backend.backend_id = location.backend_id
                WHERE link.session_id = %s
                  AND link.deleted_at IS NULL
                  AND content.deleted_at IS NULL
                  AND location.deleted_at IS NULL
                  AND location.status = 'present'
                  AND location.verified_at IS NOT NULL
                  AND backend.is_active
                ORDER BY link.name, location.priority,
                         backend.backend_id, location.object_key
            """).format(links, files, locations, backends), (sessionID,))
            fileRows = cursor.fetchall()

            cursor.execute(sql.SQL("""
                /* exportDestinationPayloadMatrixLocations */
                SELECT revision.matrix_revision_id::text,
                       revision.contract_version, revision.descriptor,
                       revision.backend_id, backend.url_prefix, revision.object_key
                FROM {} AS revision
                JOIN {} AS backend ON backend.backend_id = revision.backend_id
                WHERE backend.is_active
                  AND EXISTS (
                      SELECT 1 FROM {} AS product
                      WHERE product.session_id = %s
                        AND product.matrix_revision_id = revision.matrix_revision_id
                  )
                ORDER BY revision.matrix_revision_id
            """).format(revisions, backends, products), (sessionID,))
            matrixRows = cursor.fetchall()

        def validateLocation(backendID, root, key):
            if type(backendID) is not int or not 0 <= backendID <= 9223372036854775807:
                raise ValueError("Invalid destination payload backend ID.")
            if (
                not isinstance(root, str) or not root.strip()
                or any(character in root for character in ("\x00", "\n", "\r"))
                or not isinstance(key, str) or not key or key.startswith("/")
                or "\\" in key
                or any(character in key for character in ("\x00", "\n", "\r"))
                or any(part in ("", ".", "..") for part in key.split("/"))
            ):
                raise ValueError("Invalid destination payload location.")
            return {"backendID": backendID, "registeredRoot": root, "objectKey": key}

        def requireLocalSafe(filesystem, path):
            if isinstance(filesystem, LocalFileSystem):
                localPath = Path(path).absolute()
                for candidate in (localPath, *localPath.parents):
                    if candidate.is_symlink():
                        raise ValueError(f"Symlinked destination payload path: {candidate}")

        expectedFiles = {record["name"]: record for record in checked["files"]["records"]}
        selectedFiles = {}
        for name, digest, size, backendID, root, key in fileRows:
            if name not in expectedFiles:
                raise ValueError("Unexpected destination payload file link.")
            expected = expectedFiles[name]
            if (
                type(size) is not int
                or digest != expected["sha256"] or size != expected["size_bytes"]
            ):
                raise ValueError("Destination payload catalog identity differs from evidence.")
            if name not in selectedFiles:
                selectedFiles[name] = validateLocation(backendID, root, key)

        if set(selectedFiles) != set(expectedFiles):
            raise ValueError("Destination files lack eligible registered payload locations.")

        expectedMatrices = {
            record["matrixRevisionID"]: record
            for record in checked["matrices"]["revisions"]
        }
        selectedMatrices = {}
        for revisionID, contract, descriptor, backendID, root, key in matrixRows:
            if revisionID not in expectedMatrices or revisionID in selectedMatrices:
                raise ValueError("Unexpected or duplicate destination matrix location.")
            expected = expectedMatrices[revisionID]
            if (
                contract != expected["contractVersion"]
                or pglStorage.encodeJSON(descriptor) != pglStorage.encodeJSON(expected["descriptor"])
            ):
                raise ValueError("Destination matrix catalog differs from evidence.")
            selectedMatrices[revisionID] = validateLocation(backendID, root, key)

        if set(selectedMatrices) != set(expectedMatrices):
            raise ValueError("Destination matrix revisions lack eligible locations.")

        fileResults = []
        matrixResults = []
        fileWork = [expectedFiles[name] for name in sorted(expectedFiles)]
        matrixWork = [
            {"name": revisionID, "size_bytes": expectedMatrices[revisionID]["bundleBytes"]}
            for revisionID in sorted(expectedMatrices)
        ]
        fileWeight = sum(max(1, record["size_bytes"]) for record in fileWork)
        matrixWeight = sum(max(1, record["size_bytes"]) for record in matrixWork)
        # Floating-point rounding must not exceed the next section's endpoint.
        split = min(0.95, max(0.05, 0.05 + 0.90 * fileWeight / max(1, fileWeight + matrixWeight)))
        filesProgress = progress.section(0.05, split) if progress is not None else None
        matricesProgress = progress.section(split, 0.95) if progress is not None else None
        with pglDatabaseAccess(postgres, storageOptionsByBackend) as access:
            for item, fileProgress in pglProgress.fileSections(fileWork, filesProgress):
                name = item["name"]
                location = selectedFiles[name]
                filesystem, root = access.resolve(
                    location["backendID"], location["registeredRoot"],
                )
                path = posixpath.join(root, location["objectKey"])
                requireLocalSafe(filesystem, path)
                actual = pglStorage.hashFile(
                    filesystem, path, progress=fileProgress,
                    expectedSize=expectedFiles[name]["size_bytes"],
                    description="Verifying destination file",
                )
                expected = {
                    field: expectedFiles[name][field]
                    for field in ("sha256", "size_bytes")
                }
                if actual != expected:
                    raise ValueError(f"Destination payload bytes differ from evidence: {name}")
                fileResults.append({"name": name, **actual, "location": location})

            for item, matrixProgress in pglProgress.fileSections(matrixWork, matricesProgress):
                revisionID = item["name"]
                expected = expectedMatrices[revisionID]
                location = selectedMatrices[revisionID]
                filesystem, root = access.resolve(
                    location["backendID"], location["registeredRoot"],
                )
                path = posixpath.join(root, location["objectKey"])
                requireLocalSafe(filesystem, path)
                actual = pglStorage.inventoryDataMatrixBundleLayout(
                    path,
                    filesystem=filesystem,
                    expectedDescriptor=expected["descriptor"],
                    expectedFiles=expected["files"],
                    requireAllChunks=True,
                    progress=matrixProgress,
                )
                if actual["bundleBytes"] != expected["bundleBytes"]:
                    raise ValueError("Verified destination matrix byte total differs from evidence.")
                matrixResults.append({
                    "matrixRevisionID": revisionID,
                    "bundleBytes": actual["bundleBytes"],
                    "location": location,
                })

        if progress is not None: progress(0.95, "Rechecking destination catalog after payload hashing")
        catalogAfter = cls._verifyExportDestinationCatalog(connection, postgres, checked)
        if catalogAfter != catalogBefore:
            raise ValueError("Destination catalog binding changed during payload verification.")
        if progress is not None: progress(1, "Destination payload bytes verified")

        return {
            "destinationDatabaseID": checked["destination"]["databaseID"],
            "destinationSessionID": sessionID,
            "files": fileResults,
            "matrices": matrixResults,
            "logicalFileBytes": sum(record["size_bytes"] for record in fileResults),
            "matrixBundleBytes": sum(record["bundleBytes"] for record in matrixResults),
            "payloadBytesVerified": True,
            "strictMatrixCoverageChecked": True,
            "mappingRowBindingChecked": False,
            "foreignResolutionAuthorized": False,
        }
        
    @classmethod
    def _validateExportMappingBinding(cls, inspection):
        """Check mapping/evidence correspondence in a foreign-reference inspection.

        inspection:
            Result of _inspectCheckpointReference() for a foreign reference.
            Must be an active completed candidate requiring verification.

        Validates:
            Requested source-qualified reference against evidence.
            Actual inspected destination UUID and selected checkpoint ID.
            Mapping source/destination manifest hashes and contracts.
            Selected destination parent/root, origin-independent contract/hash
            identity, completion timestamp, and current active completed state.
            Mapping registration metadata representation.

        Profile labels are descriptive, not identity authority.
        Mapping registeredBy need not equal the destination checkpoint creator.
        Current checkpoint annotations may differ from publication snapshots.

        Returns validated evidence and explicit bindings, without authorizing
        foreign resolution or claiming catalog/payload verification.

        This is pure correspondence validation of supplied observations.
        The caller must obtain inspection from the actual destination database
        in an appropriate transaction, then perform current destination catalog
        and payload verification under the intended authorization policy.

        Does not query SQL, inspect other mapping rows in the chain, validate
        source authenticity, insert mappings, mutate inspection, or change
        requiresVerification in the original inspector result.
        """
        from copy import deepcopy
        from datetime import datetime

        requiredFields = {
            "reference", "destinationDatabaseID", "resolutionKind",
            "destinationSessionID", "state", "checkpoint", "mapping",
            "requiresVerification",
        }
        if type(inspection) is not dict or set(inspection) != requiredFields:
            raise ValueError("Invalid checkpoint-reference inspection fields.")
        inspection = deepcopy(inspection)

        if (
            inspection["resolutionKind"] != "exportMapping"
            or inspection["state"] != "candidate"
            or inspection["requiresVerification"] is not True
        ):
            raise ValueError("Mapping binding requires an unverified foreign candidate.")

        def requireFields(value, fields, label):
            if type(value) is not dict or set(value) != set(fields):
                raise ValueError(f"Invalid {label} fields.")

        def requireEqual(actual, expected, label):
            if pglStorage.encodeJSON(actual) != pglStorage.encodeJSON(expected):
                raise ValueError(f"{label} differs from mapping evidence.")

        def validateLabel(value, label):
            if (
                type(value) is not str or not value.strip()
                or any(character in value for character in ("\x00", "\n", "\r"))
            ):
                raise ValueError(f"Invalid {label}.")

        def requireTimestamp(value, label):
            if (
                not isinstance(value, datetime)
                or value.tzinfo is None or value.utcoffset() is None
            ):
                raise ValueError(f"{label} must be a timezone-aware datetime.")

        reference = inspection["reference"]
        requireFields(reference, {"databaseID", "sessionID", "databaseName"}, "reference")
        validateLabel(reference["databaseName"], "reference database label")

        mapping = inspection["mapping"]
        requireFields(mapping, {
            "destinationSessionID", "sourceDatabaseName",
            "sourceManifestHash", "destinationManifestHash",
            "sourceContractVersion", "destinationContractVersion",
            "verification", "registeredBy", "registeredAt",
        }, "mapping")
        validateLabel(mapping["sourceDatabaseName"], "mapping source label")
        if (
            type(mapping["registeredBy"]) is not int
            or not 0 <= mapping["registeredBy"] <= 9223372036854775807
        ):
            raise ValueError("Invalid mapping registrant ID.")
        requireTimestamp(mapping["registeredAt"], "Mapping registration time")

        evidence = cls._validateExportMappingEvidence(mapping["verification"])
        source = evidence["source"]
        destination = evidence["destination"]

        requireEqual(reference["databaseID"], source["databaseID"], "Requested source database")
        requireEqual(reference["sessionID"], source["sessionID"], "Requested source session")
        requireEqual(
            inspection["destinationDatabaseID"], destination["databaseID"],
            "Inspected destination database",
        )
        requireEqual(
            inspection["destinationSessionID"], destination["sessionID"],
            "Inspected destination session",
        )
        requireEqual(
            mapping["destinationSessionID"], destination["sessionID"],
            "Mapping destination session",
        )
        for field, expected in (
            ("sourceManifestHash", source["manifestHash"]),
            ("destinationManifestHash", destination["manifestHash"]),
            ("sourceContractVersion", source["contractVersion"]),
            ("destinationContractVersion", destination["contractVersion"]),
        ):
            requireEqual(mapping[field], expected, field)

        checkpoint = inspection["checkpoint"]
        requireFields(checkpoint, {
            "status", "deletedAt", "manifestHash", "contractVersion",
            "checkpointName", "description", "completedAt",
            "parentSessionID", "rootSessionID",
        }, "checkpoint")
        if checkpoint["status"] != "complete" or checkpoint["deletedAt"] is not None:
            # includeDeleted=True may still produce a candidate; it must not
            # make a deleted destination eligible for this binding operation.
            raise ValueError("Mapping destination must be active and complete.")

        requireEqual(checkpoint["manifestHash"], destination["manifestHash"], "Checkpoint manifest")
        requireEqual(
            checkpoint["contractVersion"], destination["contractVersion"],
            "Checkpoint contract",
        )
        selected = next(
            record for record in evidence["lineage"]["checkpoints"]
            if record["sourceSessionID"] == source["sessionID"]
        )
        requireEqual(
            checkpoint["parentSessionID"], selected["destinationParentSessionID"],
            "Checkpoint parent",
        )
        requireEqual(
            checkpoint["rootSessionID"], selected["destinationRootSessionID"],
            "Checkpoint root",
        )
        requireTimestamp(checkpoint["completedAt"], "Checkpoint completion time")
        if checkpoint["completedAt"] != datetime.fromisoformat(
            evidence["destinationPublication"]["completed_at"]
        ):
            raise ValueError("Checkpoint completion time differs from mapping evidence.")

        return {
            "sourceDatabaseID": source["databaseID"],
            "sourceSessionID": source["sessionID"],
            "destinationDatabaseID": destination["databaseID"],
            "destinationSessionID": destination["sessionID"],
            "evidence": evidence,
            "mappingRowCorrespondenceChecked": True,
            "requiresDestinationVerification": True,
            "foreignResolutionAuthorized": False,
        }
        
    @classmethod
    def _inspectExistingSessionExport(
        cls, connection, postgres, reference, *, storageOptionsByBackend=None,
        progress=None,
    ):
        """Inspect an existing foreign export without publishing or repairing it.

        Requires a caller-owned REPEATABLE READ or SERIALIZABLE, READ ONLY
        transaction. Checks migration compatibility and destination identity.

        Initial reconciliation policy:
            No selected mapping: return state='unmapped'.
            Selected mapping exists: require every source-qualified mapping in
            its recorded chain. Each must contain the same recorded full chain
            and agree on its selected source/destination binding.

        Runs mapping-row correspondence, actual destination catalog checks, and
        fresh destination payload verification for every checkpoint in the chain.

        Returns:
            state: 'unmapped' or 'verifiedExistingExport'.
            Selected source reference and destination identity.
            Per-checkpoint mapping bindings and payload verification results.

        An unmapped selected reference does not assert that the destination has
        no related raw manifests, matrices, or partial earlier exports.

        Successful reconciliation establishes current destination correspondence
        to stored application evidence. It does not contact or authenticate the
        source, compare its current annotations, establish scientific validity,
        authorize publication/reuse, or authorize foreign-reference loading.

        Different recorded export scopes are rejected by this initial policy;
        merging overlapping independently verified exports is not implemented.

        Reads SQL and payloads only. Does not acquire publication locks, modify
        transaction settings, insert mappings, retry publication, repair records,
        delete files, or mutate the supplied reference.
        Optional progress is a pglProgress-compatible call/section reporter.
        Ranges allocate work, not elapsed-time estimates. Helpers never
        finish the enclosing operation. The public caller supplies a
        display-failure-isolated adapter; direct callback errors propagate.

        """
        from copy import deepcopy

        from psycopg.rows import tuple_row

        cls._requireMigrationInspectionTransaction(connection)
        with connection.cursor(row_factory=tuple_row) as cursor:
            cursor.execute("SHOW transaction_isolation")
            isolation = cursor.fetchone()[0]
            cursor.execute("SHOW transaction_read_only")
            readOnly = cursor.fetchone()[0]
        if isolation not in ("repeatable read", "serializable") or readOnly != "on":
            raise ValueError("Existing export inspection requires a consistent read-only transaction.")

        destinationDatabaseID = cls._requireStableDatabaseIdentity(connection, postgres)
        selectedInspection = cls._inspectCheckpointReference(
            connection, postgres, deepcopy(reference),
        )
        if selectedInspection["resolutionKind"] != "exportMapping":
            raise ValueError("Existing export inspection requires a foreign checkpoint reference.")

        result = {
            "reference": deepcopy(selectedInspection["reference"]),
            "destinationDatabaseID": destinationDatabaseID,
            "destinationSessionID": selectedInspection["destinationSessionID"],
            "state": None,
            "checkpoints": [],
            "sourceRevalidated": False,
            "publicationAuthorized": False,
            "reuseAuthorized": False,
            "foreignResolutionAuthorized": False,
        }
        if selectedInspection["state"] == "unmapped":
            result["state"] = "unmapped"
            if progress is not None: progress(1, "Selected checkpoint has no export mapping")
            return result

        selectedBinding = cls._validateExportMappingBinding(selectedInspection)
        lineage = selectedBinding["evidence"]["lineage"]
        lineageBytes = pglStorage.encodeJSON(lineage)

        # An inspector's metadata query identifies the real destination UUID;
        # retain the explicit match instead of relying only on supplied evidence.
        if selectedBinding["destinationDatabaseID"] != destinationDatabaseID:
            raise ValueError("Selected export binding identifies a different destination database.")

        bindings = []
        for checkpoint in lineage["checkpoints"]:
            sourceID = checkpoint["sourceSessionID"]
            chainReference = {
                "databaseID": selectedBinding["sourceDatabaseID"],
                "sessionID": sourceID,
                "databaseName": selectedInspection["reference"]["databaseName"],
            }
            inspection = cls._inspectCheckpointReference(
                connection, postgres, chainReference,
            )
            binding = cls._validateExportMappingBinding(inspection)

            if (
                binding["sourceDatabaseID"] != selectedBinding["sourceDatabaseID"]
                or binding["destinationDatabaseID"] != destinationDatabaseID
                or binding["sourceSessionID"] != sourceID
                or binding["destinationSessionID"] != checkpoint["destinationSessionID"]
            ):
                raise ValueError("Existing export chain contains a conflicting mapping.")
            if pglStorage.encodeJSON(binding["evidence"]["lineage"]) != lineageBytes:
                raise ValueError("Existing export mappings have different recorded chain scopes.")

            # Match the selected mapping seen at entry as well. A consistent SQL
            # snapshot protects catalog reads, not external payload mutation.
            if sourceID == selectedBinding["sourceSessionID"]:
                if pglStorage.encodeJSON(binding["evidence"]) != pglStorage.encodeJSON(
                    selectedBinding["evidence"]
                ):
                    raise ValueError("Selected mapping evidence changed during inspection.")
            bindings.append(binding)

        # Establish the full mapping chain before doing expensive payload I/O.
        work = [
            {
                "name": f"Checkpoint {binding['sourceSessionID']}",
                "size_bytes": (
                    binding["evidence"]["files"]["logicalBytes"]
                    + binding["evidence"]["matrices"]["bundleBytes"]
                ),
                "binding": binding,
            }
            for binding in bindings
        ]
        payloadProgress = progress.section(0.05, 0.99) if progress is not None else None
        for item, checkpointProgress in pglProgress.fileSections(work, payloadProgress):
            binding = item["binding"]
            payloads = cls._verifyExportDestinationPayloads(
                connection, postgres, binding["evidence"],
                storageOptionsByBackend=storageOptionsByBackend,
                progress=checkpointProgress,
            )
            if (
                payloads["destinationDatabaseID"] != destinationDatabaseID
                or payloads["destinationSessionID"] != binding["destinationSessionID"]
                or payloads["payloadBytesVerified"] is not True
                or payloads["strictMatrixCoverageChecked"] is not True
            ):
                raise ValueError("Existing export payload verification returned inconsistent results.")

            result["checkpoints"].append({
                "sourceSessionID": binding["sourceSessionID"],
                "destinationSessionID": binding["destinationSessionID"],
                "mappingBinding": binding,
                "payloadVerification": payloads,
            })

        result["state"] = "verifiedExistingExport"
        if progress is not None: progress(1, "Existing destination export verified")
        return result
    
    @classmethod
    def _verifyExportCurrentSource(
        cls, connection, postgres, reconciliation, *,
        storageOptionsByBackend=None,
        progress=None,
    ):
        """Verify current source observations against a reconciled export scope.

        reconciliation:
            Result of _inspectExistingSessionExport() with
            state='verifiedExistingExport'.

        Requires a caller-owned REPEATABLE READ or SERIALIZABLE, READ ONLY
        transaction. Revalidates source migrations and stable database UUID.

        Checks:
            Exact source ancestry matching the recorded full export chain.
            Current manifests and logical file identities/roles/subjects.
            Every current source file against its registered/evidence identity.
            Matrix descriptors, attachments, stored bytes, and strict coverage.
            Complete source metadata and creator snapshot.

        Source location policy:
            First eligible file location in catalog order, without fallback.
            Matrix locations use the existing bundle inventory coordinator.

        Metadata policy:
            Exact recorded source snapshot, including editable annotations and
            creator labels. Timestamp strings compare by timezone-aware instant.
            Drift blocks verification; no refresh or annotation-update policy
            is inferred.

        Does not reauthenticate a supplied reconciliation result or freshly
        reverify the destination. The caller must obtain destination
        reconciliation independently through the real inspection path.

        Exact history bytes are checked through their file identity. This does
        not rerun history restoration or establish universal dependency closure.

        Owns bounded source payload access. No SQL writes, publication, mapping
        insertion, repair, cleanup, source authentication, or authorization for
        reuse/foreign loading.

        Source and destination SQL snapshots are independent. Filesystem
        hashing is not atomic; concurrent payload mutation remains unsupported.
        Optional progress is a pglProgress-compatible call/section reporter.
        Ranges allocate work, not elapsed-time estimates. Helpers never
        finish the enclosing operation. The public caller supplies a
        display-failure-isolated adapter; direct callback errors propagate.

        """
        from copy import deepcopy
        from datetime import datetime, timezone
        from pathlib import Path
        import posixpath

        from fsspec.implementations.local import LocalFileSystem
        from psycopg.rows import tuple_row

        cls._requireMigrationInspectionTransaction(connection)
        with connection.cursor(row_factory=tuple_row) as cursor:
            cursor.execute("SHOW transaction_isolation")
            isolation = cursor.fetchone()[0]
            cursor.execute("SHOW transaction_read_only")
            readOnly = cursor.fetchone()[0]
        if isolation not in ("repeatable read", "serializable") or readOnly != "on":
            raise ValueError("Current-source verification requires a consistent read-only transaction.")

        if (
            type(reconciliation) is not dict
            or reconciliation.get("state") != "verifiedExistingExport"
            or type(reconciliation.get("checkpoints")) is not list
            or not reconciliation["checkpoints"]
        ):
            raise ValueError("Current-source verification requires a reconciled existing export.")
        reconciliation = deepcopy(reconciliation)

        def requireEqual(actual, expected, label):
            if pglStorage.encodeJSON(actual) != pglStorage.encodeJSON(expected):
                raise ValueError(f"{label} differs from recorded export evidence.")

        documents = []
        for item in reconciliation["checkpoints"]:
            if type(item) is not dict or type(item.get("mappingBinding")) is not dict:
                raise ValueError("Invalid reconciled checkpoint binding.")
            binding = item["mappingBinding"]
            document = cls._validateExportMappingEvidence(binding.get("evidence"))
            for field in ("sourceSessionID", "destinationSessionID"):
                endpoint = "source" if field == "sourceSessionID" else "destination"
                requireEqual(item.get(field), document[endpoint]["sessionID"], field)
                requireEqual(binding.get(field), document[endpoint]["sessionID"], field)
            requireEqual(
                binding.get("sourceDatabaseID"), document["source"]["databaseID"],
                "Reconciled source UUID",
            )
            requireEqual(
                binding.get("destinationDatabaseID"), document["destination"]["databaseID"],
                "Reconciled destination UUID",
            )
            documents.append(document)

        lineage = documents[0]["lineage"]
        chain = lineage["checkpoints"]
        sourceDatabaseID = lineage["sourceDatabaseID"]
        destinationDatabaseID = lineage["destinationDatabaseID"]

        requireEqual(
            reconciliation.get("destinationDatabaseID"), destinationDatabaseID,
            "Reconciliation destination",
        )
        reference = reconciliation.get("reference")
        if type(reference) is not dict:
            raise ValueError("Reconciliation lacks its selected reference.")
        requireEqual(reference.get("databaseID"), sourceDatabaseID, "Selected source database")
        selected = [
            item for item in chain if item["sourceSessionID"] == reference.get("sessionID")
        ]
        if len(selected) != 1:
            raise ValueError("Selected source reference is outside the recorded chain.")
        requireEqual(
            reconciliation.get("destinationSessionID"),
            selected[0]["destinationSessionID"], "Selected destination",
        )

        requireEqual(
            [document["source"]["sessionID"] for document in documents],
            [item["sourceSessionID"] for item in chain],
            "Reconciled full-chain coverage",
        )
        for document, item in zip(documents, chain):
            requireEqual(document["lineage"], lineage, "Recorded chain scope")
            requireEqual(
                document["destination"]["sessionID"], item["destinationSessionID"],
                "Recorded destination mapping",
            )

        actualSourceID = cls._requireStableDatabaseIdentity(connection, postgres)
        if actualSourceID != sourceDatabaseID:
            raise ValueError("Actual source database UUID differs from recorded export evidence.")

        ancestry = cls._readExportAncestry(
            connection, postgres, chain[-1]["sourceSessionID"],
        )
        requireEqual(
            [item["sessionID"] for item in ancestry],
            [item["sourceSessionID"] for item in chain],
            "Current source ancestry scope",
        )

        def normalizeTimes(record):
            """Preserve all fields while comparing timestamps by instant."""
            if type(record) is not dict:
                raise ValueError("Source metadata must contain a catalog object.")
            result = deepcopy(record)
            for field in (
                "created_at", "started_at", "completed_at", "acquired_at", "deleted_at",
            ):
                if field not in result:
                    raise ValueError(f"Source metadata lacks {field}.")
                value = result[field]
                if value is None: continue
                if type(value) is not str:
                    raise ValueError(f"Invalid source timestamp representation: {field}")
                try:
                    parsed = datetime.fromisoformat(value)
                except ValueError as error:
                    raise ValueError(f"Invalid source timestamp: {field}") from error
                if parsed.tzinfo is None or parsed.utcoffset() is None:
                    raise ValueError(f"Source timestamp must be timezone-aware: {field}")
                result[field] = parsed.astimezone(timezone.utc).isoformat()
            return result

        def validateLocation(location):
            if type(location) is not dict:
                raise ValueError("Invalid source payload location.")
            backendID = location.get("backendID")
            root = location.get("registeredRoot")
            key = location.get("objectKey")
            if type(backendID) is not int or not 0 <= backendID <= 9223372036854775807:
                raise ValueError("Invalid source backend ID.")
            if (
                not isinstance(root, str) or not root.strip()
                or any(character in root for character in ("\x00", "\n", "\r"))
                or not isinstance(key, str) or not key or key.startswith("/")
                or "\\" in key
                or any(character in key for character in ("\x00", "\n", "\r"))
                or any(part in ("", ".", "..") for part in key.split("/"))
            ):
                raise ValueError("Invalid selected source payload path.")
            return {"backendID": backendID, "registeredRoot": root, "objectKey": key}

        sessions = sql.Identifier(postgres.databaseSchema, "session")
        users = sql.Identifier(postgres.databaseSchema, "users")
        results = []

        work = [
            {
                "name": f"Source checkpoint {checkpoint['sessionID']}",
                "size_bytes": document["files"]["logicalBytes"] + document["matrices"]["bundleBytes"],
                "checkpoint": checkpoint, "expectedChain": expectedChain, "document": document,
            }
            for checkpoint, expectedChain, document in zip(ancestry, chain, documents)
        ]
        sourceProgress = progress.section(0.02, 0.99) if progress is not None else None
        with pglDatabaseAccess(postgres, storageOptionsByBackend) as access:
            for item, checkpointProgress in pglProgress.fileSections(work, sourceProgress):
                checkpoint = item["checkpoint"]
                expectedChain = item["expectedChain"]
                document = item["document"]
                sessionID = checkpoint["sessionID"]
                for actualField, recordedField in (
                    ("sessionID", "sourceSessionID"),
                    ("parentSessionID", "sourceParentSessionID"),
                    ("rootSessionID", "sourceRootSessionID"),
                    ("origin", "origin"), ("kind", "kind"),
                    ("manifestHash", "manifestHash"),
                    ("contractVersion", "contractVersion"),
                ):
                    requireEqual(
                        checkpoint[actualField], expectedChain[recordedField],
                        f"Source checkpoint {sessionID} {actualField}",
                    )

                with connection.cursor(row_factory=tuple_row) as cursor:
                    cursor.execute(sql.SQL("""
                        SELECT to_jsonb(checkpoint)
                        FROM {} AS checkpoint WHERE session_id = %s
                    """).format(sessions), (sessionID,))
                    row = cursor.fetchone()
                    if row is None: raise ValueError("Source checkpoint metadata is absent.")
                    metadata = row[0]
                    cursor.execute(sql.SQL("""
                        SELECT user_id, username, display_name
                        FROM {} WHERE user_id = %s
                    """).format(users), (metadata["created_by"],))
                    creatorRow = cursor.fetchone()
                if creatorRow is None:
                    raise ValueError("Source creator record is absent.")

                provenance = document["sourceProvenance"]
                requireEqual(
                    normalizeTimes(metadata),
                    normalizeTimes(provenance["sessionMetadata"]),
                    f"Source checkpoint {sessionID} metadata snapshot",
                )
                creator = dict(zip(
                    ("sourceUserID", "username", "displayName"), creatorRow,
                ))
                requireEqual(creator, provenance["creator"], "Source creator snapshot")

                currentFiles = cls._readExportFileInventory(
                    connection, postgres, checkpoint,
                    storageOptionsByBackend=storageOptionsByBackend,
                )
                manifest = currentFiles["manifest"]
                cls._compareExportManifestIdentity(manifest, document["manifest"])
                projectedFiles = cls._compareExportFileInventory(currentFiles, currentFiles)
                requireEqual({
                    "records": projectedFiles["files"],
                    "logicalBytes": projectedFiles["logicalBytes"],
                }, document["files"], "Current source file catalog")

                verifiedFiles = []
                fileWeight = sum(max(1, record["size_bytes"]) for record in currentFiles["files"])
                matrixWeight = sum(
                    max(1, revision["bundleBytes"])
                    for revision in document["matrices"]["revisions"]
                )
                # Floating-point rounding must not exceed the next section's endpoint.
                split = min(0.95, max(0.05, 0.05 + 0.90 * fileWeight / max(1, fileWeight + matrixWeight)))
                filesProgress = (
                    checkpointProgress.section(0.05, split)
                    if checkpointProgress is not None else None
                )
                for record, fileProgress in pglProgress.fileSections(
                    currentFiles["files"], filesProgress,
                ):
                    candidates = record.get("locations")
                    if type(candidates) is not list or not candidates:
                        raise ValueError("Source file lacks an eligible location.")
                    location = validateLocation(candidates[0])
                    filesystem, root = access.resolve(
                        location["backendID"], location["registeredRoot"],
                    )
                    path = posixpath.join(root, location["objectKey"])
                    if isinstance(filesystem, LocalFileSystem):
                        localPath = Path(path).absolute()
                        for candidate in (localPath, *localPath.parents):
                            if candidate.is_symlink():
                                raise ValueError(f"Symlinked source payload path: {candidate}")
                    actual = pglStorage.hashFile(
                        filesystem, path, progress=fileProgress,
                        expectedSize=record["size_bytes"],
                        description="Verifying current source file",
                    )
                    requireEqual(
                        actual,
                        {field: record[field] for field in ("sha256", "size_bytes")},
                        f"Current source bytes: {record['name']}",
                    )
                    verifiedFiles.append({
                        "name": record["name"], **actual, "location": location,
                    })

                currentMatrices = cls._readExportMatrixBundleInventory(
                    connection, postgres, checkpoint, requireAllChunks=True,
                    storageOptionsByBackend=storageOptionsByBackend,
                    progress=(
                        checkpointProgress.section(split, 0.99)
                        if checkpointProgress is not None else None
                    ),
                )
                projectedMatrices = cls._compareExportMatrixInventory(
                    currentMatrices, currentMatrices,
                    sourceManifest=manifest, destinationManifest=manifest,
                )
                requireEqual({
                    field: projectedMatrices[field]
                    for field in ("attachments", "revisions", "bundleBytes")
                }, document["matrices"], "Current source matrix inventory")

                results.append({
                    "sourceSessionID": sessionID,
                    "destinationSessionID": document["destination"]["sessionID"],
                    "manifestIdentity": projectedFiles["manifestIdentity"],
                    "files": verifiedFiles,
                    "logicalFileBytes": projectedFiles["logicalBytes"],
                    "matrixBundleBytes": projectedMatrices["bundleBytes"],
                    "metadataSnapshotMatches": True,
                    "creatorSnapshotMatches": True,
                })

        if progress is not None: progress(1, "Current source correspondence verified")
        return {
            "sourceDatabaseID": sourceDatabaseID,
            "destinationDatabaseID": destinationDatabaseID,
            "state": "sourceMatchesRecordedExport",
            "checkpoints": results,
            "sourcePayloadBytesVerified": True,
            "sourceMetadataPolicy": "exactSnapshotIncludingAnnotationsAndCreatorLabels",
            "destinationReverifiedByThisCall": False,
            "publicationAuthorized": False,
            "reuseAuthorized": False,
            "foreignResolutionAuthorized": False,
        }
        
    @classmethod
    def _inspectSessionExportDecision(
        cls, sourceConnection, sourcePostgres,
        destinationConnection, destinationPostgres, sessionID, *,
        sourceDatabaseName,
        sourceStorageOptionsByBackend=None,
        destinationStorageOptionsByBackend=None,
        progress=None,
    ):
        """Inspect the initial export decision without publishing or authorizing.

        Caller owns consistent read-only transactions in both databases:
            REPEATABLE READ or SERIALIZABLE, READ ONLY.

        Initial contract scope:
            pgl.raw.behavior.v1 root.
            pgl.derived.behavior.v3 descendants.

        Outcomes:
            verifiedExistingExport:
                Existing recorded export scope reconciles at destination and
                current source matches its recorded evidence. No implicit
                permission to reuse, load, or publish.

            conflict:
                With no selected mapping, required ancestry mappings or
                raw-manifest/matrix UUID matches block new publication.
                No repair, overwrite, automatic reuse, or scope merging.

            newExportCandidate:
                No inspected catalog conflicts. This is not publication-ready:
                source file bytes, matrix layout/bytes, archived labels,
                metadata projection, and supported history dependencies still
                require the normal verification/preparation stages.

        Existing selected mappings are reconciled using their full recorded
        scope, which may extend beyond the selected checkpoint's ancestry.
        Source revalidation checks that recorded scope. Scope is never silently
        shortened or merged.

        Catalog conflicts are snapshot observations. Publication must recheck
        identity, eligibility, and conflicts under its destination lock.

        No new transaction, SQL writes, publication locks, destination creation,
        transfers, retries, cleanup, or ordinary-profile lookup. Reads source
        manifests when inventorying unmapped matrix catalogs; existing-export
        verification reads source and destination payloads.

        Verification/access failures propagate rather than becoming conflict-
        free outcomes. No source-authenticity or foreign-loading authorization
        is established. Cross-database snapshots/filesystems are not atomic.
        Optional progress is a pglProgress-compatible call/section reporter.
        Ranges allocate work, not elapsed-time estimates. Helpers never
        finish the enclosing operation. The public caller supplies a
        display-failure-isolated adapter; direct callback errors propagate.

        """
        from copy import deepcopy

        from psycopg.rows import tuple_row

        if type(sessionID) is not int or not 0 <= sessionID <= 9223372036854775807:
            raise ValueError("sessionID must be a nonnegative PostgreSQL bigint.")
        if (
            type(sourceDatabaseName) is not str or not sourceDatabaseName.strip()
            or any(character in sourceDatabaseName for character in ("\x00", "\n", "\r"))
        ):
            raise ValueError("sourceDatabaseName must be a nonblank display label.")

        for label, connection in (
            ("Source", sourceConnection), ("Destination", destinationConnection),
        ):
            cls._requireMigrationInspectionTransaction(connection)
            with connection.cursor(row_factory=tuple_row) as cursor:
                cursor.execute("SHOW transaction_isolation")
                isolation = cursor.fetchone()[0]
                cursor.execute("SHOW transaction_read_only")
                readOnly = cursor.fetchone()[0]
            if isolation not in ("repeatable read", "serializable") or readOnly != "on":
                raise ValueError(f"{label} export decision requires a consistent read-only transaction.")

        sourceDatabaseID = cls._requireStableDatabaseIdentity(sourceConnection, sourcePostgres)
        destinationDatabaseID = cls._requireStableDatabaseIdentity(
            destinationConnection, destinationPostgres,
        )
        if sourceDatabaseID == destinationDatabaseID:
            raise ValueError("Export decision requires distinct source and destination UUIDs.")

        ancestry = cls._readExportAncestry(sourceConnection, sourcePostgres, sessionID)
        for index, checkpoint in enumerate(ancestry):
            expectedContract = (
                "pgl.raw.behavior.v1" if index == 0 else "pgl.derived.behavior.v3"
            )
            if checkpoint["contractVersion"] != expectedContract:
                raise ValueError("Unsupported checkpoint contract for the initial export decision.")

        reference = {
            "databaseID": sourceDatabaseID,
            "sessionID": sessionID,
            "databaseName": sourceDatabaseName,
        }
        reconciliation = cls._inspectExistingSessionExport(
            destinationConnection, destinationPostgres, reference,
            storageOptionsByBackend=destinationStorageOptionsByBackend,
            progress=progress.section(0, 0.50) if progress is not None else None,
        )

        result = {
            "sourceReference": reference,
            "destinationDatabaseID": destinationDatabaseID,
            "requestedAncestrySessionIDs": [item["sessionID"] for item in ancestry],
            "state": None,
            "conflicts": {
                "ancestryMappings": [],
                "activeRawManifestMatches": [],
                "matrixRevisionCollisions": [],
            },
            "existingExport": None,
            "currentSourceVerification": None,
            "matrixRevisionIDs": [],
            "newExportPreparationComplete": False,
            "publicationTimeRecheckRequired": True,
            "publicationAuthorized": False,
            "reuseAuthorized": False,
            "foreignResolutionAuthorized": False,
        }

        if reconciliation["state"] == "verifiedExistingExport":
            sourceCheck = cls._verifyExportCurrentSource(
                sourceConnection, sourcePostgres, reconciliation,
                storageOptionsByBackend=sourceStorageOptionsByBackend,
                progress=progress.section(0.50, 1) if progress is not None else None,
            )
            if (
                sourceCheck["state"] != "sourceMatchesRecordedExport"
                or sourceCheck["sourceDatabaseID"] != sourceDatabaseID
                or sourceCheck["destinationDatabaseID"] != destinationDatabaseID
            ):
                raise ValueError("Existing-export source verification returned inconsistent identities.")

            result.update({
                "state": "verifiedExistingExport",
                "existingExport": reconciliation,
                "currentSourceVerification": sourceCheck,
                "matrixRevisionIDs": sorted({
                    revision["matrixRevisionID"]
                    for checkpoint in reconciliation["checkpoints"]
                    for revision in checkpoint["mappingBinding"]["evidence"]["matrices"]["revisions"]
                }),
            })
            return deepcopy(result)

        if reconciliation["state"] != "unmapped":
            raise ValueError("Unexpected existing-export reconciliation state.")

        # An unmapped selected checkpoint does not imply unmapped ancestors.
        # Do not verify/reuse partial exports automatically.
        for checkpoint in ancestry:
            inspected = cls._inspectCheckpointReference(
                destinationConnection, destinationPostgres,
                {**reference, "sessionID": checkpoint["sessionID"]},
            )
            if (
                inspected["resolutionKind"] != "exportMapping"
                or inspected["destinationDatabaseID"] != destinationDatabaseID
            ):
                raise ValueError("Unexpected ancestry-reference inspection identity.")
            if inspected["state"] != "unmapped":
                result["conflicts"]["ancestryMappings"].append({
                    "sourceSessionID": checkpoint["sessionID"],
                    "destinationSessionID": inspected["destinationSessionID"],
                    "state": inspected["state"],
                    "mappingPresent": inspected["mapping"] is not None,
                })

        # Reuse the source catalog reader: it checks manifest bytes and exact
        # product links without opening matrix arrays or claiming chunk coverage.
        revisionsByID = {}
        for checkpoint in ancestry:
            matrixCatalog = cls._readExportMatrixInventory(
                sourceConnection, sourcePostgres, checkpoint,
                storageOptionsByBackend=sourceStorageOptionsByBackend,
            )
            for revision in matrixCatalog["revisions"]:
                revisionID = revision["matrixRevisionID"]
                if revisionID in revisionsByID:
                    if pglStorage.encodeJSON(revisionsByID[revisionID]) != pglStorage.encodeJSON(revision):
                        raise ValueError("Source ancestry contains conflicting matrix revision records.")
                revisionsByID[revisionID] = deepcopy(revision)

        revisionIDs = sorted(revisionsByID)
        result["matrixRevisionIDs"] = revisionIDs
        sessions = sql.Identifier(destinationPostgres.databaseSchema, "session")
        revisions = sql.Identifier(destinationPostgres.databaseSchema, "matrix_revisions")

        with destinationConnection.cursor(row_factory=tuple_row) as cursor:
            cursor.execute(sql.SQL("""
                /* exportDecisionRawConflicts */
                SELECT session_id, status, contract_version
                FROM {}
                WHERE origin = 'raw'
                  AND deleted_at IS NULL
                  AND manifest_hash = %s
                ORDER BY session_id
            """).format(sessions), (ancestry[0]["manifestHash"],))
            result["conflicts"]["activeRawManifestMatches"] = [
                {
                    "destinationSessionID": row[0],
                    "status": row[1],
                    "contractVersion": row[2],
                }
                for row in cursor.fetchall()
            ]

            if revisionIDs:
                cursor.execute(sql.SQL("""
                    /* exportDecisionMatrixConflicts */
                    SELECT matrix_revision_id::text, backend_id, object_key
                    FROM {}
                    WHERE matrix_revision_id = ANY(%s::uuid[])
                    ORDER BY matrix_revision_id
                """).format(revisions), (revisionIDs,))
                result["conflicts"]["matrixRevisionCollisions"] = [
                    {
                        "matrixRevisionID": row[0],
                        "backendID": row[1],
                        "objectKey": row[2],
                    }
                    for row in cursor.fetchall()
                ]

        result["state"] = (
            "conflict" if any(result["conflicts"].values()) else "newExportCandidate"
        )
        if progress is not None: progress(1, "Export catalog decision inspected")
        return deepcopy(result)
    
    @classmethod
    def _registerVerifiedSessionExportMapping(
        cls, connection, postgres, evidence, *,
        sourceDatabaseName, registeredBy, storageOptionsByBackend=None,
        progress=None,
    ):
        """Verify destination bytes and register one immutable export mapping.

        Caller responsibilities:
            Own an explicit READ COMMITTED, READ WRITE transaction.
            Acquire the existing checkpoint publication lock before writes.
            Establish source authenticity/access and collect verified source
            observations under the intended export protocol.
            Build evidence from those observations and actual destination rows.
            Commit the outer transaction and handle uncertain commit outcomes.

        Revalidates evidence, then invokes destination catalog/payload
        verification, which also checks actual database UUID, migrations,
        transaction mode, and the caller-held publication lock.

        Inserts a new mapping without ON CONFLICT, replacement, or reuse.
        Existing source-qualified keys raise the original SQL error.

        Reads the inserted mapping through _inspectCheckpointReference() and
        validates exact evidence/registrant correspondence before returning.

        Returns:
            mappingBinding: Validated uncommitted mapping correspondence.
            payloadVerification: Fresh destination verification observations.

        Uses a savepoint. Failures roll back this method's SQL insertion only;
        previously created outer-transaction records remain the caller's
        responsibility. Does not commit, copy/delete payloads, repair mappings,
        alter evidence, or authorize foreign loading.

        Destination correspondence is not source authentication. A caller must
        not submit arbitrary JSON as proof of source equivalence. Registration
        is an application attestation, not independent proof of its history.

        No implicit retries: duplicate conflicts and SQL/access errors propagate.
        A successful return does not mean the outer transaction has committed.
        Optional progress is a pglProgress-compatible call/section reporter.
        Reports only this helper's verification/registration work; never
        finishes the enclosing export. Work ranges are not time estimates.
        Public callers supply a display-failure-isolated reporter; direct
        callback errors propagate. No success update precedes read-back
        validation or successful exit from this helper's savepoint.

        """
        from psycopg.pq import TransactionStatus
        from psycopg.types.json import Jsonb
        from psycopg.rows import tuple_row

        if connection.info.transaction_status != TransactionStatus.INTRANS:
            raise ValueError("Mapping registration requires an active caller-owned transaction.")
        if (
            type(sourceDatabaseName) is not str or not sourceDatabaseName.strip()
            or any(character in sourceDatabaseName for character in ("\x00", "\n", "\r"))
        ):
            raise ValueError("sourceDatabaseName must be a nonblank display label.")
        if type(registeredBy) is not int or not 0 <= registeredBy <= 9223372036854775807:
            raise ValueError("registeredBy must be a nonnegative PostgreSQL bigint.")

        with connection.cursor(row_factory=tuple_row) as cursor:
            cursor.execute("SHOW transaction_isolation")
            isolation = cursor.fetchone()[0]
            cursor.execute("SHOW transaction_read_only")
            readOnly = cursor.fetchone()[0]
        if isolation != "read committed" or readOnly != "off":
            raise ValueError("Mapping registration requires READ COMMITTED, READ WRITE.")

        checked = cls._validateExportMappingEvidence(evidence)
        source = checked["source"]
        destination = checked["destination"]
        reference = {
            "databaseID": source["databaseID"],
            "sessionID": source["sessionID"],
            "databaseName": sourceDatabaseName,
        }
        mappings = sql.Identifier(postgres.databaseSchema, "session_export_mappings")

        if progress is not None: progress(0, "Verifying destination before mapping registration")
        with connection.transaction():
            # This performs real destination checks and requires the existing
            # publication lock. Do not replace it with evidence flags.
            payloadVerification = cls._verifyExportDestinationPayloads(
                connection, postgres, checked,
                storageOptionsByBackend=storageOptionsByBackend,
                **({"progress": progress.section(0.05, 0.90, label="Verifying mapping destination")} if progress is not None else {}),
            )
            if (
                payloadVerification["destinationDatabaseID"] != destination["databaseID"]
                or payloadVerification["destinationSessionID"] != destination["sessionID"]
                or payloadVerification["payloadBytesVerified"] is not True
                or payloadVerification["strictMatrixCoverageChecked"] is not True
            ):
                raise ValueError("Destination verification returned inconsistent mapping identities.")

            if progress is not None: progress(0.90, "Registering immutable mapping and checking read-back")
            with connection.cursor(row_factory=tuple_row) as cursor:
                cursor.execute(sql.SQL("""
                    INSERT INTO {} (
                        source_database_id, source_session_id,
                        destination_session_id, source_database_name,
                        source_manifest_hash, destination_manifest_hash,
                        source_contract_version, destination_contract_version,
                        verification, registered_by
                    )
                    VALUES (%s::uuid, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                """).format(mappings), (
                    source["databaseID"], source["sessionID"],
                    destination["sessionID"], sourceDatabaseName,
                    source["manifestHash"], destination["manifestHash"],
                    source["contractVersion"], destination["contractVersion"],
                    Jsonb(checked), registeredBy,
                ))

            inspection = cls._inspectCheckpointReference(
                connection, postgres, reference,
            )
            binding = cls._validateExportMappingBinding(inspection)
            if (
                pglStorage.encodeJSON(binding["evidence"])
                != pglStorage.encodeJSON(checked)
                or inspection["mapping"]["registeredBy"] != registeredBy
                or inspection["mapping"]["sourceDatabaseName"] != sourceDatabaseName
            ):
                raise ValueError("Registered mapping read-back differs from the supplied attestation.")

        if progress is not None: progress(1, 'Export mapping registered; outer transaction uncommitted')
        return {
            "mappingBinding": binding,
            "payloadVerification": payloadVerification,
            "outerCommitConfirmed": False,
            "foreignResolutionAuthorized": False,
        }
        
    @classmethod
    def _registerExportRawCheckpoint(
        cls, connection, postgres, *,
        sourceDatabaseID, sourceRecord, sourceCreator, manifest,
        expectedDestinationDatabaseID, createdBy, backendID, objectPrefix,
        savedTimezone, accessContext,
        progress=None,
    ):
        """Register a prepared byte-preserving raw behavioral export.

        Initial scope:
            pgl.raw.behavior.v1, with manual/automated ingest_method.
            All saved files already exist under backendID/objectPrefix.
            Explicit source metadata and destination UUID supplied by caller.

        Requires:
            Caller-owned READ COMMITTED, READ WRITE transaction.
            Existing checkpoint publication lock acquired before writes.
            Tuple-row connection conventions used by existing registration
            helpers.
            Borrowed destination pglDatabaseAccess matching postgres.

        Before allocation:
            Validate migrations/destination UUID and source qualification.
            Reject existing source mapping or active raw-manifest match.
            Verify stored canonical manifest bytes.
            Read bounded, hash-verified archived label metadata.
            Project source metadata using independently extracted labels.

        Registration:
            Allocate raw checkpoint, preserve projected metadata, register
            verified file locations/links, require no products, and complete.
            Recheck completion and preserved metadata before returning.

        Uses a savepoint. Errors roll back SQL performed inside this method;
        outer-transaction work remains the caller's responsibility. Sequence
        allocations may remain consumed after rollback.

        Does not enumerate unexpected physical files outside the declared
        inventory. The transfer/preparation layer is responsible for the exact
        destination directory inventory. Concurrent mutation is unsupported.

        Caller must establish actual source metadata/manifest authenticity.
        This method verifies prepared destination bytes, not a live source.

        Returns destination ID/hash/metadata and the source metadata projection.
        Source provenance is returned, not durably stored here.

        No commit, mapping insertion, copying, deletion, scientific loading,
        retry/reuse, or foreign-resolution authorization. Does not close the
        borrowed access context or its filesystem.
        Optional progress is a pglProgress-compatible call/section reporter.
        Reports only this helper's verification/registration work; never
        finishes the enclosing export. Work ranges are not time estimates.
        Public callers supply a display-failure-isolated reporter; direct
        callback errors propagate. No success update precedes read-back
        validation or successful exit from this helper's savepoint.

        """
        from copy import deepcopy
        from datetime import datetime
        from pathlib import Path
        from uuid import UUID
        from zoneinfo import ZoneInfo
        import hashlib
        import io
        import posixpath

        from fsspec.implementations.local import LocalFileSystem
        from psycopg.pq import TransactionStatus
        from psycopg.rows import tuple_row
        from psycopg.types.json import Jsonb

        if connection.info.transaction_status != TransactionStatus.INTRANS:
            raise ValueError("Raw export registration requires an active caller-owned transaction.")

        def validateUUID(value, label):
            if type(value) is not str:
                raise ValueError(f"Invalid {label}.")
            try:
                parsed = UUID(value)
            except ValueError as error:
                raise ValueError(f"Invalid {label}.") from error
            if str(parsed) != value or not parsed.int:
                raise ValueError(f"{label} must be canonical and nonzero.")

        def validateID(value, label):
            if type(value) is not int or not 0 <= value <= 9223372036854775807:
                raise ValueError(f"{label} must be a nonnegative PostgreSQL bigint.")

        def validatePath(value):
            if (
                type(value) is not str or not value or value.startswith("/")
                or "\\" in value
                or any(character in value for character in ("\x00", "\n", "\r"))
                or any(part in ("", ".", "..") for part in value.split("/"))
            ):
                raise ValueError("Invalid raw export relative path.")

        validateUUID(sourceDatabaseID, "sourceDatabaseID")
        validateUUID(expectedDestinationDatabaseID, "expectedDestinationDatabaseID")
        if sourceDatabaseID == expectedDestinationDatabaseID:
            raise ValueError("Raw export requires distinct source and destination UUIDs.")
        validateID(createdBy, "createdBy")
        validateID(backendID, "backendID")
        validatePath(objectPrefix)

        if type(savedTimezone) is not str or not savedTimezone or savedTimezone != savedTimezone.strip():
            raise ValueError("savedTimezone must be an explicit timezone name.")
        ZoneInfo(savedTimezone)

        if not isinstance(accessContext, pglDatabaseAccess):
            raise TypeError("accessContext must be a pglDatabaseAccess instance.")
        if cls._checkpointDatabaseIdentity(accessContext._postgres) != cls._checkpointDatabaseIdentity(postgres):
            raise ValueError("Borrowed payload access belongs to another configured database.")

        sourceRecord = deepcopy(sourceRecord)
        sourceCreator = deepcopy(sourceCreator)
        manifest = deepcopy(manifest)
        if type(sourceRecord) is not dict:
            raise ValueError("Source record must be a dictionary.")
        validateID(sourceRecord.get("session_id"), "Source session ID")
        if sourceRecord.get("ingest_method") not in ("manual", "automated"):
            raise ValueError("Initial raw export registration requires manual or automated ingest.")

        cls.validateRawManifest(manifest)
        for name in manifest["directories"]: validatePath(name)
        for record in manifest["files"]: validatePath(record["name"])
        if "manifest.json" in {record["name"] for record in manifest["files"]}:
            raise ValueError("manifest.json is reserved for the checkpoint manifest.")

        manifestBytes = cls.encodeRawManifest(manifest)
        if len(manifestBytes) > pglStorage.MAX_METADATA_BYTES:
            raise ValueError("Raw export manifest exceeds the metadata size limit.")
        manifestIdentity = {
            "sha256": hashlib.sha256(manifestBytes).hexdigest(),
            "size_bytes": len(manifestBytes),
        }
        sessions = sql.Identifier(postgres.databaseSchema, "session")
        mappings = sql.Identifier(postgres.databaseSchema, "session_export_mappings")
        backends = sql.Identifier(postgres.databaseSchema, "storage_backends")
        users = sql.Identifier(postgres.databaseSchema, "users")

        with connection.cursor(row_factory=tuple_row) as cursor:
            cursor.execute("SHOW transaction_isolation")
            isolation = cursor.fetchone()[0]
            cursor.execute("SHOW transaction_read_only")
            readOnly = cursor.fetchone()[0]
            if isolation != "read committed" or readOnly != "off":
                raise ValueError("Raw export registration requires READ COMMITTED, READ WRITE.")

            cursor.execute("""
                /* exportRawPublicationLock */
                SELECT EXISTS (
                    SELECT 1 FROM pg_catalog.pg_locks
                    WHERE pid = pg_catalog.pg_backend_pid()
                      AND locktype = 'relation'
                      AND relation = %s::regclass
                      AND granted
                      AND mode IN (
                          'ShareRowExclusiveLock', 'ExclusiveLock', 'AccessExclusiveLock'
                      )
                )
            """, (sessions.as_string(connection),))
            if cursor.fetchone() != (True,):
                raise ValueError("Raw export registration requires the publication lock.")

        if cls._requireStableDatabaseIdentity(connection, postgres) != expectedDestinationDatabaseID:
            raise ValueError("Actual destination UUID differs from expected destination.")

        if progress is not None: progress(0, "Checking prepared raw export and archived labels")
        with connection.transaction():
            with connection.cursor(row_factory=tuple_row) as cursor:
                cursor.execute(sql.SQL("""
                    /* exportRawMappingConflict */
                    SELECT 1 FROM {}
                    WHERE source_database_id = %s::uuid AND source_session_id = %s
                """).format(mappings), (sourceDatabaseID, sourceRecord["session_id"]))
                if cursor.fetchone() is not None:
                    raise ValueError("Source checkpoint already has an export mapping.")

                cursor.execute(sql.SQL("""
                    /* exportRawManifestConflict */
                    SELECT session_id FROM {}
                    WHERE origin = 'raw' AND deleted_at IS NULL AND manifest_hash = %s
                """).format(sessions), (manifestIdentity["sha256"],))
                if cursor.fetchone() is not None:
                    raise ValueError("An active raw checkpoint already has this manifest.")

                cursor.execute(sql.SQL("""
                    /* exportRawActor */
                    SELECT user_id FROM {} WHERE user_id = %s FOR SHARE
                """).format(users), (createdBy,))
                if cursor.fetchone() != (createdBy,):
                    raise ValueError("Destination publication actor is absent.")

                cursor.execute(sql.SQL("""
                    /* exportRawBackend */
                    SELECT url_prefix, is_active FROM {} WHERE backend_id = %s FOR SHARE
                """).format(backends), (backendID,))
                backend = cursor.fetchone()
                if backend is None or backend[1] is not True:
                    raise ValueError("Destination backend is absent or inactive.")

            filesystem, root = accessContext.resolve(backendID, backend[0])
            bundlePath = posixpath.join(root, objectPrefix)

            def requireLocalSafe(path):
                if isinstance(filesystem, LocalFileSystem):
                    localPath = Path(path).absolute()
                    for candidate in (localPath, *localPath.parents):
                        if candidate.is_symlink():
                            raise ValueError(f"Symlinked prepared raw export path: {candidate}")

            requireLocalSafe(bundlePath)
            if not filesystem.isdir(bundlePath):
                raise NotADirectoryError(bundlePath)

            expectedFiles = {
                record["name"]: {
                    "sha256": record["sha256"], "size_bytes": record["size_bytes"],
                }
                for record in manifest["files"]
            }
            expectedFiles["manifest.json"] = manifestIdentity

            def readVerifiedMetadata(name):
                if name not in expectedFiles:
                    raise ValueError(f"Undeclared archived metadata: {name}")
                expected = expectedFiles[name]
                if expected["size_bytes"] > pglStorage.MAX_METADATA_BYTES:
                    raise ValueError(f"Archived metadata exceeds the read limit: {name}")
                path = posixpath.join(bundlePath, name)
                requireLocalSafe(path)
                with filesystem.open(path, "rb") as handle:
                    content = handle.read(expected["size_bytes"] + 1)
                if {
                    "sha256": hashlib.sha256(content).hexdigest(),
                    "size_bytes": len(content),
                } != expected:
                    raise ValueError(f"Prepared archived metadata identity mismatch: {name}")
                return content

            if readVerifiedMetadata("manifest.json") != manifestBytes:
                raise ValueError("Prepared manifest differs from supplied canonical manifest.")

            class VerifiedLabelView:
                """Borrow access and expose bounded verified metadata only."""
                def open(self, name, mode="rt", **kwargs):
                    if mode not in ("r", "rt", "rb"):
                        raise ValueError("Archived label view is read-only.")
                    content = readVerifiedMetadata(name)
                    stream = io.BytesIO(content)
                    if mode == "rb": return stream
                    return io.TextIOWrapper(stream, encoding=kwargs.get("encoding", "utf-8"))

            labels = cls._behaviorLabelMetadata(manifest, VerifiedLabelView())
            projection = cls._prepareExportSessionMetadata(
                sourceRecord, sourceCreator, manifest,
                sourceDatabaseID=sourceDatabaseID, verifiedLabels=labels,
            )
            preserved = projection["preservedFields"]

            sessionID = cls.createRawCheckpoint(
                connection, postgres, createdBy,
                description=preserved["description"],
                ingestMethod=preserved["ingest_method"],
            )
            columns = list(preserved)
            values = [
                Jsonb(preserved[name]) if name == "meta" else preserved[name]
                for name in columns
            ]
            with connection.cursor(row_factory=tuple_row) as cursor:
                cursor.execute(sql.SQL("""
                    /* exportRawPreserveMetadata */
                    UPDATE {} SET {}, saved_timezone = %s
                    WHERE session_id = %s AND status = 'in_progress'
                      AND deleted_at IS NULL
                    RETURNING session_id
                """).format(
                    sessions,
                    sql.SQL(", ").join(
                        sql.SQL("{} = %s").format(sql.Identifier(name)) for name in columns
                    ),
                ), (*values, savedTimezone, sessionID))
                if cursor.fetchone() != (sessionID,):
                    raise ValueError("Raw export metadata projection failed.")

            staged = [
                {**record, "object_key": posixpath.join(objectPrefix, record["name"])}
                for record in manifest["files"]
            ]
            storedManifest = {
                **manifestIdentity,
                "object_key": posixpath.join(objectPrefix, "manifest.json"),
            }
            registeredID = cls.registerStagedRawCheckpoint(
                connection, postgres, createdBy, backendID,
                manifest, staged, storedManifest,
                sessionID=sessionID, accessContext=accessContext,
                **({"progress": progress.section(0.10, 0.90, label="Registering raw files")} if progress is not None else {}),
            )
            if registeredID != sessionID:
                raise ValueError("Raw registration returned a different checkpoint ID.")
            if progress is not None: progress(0.90, "Checking raw products and completing checkpoint")
            cls._verifySessionProducts(connection, postgres, sessionID, [])
            completedHash = cls.completeRawCheckpoint(connection, postgres, sessionID, manifest)
            if completedHash != manifestIdentity["sha256"]:
                raise ValueError("Raw completion returned a different manifest identity.")

            with connection.cursor(row_factory=tuple_row) as cursor:
                cursor.execute(sql.SQL("""
                    /* exportRawCompletedMetadata */
                    SELECT to_jsonb(checkpoint) FROM {} AS checkpoint WHERE session_id = %s
                """).format(sessions), (sessionID,))
                row = cursor.fetchone()
            if row is None:
                raise ValueError("Completed raw export metadata is absent.")
            actual = row[0]
            if (
                type(actual) is not dict
                or set(actual) != set(sourceRecord)
                or actual["session_id"] != sessionID
                or actual["parent_session_id"] is not None
                or actual["root_session_id"] != sessionID
                or actual["origin"] != "raw" or actual["kind"] != "acquired"
                or actual["status"] != "complete" or actual["deleted_at"] is not None
                or actual["manifest_hash"] != completedHash
                or actual["contract_version"] != manifest["contract_version"]
                or actual["created_by"] != createdBy
                or actual["saved_timezone"] != savedTimezone
                or actual["completed_at"] is None
            ):
                raise ValueError("Completed raw export catalog binding is inconsistent.")

            for field, expected in preserved.items():
                observed = actual[field]
                # PostgreSQL may render timestamptz with another display offset.
                if field == "acquired_at" and expected is not None and observed is not None:
                    if datetime.fromisoformat(observed) != datetime.fromisoformat(expected):
                        raise ValueError("Preserved raw acquired_at differs.")
                elif pglStorage.encodeJSON(observed) != pglStorage.encodeJSON(expected):
                    raise ValueError(f"Preserved raw metadata differs: {field}")

        if progress is not None: progress(1, 'Raw checkpoint registered; outer transaction uncommitted')
        return {
            "destinationDatabaseID": expectedDestinationDatabaseID,
            "destinationSessionID": sessionID,
            "manifestHash": completedHash,
            "destinationMetadata": deepcopy(actual),
            "sourceMetadataProjection": projection,
            "outerCommitConfirmed": False,
            "mappingInserted": False,
            "foreignResolutionAuthorized": False,
        }
        
    @classmethod
    def _verifyExportDerivedParent(
        cls, connection, postgres, parentEvidence, *,
        sourceDatabaseID, sourceRecord, expectedDestinationDatabaseID,
        storageOptionsByBackend=None,
        progress=None,
    ):
        """Bind an intended derived export to its verified destination parent.

        Initial child scope:
            pgl.derived.behavior.v3.

        sourceRecord:
            Source child's catalog metadata, obtained by the coordinator from
            its checked source snapshot. Only child identity/lineage/state and
            contract are checked here. Full metadata/manifest correspondence
            remains the derived registrar's responsibility.

        parentEvidence:
            Valid byte-preserving evidence selecting the source child's direct
            parent and its corresponding destination checkpoint.
            May describe a broader recorded export chain than the parent alone.

        Checks source/destination UUID qualification and direct-parent/root
        correspondence before destination I/O. Then invokes the existing
        destination verifier for actual catalog and fresh payload checks.

        Supports a destination parent completed earlier in the caller's current
        publication transaction. Does not require its mapping row to have been
        inserted yet. Transaction/lock requirements are enforced by the
        destination verifier.

        Returns:
            destinationParentSessionID / destinationRootSessionID.
            Source parent/root IDs and both qualified database identities.
            The fresh parent payload-verification result.

        This does not authorize parent reuse or merging separate exports.
        The enclosing coordinator must decide whether this is a newly published
        parent or an explicitly permitted existing parent.

        Caller must authenticate the source observations and construct truthful
        parent evidence. Destination agreement cannot authenticate a fabricated
        source parent claim.

        No child allocation, SQL writes, mapping registration, commit, copying,
        cleanup, history rewriting, or foreign-resolution authorization.
        Does not mutate supplied records.
        Optional progress is a pglProgress-compatible call/section reporter.
        Reports only this helper's verification/registration work; never
        finishes the enclosing export. Work ranges are not time estimates.
        Public callers supply a display-failure-isolated reporter; direct
        callback errors propagate. No success update precedes read-back
        validation or successful exit from this helper's savepoint.

        """
        from copy import deepcopy
        from uuid import UUID

        def validateUUID(value, label):
            if type(value) is not str:
                raise ValueError(f"Invalid {label}.")
            try:
                parsed = UUID(value)
            except ValueError as error:
                raise ValueError(f"Invalid {label}.") from error
            if str(parsed) != value or not parsed.int:
                raise ValueError(f"{label} must be canonical and nonzero.")

        def validateID(value, label):
            if type(value) is not int or not 0 <= value <= 9223372036854775807:
                raise ValueError(f"{label} must be a nonnegative PostgreSQL bigint.")

        validateUUID(sourceDatabaseID, "sourceDatabaseID")
        validateUUID(expectedDestinationDatabaseID, "expectedDestinationDatabaseID")
        if sourceDatabaseID == expectedDestinationDatabaseID:
            raise ValueError("Derived export requires distinct database UUIDs.")

        if type(sourceRecord) is not dict:
            raise TypeError("Source child metadata must be a dictionary.")
        sourceRecord = deepcopy(sourceRecord)
        requiredFields = {
            "session_id", "parent_session_id", "root_session_id",
            "origin", "kind", "status", "deleted_at", "contract_version",
        }
        if not requiredFields.issubset(sourceRecord):
            raise ValueError("Source child metadata lacks required lineage fields.")

        for field in ("session_id", "parent_session_id", "root_session_id"):
            validateID(sourceRecord[field], field)
        childID = sourceRecord["session_id"]
        parentID = sourceRecord["parent_session_id"]
        rootID = sourceRecord["root_session_id"]
        if childID in (parentID, rootID):
            raise ValueError("Source child cannot be its own parent or root.")
        if (
            sourceRecord["origin"] != "derived"
            or sourceRecord["kind"] != "processed"
            or sourceRecord["status"] != "complete"
            or sourceRecord["deleted_at"] is not None
            or sourceRecord["contract_version"] != "pgl.derived.behavior.v3"
        ):
            raise ValueError("Expected an active completed derived behavioral-v3 source child.")

        checked = cls._validateExportMappingEvidence(parentEvidence)
        if (
            checked["source"]["databaseID"] != sourceDatabaseID
            or checked["destination"]["databaseID"] != expectedDestinationDatabaseID
        ):
            raise ValueError("Parent evidence database qualification differs from the export.")
        if checked["source"]["sessionID"] != parentID:
            raise ValueError("Parent evidence does not select the source child's direct parent.")

        chain = checked["lineage"]["checkpoints"]
        selectedParent = next(
            record for record in chain if record["sourceSessionID"] == parentID
        )
        if selectedParent["sourceRootSessionID"] != rootID:
            raise ValueError("Source child root differs from the recorded parent root.")

        # Evidence may include the child already, as happens when inspecting an
        # existing full-chain export. If present, it must corroborate this edge.
        recordedChildren = [
            record for record in chain if record["sourceSessionID"] == childID
        ]
        if recordedChildren:
            recordedChild = recordedChildren[0]
            if (
                recordedChild["sourceParentSessionID"] != parentID
                or recordedChild["sourceRootSessionID"] != rootID
                or recordedChild["origin"] != sourceRecord["origin"]
                or recordedChild["kind"] != sourceRecord["kind"]
                or recordedChild["contractVersion"] != sourceRecord["contract_version"]
            ):
                raise ValueError("Source child contradicts the parent evidence's recorded lineage.")

        destinationParentID = checked["destination"]["sessionID"]
        destinationRootID = selectedParent["destinationRootSessionID"]

        if progress is not None: progress(0, "Checking exported parent catalog and bytes")
        verification = cls._verifyExportDestinationPayloads(
            connection, postgres, checked,
            storageOptionsByBackend=storageOptionsByBackend,
            **({"progress": progress.section(0.05, 0.95, label="Verifying exported parent")} if progress is not None else {}),
        )
        if (
            verification["destinationDatabaseID"] != expectedDestinationDatabaseID
            or verification["destinationSessionID"] != destinationParentID
            or verification["payloadBytesVerified"] is not True
            or verification["strictMatrixCoverageChecked"] is not True
        ):
            raise ValueError("Destination parent verification returned inconsistent results.")

        if progress is not None: progress(1, 'Derived parent correspondence and destination bytes verified')
        return {
            "sourceDatabaseID": sourceDatabaseID,
            "sourceParentSessionID": parentID,
            "sourceRootSessionID": rootID,
            "destinationDatabaseID": expectedDestinationDatabaseID,
            "destinationParentSessionID": destinationParentID,
            "destinationRootSessionID": destinationRootID,
            "parentPayloadVerification": verification,
            "parentReuseAuthorized": False,
            "foreignResolutionAuthorized": False,
        }
        
    @classmethod
    def _registerExportDerivedCheckpoint(
        cls, connection, postgres, *,
        sourceDatabaseID, sourceRecord, sourceCreator, manifest,
        sourceMatrixInventory, parentEvidence,
        expectedDestinationDatabaseID, createdBy, backendID, objectPrefix,
        savedTimezone, accessContext, parentStorageOptionsByBackend=None,
        progress=None,
    ):
        """Register a prepared byte-preserving derived behavioral-v3 checkpoint.

        Caller must:
            Supply authentic source catalog/manifest/matrix observations.
            Own a READ COMMITTED, READ WRITE transaction and publication lock.
            Supply truthful parent evidence from the checked publication scope.
            Register intended matrix revisions before calling this method.
            Provide all saved checkpoint files under backendID/objectPrefix.
            Decide parent/matrix reuse policy independently.

        Before child allocation:
            Check destination migrations/UUID, mapping conflict, actor/backend.
            Verify direct-parent/root correspondence and parent destination bytes.
            Verify bounded manifest/history/label bytes and metadata projection.
            Check supported history references within parent evidence scope plus
            this child; this is scope coverage, not proof every mapping exists.
            Compare actual matrix catalogs and freshly verified bundles against
            the supplied source matrix inventory.

        Registration/completion uses existing helpers inside a savepoint.
        Failures roll back this method's SQL; caller work remains outside it.
        Sequence values may remain consumed.

        Tuple-row conventions are required by delegated registration helpers.
        accessContext is borrowed for child and matrix payload access.
        Parent verification owns its bounded access separately; caller runtime
        options for that access are supplied as parentStorageOptionsByBackend.

        Exact physical directory enumeration remains a transfer/preparation
        responsibility. Concurrent payload mutation is unsupported.

        Returns destination metadata, source projection, parent/history/matrix
        verification observations. Does not commit, copy/delete files, allocate
        matrix UUIDs, insert mappings, authorize reuse/foreign loading, or persist
        source provenance. No scientific arrays are opened or decoded.
        Optional progress is a pglProgress-compatible call/section reporter.
        File/bundle verification uses captured byte weights where known;
        metadata and registration phases use explicit work allocations,
        not elapsed-time estimates. This helper never calls finish().
        Success means this helper returned, not that SQL was committed.
        Public calls supply a display-failure-isolated progress adapter.

        """
        from copy import deepcopy
        from datetime import datetime
        from pathlib import Path
        from uuid import UUID
        from zoneinfo import ZoneInfo
        import io
        import posixpath

        from fsspec.implementations.local import LocalFileSystem
        from psycopg.pq import TransactionStatus
        from psycopg.rows import tuple_row
        from psycopg.types.json import Jsonb

        if connection.info.transaction_status != TransactionStatus.INTRANS:
            raise ValueError("Derived export requires an active caller-owned transaction.")

        def validateID(value, label):
            if type(value) is not int or not 0 <= value <= 9223372036854775807:
                raise ValueError(f"Invalid {label}.")

        def validateUUID(value):
            if type(value) is not str:
                raise ValueError("Export database UUID must be a string.")
            try:
                parsed = UUID(value)
            except ValueError as error:
                raise ValueError("Invalid export database UUID.") from error
            if str(parsed) != value or not parsed.int:
                raise ValueError("Export database UUID must be canonical and nonzero.")

        def validatePath(value):
            if (
                type(value) is not str or not value or value.startswith("/")
                or "\\" in value
                or any(character in value for character in ("\x00", "\n", "\r"))
                or any(part in ("", ".", "..") for part in value.split("/"))
            ):
                raise ValueError("Invalid derived export relative path.")

        def requireEqual(actual, expected, label):
            if pglStorage.encodeJSON(actual) != pglStorage.encodeJSON(expected):
                raise ValueError(f"Derived export {label} differs.")

        validateUUID(sourceDatabaseID)
        validateUUID(expectedDestinationDatabaseID)
        if sourceDatabaseID == expectedDestinationDatabaseID:
            raise ValueError("Derived export requires distinct database UUIDs.")
        validateID(createdBy, "publication actor")
        validateID(backendID, "destination backend")
        validatePath(objectPrefix)
        if type(savedTimezone) is not str or not savedTimezone or savedTimezone != savedTimezone.strip():
            raise ValueError("An explicit publication timezone is required.")
        ZoneInfo(savedTimezone)

        if not isinstance(accessContext, pglDatabaseAccess):
            raise TypeError("accessContext must be a pglDatabaseAccess instance.")
        if cls._checkpointDatabaseIdentity(accessContext._postgres) != cls._checkpointDatabaseIdentity(postgres):
            raise ValueError("Borrowed access belongs to another configured database.")

        sourceRecord = deepcopy(sourceRecord)
        sourceCreator = deepcopy(sourceCreator)
        manifest = deepcopy(manifest)
        sourceMatrixInventory = deepcopy(sourceMatrixInventory)
        parentEvidence = cls._validateExportMappingEvidence(parentEvidence)

        if type(sourceRecord) is not dict:
            raise ValueError("Source child metadata must be a dictionary.")
        validateID(sourceRecord.get("session_id"), "source child ID")
        if sourceRecord.get("ingest_method") not in ("manual", "automated"):
            raise ValueError("Initial derived export requires manual or automated ingest.")
        if type(manifest) is not dict or manifest.get("contract_version") != "pgl.derived.behavior.v3":
            raise ValueError("Initial derived registrar supports behavioral-v3 only.")
        cls.validateDerivedManifest(manifest)
        for name in manifest["directories"]: validatePath(name)
        for record in manifest["files"]: validatePath(record["name"])

        manifestIdentity = cls._compareExportManifestIdentity(manifest, manifest)
        manifestBytes = cls.encodeRawManifest(manifest)
        if len(manifestBytes) > pglStorage.MAX_METADATA_BYTES:
            raise ValueError("Derived export manifest exceeds the metadata limit.")

        # Validate supplied captured inventory structure and exact attachment
        # coverage now. This self-comparison does not authenticate source bytes.
        cls._compareExportMatrixInventory(
            sourceMatrixInventory, sourceMatrixInventory,
            sourceManifest=manifest, destinationManifest=manifest,
        )

        sessions = sql.Identifier(postgres.databaseSchema, "session")
        mappings = sql.Identifier(postgres.databaseSchema, "session_export_mappings")
        backends = sql.Identifier(postgres.databaseSchema, "storage_backends")
        users = sql.Identifier(postgres.databaseSchema, "users")
        revisions = sql.Identifier(postgres.databaseSchema, "matrix_revisions")

        with connection.cursor(row_factory=tuple_row) as cursor:
            cursor.execute("SHOW transaction_isolation")
            isolation = cursor.fetchone()[0]
            cursor.execute("SHOW transaction_read_only")
            readOnly = cursor.fetchone()[0]
            if isolation != "read committed" or readOnly != "off":
                raise ValueError("Derived export requires READ COMMITTED, READ WRITE.")
            cursor.execute("""
                /* exportDerivedPublicationLock */
                SELECT EXISTS (
                    SELECT 1 FROM pg_catalog.pg_locks
                    WHERE pid = pg_catalog.pg_backend_pid()
                      AND locktype = 'relation' AND relation = %s::regclass
                      AND granted
                      AND mode IN (
                          'ShareRowExclusiveLock', 'ExclusiveLock', 'AccessExclusiveLock'
                      )
                )
            """, (sessions.as_string(connection),))
            if cursor.fetchone() != (True,):
                raise ValueError("Derived export requires the publication lock.")

        if cls._requireStableDatabaseIdentity(connection, postgres) != expectedDestinationDatabaseID:
            raise ValueError("Actual destination UUID differs from expected destination.")

        if progress is not None: progress(0, "Checking derived export conflicts and parent")
        with connection.transaction():
            with connection.cursor(row_factory=tuple_row) as cursor:
                cursor.execute(sql.SQL("""
                    /* exportDerivedMappingConflict */
                    SELECT 1 FROM {}
                    WHERE source_database_id = %s::uuid AND source_session_id = %s
                """).format(mappings), (sourceDatabaseID, sourceRecord["session_id"]))
                if cursor.fetchone() is not None:
                    raise ValueError("Source child already has an export mapping.")
                cursor.execute(sql.SQL("""
                    /* exportDerivedActor */
                    SELECT user_id FROM {} WHERE user_id = %s FOR SHARE
                """).format(users), (createdBy,))
                if cursor.fetchone() != (createdBy,):
                    raise ValueError("Destination publication actor is absent.")
                cursor.execute(sql.SQL("""
                    /* exportDerivedBackend */
                    SELECT url_prefix, is_active FROM {} WHERE backend_id = %s FOR SHARE
                """).format(backends), (backendID,))
                backend = cursor.fetchone()
                if backend is None or backend[1] is not True:
                    raise ValueError("Destination backend is absent or inactive.")

            parent = cls._verifyExportDerivedParent(
                connection, postgres, parentEvidence,
                sourceDatabaseID=sourceDatabaseID,
                sourceRecord=sourceRecord,
                expectedDestinationDatabaseID=expectedDestinationDatabaseID,
                storageOptionsByBackend=parentStorageOptionsByBackend,
                **({"progress": progress.section(0, 0.20, label="Checking parent")} if progress is not None else {}),
            )

            if progress is not None:
                progress(0.20, "Verifying prepared derived history and archived labels")
            filesystem, root = accessContext.resolve(backendID, backend[0])
            bundlePath = posixpath.join(root, objectPrefix)

            def requireLocalSafe(filesystem, path):
                if isinstance(filesystem, LocalFileSystem):
                    localPath = Path(path).absolute()
                    for candidate in (localPath, *localPath.parents):
                        if candidate.is_symlink():
                            raise ValueError(f"Symlinked derived export path: {candidate}")

            requireLocalSafe(filesystem, bundlePath)
            if not filesystem.isdir(bundlePath): raise NotADirectoryError(bundlePath)

            expectedFiles = {
                record["name"]: {
                    "sha256": record["sha256"], "size_bytes": record["size_bytes"],
                }
                for record in manifest["files"]
            }
            if "manifest.json" in expectedFiles:
                raise ValueError("manifest.json is reserved.")
            expectedFiles["manifest.json"] = {
                "sha256": manifestIdentity["sha256"],
                "size_bytes": manifestIdentity["size_bytes"],
            }

            def readMetadata(name):
                import hashlib
                if name not in expectedFiles:
                    raise ValueError(f"Undeclared prepared metadata: {name}")
                expected = expectedFiles[name]
                if expected["size_bytes"] > pglStorage.MAX_METADATA_BYTES:
                    raise ValueError("Prepared metadata exceeds the read limit.")
                path = posixpath.join(bundlePath, name)
                requireLocalSafe(filesystem, path)
                with filesystem.open(path, "rb") as handle:
                    content = handle.read(expected["size_bytes"] + 1)
                if {
                    "sha256": hashlib.sha256(content).hexdigest(),
                    "size_bytes": len(content),
                } != expected:
                    raise ValueError(f"Prepared derived metadata identity mismatch: {name}")
                return content

            if readMetadata("manifest.json") != manifestBytes:
                raise ValueError("Prepared derived manifest is not the expected canonical bytes.")

            class VerifiedMetadataView:
                def open(self, name, mode="rt", **kwargs):
                    if mode not in ("r", "rt", "rb"):
                        raise ValueError("Prepared metadata view is read-only.")
                    stream = io.BytesIO(readMetadata(name))
                    if mode == "rb": return stream
                    return io.TextIOWrapper(stream, encoding=kwargs.get("encoding", "utf-8"))

            view = VerifiedMetadataView()
            labels = cls._behaviorLabelMetadata(manifest, view)
            history, historyLabels = cls._readSessionHistory(view, len(manifest["runs"]))
            requireEqual(historyLabels, labels, "history/archived labels")

            scope = [
                item["sourceSessionID"] for item in parentEvidence["lineage"]["checkpoints"]
            ]
            if sourceRecord["session_id"] not in scope:
                scope.append(sourceRecord["session_id"])
            historyReferences = cls._inspectExportHistoryReferences(
                history, sourceDatabaseID=sourceDatabaseID, sourceSessionIDs=scope,
            )
            projection = cls._prepareExportSessionMetadata(
                sourceRecord, sourceCreator, manifest,
                sourceDatabaseID=sourceDatabaseID, verifiedLabels=labels,
            )

            expectedRevisions = {
                item["matrixRevisionID"]: item
                for item in sourceMatrixInventory["revisions"]
            }
            actualRevisions = []
            matrixWork = [
                {
                    "name": revisionID,
                    "size_bytes": expectedRevisions[revisionID]["bundleInventory"]["bundleBytes"],
                }
                for revisionID in sorted(expectedRevisions)
            ]
            matrixRange = progress.section(0.25, 0.55) if progress is not None else None
            for matrixItem, matrixProgress in pglProgress.fileSections(matrixWork, matrixRange):
                revisionID = matrixItem["name"]
                expected = expectedRevisions[revisionID]
                with connection.cursor(row_factory=tuple_row) as cursor:
                    cursor.execute(sql.SQL("""
                        /* exportDerivedMatrix */
                        SELECT revision.contract_version, revision.descriptor,
                               revision.backend_id, revision.object_key,
                               backend.url_prefix, backend.is_active
                        FROM {} AS revision
                        JOIN {} AS backend ON backend.backend_id = revision.backend_id
                        WHERE revision.matrix_revision_id = %s::uuid
                        -- Revision rows are immutable; the application role
                        -- intentionally has SELECT/INSERT only on them.
                        -- Lock the mutable backend to protect active status.
                        FOR SHARE OF backend
                    """).format(revisions, backends), (revisionID,))
                    row = cursor.fetchone()
                if row is None or row[5] is not True:
                    raise ValueError("Expected registered matrix is absent or inactive.")
                contract, descriptor, matrixBackendID, key, registeredRoot, _ = row
                validateID(matrixBackendID, "matrix backend ID")
                validatePath(key)
                if (
                    type(registeredRoot) is not str or not registeredRoot.strip()
                    or any(character in registeredRoot for character in ("\x00", "\n", "\r"))
                ):
                    raise ValueError("Invalid registered matrix root.")
                requireEqual(contract, expected["contractVersion"], "matrix contract")
                requireEqual(descriptor, expected["descriptor"], "matrix descriptor")
                matrixFS, matrixRoot = accessContext.resolve(matrixBackendID, registeredRoot)
                matrixPath = posixpath.join(matrixRoot, key)
                requireLocalSafe(matrixFS, matrixPath)
                inventory = pglStorage.inventoryDataMatrixBundleLayout(
                    matrixPath, filesystem=matrixFS,
                    expectedDescriptor=expected["descriptor"],
                    expectedFiles=expected["bundleInventory"]["files"],
                    requireAllChunks=True,
                    **({"progress": matrixProgress} if matrixProgress is not None else {}),
                )
                actualRevisions.append({
                    "matrixRevisionID": revisionID,
                    "contractVersion": contract,
                    "descriptor": descriptor,
                    "bundleInventory": inventory,
                })

            actualMatrixInventory = {
                "attachments": [
                    {
                        "catalogName": item["name"], "owner": "session",
                        "localName": item["name"],
                        "matrixRevisionID": item["matrixRevisionID"],
                    }
                    for item in manifest["products"]
                ],
                "revisions": actualRevisions,
                "bundleBytes": sum(
                    item["bundleInventory"]["bundleBytes"] for item in actualRevisions
                ),
            }
            matrixComparison = cls._compareExportMatrixInventory(
                sourceMatrixInventory, actualMatrixInventory,
                sourceManifest=manifest, destinationManifest=manifest,
            )

            if progress is not None:
                progress(0.55, "Allocating derived checkpoint and preserving metadata")
            preserved = projection["preservedFields"]
            sessionID = cls.createDerivedCheckpoint(
                connection, postgres, createdBy, parent["destinationParentSessionID"],
                description=preserved["description"],
                ingestMethod=preserved["ingest_method"],
                checkpointName=preserved["checkpoint_name"],
                contractVersion=manifest["contract_version"],
                modalities=preserved["modalities"],
            )
            columns = list(preserved)
            values = [
                Jsonb(preserved[name]) if name == "meta" else preserved[name]
                for name in columns
            ]
            with connection.cursor(row_factory=tuple_row) as cursor:
                cursor.execute(sql.SQL("""
                    /* exportDerivedPreserveMetadata */
                    UPDATE {} SET {}, saved_timezone = %s
                    WHERE session_id = %s AND status = 'in_progress' AND deleted_at IS NULL
                    RETURNING session_id
                """).format(
                    sessions,
                    sql.SQL(", ").join(
                        sql.SQL("{} = %s").format(sql.Identifier(name)) for name in columns
                    ),
                ), (*values, savedTimezone, sessionID))
                if cursor.fetchone() != (sessionID,):
                    raise ValueError("Derived metadata projection failed.")

            registeredID = cls._registerSessionBundleFiles(
                connection, postgres, sessionID, backendID, manifest,
                objectPrefix=objectPrefix, origin="derived", accessContext=accessContext,
                **({"progress": progress.section(0.55, 0.90, label="Registering derived files")} if progress is not None else {}),
            )
            if registeredID != sessionID:
                raise ValueError("Derived file registration returned another checkpoint ID.")
            if progress is not None:
                progress(0.90, "Registering matrix attachments and completing derived checkpoint")
            cls._registerSessionProducts(connection, postgres, sessionID, manifest["products"])
            completedHash = cls._completeSessionBundleCheckpoint(
                connection, postgres, sessionID, manifest, origin="derived",
            )
            if completedHash != manifestIdentity["sha256"]:
                raise ValueError("Derived completion returned a different manifest hash.")

            with connection.cursor(row_factory=tuple_row) as cursor:
                cursor.execute(sql.SQL("""
                    /* exportDerivedCompletedMetadata */
                    SELECT to_jsonb(checkpoint) FROM {} AS checkpoint WHERE session_id = %s
                """).format(sessions), (sessionID,))
                row = cursor.fetchone()
            if row is None or type(row[0]) is not dict:
                raise ValueError("Completed derived checkpoint metadata is absent.")
            actual = row[0]
            if set(actual) != set(sourceRecord):
                raise ValueError("Completed derived metadata columns differ from supported schema.")
            expectedBindings = {
                "session_id": sessionID,
                "parent_session_id": parent["destinationParentSessionID"],
                "root_session_id": parent["destinationRootSessionID"],
                "origin": "derived", "kind": "processed",
                "status": "complete", "deleted_at": None,
                "manifest_hash": completedHash,
                "contract_version": manifest["contract_version"],
                "created_by": createdBy, "saved_timezone": savedTimezone,
            }
            for field, value in expectedBindings.items():
                requireEqual(actual[field], value, f"completed {field}")
            if actual["completed_at"] is None:
                raise ValueError("Derived completion timestamp is absent.")
            for field, expected in preserved.items():
                observed = actual[field]
                if field == "acquired_at" and expected is not None and observed is not None:
                    if datetime.fromisoformat(observed) != datetime.fromisoformat(expected):
                        raise ValueError("Preserved derived acquired_at differs.")
                else:
                    requireEqual(observed, expected, f"preserved {field}")

        if progress is not None:
            progress(1, "Derived checkpoint registered; outer transaction uncommitted")
        return {
            "destinationDatabaseID": expectedDestinationDatabaseID,
            "destinationSessionID": sessionID,
            "manifestHash": completedHash,
            "destinationMetadata": deepcopy(actual),
            "sourceMetadataProjection": projection,
            "parentVerification": parent,
            "historyReferences": historyReferences,
            "matrixComparison": matrixComparison,
            "outerCommitConfirmed": False,
            "mappingInserted": False,
            "foreignResolutionAuthorized": False,
        }

    @classmethod
    def _registerExportMatrixRevision(
        cls, connection, postgres, *,
        sourceDatabaseID, expectedDescriptor, expectedFiles,
        expectedDestinationDatabaseID, createdBy, backendID, objectKey,
        accessContext,
        progress=None,
    ):
        """Verify and register one prepared byte-preserving matrix revision.

        Caller must:
            Obtain authentic source descriptor and captured file identities.
            Copy the unchanged bundle to the explicit destination objectKey.
            Own a READ COMMITTED, READ WRITE transaction and publication lock.
            Decide whether publication is permitted by the enclosing plan.

        Requires distinct source/destination schema UUIDs. Checks destination
        migration compatibility and actual UUID before registration.

        Rejects any existing revision UUID or registered backend/objectKey.
        No overwrite, relocation, automatic reuse, or ON CONFLICT fallback.

        Verifies the destination descriptor, exact stored-file identities, and
        strict grid-chunk coverage before insertion. Does not allocate a new
        revision UUID or rewrite provenance.

        Locks the mutable backend row through the transaction. Immutable
        matrix_revisions rows are not row-locked: the application intentionally
        has SELECT/INSERT privileges only on that table.

        Uses a savepoint. Failures roll back this method's SQL insertion;
        outer-transaction work and prepared payload files are retained.

        Returns the actual registered revision fields and verified bundle
        inventory. Successful return does not imply an outer commit.

        Supplied source identity/bytes are caller observations, not independently
        authenticated here. No publication-time source integrity, scientific
        decoding, or value equivalence is established.

        No copying, product-link creation, mapping insertion, commit, deletion,
        retry/reuse authorization, or closing of borrowed payload access.
        Concurrent payload mutation is unsupported.
        Optional progress is a pglProgress-compatible call/section reporter.
        Reports only this helper's verification/registration work; never
        finishes the enclosing export. Work ranges are not time estimates.
        Public callers supply a display-failure-isolated reporter; direct
        callback errors propagate. No success update precedes read-back
        validation or successful exit from this helper's savepoint.

        """
        from copy import deepcopy
        from pathlib import Path
        from uuid import UUID
        import posixpath

        from fsspec.implementations.local import LocalFileSystem
        from psycopg.pq import TransactionStatus
        from psycopg.rows import tuple_row
        from psycopg.types.json import Jsonb

        if connection.info.transaction_status != TransactionStatus.INTRANS:
            raise ValueError("Matrix export registration requires an active caller-owned transaction.")

        def validateUUID(value, label):
            if type(value) is not str:
                raise ValueError(f"Invalid {label}.")
            try:
                parsed = UUID(value)
            except ValueError as error:
                raise ValueError(f"Invalid {label}.") from error
            if str(parsed) != value or not parsed.int:
                raise ValueError(f"{label} must be canonical and nonzero.")

        def validateID(value, label):
            if type(value) is not int or not 0 <= value <= 9223372036854775807:
                raise ValueError(f"{label} must be a nonnegative PostgreSQL bigint.")

        validateUUID(sourceDatabaseID, "sourceDatabaseID")
        validateUUID(expectedDestinationDatabaseID, "expectedDestinationDatabaseID")
        if sourceDatabaseID == expectedDestinationDatabaseID:
            raise ValueError("Matrix export requires distinct database UUIDs.")
        validateID(createdBy, "createdBy")
        validateID(backendID, "backendID")

        if (
            type(objectKey) is not str or not objectKey or objectKey.startswith("/")
            or "\\" in objectKey
            or any(character in objectKey for character in ("\x00", "\n", "\r"))
            or any(part in ("", ".", "..") for part in objectKey.split("/"))
        ):
            raise ValueError("Invalid destination matrix object key.")

        if not isinstance(accessContext, pglDatabaseAccess):
            raise TypeError("accessContext must be a pglDatabaseAccess instance.")
        if cls._checkpointDatabaseIdentity(accessContext._postgres) != cls._checkpointDatabaseIdentity(postgres):
            raise ValueError("Borrowed matrix access belongs to another configured database.")

        expectedDescriptor = deepcopy(expectedDescriptor)
        expectedFiles = deepcopy(expectedFiles)
        pglStorage._validateMatrixDescriptor(expectedDescriptor)
        pglStorage.encodeJSON(expectedDescriptor)
        if type(expectedFiles) is not list:
            raise TypeError("expectedFiles must be a captured file-inventory list.")

        revisionID = expectedDescriptor["matrixRevisionID"]
        contract = expectedDescriptor["contractVersion"]
        sessions = sql.Identifier(postgres.databaseSchema, "session")
        revisions = sql.Identifier(postgres.databaseSchema, "matrix_revisions")
        backends = sql.Identifier(postgres.databaseSchema, "storage_backends")
        users = sql.Identifier(postgres.databaseSchema, "users")

        with connection.cursor(row_factory=tuple_row) as cursor:
            cursor.execute("SHOW transaction_isolation")
            isolation = cursor.fetchone()[0]
            cursor.execute("SHOW transaction_read_only")
            readOnly = cursor.fetchone()[0]
            if isolation != "read committed" or readOnly != "off":
                raise ValueError("Matrix export registration requires READ COMMITTED, READ WRITE.")

            cursor.execute("""
                /* exportMatrixPublicationLock */
                SELECT EXISTS (
                    SELECT 1 FROM pg_catalog.pg_locks
                    WHERE pid = pg_catalog.pg_backend_pid()
                      AND locktype = 'relation' AND relation = %s::regclass
                      AND granted
                      AND mode IN (
                          'ShareRowExclusiveLock', 'ExclusiveLock', 'AccessExclusiveLock'
                      )
                )
            """, (sessions.as_string(connection),))
            if cursor.fetchone() != (True,):
                raise ValueError("Matrix export registration requires the publication lock.")

        if cls._requireStableDatabaseIdentity(connection, postgres) != expectedDestinationDatabaseID:
            raise ValueError("Actual destination UUID differs from expected destination.")

        if progress is not None: progress(0, "Checking matrix registration conflicts and backend")
        with connection.transaction():
            with connection.cursor(row_factory=tuple_row) as cursor:
                cursor.execute(sql.SQL("""
                    /* exportMatrixConflict */
                    SELECT matrix_revision_id::text, backend_id, object_key
                    FROM {}
                    WHERE matrix_revision_id = %s::uuid
                       OR (backend_id = %s AND object_key = %s)
                """).format(revisions), (revisionID, backendID, objectKey))
                if cursor.fetchone() is not None:
                    raise ValueError("Destination matrix revision UUID or registered path already exists.")

                cursor.execute(sql.SQL("""
                    /* exportMatrixActor */
                    SELECT user_id FROM {} WHERE user_id = %s FOR SHARE
                """).format(users), (createdBy,))
                if cursor.fetchone() != (createdBy,):
                    raise ValueError("Destination matrix publication actor is absent.")

                cursor.execute(sql.SQL("""
                    /* exportMatrixBackend */
                    SELECT url_prefix, is_active FROM {} WHERE backend_id = %s FOR SHARE
                """).format(backends), (backendID,))
                backend = cursor.fetchone()
                if backend is None or backend[1] is not True:
                    raise ValueError("Destination matrix backend is absent or inactive.")

            registeredRoot = backend[0]
            if (
                type(registeredRoot) is not str or not registeredRoot.strip()
                or any(character in registeredRoot for character in ("\x00", "\n", "\r"))
            ):
                raise ValueError("Invalid destination matrix registered root.")

            filesystem, root = accessContext.resolve(backendID, registeredRoot)
            bundlePath = posixpath.join(root, objectKey)
            if isinstance(filesystem, LocalFileSystem):
                localPath = Path(bundlePath).absolute()
                for candidate in (localPath, *localPath.parents):
                    if candidate.is_symlink():
                        raise ValueError(f"Symlinked destination matrix path: {candidate}")

            # The inventory helper validates expectedFiles completely, hashes
            # actual bytes, and checks layout. No scientific arrays are opened.
            inventory = pglStorage.inventoryDataMatrixBundleLayout(
                bundlePath,
                filesystem=filesystem,
                expectedDescriptor=expectedDescriptor,
                expectedFiles=expectedFiles,
                requireAllChunks=True,
                **({"progress": progress.section(0.05, 0.90, label="Verifying matrix bundle")} if progress is not None else {}),
            )

            if progress is not None: progress(0.90, "Registering verified matrix revision and checking read-back")
            with connection.cursor(row_factory=tuple_row) as cursor:
                cursor.execute(sql.SQL("""
                    /* exportMatrixInsert */
                    INSERT INTO {} (
                        matrix_revision_id, backend_id, object_key,
                        contract_version, descriptor, created_by
                    )
                    VALUES (%s::uuid, %s, %s, %s, %s, %s)
                """).format(revisions), (
                    revisionID, backendID, objectKey, contract,
                    Jsonb(expectedDescriptor), createdBy,
                ))

                # A catalog read-back is separate from the preceding byte check.
                # No revision row lock or extra UPDATE privilege is required.
                cursor.execute(sql.SQL("""
                    /* exportMatrixReadback */
                    SELECT matrix_revision_id::text, backend_id, object_key,
                           contract_version, descriptor, created_by
                    FROM {} WHERE matrix_revision_id = %s::uuid
                """).format(revisions), (revisionID,))
                row = cursor.fetchone()

            if row is None:
                raise ValueError("Registered matrix revision is absent on read-back.")
            actual = dict(zip(
                ("matrixRevisionID", "backendID", "objectKey",
                 "contractVersion", "descriptor", "createdBy"),
                row,
            ))
            expected = {
                "matrixRevisionID": revisionID,
                "backendID": backendID,
                "objectKey": objectKey,
                "contractVersion": contract,
                "descriptor": expectedDescriptor,
                "createdBy": createdBy,
            }
            if pglStorage.encodeJSON(actual) != pglStorage.encodeJSON(expected):
                raise ValueError("Registered matrix read-back differs from the supplied revision.")

        if progress is not None: progress(1, 'Matrix revision registered; outer transaction uncommitted')
        return {
            "destinationDatabaseID": expectedDestinationDatabaseID,
            "revision": deepcopy(actual),
            "registeredRoot": registeredRoot,
            "bundleInventory": inventory,
            "outerCommitConfirmed": False,
            "productLinksCreated": False,
            "mappingInserted": False,
            "reuseAuthorized": False,
            "foreignResolutionAuthorized": False,
        }
        
    @classmethod
    def _registerPreparedSessionExport(
        cls, connection, postgres, *,
        sourceDatabaseID, sourceDatabaseName, expectedDestinationDatabaseID,
        preparedCheckpoints, matrixObjectKeys,
        createdBy, backendID, savedTimezone, accessContext,
        storageOptionsByBackend=None,
        progress=None,
    ):
        """Publish a prepared behavioral chain inside a caller transaction.

        preparedCheckpoints:
            Nonempty root-to-selected list of dictionaries containing exactly:
                metadata: Full source session row in JSON-compatible form.
                creator: Source creator description.
                files: _readExportFileInventory() result.
                matrices: _readExportMatrixBundleInventory() result.
                objectPrefix: Prepared destination checkpoint-file directory,
                    relative to backendID's registered root.

            Initial contracts: raw.behavior.v1 followed by derived.behavior.v3.
            Caller must obtain source observations from a checked source
            snapshot and establish source authenticity/transfer scope.

        matrixObjectKeys:
            Exact dictionary of distinct matrix revision UUIDs to prepared
            destination bundle paths, relative to backendID's registered root.
            Shared revisions are registered once; conflicting observations fail.

        Requires:
            Explicit caller-owned READ COMMITTED, READ WRITE transaction.
            Publication lock already held before publication writes.
            Existing destination actor/backend and matching borrowed access.
            Prepared bytes already copied and exact physical inventories
            checked by the transfer layer. No concurrent payload mutation.

        Rechecks conflicts for the entire requested scope before its SQL writes.
        Verifies prepared manifest/labels/history and uses production raw,
        matrix, derived, and mapping registrars. Parent evidence is built for
        the published prefix; final mapping evidence uses the complete chain.

        One outer savepoint covers all SQL performed by this method. Any later
        failure removes the entire attempt, preserving earlier caller work.
        Sequence allocations may remain consumed. Files are never removed.

        Returns actual session mapping, full-chain evidence, and mapping
        registration results. Does not commit or confirm an outer commit.

        No automatic reuse/merging, transfer, backend/user creation, schema
        changes, source SQL access, repair, cleanup, or foreign authorization.
        Runtime storage options are forwarded separately, never serialized.
        The borrowed access context is not closed.
        Optional progress is a pglProgress-compatible call/section reporter.
        File/bundle verification uses captured byte weights where known;
        metadata and registration phases use explicit work allocations,
        not elapsed-time estimates. This helper never calls finish().
        Success means this helper returned, not that SQL was committed.
        Public calls supply a display-failure-isolated progress adapter.

        """
        from copy import deepcopy
        from datetime import datetime
        from pathlib import Path
        from uuid import UUID
        from zoneinfo import ZoneInfo
        import hashlib
        import io
        import posixpath

        from fsspec.implementations.local import LocalFileSystem
        from psycopg.pq import TransactionStatus
        from psycopg.rows import tuple_row

        if connection.info.transaction_status != TransactionStatus.INTRANS:
            raise ValueError("Prepared export requires an active caller-owned transaction.")

        def validateUUID(value):
            if type(value) is not str:
                raise ValueError("Export database UUID must be a string.")
            try:
                parsed = UUID(value)
            except ValueError as error:
                raise ValueError("Invalid export database UUID.") from error
            if str(parsed) != value or not parsed.int:
                raise ValueError("Export database UUID must be canonical and nonzero.")

        def validateID(value):
            if type(value) is not int or not 0 <= value <= 9223372036854775807:
                raise ValueError("Invalid export catalog ID.")

        def validatePath(value):
            if (
                type(value) is not str or not value or value.startswith("/")
                or "\\" in value
                or any(character in value for character in ("\x00", "\n", "\r"))
                or any(part in ("", ".", "..") for part in value.split("/"))
            ):
                raise ValueError("Invalid prepared export path.")

        def requireEqual(actual, expected, label):
            if pglStorage.encodeJSON(actual) != pglStorage.encodeJSON(expected):
                raise ValueError(f"Prepared export {label} differs.")

        validateUUID(sourceDatabaseID)
        validateUUID(expectedDestinationDatabaseID)
        if sourceDatabaseID == expectedDestinationDatabaseID:
            raise ValueError("Prepared export requires distinct database UUIDs.")
        validateID(createdBy)
        validateID(backendID)
        if (
            type(sourceDatabaseName) is not str or not sourceDatabaseName.strip()
            or any(character in sourceDatabaseName for character in ("\x00", "\n", "\r"))
        ):
            raise ValueError("Invalid source database display label.")
        if type(savedTimezone) is not str or not savedTimezone or savedTimezone != savedTimezone.strip():
            raise ValueError("Explicit destination publication timezone required.")
        ZoneInfo(savedTimezone)
        if not isinstance(accessContext, pglDatabaseAccess):
            raise TypeError("accessContext must be a pglDatabaseAccess instance.")
        if cls._checkpointDatabaseIdentity(accessContext._postgres) != cls._checkpointDatabaseIdentity(postgres):
            raise ValueError("Borrowed export access belongs to another configuration.")
        if type(preparedCheckpoints) is not list or not preparedCheckpoints:
            raise ValueError("Prepared export requires a nonempty checkpoint list.")
        if type(matrixObjectKeys) is not dict:
            raise TypeError("matrixObjectKeys must be a dictionary.")

        prepared = deepcopy(preparedCheckpoints)
        matrixObjectKeys = deepcopy(matrixObjectKeys)
        sourceAncestry = []
        sourceIDs = []
        expectedRevisions = {}
        prefixes = []

        def ancestryRecord(metadata):
            fields = (
                ("session_id", "sessionID"),
                ("parent_session_id", "parentSessionID"),
                ("root_session_id", "rootSessionID"),
                ("origin", "origin"), ("kind", "kind"), ("status", "status"),
                ("deleted_at", "deletedAt"), ("manifest_hash", "manifestHash"),
                ("contract_version", "contractVersion"),
            )
            return {
                **{target: metadata[source] for source, target in fields},
                "completedAt": datetime.fromisoformat(metadata["completed_at"]),
            }

        for index, item in enumerate(prepared):
            if type(item) is not dict or set(item) != {
                "metadata", "creator", "files", "matrices", "objectPrefix",
            }:
                raise ValueError("Invalid prepared checkpoint fields.")
            metadata = item["metadata"]
            if type(metadata) is not dict:
                raise ValueError("Prepared source metadata must be a dictionary.")
            sourceID = metadata.get("session_id")
            validateID(sourceID)
            if sourceID in sourceIDs:
                raise ValueError("Duplicate prepared source checkpoint.")
            validatePath(item["objectPrefix"])
            prefixes.append(item["objectPrefix"])

            manifest = item["files"]["manifest"]
            expectedContract = "pgl.raw.behavior.v1" if index == 0 else "pgl.derived.behavior.v3"
            if manifest.get("contract_version") != expectedContract:
                raise ValueError("Unsupported prepared checkpoint contract/order.")
            cls._compareExportManifestIdentity(manifest, manifest)
            cls._compareExportFileInventory(item["files"], item["files"])
            cls._compareExportMatrixInventory(
                item["matrices"], item["matrices"],
                sourceManifest=manifest, destinationManifest=manifest,
            )
            # Structural projection now; labels are independently read below.
            cls._prepareExportSessionMetadata(
                metadata, item["creator"], manifest,
                sourceDatabaseID=sourceDatabaseID,
                verifiedLabels=metadata["meta"]["pgl_session_labels"],
            )
            if metadata["ingest_method"] not in ("manual", "automated"):
                raise ValueError("Prepared export requires manual or automated ingest.")
            if index == 0:
                if metadata["parent_session_id"] is not None or metadata["root_session_id"] != sourceID:
                    raise ValueError("Invalid prepared raw root.")
            elif (
                metadata["parent_session_id"] != sourceIDs[-1]
                or metadata["root_session_id"] != sourceIDs[0]
            ):
                raise ValueError("Prepared ancestry must be one complete ordered parent chain.")
            sourceIDs.append(sourceID)
            sourceAncestry.append(ancestryRecord(metadata))

            for revision in item["matrices"]["revisions"]:
                revisionID = revision["matrixRevisionID"]
                # Storage locations may differ; scientific/captured identity may not.
                identity = {
                    key: revision[key]
                    for key in ("matrixRevisionID", "contractVersion", "descriptor")
                }
                identity["bundleInventory"] = {
                    key: revision["bundleInventory"][key]
                    for key in ("descriptor", "files", "bundleBytes")
                }
                if revisionID in expectedRevisions:
                    requireEqual(identity, expectedRevisions[revisionID], "shared matrix observation")
                expectedRevisions[revisionID] = identity

        if set(matrixObjectKeys) != set(expectedRevisions):
            raise ValueError("Prepared matrix paths do not exactly cover distinct revisions.")
        for key in matrixObjectKeys.values(): validatePath(key)
        allPaths = sorted(prefixes + list(matrixObjectKeys.values()))
        for index, path in enumerate(allPaths):
            for other in allPaths[index + 1:]:
                if other == path or other.startswith(path + "/"):
                    raise ValueError("Prepared checkpoint/matrix directories overlap.")

        sessions = sql.Identifier(postgres.databaseSchema, "session")
        users = sql.Identifier(postgres.databaseSchema, "users")
        backends = sql.Identifier(postgres.databaseSchema, "storage_backends")
        mappings = sql.Identifier(postgres.databaseSchema, "session_export_mappings")
        revisions = sql.Identifier(postgres.databaseSchema, "matrix_revisions")
        products = sql.Identifier(postgres.databaseSchema, "session_products")
        links = sql.Identifier(postgres.databaseSchema, "session_files")
        files = sql.Identifier(postgres.databaseSchema, "files")

        with connection.cursor(row_factory=tuple_row) as cursor:
            cursor.execute("SHOW transaction_isolation")
            isolation = cursor.fetchone()[0]
            cursor.execute("SHOW transaction_read_only")
            readOnly = cursor.fetchone()[0]
            if isolation != "read committed" or readOnly != "off":
                raise ValueError("Prepared export requires READ COMMITTED, READ WRITE.")
            cursor.execute("""
                SELECT EXISTS (
                    SELECT 1 FROM pg_catalog.pg_locks
                    WHERE pid = pg_catalog.pg_backend_pid()
                      AND locktype = 'relation' AND relation = %s::regclass
                      AND granted AND mode IN (
                          'ShareRowExclusiveLock', 'ExclusiveLock', 'AccessExclusiveLock'
                      )
                )
            """, (sessions.as_string(connection),))
            if cursor.fetchone() != (True,):
                raise ValueError("Prepared export requires the publication lock.")
        if cls._requireStableDatabaseIdentity(connection, postgres) != expectedDestinationDatabaseID:
            raise ValueError("Actual prepared-export destination UUID differs.")

        if progress is not None: progress(0, "Checking complete export publication scope")
        with connection.transaction():
            with connection.cursor(row_factory=tuple_row) as cursor:
                cursor.execute(sql.SQL("""
                    SELECT source_session_id FROM {}
                    WHERE source_database_id = %s::uuid
                      AND source_session_id = ANY(%s::bigint[])
                """).format(mappings), (sourceDatabaseID, sourceIDs))
                if cursor.fetchone() is not None:
                    raise ValueError("Prepared export scope already contains a mapping.")
                cursor.execute(sql.SQL("""
                    SELECT session_id FROM {}
                    WHERE origin = 'raw' AND deleted_at IS NULL AND manifest_hash = %s
                """).format(sessions), (prepared[0]["metadata"]["manifest_hash"],))
                if cursor.fetchone() is not None:
                    raise ValueError("Prepared export root manifest already exists.")
                if expectedRevisions:
                    cursor.execute(sql.SQL("""
                        SELECT matrix_revision_id FROM {}
                        WHERE matrix_revision_id = ANY(%s::uuid[])
                           OR (backend_id = %s AND object_key = ANY(%s::text[]))
                    """).format(revisions), (
                        sorted(expectedRevisions), backendID, list(matrixObjectKeys.values()),
                    ))
                    if cursor.fetchone() is not None:
                        raise ValueError("Prepared export matrix revision/path conflict.")
                cursor.execute(sql.SQL(
                    "SELECT user_id, username, display_name FROM {} WHERE user_id = %s FOR SHARE"
                ).format(users), (createdBy,))
                actorRow = cursor.fetchone()
                if actorRow is None: raise ValueError("Prepared export actor is absent.")
                destinationCreator = dict(zip(
                    ("sourceUserID", "username", "displayName"), actorRow,
                ))
                cursor.execute(sql.SQL(
                    "SELECT url_prefix, is_active FROM {} WHERE backend_id = %s FOR SHARE"
                ).format(backends), (backendID,))
                backend = cursor.fetchone()
                if backend is None or backend[1] is not True:
                    raise ValueError("Prepared export backend is absent or inactive.")

            filesystem, root = accessContext.resolve(backendID, backend[0])

            def readPreparedMetadata(item, name):
                manifest = item["files"]["manifest"]
                identities = {
                    record["name"]: {
                        "sha256": record["sha256"], "size_bytes": record["size_bytes"],
                    }
                    for record in manifest["files"]
                }
                if name == "manifest.json":
                    content = cls.encodeRawManifest(manifest)
                    expected = {
                        "sha256": hashlib.sha256(content).hexdigest(), "size_bytes": len(content),
                    }
                else:
                    if name not in identities: raise ValueError("Undeclared prepared metadata.")
                    expected = identities[name]
                if expected["size_bytes"] > pglStorage.MAX_METADATA_BYTES:
                    raise ValueError("Prepared metadata exceeds the read limit.")
                validatePath(name)
                path = posixpath.join(root, item["objectPrefix"], name)
                if isinstance(filesystem, LocalFileSystem):
                    localPath = Path(path).absolute()
                    for candidate in (localPath, *localPath.parents):
                        if candidate.is_symlink():
                            raise ValueError("Symlinked prepared export metadata.")
                with filesystem.open(path, "rb") as handle:
                    content = handle.read(expected["size_bytes"] + 1)
                requireEqual({
                    "sha256": hashlib.sha256(content).hexdigest(), "size_bytes": len(content),
                }, expected, "prepared metadata bytes")
                return content

            class PreparedView:
                def __init__(self, item): self.item = item
                def open(self, name, mode="rt", **kwargs):
                    if mode not in ("r", "rt", "rb"):
                        raise ValueError("Prepared metadata view is read-only.")
                    stream = io.BytesIO(readPreparedMetadata(self.item, name))
                    if mode == "rb": return stream
                    return io.TextIOWrapper(stream, encoding=kwargs.get("encoding", "utf-8"))

            if progress is not None:
                progress(0.01, "Rechecking prepared manifests, labels, and history")
            # Reconstruct only history metadata, never scientific arrays.
            labelsByID, historyByID = {}, {}
            for index, item in enumerate(prepared):
                sourceID = sourceIDs[index]
                manifest = item["files"]["manifest"]
                if readPreparedMetadata(item, "manifest.json") != cls.encodeRawManifest(manifest):
                    raise ValueError("Prepared manifest is not the expected canonical bytes.")
                view = PreparedView(item)
                labels = cls._behaviorLabelMetadata(manifest, view)
                history = None
                if index:
                    history, historyLabels = cls._readSessionHistory(view, len(manifest["runs"]))
                    requireEqual(historyLabels, labels, "history labels")
                    # Initial policy requires inputs within the current prefix.
                    cls._inspectExportHistoryReferences(
                        history, sourceDatabaseID=sourceDatabaseID,
                        sourceSessionIDs=sourceIDs[:index + 1],
                    )
                cls._prepareExportSessionMetadata(
                    item["metadata"], item["creator"], manifest,
                    sourceDatabaseID=sourceDatabaseID, verifiedLabels=labels,
                )
                labelsByID[sourceID], historyByID[sourceID] = labels, history

            sessionMapping = {}
            destinationAncestry = []
            observations = {}
            temporaryEvidence = {}
            registeredMatrices = {}

            def readObservation(item, destinationID, observationProgress=None):
                """Read actual uncommitted catalogs and verify matrix bytes."""
                manifest = item["files"]["manifest"]
                with connection.cursor(row_factory=tuple_row) as cursor:
                    cursor.execute(sql.SQL(
                        "SELECT to_jsonb(checkpoint) FROM {} AS checkpoint WHERE session_id = %s"
                    ).format(sessions), (destinationID,))
                    row = cursor.fetchone()
                    if row is None: raise ValueError("Published checkpoint metadata disappeared.")
                    metadata = row[0]
                    cursor.execute(sql.SQL("""
                        SELECT link.name, content.file_id, content.sha256,
                               content.size_bytes, link.role, link.subject_id
                        FROM {} AS link JOIN {} AS content ON content.file_id = link.file_id
                        WHERE link.session_id = %s ORDER BY link.name
                    """).format(links, files), (destinationID,))
                    fileRecords = [
                        dict(zip(
                            ("name", "fileID", "sha256", "size_bytes", "role", "subjectID"), record,
                        ))
                        for record in cursor.fetchall()
                    ]
                    cursor.execute(sql.SQL("""
                        SELECT product.product_name, revision.matrix_revision_id::text,
                               revision.contract_version, revision.descriptor,
                               revision.backend_id, revision.object_key,
                               backend.url_prefix, backend.is_active
                        FROM {} AS product
                        LEFT JOIN {} AS revision
                          ON revision.matrix_revision_id = product.matrix_revision_id
                        LEFT JOIN {} AS backend ON backend.backend_id = revision.backend_id
                        WHERE product.session_id = %s ORDER BY product.product_name
                    """).format(products, revisions, backends), (destinationID,))
                    productRows = cursor.fetchall()

                attachments, actualRevisions = [], {}
                for productIndex, (
                    name, revisionID, contract, descriptor,
                    actualBackend, key, registeredRoot, active,
                ) in enumerate(productRows):
                    observedMatrixProgress = (
                        observationProgress.section(
                            productIndex / len(productRows),
                            (productIndex + 1) / len(productRows),
                            label=f"Rechecking registered matrix {productIndex + 1}/{len(productRows)}",
                        )
                        if observationProgress is not None else None
                    )
                    if revisionID not in expectedRevisions or active is not True:
                        raise ValueError("Unexpected/inactive actual matrix product.")
                    requireEqual(
                        [actualBackend, key, registeredRoot],
                        [backendID, matrixObjectKeys[revisionID], backend[0]],
                        "matrix registration location",
                    )
                    expected = expectedRevisions[revisionID]
                    requireEqual(descriptor, expected["descriptor"], "matrix descriptor")
                    matrixFS, matrixRoot = accessContext.resolve(actualBackend, registeredRoot)
                    inventory = pglStorage.inventoryDataMatrixBundleLayout(
                        posixpath.join(matrixRoot, key), filesystem=matrixFS,
                        expectedDescriptor=descriptor,
                        expectedFiles=expected["bundleInventory"]["files"],
                        requireAllChunks=True,
                        **({"progress": observedMatrixProgress} if observedMatrixProgress is not None else {}),
                    )
                    attachments.append({
                        "catalogName": name, "owner": "session", "localName": name,
                        "matrixRevisionID": revisionID,
                    })
                    actualRevisions[revisionID] = {
                        "matrixRevisionID": revisionID, "contractVersion": contract,
                        "descriptor": descriptor, "bundleInventory": inventory,
                    }
                if observationProgress is not None:
                    observationProgress(1, "Actual checkpoint catalog observations verified")
                return {
                    "metadata": metadata,
                    "files": {"manifest": manifest, "files": fileRecords},
                    "matrices": {
                        "attachments": attachments,
                        "revisions": [actualRevisions[key] for key in sorted(actualRevisions)],
                        "bundleBytes": sum(
                            value["bundleInventory"]["bundleBytes"]
                            for value in actualRevisions.values()
                        ),
                    },
                }

            def buildEvidence(index, scopeLength):
                item = prepared[index]
                sourceID = sourceIDs[index]
                observed = observations[sourceID]
                scopeIDs = sourceIDs[:scopeLength]
                return cls._buildExportMappingEvidence(
                    sourceDatabaseID=sourceDatabaseID,
                    destinationDatabaseID=expectedDestinationDatabaseID,
                    sourceRecord=item["metadata"], sourceCreator=item["creator"],
                    destinationRecord=observed["metadata"],
                    destinationCreator=destinationCreator,
                    sourceManifest=item["files"]["manifest"],
                    destinationManifest=observed["files"]["manifest"],
                    sourceFiles=item["files"], destinationFiles=observed["files"],
                    sourceMatrices=item["matrices"], destinationMatrices=observed["matrices"],
                    sourceAncestry=sourceAncestry[:scopeLength],
                    destinationAncestry=destinationAncestry[:scopeLength],
                    sessionIDMapping={key: sessionMapping[key] for key in scopeIDs},
                    verifiedLabels=labelsByID[sourceID], history=historyByID[sourceID],
                )

            checkpointWork = [
                {
                    "name": f"Publishing source checkpoint {sourceIDs[index]}",
                    "size_bytes": (
                        sum(record["size_bytes"] for record in item["files"]["files"])
                        + item["matrices"]["bundleBytes"]
                    ),
                    "index": index,
                    "checkpoint": item,
                }
                for index, item in enumerate(prepared)
            ]
            checkpointRange = progress.section(0.05, 0.75) if progress is not None else None
            for workItem, checkpointProgress in pglProgress.fileSections(
                checkpointWork, checkpointRange,
            ):
                index = workItem["index"]
                item = workItem["checkpoint"]
                sourceID = sourceIDs[index]
                matrixWork = [
                    {
                        "name": revision["matrixRevisionID"],
                        "size_bytes": revision["bundleInventory"]["bundleBytes"],
                        "revision": revision,
                    }
                    for revision in item["matrices"]["revisions"]
                ]
                matrixRange = (
                    checkpointProgress.section(0, 0.25)
                    if checkpointProgress is not None else None
                )
                for matrixItem, matrixProgress in pglProgress.fileSections(matrixWork, matrixRange):
                    revision = matrixItem["revision"]
                    revisionID = revision["matrixRevisionID"]
                    if revisionID in registeredMatrices: continue
                    registeredMatrices[revisionID] = cls._registerExportMatrixRevision(
                        connection, postgres,
                        sourceDatabaseID=sourceDatabaseID,
                        expectedDescriptor=revision["descriptor"],
                        expectedFiles=revision["bundleInventory"]["files"],
                        expectedDestinationDatabaseID=expectedDestinationDatabaseID,
                        createdBy=createdBy, backendID=backendID,
                        objectKey=matrixObjectKeys[revisionID], accessContext=accessContext,
                        **({"progress": matrixProgress} if matrixProgress is not None else {}),
                    )

                common = {
                    "sourceDatabaseID": sourceDatabaseID,
                    "sourceRecord": item["metadata"], "sourceCreator": item["creator"],
                    "manifest": item["files"]["manifest"],
                    "expectedDestinationDatabaseID": expectedDestinationDatabaseID,
                    "createdBy": createdBy, "backendID": backendID,
                    "objectPrefix": item["objectPrefix"], "savedTimezone": savedTimezone,
                    "accessContext": accessContext,
                }
                if checkpointProgress is not None:
                    common["progress"] = checkpointProgress.section(
                        0.25, 0.80, label=f"Registering checkpoint {sourceID}",
                    )
                if index == 0:
                    registered = cls._registerExportRawCheckpoint(connection, postgres, **common)
                else:
                    registered = cls._registerExportDerivedCheckpoint(
                        connection, postgres, **common,
                        sourceMatrixInventory=item["matrices"],
                        parentEvidence=temporaryEvidence[sourceIDs[index - 1]],
                        parentStorageOptionsByBackend=storageOptionsByBackend,
                    )
                destinationID = registered["destinationSessionID"]
                sessionMapping[sourceID] = destinationID
                observations[sourceID] = readObservation(
                    item, destinationID,
                    observationProgress=(
                        checkpointProgress.section(0.80, 0.95)
                        if checkpointProgress is not None else None
                    ),
                )
                destinationAncestry.append(ancestryRecord(observations[sourceID]["metadata"]))
                prefixEvidence = buildEvidence(index, index + 1)
                cls._validateExportMappingEvidence(prefixEvidence)
                temporaryEvidence[sourceID] = prefixEvidence
                if checkpointProgress is not None:
                    checkpointProgress(1, "Checkpoint and prefix evidence checked; uncommitted")

            # Do not persist prefix evidence: every mapping must attest the
            # same final chain, including the root's mapping.
            evidenceByID = {}
            for index, sourceID in enumerate(sourceIDs):
                if progress is not None:
                    progress(
                        0.75 + 0.05 * index / len(sourceIDs),
                        f"Building full-chain evidence for checkpoint {sourceID}",
                    )
                evidence = buildEvidence(index, len(prepared))
                cls._validateExportMappingEvidence(evidence)
                evidenceByID[sourceID] = evidence

            mappingResults = {}
            mappingWork = [
                {
                    "name": f"Mapping source checkpoint {sourceID}",
                    "size_bytes": (
                        evidenceByID[sourceID]["files"]["logicalBytes"]
                        + evidenceByID[sourceID]["matrices"]["bundleBytes"]
                    ),
                    "sourceID": sourceID,
                }
                for sourceID in sourceIDs
            ]
            mappingRange = progress.section(0.80, 0.99) if progress is not None else None
            for workItem, mappingProgress in pglProgress.fileSections(mappingWork, mappingRange):
                sourceID = workItem["sourceID"]
                mappingResults[sourceID] = cls._registerVerifiedSessionExportMapping(
                    connection, postgres, evidenceByID[sourceID],
                    sourceDatabaseName=sourceDatabaseName, registeredBy=createdBy,
                    storageOptionsByBackend=storageOptionsByBackend,
                    **({"progress": mappingProgress} if mappingProgress is not None else {}),
                )

        if progress is not None:
            progress(1, "Prepared export registered; outer transaction uncommitted")
        return {
            "sourceDatabaseID": sourceDatabaseID,
            "destinationDatabaseID": expectedDestinationDatabaseID,
            "sessionIDMapping": sessionMapping,
            "evidenceBySourceSessionID": evidenceByID,
            "mappingRegistrations": mappingResults,
            "outerCommitConfirmed": False,
            "foreignResolutionAuthorized": False,
        }
        
    @classmethod
    def _prepareSessionExportPayloads(
        cls, connection, postgres, sessionID, destinationPath, *,
        expectedSourceDatabaseID,
        sourceStorageOptionsByBackend=None,
        destinationFilesystem=None, destinationStorageOptions=None,
        progress=None,
    ):
        """Inspect a source chain and copy prepared byte-preserving payloads.

        Requires caller-owned REPEATABLE READ or SERIALIZABLE, READ ONLY.
        Checks source migration compatibility and the expected stable UUID.

        Initial contracts:
            pgl.raw.behavior.v1 root.
            pgl.derived.behavior.v3 descendants.

        destinationPath:
            Exact fresh preparation directory; its parent must already exist.
            It is not an existing destination backend to merge or overwrite.
            Caller resolves/authorizes the intended destination storage.

        Produces:
            checkpoints/checkpoint-<source ID>/...
            matrices/matrix-<revision UUID>/...

        Returns preparedCheckpoints and matrixObjectKeys in the representation
        required by _registerPreparedSessionExport(), plus transfer observations.

        Source files use the first eligible catalog location without fallback.
        Distinct matrix revisions are copied once; conflicting captured
        observations fail. All bundles require strict grid-chunk coverage.

        Copied metadata is read with bounded, hash-verified reads for independent
        label extraction and supported history-reference inspection. Scientific
        arrays are never constructed or decoded.

        Source snapshots remain the caller's responsibility until publication
        policy has established the required source stability. Independent SQL
        snapshots and filesystems are not an atomic cross-database snapshot.
        Concurrent payload mutation/writers are unsupported.

        Rejects detectable local symlinks and overlap with selected source roots
        when filesystem namespace identity is known. Arbitrarily aliased remote
        namespaces cannot be identified generically.

        Owns bounded source pglDatabaseAccess. Does not close the destination
        filesystem, including one resolved by fsspec.

        No destination SQL, mapping insertion, commit, retries, reuse, deletion,
        rollback of files, or publication/foreign-loading authorization.
        Failures retain created directories and copied/partial files.
        Optional progress is a pglProgress-compatible call/section reporter.
        Source inventory uses checkpoint-count allocation until byte totals
        are known; subsequent transfers are weighted by captured bytes.
        These ranges allocate work, not elapsed-time estimates. This helper
        never finishes the enclosing export display. Public calls supply
        a display-failure-isolated adapter; direct callback errors propagate.

        """
        from copy import deepcopy
        from pathlib import Path
        from uuid import UUID
        import hashlib
        import io
        import posixpath

        from fsspec.implementations.local import LocalFileSystem
        from psycopg.rows import tuple_row

        if progress is not None: progress(0, "Checking source identity and preparation destination")
        cls._requireMigrationInspectionTransaction(connection)
        with connection.cursor(row_factory=tuple_row) as cursor:
            cursor.execute("SHOW transaction_isolation")
            isolation = cursor.fetchone()[0]
            cursor.execute("SHOW transaction_read_only")
            readOnly = cursor.fetchone()[0]
        if isolation not in ("repeatable read", "serializable") or readOnly != "on":
            raise ValueError("Export preparation requires a consistent read-only source transaction.")

        if type(expectedSourceDatabaseID) is not str:
            raise ValueError("Expected source UUID must be a string.")
        try:
            parsedID = UUID(expectedSourceDatabaseID)
        except ValueError as error:
            raise ValueError("Invalid expected source UUID.") from error
        if str(parsedID) != expectedSourceDatabaseID or not parsedID.int:
            raise ValueError("Expected source UUID must be canonical and nonzero.")
        if cls._requireStableDatabaseIdentity(connection, postgres) != expectedSourceDatabaseID:
            raise ValueError("Actual source UUID differs from expected source.")

        ancestry = cls._readExportAncestry(connection, postgres, sessionID)
        for index, checkpoint in enumerate(ancestry):
            expectedContract = (
                "pgl.raw.behavior.v1" if index == 0 else "pgl.derived.behavior.v3"
            )
            if checkpoint["contractVersion"] != expectedContract:
                raise ValueError("Unsupported source contract for initial export preparation.")

        destinationFilesystem, destinationRoot = pglStorage._resolveStoragePath(
            destinationPath,
            filesystem=destinationFilesystem,
            storageOptions=destinationStorageOptions,
            label="export preparation destination",
        )
        destinationRoot = destinationRoot.rstrip("/")
        if not destinationRoot:
            raise ValueError("Export preparation cannot target the filesystem root.")

        def requireLocalSafe(filesystem, path):
            if isinstance(filesystem, LocalFileSystem):
                localPath = Path(path).absolute()
                for candidate in (localPath, *localPath.parents):
                    if candidate.is_symlink():
                        raise ValueError(f"Symlinked export preparation path: {candidate}")

        def requireNewDestination():
            requireLocalSafe(destinationFilesystem, destinationRoot)
            if destinationFilesystem.exists(destinationRoot):
                raise FileExistsError(destinationRoot)
            parent = posixpath.dirname(destinationRoot) or "."
            requireLocalSafe(destinationFilesystem, parent)
            if not destinationFilesystem.isdir(parent):
                raise NotADirectoryError(parent)

        requireNewDestination()
        sessions = sql.Identifier(postgres.databaseSchema, "session")
        users = sql.Identifier(postgres.databaseSchema, "users")
        prepared = []
        revisionsByID = {}
        matrixObjectKeys = {}
        transferObservations = []

        with pglDatabaseAccess(postgres, sourceStorageOptionsByBackend) as sourceAccess:
            def checkSourceOverlap(backendID, registeredRoot):
                sourceFS, sourceRoot = sourceAccess.resolve(backendID, registeredRoot)
                requireLocalSafe(sourceFS, sourceRoot)
                bothLocal = (
                    isinstance(sourceFS, LocalFileSystem)
                    and isinstance(destinationFilesystem, LocalFileSystem)
                )
                if bothLocal:
                    sourcePath = str(Path(sourceRoot).absolute())
                    targetPath = str(Path(destinationRoot).absolute())
                elif sourceFS is destinationFilesystem:
                    sourcePath, targetPath = sourceRoot, destinationRoot
                else:
                    return

                sourcePath = posixpath.normpath(sourcePath)
                targetPath = posixpath.normpath(targetPath)
                if (
                    sourcePath == targetPath
                    or targetPath.startswith(sourcePath.rstrip("/") + "/")
                    or sourcePath.startswith(targetPath.rstrip("/") + "/")
                ):
                    raise ValueError("Preparation destination overlaps a selected source storage root.")

            # Capture and structurally check the complete source scope before
            # creating any destination output. Matrix inventory hashes source
            # bundles but does not open scientific arrays.
            for checkpointIndex, checkpoint in enumerate(ancestry):
                sourceID = checkpoint["sessionID"]
                checkpointProgress = (
                    progress.section(
                        0.20 * checkpointIndex / len(ancestry),
                        0.20 * (checkpointIndex + 1) / len(ancestry),
                        label=f"Inventory source checkpoint {sourceID}",
                    )
                    if progress is not None else None
                )
                if checkpointProgress is not None:
                    checkpointProgress(0, "Reading source manifest and catalog")
                fileInventory = cls._readExportFileInventory(
                    connection, postgres, checkpoint,
                    storageOptionsByBackend=sourceStorageOptionsByBackend,
                )
                matrixInventory = cls._readExportMatrixBundleInventory(
                    connection, postgres, checkpoint, requireAllChunks=True,
                    storageOptionsByBackend=sourceStorageOptionsByBackend,
                    progress=(
                        checkpointProgress.section(0.05, 0.95)
                        if checkpointProgress is not None else None
                    ),
                )
                with connection.cursor(row_factory=tuple_row) as cursor:
                    cursor.execute(sql.SQL(
                        "SELECT to_jsonb(checkpoint) FROM {} AS checkpoint WHERE session_id = %s"
                    ).format(sessions), (sourceID,))
                    row = cursor.fetchone()
                    if row is None: raise ValueError("Source metadata is absent.")
                    metadata = row[0]
                    cursor.execute(sql.SQL(
                        "SELECT user_id, username, display_name FROM {} WHERE user_id = %s"
                    ).format(users), (metadata["created_by"],))
                    creatorRow = cursor.fetchone()
                if creatorRow is None:
                    raise ValueError("Source creator metadata is absent.")
                creator = dict(zip(("sourceUserID", "username", "displayName"), creatorRow))

                manifest = fileInventory["manifest"]
                cls._compareExportFileInventory(fileInventory, fileInventory)
                cls._compareExportMatrixInventory(
                    matrixInventory, matrixInventory,
                    sourceManifest=manifest, destinationManifest=manifest,
                )
                # Structural metadata check only here; labels are independently
                # extracted from verified destination metadata below.
                cls._prepareExportSessionMetadata(
                    metadata, creator, manifest,
                    sourceDatabaseID=expectedSourceDatabaseID,
                    verifiedLabels=metadata["meta"]["pgl_session_labels"],
                )
                if metadata["ingest_method"] not in ("manual", "automated"):
                    raise ValueError("Initial preparation requires manual or automated ingest.")

                for record in fileInventory["files"]:
                    location = record["locations"][0]
                    checkSourceOverlap(location["backendID"], location["registeredRoot"])
                for revision in matrixInventory["revisions"]:
                    checkSourceOverlap(revision["backendID"], revision["registeredRoot"])
                    revisionID = revision["matrixRevisionID"]
                    if revisionID in revisionsByID:
                        if pglStorage.encodeJSON(revisionsByID[revisionID]) != pglStorage.encodeJSON(revision):
                            raise ValueError("Conflicting source observations for a shared matrix revision.")
                    revisionsByID[revisionID] = deepcopy(revision)

                prepared.append({
                    "metadata": metadata,
                    "creator": creator,
                    "files": fileInventory,
                    "matrices": matrixInventory,
                    "objectPrefix": f"checkpoints/checkpoint-{sourceID}",
                })
                if checkpointProgress is not None:
                    checkpointProgress(1, "Source checkpoint inventory captured")

            checkpointWork = [
                {
                    "name": f"Checkpoint {item['metadata']['session_id']}",
                    "size_bytes": sum(
                        record["size_bytes"] for record in item["files"]["files"]
                    ),
                    "checkpoint": item,
                }
                for item in prepared
            ]
            matrixWork = [
                {
                    "name": revisionID,
                    "size_bytes": revisionsByID[revisionID]["bundleInventory"]["bundleBytes"],
                }
                for revisionID in sorted(revisionsByID)
            ]
            checkpointWeight = sum(max(1, item["size_bytes"]) for item in checkpointWork)
            matrixWeight = sum(max(1, item["size_bytes"]) for item in matrixWork)
            transferSplit = (
                0.20 + 0.75 * checkpointWeight
                / max(1, checkpointWeight + matrixWeight)
            )
            checkpointTransferProgress = (
                progress.section(0.20, transferSplit)
                if progress is not None else None
            )
            matrixTransferProgress = (
                progress.section(transferSplit, 0.95)
                if progress is not None else None
            )

            requireNewDestination()
            destinationFilesystem.makedirs(destinationRoot, exist_ok=False)
            for directory in ("checkpoints", "matrices"):
                requireLocalSafe(
                    destinationFilesystem, posixpath.join(destinationRoot, directory),
                )
                destinationFilesystem.makedirs(
                    posixpath.join(destinationRoot, directory), exist_ok=False,
                )

            for workItem, checkpointProgress in pglProgress.fileSections(
                checkpointWork, checkpointTransferProgress,
            ):
                item = workItem["checkpoint"]
                destinationBundle = posixpath.join(destinationRoot, item["objectPrefix"])
                copied = cls._copyExportCheckpointFiles(
                    item["files"], destinationBundle,
                    sourceAccess=sourceAccess,
                    destinationFilesystem=destinationFilesystem,
                    progress=checkpointProgress,
                )
                transferObservations.append({
                    "sourceSessionID": item["metadata"]["session_id"],
                    "fileCount": len(copied["files"]),
                    "logicalFileBytes": copied["fileBytes"],
                })

            for workItem, matrixProgress in pglProgress.fileSections(
                matrixWork, matrixTransferProgress,
            ):
                revisionID = workItem["name"]
                revision = revisionsByID[revisionID]
                matrixKey = f"matrices/matrix-{revisionID}"
                sourceFS, sourceRoot = sourceAccess.resolve(
                    revision["backendID"], revision["registeredRoot"],
                )
                copied = pglStorage.copyDataMatrixBundle(
                    posixpath.join(sourceRoot, revision["objectKey"]),
                    posixpath.join(destinationRoot, matrixKey),
                    sourceFilesystem=sourceFS,
                    destinationFilesystem=destinationFilesystem,
                    expectedDescriptor=revision["descriptor"],
                    expectedFiles=revision["bundleInventory"]["files"],
                    requireAllChunks=True,
                    progress=matrixProgress,
                )
                if copied["inventory"] != revision["bundleInventory"]:
                    raise ValueError("Transferred matrix inventory differs from captured source.")
                matrixObjectKeys[revisionID] = matrixKey

            def readMetadata(item, name):
                manifest = item["files"]["manifest"]
                records = {record["name"]: record for record in manifest["files"]}
                if name == "manifest.json":
                    canonical = cls.encodeRawManifest(manifest)
                    expected = {
                        "sha256": hashlib.sha256(canonical).hexdigest(),
                        "size_bytes": len(canonical),
                    }
                else:
                    if name not in records:
                        raise ValueError("Undeclared copied metadata.")
                    expected = {
                        key: records[name][key] for key in ("sha256", "size_bytes")
                    }
                if expected["size_bytes"] > pglStorage.MAX_METADATA_BYTES:
                    raise ValueError("Copied metadata exceeds the read limit.")
                path = posixpath.join(destinationRoot, item["objectPrefix"], name)
                requireLocalSafe(destinationFilesystem, path)
                with destinationFilesystem.open(path, "rb") as handle:
                    content = handle.read(expected["size_bytes"] + 1)
                if {
                    "sha256": hashlib.sha256(content).hexdigest(),
                    "size_bytes": len(content),
                } != expected:
                    raise ValueError("Copied metadata changed or differs from source inventory.")
                return content

            class MetadataView:
                def __init__(self, item): self.item = item
                def open(self, name, mode="rt", **kwargs):
                    if mode not in ("r", "rt", "rb"):
                        raise ValueError("Preparation metadata view is read-only.")
                    stream = io.BytesIO(readMetadata(self.item, name))
                    if mode == "rb": return stream
                    return io.TextIOWrapper(stream, encoding=kwargs.get("encoding", "utf-8"))

            historyReports = []
            sourceIDs = [item["metadata"]["session_id"] for item in prepared]
            for index, item in enumerate(prepared):
                if progress is not None:
                    progress(
                        0.95 + 0.04 * index / len(prepared),
                        f"Checking copied labels and history for checkpoint {sourceIDs[index]}",
                    )
                manifest = item["files"]["manifest"]
                if readMetadata(item, "manifest.json") != cls.encodeRawManifest(manifest):
                    raise ValueError("Copied manifest is not the expected canonical bytes.")
                view = MetadataView(item)
                labels = cls._behaviorLabelMetadata(manifest, view)
                cls._prepareExportSessionMetadata(
                    item["metadata"], item["creator"], manifest,
                    sourceDatabaseID=expectedSourceDatabaseID,
                    verifiedLabels=labels,
                )
                historyReport = None
                if index:
                    history, historyLabels = cls._readSessionHistory(view, len(manifest["runs"]))
                    if pglStorage.encodeJSON(historyLabels) != pglStorage.encodeJSON(labels):
                        raise ValueError("Copied history and archived settings labels differ.")
                    historyReport = cls._inspectExportHistoryReferences(
                        history, sourceDatabaseID=expectedSourceDatabaseID,
                        sourceSessionIDs=sourceIDs[:index + 1],
                    )
                historyReports.append({
                    "sourceSessionID": sourceIDs[index],
                    "historyInspection": historyReport,
                })

        if progress is not None: progress(1, "Export payload preparation verified")
        return {
            "sourceDatabaseID": expectedSourceDatabaseID,
            "selectedSourceSessionID": sessionID,
            "destinationPath": destinationFilesystem.unstrip_protocol(destinationRoot),
            "preparedCheckpoints": prepared,
            "matrixObjectKeys": matrixObjectKeys,
            "checkpointTransfers": transferObservations,
            "historyInspections": historyReports,
            "publicationTimeRecheckRequired": True,
            "publicationAuthorized": False,
            "reuseAuthorized": False,
            "foreignResolutionAuthorized": False,
        }
        
    @classmethod
    def _resolveSessionExportConfiguration(
        cls, session, databaseName, *,
        lockTimeoutSeconds=30.0, ioTimeoutSeconds=60, connectTimeoutSeconds=10,
    ):
        """Resolve a saved-session export's explicit runtime configurations.

        Public intent:
            session.export(databaseName="destinationProfile")

        Source:
            Uses only storage-established checkpoint binding and the retained
            _checkpointPostgres configuration. Never resolves the source by
            its display label or by the current default profile.

        Destination:
            Loads only the explicitly named PGL profile. Does not create a
            default profile, change the default, or create a missing profile.
            Uses that profile's creator username and PostgreSQL configuration.

        Validates retained source endpoint correspondence before destination
        profile discovery. Numeric sessionID alone is not sufficient.

        Returns independent source/destination PostgreSQL configuration copies,
        a source checkpoint reference, destination profile labels, and username.
        Runtime credentials/configuration must not be serialized into evidence
        or indiscriminately logged by the caller.

        Does not open SQL connections, read scientific data, detect dirty
        working values, save a session, resolve payload filesystems, register
        backends, publish, or change the session's binding.

        Reading the named destination profile/configuration can involve its
        configured filesystem. Configuration/authentication errors propagate.

        Does not establish the actual destination UUID, source authenticity,
        backend availability, or publication eligibility. Those require live
        inspection before any payload creation.

        A destination without storageLocations is returned as configured:
        existing-export reconciliation may still be possible. A new export
        must reject missing destination storage before preparation.
        """
        from copy import deepcopy

        from .pglPostgres import pglPostgres
        from .pglSession import pglSession

        if not isinstance(session, pglSession):
            raise TypeError("session must be a pglSession.")
        if (
            type(databaseName) is not str or not databaseName.strip()
            or databaseName != databaseName.strip()
            or any(character in databaseName for character in ("\x00", "\n", "\r"))
        ):
            raise ValueError("databaseName must explicitly name a destination profile.")

        pglPostgres.validateTimeouts(
            lockTimeoutSeconds=lockTimeoutSeconds,
            ioTimeoutSeconds=ioTimeoutSeconds,
            connectTimeoutSeconds=connectTimeoutSeconds,
        )

        reference = cls._getBoundCheckpointReference(session)
        if reference is None:
            raise ValueError(
                "Export requires a saved checkpoint with a database binding. "
                "Save or reload the intended source checkpoint first."
            )

        binding = cls._validateCheckpointBinding(session._checkpointBinding)
        sourceConfiguration = getattr(session, "_checkpointPostgres", None)
        if not isinstance(sourceConfiguration, pglPostgres):
            raise ValueError(
                "The saved source PostgreSQL configuration is unavailable. "
                "Reload the intended checkpoint; export will not infer a source profile."
            )

        # Snapshot configurations, not live connections or scientific objects.
        sourcePostgres = sourceConfiguration.withTimeouts(
            lockTimeoutSeconds=lockTimeoutSeconds,
            ioTimeoutSeconds=ioTimeoutSeconds,
            connectTimeoutSeconds=connectTimeoutSeconds,
        )
        if (
            cls._checkpointDatabaseIdentity(sourcePostgres)
            != binding["databaseIdentity"]
        ):
            raise ValueError(
                "Retained source configuration differs from the saved checkpoint endpoint. "
                "Reload the intended source rather than retargeting its configuration."
            )

        # Never call getSettings() with neither an explicit name nor settings:
        # that branch may create/change defaults.
        destinationSettings = cls.getSettings(settingsName=databaseName)
        if destinationSettings is None:
            raise ValueError("The explicitly named destination profile could not be loaded.")
        if not isinstance(destinationSettings, pglDatabaseSettings):
            raise TypeError("Destination profile is not pglDatabaseSettings.")

        username = destinationSettings.username
        if type(username) is not str or not username.strip() or "\x00" in username:
            raise ValueError("The destination profile needs a valid publication username.")
        destinationLabel = destinationSettings.name
        if (
            type(destinationLabel) is not str or not destinationLabel.strip()
            or any(character in destinationLabel for character in ("\x00", "\n", "\r"))
        ):
            raise ValueError("The destination profile has an invalid display name.")

        destinationConfiguration = pglPostgres.fromSettings(settings=destinationSettings)
        if destinationConfiguration is None:
            raise ValueError("The destination profile's PostgreSQL configuration is unavailable.")
        if not isinstance(destinationConfiguration, pglPostgres):
            raise TypeError("Destination configuration is not pglPostgres.")

        destinationPostgres = destinationConfiguration.withTimeouts(
            lockTimeoutSeconds=lockTimeoutSeconds,
            ioTimeoutSeconds=ioTimeoutSeconds,
            connectTimeoutSeconds=connectTimeoutSeconds,
        )

        return {
            "sourceReference": deepcopy(reference),
            "sourcePostgres": sourcePostgres,
            "destinationPostgres": destinationPostgres,
            "destinationProfileName": databaseName,
            "destinationDisplayName": destinationLabel,
            "username": username,
        }
        
    @staticmethod
    def _confirmSessionExportPlan(decision, *, destinationProfileName):
        """Confirm a new export without destination writes or publication locks.

        The decision supplies the source ancestry and distinct matrix IDs.
        No total transfer size is invented: catalog-only decision inspection
        has not established a complete byte inventory.

        Existing/conflicting exports are not confirmation candidates.
        Only literal True from the shared dialog authorizes continuation.
        Dialog cancellation/failure returns False; interrupts propagate.
        """
        if type(decision) is not dict or decision.get("state") != "newExportCandidate":
            raise ValueError("Only a new-export candidate can be confirmed.")

        source = decision["sourceReference"]
        ancestry = decision["requestedAncestrySessionIDs"]
        matrices = decision["matrixRevisionIDs"]
        details = "\n".join([
            f"Source profile label: {source['databaseName']!r}",
            f"Source database UUID: {source['databaseID']}",
            f"Selected saved checkpoint: {source['sessionID']}",
            f"Saved ancestry, root to selected: {', '.join(map(str, ancestry))}",
            f"Checkpoint count: {len(ancestry)}",
            f"Distinct matrix revisions: {len(matrices)}",
            "",
            f"Destination profile: {destinationProfileName!r}",
            f"Destination database UUID: {decision['destinationDatabaseID']}",
            "Storage: first configured destination payload location.",
            "Output: a newly generated export-<UUID> directory; no overwrite.",
            "",
            "Transfer size: not yet inventoried; no byte estimate is claimed.",
            "Preparation and repeated integrity verification may take time.",
            "The current implementation holds the destination publication lock during transfer.",
            "",
            "Only SAVED checkpoint contents are exported.",
            "Unsaved working edits are excluded; the working source binding stays unchanged.",
            "Source-qualified historical provenance is preserved.",
            "",
            "Approval permits attempting new destination publication.",
            "Identities and conflicts are checked again during publication.",
            "Failures may leave retained partial/unregistered payloads.",
            "An uncertain commit must be inspected before any retry.",
            "No automatic cleanup, overwrite, or repair is performed.",
        ])
        return pglDialogs.confirm(
            "Export the selected saved checkpoint and its ancestry?",
            title="Confirm database session export",
            details=details,
            confirmButtonText="Export saved checkpoint",
            copyText="Copy export plan",
        ) is True

    @staticmethod
    def _warnSessionExportFailure(error, outcome):
        """Report export failure without leaking backend exception text.

        Presentation only: does not suppress/reclassify the original exception,
        retry, connect, repair, or delete anything. Caller guards warning failures.
        The full original exception and exportOutcome remain available.
        """
        if outcome.get("commitConfirmed"):
            status = (
                "Destination publication COMMITTED. It was not rolled back. "
                "Subsequent verification or resource cleanup did not finish successfully."
            )
            if outcome.get("postCommitVerificationPassed"):
                status += " Independent post-commit verification had already passed."
            recovery = (
                "Inspect the existing destination mappings before doing anything else. "
                "Do not republish or delete its payload directory to resolve this error."
            )
        elif outcome.get("commitAttempted"):
            status = (
                "Commit was attempted, but this client did not confirm its outcome. "
                "The destination may already contain the completed export."
            )
            recovery = (
                "Restore access and inspect the source-qualified destination mappings "
                "before retrying. Do not assume rollback or start another publication blindly."
            )
        else:
            status = (
                "The final destination commit was not attempted. "
                "Transaction/resource cleanup was attempted; prepared files may remain."
            )
            recovery = (
                "Resolve the reported issue and inspect any retained preparation output "
                "before another attempt. Do not overwrite or automatically delete it."
            )

        sqlstate = getattr(error, "sqlstate", None)
        if isinstance(error, KeyboardInterrupt):
            advice = "The operation was interrupted."
        elif isinstance(error, TimeoutError) or sqlstate in {"55P03", "57014"}:
            advice = (
                "A wait or operation timed out. Check connectivity and active PostgreSQL "
                "locks; do not terminate another session without reviewing its work."
            )
        elif isinstance(error, PermissionError) or sqlstate in {"28000", "28P01", "42501"}:
            advice = "Check the selected profile's credentials and database/storage permissions."
        elif isinstance(error, FileExistsError):
            advice = "An output location already exists. Retain it for review; export does not overwrite."
        elif isinstance(error, FileNotFoundError):
            advice = (
                "Check configured storage roots, mounts, and registered payload availability. "
                "Restore missing files from a trusted copy rather than altering hashes."
            )
        elif isinstance(error, (ConnectionError, psycopg.OperationalError, psycopg.InterfaceError)):
            advice = "Check PostgreSQL availability, network/VPN connectivity, and configured transport."
        elif isinstance(error, (ValueError, TypeError)):
            advice = (
                "Review the original exception for the exact configuration, contract, "
                "identity, or integrity mismatch. Do not bypass validation to proceed."
            )
        elif isinstance(error, OSError):
            advice = "Check storage availability, free space, mounts, and read/write permissions."
        else:
            advice = (
                "Retain the traceback and report the failure before retrying; "
                "an unexpected implementation or dependency error may have occurred."
            )

        identifiers = []
        reference = outcome.get("sourceReference")
        if type(reference) is dict:
            identifiers.append(
                f"Source checkpoint: {reference.get('sessionID')} "
                f"in schema UUID {reference.get('databaseID')}."
            )
        if outcome.get("destinationDatabaseID"):
            identifiers.append(f"Destination schema UUID: {outcome['destinationDatabaseID']}.")
        if outcome.get("destinationBackendID") is not None:
            identifiers.append(f"Destination backend ID: {outcome['destinationBackendID']}.")
        if outcome.get("preparationObjectPrefix"):
            identifiers.append(
                f"Retained preparation prefix: {outcome['preparationObjectPrefix']} "
                "(relative to the configured backend root)."
            )
        if outcome.get("sessionIDMapping"):
            identifiers.append(f"Allocated source-to-destination IDs: {outcome['sessionIDMapping']}.")

        pglMessages.warning(
            f"Session export stopped during {outcome.get('phase', 'unknown phase')} "
            f"({type(error).__name__}).\n"
            f"{status}\n{advice}\n{recovery}\n"
            + "\n".join(identifiers)
            + "\nThe original exception retains exportOutcome where available. "
              "No automatic retry, connection termination, or payload deletion occurred.",
            level=2,
        )

    @classmethod
    def exportSession(
        cls, session, *, databaseName,
        sourceStorageOptionsByBackend=None, destinationStorageOptions=None,
        sourceSSLRootCert=None, destinationSSLRootCert=None,
        lockTimeoutSeconds=30.0, ioTimeoutSeconds=60, connectTimeoutSeconds=10,
    ):
        """Export a session's selected SAVED checkpoint to a named profile.

        Public wrapper:
            session.export(databaseName="labArchive")

        Does not save working edits, switch the session's source binding, or
        infer source identity from the current default profile.

        Initial scope:
            Raw behavioral-v1 root and derived behavioral-v3 descendants.
            No automatic partial-export merging, conflicting revision reuse,
            overwrite, repair, or retry.

        Returns:
            state='verifiedExistingExport':
                Existing destination and current source verified; no new writes.
            state='conflict':
                Initial decision found blockers; no preparation/publication.
            state='cancelled':
                New-export confirmation was declined or unavailable. No
                publication connection, lock, destination writes, or output.
            state='exported':
                New publication committed and independently verified through
                a new read-only destination connection.

        Internal transaction sequence:
            Consistent read-only source snapshot.
            Separate destination read-only decision transaction, closed first.
            READ COMMITTED destination publication transaction and lock.
            Configured-backend registration, fresh preparation, actor resolution,
            prepared publication, payload-access closure, then commit.
            New read-only destination connection for post-commit verification.

        The initial implementation holds the destination publication lock
        throughout preparation/transfer. This favors explicit ownership and
        rollback boundaries over concurrent-writer throughput.

        A configured destination root must already exist. Preparation creates
        a fresh generated child directory. Failed/partial output is retained.

        Confirmation/progress:
            New exports require pglDialogs.confirm before publication access.
            Verification paths report actual streamed-byte progress.
            Preparation and publication report streamed copying/hashing,
            catalog registration, evidence construction, and mapping verification.
            Ranges allocate work rather than predict elapsed time. Only this
            outer operation reports overall success after verification and cleanup.
            Confirmation occurs with no destination publication locks.

        Failure:
            An export-specific warning is displayed without suppressing errors.
            Original exception propagates. Where supported, exportOutcome is
            attached to it, with commitAttempted, commitConfirmed, phase,
            selected identities, allocated mapping, and preparation prefix.
            Exception notes summarize commit state without runtime credentials.
            No automatic retry, connection termination, or deletion.

        A failure after confirmed commit does not roll publication back.
        An unconfirmed commit may already have succeeded.
        A post-commit verification result does not authorize foreign loading.

        Connection/password handling uses existing pglPostgres.connect().
        Cancellation produces an exception rather than silently choosing another
        profile. Runtime storage/authentication options are never returned as
        evidence or included in exportOutcome.

        Source/destination SQL snapshots and payload hashing are not atomic.
        Concurrent scientific-payload mutation is unsupported.
        """
        from copy import deepcopy
        from uuid import uuid4
        import posixpath

        outcome = {
            "state": "inProgress",
            "phase": "resolvingConfiguration",
            "sourceReference": None,
            "destinationDatabaseID": None,
            "destinationProfileName": databaseName if type(databaseName) is str else None,
            "destinationBackendID": None,
            "preparationObjectPrefix": None,
            "preparationStarted": False,
            "confirmationRequested": False,
            "confirmationAccepted": False,
            "commitAttempted": False,
            "commitConfirmed": False,
            "postCommitVerificationPassed": False,
            "sessionIDMapping": None,
            "foreignResolutionAuthorized": False,
        }


        progress = None


        class SafeExportProgress:
            """Isolate ordinary display failures, never operation failures.

            Only the wrapped display methods are inside try/except. Errors
            raised by hashing, copying, SQL, or validation still propagate.
            KeyboardInterrupt is not suppressed.
            """
            def __init__(self, target):
                self.target = target

            def __call__(self, fraction=None, description=None):
                if self.target is None: return
                try:
                    self.target(fraction, description)
                except Exception:
                    self.target = None

            def section(self, start, end, label=None):
                if self.target is None: return SafeExportProgress(None)
                try:
                    return SafeExportProgress(self.target.section(start, end, label=label))
                except Exception:
                    return SafeExportProgress(None)

        def progressSection(start, end, label):
            if progress is None: return None
            return SafeExportProgress(progress).section(start, end, label=label)

        def reportProgress(fraction=None, description=None):
            """A broken display must not change transaction/commit behavior."""
            if progress is None: return
            try:
                progress(fraction, description)
            except Exception:
                pass

        def closeProgress(description):
            if progress is None: return
            try:
                progress.close(description)
            except Exception:
                pass

        def safeWarning(message):
            try:
                pglMessages.warning(message, level=2)
            except Exception:
                pass

        def requireConnection(connection, label):
            if connection is None:
                raise RuntimeError(f"{label} PostgreSQL connection was cancelled.")

        def requireIdentity(connection, postgres, expected, label):
            actual = cls._requireStableDatabaseIdentity(connection, postgres)
            if actual != expected:
                raise ValueError(f"{label} database UUID changed or differs from expected identity.")
            return actual

        def requireUnchangedBinding():
            if cls._getBoundCheckpointReference(session) != sourceReference:
                raise ValueError("Session saved-checkpoint binding changed during export.")

        try:
            try:
                progress = pglProgress("Exporting saved session")
            except Exception:
                # Display construction is optional; export safety is not.
                progress = None
            reportProgress(None, "Resolving explicit export configurations")
            if destinationStorageOptions is not None and type(destinationStorageOptions) is not dict:
                raise TypeError("destinationStorageOptions must be a dictionary or None.")
            if sourceStorageOptionsByBackend is not None and type(sourceStorageOptionsByBackend) is not dict:
                raise TypeError("sourceStorageOptionsByBackend must be a dictionary or None.")

            configuration = cls._resolveSessionExportConfiguration(
                session, databaseName,
                lockTimeoutSeconds=lockTimeoutSeconds,
                ioTimeoutSeconds=ioTimeoutSeconds,
                connectTimeoutSeconds=connectTimeoutSeconds,
            )
            sourceReference = deepcopy(configuration["sourceReference"])
            sourcePostgres = configuration["sourcePostgres"]
            destinationPostgres = configuration["destinationPostgres"]
            sourceDatabaseID = sourceReference["databaseID"]
            sessionID = sourceReference["sessionID"]
            outcome["sourceReference"] = deepcopy(sourceReference)

            pglMessages.message(
                f"Exporting saved checkpoint {sessionID} to profile {databaseName!r}. "
                "Unsaved working edits are not included; the working session remains bound to its source."
            )

            outcome["phase"] = "openingSource"
            reportProgress(None, 'Opening source database')
            with sourcePostgres.connect(sslRootCert=sourceSSLRootCert) as sourceConnection:
                requireConnection(sourceConnection, "Source")
                with sourceConnection.transaction():
                    sourceConnection.execute(
                        "SET TRANSACTION ISOLATION LEVEL REPEATABLE READ, READ ONLY"
                    )
                    requireIdentity(
                        sourceConnection, sourcePostgres, sourceDatabaseID, "Source",
                    )

                    outcome["phase"] = "inspectingDestination"
                    reportProgress(None, 'Inspecting destination and checking existing export')
                    with destinationPostgres.connect(
                        sslRootCert=destinationSSLRootCert,
                    ) as decisionConnection:
                        requireConnection(decisionConnection, "Destination decision")
                        with decisionConnection.transaction():
                            decisionConnection.execute(
                                "SET TRANSACTION ISOLATION LEVEL REPEATABLE READ, READ ONLY"
                            )
                            destinationDatabaseID = cls._requireStableDatabaseIdentity(
                                decisionConnection, destinationPostgres,
                            )
                            if destinationDatabaseID == sourceDatabaseID:
                                raise ValueError("Export requires different source/destination database UUIDs.")
                            outcome["destinationDatabaseID"] = destinationDatabaseID
                            # Choose the display range from a cheap catalog-only
                            # inspection in this same consistent SQL snapshot.
                            # Actual mapping/evidence/payload verification still
                            # belongs to the normal decision helper below.
                            progressInspection = cls._inspectCheckpointReference(
                                decisionConnection, destinationPostgres, sourceReference,
                            )
                            decisionProgressEnd = (
                                0.99 if progressInspection["state"] == "candidate"
                                else 0.15
                            )
                            decision = cls._inspectSessionExportDecision(
                                sourceConnection, sourcePostgres,
                                decisionConnection, destinationPostgres, sessionID,
                                sourceDatabaseName=sourceReference["databaseName"],
                                sourceStorageOptionsByBackend=sourceStorageOptionsByBackend,
                                # Existing export locations may span backends;
                                # the simple API uses their configured access defaults.
                                destinationStorageOptionsByBackend=None,
                                progress=progressSection(0.02, decisionProgressEnd, "Inspecting export"),
                            )

                    if (
                        decision["sourceReference"]["databaseID"] != sourceDatabaseID
                        or decision["sourceReference"]["sessionID"] != sessionID
                        or decision["destinationDatabaseID"] != destinationDatabaseID
                    ):
                        raise ValueError("Export decision returned inconsistent database/checkpoint identities.")

                    if decision["state"] in ("verifiedExistingExport", "conflict"):
                        requireUnchangedBinding()
                        finalState = decision["state"]
                        operationResult = {"decision": decision}
                        if finalState == "conflict":
                            conflicts = decision.get("conflicts", {})
                            summary = ", ".join(
                                f"{name}: {len(records)}"
                                for name, records in conflicts.items() if records
                            )
                            safeWarning(
                                "Export blocked by destination catalog conflicts. "
                                + (summary + ". " if summary else "")
                                + "No new payloads or checkpoint records were created. "
                                "Review the returned decision; automatic merging and overwrite are not supported."
                            )
                        else:
                            reportProgress(None, "Existing export verified; no new publication")
                    elif decision["state"] == "newExportCandidate":
                        if not destinationPostgres.storageLocations:
                            raise ValueError("New export requires a configured destination storage location.")

                        outcome["phase"] = "awaitingConfirmation"
                        reportProgress(None, 'Awaiting confirmation; no publication lock held')
                        outcome["confirmationRequested"] = True
                        approved = cls._confirmSessionExportPlan(
                            decision, destinationProfileName=databaseName,
                        )
                        if approved is not True:
                            requireUnchangedBinding()
                            finalState = "cancelled"
                            operationResult = {"decision": decision}
                        else:
                            outcome["confirmationAccepted"] = True
                            outcome["phase"] = "openingPublication"
                            reportProgress(None, 'Opening destination publication connection')
                            with destinationPostgres.connect(
                                sslRootCert=destinationSSLRootCert,
                            ) as publicationConnection:
                                requireConnection(publicationConnection, "Destination publication")
                                with publicationConnection.transaction():
                                    publicationConnection.execute(
                                        "SET TRANSACTION ISOLATION LEVEL READ COMMITTED, READ WRITE"
                                    )
                                    requireIdentity(
                                        publicationConnection, destinationPostgres,
                                        destinationDatabaseID, "Destination",
                                    )
                                    outcome["phase"] = "acquiringPublicationLock"
                                    reportProgress(None, 'Waiting for destination publication lock')
                                    cls._acquireCheckpointPublicationLock(
                                        publicationConnection, destinationPostgres,
                                        progress=progressSection(0.15, 0.15, "Waiting for publication lock"),
                                    )

                                    # This helper may insert a backend. Keep that
                                    # insertion in the same transaction as publication.
                                    backendID = cls._getConfiguredStorageBackend(
                                        publicationConnection, destinationPostgres,
                                        storageOptions=destinationStorageOptions,
                                    )
                                    outcome["destinationBackendID"] = backendID
                                    backends = sql.Identifier(
                                        destinationPostgres.databaseSchema, "storage_backends",
                                    )
                                    backend = publicationConnection.execute(
                                        sql.SQL(
                                            "SELECT url_prefix, is_active FROM {} "
                                            "WHERE backend_id = %s FOR SHARE"
                                        ).format(backends),
                                        (backendID,),
                                    ).fetchone()
                                    if backend is None or backend[1] is not True:
                                        raise ValueError("Configured export backend is absent or inactive.")

                                    runtimeOptions = {
                                        backendID: dict(destinationStorageOptions or {})
                                    }
                                    objectPrefix = f"export-{uuid4()}"
                                    outcome["preparationObjectPrefix"] = objectPrefix

                                    with pglDatabaseAccess(
                                        destinationPostgres, runtimeOptions,
                                    ) as destinationAccess:
                                        filesystem, root = destinationAccess.resolve(
                                            backendID, backend[0],
                                        )
                                        outcome["phase"] = "preparingPayloads"
                                        reportProgress(None, 'Inventorying, copying, and verifying saved payloads')
                                        outcome["preparationStarted"] = True
                                        preparation = cls._prepareSessionExportPayloads(
                                            sourceConnection, sourcePostgres, sessionID,
                                            posixpath.join(root, objectPrefix),
                                            expectedSourceDatabaseID=sourceDatabaseID,
                                            sourceStorageOptionsByBackend=sourceStorageOptionsByBackend,
                                            destinationFilesystem=filesystem,
                                            progress=progressSection(0.15, 0.60, "Preparing export payloads"),
                                        )

                                        # Preparation paths are relative to its new
                                        # directory. Registration paths are relative
                                        # to the backend root, so prefix them once.
                                        prepared = deepcopy(preparation["preparedCheckpoints"])
                                        for item in prepared:
                                            item["objectPrefix"] = posixpath.join(
                                                objectPrefix, item["objectPrefix"],
                                            )
                                        matrixObjectKeys = {
                                            revisionID: posixpath.join(objectPrefix, key)
                                            for revisionID, key in preparation["matrixObjectKeys"].items()
                                        }

                                        requireUnchangedBinding()
                                        outcome["phase"] = "publishingPreparedExport"
                                        reportProgress(None, 'Registering checkpoints, matrices, evidence, and mappings')
                                        createdBy = cls.getOrCreateUser(
                                            publicationConnection, destinationPostgres,
                                            configuration["username"],
                                        )
                                        publication = cls._registerPreparedSessionExport(
                                            publicationConnection, destinationPostgres,
                                            sourceDatabaseID=sourceDatabaseID,
                                            sourceDatabaseName=sourceReference["databaseName"],
                                            expectedDestinationDatabaseID=destinationDatabaseID,
                                            preparedCheckpoints=prepared,
                                            matrixObjectKeys=matrixObjectKeys,
                                            createdBy=createdBy, backendID=backendID,
                                            savedTimezone="UTC",
                                            accessContext=destinationAccess,
                                            storageOptionsByBackend=runtimeOptions,
                                            **({"progress": progressSection(0.60, 0.85, "Publishing and verifying export")} if progress is not None else {}),
                                        )
                                        outcome["sessionIDMapping"] = deepcopy(
                                            publication["sessionIDMapping"]
                                        )
                                        requireUnchangedBinding()
                                        outcome["phase"] = "closingPublicationPayloadAccess"
                                        reportProgress(None, 'Closing publication payload access before commit')

                                    # Never set attempted before payload-access exit.
                                    outcome["phase"] = "committingDestination"
                                    reportProgress(None, 'Committing destination publication')
                                    outcome["commitAttempted"] = True
                                outcome["commitConfirmed"] = True
                                outcome["phase"] = "closingPublicationConnection"
                                reportProgress(None, 'Closing committed publication connection')

                            # A fresh connection must see the committed rows.
                            outcome["phase"] = "verifyingCommittedExport"
                            reportProgress(None, 'Independently verifying committed export and current source')
                            with destinationPostgres.connect(
                                sslRootCert=destinationSSLRootCert,
                            ) as verificationConnection:
                                requireConnection(verificationConnection, "Post-commit verification")
                                with verificationConnection.transaction():
                                    verificationConnection.execute(
                                        "SET TRANSACTION ISOLATION LEVEL REPEATABLE READ, READ ONLY"
                                    )
                                    requireIdentity(
                                        verificationConnection, destinationPostgres,
                                        destinationDatabaseID, "Post-commit destination",
                                    )
                                    reconciliation = cls._inspectExistingSessionExport(
                                        verificationConnection, destinationPostgres,
                                        sourceReference,
                                        storageOptionsByBackend=runtimeOptions,
                                        progress=progressSection(0.85, 0.93, "Verifying committed destination"),
                                    )
                                    if reconciliation["state"] != "verifiedExistingExport":
                                        raise ValueError("Committed export did not reconcile.")
                                    observedMapping = {
                                        item["sourceSessionID"]: item["destinationSessionID"]
                                        for item in reconciliation["checkpoints"]
                                    }
                                    if observedMapping != publication["sessionIDMapping"]:
                                        raise ValueError("Post-commit mapping differs from the published allocation.")
                                    for item in reconciliation["checkpoints"]:
                                        sourceID = item["sourceSessionID"]
                                        observedEvidence = item["mappingBinding"]["evidence"]
                                        expectedEvidence = publication["evidenceBySourceSessionID"][sourceID]
                                        if pglStorage.encodeJSON(observedEvidence) != pglStorage.encodeJSON(expectedEvidence):
                                            raise ValueError("Post-commit mapping evidence differs from publication.")

                                    sourceVerification = cls._verifyExportCurrentSource(
                                        sourceConnection, sourcePostgres, reconciliation,
                                        storageOptionsByBackend=sourceStorageOptionsByBackend,
                                        progress=progressSection(0.93, 0.99, "Rechecking source"),
                                    )
                                    if (
                                        sourceVerification["state"] != "sourceMatchesRecordedExport"
                                        or sourceVerification["sourceDatabaseID"] != sourceDatabaseID
                                        or sourceVerification["destinationDatabaseID"] != destinationDatabaseID
                                    ):
                                        raise ValueError("Post-commit source correspondence is inconsistent.")
                            outcome["postCommitVerificationPassed"] = True
                            finalState = "exported"
                            operationResult = {
                                "sessionIDMapping": deepcopy(publication["sessionIDMapping"]),
                                "destinationSessionID": publication["sessionIDMapping"][sessionID],
                                "verificationScope": [
                                    item["sourceSessionID"] for item in reconciliation["checkpoints"]
                                ],
                            }
                    else:
                        raise ValueError("Unsupported export decision state.")

                    outcome["phase"] = "closingSourceSnapshot"
                    reportProgress(None, 'Closing source inspection transaction')
                outcome["phase"] = "closingSourceConnection"
                reportProgress(None, 'Closing source connection')

            outcome["phase"] = "complete"
            outcome["state"] = finalState
            if finalState in ("exported", "verifiedExistingExport"):
                if progress is not None:
                    try:
                        progress.finish(
                            "Export committed and verified" if finalState == "exported"
                            else "Existing export verified; no new writes"
                        )
                    except Exception:
                        pass
            elif finalState == "cancelled":
                reportProgress(None, "Export cancelled; no destination publication attempted")
                closeProgress("Cancelled")
            else:
                reportProgress(None, "Export blocked; inspect returned conflicts")
                closeProgress("Blocked")
            return {**deepcopy(outcome), **operationResult}

        except BaseException as error:
            outcome["state"] = (
                "committedButOperationFailed" if outcome["commitConfirmed"]
                else "commitOutcomeUnconfirmed" if outcome["commitAttempted"]
                else "failedBeforeCommit"
            )
            # Retain original error category/traceback. Configuration dictionaries,
            # passwords, signed access URLs, and storage options are excluded.
            try:
                error.exportOutcome = deepcopy(outcome)
            except Exception:
                pass
            try:
                error.add_note(
                    "PGL export outcome: "
                    f"{outcome['state']}; phase={outcome['phase']}; "
                    f"commitAttempted={outcome['commitAttempted']}; "
                    f"commitConfirmed={outcome['commitConfirmed']}; "
                    f"postCommitVerificationPassed={outcome['postCommitVerificationPassed']}. "
                    "Prepared payloads are retained. No automatic retry or cleanup occurred."
                )
            except Exception:
                pass
            try:
                cls._warnSessionExportFailure(error, outcome)
            except Exception:
                # Reporting must never replace the original export exception.
                pass
            closeProgress("Interrupted" if isinstance(error, KeyboardInterrupt) else "Failed")
            raise

        finally:
            closeProgress(None)

    # -------------------------------------------------------------------------
    # Lifecycle exception types
    # -------------------------------------------------------------------------
    # Internal refusal categories translated into user-facing warnings by lifecycle wrappers.

    # ++++++++++++++++++++++++ _UnknownLifecycleSession +++++++++++++++++++++++
    class _UnknownLifecycleSession(ValueError):
        """Requested lifecycle session does not exist."""

    # ++++++++++++++++++++++++ _SessionLifecycleBlocked +++++++++++++++++++++++
    class _SessionLifecycleBlocked(ValueError):
        """Lifecycle operation was refused without making changes."""
        
    @classmethod
    def _handleCheckpointSaveFailure(cls, error, *, checkpointKind, checkpointID, operation, commitAttempted, commitConfirmed):
        """Warn for recognized operational failures after resource cleanup.

        Returns True when handled, False when the caller should re-raise.
        Does not retry, connect for diagnostics, terminate sessions, or delete
        payloads. Avoids exposing backend exception text or signed URLs.

        Authentication/host-key failures, integrity failures, and programming
        errors are not intentionally suppressed.
        """
        from paramiko import SSHException
        from paramiko.ssh_exception import AuthenticationException, BadHostKeyException

        lockFailure = False

        if isinstance(error, (AuthenticationException, BadHostKeyException)):
            return False

        if isinstance(error, psycopg.errors.LockNotAvailable):
            reason = "a required PostgreSQL lock could not be acquired"
            lockFailure = True
        elif isinstance(error, TimeoutError):
            reason = "a lock wait, connection attempt, or I/O operation timed out"
            lockFailure = True
        elif isinstance(error, SSHException):
            message = str(error).strip().lower()
            dropped = message.startswith("server connection dropped:") or message in {
                "socket is closed",
                "socket is closed.",
                "server connection dropped",
                "ssh session not active",
                "no existing session",
            }

            if not dropped:
                return False

            reason = "the SSH/SFTP connection was lost"
        elif isinstance(error, (psycopg.OperationalError, psycopg.InterfaceError)):
            # Explicit authentication/authorization failures remain visible.
            if getattr(error, "sqlstate", None) in {"28000", "28P01", "42501"}:
                return False

            reason = "a PostgreSQL connection or operational failure occurred"
        elif isinstance(error, ConnectionError):
            reason = "a network connection failed"
        else:
            return False

        label = checkpointKind if checkpointID is None else f"{checkpointKind} {checkpointID}"

        if commitConfirmed:
            outcome = (
                f"The transaction for {label} committed, but subsequent cleanup failed. "
                "The committed checkpoint was not rolled back. "
                "The working object's checkpoint bookkeeping was not updated."
            )
        elif commitAttempted:
            outcome = (
                f"The failure occurred during commit for {label}. "
                "The outcome is not confirmed by this client; the checkpoint may "
                "already have been saved. Inspect the database before retrying."
            )
        else:
            outcome = (
                "The final checkpoint commit was not attempted. "
                "Transaction and connection cleanup were attempted. "
                "If PostgreSQL is unreachable, its transaction and locks may remain "
                "until the server detects the disconnected client."
            )

        inspection = (
            "Run pglDatabase.inspectPostgresLocks() with the same settings to inspect "
            "current lock-related sessions. For table-lock blockers, inspect live "
            "activity while the wait is occurring; a timed-out waiter may already "
            "have disappeared. Idle database state does not prove abandonment."
            if lockFailure else
            "Restore VPN/network access and check pglDatabase.inspectPostgres() "
            "with the same settings before retrying."
        )

        report = "pglDatabase.print(datasets=True)" if checkpointKind == "Dataset checkpoint" else "pglDatabase.print()"

        pglMessages.warning(
            f"{checkpointKind} save stopped while {operation}: {reason} ({type(error).__name__}).\n"
            f"{outcome}\n"
            f"{inspection}\n"
            f"Inspect saved checkpoints with {report}. "
            "Partial or unregistered files/matrix bundles may remain. "
            "No automatic retry, connection termination, or payload deletion occurred.",
            level=2,
        )
        return True
    
    @classmethod
    def saveRawMRISessionFiles(cls, session, dataPath, *, filesystem=None):
        """Export a raw MRI session directly into a fresh destination.

        Streams original MRI payloads and optional saved behavioral acquisition
        files. Writes verified history and a raw v2 manifest last.

        Does not export edited MRI data, derived matrices, or derived files.
        Working contents and metadata remain unchanged.

        Returns (destination, manifest), or None for expected input refusals.
        Storage, source-integrity, and serialization failures propagate.
        Failed exports may leave partial destination files.

        Does not register SQL rows or complete a database checkpoint.
        """
        import os
        from pathlib import Path

        from fsspec import AbstractFileSystem
        from fsspec.core import url_to_fs
        from fsspec.implementations.local import LocalFileSystem

        from .pglMRI import pglMRI
        from .pglSession import pglSession

        if type(session) is not pglSession:
            pglMessages.warning("Raw MRI export requires a pglSession.", level=0)
            return None

        if type(session.mri) is not pglMRI or not session.mri.scans:
            pglMessages.warning("Raw MRI session was not exported: no supported MRI scans are attached.", level=0)
            return None

        if session.mne is not None:
            pglMessages.warning("Raw MRI session was not exported: combined MRI/MNE checkpoints are unsupported.", level=0)
            return None

        try:
            pathText = os.fspath(dataPath)
            if not isinstance(pathText, str) or not pathText.strip():
                raise ValueError("dataPath must be a nonempty path.")
            if any(character in pathText for character in ("\x00", "\n", "\r")):
                raise ValueError("dataPath must not contain NUL or newlines.")
            if filesystem is not None and not isinstance(filesystem, AbstractFileSystem):
                raise TypeError("filesystem must be an fsspec filesystem.")

        except (TypeError, ValueError) as error:
            pglMessages.warning(f"Raw MRI session was not exported: {error}", level=0)
            return None

        if filesystem is None:
            filesystem, destination = url_to_fs(pathText)
        else:
            destination = filesystem._strip_protocol(pathText)

        destinationExists = filesystem.exists(destination)
        if isinstance(filesystem, LocalFileSystem):
            destinationExists = destinationExists or os.path.lexists(destination)

        if destinationExists:
            pglMessages.warning(
                "Raw MRI session was not exported: destination already exists. "
                "Nothing was overwritten.",
                level=0,
            )
            return None

        runs = list(session.runs or [])
        mri = session.mri

        # Prevent export into a behavioral source tree: doing so would change
        # its inventory while we are copying it.
        for run in runs:
            if run.filesystem is None:
                raise ValueError("Behavioral acquisition source has no filesystem.")

            if isinstance(filesystem, LocalFileSystem) and isinstance(run.filesystem, LocalFileSystem):
                target = Path(destination).expanduser().resolve()
                source = Path(run.fullDataPath).expanduser().resolve()
                if target == source or source in target.parents:
                    raise ValueError("Export destination must be outside behavioral source directories.")

            elif filesystem is run.filesystem:
                target = posixpath.normpath(destination)
                source = posixpath.normpath(run.fullDataPath)
                if target == source or target.startswith(source.rstrip("/") + "/"):
                    raise ValueError("Export destination must be outside behavioral source directories.")

        # Inventory unchanged acquisition sources, not edited in-memory runs.
        behavior = pglSession()
        behavior.runs = runs
        behaviorManifest = cls.buildRawManifest(behavior) if runs else None

        # This also enforces the existing working-session save-safety check.
        historyBytes = cls._sessionHistoryBytes(session, acquisition=True)

        if session.dataMatrices or session.derivedFiles:
            pglMessages.warning(
                "Raw MRI export includes acquisition contents only. "
                "Derived matrices/files are omitted; working attachments are unchanged.",
                level=0,
            )

        filesystem.makedirs(destination, exist_ok=False)
        directories = set()
        files = []

        if behaviorManifest is not None:
            directories.update(behaviorManifest["directories"])

            for directory in sorted(directories):
                filesystem.makedirs(posixpath.join(destination, directory), exist_ok=True)

            for record in behaviorManifest["files"]:
                parts = record["name"].split("/", 2)
                run = runs[int(parts[1])]
                pglStorage.copyVerifiedFile(
                    run.filesystem,
                    posixpath.join(run.fullDataPath, parts[2]),
                    filesystem,
                    destination,
                    record,
                    objectKey=record["name"],
                )
                files.append(dict(record))

        # The acquisition writer streams each original source directly to
        # this destination and extracts headers from the exported bytes.
        mriRoot = posixpath.join(destination, "mri")
        if mri.saveAcquisitionBundle(mriRoot, filesystem=filesystem) is None:
            raise RuntimeError("MRI bundle export was refused; raw session export is incomplete.")

        directories.add("mri")
        for current, directoryNames, fileNames in filesystem.walk(mriRoot, detail=False, on_error="raise"):
            relative = posixpath.relpath(current, destination)

            for name in directoryNames:
                directories.add(posixpath.join(relative, name))

            for name in fileNames:
                path = posixpath.join(current, name)
                files.append({
                    "name": posixpath.join(relative, name),
                    **pglStorage.hashFile(filesystem, path),
                })

        # Recheck behavioral sources and history before publishing metadata.
        # Concurrent working-session/source mutation is unsupported.
        if behaviorManifest is not None and cls.buildRawManifest(behavior) != behaviorManifest:
            raise ValueError("Behavioral acquisition changed during export.")

        currentRuns = list(session.runs or [])
        if (
            session.mri is not mri
            or session.mne is not None
            or len(currentRuns) != len(runs)
            or any(current is not original for current, original in zip(currentRuns, runs))
        ):
            raise ValueError("Session contents changed during export.")

        if cls._sessionHistoryBytes(session, acquisition=True) != historyBytes:
            raise ValueError("Session history or labels changed during export.")

        def writeVerified(name, content):
            """Write new metadata bytes and verify the stored identity."""
            path = posixpath.join(destination, name)
            expected = {
                "sha256": hashlib.sha256(content).hexdigest(),
                "size_bytes": len(content),
            }

            with filesystem.open(path, "xb") as target:
                if target.write(content) != len(content):
                    raise OSError(f"Incomplete metadata write: {name}")

            if pglStorage.hashFile(filesystem, path) != expected:
                raise ValueError(f"Metadata verification failed: {name}")

            return {"name": name, **expected}

        files.append(writeVerified("history.json", historyBytes))

        manifest = {
            "contract_version": "pgl.raw.session.v2",
            "runs": deepcopy(behaviorManifest["runs"]) if behaviorManifest else [],
            "mri": {"path": "mri"},
            "directories": sorted(directories),
            "files": sorted(files, key=lambda record: record["name"]),
        }
        cls.validateRawSessionManifest(manifest)

        class DestinationView:
            """Expose the export's logical paths without changing its files."""
            def open(self, path, mode="rb", **kwargs):
                return filesystem.open(posixpath.join(destination, path), mode=mode, **kwargs)

        view = DestinationView()
        cls._verifyMRIInventory(manifest, view)
        _, labels = cls._readSessionHistory(view, len(runs))

        if runs and labels != cls._behaviorLabelMetadata(manifest, view):
            raise ValueError("Raw session labels differ from exported behavioral acquisition settings.")

        # Completion marker is last. Its own identity is not embedded inside it.
        writeVerified("manifest.json", cls.encodeRawManifest(manifest))
        pglMessages.message("Raw MRI session export complete; not registered in PostgreSQL.")
        return destination, manifest
    
    @classmethod
    def _saveRawMRICheckpoint(cls, connection, postgres, session, createdBy, backendID, storageOptions=None, *, progress=None):
        """Publish or reuse a raw MRI checkpoint in the caller's transaction.

        Streams acquisition contents directly into registered destination
        storage using saveRawMRISessionFiles(). No complete local staging
        copy is required.

        Supports MRI-only and MRI with behavioral acquisition sources.
        Does not save edited MRI data or derived attachments.

        Uses a nested transaction/savepoint. The public coordinator owns
        final commit, connection cleanup, and working-session identity updates.

        Duplicate identity is known only after export. Active matching
        checkpoints are verified and reused. The provisional catalog row is
        rolled back, but exported files remain unregistered for inspection.
        Matching deleted checkpoints remain deleted.

        Storage writes are not transactional. Failures may leave partial or
        unregistered files. Never automatically deletes payload directories.

        Does not modify session.sessionID, history, or annotations.
        """
        from tempfile import TemporaryDirectory

        from .pglMRI import pglMRI

        for label, value in (("createdBy", createdBy), ("backendID", backendID)):
            if type(value) is not int or not 0 <= value <= 9223372036854775807:
                raise ValueError(f"{label} must be a nonnegative PostgreSQL bigint.")

        if storageOptions is not None and not isinstance(storageOptions, dict):
            raise TypeError("storageOptions must be a dictionary or None.")

        if type(session.mri) is not pglMRI or not session.mri.scans:
            raise ValueError("Raw MRI publication requires a nonempty pglMRI collection.")

        if session.mne is not None:
            raise ValueError("Combined MRI/MNE checkpoints are unsupported.")

        pglStorage.requireSafeSave(session)

        sessions = sql.Identifier(postgres.databaseSchema, "session")
        users = sql.Identifier(postgres.databaseSchema, "users")
        backends = sql.Identifier(postgres.databaseSchema, "storage_backends")

        def report(fraction, description):
            if progress is not None: progress(fraction, description)

        class ReuseCheckpoint(Exception):
            """Exit the savepoint by rollback, retaining the existing ID."""
            def __init__(self, sessionID): self.sessionID = sessionID

        destination = None

        # Own destination access for this operation only. Source filesystems
        # and the Flywheel client remain owned by the working session/caller.
        with pglDatabaseAccess(postgres, {backendID: storageOptions or {}}) as access:
            try:
                with connection.transaction():
                    report(0.05, "Validating MRI checkpoint owner and storage backend")

                    statement = sql.SQL("SELECT 1 FROM {} WHERE user_id = %s FOR SHARE").format(users)
                    if connection.execute(statement, (createdBy,)).fetchone() is None:
                        raise ValueError(f"Unknown creator: {createdBy}")

                    statement = sql.SQL("SELECT url_prefix, is_active FROM {} WHERE backend_id = %s FOR SHARE").format(backends)
                    backend = connection.execute(statement, (backendID,)).fetchone()

                    if backend is None or not backend[1]:
                        raise ValueError("Storage backend is missing or inactive.")

                    report(0.06, "Opening MRI checkpoint destination")
                    destinationFS, destinationRoot = access.resolve(backendID, backend[0])

                    modalities = (["behavior"] if session.runs else []) + ["mri"]

                    # Allocate an unpublished row to obtain its destination ID.
                    # Existing lineage triggers assign this raw row its own root.
                    report(0.07, "Allocating raw MRI checkpoint")
                    statement = sql.SQL("""
                        INSERT INTO {} (
                            origin, kind, ingest_method, modalities, status,
                            contract_version, created_by, started_at
                        )
                        VALUES (
                            'raw', 'acquired', 'manual', %s::text[], 'in_progress',
                            'pgl.raw.session.v2', %s, now()
                        )
                        RETURNING session_id
                    """).format(sessions)

                    sessionID = connection.execute(statement, (modalities, createdBy)).fetchone()[0]
                    objectPrefix = f"session{sessionID:06d}"
                    destination = posixpath.join(destinationRoot, objectPrefix)

                    report(0.08, "Streaming original MRI and behavioral acquisition files")

                    # The tested exporter handles a fresh destination, source
                    # overlap checks, original-byte export, and metadata checks.
                    result = cls.saveRawMRISessionFiles(
                        session,
                        destination,
                        filesystem=destinationFS,
                    )
                    if result is None:
                        raise RuntimeError("Raw MRI export was refused; no checkpoint was completed.")

                    exportedPath, manifest = result
                    if exportedPath != destination:
                        raise ValueError("Raw MRI exporter returned an unexpected destination.")

                    expectedModalities = (["behavior"] if manifest["runs"] else []) + ["mri"]
                    if modalities != expectedModalities:
                        raise ValueError("Exported contents differ from the allocated checkpoint modalities.")

                    manifestHash = cls.hashRawManifest(manifest)

                    report(0.70, "Acquiring raw-checkpoint identity lock")
                    postgres.acquireTransactionLock(
                        connection,
                        manifestHash,
                        description="raw-checkpoint identity",
                        timeoutSeconds=postgres.lockTimeoutSeconds,
                    )

                    # The same identity lock used by existing raw publication
                    # serializes cooperating writers before completion.
                    statement = sql.SQL("""
                        SELECT session_id, status, contract_version
                        FROM {}
                        WHERE origin = 'raw'
                          AND manifest_hash = %s
                          AND deleted_at IS NULL
                        FOR SHARE
                    """).format(sessions)
                    existing = connection.execute(statement, (manifestHash,)).fetchone()

                    if existing is not None:
                        existingID, status, contract = existing
                        if (status, contract) != ("complete", "pgl.raw.session.v2"):
                            raise ValueError("Matching raw manifest belongs to an unsupported or incomplete checkpoint.")

                        report(0.71, f"Verifying existing checkpoint {existingID}")

                        # Verify catalog/manifest/descriptor correspondence.
                        # Restoration is metadata-only; no NIfTI is materialized.
                        inspected = None
                        with TemporaryDirectory(prefix="pgl-mri-duplicate-check-") as temporary:
                            try:
                                inspected = cls.loadRawSessionBundle(
                                    connection,
                                    postgres,
                                    existingID,
                                    storageOptionsByBackend={backendID: storageOptions or {}},
                                    cacheDirectory=temporary,
                                )
                            finally:
                                if inspected is not None:
                                    try:
                                        for matrix in inspected.dataMatrices.values(): matrix.close()
                                    finally:
                                        inspected.filesystem.close()

                        # Roll back the provisional row without issuing DELETE
                        # against an immutable/lifecycle-protected checkpoint.
                        raise ReuseCheckpoint(existingID)

                    statement = sql.SQL("""
                        SELECT session_id
                        FROM {}
                        WHERE origin = 'raw'
                          AND manifest_hash = %s
                          AND deleted_at IS NOT NULL
                        ORDER BY session_id
                        FOR SHARE
                    """).format(sessions)
                    deletedMatches = connection.execute(statement, (manifestHash,)).fetchall()

                    if deletedMatches:
                        deletedIDs = ", ".join(str(row[0]) for row in deletedMatches)
                        pglMessages.message(
                            f"Matching deleted raw checkpoint(s): {deletedIDs}. "
                            "Leaving them deleted and publishing a new checkpoint."
                        )

                    registrationProgress = progress.section(0.72, 0.95) if progress is not None else None
                    cls._registerSessionBundleFiles(
                        connection,
                        postgres,
                        sessionID,
                        backendID,
                        manifest,
                        objectPrefix=objectPrefix,
                        origin="raw",
                        accessContext=access,
                        progress=registrationProgress,
                    )

                    # Preserve existing working-session safety requirements.
                    pglStorage.requireSafeSave(session)

                    report(0.96, "Validating raw MRI checkpoint completion")
                    cls._completeSessionBundleCheckpoint(
                        connection, postgres, sessionID, manifest, origin="raw"
                    )

                report(0.97, "Closing MRI publication payload access")

            except ReuseCheckpoint as reused:
                # The nested transaction has rolled back the provisional row.
                # Files are outside SQL rollback and are intentionally retained.
                sessionID = reused.sessionID
                pglMessages.warning(
                    f"This raw session is already saved as active checkpoint "
                    f"{sessionID}; returning the existing ID. "
                    "The provisional database row was rolled back. "
                    f"Exported files remain unregistered at {destination}. "
                    "No files were automatically deleted.",
                    level=0,
                )
                report(0.97, f"Reusing existing checkpoint {sessionID}")

        # The caller still must commit its outer transaction and finish cleanup.
        return sessionID
    
    # -------------------------------------------------------------------------
    # PostgreSQL server management
    # -------------------------------------------------------------------------

    # +++++++++++++++++++++++++++ postgresStatus ++++++++++++++++++++++++++++++
    @classmethod
    def postgresStatus(cls, postgres=None, *, settings=None, settingsName=None):
        """Display process status for the locally managed PostgreSQL server.

        Uses the default database settings unless another configuration is
        supplied. Does not connect to SQL or request a database password.

        Returns True when running, False when stopped, or None when the
        configuration is unavailable. Inspection errors propagate.

        Local management currently supports macOS/Homebrew only.
        Remote configurations are refused, not interpreted as local servers.
        """
        postgres = cls._printPostgres(postgres, settings=settings, settingsName=settingsName)

        if postgres is None:
            return None

        return postgres.status()

    # ++++++++++++++++++++++++++++ postgresStart ++++++++++++++++++++++++++++++
    # ++++++++++++++++++++++++++++ postgresStart ++++++++++++++++++++++++++++++
    @classmethod
    def postgresStart(cls, postgres=None, *, settings=None, settingsName=None):
        """Start the locally managed PostgreSQL server if stopped.

        Returns True when running/startup succeeds, False for a handled
        startup failure, or None when configuration is unavailable.

        Startup failures warn and display recent server log entries.
        Configuration and inspection errors propagate.
        """
        postgres = cls._printPostgres(postgres, settings=settings, settingsName=settingsName)

        if postgres is None:
            return None

        return postgres.start()
    
    # +++++++++++++++++++++++ _isPostgresUnavailable ++++++++++++++++++++++++++
    @staticmethod
    def _isPostgresUnavailable(error):
        """Identify operational availability failures, not arbitrary SQL errors.

        Authentication and TLS-policy failures remain visible exceptions.
        Does not infer that an unreachable server is necessarily stopped.
        """
        if not isinstance(error, psycopg.OperationalError):
            return False

        message = str(error).lower()

        # Some connection failures have no SQLSTATE. Preserve recognizable
        # authentication/security errors rather than suggesting a restart.
        securityMessages = (
            "password authentication failed",
            "no password supplied",
            "no pg_hba.conf entry",
            "certificate",
            "ssl error",
            "tls error",
            "does not support ssl",
            "ssl is required",
            "authentication method",
        )

        if any(text in message for text in securityMessages):
            return False

        sqlState = error.sqlstate

        if sqlState is None:
            # libpq commonly supplies no SQLSTATE for refused connections,
            # DNS/socket failures, connection timeouts, and connection loss.
            return True

        return sqlState.startswith("08") or sqlState in {
            "57P01",  # Administrator shutdown.
            "57P02",  # Crash shutdown.
            "57P03",  # Cannot connect now, e.g. startup/recovery.
            "53300",  # Too many connections.
        }

    # +++++++++++++++++++++++ _warnPostgresUnavailable ++++++++++++++++++++++++
    @classmethod
    def _warnPostgresUnavailable(cls, error, *, operation, postgres=None, settings=None, settingsName=None):
        """Explain an availability failure without reconnecting or retrying.

        Retains configuration selection in suggested commands.
        Does not resolve settings again, prompt, or administer the server.
        """
        if postgres is not None:
            arguments = "postgres=postgres"
            selectionNote = (
                "\nIn the commands below, postgres means the same configuration "
                "object supplied to the failed operation."
            )
        elif settings is not None:
            arguments = "settings=settings"
            selectionNote = (
                "\nIn the commands below, settings means the same settings "
                "object supplied to the failed operation."
            )
        elif settingsName is not None:
            arguments = f"settingsName={settingsName!r}"
            selectionNote = ""
        else:
            arguments = ""
            selectionNote = ""

        endpoint = (
            f" at {postgres.connectionHost}:{postgres.connectionPort}"
            if postgres is not None else ""
        )

        knownRemote = postgres is not None and (
            getattr(postgres, "_configurationLoadedRemotely", False)
            or postgres.connectionTransport != "direct"
            or postgres.connectionHost != postgres.postgresHost
            or postgres.connectionPort != postgres.postgresPort
        )

        if knownRemote:
            instructions = (
                "Check SSH/VPN/network access and the configured database endpoint. "
                "Inspect or start PostgreSQL on its installation machine using "
                "that machine's local server configuration. "
                "Do not start an unrelated server on this client."
            )
        else:
            localQualifier = "For a locally managed database, " if postgres is None else ""
            instructions = (
                f"{localQualifier}inspect the server with:\n"
                f"    pglDatabase.postgresStatus({arguments})\n"
                "If it is stopped, start it with:\n"
                f"    pglDatabase.postgresStart({arguments})\n"
                "If it is already running, inspect its server log and connection "
                "settings before considering a restart."
            )

            if postgres is None:
                instructions += (
                    "\nFor a remote database, check SSH/VPN/network access and "
                    "inspect the server on its installation machine instead."
                )

        pglMessages.warning(
            f"Could not complete {operation}: PostgreSQL is unavailable{endpoint}.\n"
            "The server may be stopped, starting, overloaded, or unreachable; "
            "this error alone does not establish which.\n"
            f"{instructions}{selectionNote}\n"
            "No automatic start, restart, or retry was performed.",
            level=2,
        )
        
    ################################################################
    # Validate a derived MRI session checkpoint inventory
    ################################################################
    @classmethod
    def _validateDerivedMRIV2Manifest(cls, manifest):
        """Validate MRI-v2 inventories with explicit matrix ownership.

        Contract:
            pgl.derived.mri.v2

        Preserves the MRI-v1 acquisition, behavioral, history, and derived-file
        inventory layout. Changes only the matrix-reference representation:

            name: Canonical catalog key.
            owner: "session" or "mri".
            localName: Attachment name within that owner.
            matrixRevisionID: Published matrix revision UUID.

        Original acquisition payloads remain acquisitions. MRI matrices are
        published separately through the existing Zarr revision system.

        The inner MRI acquisition/annotation descriptor remains
        pgl.mri.derived.v1. Matrix ownership belongs to this outer checkpoint.

        Reuses the complete MRI-v1 inventory validator through a temporary
        catalog-only view. Does not weaken its path, identity, attachment,
        history, or modality checks.

        Does not mutate the manifest, read payloads, query SQL, or establish
        scientific validity or current-image-stage selection.
        """
        expectedFields = {
            "contract_version", "runs", "mri", "directories",
            "files", "products", "derivedFiles",
        }

        if type(manifest) is not dict or set(manifest) != expectedFields:
            raise ValueError("Derived MRI-v2 manifest has missing or unexpected fields.")
        if manifest["contract_version"] != "pgl.derived.mri.v2":
            raise ValueError("Expected the derived MRI-v2 checkpoint contract.")

        # Ownership is validated before projecting records into catalog links.
        # The original records, including owner/localName, remain unchanged.
        catalogRecords = cls._matrixCatalogRecords(manifest["products"], owned=True)

        inventoryView = {
            **manifest,
            "contract_version": "pgl.derived.mri.v1",
            "products": catalogRecords,
        }

        # The existing validator does not mutate its input. Reusing it avoids
        # maintaining two copies of the complete acquisition/file checks.
        cls._validateDerivedMRIManifest(inventoryView)
        return manifest

    @classmethod
    def _validateDerivedMRIManifest(cls, manifest):
        """Validate derived MRI inventories without reading payload files.

        Contract:
            pgl.derived.mri.v1

        Contains:
            MRI acquisition sources and current scan annotations.
            Optional current behavioral runs.
            Explicit matrix-product references.
            Explicit derived-file attachments.
            Session history and associated metadata.

        Corrected images are derived attachments, not replacement acquisitions.
        Combined MRI/MNE checkpoints remain unsupported.

        Validates complete inventory structure before separating attachments.
        Does not mutate the manifest or verify scientific payload bytes.
        """
        import posixpath
        import re

        expectedFields = {
            "contract_version", "runs", "mri", "directories",
            "files", "products", "derivedFiles",
        }
        if type(manifest) is not dict or set(manifest) != expectedFields:
            raise ValueError("Derived MRI manifest has missing or unexpected fields.")
        if manifest["contract_version"] != "pgl.derived.mri.v1":
            raise ValueError("Unsupported derived MRI checkpoint contract.")
        if manifest["mri"] != {"path": "mri"}:
            raise ValueError("Derived MRI bundle path must be 'mri'.")

        for field in ("runs", "directories", "files", "derivedFiles"):
            if type(manifest[field]) is not list:
                raise ValueError(f"Manifest {field} must be a list.")

        cls._validateSessionProductRecords(manifest["products"])

        def validatePath(path):
            if (
                not isinstance(path, str) or not path
                or path.startswith("/") or "\\" in path or "\x00" in path
                or any(part in ("", ".", "..") for part in path.split("/"))
            ):
                raise ValueError(f"Invalid checkpoint path: {path!r}")

        ################################################################
        # Validate the complete inventory before removing any entries
        ################################################################
        directories = manifest["directories"]
        for path in directories: validatePath(path)
        if directories != sorted(set(directories)):
            raise ValueError("Manifest directories must be unique and sorted.")

        fileNames = []

        for record in manifest["files"]:
            if type(record) is not dict or set(record) != {"name", "sha256", "size_bytes"}:
                raise ValueError("Invalid checkpoint file record.")

            validatePath(record["name"])
            if not isinstance(record["sha256"], str) or re.fullmatch(r"[0-9a-f]{64}", record["sha256"]) is None:
                raise ValueError("Invalid checkpoint file SHA-256.")
            if type(record["size_bytes"]) is not int or not 0 <= record["size_bytes"] <= 9223372036854775807:
                raise ValueError("Invalid checkpoint file size.")

            fileNames.append(record["name"])

        if fileNames != sorted(set(fileNames)):
            raise ValueError("Manifest filenames must be unique and sorted.")

        directorySet, fileSet = set(directories), set(fileNames)
        if directorySet.intersection(fileSet):
            raise ValueError("A checkpoint path cannot be both a file and a directory.")

        for path in directories + fileNames:
            parent = posixpath.dirname(path)
            if parent and parent not in directorySet:
                raise ValueError(f"Missing checkpoint parent directory for {path!r}.")

        ################################################################
        # Validate explicitly declared derived attachments
        ################################################################
        attachments = manifest["derivedFiles"]
        attachmentNames = []
        expectedPayloads = set()
        expectedDirectories = {"derived"} if attachments else set()

        for index, attachment in enumerate(attachments):
            if type(attachment) is not dict or set(attachment) != {
                "name", "runIndex", "filename", "mediaType", "path",
            }:
                raise ValueError("Invalid derived-file descriptor.")

            name = attachment["name"]
            if not isinstance(name, str) or not name.strip():
                raise ValueError("Derived-file names must be nonblank strings.")
            if any(character in name for character in ("\x00", "\n", "\r")):
                raise ValueError("Invalid derived-file name.")
            attachmentNames.append(name)

            runIndex = attachment["runIndex"]
            if runIndex is not None:
                if type(runIndex) is not int or not 0 <= runIndex < len(manifest["runs"]):
                    raise ValueError("Invalid derived-file behavioral run index.")

            filename = attachment["filename"]
            if (
                not isinstance(filename, str) or not filename.strip()
                or filename in (".", "..")
                or any(character in filename for character in ("/", "\\", "\x00", "\n", "\r"))
            ):
                raise ValueError("Derived filename must be one safe filename.")

            mediaType = attachment["mediaType"]
            if not isinstance(mediaType, str) or not mediaType.strip():
                raise ValueError("Derived-file mediaType must be a nonblank string.")
            if any(character in mediaType for character in ("\x00", "\n", "\r")):
                raise ValueError("Invalid derived-file mediaType.")

            # Preserve the existing deterministic attachment directory layout.
            root = f"derived/f{index:06d}"
            expectedPath = f"{root}/{filename}"
            if attachment["path"] != expectedPath:
                raise ValueError(f"Derived-file path must be {expectedPath!r}.")

            expectedDirectories.add(root)
            expectedPayloads.add(expectedPath)

        if attachmentNames != sorted(set(attachmentNames)):
            raise ValueError("Derived-file names must be unique and sorted.")

        actualPayloads = {path for path in fileSet if path == "derived" or path.startswith("derived/")}
        actualDirectories = {path for path in directorySet if path == "derived" or path.startswith("derived/")}

        if actualPayloads != expectedPayloads:
            raise ValueError("Derived-file declarations do not exactly match attachment payloads.")
        if actualDirectories != expectedDirectories:
            raise ValueError("Derived-file declarations do not exactly match attachment directories.")

        ################################################################
        # Reuse the existing MRI/behavior inventory layout checks
        ################################################################
        # This is only a temporary structural validation view. The actual
        # checkpoint remains derived, and its inner MRI descriptor is checked
        # separately against pgl.mri.derived.v1.
        inventoryView = {
            "contract_version": "pgl.raw.session.v2",
            "runs": manifest["runs"],
            "mri": manifest["mri"],
            "directories": [
                path for path in directories if path not in expectedDirectories
            ],
            "files": [
                record for record in manifest["files"]
                if record["name"] not in expectedPayloads
            ],
        }
        cls.validateRawSessionV2Manifest(inventoryView)
        return manifest
    
    @classmethod
    def _acquireCheckpointPublicationLock(cls, connection, postgres, *, progress=None):
        """Acquire the session publication/lifecycle lock before any writes.

        SHARE ROW EXCLUSIVE:
            Allows ordinary SELECT reports.
            Conflicts with session lifecycle EXCLUSIVE locks.
            Serializes publication against other session writers and dataset
            dependency SHARE locks.

        Unlike SHARE, concurrent publication holders cannot both acquire this
        lock and then deadlock merely by inserting into session.

        Uses NOWAIT attempts in savepoints, bounded by lockTimeoutSeconds.
        Does not change SQL statement_timeout or lock_timeout settings.

        The caller must own an explicit READ COMMITTED transaction.
        The acquired lock remains held until the outer transaction ends.
        """
        from time import monotonic, sleep

        from psycopg.pq import TransactionStatus

        if connection.info.transaction_status != TransactionStatus.INTRANS:
            raise ValueError("Checkpoint publication requires an active caller-owned transaction.")

        isolation = connection.execute("SHOW transaction_isolation").fetchone()[0]
        if isolation != "read committed":
            raise ValueError("Checkpoint publication requires READ COMMITTED isolation.")

        table = sql.Identifier(postgres.databaseSchema, "session")
        statement = sql.SQL("LOCK TABLE {} IN SHARE ROW EXCLUSIVE MODE NOWAIT").format(table)
        timeout = postgres.lockTimeoutSeconds
        started = monotonic()

        while True:
            try:
                # A failed NOWAIT must roll back only this attempt, not leave
                # the caller's publication transaction in an aborted state.
                with connection.transaction():
                    connection.execute(statement)
                return

            except psycopg.errors.LockNotAvailable:
                elapsed = monotonic() - started
                if elapsed >= timeout:
                    raise TimeoutError(
                        f"Timed out after {timeout:g} seconds waiting for the "
                        "checkpoint publication/lifecycle lock."
                    ) from None

                if progress is not None:
                    progress(None, f"Waiting for checkpoint publication/lifecycle lock ({elapsed:.1f} s)")

                sleep(min(0.1, max(0.0, timeout - elapsed)))
                
    @classmethod
    def _matrixCatalogRecords(cls, records, *, owned=False):
        """Return the catalog-link projection of validated matrix records.

        owned=False:
            Legacy records containing name and matrixRevisionID.
            Names remain literal session attachment names.

        owned=True:
            Explicit owner/localName records from MRI-v2 manifests.
            Canonical catalog keys are preserved unchanged.

        The enclosing manifest contract must choose the mode explicitly.
        Never infer ownership from a name or from the presence of extra fields.

        Returns independent dictionaries. Does not read payloads, access SQL,
        mutate records, or discard ownership from the original manifest.
        """
        if type(owned) is not bool:
            raise TypeError("owned must be Boolean.")

        validated = (
            cls._validateOwnedMatrixRecords(records)
            if owned else
            cls._validateSessionProductRecords(records)
        )

        return [
            {
                "name": record["name"],
                "matrixRevisionID": record["matrixRevisionID"],
            }
            for record in validated
        ]


    @classmethod
    def _requireStableDatabaseIdentity(cls, connection, postgres):
        """Require current migration history, then read the persistent UUID.

        Uses the caller's transaction. No migrations, grants, or schema writes.
        SQL access failures retain their original exception categories.

        Public load/save coordinators call this before accessing checkpoint
        payloads or performing publication writes.
        """
        report = cls._inspectMigrationCompatibility(connection, postgres)

        if not report["compatible"]:
            details = "\n".join(issue["message"] for issue in report["issues"])
            raise RuntimeError(
                "Scientific database migration compatibility could not be established.\n"
                + details
            )

        return cls._readStableDatabaseID(connection, postgres)

    @staticmethod
    def _validateCheckpointBinding(binding):
        """Validate runtime binding metadata without reading settings or SQL.

        This record identifies the selected saved checkpoint, not the complete
        current scientific state. Unsaved working changes may exist.

        Runtime endpoint checks remain distinct from durable provenance.
        Returns an independent copy; never upgrades a legacy history record.
        """
        expectedFields = {"version", "checkpoint", "databaseIdentity"}

        if type(binding) is not dict or set(binding) != expectedFields:
            raise ValueError("Invalid saved-checkpoint binding fields.")
        if type(binding["version"]) is not int or binding["version"] != 1:
            raise ValueError("Unsupported saved-checkpoint binding version.")

        reference = binding["checkpoint"]
        if type(reference) is not dict or set(reference) != {"databaseID", "sessionID", "databaseName"}:
            raise ValueError("Invalid database-qualified checkpoint reference.")

        sessionID = reference["sessionID"]
        if type(sessionID) is not int or not 0 <= sessionID <= 9223372036854775807:
            raise ValueError("Bound sessionID must be a nonnegative PostgreSQL bigint.")

        databaseID = reference["databaseID"]
        if not isinstance(databaseID, str):
            raise ValueError("Bound databaseID must be a canonical UUID string.")

        try:
            parsedID = uuid.UUID(databaseID)
        except (ValueError, AttributeError):
            raise ValueError("Bound databaseID is invalid.") from None

        if str(parsedID) != databaseID or parsedID.int == 0:
            raise ValueError("Bound databaseID must be a canonical nonzero UUID.")

        databaseName = reference["databaseName"]
        if (
            not isinstance(databaseName, str) or not databaseName.strip()
            or any(character in databaseName for character in ("\x00", "\n", "\r"))
        ):
            raise ValueError("Bound databaseName must be a nonblank profile label without NUL or newlines.")

        identity = binding["databaseIdentity"]
        if type(identity) is not dict:
            raise ValueError("Bound runtime database identity must be a dictionary.")

        fields = {"transport", "host", "port", "database", "schema"}
        if identity.get("transport") == "ssh":
            fields.update({"sshHost", "sshPort", "sshUser"})
        elif identity.get("transport") != "direct":
            raise ValueError("Unsupported bound database transport.")

        if set(identity) != fields:
            raise ValueError("Invalid bound runtime database identity fields.")

        for name in ("host", "database", "schema"):
            if not isinstance(identity[name], str) or not identity[name].strip() or "\x00" in identity[name]:
                raise ValueError(f"Invalid bound database endpoint field: {name}.")

        for name in ("port", "sshPort"):
            if name in identity and (type(identity[name]) is not int or not 1 <= identity[name] <= 65535):
                raise ValueError(f"Invalid bound database endpoint port: {name}.")

        if identity["transport"] == "ssh":
            if not isinstance(identity["sshHost"], str) or not identity["sshHost"].strip() or "\x00" in identity["sshHost"]:
                raise ValueError("Invalid bound SSH host.")
            if not isinstance(identity["sshUser"], str) or "\x00" in identity["sshUser"]:
                raise ValueError("Invalid bound SSH user.")

        return deepcopy(binding)

    @classmethod
    def _prepareCheckpointBinding(cls, sessionID, postgres, *, databaseID, databaseName):
        """Prepare a binding without modifying a working session.

        databaseID must have been read from the caller's verified SQL snapshot.
        databaseName is the resolved PGL profile label, not the SQL database name.

        Saves prepare this before commit and install it after cleanup.
        No scientific history boundary is inferred, including for raw saves.
        """
        binding = {
            "version": 1,
            "checkpoint": {
                "databaseID": databaseID,
                "sessionID": sessionID,
                "databaseName": databaseName,
            },
            "databaseIdentity": cls._checkpointDatabaseIdentity(postgres),
        }
        return cls._validateCheckpointBinding(binding)

    @classmethod
    def _getBoundCheckpointReference(cls, session):
        """Return the selected saved-checkpoint reference, or None if unbound.

        Reads runtime bookkeeping only. Never consults the current default
        database, opens payloads, or changes history.

        A numeric sessionID without this binding does not establish a source
        database. Existing pre-update working sessions should be reloaded.

        A reference identifies the saved checkpoint beneath a working object;
        it is not a claim that every current scientific value was saved there.
        """
        binding = getattr(session, "_checkpointBinding", {})

        if type(binding) is not dict:
            raise ValueError("Invalid saved-checkpoint binding.")
        if not binding: return None

        validated = cls._validateCheckpointBinding(binding)
        sessionID = getattr(session, "sessionID", None)

        if type(sessionID) is not int or sessionID != validated["checkpoint"]["sessionID"]:
            raise ValueError(
                "Working sessionID differs from its saved-checkpoint binding. "
                "Reload the intended checkpoint rather than manually retargeting its ID."
            )

        return validated["checkpoint"]

    
    

# =========================================================================
# RUNTIME PAYLOAD ACCESS CONTEXT
# =========================================================================

class pglDatabaseAccess:
    """Retain caller-specific payload access independently of SQL connections.

    Created by database readers and publication coordinators.

    Owns:
        A snapshot of the caller's PostgreSQL access configuration.
        Runtime filesystem options indexed by backend ID.
        Cached filesystem/root pairs for registered backend locations.
        Inferred SSH connections created through the backend resolver.

    Does not:
        Connect to PostgreSQL.
        Change registered roots or relative object keys.
        Register database records.
        Belong in scientific serialization.

    Lifetime:
        Short-lived operations close the context after completing all I/O.
        Deferred checkpoint readers retain the context until no reader needs
        its filesystems. Closing SQL does not close this context.

        Do not close a context while lazy matrices, runs, or MNE readers still
        depend on it. Context-manager use is appropriate only when all payload
        access finishes within the with block.

    Explicit-URL filesystems may be shared by fsspec's instance cache.
    This context closes only inferred SSH connections that it owns.
    """

    # +++++++++++++++++++++++++++++ __init__ ++++++++++++++++++++++++++++++++
    def __init__(self, postgres, storageOptionsByBackend=None):
        """Snapshot configuration and runtime timeouts without connecting.

        Backend option dictionaries are shallow-copied.
        Connections, tunnels, and scientific readers are not copied.

        Runtime timeout overrides remain private to this access context and
        are not added to serialized database configuration.
        """
        from threading import RLock

        from .pglPostgres import pglPostgres

        if not isinstance(postgres, pglPostgres):
            raise TypeError("postgres must be a pglPostgres instance.")

        postgres._validateValues()

        if storageOptionsByBackend is None:
            storageOptionsByBackend = {}

        if not isinstance(storageOptionsByBackend, dict):
            raise TypeError("storageOptionsByBackend must be a dictionary or None.")

        options = {}

        for backendID, backendOptions in storageOptionsByBackend.items():
            if type(backendID) is not int or not 0 <= backendID <= 9223372036854775807:
                raise ValueError("Backend option keys must be nonnegative PostgreSQL bigints.")

            if not isinstance(backendOptions, dict):
                raise TypeError("Each backend's storage options must be a dictionary.")

            options[backendID] = dict(backendOptions)

        self._postgres = postgres.withTimeouts()
        self._optionsByBackend = options
        self._resolved = {}
        self._ownedFilesystems = []
        self._closed = False
        self._lock = RLock()

    # +++++++++++++++++++++++++++++ resolve +++++++++++++++++++++++++++++++++
    def resolve(self, backendID, registeredRoot):
        """Return cached filesystem access for a registered backend root.

        Called by payload readers and writers before appending object keys.

        Returns:
            (filesystem, filesystemRoot)

        First access delegates to pglDatabase._resolveBackendAccess().
        Repeated access to the same backend/root reuses that filesystem.

        The lock prevents concurrent first accesses from creating duplicate
        connections. It does not serialize subsequent scientific reads or
        authorize closing the context concurrently with active I/O.

        Failed resolutions are not cached and never fall back to local access.
        """
        from urllib.parse import urlsplit

        if type(backendID) is not int or not 0 <= backendID <= 9223372036854775807:
            raise ValueError("backendID must be a nonnegative PostgreSQL bigint.")

        if not isinstance(registeredRoot, str) or not registeredRoot.strip():
            raise ValueError("registeredRoot must be a nonempty string.")

        key = (backendID, registeredRoot)

        with self._lock:
            if self._closed:
                raise ValueError("Database payload access context is closed.")

            if key in self._resolved:
                return self._resolved[key]

            options = self._optionsByBackend.get(backendID, {})
            filesystem, filesystemRoot = pglDatabase._resolveBackendAccess(self._postgres, registeredRoot, storageOptions=options)

            # The resolver creates a privately owned strict SFTP filesystem
            # only for server-local roots accessed through the SQL SSH context.
            # Explicit remote URLs continue to use fsspec's ownership model.
            explicitURL = "://" in registeredRoot
            serverLocal = not explicitURL or urlsplit(registeredRoot).scheme.lower() in {"file", "local"}
            owned = serverLocal and self._postgres.connectionTransport == "ssh"

            if owned:
                self._ownedFilesystems.append(filesystem)

            self._resolved[key] = (filesystem, filesystemRoot)
            return self._resolved[key]

    # +++++++++++++++++++++++++++++++ close +++++++++++++++++++++++++++++++++
    def close(self):
        """Release owned inferred-SSH connections without deleting anything.

        Idempotent. No SQL or catalog writes are performed.
        Explicit-URL filesystems are not closed because fsspec may share them.

        Closing invalidates dependent deferred readers. Call only after they
        have finished. Cleanup failures warn without replacing an earlier
        publication or scientific error.
        """
        with self._lock:
            if self._closed:
                return

            self._closed = True
            ownedFilesystems = self._ownedFilesystems
            self._ownedFilesystems = []
            self._resolved = {}
            self._optionsByBackend = {}

        for filesystem in reversed(ownedFilesystems):
            try:
                filesystem.close()
            except Exception as error:
                pglMessages.warning(f"Could not close a database payload SSH connection ({type(error).__name__}).", level=1)

    # +++++++++++++++++++++++++++++ __enter__ +++++++++++++++++++++++++++++++
    def __enter__(self):
        """Support bounded operations whose payload I/O finishes in the block."""
        with self._lock:
            if self._closed:
                raise ValueError("Database payload access context is closed.")

        return self

    # +++++++++++++++++++++++++++++ __exit__ ++++++++++++++++++++++++++++++++
    def __exit__(self, exceptionType, exception, traceback):
        """Release owned connections without suppressing caller errors."""
        self.close()
        return False

# =========================================================================
# READ-ONLY LOGICAL FILESYSTEM FOR DATABASE CHECKPOINTS
# =========================================================================
# Constructed by checkpoint loaders and registration validators after
# manifest validation and location resolution. It does not query SQL.
# Payload bytes are verified when opened. Matrix Zarr bundles are opened
# separately through the registered matrix-product loading path.

class pglCheckpointFilesystem(AbstractFileSystem):
    """Expose verified logical checkpoint files independently of storage paths.

    Constructed by checkpoint loaders and registration validators.

    accessContext:
        Caller-specific pglDatabaseAccess retained for deferred payload reads.
        When supplied, all physical locations resolve through this context.
        Failed remote access never falls back to client-local access.

    ownsAccess:
        True when this filesystem is responsible for closing accessContext.
        False when a publication coordinator or another owner manages it.

    Without an access context, retain the previous explicit-filesystem behavior
    for compatibility with local reconstruction callers. Bare paths then mean
    caller-local paths. Database remote loaders must always supply a context.

    Construction validates metadata but does not read payload bytes.
    Opening a file verifies its complete contents before returning a stream.
    Matrix Zarr bundles are resolved separately by matrix-product loaders.

    Keep this filesystem and its access context open while deferred session
    readers depend on them. Closing a SQL connection does not close either.
    """

    protocol = "pglcheckpoint"
    cachable = False

    ################################################################
    # Validate inventory and retain deferred payload access
    ################################################################
    def __init__(self, manifest, fileLocations, storageOptionsByBackend=None, *, accessContext=None, ownsAccess=False):
        """Construct a read-only logical checkpoint filesystem.

        Supports raw behavior v1, raw session v1/v2, derived behavior/session
        v1/v2/v3, and derived MRI v1.

        Construction reads no payload bytes. Opening a file verifies its
        complete contents through the existing _open() implementation.

        With accessContext, configure backend options on that context.
        Without one, retain local/explicit-URL reconstruction compatibility.

        Ownership transfers on successful construction only.
        """
        super().__init__()

        if type(ownsAccess) is not bool:
            raise ValueError("ownsAccess must be Boolean.")
        if accessContext is not None and not isinstance(accessContext, pglDatabaseAccess):
            raise TypeError("accessContext must be a pglDatabaseAccess instance.")
        if ownsAccess and accessContext is None:
            raise ValueError("ownsAccess requires an access context.")
        if accessContext is not None and storageOptionsByBackend:
            raise ValueError("Configure storage options on accessContext, not on both objects.")
        if not isinstance(manifest, dict):
            raise ValueError("Manifest must contain a dictionary.")

        contractVersion = manifest.get("contract_version")

        if contractVersion == "pgl.raw.behavior.v1":
            pglDatabase.validateRawManifest(manifest)
        elif contractVersion in ("pgl.raw.session.v1", "pgl.raw.session.v2"):
            pglDatabase.validateRawSessionManifest(manifest)
        elif contractVersion in (
            "pgl.derived.behavior.v1",
            "pgl.derived.behavior.v2",
            "pgl.derived.behavior.v3",
            "pgl.derived.session.v1",
            "pgl.derived.session.v2",
            "pgl.derived.session.v3",
            "pgl.derived.mri.v1",
            "pgl.derived.mri.v2",
        ):
            pglDatabase.validateDerivedManifest(manifest)
        else:
            raise ValueError(f"Unsupported checkpoint contract: {contractVersion!r}")

        expectedFiles = {record["name"]: record for record in manifest["files"]}
        if set(fileLocations) != set(expectedFiles):
            raise ValueError("File locations must cover exactly the manifest files.")

        self._payloads = deepcopy(fileLocations)
        self._storageOptionsByBackend = dict(storageOptionsByBackend or {})
        self._accessContext = accessContext
        self._ownsAccess = ownsAccess
        self._pglClosed = False

        for name, record in self._payloads.items():
            expected = expectedFiles[name]

            if record["sha256"] != expected["sha256"] or record["size_bytes"] != expected["size_bytes"]:
                raise ValueError(f"File identity does not match manifest: {name!r}")
            if not isinstance(record["locations"], list) or not record["locations"]:
                raise ValueError(f"File has no location candidates: {name!r}")

            for location in record["locations"]:
                key = location["object_key"]
                if (
                    not isinstance(key, str) or key.startswith("/")
                    or "\\" in key or "\x00" in key
                    or any(part in {"", ".", ".."} for part in key.split("/"))
                ):
                    raise ValueError(f"Invalid payload object key: {key!r}")

                root = location["url_prefix"]
                if not isinstance(root, str) or not root.strip():
                    raise ValueError(f"Invalid storage root for {name!r}")

        self._entries = {"": {"name": "", "type": "directory", "size": 0}}

        def validateName(name):
            if not isinstance(name, str) or not name:
                raise ValueError("Checkpoint paths must be nonempty strings.")
            if name.startswith("/") or "\\" in name or "\x00" in name:
                raise ValueError(f"Invalid checkpoint path: {name!r}")
            if any(part in {"", ".", ".."} for part in name.split("/")):
                raise ValueError(f"Invalid checkpoint path: {name!r}")

        def addEntry(name, kind, size):
            validateName(name)
            if name in self._entries:
                raise ValueError(f"Duplicate checkpoint path: {name!r}")
            self._entries[name] = {"name": name, "type": kind, "size": size}

        for name in manifest["directories"]:
            addEntry(name, "directory", 0)

        for record in manifest["files"]:
            size = record["size_bytes"]
            if type(size) is not int or size < 0:
                raise ValueError(f"Invalid file size for {record['name']!r}")
            addEntry(record["name"], "file", size)

        for name in self._entries:
            if not name: continue
            parentEntry = self._entries.get(posixpath.dirname(name))
            if parentEntry is None or parentEntry["type"] != "directory":
                raise ValueError(f"Missing parent directory for checkpoint path: {name!r}")

    # +++++++++++++++++++++++++++ _logicalPath ++++++++++++++++++++++++++++++
    def _logicalPath(self, path):
        """Normalize a caller's logical lookup path, not a physical file path."""
        return self._strip_protocol(str(path)).strip("/")

    # +++++++++++++++++++++++++++++++ info ++++++++++++++++++++++++++++++++++
    def info(self, path, **kwargs):
        """Return inventory metadata without checking physical availability."""
        name = self._logicalPath(path)

        if name not in self._entries:
            raise FileNotFoundError(name)

        return dict(self._entries[name])

    # ++++++++++++++++++++++++++++++++ ls +++++++++++++++++++++++++++++++++++
    def ls(self, path, detail=True, **kwargs):
        """List logical children from the validated inventory without I/O."""
        entry = self.info(path)
        name = entry["name"]

        if entry["type"] == "file":
            entries = [entry]
        else:
            entries = [
                dict(child)
                for childName, child in self._entries.items()
                if childName and posixpath.dirname(childName) == name
            ]
            entries.sort(key=lambda child: child["name"])

        return entries if detail else [child["name"] for child in entries]

    def getPublicationReference(self, path):
        """Return checkpoint content metadata without opening its payload.

        Used by database publication after the owning exporter has established
        that these saved bytes still represent the desired contents.

        This method does NOT establish that a materialized working object is
        unchanged. Retained lazy backing alone is not sufficient evidence.

        Requires a database-owned access context. Standalone reconstruction
        without that context cannot establish the source database identity.

        Returns independent metadata only. Does not resolve storage, connect
        to SQL, read bytes, or transfer ownership of the access context.
        """
        if self._pglClosed:
            raise ValueError("Checkpoint filesystem is closed.")

        if self._accessContext is None:
            raise ValueError("Checkpoint payload reuse requires a database access context.")

        if self._accessContext._closed:
            raise ValueError("Checkpoint payload access context is closed.")

        entry = self.info(path)
        if entry["type"] != "file":
            raise IsADirectoryError(entry["name"])

        payload = self._payloads[entry["name"]]

        return {
            "databaseIdentity": deepcopy(pglDatabase._checkpointDatabaseIdentity(self._accessContext._postgres)),
            "sourceName": entry["name"],
            "sha256": payload["sha256"],
            "size_bytes": payload["size_bytes"],
        }
    
    # +++++++++++++++++++++++++ _resolveLocation ++++++++++++++++++++++++++++
    def _resolveLocation(self, location):
        """Resolve a physical replica using this reader's retained context.

        Used by verified opens and direct-local MNE eligibility checks.
        With a context, never independently reinterpret the registered root.
        """
        if self._pglClosed:
            raise ValueError("Checkpoint filesystem is closed.")

        backendID = location["backend_id"]
        registeredRoot = location["url_prefix"]

        if self._accessContext is not None:
            return self._accessContext.resolve(backendID, registeredRoot)

        # Compatibility path for existing local/explicit-URL reconstruction.
        # Remote database loaders must supply their access context.
        options = self._storageOptionsByBackend.get(backendID, {})
        return url_to_fs(registeredRoot, **options)

    # +++++++++++++++++++++++++++++++ _open +++++++++++++++++++++++++++++++++
    def _open(self, path, mode="rb", **kwargs):
        """Return fully verified bytes, trying eligible replicas in order.

        Reads each attempted replica into bounded-memory temporary storage.
        Large files spill to a caller-local temporary file.

        Returns an independent seekable binary stream. That stream no longer
        needs the SSH connection after verification has completed.

        Read and integrity failures may advance to another replica.
        Authentication/security exceptions outside those categories propagate.
        """
        if self._pglClosed:
            raise ValueError("Checkpoint filesystem is closed.")

        if mode != "rb":
            raise PermissionError("Checkpoint filesystems are read-only.")

        entry = self.info(path)

        if entry["type"] != "file":
            raise IsADirectoryError(entry["name"])

        record = self._payloads[entry["name"]]
        failures = []

        for location in record["locations"]:
            backendID = location["backend_id"]
            buffer = tempfile.SpooledTemporaryFile(max_size=8 * 1024 * 1024, mode="w+b")

            try:
                filesystem, root = self._resolveLocation(location)
                payloadPath = posixpath.join(root, location["object_key"])
                digest = hashlib.sha256()
                sizeBytes = 0

                with filesystem.open(payloadPath, "rb") as source:
                    while True:
                        chunk = source.read(1024 * 1024)

                        if not chunk:
                            break

                        sizeBytes += len(chunk)

                        if sizeBytes > record["size_bytes"]:
                            raise ValueError("Payload exceeds expected size.")

                        digest.update(chunk)

                        if buffer.write(chunk) != len(chunk):
                            raise OSError("Incomplete checkpoint verification-buffer write.")

                if sizeBytes != record["size_bytes"] or digest.hexdigest() != record["sha256"]:
                    raise ValueError("Payload integrity check failed.")

                buffer.seek(0)

            except (OSError, ValueError) as error:
                buffer.close()
                failures.append(f"backend {backendID}: {type(error).__name__}")
                continue

            except BaseException:
                buffer.close()
                raise

            return buffer

        raise OSError(f"No verified copy available for {entry['name']!r}: {'; '.join(failures)}")

    # +++++++++++++++++++++++++ localBundlePaths ++++++++++++++++++++++++++++
    def localBundlePaths(self, resourceRoot, records):
        """Return a layout-compatible client-local bundle, or None.

        Called by MNE resolution only when direct-local access is requested.

        Checks inner/outer identities and resolves actual caller-side access.
        An SSH-backed server-local root is not eligible for direct-local use,
        even during a loopback test where the same path exists on the client.

        Does not hash or open scientific payloads. Resolving an access context
        can establish a filesystem connection; local candidates are stat'ed.
        The caller must verify every returned file before opening MNE.
        """
        from fsspec.implementations.local import LocalFileSystem

        if self._pglClosed:
            raise ValueError("Checkpoint filesystem is closed.")

        candidatesByName = {}

        for member in records:
            relativeName = member["name"]
            logicalName = self._logicalPath(posixpath.join(resourceRoot, relativeName))
            registered = self._payloads.get(logicalName)

            if registered is None:
                raise ValueError(f"FIF member is absent from checkpoint: {logicalName}")

            expected = {key: member[key] for key in ("sha256", "size_bytes")}
            actual = {key: registered[key] for key in ("sha256", "size_bytes")}

            if actual != expected:
                raise ValueError(f"FIF/checkpoint identity mismatch: {logicalName}")

            candidates = {}
            parts = relativeName.split("/")

            for location in registered["locations"]:
                filesystem, root = self._resolveLocation(location)

                # Determine locality from the resolved filesystem, never the
                # stored path, backend label, or SQL transport alone.
                if type(filesystem) is not LocalFileSystem:
                    continue

                source = Path(filesystem._strip_protocol(posixpath.join(root, location["object_key"]))).expanduser()

                if source.is_symlink():
                    continue

                source = source.resolve()
                bundleRoot = source

                for part in parts:
                    bundleRoot = bundleRoot.parent

                if bundleRoot.joinpath(*parts) != source:
                    continue

                candidates[bundleRoot] = source

            candidatesByName[relativeName] = candidates

        if not candidatesByName:
            return None

        commonRoots = set.intersection(*(set(candidates) for candidates in candidatesByName.values()))

        for root in sorted(commonRoots, key=str):
            paths = {name: candidates[root] for name, candidates in candidatesByName.items()}

            if all(path.is_file() for path in paths.values()):
                return paths

        return None

    # +++++++++++++++++++++++ validateBundleIdentities +++++++++++++++++++++++
    def validateBundleIdentities(self, resourceRoot, records):
        """Check MNE bundle identities against checkpoint metadata without I/O."""
        for member in records:
            logicalName = self._logicalPath(posixpath.join(resourceRoot, member["name"]))
            registered = self._payloads.get(logicalName)

            if registered is None:
                raise ValueError(f"FIF member is absent from checkpoint: {logicalName}")

            expected = {key: member[key] for key in ("sha256", "size_bytes")}
            actual = {key: registered[key] for key in ("sha256", "size_bytes")}

            if actual != expected:
                raise ValueError(f"FIF/checkpoint identity mismatch: {logicalName}")

    # +++++++++++++++++++++++++++++++ close +++++++++++++++++++++++++++++++++
    def close(self):
        """Disable future payload reads and close an owned access context.

        Call only after all deferred session readers are finished.
        Does not delete files or affect the database.

        A shared context remains the responsibility of its external owner.
        Already returned verified temporary streams remain caller-owned.
        """
        if self._pglClosed:
            return

        self._pglClosed = True

        if self._ownsAccess and self._accessContext is not None:
            self._accessContext.close()


    
